if (!defined('PM_MANAGE_SHUTDOWN')) {
	define('PM_MANAGE_SHUTDOWN', true);
	$GLOBALS['pm_manage_error_shown'] = false;
	register_shutdown_function(static function () {
		if (!empty($GLOBALS['pm_manage_error_shown'])) {
			return;
		}
		$e = error_get_last();
		if (!$e) {
			return;
		}
		$fatal = [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR, E_USER_ERROR];
		if (!in_array((int) ($e['type'] ?? 0), $fatal, true)) {
			return;
		}
		$msg = (string) ($e['message'] ?? '') . ' @ ' . basename((string) ($e['file'] ?? '')) . ':' . (int) ($e['line'] ?? 0);
		echo '<div class="alert alert-danger" style="margin:1rem">เกิดข้อผิดพลาด: ' . htmlspecialchars($msg, ENT_QUOTES, 'UTF-8') . '</div>';
	});
}

