if (!function_exists('pm_get_project_status_now')) {
	function pm_get_project_status_now($db_Project, $project_id)
	{
		$project_id = (int)$project_id;
		if ($project_id <= 0) return '';
		$q = @mysqli_query($db_Project, "SELECT status_project FROM pre_project WHERE id='".$project_id."' LIMIT 1");
		$r = $q ? mysqli_fetch_assoc($q) : null;
		return (string)($r['status_project'] ?? '');
	}
}

if (!function_exists('pm_is_plan_fix_awaiting_review')) {
	function pm_is_plan_fix_awaiting_review($status_project, $notify_result = '', $user_fix_note = '')
	{
		return ((string)$status_project === '8')
			&& (trim((string)$notify_result) === 'บรรจุแผนและแก้ไข')
			&& (trim((string)$user_fix_note) !== '');
	}
}

if (!function_exists('pm_is_editable_in_plan_mode')) {
	function pm_is_editable_in_plan_mode($status_project, $notify_result = '', $user_fix_note = '')
	{
		// ขั้นขอบรรจุที่หน่วยแผนแจ้งผล "บรรจุแผนและแก้ไข" (status=8)
		// ยังไม่ใช่แผนปฏิบัติการประจำปี — ผู้รับผิดชอบแก้ได้ทุกข้อมูล จนกว่าจะยืนยันส่งกลับแผน
		$st = (string)$status_project;
		$nr = trim((string)$notify_result);
		if ($st !== '8' || $nr !== 'บรรจุแผนและแก้ไข') {
			return false;
		}
		return trim((string)$user_fix_note) === '';
	}
}

/** แผนปฏิบัติการประจำปี หลังบรรจุแผน และยังไม่ขอดำเนินโครงการ */
if (!function_exists('pm_is_annual_plan_pre_operate')) {
	function pm_is_annual_plan_pre_operate($status_project, $notify_result = '')
	{
		$st = (string)$status_project;
		$nr = trim((string)$notify_result);
		return ($st === '4' && $nr === 'บรรจุแผน');
	}
}

/** หลังแผนกดนำเข้าที่ประชุมแล้ว แต่ยังไม่แจ้งผลบรรจุแผน — ดูอย่างเดียว ห้ามแก้ไข */
if (!function_exists('pm_is_include_meeting_view_only')) {
	function pm_is_include_meeting_view_only($status_project, $notify_result = '')
	{
		$st = (string)$status_project;
		$nr = trim((string)$notify_result);
		if ($st !== '4') {
			return false;
		}
		return ($nr !== 'บรรจุแผน' && $nr !== 'บรรจุแผนและแก้ไข');
	}
}

if (!function_exists('pm_can_edit_full_or_plan')) {
	function pm_can_edit_full_or_plan($status_project, $notify_result = '', $user_fix_note = '')
	{
		if (function_exists('pm_is_include_meeting_view_only') && pm_is_include_meeting_view_only($status_project, $notify_result)) {
			return false;
		}
		if (function_exists('pm_is_plan_fix_awaiting_review') && pm_is_plan_fix_awaiting_review($status_project, $notify_result, $user_fix_note)) {
			return false;
		}
		if (defined('PLAN_ADMIN') && PLAN_ADMIN) {
			return true;
		}
		$st = (string)$status_project;
		if ($st === '0') {
			return true;
		}
		if ($st === '8' && trim((string)$notify_result) !== 'บรรจุแผนและแก้ไข') {
			return true;
		}
		if (pm_is_annual_plan_pre_operate($st, $notify_result)) {
			return true;
		}
		return pm_is_editable_in_plan_mode($st, $notify_result, $user_fix_note);
	}
}

/**
 * จำกัดฟิลด์เมื่อเป็นแผนปฏิบัติการประจำปี (บรรจุแผนแล้ว ยังไม่ขอดำเนินการ)
 * ขั้นขอบรรจุที่ถูกตีกลับ / แผนแจ้งผลให้แก้ไข — ไม่จำกัดฟิลด์
 */
if (!function_exists('pm_plan_restricts_like_user')) {
	function pm_plan_restricts_like_user($status_project, $notify_result = '')
	{
		if (defined('PLAN_ADMIN') && PLAN_ADMIN) {
			return false;
		}
		$st = (string)$status_project;
		$nr = trim((string)$notify_result);
		if ($st === '8') {
			// ตีกลับหลังขอดำเนินการของแผนประจำปี — แก้ได้บางข้อเหมือนก่อนขอดำเนินการ
			return ($nr === 'บรรจุแผน');
		}
		return pm_is_annual_plan_pre_operate($st, $nr);
	}
}

/** สิทธิ์บันทึกเนื้อหาที่อนุญาตในสถานะร่าง/ตีกลับ/แผนประจำปีก่อนขอดำเนินการ */
if (!function_exists('pm_staff_can_save_allowed_project_content')) {
	function pm_staff_can_save_allowed_project_content($db_Project, $project_id, $staff_id, $staff_code = '', $staff_unit_code = ''): bool
	{
		$project_id = (int)$project_id;
		$staff_id = (int)$staff_id;
		if ($project_id <= 0 || $staff_id <= 0) {
			return false;
		}
		if (!function_exists('staffCanViewPreProjectManageDetail')
			|| !staffCanViewPreProjectManageDetail($db_Project, $project_id, $staff_id, $staff_code, $staff_unit_code)) {
			return false;
		}
		$status_now = pm_get_project_status_now($db_Project, $project_id);
		$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
		if ((string)$status_now === '8' && trim((string)$notify_result_now) === 'บรรจุแผน') {
			$qReply = @mysqli_query($db_Project, "SELECT operate_submitter_reply_note FROM pre_project WHERE id='" . (int)$project_id . "' LIMIT 1");
			$rReply = $qReply ? mysqli_fetch_assoc($qReply) : null;
			if (trim((string)($rReply['operate_submitter_reply_note'] ?? '')) !== '') {
				return false;
			}
		}
		$fixNote = '';
		if (function_exists('pm_get_project_user_fix_note')) {
			$fixNote = pm_get_project_user_fix_note($db_Project, $project_id);
		}
		return pm_can_edit_full_or_plan($status_now, $notify_result_now, $fixNote);
	}
}

