/** โหลดผลตัวชี้วัดที่บันทึกแล้ว แยกตาม project_kpi_id + เดือน */
if (!function_exists('pm_load_project_kpi_results_map')) {
	function pm_load_project_kpi_results_map($db_Project, $project_id): array
	{
		$map = [];
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return $map;
		}
		if (function_exists('ensureKpiResultSchema')) {
			ensureKpiResultSchema($db_Project);
		}
		$q = @mysqli_query(
			$db_Project,
			"SELECT project_kpi_id, result_month, SUM(result_amount) AS amt
			 FROM project_kpi_result
			 WHERE project_id='" . $pid . "' AND status='1'
			 GROUP BY project_kpi_id, result_month"
		);
		if ($q) {
			while ($r = mysqli_fetch_assoc($q)) {
				$kpiId = (int)($r['project_kpi_id'] ?? 0);
				$mon = trim((string)($r['result_month'] ?? ''));
				if ($kpiId <= 0 || $mon === '') {
					continue;
				}
				if (!isset($map[$kpiId])) {
					$map[$kpiId] = [];
				}
				$map[$kpiId][$mon] = (float)($r['amt'] ?? 0);
			}
		}
		return $map;
	}
}

/** แสดงเดือนที่เกิดผลพร้อมปีสั้น (เช่น ต.ค. 68)
 * ปีงบประมาณ พ.ศ. Y = ต.ค. (Y-1) ถึง ก.ย. Y
 */
if (!function_exists('pm_kpi_result_month_display')) {
	function pm_kpi_result_month_display(string $monthVal, string $yearsSelect): string
	{
		$short = '';
		foreach (pm_kpi_month_plan_fields() as $m) {
			if ((string)($m['val'] ?? '') === $monthVal) {
				$short = (string)($m['short'] ?? '');
				break;
			}
		}
		if ($short === '') {
			return $monthVal;
		}
		$ys = preg_replace('/\D/', '', $yearsSelect);
		$yNum = (int)$ys;
		if ($yNum <= 0) {
			$yNum = (int)date('Y') + 543;
		}
		$mInt = (int)$monthVal;
		// ต.ค.–ธ.ค. อยู่ในปีปฏิทินก่อนปีงบประมาณ, ม.ค.–ก.ย. อยู่ในปีงบประมาณ
		$yShort = ($mInt >= 10 && $mInt <= 12)
			? substr((string)($yNum - 1), -2)
			: substr((string)$yNum, -2);
		return trim($short . ' ' . $yShort);
	}
}

/** แปลงรายละเอียดผลเป็น HTML (รองรับ url) */
if (!function_exists('pm_kpi_result_detail_html')) {
	function pm_kpi_result_detail_html(string $detail): string
	{
		$detail = trim($detail);
		if ($detail === '') {
			return '<span class="text-muted">-</span>';
		}
		$escaped = htmlspecialchars($detail, ENT_QUOTES, 'UTF-8');
		$escaped = preg_replace_callback(
			'/(https?:\/\/[^\s<]+|www\.[^\s<]+)/i',
			function ($m) {
				$url = (string)($m[0] ?? '');
				$href = (stripos($url, 'http') === 0) ? $url : ('http://' . $url);
				return '<a href="' . htmlspecialchars($href, ENT_QUOTES, 'UTF-8') . '" target="_blank" rel="noopener">' . htmlspecialchars($url, ENT_QUOTES, 'UTF-8') . '</a>';
			},
			$escaped
		);
		return nl2br($escaped, false);
	}
}

/** โหลดรายการผลที่บันทึกแล้ว (รายเดือน) พร้อมไฟล์แนบ */
if (!function_exists('pm_load_kpi_result_entry_list')) {
	function pm_load_kpi_result_entry_list($db_Project, $project_id, $project_kpi_id, string $yearsSelect = '', string $fileWebBase = '../document/kpi_result_files/'): array
	{
		$items = [];
		$pid = (int)$project_id;
		$kpiId = (int)$project_kpi_id;
		if ($pid <= 0 || $kpiId <= 0 || !$db_Project) {
			return $items;
		}
		if (function_exists('ensureKpiResultSchema')) {
			ensureKpiResultSchema($db_Project);
		}
		$order = "'10','11','12','01','02','03','04','05','06','07','08','09'";
		$q = @mysqli_query(
			$db_Project,
			"SELECT id, result_month, result_amount, result_detail, created_at
			 FROM project_kpi_result
			 WHERE project_id='" . $pid . "' AND project_kpi_id='" . $kpiId . "' AND status='1'
			 ORDER BY FIELD(result_month, " . $order . "), id ASC"
		);
		if (!$q) {
			return $items;
		}
		while ($r = mysqli_fetch_assoc($q)) {
			$rid = (int)($r['id'] ?? 0);
			if ($rid <= 0) {
				continue;
			}
			$month = trim((string)($r['result_month'] ?? ''));
			$files = [];
			$fq = @mysqli_query(
				$db_Project,
				"SELECT id, original_name, stored_file
				 FROM project_kpi_result_file
				 WHERE result_id='" . $rid . "' AND status='1'
				 ORDER BY id ASC"
			);
			if ($fq) {
				while ($fr = mysqli_fetch_assoc($fq)) {
					$orig = trim((string)($fr['original_name'] ?? ''));
					$stored = trim((string)($fr['stored_file'] ?? ''));
					$ext = strtolower(pathinfo($orig, PATHINFO_EXTENSION));
					$files[] = [
						'id' => (int)($fr['id'] ?? 0),
						'name' => $orig,
						'url' => ($stored !== '') ? ($fileWebBase . rawurlencode($stored)) : '',
						'ext' => $ext,
						'is_pdf' => ($ext === 'pdf'),
					];
				}
			}
			$items[] = [
				'id' => $rid,
				'month' => $month,
				'month_label' => pm_kpi_result_month_display($month, $yearsSelect),
				'amount' => (float)($r['result_amount'] ?? 0),
				'detail' => (string)($r['result_detail'] ?? ''),
				'created_at' => (string)($r['created_at'] ?? ''),
				'files' => $files,
			];
		}
		return $items;
	}
}

/** ตรวจว่ามีผลเดือนนี้แล้วหรือไม่ */
if (!function_exists('pm_kpi_result_month_exists')) {
	function pm_kpi_result_month_exists($db_Project, $project_id, $project_kpi_id, string $month, int $exclude_id = 0): bool
	{
		$pid = (int)$project_id;
		$kpiId = (int)$project_kpi_id;
		$exclude_id = (int)$exclude_id;
		if ($pid <= 0 || $kpiId <= 0 || $month === '' || !$db_Project) {
			return false;
		}
		$esc = mysqli_real_escape_string($db_Project, $month);
		$sql = "SELECT id FROM project_kpi_result
			WHERE project_id='" . $pid . "' AND project_kpi_id='" . $kpiId . "'
			AND result_month='" . $esc . "' AND status='1'";
		if ($exclude_id > 0) {
			$sql .= " AND id<>'" . $exclude_id . "'";
		}
		$sql .= " LIMIT 1";
		$q = @mysqli_query($db_Project, $sql);
		return ($q && mysqli_num_rows($q) > 0);
	}
}

/** คำนวณร้อยละความสำเร็จจากเป้าหมายและผล (ไม่จำกัดที่ 100%) */
if (!function_exists('pm_kpi_compute_success_percent')) {
	function pm_kpi_compute_success_percent(float $plan, float $result): int
	{
		if ($plan <= 0) {
			return $result > 0 ? 101 : 0;
		}
		return (int)max(0, round(($result / $plan) * 100, 0));
	}
}

/** โทนสีร้อยละความสำเร็จ: เขียว=≥100, เหลือง=<100 */
if (!function_exists('pm_kpi_success_percent_tone')) {
	function pm_kpi_success_percent_tone(int $pct): string
	{
		if ($pct > 100) {
			return 'is-over';
		}
		if ($pct < 100) {
			return 'is-under';
		}
		return 'is-exact';
	}
}

/** แสดงเป้าหมาย / ผล / ร้อยละความสำเร็จ (รูปแบบเดียวกับภาพอ้างอิง) */
if (!function_exists('pm_render_kpi_goal_trio')) {
	function pm_render_kpi_goal_trio(float $plan, float $result, callable $fmtInt, string $monthShort = ''): void
	{
		$planShow = $plan > 0 ? $fmtInt($plan) : '-';
		$resultShow = $result > 0 ? $fmtInt($result) : '-';
		$pct = pm_kpi_compute_success_percent($plan, $result);
		$pctTone = pm_kpi_success_percent_tone($pct);
		?>
		<div class="pm-kpi-goal-trio<?= $monthShort !== '' ? ' pm-kpi-goal-trio-month' : '' ?>">
			<?php if ($monthShort !== ''): ?>
				<div class="pm-kpi-goal-trio-month-label"><?= htmlspecialchars($monthShort, ENT_QUOTES, 'UTF-8') ?></div>
			<?php endif; ?>
			<div class="pm-kpi-goal-trio-body">
				<div class="pm-kpi-goal-trio-group">
					<span class="pm-kpi-goal-trio-label">ค่าเป้าหมาย</span>
					<span class="pm-kpi-goal-trio-box"><?= htmlspecialchars((string)$planShow, ENT_QUOTES, 'UTF-8') ?></span>
				</div>
				<div class="pm-kpi-goal-trio-group">
					<span class="pm-kpi-goal-trio-label">ผล</span>
					<span class="pm-kpi-goal-trio-box pm-kpi-goal-trio-box-result"><?= htmlspecialchars((string)$resultShow, ENT_QUOTES, 'UTF-8') ?></span>
				</div>
				<div class="pm-kpi-goal-trio-group pm-kpi-goal-trio-group-pct">
					<span class="pm-kpi-goal-trio-label">ร้อยละความสำเร็จของตัวชี้วัด</span>
					<span class="pm-kpi-goal-trio-bar <?= htmlspecialchars($pctTone, ENT_QUOTES, 'UTF-8') ?>"><span><?= (int)$pct ?>%</span></span>
				</div>
			</div>
		</div>
		<?php
	}
}

/** รวมเป้าหมายรายเดือนทั้งหมดของตัวชี้วัด */
if (!function_exists('pm_kpi_sum_plan_total')) {
	function pm_kpi_sum_plan_total(array $pk): float
	{
		$sum = 0.0;
		foreach (pm_kpi_month_plan_fields() as $def) {
			$sum += (float)($pk[(string)($def['field'] ?? '')] ?? 0);
		}
		return $sum;
	}
}

/** รวมผลรายเดือนทั้งหมดของตัวชี้วัด */
if (!function_exists('pm_kpi_sum_result_total')) {
	function pm_kpi_sum_result_total(array $cells): float
	{
		$sum = 0.0;
		foreach (pm_kpi_month_plan_fields() as $def) {
			$sum += (float)($cells[(string)($def['val'] ?? '')] ?? 0);
		}
		return $sum;
	}
}

/** ร้อยละความสำเร็จรวมทุกตัวชี้วัด (ถ่วงน้ำหนักตาม kpi_weight) */
if (!function_exists('pm_compute_kpi_list_overall_success_percent')) {
	function pm_compute_kpi_list_overall_success_percent(array $kpiList, array $resultsMap): ?int
	{
		if (empty($kpiList)) {
			return null;
		}
		$weightSum = 0.0;
		$weightedPct = 0.0;
		$hasAnyResult = false;
		foreach ($kpiList as $pk) {
			$w = (float)($pk['kpi_weight'] ?? 0);
			if ($w <= 0) {
				continue;
			}
			$kpiId = (int)($pk['id'] ?? 0);
			$plan = pm_kpi_sum_plan_total($pk);
			$cells = $kpiId > 0 ? ($resultsMap[$kpiId] ?? []) : [];
			$result = pm_kpi_sum_result_total($cells);
			if ($result > 0) {
				$hasAnyResult = true;
			}
			$pct = pm_kpi_compute_success_percent($plan, $result);
			$weightedPct += $w * $pct;
			$weightSum += $w;
		}
		if ($weightSum <= 0 || !$hasAnyResult) {
			return null;
		}
		return (int)max(0, round($weightedPct / $weightSum, 0));
	}
}

if (!function_exists('pm_resolve_kpi_display_name')) {
	function pm_resolve_kpi_display_name($db_KPI, array $pk): string
	{
		$name = trim((string)($pk['kpi_name'] ?? ''));
		if ($name === '' && !empty($pk['code_kpi']) && $db_KPI && function_exists('getKPI')) {
			$kpiRow = getKPI($db_KPI, $pk['code_kpi']);
			$name = trim((string)($kpiRow['name'] ?? ''));
		}
		return $name !== '' ? $name : '-';
	}
}

if (!function_exists('pm_build_kpi_evaluation_summary')) {
	function pm_build_kpi_evaluation_summary($db_Project, $db_KPI, $project_id): array
	{
		$pid = (int)$project_id;
		$kpiList = ($pid > 0 && function_exists('getProjectKPIList')) ? getProjectKPIList($db_Project, $pid) : [];
		$resultsMap = ($pid > 0 && function_exists('pm_load_project_kpi_results_map'))
			? pm_load_project_kpi_results_map($db_Project, $pid)
			: [];
		$overallPct = pm_compute_kpi_list_overall_success_percent($kpiList, $resultsMap);
		$lines = [];
		$no = 0;
		foreach ($kpiList as $pk) {
			$kpiId = (int)($pk['id'] ?? 0);
			$plan = pm_kpi_sum_plan_total($pk);
			$result = pm_kpi_sum_result_total($resultsMap[$kpiId] ?? []);
			if ($plan <= 0 && $result <= 0) {
				continue;
			}
			$no++;
			$planShow = (int)round($plan, 0);
			$resultShow = (int)round($result, 0);
			$name = pm_resolve_kpi_display_name($db_KPI, $pk);
			$lines[] = [
				'no' => $no,
				'name' => $name,
				'plan' => $planShow,
				'result' => $resultShow,
				'text' => $name . ' เป้า : ' . $planShow . ' ผล : ' . $resultShow,
			];
		}
		return [
			'overall_percent' => $overallPct,
			'lines' => $lines,
		];
	}
}

if (!function_exists('pm_load_project_evaluation_result')) {
	function pm_load_project_evaluation_result($db_Project, $project_id): ?array
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return null;
		}
		if (function_exists('ensureProjectEvaluationResultSchema')) {
			ensureProjectEvaluationResultSchema($db_Project);
		}
		$q = @mysqli_query($db_Project, "SELECT * FROM project_evaluation_result WHERE project_id='" . $pid . "' AND status='1' ORDER BY id DESC LIMIT 1");
		$row = ($q && mysqli_num_rows($q) > 0) ? mysqli_fetch_assoc($q) : null;
		return is_array($row) ? $row : null;
	}
}

/** โหลดสถานะการส่งรายงานผลโครงการ */
if (!function_exists('pm_get_project_result_report_state')) {
	function pm_get_project_result_report_state($db_Project, $project_id): array
	{
		$pid = (int)$project_id;
		$empty = [
			'is_submitted' => false,
			'is_locked' => false,
			'is_rejected' => false,
			'is_completed' => false,
			'is_plan_closed' => false,
			'can_submit' => true,
			'submitted_at' => '',
			'completed_at' => '',
			'plan_closed_at' => '',
			'certifiers_json' => '',
		];
		if ($pid <= 0 || !$db_Project) {
			return $empty;
		}
		if (function_exists('ensureProjectResultReportSchema')) {
			ensureProjectResultReportSchema($db_Project);
		}
		$q = @mysqli_query($db_Project, "SELECT result_report_certifiers_json, result_report_submitted_at, result_report_completed_at, result_report_plan_closed_at, result_report_submitter_reply_note FROM pre_project WHERE id='" . $pid . "' AND status='1' LIMIT 1");
		$row = ($q && mysqli_num_rows($q) > 0) ? mysqli_fetch_assoc($q) : null;
		if (!is_array($row)) {
			return $empty;
		}
		$submittedAt = trim((string)($row['result_report_submitted_at'] ?? ''));
		$completedAt = trim((string)($row['result_report_completed_at'] ?? ''));
		$planClosedAt = trim((string)($row['result_report_plan_closed_at'] ?? ''));
		$certRaw = trim((string)($row['result_report_certifiers_json'] ?? ''));
		$isSubmitted = ($submittedAt !== '');
		$isCompleted = ($completedAt !== '');
		$isPlanClosed = ($planClosedAt !== '');
		$isRejected = false;
		if ($isSubmitted && !$isCompleted && !$isPlanClosed) {
			$qDec = @mysqli_query($db_Project, "SELECT decision FROM project_result_report_certifier_decision WHERE project_id='" . $pid . "'");
			while ($qDec && ($d = mysqli_fetch_assoc($qDec))) {
				if ((string)($d['decision'] ?? '') === 'rejected') {
					$isRejected = true;
					break;
				}
			}
		}
		$isLocked = $isSubmitted && !$isRejected && !$isCompleted;
		return [
			'is_submitted' => $isSubmitted,
			'is_locked' => $isLocked,
			'is_rejected' => $isRejected,
			'is_completed' => $isCompleted,
			'is_plan_closed' => $isPlanClosed,
			'can_submit' => (!$isSubmitted || $isRejected) && !$isCompleted && !$isPlanClosed,
			'submitted_at' => $submittedAt,
			'completed_at' => $completedAt,
			'plan_closed_at' => $planClosedAt,
			'certifiers_json' => $certRaw,
		];
	}
}

/** ตรวจความครบถ้วนของรายงานผลก่อนส่ง */
if (!function_exists('pm_check_project_report_completeness')) {
	function pm_check_project_report_completeness($db_Project, $db_KPI, $project_id): array
	{
		$pid = (int)$project_id;
		$missing = [];
		if ($pid <= 0 || !$db_Project) {
			return ['ok' => false, 'missing' => ['ไม่พบโครงการ']];
		}
		$kpiList = function_exists('getProjectKPIList') ? getProjectKPIList($db_Project, $pid) : [];
		$resultsMap = function_exists('pm_load_project_kpi_results_map')
			? pm_load_project_kpi_results_map($db_Project, $pid)
			: [];
		foreach ($kpiList as $pk) {
			$kpiId = (int)($pk['id'] ?? 0);
			$plan = function_exists('pm_kpi_sum_plan_total') ? pm_kpi_sum_plan_total($pk) : 0.0;
			if ($plan <= 0) {
				continue;
			}
			$result = function_exists('pm_kpi_sum_result_total')
				? pm_kpi_sum_result_total($resultsMap[$kpiId] ?? [])
				: 0.0;
			if ($result <= 0) {
				$name = function_exists('pm_resolve_kpi_display_name')
					? pm_resolve_kpi_display_name($db_KPI, $pk)
					: ('ตัวชี้วัด #' . $kpiId);
				$missing[] = 'ยังไม่กรอกผลตัวชี้วัด: ' . $name;
			}
		}
		$acts = function_exists('getProjectActivityList') ? getProjectActivityList($db_Project, $pid) : [];
		$actResults = function_exists('pm_load_activity_results_map')
			? pm_load_activity_results_map($db_Project, $pid)
			: [];
		foreach ($acts as $a) {
			$aid = (int)($a['id'] ?? 0);
			if ($aid <= 0) {
				continue;
			}
			$rec = $actResults[$aid] ?? null;
			$detail = is_array($rec) ? trim((string)($rec['result_detail'] ?? '')) : '';
			$actName = trim((string)($a['name_activity'] ?? ($a['activity_name'] ?? 'กิจกรรม')));
			$actLabel = $actName !== '' ? $actName : ('#' . $aid);
			if ($detail === '') {
				$missing[] = 'ยังไม่กรอกผลกิจกรรม: ' . $actLabel;
				continue;
			}
			$hasMonth = false;
			if (is_array($rec) && !empty($rec['months']) && is_array($rec['months'])) {
				foreach ($rec['months'] as $mv) {
					if (!empty($mv)) {
						$hasMonth = true;
						break;
					}
				}
			}
			if (!$hasMonth) {
				$missing[] = 'ยังไม่ทำเครื่องหมายเดือนที่ดำเนินการ (ผล) ของกิจกรรม: ' . $actLabel;
			}
		}
		$eval = function_exists('pm_load_project_evaluation_result')
			? pm_load_project_evaluation_result($db_Project, $pid)
			: null;
		$evalSt = is_array($eval) ? (string)($eval['overall_status'] ?? '') : '';
		if (!in_array($evalSt, ['achieved', 'not_achieved'], true)) {
			$missing[] = 'ยังไม่ประเมินผลโครงการ (ส่วนที่ 6)';
		} elseif ($evalSt === 'not_achieved') {
			$prob = trim((string)($eval['problem_obstacle'] ?? ''));
			$sol = trim((string)($eval['solution_suggestion'] ?? ''));
			if ($prob === '' || $sol === '') {
				$missing[] = 'การประเมินไม่บรรลุ — ต้องระบุปัญหา/อุปสรรค และแนวทางแก้ไข';
			}
		}
		return ['ok' => empty($missing), 'missing' => $missing];
	}
}

/** ผ่านลำดับผู้ตรวจสอบรายงานผลครบ */
if (!function_exists('pm_compute_result_report_chain_all_approved')) {
	function pm_compute_result_report_chain_all_approved($db_Project, $project_id, $certifiers_json = ''): bool
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return false;
		}
		if (function_exists('ensureProjectResultReportSchema')) {
			ensureProjectResultReportSchema($db_Project);
		}
		$certRaw = trim((string)$certifiers_json);
		if ($certRaw === '') {
			$q = @mysqli_query($db_Project, "SELECT result_report_certifiers_json FROM pre_project WHERE id='" . $pid . "' LIMIT 1");
			$r = $q ? mysqli_fetch_assoc($q) : null;
			$certRaw = trim((string)($r['result_report_certifiers_json'] ?? ''));
		}
		$certArr = $certRaw !== '' ? json_decode($certRaw, true) : [];
		if (!is_array($certArr) || empty($certArr)) {
			return false;
		}
		$required = [];
		$seq = 0;
		foreach ($certArr as $c) {
			if (!is_array($c)) {
				continue;
			}
			$seq++;
			$so = (int)($c['sort_order'] ?? 0);
			if ($so <= 0) {
				$so = $seq;
			}
			if ((int)($c['staff_id'] ?? 0) > 0) {
				$required[$so] = true;
			}
		}
		if (empty($required)) {
			return false;
		}
		$decMap = [];
		$qDec = @mysqli_query($db_Project, "SELECT sort_order, decision FROM project_result_report_certifier_decision WHERE project_id='" . $pid . "'");
		while ($qDec && ($d = mysqli_fetch_assoc($qDec))) {
			$so = (int)($d['sort_order'] ?? 0);
			if ($so > 0) {
				$decMap[$so] = (string)($d['decision'] ?? '');
			}
		}
		foreach (array_keys($required) as $so) {
			if (($decMap[$so] ?? '') !== 'approved') {
				return false;
			}
		}
		return true;
	}
}

/** สร้างแถวลำดับผู้ตรวจสอบรายงานผลสำหรับแสดงประวัติ */
if (!function_exists('pm_build_result_report_review_rows')) {
	function pm_build_result_report_review_rows($db_Project, $db_person, int $project_id, array $saved_pre = []): array
	{
		$out = [
			'rows' => [],
			'is_submitted' => false,
			'is_completed' => false,
			'is_rejected' => false,
			'all_approved' => false,
			'submitted_at_th' => '',
			'completed_at_th' => '',
			'rejected_note' => '',
			'rejected_at_th' => '',
			'rejected_by_name' => '',
			'reply_note' => '',
			'reply_at_th' => '',
			'reply_staff_name' => '',
			'reply_nested' => false,
		];
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return $out;
		}
		if (function_exists('ensureProjectResultReportSchema')) {
			ensureProjectResultReportSchema($db_Project);
		}
		$state = function_exists('pm_get_project_result_report_state')
			? pm_get_project_result_report_state($db_Project, $pid)
			: [];
		$fmtDt = static function ($dtTxt): string {
			$dtTxt = trim((string)$dtTxt);
			if ($dtTxt === '') {
				return '';
			}
			try {
				$ts = strtotime($dtTxt);
				if ($ts === false) {
					return $dtTxt;
				}
				$m = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
				$d = (int)date('j', $ts);
				$mi = (int)date('n', $ts);
				$y = ((int)date('Y', $ts) + 543) % 100;
				$t = date('H:i', $ts);
				return $d . ' ' . $m[max(0, min(11, $mi - 1))] . ' ' . str_pad((string)$y, 2, '0', STR_PAD_LEFT) . ' ' . $t . ' น.';
			} catch (Throwable $e) {
				return $dtTxt;
			}
		};
		$getStaffName = static function ($sid) use ($db_person): string {
			$sid = (int)$sid;
			if ($sid <= 0) {
				return '-';
			}
			if (function_exists('pm_get_staff_display_name_by_id')) {
				$nm = trim((string)pm_get_staff_display_name_by_id($db_person, $sid));
				return $nm !== '' ? $nm : ('Staff #' . $sid);
			}
			$qNm = @mysqli_query($db_person, "SELECT CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n FROM staff WHERE id='" . $sid . "' LIMIT 1");
			$rNm = $qNm ? mysqli_fetch_assoc($qNm) : null;
			$nm = trim((string)($rNm['n'] ?? ''));
			return $nm !== '' ? $nm : ('Staff #' . $sid);
		};
		$submittedAt = trim((string)($saved_pre['result_report_submitted_at'] ?? ($state['submitted_at'] ?? '')));
		$completedAt = trim((string)($saved_pre['result_report_completed_at'] ?? ($state['completed_at'] ?? '')));
		$out['is_submitted'] = ($submittedAt !== '');
		$out['is_completed'] = ($completedAt !== '');
		$out['submitted_at_th'] = $fmtDt($submittedAt);
		$out['completed_at_th'] = $fmtDt($completedAt);
		$replyNote = trim((string)($saved_pre['result_report_submitter_reply_note'] ?? ''));
		$replyAt = trim((string)($saved_pre['result_report_submitter_reply_updated_at'] ?? ''));
		$replySid = (int)($saved_pre['result_report_submitter_reply_staff_id'] ?? 0);
		$out['reply_note'] = $replyNote;
		$out['reply_at_th'] = $fmtDt($replyAt);
		$out['reply_staff_name'] = $replySid > 0 ? $getStaffName($replySid) : '';
		if (!$out['is_submitted']) {
			return $out;
		}
		$certRaw = trim((string)($saved_pre['result_report_certifiers_json'] ?? ($state['certifiers_json'] ?? '')));
		$certArr = ($certRaw !== '') ? json_decode($certRaw, true) : [];
		if (!is_array($certArr)) {
			$certArr = [];
		}
		$certMap = [];
		$seqNo = 0;
		foreach ($certArr as $__c) {
			if (!is_array($__c)) {
				continue;
			}
			$seqNo++;
			$so = (int)($__c['sort_order'] ?? 0);
			if ($so <= 0) {
				$so = $seqNo;
			}
			$sidC = (int)($__c['staff_id'] ?? 0);
			if ($sidC <= 0) {
				continue;
			}
			$certMap[$so] = [
				'staff_id' => $sidC,
				'position_title' => trim((string)($__c['position_title'] ?? $__c['position'] ?? '')),
			];
		}
		$decMap = [];
		$qDec = @mysqli_query($db_Project, "SELECT sort_order, decision, certifier_note, decided_at, decided_by_staff_id, staff_id FROM project_result_report_certifier_decision WHERE project_id='" . $pid . "' ORDER BY sort_order ASC");
		while ($qDec && ($od = mysqli_fetch_assoc($qDec))) {
			$so = (int)($od['sort_order'] ?? 0);
			if ($so > 0) {
				$decMap[$so] = $od;
			}
		}
		$allSorts = array_unique(array_merge(array_keys($certMap), array_keys($decMap)));
		sort($allSorts, SORT_NUMERIC);
		foreach ($allSorts as $__so) {
			$dv = (string)($decMap[$__so]['decision'] ?? '');
			$st = 'waiting_queue';
			if ($dv === 'approved') {
				$st = 'approved';
			} elseif ($dv === 'rejected') {
				$st = 'rejected';
				$out['is_rejected'] = true;
			} else {
				$prevOk = true;
				foreach ($allSorts as $__pso) {
					if ($__pso >= $__so) {
						break;
					}
					if ((string)($decMap[$__pso]['decision'] ?? '') !== 'approved') {
						$prevOk = false;
						break;
					}
				}
				$st = $prevOk ? 'waiting_turn' : 'waiting_queue';
			}
			$sidC = (int)($certMap[$__so]['staff_id'] ?? ($decMap[$__so]['staff_id'] ?? 0));
			$noteTxt = trim((string)($decMap[$__so]['certifier_note'] ?? ''));
			$dtTh = $fmtDt((string)($decMap[$__so]['decided_at'] ?? ''));
			if ($dv === 'rejected') {
				$out['rejected_note'] = $noteTxt;
				$out['rejected_at_th'] = $dtTh;
				$out['rejected_by_name'] = $getStaffName((int)($decMap[$__so]['decided_by_staff_id'] ?? $sidC));
			}
			$hist = [];
			if ($noteTxt !== '' && $dv !== '') {
				$hist[] = [
					'action_type' => ($dv === 'rejected') ? 'certifier_rejected' : 'certifier_approved',
					'note' => $noteTxt,
					'created_at_th' => $dtTh,
				];
			}
			$out['rows'][] = [
				'sort_order' => (int)$__so,
				'status' => $st,
				'decision' => $dv,
				'staff_name' => $getStaffName($sidC),
				'position_title' => (string)($certMap[$__so]['position_title'] ?? ''),
				'note' => $noteTxt,
				'decided_at_th' => $dtTh,
				'hist' => $hist,
			];
		}
		if ($replyNote !== '' && !empty($out['rows'])) {
			$attachIdx = 0;
			foreach ($out['rows'] as $ri => $rr) {
				if ((string)($rr['status'] ?? '') === 'rejected') {
					$attachIdx = (int)$ri;
				}
			}
			$out['rows'][$attachIdx]['hist'][] = [
				'action_type' => 'submitter_reply_saved',
				'note' => $replyNote,
				'created_at_th' => (string)$out['reply_at_th'],
			];
			$out['reply_nested'] = true;
		}
		$out['all_approved'] = !empty($out['is_completed'])
			|| (function_exists('pm_compute_result_report_chain_all_approved')
				&& pm_compute_result_report_chain_all_approved($db_Project, $pid, $certRaw));
		return $out;
	}
}

/** บล็อกแก้ไขรายงานผลเมื่อส่งแล้วและยังไม่ถูกตีกลับ (หรือเสร็จสิ้นแล้ว) */
if (!function_exists('pm_result_report_edit_blocked')) {
	function pm_result_report_edit_blocked($db_Project, $project_id): bool
	{
		if (!function_exists('pm_get_project_result_report_state')) {
			return false;
		}
		$state = pm_get_project_result_report_state($db_Project, $project_id);
		if (!empty($state['is_plan_closed'])) {
			return true;
		}
		if (empty($state['is_submitted'])) {
			return false;
		}
		if (!empty($state['is_rejected'])) {
			return false;
		}
		return true;
	}
}

if (!function_exists('pm_exit_if_result_report_edit_blocked')) {
	function pm_exit_if_result_report_edit_blocked($db_Project, $project_id): void
	{
		if (pm_result_report_edit_blocked($db_Project, $project_id)) {
			$state = function_exists('pm_get_project_result_report_state')
				? pm_get_project_result_report_state($db_Project, $project_id)
				: [];
			$msg = !empty($state['is_plan_closed'])
				? 'โครงการนี้ปิดแล้ว ไม่สามารถแก้ไขได้'
				: 'รายงานถูกส่งแล้ว ไม่สามารถแก้ไขได้จนกว่าจะถูกตีกลับ';
			if (function_exists('pm_json_exit')) {
				pm_json_exit(['ok' => 0, 'msg' => $msg]);
			}
			header('Content-Type: application/json; charset=utf-8');
			echo json_encode(['ok' => 0, 'msg' => $msg], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}
}

if (!function_exists('pm_exit_if_project_plan_closed')) {
	function pm_exit_if_project_plan_closed($db_Project, $project_id): void
	{
		if (!function_exists('pm_project_is_result_report_plan_closed')) {
			return;
		}
		if (!pm_project_is_result_report_plan_closed($db_Project, (int)$project_id)) {
			return;
		}
		$msg = 'โครงการนี้ปิดแล้ว ไม่สามารถแก้ไขได้';
		if (function_exists('pm_json_exit')) {
			pm_json_exit(['ok' => 0, 'msg' => $msg]);
		}
		header('Content-Type: application/json; charset=utf-8');
		echo json_encode(['ok' => 0, 'msg' => $msg], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

if (!function_exists('pm_fmt_operate_hist_dt')) {
	function pm_fmt_operate_hist_dt($dtTxt): string
	{
		$dtTxt = trim((string)$dtTxt);
		if ($dtTxt === '') {
			return '';
		}
		$ts = strtotime($dtTxt);
		if ($ts === false) {
			return $dtTxt;
		}
		$m = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
		$d = (int)date('j', $ts);
		$mi = (int)date('n', $ts);
		$y = ((int)date('Y', $ts) + 543) % 100;
		$t = date('H:i', $ts);
		return $d . ' ' . $m[max(0, min(11, $mi - 1))] . ' ' . str_pad((string)$y, 2, '0', STR_PAD_LEFT) . ' ' . $t . ' น.';
	}
}

if (!function_exists('pm_operate_hist_label')) {
	function pm_operate_hist_label(string $actionType): string
	{
		$t = strtolower(trim($actionType));
		if ($t === 'certifier_rejected' || $t === 'plan_admin_operate_returned') {
			return 'ข้อเสนอแนะ';
		}
		if ($t === 'submitter_reply_saved' || $t === 'submitter_reply_kept' || $t === 'operate_submitter_reply') {
			return 'คำชี้แจง';
		}
		if ($t === 'certifier_approved' || $t === 'certifier_recheck_approved') {
			return 'ความเห็น';
		}
		return 'ความเห็น';
	}
}

if (!function_exists('pm_operate_hist_is_reject')) {
	function pm_operate_hist_is_reject(string $actionType): bool
	{
		$t = strtolower(trim($actionType));
		return ($t === 'certifier_rejected' || $t === 'plan_admin_operate_returned');
	}
}

if (!function_exists('pm_render_operate_review_hist')) {
	function pm_render_operate_review_hist(array $hist, string $fallbackNote = '', string $fallbackStatus = ''): void
	{
		$items = [];
		$seen = [];
		foreach ($hist as $h) {
			if (!is_array($h)) {
				continue;
			}
			$note = trim((string)($h['note'] ?? ''));
			if ($note === '') {
				continue;
			}
			$key = strtolower((string)($h['action_type'] ?? '')) . "\n" . $note . "\n" . trim((string)($h['created_at'] ?? ''));
			if (isset($seen[$key])) {
				continue;
			}
			$seen[$key] = true;
			$items[] = $h;
		}
		$fb = trim($fallbackNote);
		if ($fb !== '') {
			$already = false;
			foreach ($items as $h) {
				if (trim((string)($h['note'] ?? '')) === $fb) {
					$already = true;
					break;
				}
			}
			if (!$already) {
				$items[] = [
					'action_type' => ($fallbackStatus === 'rejected') ? 'certifier_rejected' : 'certifier_approved',
					'note' => $fb,
					'created_at_th' => '',
				];
			}
		}
		if (empty($items)) {
			return;
		}
		foreach ($items as $h) {
			$typ = (string)($h['action_type'] ?? '');
			$note = trim((string)($h['note'] ?? ''));
			if ($note === '') {
				continue;
			}
			$cls = 'pm-review-note';
			if (pm_operate_hist_is_reject($typ)) {
				$cls .= ' pm-review-note-reject';
			} elseif (in_array(strtolower(trim($typ)), ['submitter_reply_saved', 'submitter_reply_kept', 'operate_submitter_reply', 'project_fix_confirmed'], true)) {
				$cls .= ' pm-review-note-reply';
			}
			$label = pm_operate_hist_label($typ);
			$atTh = trim((string)($h['created_at_th'] ?? ''));
			echo '<div class="' . htmlspecialchars($cls, ENT_QUOTES, 'UTF-8') . '">';
			echo '<div class="pm-review-note-head">';
			echo '<span class="pm-review-note-label">' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</span>';
			if ($atTh !== '') {
				echo '<span class="pm-review-hist-dt">' . htmlspecialchars($atTh, ENT_QUOTES, 'UTF-8') . '</span>';
			}
			echo '</div>';
			echo '<div class="pm-review-note-body">' . nl2br(htmlspecialchars($note, ENT_QUOTES, 'UTF-8')) . '</div>';
			echo '</div>';
		}
	}
}

if (!function_exists('pm_render_operate_reply_cards')) {
	function pm_render_operate_reply_cards(array $hist, string $latestNote = '', string $latestName = '', string $latestAtTh = ''): void
	{
		$cards = [];
		$seen = [];
		foreach ($hist as $h) {
			if (!is_array($h)) {
				continue;
			}
			$note = trim((string)($h['note'] ?? ''));
			if ($note === '') {
				continue;
			}
			$key = $note . "\n" . trim((string)($h['created_at'] ?? ''));
			if (isset($seen[$key])) {
				continue;
			}
			$seen[$key] = true;
			$cards[] = [
				'note' => $note,
				'staff_name' => trim((string)($h['actor_name'] ?? $h['staff_name'] ?? '')),
				'at_th' => trim((string)($h['created_at_th'] ?? '')),
			];
		}
		$fb = trim($latestNote);
		if ($fb !== '') {
			$already = false;
			foreach ($cards as $c) {
				if ((string)$c['note'] === $fb) {
					$already = true;
					break;
				}
			}
			if (!$already) {
				$cards[] = [
					'note' => $fb,
					'staff_name' => $latestName,
					'at_th' => $latestAtTh,
				];
			}
		}
		$total = count($cards);
		if ($total <= 0) {
			return;
		}
		foreach ($cards as $i => $c) {
			$isLast = ($i === $total - 1);
			$title = $isLast ? 'คำชี้แจงของผู้ยื่น (ล่าสุด)' : ('คำชี้แจงของผู้ยื่น (ครั้งที่ ' . ($i + 1) . ')');
			$idAttr = $isLast ? ' id="pmOperateReplyDisplayBox"' : '';
			$textId = $isLast ? ' id="pmOperateReplyDisplayText"' : '';
			$who = trim((string)($c['staff_name'] ?? ''));
			$when = trim((string)($c['at_th'] ?? ''));
			echo '<div class="pm-user-fix-confirmed mt-2"' . $idAttr . '>';
			echo '<div class="pm-user-fix-confirmed-head">';
			echo '<span class="pm-user-fix-confirmed-title"><i class="fa fa-reply" aria-hidden="true"></i> ' . htmlspecialchars($title, ENT_QUOTES, 'UTF-8') . '</span>';
			echo '<div class="pm-user-fix-badges">';
			echo '<span class="pm-user-fix-name-badge" title="ผู้บันทึกคำชี้แจง"><i class="fa fa-user" aria-hidden="true"></i><span>' . htmlspecialchars($who !== '' ? $who : '-', ENT_QUOTES, 'UTF-8') . '</span></span>';
			echo '<span class="pm-user-fix-date-badge" title="วันที่บันทึกคำชี้แจง"><i class="fa fa-clock" aria-hidden="true"></i><span>' . htmlspecialchars($when !== '' ? $when : '-', ENT_QUOTES, 'UTF-8') . '</span></span>';
			echo '</div></div>';
			echo '<div class="pm-user-fix-summary">';
			echo '<div class="pm-user-fix-summary-label">รายละเอียดคำชี้แจง</div>';
			echo '<div class="pm-user-fix-summary-text"' . $textId . '>' . nl2br(htmlspecialchars((string)$c['note'], ENT_QUOTES, 'UTF-8')) . '</div>';
			echo '</div></div>';
		}
	}
}

if (!function_exists('pm_collect_operate_action_hist')) {
	function pm_collect_operate_action_hist($db_Project, $db_person, int $projectId, string $rechainAt, array $operateRows, array $approverRows, bool $isLegacy): array
	{
		$out = ['cert' => [], 'appr' => [], 'replies' => [], 'plan_returns' => []];
		if ($projectId <= 0 || !$db_Project) {
			return $out;
		}
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_operate_action_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			sort_order TINYINT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_poal_project (project_id, created_at),
			KEY idx_poal_actor (actor_staff_id),
			KEY idx_poal_sort (project_id, sort_order)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$q = @mysqli_query(
			$db_Project,
			"SELECT action_type, actor_staff_id, sort_order, note, created_at
			 FROM project_operate_action_log
			 WHERE project_id='" . (int)$projectId . "'
			 ORDER BY id ASC"
		);
		if (!$q) {
			return $out;
		}
		$rechainTs = 0;
		if (trim($rechainAt) !== '') {
			$t = strtotime($rechainAt);
			if ($t !== false) {
				$rechainTs = $t;
			}
		}
		$hasCert = !empty($operateRows);
		$hasAppr = !empty($approverRows);
		$useTimeSplit = ($rechainTs > 0 && $hasCert && $hasAppr);
		$certSorts = [];
		foreach ($operateRows as $r) {
			$so = (int)($r['sort_order'] ?? 0);
			if ($so > 0) {
				$certSorts[$so] = true;
			}
		}
		$approvedCertSeen = [];
		$passedToApprover = (!$hasCert && $hasAppr);
		$lastReject = null;
		$nameCache = [];
		$nmFn = function ($sid) use ($db_person, &$nameCache) {
			$sid = (int)$sid;
			if ($sid <= 0) {
				return '';
			}
			if (isset($nameCache[$sid])) {
				return $nameCache[$sid];
			}
			$nm = '';
			if ($db_person) {
				$qNm = @mysqli_query($db_person, "SELECT CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n FROM staff WHERE id='" . (int)$sid . "' LIMIT 1");
				$rNm = $qNm ? mysqli_fetch_assoc($qNm) : null;
				$nm = trim((string)($rNm['n'] ?? ''));
			}
			if ($nm === '') {
				$nm = 'Staff #' . $sid;
			}
			$nameCache[$sid] = $nm;
			return $nm;
		};
		while ($row = mysqli_fetch_assoc($q)) {
			$typ = (string)($row['action_type'] ?? '');
			$so = (int)($row['sort_order'] ?? 0);
			$note = trim((string)($row['note'] ?? ''));
			$at = trim((string)($row['created_at'] ?? ''));
			$sidA = (int)($row['actor_staff_id'] ?? 0);
			$atTh = function_exists('pm_fmt_operate_hist_dt') ? pm_fmt_operate_hist_dt($at) : $at;
			$item = [
				'action_type' => $typ,
				'sort_order' => $so,
				'note' => $note,
				'created_at' => $at,
				'created_at_th' => $atTh,
				'actor_staff_id' => $sidA,
				'actor_name' => $sidA > 0 ? $nmFn($sidA) : '',
			];
			$atTs = ($at !== '') ? strtotime($at) : false;
			if (in_array($typ, ['submitter_reply_saved', 'submitter_reply_kept', 'operate_submitter_reply'], true)) {
				if ($note === '') {
					continue;
				}
				$attachWave = '';
				$attachSo = 0;
				if (is_array($lastReject) && (int)($lastReject['so'] ?? 0) > 0) {
					$attachWave = (string)($lastReject['wave'] ?? 'cert');
					$attachSo = (int)$lastReject['so'];
				} elseif ($so > 0) {
					$attachSo = $so;
					$attachWave = (isset($certSorts[$so]) || !$hasAppr) ? 'cert' : 'appr';
				}
				if ($attachWave !== '' && $attachSo > 0 && isset($out[$attachWave])) {
					$item['sort_order'] = $attachSo;
					$out[$attachWave][$attachSo][] = $item;
				} else {
					$out['replies'][] = $item;
				}
				continue;
			}
			if ($typ === 'plan_admin_operate_returned') {
				if ($note !== '') {
					$out['plan_returns'][] = $item;
				}
				continue;
			}
			if (!in_array($typ, ['certifier_rejected', 'certifier_approved', 'certifier_recheck_approved'], true)) {
				continue;
			}
			$wave = 'cert';
			if ($useTimeSplit) {
				if ($atTs !== false && $atTs >= $rechainTs) {
					$wave = 'appr';
				}
			} elseif ($hasCert && $hasAppr && !$isLegacy) {
				$wave = $passedToApprover ? 'appr' : 'cert';
			} elseif ($hasAppr && !$hasCert) {
				$wave = 'appr';
			}
			if ($so > 0) {
				$out[$wave][$so][] = $item;
			}
			if ($typ === 'certifier_rejected' && $so > 0) {
				$lastReject = ['wave' => $wave, 'so' => $so];
			}
			if (!$useTimeSplit && $hasCert && $hasAppr && !$isLegacy && !$passedToApprover) {
				if ($typ === 'certifier_approved' || $typ === 'certifier_recheck_approved') {
					if (isset($certSorts[$so])) {
						$approvedCertSeen[$so] = true;
					}
					if (count($certSorts) > 0 && count($approvedCertSeen) >= count($certSorts)) {
						$passedToApprover = true;
					}
				} elseif ($typ === 'certifier_rejected' && isset($certSorts[$so])) {
					unset($approvedCertSeen[$so]);
				}
			}
		}
		return $out;
	}
}

