/** ร้อยละความสำเร็จรวมทุกกิจกรรม (ถ่วงน้ำหนักตาม activity_weight) */
if (!function_exists('pm_compute_activity_list_overall_progress_percent')) {
	function pm_compute_activity_list_overall_progress_percent(array $activityList, array $resultsMap): ?float
	{
		if (empty($activityList)) {
			return null;
		}
		$weightSum = 0.0;
		$weightedPct = 0.0;
		$hasAnyProgress = false;
		foreach ($activityList as $a) {
			$w = (float)($a['activity_weight'] ?? 0);
			if ($w <= 0) {
				continue;
			}
			$actId = (int)($a['id'] ?? 0);
			$rec = $actId > 0 ? ($resultsMap[$actId] ?? null) : null;
			$prog = 0.0;
			if (is_array($rec) && $rec['progress_percent'] !== null && $rec['progress_percent'] !== '') {
				$prog = (float)$rec['progress_percent'];
				$hasAnyProgress = true;
			}
			$weightedPct += $w * $prog;
			$weightSum += $w;
		}
		if ($weightSum <= 0 || !$hasAnyProgress) {
			return null;
		}
		return round($weightedPct / $weightSum, 2);
	}
}

