/** ข้อความค่าน้ำหนักต่อท้ายชื่อตัวชี้วัด เช่น (ค่าน้ำหนัก : 50) */
if (!function_exists('pm_format_kpi_weight_label')) {
	function pm_format_kpi_weight_label($weight): string
	{
		$w = trim((string)$weight);
		if ($w !== '' && is_numeric($w)) {
			$w = rtrim(rtrim(number_format((float)$w, 2, '.', ''), '0'), '.');
		}
		if ($w === '') {
			$w = '0';
		}
		return '(ค่าน้ำหนัก : ' . $w . ')';
	}
}

