if (!function_exists('pm_render_kpi_goal_result_row')) {
	function pm_render_kpi_goal_result_row(int $project_kpi_id, array $pk, array $resultsMap, callable $fmtInt, string $kpiName = '', string $kpiUnit = '', string $kpiPlanJson = ''): void
	{
