/** ปุ่มกรอกผล / แก้ไขผล ในตารางตัวชี้วัด */
if (!function_exists('pm_render_kpi_fill_result_button')) {
	function pm_render_kpi_fill_result_button(int $kpiId, string $kpiName, string $kpiUnit, string $kpiPlanJson, array $kpiResultsMap, string $mode = 'auto'): void
	{
		if ($kpiId <= 0) {
			return;
		}
		$hasResults = pm_kpi_sum_result_total($kpiResultsMap[$kpiId] ?? []) > 0;
		if ($mode === 'fill' && $hasResults) {
			return;
		}
		if ($mode === 'edit' && !$hasResults) {
			return;
		}
		if ($mode === 'auto') {
			$mode = $hasResults ? 'edit' : 'fill';
		}
		$isEdit = ($mode === 'edit');
		$btnClass = $isEdit
			? 'btn btn-xs font-weight-bold btn-kpi-fill-result btn-kpi-edit-result'
			: 'btn btn-success btn-xs font-weight-bold btn-kpi-fill-result';
		$btnTitle = $isEdit ? 'แก้ไขผลตัวชี้วัด' : 'กรอกผลตัวชี้วัด';
		$btnIcon = $isEdit ? 'fa-edit' : 'fa-pen-square';
		$btnLabel = $isEdit ? 'แก้ไขผล' : 'กรอกผล';
		$actualJson = htmlspecialchars(json_encode($kpiResultsMap[$kpiId] ?? [], JSON_UNESCAPED_UNICODE), ENT_QUOTES, 'UTF-8');
		?>
		<button type="button"
			class="<?= htmlspecialchars($btnClass, ENT_QUOTES, 'UTF-8') ?>"
			data-kpi-result-id="<?= $kpiId ?>"
			data-kpi-result-has="<?= $hasResults ? '1' : '0' ?>"
			data-kpi-result-name="<?= htmlspecialchars($kpiName !== '' ? $kpiName : '-', ENT_QUOTES, 'UTF-8') ?>"
			data-kpi-result-unit="<?= htmlspecialchars($kpiUnit, ENT_QUOTES, 'UTF-8') ?>"
			data-kpi-result-plan="<?= $kpiPlanJson ?>"
			data-kpi-result-actual="<?= $actualJson ?>"
			data-toggle="modal"
			data-target="#modalKpiResultFill"
			title="<?= htmlspecialchars($btnTitle, ENT_QUOTES, 'UTF-8') ?>">
			<i class="fa <?= htmlspecialchars($btnIcon, ENT_QUOTES, 'UTF-8') ?>"></i> <?= htmlspecialchars($btnLabel, ENT_QUOTES, 'UTF-8') ?>
		</button>
		<?php
	}
}

