if (!function_exists('pm_activity_result_months_from_row')) {
	function pm_activity_result_months_from_row(array $row): array
	{
		$months = [];
		foreach (pm_activity_month_cols() as $mc) {
			$months[$mc] = (!empty($row[$mc]) && (string)$row[$mc] === '1') ? 1 : 0;
		}
		return $months;
	}
}

if (!function_exists('pm_parse_activity_result_months_input')) {
	function pm_parse_activity_result_months_input($raw): array
	{
		$months = [];
		foreach (pm_activity_month_cols() as $mc) {
			$months[$mc] = 0;
		}
		$decoded = is_array($raw) ? $raw : json_decode((string)$raw, true);
		if (!is_array($decoded)) {
			return $months;
		}
		foreach (pm_activity_month_cols() as $mc) {
			$months[$mc] = !empty($decoded[$mc]) ? 1 : 0;
		}
		return $months;
	}
}

if (!function_exists('pm_activity_result_months_sql_set')) {
	function pm_activity_result_months_sql_set(array $months, callable $esc): string
	{
		$parts = [];
		foreach (pm_activity_month_cols() as $mc) {
			$parts[] = $mc . "='" . $esc((string)(int)($months[$mc] ?? 0)) . "'";
		}
		return implode(', ', $parts);
	}
}

if (!function_exists('pm_load_activity_results_map')) {
	function pm_load_activity_results_map($db_Project, $project_id): array
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return [];
		}
		if (function_exists('ensureActivityResultSchema')) {
			ensureActivityResultSchema($db_Project);
		}
		$map = [];
		$monSelect = implode(', ', pm_activity_month_cols());
		$q = @mysqli_query($db_Project, "SELECT id, project_activity_id, result_detail, progress_percent, " . $monSelect . " FROM project_activity_result WHERE project_id='" . $pid . "' AND status='1' ORDER BY id DESC");
		if (!$q) {
			return [];
		}
		while ($row = mysqli_fetch_assoc($q)) {
			$aid = (int)($row['project_activity_id'] ?? 0);
			if ($aid <= 0 || isset($map[$aid])) {
				continue;
			}
			$rid = (int)($row['id'] ?? 0);
			$targets = [];
			$tq = @mysqli_query($db_Project, "SELECT code_target, result_amount FROM project_activity_result_target WHERE result_id='" . $rid . "' AND status='1'");
			if ($tq) {
				while ($tr = mysqli_fetch_assoc($tq)) {
					$code = trim((string)($tr['code_target'] ?? ''));
					if ($code === '') {
						continue;
					}
					$targets[$code] = (float)($tr['result_amount'] ?? 0);
				}
			}
			$files = [];
			$fq = @mysqli_query($db_Project, "SELECT id, original_name, stored_file FROM project_activity_result_file WHERE result_id='" . $rid . "' AND status='1' ORDER BY id ASC");
			if ($fq) {
				while ($fr = mysqli_fetch_assoc($fq)) {
					$files[] = [
						'id' => (int)($fr['id'] ?? 0),
						'original_name' => (string)($fr['original_name'] ?? ''),
						'stored_file' => (string)($fr['stored_file'] ?? ''),
					];
				}
			}
			$map[$aid] = [
				'id' => $rid,
				'result_detail' => (string)($row['result_detail'] ?? ''),
				'progress_percent' => ($row['progress_percent'] !== null && $row['progress_percent'] !== '') ? (float)$row['progress_percent'] : null,
				'months' => pm_activity_result_months_from_row($row),
				'targets' => $targets,
				'files' => $files,
			];
		}
		return $map;
	}
}

if (!function_exists('pm_activity_result_success_percent')) {
	function pm_activity_result_success_percent($planTotal, $resultTotal): float
	{
		$plan = (float)$planTotal;
		$result = (float)$resultTotal;
		if ($plan <= 0) {
			return $result > 0 ? 100.0 : 0.0;
		}
		return round(($result / $plan) * 100, 2);
	}
}

/** โทนสีร้อยละ: เขียว=≥100, ส้ม=<100 */
if (!function_exists('pm_percent_progress_tone')) {
	function pm_percent_progress_tone(float $pct): string
	{
		if ($pct > 100) {
			return 'is-over';
		}
		if ($pct < 100) {
			return 'is-under';
		}
		return 'is-exact';
	}
}

if (!function_exists('pm_format_activity_target_amount_display')) {
	function pm_format_activity_target_amount_display($v): string
	{
		if ($v === '' || $v === null) {
			return '-';
		}
		$n = (float)$v;
		if ($n == 0.0) {
			return '0';
		}
		if (abs($n - round($n)) < 0.0001) {
			return number_format(round($n), 0);
		}
		return rtrim(rtrim(number_format($n, 2, '.', ''), '0'), '.');
	}
}

