if (!function_exists('pm_build_activity_disbursement_text')) {
	function pm_build_activity_disbursement_text($db_Project, $project_id, $activity_id): string
	{
		$pid = (int)$project_id;
		$aid = (int)$activity_id;
		if ($pid <= 0 || $aid <= 0 || !$db_Project) {
			return '';
		}
		if (!function_exists('getProjectActivityBudgetList')) {
			return '';
		}
		$monthMap = [
			'mon_10' => 'ต.ค.', 'mon_11' => 'พ.ย.', 'mon_12' => 'ธ.ค.',
			'mon_01' => 'ม.ค.', 'mon_02' => 'ก.พ.', 'mon_03' => 'มี.ค.',
			'mon_04' => 'เม.ย.', 'mon_05' => 'พ.ค.', 'mon_06' => 'มิ.ย.',
			'mon_07' => 'ก.ค.', 'mon_08' => 'ส.ค.', 'mon_09' => 'ก.ย.',
		];
		$monthCols = array_keys($monthMap);
		$items = getProjectActivityBudgetList($db_Project, $aid);
		if (empty($items)) {
			return '';
		}
		$descCol = function_exists('pmProjectActivityBudgetDescColumn')
			? pmProjectActivityBudgetDescColumn($db_Project)
			: '';
		$lines = [];
		foreach ($items as $it) {
			$itemId = (int)($it['id'] ?? 0);
			$label = function_exists('pmProjectActivityBudgetDescValue')
				? pmProjectActivityBudgetDescValue($it, $descCol)
				: trim((string)($it['detail'] ?? $it['budget_item'] ?? ''));
			if ($label === '') {
				$no = (int)($it['budget_no'] ?? 0);
				$label = $no > 0 ? ('รายการค่าใช้จ่ายที่ ' . $no) : ('รายการ #' . $itemId);
			}
			$itemTotal = (float)($it['total'] ?? 0);
			$detail = function_exists('getProjectActivityBudgetDetail')
				? getProjectActivityBudgetDetail($db_Project, $aid, $itemId)
				: null;
			$d = is_array($detail) ? $detail : [];
			$monthParts = [];
			foreach ($monthCols as $mc) {
				$v = (float)($d[$mc] ?? 0);
				if ($v > 0) {
					$monthParts[] = $monthMap[$mc] . ' ' . pm_fmt_budget_money($v, false) . ' บาท';
				}
			}
			$disbTotal = (float)($d['total'] ?? 0);
			if ($disbTotal <= 0) {
				foreach ($monthCols as $mc) {
					$disbTotal += (float)($d[$mc] ?? 0);
				}
			}
			$line = $label;
			if ($itemTotal > 0) {
				$line .= ' | งบ ' . pm_fmt_budget_money($itemTotal, false) . ' บาท';
			}
			if ($disbTotal > 0) {
				$line .= ' | เบิกจ่ายรวม ' . pm_fmt_budget_money($disbTotal, false) . ' บาท';
			}
			if (!empty($monthParts)) {
				$line .= ' | รายเดือน: ' . implode(', ', $monthParts);
			}
			$lines[] = $line;
		}
		return implode("\n", $lines);
	}
}

