if (!function_exists('pm_load_budget_disburse_reports_map')) {
	function pm_load_budget_disburse_reports_map($db_Project, $project_id): array
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return [];
		}
		if (function_exists('ensureBudgetDisburseReportSchema')) {
			ensureBudgetDisburseReportSchema($db_Project);
		}
		$map = [];
		$q = @mysqli_query($db_Project, "SELECT * FROM project_budget_disburse_report WHERE project_id='" . $pid . "' AND status='1' ORDER BY id DESC");
		if ($q) {
			while ($row = mysqli_fetch_assoc($q)) {
				$aid = (int)($row['project_activity_id'] ?? 0);
				if ($aid > 0 && !isset($map[$aid])) {
					$map[$aid] = $row;
				}
			}
		}
		$reportIds = [];
		foreach ($map as $row) {
			$rid = (int)($row['id'] ?? 0);
			if ($rid > 0) {
				$reportIds[$rid] = (int)($row['project_activity_id'] ?? 0);
			}
		}
		if (!empty($reportIds)) {
			$idList = implode(',', array_map('intval', array_keys($reportIds)));
			$ql = @mysqli_query($db_Project, "SELECT * FROM project_budget_disburse_line WHERE report_id IN (" . $idList . ") AND status='1' ORDER BY sort_order ASC, id ASC");
			if ($ql) {
				while ($line = mysqli_fetch_assoc($ql)) {
					$rid = (int)($line['report_id'] ?? 0);
					$aid = $reportIds[$rid] ?? 0;
					if ($aid <= 0) {
						continue;
					}
					if (!isset($map[$aid]['lines']) || !is_array($map[$aid]['lines'])) {
						$map[$aid]['lines'] = [];
					}
					$map[$aid]['lines'][] = $line;
				}
			}
		}
		return $map;
	}
}

if (!function_exists('pm_collect_project_budget_report_data')) {
	function pm_collect_project_budget_report_data($db_Project, $project_id): array
	{
		$monthMap = pm_budget_month_map();
		$monthCols = pm_budget_month_cols();
		$projectPlanMonths = array_fill_keys($monthCols, 0.0);
		$projectDisbMonths = array_fill_keys($monthCols, 0.0);
		$projectEstimate = 0.0;
		$projectDisbursed = 0.0;
		$activities = [];
		$acts = function_exists('getProjectActivityList') ? getProjectActivityList($db_Project, $project_id) : [];
		$disbMap = pm_load_budget_disburse_reports_map($db_Project, $project_id);
		$detailCols = [];
		$colRes = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_activity_budget_detail");
		if ($colRes) {
			while ($c = mysqli_fetch_assoc($colRes)) {
				if (!empty($c['Field'])) {
					$detailCols[(string)$c['Field']] = true;
				}
			}
		}
		$hasCodeActivityBudgetCol = isset($detailCols['code_activity_budget']);
		$budgetDescCol = function_exists('pmProjectActivityBudgetDescColumn')
			? pmProjectActivityBudgetDescColumn($db_Project)
			: '';
		foreach ($acts as $a) {
			$actId = (int)($a['id'] ?? 0);
			$items = function_exists('getProjectActivityBudgetList') ? getProjectActivityBudgetList($db_Project, $actId) : [];
			$actPlanMonths = array_fill_keys($monthCols, 0.0);
			$actEstimate = 0.0;
			$actDisbursed = 0.0;
			$itemRows = [];
			$reportRec = $disbMap[$actId] ?? null;
			$lines = (is_array($reportRec) && !empty($reportRec['lines']) && is_array($reportRec['lines']))
				? $reportRec['lines']
				: [];
			$linesByItem = [];
			foreach ($lines as $ln) {
				$iid = (int)($ln['project_activity_budget_id'] ?? 0);
				if (!isset($linesByItem[$iid])) {
					$linesByItem[$iid] = [];
				}
				$linesByItem[$iid][] = $ln;
				$amt = (float)($ln['amount'] ?? 0);
				$actDisbursed += $amt;
				$projectDisbursed += $amt;
				$m = trim((string)($ln['disburse_month'] ?? ''));
				if ($m !== '' && isset($projectDisbMonths[$m])) {
					$projectDisbMonths[$m] += $amt;
				}
			}
			foreach ($items as $it) {
				$itemId = (int)($it['id'] ?? 0);
				$itemPlan = [];
				if ($itemId > 0 && $hasCodeActivityBudgetCol) {
					$where2 = [];
					if (isset($detailCols['code_activity'])) {
						$where2[] = "code_activity='" . (int)$actId . "'";
					}
					if (isset($detailCols['code_pre_project'])) {
						$where2[] = "code_pre_project='" . (int)$project_id . "'";
					}
					$where2[] = "code_activity_budget='" . (int)$itemId . "'";
					if (isset($detailCols['status'])) {
						$where2[] = "status!='99'";
					}
					$q2 = "SELECT * FROM project_activity_budget_detail";
					if (!empty($where2)) {
						$q2 .= " WHERE " . implode(' AND ', $where2);
					}
					$q2 .= " ORDER BY id DESC LIMIT 1";
					$rs2 = @mysqli_query($db_Project, $q2);
					$rw2 = ($rs2 && mysqli_num_rows($rs2) > 0) ? mysqli_fetch_assoc($rs2) : null;
					if (is_array($rw2)) {
						$itemPlan = $rw2;
					}
				}
				$itemPlanMonths = array_fill_keys($monthCols, 0.0);
				$itemPlanTotal = 0.0;
				foreach ($monthCols as $mc) {
					$v = (float)($itemPlan[$mc] ?? 0);
					$itemPlanMonths[$mc] = $v;
					$itemPlanTotal += $v;
					$actPlanMonths[$mc] += $v;
					$projectPlanMonths[$mc] += $v;
				}
				$estimate = (float)($it['total'] ?? 0);
				$actEstimate += $estimate;
				$projectEstimate += $estimate;
				$it_name = '';
				if (!empty($it['code_expenses_detail']) && function_exists('getSetExpensesDetailByID')) {
					$exd = getSetExpensesDetailByID($db_Project, $it['code_expenses_detail']);
					$it_name = trim((string)($exd['name'] ?? ''));
				}
				if ($it_name === '') {
					$it_name = '-';
				}
				$budgetDescVal = function_exists('pmProjectActivityBudgetDescValue')
					? pmProjectActivityBudgetDescValue($it, $budgetDescCol)
					: trim((string)($it['detail'] ?? $it['budget_item'] ?? ''));
				$calcTxt = function_exists('pm_budget_item_calc_text')
					? pm_budget_item_calc_text(is_array($it) ? $it : [])
					: trim(
						($it['price'] ?? '') . ' บาท x ' .
						($it['qty1'] ?? '') . ' ' . ($it['unit1'] ?? '') .
						((!empty($it['qty2']) && (float)$it['qty2'] > 0) ? (' x ' . ($it['qty2'] ?? '') . ' ' . ($it['unit2'] ?? '')) : '')
					);
				$itemLines = $linesByItem[$itemId] ?? [];
				$itemDisb = 0.0;
				foreach ($itemLines as $ln) {
					$itemDisb += (float)($ln['amount'] ?? 0);
				}
				$itemRows[] = [
					'id' => $itemId,
					'budget_no' => (string)($it['budget_no'] ?? ''),
					'name' => $it_name,
					'desc' => $budgetDescVal,
					'calc' => ($calcTxt !== '' && $calcTxt !== ' บาท x  ') ? $calcTxt : '',
					'estimate' => $estimate,
					'plan_months' => $itemPlanMonths,
					'plan_total' => $itemPlanTotal,
					'disbursed' => $itemDisb,
					'lines' => $itemLines,
				];
			}
			$activities[] = [
				'id' => $actId,
				'activity_no' => (string)($a['activity_no'] ?? ''),
				'activity_name' => (string)($a['activity_name'] ?? ''),
				'estimate' => $actEstimate,
				'plan_months' => $actPlanMonths,
				'plan_total' => array_sum($actPlanMonths),
				'disbursed' => $actDisbursed,
				'activity_detail' => is_array($reportRec) ? trim((string)($reportRec['activity_detail'] ?? '')) : '',
				'report_id' => is_array($reportRec) ? (int)($reportRec['id'] ?? 0) : 0,
				'items' => $itemRows,
			];
		}
		$projectPlanTotal = array_sum($projectPlanMonths);
		$data = [
			'month_map' => $monthMap,
			'month_cols' => $monthCols,
			'project_estimate' => $projectEstimate,
			'project_plan_months' => $projectPlanMonths,
			'project_plan_total' => $projectPlanTotal,
			'project_disbursed_months' => $projectDisbMonths,
			'project_disbursed_total' => $projectDisbursed,
			'activities' => $activities,
		];
		if (function_exists('pm_enrich_budget_report_withdraw_status')) {
			$data = pm_enrich_budget_report_withdraw_status($db_Project, (int)$project_id, $data);
		}
		return $data;
	}
}

if (!function_exists('pm_project_disburse_budget_snapshot')) {
	function pm_project_disburse_budget_snapshot($db_Project, $project_id, $exclude_line_id = 0): array
	{
		$budget = 0.0;
		$disb = 0.0;
		$excluded = 0.0;
		if (function_exists('pm_collect_project_budget_report_data')) {
			$data = pm_collect_project_budget_report_data($db_Project, (int)$project_id);
			$budget = (float)($data['project_estimate'] ?? 0);
			$disb = (float)($data['project_disbursed_total'] ?? 0);
		}
		$excludeIds = [];
		if (is_array($exclude_line_id)) {
			foreach ($exclude_line_id as $eid) {
				$eid = (int)$eid;
				if ($eid > 0) {
					$excludeIds[$eid] = $eid;
				}
			}
		} else {
			$eid = (int)$exclude_line_id;
			if ($eid > 0) {
				$excludeIds[$eid] = $eid;
			}
		}
		if ($excludeIds !== [] && $db_Project) {
			$idList = implode(',', array_map('intval', array_values($excludeIds)));
			$q = @mysqli_query(
				$db_Project,
				"SELECT IFNULL(SUM(amount),0) AS amt FROM project_budget_disburse_line WHERE id IN (" . $idList . ") AND status='1'"
			);
			$r = $q ? mysqli_fetch_assoc($q) : null;
			if (is_array($r)) {
				$excluded = (float)($r['amt'] ?? 0);
			}
		}
		$remain = $budget - $disb;
		return [
			'budget_total' => $budget,
			'disbursed_total' => $disb,
			'remain_total' => max(0.0, $remain),
			'remain_available' => $remain + $excluded,
			'excluded_amount' => $excluded,
		];
	}
}

if (!function_exists('pm_get_budget_disburse_modal_payload')) {
	function pm_get_budget_disburse_modal_payload($db_Project, $project_id, $activity_id, $line_id = 0, $mode = 'add'): ?array
	{
		$pid = (int)$project_id;
		$aid = (int)$activity_id;
		$line_id = (int)$line_id;
		$mode = ($mode === 'edit') ? 'edit' : 'add';
		if ($pid <= 0 || $aid <= 0 || !$db_Project) {
			return null;
		}
		$acts = function_exists('getProjectActivityList') ? getProjectActivityList($db_Project, $pid) : [];
		$actRow = null;
		foreach ($acts as $a) {
			if ((int)($a['id'] ?? 0) === $aid) {
				$actRow = $a;
				break;
			}
		}
		if (!$actRow) {
			return null;
		}
		$disbMap = pm_load_budget_disburse_reports_map($db_Project, $pid);
		$reportRec = $disbMap[$aid] ?? null;
		$lines = (is_array($reportRec) && !empty($reportRec['lines']) && is_array($reportRec['lines']))
			? $reportRec['lines']
			: [];
		$items = function_exists('getProjectActivityBudgetList') ? getProjectActivityBudgetList($db_Project, $aid) : [];
		$itemPayload = [];
		foreach ($items as $it) {
			$itemId = (int)($it['id'] ?? 0);
			if ($itemId <= 0) {
				continue;
			}
			$it_name = '';
			if (!empty($it['code_expenses_detail']) && function_exists('getSetExpensesDetailByID')) {
				$exd = getSetExpensesDetailByID($db_Project, $it['code_expenses_detail']);
				$it_name = trim((string)($exd['name'] ?? ''));
			}
			if ($it_name === '') {
				$it_name = '-';
			}
			$itemPayload[] = [
				'id' => $itemId,
				'budget_no' => (string)($it['budget_no'] ?? ''),
				'name' => $it_name,
			];
		}
		$linePayload = [];
		$sessionLineIds = [];
		if ($mode === 'edit' && $line_id > 0) {
			$anchor = null;
			foreach ($lines as $ln) {
				if (is_array($ln) && (int)($ln['id'] ?? 0) === $line_id) {
					$anchor = $ln;
					break;
				}
			}
			if (!$anchor) {
				return null;
			}
			$anchorAct = trim((string)($anchor['activity_detail'] ?? ''));
			if ($anchorAct === '' && is_array($reportRec)) {
				$anchorAct = trim((string)($reportRec['activity_detail'] ?? ''));
			}
			$anchorConfirmed = trim((string)($anchor['confirmed_at'] ?? ''));
			$anchorDoc = trim((string)($anchor['doc_status'] ?? ''));
			$sessionLines = [];
			foreach ($lines as $ln) {
				if (!is_array($ln)) {
					continue;
				}
				$lid = (int)($ln['id'] ?? 0);
				if ($lid <= 0) {
					continue;
				}
				// แก้ได้เฉพาะรายการที่ยังไม่ยืนยัน
				if (trim((string)($ln['doc_status'] ?? '')) === 'confirmed') {
					continue;
				}
				$lnAct = trim((string)($ln['activity_detail'] ?? ''));
				if ($lnAct === '' && is_array($reportRec)) {
					$lnAct = trim((string)($reportRec['activity_detail'] ?? ''));
				}
				$lnConfirmed = trim((string)($ln['confirmed_at'] ?? ''));
				$sameSession = false;
				if ($anchorDoc === 'confirmed' && $anchorConfirmed !== '') {
					$sameSession = ($lnAct === $anchorAct && $lnConfirmed === $anchorConfirmed);
				} else {
					// draft: รวมรายการที่รายละเอียดกิจกรรมเดียวกันในครั้งนี้
					$sameSession = ($anchorAct !== '' && $lnAct === $anchorAct) || $lid === $line_id;
				}
				if ($sameSession) {
					$sessionLines[] = $ln;
				}
			}
			if ($sessionLines === []) {
				$sessionLines = [$anchor];
			}
			usort($sessionLines, static function ($a, $b) {
				return (int)($a['id'] ?? 0) <=> (int)($b['id'] ?? 0);
			});
			foreach ($sessionLines as $ln) {
				$lid = (int)($ln['id'] ?? 0);
				$lineActDetail = trim((string)($ln['activity_detail'] ?? ''));
				if ($lineActDetail === '' && is_array($reportRec)) {
					$lineActDetail = trim((string)($reportRec['activity_detail'] ?? ''));
				}
				$linePayload[] = [
					'id' => $lid,
					'project_activity_budget_id' => (int)($ln['project_activity_budget_id'] ?? 0),
					'line_detail' => (string)($ln['line_detail'] ?? ''),
					'activity_detail' => $lineActDetail,
					'amount' => (string)($ln['amount'] ?? ''),
					'disburse_month' => (string)($ln['disburse_month'] ?? ''),
				];
				if ($lid > 0) {
					$sessionLineIds[] = $lid;
				}
			}
			if (empty($linePayload)) {
				return null;
			}
		}
		$modalActivityDetail = '';
		if ($mode === 'edit' && !empty($linePayload[0]['activity_detail'])) {
			$modalActivityDetail = (string)$linePayload[0]['activity_detail'];
		}
		return [
			'project_activity_id' => $aid,
			'activity_no' => (string)($actRow['activity_no'] ?? ''),
			'activity_name' => (string)($actRow['activity_name'] ?? ''),
			'activity_detail' => $modalActivityDetail,
			'report_id' => is_array($reportRec) ? (int)($reportRec['id'] ?? 0) : 0,
			'items' => $itemPayload,
			'lines' => $linePayload,
			'session_line_ids' => $sessionLineIds,
			'mode' => $mode,
		];
	}
}

if (!function_exists('pm_merge_disburse_input_lines')) {
	/**
	 * คงรายการในฟอร์มตามที่ผู้ใช้เพิ่ม (1 ครั้งเบิกจ่าย = หลายรายการได้)
	 * ไม่รวมยอดข้ามแถว เพราะแต่ละแถวคือรายการค่าใช้จ่ายในครั้งเดียวกัน
	 */
	function pm_merge_disburse_input_lines(array $validLines): array
	{
		$out = [];
		foreach ($validLines as $ln) {
			if (!is_array($ln)) {
				continue;
			}
			$out[] = $ln;
		}
		return $out;
	}
}

if (!function_exists('pm_next_disburse_session_round')) {
	/** หมายเลขครั้งถัดไปของรายงานเบิกจ่าย (นับจากครั้งที่ยืนยัน/บันทึกแล้ว) */
	function pm_next_disburse_session_round($db_Project, int $report_id): int
	{
		$report_id = (int)$report_id;
		$maxRound = 0;
		if ($report_id > 0 && $db_Project) {
			$q = @mysqli_query(
				$db_Project,
				"SELECT line_detail, activity_detail, confirmed_at, doc_status
				 FROM project_budget_disburse_line
				 WHERE report_id='" . $report_id . "' AND status='1'"
			);
			$seenSessions = [];
			if ($q) {
				while ($r = mysqli_fetch_assoc($q)) {
					$detail = trim((string)($r['line_detail'] ?? ''));
					if ($detail !== '' && preg_match('/^ครั้งที่\s*(\d+)$/u', $detail, $m)) {
						$maxRound = max($maxRound, (int)$m[1]);
					}
					$act = trim((string)($r['activity_detail'] ?? ''));
					$confirmedAt = trim((string)($r['confirmed_at'] ?? ''));
					$docStatus = trim((string)($r['doc_status'] ?? ''));
					if ($act === '') {
						continue;
					}
					if ($docStatus === 'confirmed' && $confirmedAt !== '') {
						$seenSessions['c|' . $act . '|' . $confirmedAt] = true;
					} else {
						$seenSessions['d|' . $act] = true;
					}
				}
			}
			$sessionCount = count($seenSessions);
			if ($sessionCount > $maxRound) {
				$maxRound = $sessionCount;
			}
		}
		return max(1, $maxRound + 1);
	}
}

if (!function_exists('pm_group_budget_disburse_lines_for_display')) {
	/** รวมรายการในครั้งเดียวกัน (activity_detail + วันที่ยืนยัน) เป็นแถวเดียว */
	function pm_group_budget_disburse_lines_for_display(array $lines): array
	{
		$groups = [];
		$order = [];
		foreach ($lines as $ln) {
			if (!is_array($ln)) {
				continue;
			}
			$act = trim((string)($ln['activity_detail'] ?? ''));
			$confirmedAt = trim((string)($ln['confirmed_at'] ?? ''));
			$docStatus = trim((string)($ln['doc_status'] ?? ''));
			$lineDetail = trim((string)($ln['line_detail'] ?? ''));
			if ($act !== '') {
				if ($docStatus === 'confirmed' && $confirmedAt !== '') {
					$key = 'c|' . $act . '|' . $confirmedAt;
				} else {
					$key = 'd|' . $act;
				}
			} else {
				$key = '__id_' . (int)($ln['id'] ?? 0);
			}
			if (!isset($groups[$key])) {
				$groups[$key] = $ln;
				$groups[$key]['amount'] = 0.0;
				$groups[$key]['_any_unconfirmed'] = false;
				$groups[$key]['_any_confirmed'] = false;
				$groups[$key]['_session_round'] = '';
				$groups[$key]['_details'] = [];
				$order[] = $key;
			}
			$groups[$key]['amount'] += (float)($ln['amount'] ?? 0);
			$st = trim((string)($ln['doc_status'] ?? ''));
			if ($st === 'confirmed') {
				$groups[$key]['_any_confirmed'] = true;
			} else {
				$groups[$key]['_any_unconfirmed'] = true;
				if ((int)($groups[$key]['id'] ?? 0) <= 0 || trim((string)($groups[$key]['doc_status'] ?? '')) === 'confirmed') {
					$groups[$key]['id'] = (int)($ln['id'] ?? 0);
					if ($st !== 'confirmed') {
						$groups[$key]['doc_status'] = $st;
					}
				}
			}
			if ($lineDetail !== '' && preg_match('/^ครั้งที่\s*\d+$/u', $lineDetail)) {
				$groups[$key]['_session_round'] = $lineDetail;
			} elseif ($lineDetail !== '') {
				$groups[$key]['_details'][] = $lineDetail;
			}
			if (trim((string)($groups[$key]['doc_label'] ?? '')) === '' && trim((string)($ln['doc_label'] ?? '')) !== '') {
				$groups[$key]['doc_label'] = (string)$ln['doc_label'];
				$groups[$key]['doc_url'] = (string)($ln['doc_url'] ?? '');
				$groups[$key]['withdraw_status'] = (string)($ln['withdraw_status'] ?? '');
				$groups[$key]['withdraw_raw_status'] = (string)($ln['withdraw_raw_status'] ?? '');
				$groups[$key]['withdraw_status_label'] = (string)($ln['withdraw_status_label'] ?? '');
				$groups[$key]['withdraw_approval_done'] = (int)($ln['withdraw_approval_done'] ?? 0);
				$groups[$key]['withdraw_approval_total'] = (int)($ln['withdraw_approval_total'] ?? 0);
				$groups[$key]['withdraw_resume_url'] = (string)($ln['withdraw_resume_url'] ?? '');
				$groups[$key]['withdraw_reconcile'] = (string)($ln['withdraw_reconcile'] ?? '');
			}
		}
		$out = [];
		foreach ($order as $key) {
			$row = $groups[$key];
			$details = array_values(array_unique($row['_details'] ?? []));
			$sessionRound = trim((string)($row['_session_round'] ?? ''));
			// แสดงรายละเอียดกิจกรรมเป็นหลัก — ถ้ามีหลายรายการในครั้งเดียวกันไม่แตกเป็นครั้งใหม่
			if ($sessionRound !== '') {
				$row['line_detail'] = $sessionRound;
			} elseif (count($details) === 1) {
				$row['line_detail'] = (string)$details[0];
			} else {
				$row['line_detail'] = '';
			}
			if (!empty($row['_any_unconfirmed'])) {
				$row['doc_status'] = trim((string)($row['doc_status'] ?? ''));
				if ($row['doc_status'] === 'confirmed') {
					$row['doc_status'] = '';
				}
			} elseif (!empty($row['_any_confirmed'])) {
				$row['doc_status'] = 'confirmed';
			}
			unset($row['_any_unconfirmed'], $row['_any_confirmed'], $row['_session_round'], $row['_details']);
			$out[] = $row;
		}
		return $out;
	}
}

if (!function_exists('pm_format_budget_disburse_line_display')) {
	function pm_format_budget_disburse_line_display(array $ln, int $idx = 0): string
	{
		$actDetail = trim((string)($ln['activity_detail'] ?? ''));
		$lineDetail = trim((string)($ln['line_detail'] ?? ''));
		$roundLabel = '';
		if ($lineDetail !== '' && preg_match('/^ครั้งที่\s*\d+$/u', $lineDetail)) {
			$roundLabel = $lineDetail;
			$lineDetail = '';
		}
		$parts = [];
		if ($actDetail !== '') {
			$parts[] = $actDetail;
		}
		if ($lineDetail !== '' && $lineDetail !== $actDetail) {
			$parts[] = $lineDetail;
		}
		$body = implode(' — ', $parts);
		if ($body === '' && $roundLabel !== '') {
			return $roundLabel;
		}
		if ($body === '') {
			// ไม่มีรายละเอียดเลยค่อยใช้ครั้งที่จากลำดับแสดง
			return 'ครั้งที่ ' . max(1, $idx + 1);
		}
		if ($roundLabel !== '') {
			return $body . ' - ' . $roundLabel;
		}
		return $body;
	}
}

if (!function_exists('pm_budget_unit_suggestions')) {
	function pm_budget_unit_suggestions($db_Project): array
	{
		$seed = ['คน', 'มื้อ', 'ครั้ง', 'วัน', 'เดือน', 'ปี', 'ชิ้น', 'ชุด', 'เล่ม', 'ชั่วโมง', 'รายการ', 'งาน', 'กล่อง', 'แผ่น', 'ใบ'];
		$freq = [];
		foreach ($seed as $s) {
			$freq[$s] = 0;
		}
		if ($db_Project) {
			$hasStatus = false;
			$qcol = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_activity_budget LIKE 'status'");
			if ($qcol && mysqli_num_rows($qcol) > 0) {
				$hasStatus = true;
			}
			$where = $hasStatus ? " WHERE (status IS NULL OR status!='99') " : '';
			$sql = "SELECT u AS unit, COUNT(*) AS c FROM (
					SELECT TRIM(unit1) AS u FROM project_activity_budget $where
					UNION ALL
					SELECT TRIM(unit2) AS u FROM project_activity_budget $where
				) t
				WHERE u IS NOT NULL AND TRIM(u) != '' AND TRIM(u) != '0'
				GROUP BY u
				ORDER BY c DESC, u ASC
				LIMIT 120";
			$q = @mysqli_query($db_Project, $sql);
			if ($q) {
				while ($r = mysqli_fetch_assoc($q)) {
					$u = trim((string)($r['unit'] ?? ''));
					if ($u === '') {
						continue;
					}
					$freq[$u] = (int)($r['c'] ?? 0);
				}
			}
		}
		arsort($freq);
		return array_keys($freq);
	}
}

if (!function_exists('pm_fmt_budget_money')) {
	function pm_fmt_budget_money($v, bool $emptyZero = true): string
	{
		$f = (float)$v;
		if ($emptyZero && abs($f) < 0.0000001) {
			return '';
		}
		if (abs($f - round($f)) < 0.0000001) {
			return number_format((float)round($f), 0);
		}
		return number_format($f, 2);
	}
}

if (!function_exists('pm_fmt_budget_calc_num')) {
	function pm_fmt_budget_calc_num($v): string
	{
		$s = trim((string)$v);
		if ($s === '') {
			return '';
		}
		if (!is_numeric($s)) {
			return $s;
		}
		return pm_fmt_budget_money($s, false);
	}
}

if (!function_exists('pm_budget_item_calc_text')) {
	function pm_budget_item_calc_text(array $it): string
	{
		$qty2 = $it['qty2'] ?? '';
		$txt = trim(
			pm_fmt_budget_calc_num($it['price'] ?? '') . ' บาท x ' .
			pm_fmt_budget_calc_num($it['qty1'] ?? '') . ' ' . trim((string)($it['unit1'] ?? '')) .
			((!empty($qty2) && (float)$qty2 > 0)
				? (' x ' . pm_fmt_budget_calc_num($qty2) . ' ' . trim((string)($it['unit2'] ?? '')))
				: '')
		);
		if ($txt === '' || $txt === 'บาท x' || preg_match('/^บาท x\s*$/u', $txt)) {
			return '';
		}
		return $txt;
	}
}

