if (!function_exists('pm_format_thai_short_date')) {
	function pm_format_thai_short_date($dt): string
	{
		$ts = is_numeric($dt) ? (int)$dt : strtotime((string)$dt);
		if (!$ts) {
			return '-';
		}
		$months = ['', 'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
		$d = (int)date('j', $ts);
		$m = (int)date('n', $ts);
		$y = ((int)date('Y', $ts) + 543) % 100;
		return $d . ' ' . ($months[$m] ?? '') . ' ' . $y;
	}
}

if (!function_exists('pm_get_staff_display_name_by_id')) {
	function pm_get_staff_display_name_by_id($db_person, $staff_id): string
	{
		$sid = (int)$staff_id;
		if ($sid <= 0 || !$db_person) {
			return '-';
		}
		if (function_exists('getStaffByID')) {
			$row = getStaffByID($db_person, $sid);
			if (is_array($row)) {
				$name = trim((string)($row['fname'] ?? '') . ' ' . (string)($row['lname'] ?? ''));
				if ($name !== '') {
					return $name;
				}
			}
		}
		return '-';
	}
}

if (!function_exists('pm_budget_other_action_type_label')) {
	function pm_budget_other_action_type_label(string $type): string
	{
		return ($type === 'travel') ? 'ลาราชการ' : 'ยืมเงิน';
	}
}

if (!function_exists('pm_load_budget_other_actions')) {
	function pm_load_budget_other_actions($db_Project, $project_id): array
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return [];
		}
		if (function_exists('ensureBudgetOtherActionSchema')) {
			ensureBudgetOtherActionSchema($db_Project);
		}
		$list = [];
		$q = @mysqli_query($db_Project, "SELECT * FROM project_budget_other_action WHERE project_id='" . $pid . "' AND status='1' ORDER BY request_date DESC, id DESC");
		if ($q) {
			while ($row = mysqli_fetch_assoc($q)) {
				$list[] = $row;
			}
		}
		return $list;
	}
}

