if (!function_exists('pm_get_project_notify_result')) {
	function pm_get_project_notify_result($db_Project, $project_id): string
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return '';
		}
		$q = @mysqli_query($db_Project, "SHOW COLUMNS FROM pre_project LIKE 'notify_result'");
		if (!$q || mysqli_num_rows($q) === 0) {
			return '';
		}
		$rq = @mysqli_query($db_Project, "SELECT notify_result FROM pre_project WHERE id='" . $pid . "' LIMIT 1");
		$rr = $rq ? mysqli_fetch_assoc($rq) : null;
		return trim((string)($rr['notify_result'] ?? ''));
	}
}

if (!function_exists('pm_get_project_user_fix_note')) {
	function pm_get_project_user_fix_note($db_Project, $project_id): string
	{
		$pid = (int)$project_id;
		if ($pid <= 0 || !$db_Project) {
			return '';
		}
		$q = @mysqli_query($db_Project, "SHOW COLUMNS FROM pre_project LIKE 'user_fix_note'");
		if (!$q || mysqli_num_rows($q) === 0) {
			return '';
		}
		$rq = @mysqli_query($db_Project, "SELECT user_fix_note FROM pre_project WHERE id='" . $pid . "' LIMIT 1");
		$rr = $rq ? mysqli_fetch_assoc($rq) : null;
		return trim((string)($rr['user_fix_note'] ?? ''));
	}
}

if (!function_exists('pm_build_project_file_list_html')) {
	/**
	 * รายการไฟล์ส่วนที่ 7 — ใช้ทั้งหน้าแรกและ AJAX refresh
	 *
	 * @param mysqli      $db_Project
	 * @param int         $project_id pre_project.id
	 * @param string      $file_web_base path สัมพันธ์จากหน้า User (ไปยังโฟลเดอร์เก็บไฟล์)
	 */
	function pm_build_project_file_list_html($db_Project, $project_id, $file_web_base = '../document/project_files/')
	{
		if (function_exists('ensureProjectExtraSchema')) {
			ensureProjectExtraSchema($db_Project);
		}
		$pid = (int)$project_id;
		$list = function_exists('getProjectFileList') ? getProjectFileList($db_Project, $pid) : [];
		ob_start();
		if (empty($list)) {
			echo '<p class="text-muted mb-0 pm-s7-empty"><small>ยังไม่มีไฟล์แนบ</small></p>';
		} else {
			foreach ($list as $row) {
				$fid = (int)($row['id'] ?? 0);
				$orig = (string)($row['files'] ?? '');
				$stored = trim((string)($row['stored_file'] ?? ''));
				$ext = strtolower(pathinfo($orig, PATHINFO_EXTENSION));
				$isImg = in_array($ext, ['jpg', 'jpeg', 'png', 'gif', 'webp'], true);
				$isPdf = ($ext === 'pdf');
				$fileUrl = ($stored !== '') ? ($file_web_base . rawurlencode($stored)) : '';
				$safeOrig = htmlspecialchars($orig, ENT_QUOTES, 'UTF-8');
				$collapseId = 'pm-s7-prev-' . $fid;
				?>
				<div class="card pm-s7-file-row mb-2 border shadow-sm">
					<div class="card-body py-2 px-3">
						<div class="d-flex flex-wrap align-items-center">
							<span class="mr-2 text-secondary"><i class="fa fa-paperclip"></i></span>
							<span class="flex-grow-1 text-left" style="min-width:140px;"><strong class="pm-s7-fname"><?= $safeOrig ?></strong></span>
							<?php if ($stored !== '' && ($isImg || $isPdf)): ?>
								<button type="button"
									class="btn btn-sm btn-outline-secondary mr-1 pm-s7-preview-toggle"
									data-toggle="collapse"
									data-target="#<?= htmlspecialchars($collapseId, ENT_QUOTES, 'UTF-8') ?>"
									aria-expanded="false">
									<i class="fa fa-eye mr-1"></i> แสดงตัวอย่าง
								</button>
							<?php endif ?>
							<?php if ($fileUrl !== ''): ?>
								<a href="<?= htmlspecialchars($fileUrl, ENT_QUOTES, 'UTF-8') ?>" class="btn btn-sm btn-link py-0" target="_blank" rel="noopener">
									<i class="fa fa-external-link-alt mr-1"></i> เปิดไฟล์
								</a>
							<?php endif ?>
							<button type="button"
								class="btn btn-sm btn-link text-danger py-0 pm-s7-file-delete"
								title="ลบ"
								data-file-id="<?= $fid ?>">
								<i class="fa fa-trash"></i>
							</button>
						</div>
						<?php if ($stored !== '' && ($isImg || $isPdf)): ?>
							<div class="collapse mt-2 pm-s7-preview-wrap" id="<?= htmlspecialchars($collapseId, ENT_QUOTES, 'UTF-8') ?>">
								<div class="pm-s7-preview-inner border rounded bg-light p-2 text-center">
									<?php if ($isImg): ?>
										<a href="<?= htmlspecialchars($fileUrl, ENT_QUOTES, 'UTF-8') ?>" target="_blank" rel="noopener">
											<img src="<?= htmlspecialchars($fileUrl, ENT_QUOTES, 'UTF-8') ?>" alt="" class="img-fluid pm-s7-preview-img" style="max-height:320px;">
										</a>
									<?php elseif ($isPdf): ?>
										<iframe class="pm-s7-preview-iframe border-0" title="preview" src="<?= htmlspecialchars($fileUrl, ENT_QUOTES, 'UTF-8') ?>#toolbar=0" style="width:100%;min-height:420px;"></iframe>
									<?php endif ?>
								</div>
							</div>
						<?php elseif ($stored === ''): ?>
							<small class="text-warning d-block mt-1"><i class="fa fa-info-circle"></i> ไม่พบชื่อไฟล์บนเซิร์ฟเวอร์ (อัปโหลดใหม่ได้)</small>
						<?php endif ?>
					</div>
				</div>
				<?php
			}
		}
		return ob_get_clean();
	}
}

if (!function_exists('pm_json_exit')) {
	function pm_json_exit(array $payload): void
	{
		while (ob_get_level() > 0) {
			@ob_end_clean();
		}
		if (!headers_sent()) {
			header('Content-Type: application/json; charset=utf-8');
		}
		echo json_encode($payload, JSON_UNESCAPED_UNICODE);
		exit;
	}
}

$page = isset($_GET['page']) ? trim((string)$_GET['page']) : '';
$op   = isset($_GET['op']) ? trim((string)$_GET['op']) : '';
if ($op === '' && isset($_POST['op'])) {
	$op = trim((string)$_POST['op']);
}

// ส่วนที่ 4 กิจกรรม/ขั้นตอนการดำเนินงาน (AJAX)
if ($op === 'save_data_activity_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');

	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$type = isset($_POST['type']) ? trim((string)$_POST['type']) : '';
	$project_activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;

	if ($project_id <= 0 || ($type !== 'insert' && $type !== 'update' && $type !== 'delete')) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);

	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$status_now = pm_get_project_status_now($db_Project, $project_id);
	$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
	if (!pm_can_edit_full_or_plan($status_now, $notify_result_now, function_exists('pm_get_project_user_fix_note') ? pm_get_project_user_fix_note($db_Project, $project_id) : '')) {
		echo json_encode(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไข'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$esc = function($v) use ($db_Project) { return mysqli_real_escape_string($db_Project, (string)$v); };

	if ($type === 'delete') {
		if ($project_activity_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการที่ต้องการลบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$aid = (int)$project_activity_id;
		$ok = mysqli_query($db_Project, "UPDATE project_activity SET status='99', staff_insert='".(int)$sid."', dates=NOW() WHERE id='".$aid."' LIMIT 1");
		echo json_encode(['ok' => $ok ? 1 : 0, 'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'ลบไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$activity_no = trim((string)($_POST['activity_no'] ?? ''));
	$activity_name = trim((string)($_POST['activity_name'] ?? ''));
	$activity_detail = trim((string)($_POST['activity_detail'] ?? ''));
	$activity_weight = trim((string)($_POST['activity_weight'] ?? ''));
	$activity_budget_raw = trim((string)($_POST['activity_budget'] ?? ''));
	$activity_budget = ($activity_budget_raw !== '') ? (float) str_replace(',', '', $activity_budget_raw) : 0.0;
	if ($activity_budget < 0) {
		$activity_budget = 0.0;
	}
	$hasActivityBudgetCol = function_exists('pmProjectActivityHasBudgetColumn') && pmProjectActivityHasBudgetColumn($db_Project);
	if ($activity_no === '' || $activity_name === '' || $activity_weight === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกข้อมูลให้ครบถ้วน'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$w = (float)str_replace(',', '', $activity_weight);
	if (!is_numeric((string)$w) || $w < 0 || $w > 100) {
		echo json_encode(['ok' => 0, 'msg' => 'ค่าน้ำหนักกิจกรรมต้องอยู่ระหว่าง 0-100'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	// เดือนตามปีงบประมาณ (ต.ค. -> ก.ย.)
	$monthCols = ['mon_10','mon_11','mon_12','mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09'];
	$mon = [];
	foreach ($monthCols as $mc) {
		$mon[$mc] = isset($_POST[$mc]) ? 1 : 0;
	}

	$target_groups = $_POST['target_group'] ?? [];
	$target_amounts = $_POST['target_amount'] ?? [];

	if ($type === 'insert') {
		$actCols = [
			'code_pre_project', 'activity_no', 'activity_name', 'activity_detail',
			'mon_01', 'mon_02', 'mon_03', 'mon_04', 'mon_05', 'mon_06', 'mon_07', 'mon_08', 'mon_09', 'mon_10', 'mon_11', 'mon_12',
			'activity_weight', 'status', 'dates', 'staff_insert',
		];
		$actVals = [
			"'".(int)$project_id."'",
			"'".$esc($activity_no)."'",
			"'".$esc($activity_name)."'",
			"'".$esc($activity_detail)."'",
			"'".$esc($mon['mon_01'] ?? 0)."'", "'".$esc($mon['mon_02'] ?? 0)."'", "'".$esc($mon['mon_03'] ?? 0)."'", "'".$esc($mon['mon_04'] ?? 0)."'",
			"'".$esc($mon['mon_05'] ?? 0)."'", "'".$esc($mon['mon_06'] ?? 0)."'", "'".$esc($mon['mon_07'] ?? 0)."'", "'".$esc($mon['mon_08'] ?? 0)."'",
			"'".$esc($mon['mon_09'] ?? 0)."'", "'".$esc($mon['mon_10'] ?? 0)."'", "'".$esc($mon['mon_11'] ?? 0)."'", "'".$esc($mon['mon_12'] ?? 0)."'",
			"'".$esc($w)."'", "'1'", 'NOW()', "'".(int)$sid."'",
		];
		if ($hasActivityBudgetCol) {
			$actCols[] = 'budget';
			$actVals[] = "'".$esc($activity_budget)."'";
		}
		$sql = "INSERT INTO project_activity(" . implode(', ', $actCols) . ") VALUES (" . implode(', ', $actVals) . ")";
		$ok = mysqli_query($db_Project, $sql);
		$aid = $ok ? (int)mysqli_insert_id($db_Project) : 0;
		if (!$ok || $aid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}

		// targets
		if (!empty($target_groups) && is_array($target_groups)) {
			for ($i = 0; $i < count($target_groups); $i++) {
				$gid = trim((string)($target_groups[$i] ?? ''));
				$amt = (float)str_replace(',', '', (string)($target_amounts[$i] ?? '0'));
				if ($gid === '' || $amt <= 0) continue;
				@mysqli_query($db_Project, "INSERT INTO project_activity_target(code_pre_project, code_activity, code_target, target_amount, status, staff_insert, dates)
					VALUES('".(int)$project_id."','".(int)$aid."','".$esc($gid)."','".$esc($amt)."','1','".(int)$sid."',NOW())");
			}
		}

		$weightWarning = function_exists('pmValidateProjectActivitiesWeights')
			? pmValidateProjectActivitiesWeights($db_Project, $project_id)
			: null;
		echo json_encode([
			'ok' => 1,
			'id' => $aid,
			'weight_warning' => $weightWarning,
			'activity_weight_sum' => function_exists('pmGetProjectActivityWeightSum') ? pmGetProjectActivityWeightSum($db_Project, $project_id) : null,
		], JSON_UNESCAPED_UNICODE);
		exit;
	}

	// update
	if ($project_activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการที่ต้องการแก้ไข'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$aid = (int)$project_activity_id;
	$sql = "UPDATE project_activity SET
		activity_no='".$esc($activity_no)."',
		activity_name='".$esc($activity_name)."',
		activity_detail='".$esc($activity_detail)."',
		mon_01='".$esc($mon['mon_01'] ?? 0)."', mon_02='".$esc($mon['mon_02'] ?? 0)."', mon_03='".$esc($mon['mon_03'] ?? 0)."', mon_04='".$esc($mon['mon_04'] ?? 0)."',
		mon_05='".$esc($mon['mon_05'] ?? 0)."', mon_06='".$esc($mon['mon_06'] ?? 0)."', mon_07='".$esc($mon['mon_07'] ?? 0)."', mon_08='".$esc($mon['mon_08'] ?? 0)."',
		mon_09='".$esc($mon['mon_09'] ?? 0)."', mon_10='".$esc($mon['mon_10'] ?? 0)."', mon_11='".$esc($mon['mon_11'] ?? 0)."', mon_12='".$esc($mon['mon_12'] ?? 0)."',
		activity_weight='".$esc($w)."'".
		($hasActivityBudgetCol ? ", budget='".$esc($activity_budget)."'" : '').
		", staff_insert='".(int)$sid."',
		dates=NOW()
		WHERE id='".$aid."' LIMIT 1";
	$ok = mysqli_query($db_Project, $sql);
	if (!$ok) {
		echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
		exit;
	}

	// replace targets
	@mysqli_query($db_Project, "UPDATE project_activity_target SET status='99', staff_insert='".(int)$sid."', dates=NOW() WHERE code_activity='".$aid."'");
	if (!empty($target_groups) && is_array($target_groups)) {
		for ($i = 0; $i < count($target_groups); $i++) {
			$gid = trim((string)($target_groups[$i] ?? ''));
			$amt = (float)str_replace(',', '', (string)($target_amounts[$i] ?? '0'));
			if ($gid === '' || $amt <= 0) continue;
			@mysqli_query($db_Project, "INSERT INTO project_activity_target(code_pre_project, code_activity, code_target, target_amount, status, staff_insert, dates)
				VALUES('".(int)$project_id."','".(int)$aid."','".$esc($gid)."','".$esc($amt)."','1','".(int)$sid."',NOW())");
		}
	}

	$weightWarning = function_exists('pmValidateProjectActivitiesWeights')
		? pmValidateProjectActivitiesWeights($db_Project, $project_id)
		: null;
	echo json_encode([
		'ok' => 1,
		'id' => $aid,
