if ($op === 'save_activity_budget_plan_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;
	$activity_budget_id = isset($_POST['project_activity_budget_id']) ? (int)$_POST['project_activity_budget_id'] : 0; // รายการย่อย
	if ($project_id <= 0 || $activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$status_now = pm_get_project_status_now($db_Project, $project_id);
	$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
	if (!pm_can_edit_full_or_plan($status_now, $notify_result_now, function_exists('pm_get_project_user_fix_note') ? pm_get_project_user_fix_note($db_Project, $project_id) : '')) {
		echo json_encode(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไข'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (pm_plan_restricts_like_user($status_now, $notify_result_now)) {
		echo json_encode(['ok' => 0, 'msg' => 'โหมดแผนปฏิบัติการ ไม่อนุญาตแก้ไขแผนการใช้จ่ายรายเดือน'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$toDec = function($v) {
		$v = trim((string)$v);
		if ($v === '') return 0;
		$v = str_replace(',', '', $v);
		return is_numeric($v) ? (float)$v : 0;
	};
	$esc = function($v) use ($db_Project) { return mysqli_real_escape_string($db_Project, (string)$v); };

	// รองรับ DB ที่ schema ของ project_activity_budget_detail ไม่เท่ากัน
	$planCols = [];
	$colRes = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_activity_budget_detail");
	if ($colRes) {
		while ($c = mysqli_fetch_assoc($colRes)) {
			if (!empty($c['Field'])) $planCols[(string)$c['Field']] = true;
		}
	}
	$monthKeys = ['mon_10','mon_11','mon_12','mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09'];
	$hasCodeActivityBudgetCol = isset($planCols['code_activity_budget']);

	// ถ้า DB ยังไม่มีคอลัมน์ผูกกับรายการย่อย ให้เพิ่มอัตโนมัติ (เพื่อแผนการใช้จ่ายรายรายการ)
	if ($activity_budget_id > 0 && !$hasCodeActivityBudgetCol) {
		@mysqli_query($db_Project, "ALTER TABLE project_activity_budget_detail ADD COLUMN code_activity_budget INT NULL DEFAULT NULL");
		$colRes2 = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_activity_budget_detail");
		if ($colRes2) {
			$planCols = [];
			while ($c = mysqli_fetch_assoc($colRes2)) {
				if (!empty($c['Field'])) $planCols[(string)$c['Field']] = true;
			}
			$hasCodeActivityBudgetCol = isset($planCols['code_activity_budget']);
		}
	}

	$mon_10 = $toDec($_POST['mon_10'] ?? 0);
	$mon_11 = $toDec($_POST['mon_11'] ?? 0);
	$mon_12 = $toDec($_POST['mon_12'] ?? 0);
	$mon_01 = $toDec($_POST['mon_01'] ?? 0);
	$mon_02 = $toDec($_POST['mon_02'] ?? 0);
	$mon_03 = $toDec($_POST['mon_03'] ?? 0);
	$mon_04 = $toDec($_POST['mon_04'] ?? 0);
	$mon_05 = $toDec($_POST['mon_05'] ?? 0);
	$mon_06 = $toDec($_POST['mon_06'] ?? 0);
	$mon_07 = $toDec($_POST['mon_07'] ?? 0);
	$mon_08 = $toDec($_POST['mon_08'] ?? 0);
	$mon_09 = $toDec($_POST['mon_09'] ?? 0);
	$total = $mon_10 + $mon_11 + $mon_12 + $mon_01 + $mon_02 + $mon_03 + $mon_04 + $mon_05 + $mon_06 + $mon_07 + $mon_08 + $mon_09;
	if ($activity_budget_id > 0) {
		$qLimit = @mysqli_query($db_Project, "SELECT total FROM project_activity_budget WHERE id='".(int)$activity_budget_id."' AND code_pre_project='".(int)$project_id."' AND status!='99' LIMIT 1");
		$rLimit = $qLimit ? mysqli_fetch_assoc($qLimit) : null;
		$item_total = (float)($rLimit['total'] ?? 0);
		if ($item_total > 0.0001 && $total <= 0.0001) {
			echo json_encode([
				'ok' => 0,
				'msg' => 'กรุณากรอกแผนการใช้จ่ายอย่างน้อย 1 เดือน (บังคับทุกรายการค่าใช้จ่าย)',
			], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($item_total > 0 && $total > ($item_total + 0.0001)) {
			echo json_encode([
				'ok' => 0,
				'msg' => 'รวมแผนการใช้จ่ายรายเดือนต้องไม่เกินค่าใช้จ่ายรวมของรายการ (ค่าใช้จ่ายรวม '
					. pm_fmt_budget_money($item_total, false) . ' บาท, แผนรายเดือนรวม ' . pm_fmt_budget_money($total, false) . ' บาท)',
			], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}

	$detail_id = isset($_POST['project_budget_detail_id']) ? (int)$_POST['project_budget_detail_id'] : 0;

	// upsert by (project, activity, activity_budget) if column exists and id not provided
	if ($detail_id <= 0 && $activity_budget_id > 0 && $hasCodeActivityBudgetCol) {
		$where = [];
		if (isset($planCols['code_pre_project'])) $where[] = "code_pre_project='".(int)$project_id."'";
		if (isset($planCols['code_activity'])) $where[] = "code_activity='".(int)$activity_id."'";
		$where[] = "code_activity_budget='".(int)$activity_budget_id."'";
		if (isset($planCols['status'])) $where[] = "status!='99'";
		$q = "SELECT id FROM project_activity_budget_detail";
		if (!empty($where)) $q .= " WHERE " . implode(' AND ', $where);
		$q .= " ORDER BY id DESC LIMIT 1";
		$rs = @mysqli_query($db_Project, $q);
		$rw = ($rs && mysqli_num_rows($rs) > 0) ? mysqli_fetch_assoc($rs) : null;
		if ($rw && !empty($rw['id'])) $detail_id = (int)$rw['id'];
	}

	if ($detail_id > 0) {
		$sets = [];
		foreach ($monthKeys as $k) {
			if (!isset($planCols[$k])) continue;
			$sets[] = $k."='".$esc($$k)."'";
		}
		if (isset($planCols['total'])) $sets[] = "total='".$esc($total)."'";
		if ($activity_budget_id > 0 && $hasCodeActivityBudgetCol) $sets[] = "code_activity_budget='".(int)$activity_budget_id."'";
		if (isset($planCols['staff_insert'])) $sets[] = "staff_insert='".(int)$sid."'";
		if (isset($planCols['dates'])) $sets[] = "dates=NOW()";
		$sql = "UPDATE project_activity_budget_detail SET ".implode(',', $sets)." WHERE id='".(int)$detail_id."' LIMIT 1";
		$ok = mysqli_query($db_Project, $sql);
		echo json_encode(['ok' => $ok ? 1 : 0, 'id' => $detail_id, 'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$cols = [];
	$vals = [];
	if (isset($planCols['code_pre_project'])) { $cols[] = 'code_pre_project'; $vals[] = "'".(int)$project_id."'"; }
	if (isset($planCols['code_activity'])) { $cols[] = 'code_activity'; $vals[] = "'".(int)$activity_id."'"; }
	if ($activity_budget_id > 0 && $hasCodeActivityBudgetCol) { $cols[] = 'code_activity_budget'; $vals[] = "'".(int)$activity_budget_id."'"; }
	foreach ($monthKeys as $k) {
		if (!isset($planCols[$k])) continue;
		$cols[] = $k;
		$vals[] = "'".$esc($$k)."'";
	}
	if (isset($planCols['total'])) { $cols[] = 'total'; $vals[] = "'".$esc($total)."'"; }
	if (isset($planCols['status'])) { $cols[] = 'status'; $vals[] = "'1'"; }
	if (isset($planCols['staff_insert'])) { $cols[] = 'staff_insert'; $vals[] = "'".(int)$sid."'"; }
	if (isset($planCols['dates'])) { $cols[] = 'dates'; $vals[] = "NOW()"; }
	$sql = "INSERT INTO project_activity_budget_detail(".implode(',', $cols).") VALUES (".implode(',', $vals).")";
	$ok = mysqli_query($db_Project, $sql);
	$id = $ok ? (int)mysqli_insert_id($db_Project) : 0;
	echo json_encode(['ok' => $ok ? 1 : 0, 'id' => $id, 'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
	exit;
}

// โหลดข้อมูลรายงานเบิกจ่ายสำหรับเปิด modal (ส่วนที่ 5 — โหมดรายงานผล)
if ($op === 'get_budget_disburse_report_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;
	$line_id = isset($_POST['line_id']) ? (int)$_POST['line_id'] : 0;
	$mode = isset($_POST['mode']) ? trim((string)$_POST['mode']) : 'add';
	if ($project_id <= 0 || $activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$payload = pm_get_budget_disburse_modal_payload($db_Project, $project_id, $activity_id, $line_id, $mode);
	if (!$payload) {
		$errMsg = ($mode === 'edit' && $line_id > 0) ? 'ไม่พบรายการเบิกจ่ายที่ต้องการแก้ไข' : 'ไม่พบข้อมูลกิจกรรม';
		echo json_encode(['ok' => 0, 'msg' => $errMsg], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if ($mode === 'edit' && $line_id > 0) {
		$qConf = @mysqli_query(
			$db_Project,
			"SELECT IFNULL(doc_status,'') AS doc_status FROM project_budget_disburse_line WHERE id='" . (int)$line_id . "' AND status='1' LIMIT 1"
		);
		$confRow = $qConf ? mysqli_fetch_assoc($qConf) : null;
		if ($confRow && trim((string)($confRow['doc_status'] ?? '')) === 'confirmed') {
			echo json_encode(['ok' => 0, 'msg' => 'รายการนี้ยืนยันเบิกจ่ายแล้ว ไม่สามารถแก้ไขได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}
	$excludeIds = [];
	if ($mode === 'edit' && $line_id > 0) {
		$sessionIds = is_array($payload['session_line_ids'] ?? null) ? $payload['session_line_ids'] : [];
		foreach ($sessionIds as $sidEx) {
			$sidEx = (int)$sidEx;
			if ($sidEx > 0) {
				$excludeIds[] = $sidEx;
			}
		}
		if ($excludeIds === []) {
			$excludeIds[] = $line_id;
		}
	}
	$snap = function_exists('pm_project_disburse_budget_snapshot')
		? pm_project_disburse_budget_snapshot($db_Project, $project_id, $excludeIds)
		: [
			'budget_total' => 0.0,
			'disbursed_total' => 0.0,
			'remain_total' => 0.0,
			'remain_available' => 0.0,
			'excluded_amount' => 0.0,
		];
	echo json_encode([
		'ok' => 1,
		'data' => $payload,
		'project_budget_total' => (float)($snap['budget_total'] ?? 0),
		'project_disbursed_total' => (float)($snap['disbursed_total'] ?? 0),
		'project_remain_total' => (float)($snap['remain_total'] ?? 0),
		'project_remain_available' => (float)($snap['remain_available'] ?? 0),
		'edit_line_amount' => (float)($snap['excluded_amount'] ?? 0),
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// บันทึกรายงานเบิกจ่าย (ส่วนที่ 5 — โหมดรายงานผล)
if ($op === 'save_budget_disburse_report_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	while (ob_get_level() > 0) {
		@ob_end_clean();
	}
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;
	$activity_detail = isset($_POST['activity_detail']) ? trim((string)$_POST['activity_detail']) : '';
	$lines_raw = isset($_POST['lines']) ? (string)$_POST['lines'] : '[]';
	$save_mode = isset($_POST['save_mode']) ? trim((string)$_POST['save_mode']) : 'add';
	$line_id = isset($_POST['line_id']) ? (int)$_POST['line_id'] : 0;
	$do_confirm = isset($_POST['confirm']) && ((string)$_POST['confirm'] === '1' || (string)$_POST['confirm'] === 'true');
	$lines = json_decode($lines_raw, true);
	if ($project_id <= 0 || $activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (!is_array($lines)) {
		$lines = [];
	}
	if ($save_mode === 'edit' && $line_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการเบิกจ่ายที่ต้องการแก้ไข'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์บันทึกรายงานเบิกจ่าย'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureBudgetDisburseReportSchema')) {
		ensureBudgetDisburseReportSchema($db_Project);
	}
	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};
	$validLines = [];
	foreach ($lines as $ln) {
		if (!is_array($ln)) {
			continue;
		}
		$itemId = (int)($ln['project_activity_budget_id'] ?? 0);
		$detail = trim((string)($ln['line_detail'] ?? ''));
		$amount = (float)($ln['amount'] ?? 0);
		$month = trim((string)($ln['disburse_month'] ?? ''));
		if ($itemId <= 0 && $detail === '' && $amount <= 0) {
			continue;
		}
		if ($itemId <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกรายการค่าใช้จ่าย'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($amount <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุจำนวนเงินเบิกจ่ายให้มากกว่า 0'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($month === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกเดือนเบิกจ่าย'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$validLines[] = [
			'id' => (int)($ln['id'] ?? 0),
			'project_activity_budget_id' => $itemId,
			'line_detail' => $detail,
			'amount' => $amount,
			'disburse_month' => $month,
		];
	}
	if (empty($validLines)) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกรายการเบิกจ่ายอย่างน้อย 1 รายการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('pm_merge_disburse_input_lines')) {
		$validLines = pm_merge_disburse_input_lines($validLines);
	}
	if ($do_confirm) {
		$excludeIds = [];
		if ($save_mode === 'edit' && $line_id > 0) {
			// หักยอดเดิมทั้งชุดที่กำลังแก้ไข (รายการในครั้งเดียวกัน)
			$qAnchor = @mysqli_query(
				$db_Project,
				"SELECT l.id, l.activity_detail, l.confirmed_at, IFNULL(l.doc_status,'') AS doc_status, l.report_id
				 FROM project_budget_disburse_line l
				 WHERE l.id='" . (int)$line_id . "' AND l.status='1' LIMIT 1"
			);
			$anchor = $qAnchor ? mysqli_fetch_assoc($qAnchor) : null;
			if ($anchor) {
				$actKey = trim((string)($anchor['activity_detail'] ?? ''));
				$repId = (int)($anchor['report_id'] ?? 0);
				$sqlSib = "SELECT id, amount FROM project_budget_disburse_line
				           WHERE report_id='" . $repId . "' AND status='1'
				             AND IFNULL(doc_status,'') <> 'confirmed'";
				if ($actKey !== '') {
					$sqlSib .= " AND IFNULL(activity_detail,'')='" . mysqli_real_escape_string($db_Project, $actKey) . "'";
				} else {
					$sqlSib .= " AND id='" . (int)$line_id . "'";
				}
				$qSib = @mysqli_query($db_Project, $sqlSib);
				if ($qSib) {
					while ($sr = mysqli_fetch_assoc($qSib)) {
						$excludeIds[] = (int)($sr['id'] ?? 0);
					}
				}
			}
			if ($excludeIds === []) {
				$excludeIds[] = $line_id;
			}
		}
		$snap = function_exists('pm_project_disburse_budget_snapshot')
			? pm_project_disburse_budget_snapshot($db_Project, $project_id, $excludeIds)
			: ['remain_available' => 0.0];
		$newSum = 0.0;
		foreach ($validLines as $lnChk) {
			$newSum += (float)($lnChk['amount'] ?? 0);
		}
		$remainAvail = (float)($snap['remain_available'] ?? 0);
		if (($newSum - $remainAvail) > 0.005) {
			echo json_encode([
				'ok' => 0,
				'msg' => 'งบประมาณคงเหลือไม่เพียงพอ ไม่สามารถทำรายการได้',
				'over_budget' => 1,
			], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}
	$report_id = 0;
	$qr = @mysqli_query($db_Project, "SELECT id FROM project_budget_disburse_report WHERE project_id='" . (int)$project_id . "' AND project_activity_id='" . (int)$activity_id . "' AND status='1' ORDER BY id DESC LIMIT 1");
	if ($qr && ($rr = mysqli_fetch_assoc($qr))) {
		$report_id = (int)($rr['id'] ?? 0);
	}
	$savedLineIds = [];

	if ($save_mode === 'edit') {
		if ($report_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายงานเบิกจ่าย'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$qLine = @mysqli_query(
			$db_Project,
			"SELECT id, IFNULL(doc_status,'') AS doc_status, IFNULL(activity_detail,'') AS activity_detail,
			        IFNULL(line_detail,'') AS line_detail, confirmed_at
			 FROM project_budget_disburse_line
			 WHERE id='" . (int)$line_id . "' AND report_id='" . (int)$report_id . "' AND status='1' LIMIT 1"
		);
		$existLine = $qLine ? mysqli_fetch_assoc($qLine) : null;
		if (!$existLine) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการเบิกจ่ายที่ต้องการแก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($existLine['doc_status'] ?? '')) === 'confirmed' && !$do_confirm) {
			echo json_encode(['ok' => 0, 'msg' => 'รายการนี้ยืนยันเบิกจ่ายแล้ว ไม่สามารถแก้ไขได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query($db_Project, "UPDATE project_budget_disburse_report SET activity_detail='" . $esc($activity_detail) . "', staff_insert='" . (int)$sid . "', updated_at=NOW() WHERE id='" . (int)$report_id . "' LIMIT 1");

		// รายการเดิมในครั้งเดียวกัน (draft)
		$oldAct = trim((string)($existLine['activity_detail'] ?? ''));
		$oldSessionIds = [];
		$sqlOld = "SELECT id, line_detail FROM project_budget_disburse_line
		           WHERE report_id='" . (int)$report_id . "' AND status='1'
		             AND IFNULL(doc_status,'') <> 'confirmed'";
		if ($oldAct !== '') {
			$sqlOld .= " AND IFNULL(activity_detail,'')='" . $esc($oldAct) . "'";
		} else {
			$sqlOld .= " AND id='" . (int)$line_id . "'";
		}
		$qOldSess = @mysqli_query($db_Project, $sqlOld);
		$sessionRoundLabel = '';
		if ($qOldSess) {
			while ($os = mysqli_fetch_assoc($qOldSess)) {
				$oid = (int)($os['id'] ?? 0);
				if ($oid > 0) {
					$oldSessionIds[$oid] = $oid;
				}
				$od = trim((string)($os['line_detail'] ?? ''));
				if ($sessionRoundLabel === '' && preg_match('/^ครั้งที่\s*\d+$/u', $od)) {
					$sessionRoundLabel = $od;
				}
			}
		}
		if ($oldSessionIds === []) {
			$oldSessionIds[(int)$line_id] = (int)$line_id;
		}
		if ($sessionRoundLabel === '') {
			$oldDetail = trim((string)($existLine['line_detail'] ?? ''));
			if (preg_match('/^ครั้งที่\s*\d+$/u', $oldDetail)) {
				$sessionRoundLabel = $oldDetail;
			} else {
				$sessionRoundLabel = 'ครั้งที่ ' . (function_exists('pm_next_disburse_session_round')
					? max(1, pm_next_disburse_session_round($db_Project, (int)$report_id) - 1)
					: 1);
			}
		}

		$sort = 0;
		$qMax = @mysqli_query($db_Project, "SELECT IFNULL(MAX(sort_order),0) AS mx FROM project_budget_disburse_line WHERE report_id='" . (int)$report_id . "'");
		if ($qMax && ($rm = mysqli_fetch_assoc($qMax))) {
			$sort = (int)($rm['mx'] ?? 0);
		}
		$batchConfirmedAt = $do_confirm ? date('Y-m-d H:i:s') : '';
		$keptIds = [];
		$linesForPayload = [];
		$firstExtUrl = '';

		foreach ($validLines as $ln) {
			$itemId = (int)$ln['project_activity_budget_id'];
			$detail = trim((string)$ln['line_detail']);
			$amount = (float)$ln['amount'];
			$month = (string)$ln['disburse_month'];
			$rowId = (int)($ln['id'] ?? 0);
			if ($detail === '' || preg_match('/^ครั้งที่\s*\d+$/u', $detail)) {
				$detail = $sessionRoundLabel;
			}
			$docLabel = '';
			$docStatus = '';
			$docUrl = '';
			if ($do_confirm) {
				$docLabel = 'เอกสารเบิกจ่าย';
				$docStatus = 'confirmed';
				$docUrl = function_exists('pm_budget_disburse_external_url')
					? pm_budget_disburse_external_url($project_id, $rowId > 0 ? $rowId : 0, $report_id)
					: '';
				if ($firstExtUrl === '') {
					$firstExtUrl = $docUrl;
				}
			}

			if ($rowId > 0 && isset($oldSessionIds[$rowId])) {
				$sqlUp = "UPDATE project_budget_disburse_line SET
					project_activity_budget_id='" . (int)$itemId . "',
					line_detail='" . $esc($detail) . "',
					activity_detail='" . $esc($activity_detail) . "',
					amount='" . $esc((string)$amount) . "',
					disburse_month='" . $esc($month) . "'"
					. ($do_confirm
						? (", doc_label='" . $esc($docLabel) . "', doc_status='" . $esc($docStatus) . "', doc_url='" . $esc($docUrl) . "', confirmed_at='" . $esc($batchConfirmedAt) . "'")
						: '')
					. " WHERE id='" . $rowId . "' AND report_id='" . (int)$report_id . "' LIMIT 1";
				if (!@mysqli_query($db_Project, $sqlUp)) {
					echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$keptIds[$rowId] = $rowId;
				$savedLineIds[] = $rowId;
			} else {
				$sort++;
				$confirmedAtSql = $do_confirm ? ("'" . $esc($batchConfirmedAt) . "'") : 'NULL';
				$sqlLine = "INSERT INTO project_budget_disburse_line
					(report_id, project_activity_budget_id, line_detail, activity_detail, amount, disburse_month, doc_label, doc_status, doc_url, confirmed_at, sort_order, status)
					VALUES (
						'" . (int)$report_id . "',
						'" . (int)$itemId . "',
						'" . $esc($detail) . "',
						'" . $esc($activity_detail) . "',
						'" . $esc((string)$amount) . "',
						'" . $esc($month) . "',
						'" . $esc($docLabel) . "',
						'" . $esc($docStatus) . "',
						'" . $esc($docUrl) . "',
						" . $confirmedAtSql . ",
						'" . (int)$sort . "',
						'1'
					)";
				if (!@mysqli_query($db_Project, $sqlLine)) {
					echo json_encode(['ok' => 0, 'msg' => 'บันทึกรายการเพิ่มไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$newLineId = (int)mysqli_insert_id($db_Project);
				if ($newLineId <= 0) {
					echo json_encode(['ok' => 0, 'msg' => 'บันทึกรายการเพิ่มไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$keptIds[$newLineId] = $newLineId;
				$savedLineIds[] = $newLineId;
				$rowId = $newLineId;
				if ($do_confirm && function_exists('pm_budget_disburse_external_url')) {
					$lineUrl = pm_budget_disburse_external_url($project_id, $newLineId, $report_id);
					@mysqli_query($db_Project, "UPDATE project_budget_disburse_line SET doc_url='" . $esc($lineUrl) . "' WHERE id='" . $newLineId . "' LIMIT 1");
					if ($firstExtUrl === '' || $firstExtUrl === $docUrl) {
						$firstExtUrl = $lineUrl;
					}
				}
			}
			$linesForPayload[] = [
				'project_activity_budget_id' => $itemId,
				'line_detail' => $detail,
				'amount' => $amount,
				'disburse_month' => $month,
			];
			if ($do_confirm && $rowId > 0 && function_exists('pm_budget_disburse_external_url')) {
				$lineUrl = pm_budget_disburse_external_url($project_id, $rowId, $report_id);
				@mysqli_query($db_Project, "UPDATE project_budget_disburse_line SET doc_url='" . $esc($lineUrl) . "' WHERE id='" . $rowId . "' LIMIT 1");
				if ($firstExtUrl === '') {
					$firstExtUrl = $lineUrl;
				}
			}
		}

		// ลบรายการเดิมในครั้งนี้ที่ผู้ใช้เอาออกจากฟอร์ม
		foreach ($oldSessionIds as $oid) {
			if (!isset($keptIds[$oid])) {
				@mysqli_query(
					$db_Project,
					"UPDATE project_budget_disburse_line SET status='99' WHERE id='" . (int)$oid . "' AND report_id='" . (int)$report_id . "' AND status='1' LIMIT 1"
				);
			}
		}

		$extPayload = null;
		$extUrl = '';
		if ($do_confirm && function_exists('pm_build_budget_disburse_external_payload')) {
			$extPayload = pm_build_budget_disburse_external_payload(
				$db_Project,
				$project_id,
				$activity_id,
				$activity_detail,
				$linesForPayload,
				$staff_code
			);
			$extUrl = $firstExtUrl;
		}
		echo json_encode([
			'ok' => 1,
			'msg' => $do_confirm ? 'ยืนยันและจัดทำเอกสารเบิกจ่ายแล้ว' : 'แก้ไขรายการเบิกจ่ายสำเร็จ',
			'report_id' => $report_id,
			'line_ids' => $savedLineIds,
			'confirmed' => $do_confirm ? 1 : 0,
			'external_url' => $extUrl,
			'external_payload' => $extPayload,
		], JSON_UNESCAPED_UNICODE);
		exit;
	}

	if ($report_id > 0) {
		@mysqli_query($db_Project, "UPDATE project_budget_disburse_report SET activity_detail='" . $esc($activity_detail) . "', staff_insert='" . (int)$sid . "', updated_at=NOW() WHERE id='" . (int)$report_id . "' LIMIT 1");
	} else {
		$sqlIns = "INSERT INTO project_budget_disburse_report (project_id, project_activity_id, activity_detail, staff_insert, created_at, status) VALUES ('" . (int)$project_id . "', '" . (int)$activity_id . "', '" . $esc($activity_detail) . "', '" . (int)$sid . "', NOW(), '1')";
		if (!@mysqli_query($db_Project, $sqlIns)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$report_id = (int)mysqli_insert_id($db_Project);
	}
	if ($report_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sort = 0;
	$qMax = @mysqli_query($db_Project, "SELECT IFNULL(MAX(sort_order),0) AS mx FROM project_budget_disburse_line WHERE report_id='" . (int)$report_id . "'");
	if ($qMax && ($rm = mysqli_fetch_assoc($qMax))) {
		$sort = (int)($rm['mx'] ?? 0);
	}
	// 1 ฟอร์ม = 1 ครั้ง — ใช้หมายเลขครั้งเดียวกันทั้งชุดรายการ
	$sessionRound = function_exists('pm_next_disburse_session_round')
		? pm_next_disburse_session_round($db_Project, (int)$report_id)
		: 1;
	$sessionRoundLabel = 'ครั้งที่ ' . $sessionRound;
	$batchConfirmedAt = $do_confirm ? date('Y-m-d H:i:s') : '';
	$firstExtUrl = '';
	$linesForPayload = [];
	foreach ($validLines as $ln) {
		$itemId = (int)$ln['project_activity_budget_id'];
		$detail = trim((string)$ln['line_detail']);
		$amount = (float)$ln['amount'];
		$month = (string)$ln['disburse_month'];
		// ถ้าว่างหรือเป็นแค่ป้ายครั้งที่ ให้ใช้ครั้งเดียวกันของชุดนี้
		if ($detail === '' || preg_match('/^ครั้งที่\s*\d+$/u', $detail)) {
			$detail = $sessionRoundLabel;
		}
		$sort++;
		$docLabel = '';
		$docStatus = '';
		$docUrl = '';
		$confirmedAtSql = 'NULL';
		if ($do_confirm) {
			$docLabel = 'เอกสารเบิกจ่าย';
			$docStatus = 'confirmed';
			$docUrl = function_exists('pm_budget_disburse_external_url')
				? pm_budget_disburse_external_url($project_id, 0, $report_id)
				: '';
			$confirmedAtSql = "'" . $esc($batchConfirmedAt) . "'";
			if ($firstExtUrl === '') {
				$firstExtUrl = $docUrl;
			}
		}
		$sqlLine = "INSERT INTO project_budget_disburse_line
			(report_id, project_activity_budget_id, line_detail, activity_detail, amount, disburse_month, doc_label, doc_status, doc_url, confirmed_at, sort_order, status)
			VALUES (
				'" . (int)$report_id . "',
				'" . (int)$itemId . "',
				'" . $esc($detail) . "',
				'" . $esc($activity_detail) . "',
				'" . $esc((string)$amount) . "',
				'" . $esc($month) . "',
				'" . $esc($docLabel) . "',
				'" . $esc($docStatus) . "',
				'" . $esc($docUrl) . "',
				" . $confirmedAtSql . ",
				'" . (int)$sort . "',
				'1'
			)";
		if (@mysqli_query($db_Project, $sqlLine)) {
			$newLineId = (int)mysqli_insert_id($db_Project);
			if ($newLineId > 0) {
				$savedLineIds[] = $newLineId;
				$linesForPayload[] = [
					'project_activity_budget_id' => $itemId,
					'line_detail' => $detail,
					'amount' => $amount,
					'disburse_month' => $month,
				];
				if ($do_confirm && function_exists('pm_budget_disburse_external_url')) {
					$lineUrl = pm_budget_disburse_external_url($project_id, $newLineId, $report_id);
					@mysqli_query($db_Project, "UPDATE project_budget_disburse_line SET doc_url='" . $esc($lineUrl) . "' WHERE id='" . $newLineId . "' LIMIT 1");
					if ($firstExtUrl === '' || $firstExtUrl === $docUrl) {
						$firstExtUrl = $lineUrl;
					}
				}
			}
		}
	}
	if (empty($savedLineIds)) {
		echo json_encode(['ok' => 0, 'msg' => 'บันทึกรายการเบิกจ่ายไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$extPayload = null;
	if ($do_confirm && function_exists('pm_build_budget_disburse_external_payload')) {
		$extPayload = pm_build_budget_disburse_external_payload(
			$db_Project,
			$project_id,
			$activity_id,
			$activity_detail,
			$linesForPayload,
			$staff_code
		);
	}
	echo json_encode([
		'ok' => 1,
		'msg' => $do_confirm ? 'ยืนยันและจัดทำเอกสารเบิกจ่ายแล้ว' : 'เพิ่มรายการเบิกจ่ายสำเร็จ',
		'report_id' => $report_id,
		'line_ids' => $savedLineIds,
		'confirmed' => $do_confirm ? 1 : 0,
		'external_url' => $do_confirm ? $firstExtUrl : '',
		'external_payload' => $extPayload,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// ดึงรายละเอียดเบิกจ่ายจากระบบ withdraw (API external/withdraws)
if ($op === 'get_budget_disburse_external_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	while (ob_get_level() > 0) {
		@ob_end_clean();
	}
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$line_id = isset($_POST['line_id']) ? (int)$_POST['line_id'] : 0;
	if ($project_id <= 0 || $line_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	$canView = $sid > 0 && (
		(function_exists('staffCanViewPreProjectManageDetail') && staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code))
		|| (function_exists('staffCanFillKpiProjectResult') && staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code))
		|| (defined('PLAN_ADMIN') && PLAN_ADMIN)
	);
	if (!$canView) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('ensureBudgetDisburseReportSchema')) {
		ensureBudgetDisburseReportSchema($db_Project);
	}
	$qLine = @mysqli_query(
		$db_Project,
		"SELECT l.*, r.project_id, r.project_activity_id, r.activity_detail AS report_activity_detail
		 FROM project_budget_disburse_line l
		 INNER JOIN project_budget_disburse_report r ON r.id = l.report_id
		 WHERE l.id='" . (int)$line_id . "' AND l.status='1' AND r.status='1' AND r.project_id='" . (int)$project_id . "'
		 LIMIT 1"
	);
	$lineRow = $qLine ? mysqli_fetch_assoc($qLine) : null;
	if (!$lineRow) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการเบิกจ่าย'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (trim((string)($lineRow['doc_status'] ?? '')) !== 'confirmed') {
		echo json_encode(['ok' => 0, 'msg' => 'รายการนี้ยังไม่ได้ยืนยันการเบิกจ่าย'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$pre = function_exists('getPreProjectID') ? getPreProjectID($db_Project, $project_id) : null;
	$projectCode = is_array($pre) ? trim((string)($pre['code_pre_project'] ?? '')) : '';
	$projectName = is_array($pre) ? trim((string)($pre['name_project'] ?? '')) : '';
	if ($projectCode === '') {
		$projectCode = 'P' . $project_id;
	}
	$activityId = (int)($lineRow['project_activity_id'] ?? 0);
	$activityName = '';
	if ($activityId > 0 && function_exists('getProjectActivityList')) {
		foreach (getProjectActivityList($db_Project, $project_id) as $a) {
			if ((int)($a['id'] ?? 0) === $activityId) {
				$activityName = trim((string)($a['activity_name'] ?? ''));
				break;
			}
		}
	}
	$itemName = '';
	$budgetItemId = (int)($lineRow['project_activity_budget_id'] ?? 0);
	if ($budgetItemId > 0 && $activityId > 0 && function_exists('getProjectActivityBudgetList')) {
		foreach (getProjectActivityBudgetList($db_Project, $activityId) as $bi) {
			if ((int)($bi['id'] ?? 0) === $budgetItemId) {
				$itemName = trim((string)($bi['name'] ?? $bi['item_name'] ?? $bi['detail'] ?? ''));
				break;
			}
		}
	}
	$monthLabels = [
		'mon_10' => 'ต.ค.', 'mon_11' => 'พ.ย.', 'mon_12' => 'ธ.ค.',
		'mon_01' => 'ม.ค.', 'mon_02' => 'ก.พ.', 'mon_03' => 'มี.ค.',
		'mon_04' => 'เม.ย.', 'mon_05' => 'พ.ค.', 'mon_06' => 'มิ.ย.',
		'mon_07' => 'ก.ค.', 'mon_08' => 'ส.ค.', 'mon_09' => 'ก.ย.',
	];
	$disburseMonth = (string)($lineRow['disburse_month'] ?? '');
	$lineDetail = trim((string)($lineRow['line_detail'] ?? ''));
	$activityDetail = trim((string)(($lineRow['activity_detail'] ?? '') !== ''
		? $lineRow['activity_detail']
		: ($lineRow['report_activity_detail'] ?? '')));
	$lineAmount = round((float)($lineRow['amount'] ?? 0), 2);
	$lineSummary = [
		'id' => (int)($lineRow['id'] ?? 0),
		'line_detail' => $lineDetail,
		'activity_detail' => $activityDetail,
		'activity_id' => $activityId,
		'activity_name' => $activityName,
		'item_name' => $itemName,
		'amount' => $lineAmount,
		'disburse_month' => $disburseMonth,
		'disburse_month_label' => $monthLabels[$disburseMonth] ?? $disburseMonth,
		'confirmed_at' => (string)($lineRow['confirmed_at'] ?? ''),
		'doc_label' => (string)($lineRow['doc_label'] ?? ''),
		'doc_url' => (string)($lineRow['doc_url'] ?? ''),
	];

	// รายการที่ยืนยันพร้อมกันในชุดเดียวกัน (เช่น ยืนยัน 2 รายการในครั้งเดียว)
	$batchLines = function_exists('pm_load_confirmed_disburse_batch_siblings')
		? pm_load_confirmed_disburse_batch_siblings($db_Project, $lineRow)
		: [$lineRow];
	$batchAmount = 0.0;
	$batchItemNames = [];
	if ($activityId > 0 && function_exists('getProjectActivityBudgetList')) {
		foreach (getProjectActivityBudgetList($db_Project, $activityId) as $bi) {
			$bid = (int)($bi['id'] ?? 0);
			if ($bid > 0) {
				$batchItemNames[$bid] = trim((string)($bi['name'] ?? $bi['item_name'] ?? $bi['detail'] ?? ''));
			}
		}
	}
	$batchItems = [];
	foreach ($batchLines as $bl) {
		$bAmt = round((float)($bl['amount'] ?? 0), 2);
		$batchAmount += $bAmt;
		$bDetail = trim((string)($bl['line_detail'] ?? ''));
		$bItemId = (int)($bl['project_activity_budget_id'] ?? 0);
		$bItemName = $batchItemNames[$bItemId] ?? '';
		$bName = $bDetail !== '' ? $bDetail : ($bItemName !== '' ? $bItemName : 'รายการเบิกจ่าย');
		if ($bItemName !== '' && $bDetail !== '' && $bItemName !== $bDetail) {
			$bName = $bItemName . ' — ' . $bDetail;
		}
		$batchItems[] = [
			'line_id' => (int)($bl['id'] ?? 0),
			'name' => $bName,
			'category' => $bItemName,
			'amount' => $bAmt,
			'disburse_month' => (string)($bl['disburse_month'] ?? ''),
			'disburse_month_label' => $monthLabels[(string)($bl['disburse_month'] ?? '')] ?? (string)($bl['disburse_month'] ?? ''),
		];
	}
	$batchAmount = round($batchAmount, 2);
	$lineSummary['batch_count'] = count($batchItems);
	$lineSummary['batch_amount'] = $batchAmount;

	$withdraw = null;
	$apiMeta = [];
	$withdrawFetchOk = false;
	if (function_exists('pm_pbm_fetch_external_withdraws')) {
		$apiRes = pm_pbm_fetch_external_withdraws($projectCode);
		$withdrawFetchOk = !empty($apiRes['ok']);
		$apiMeta = is_array($apiRes['meta'] ?? null) ? $apiRes['meta'] : [];
		if ($withdrawFetchOk) {
			$withdraws = is_array($apiRes['data'] ?? null) ? $apiRes['data'] : [];
			$withdraw = function_exists('pm_pbm_match_external_withdraw_for_line')
				? pm_pbm_match_external_withdraw_for_line($withdraws, $lineRow, $batchLines)
				: null;
		}
	}

	$resumeUrl = '';
	$reconcile = 'confirmed_no_withdraw';
	if (is_array($withdraw) && (int)($withdraw['id'] ?? 0) > 0) {
		$reconcile = 'has_withdraw';
	} else {
		$pendingConfirms = [];
		if (function_exists('pm_pbm_fetch_pending_confirms')) {
			$pendRes = pm_pbm_fetch_pending_confirms($projectCode, '');
			if (!empty($pendRes['ok']) && is_array($pendRes['data'] ?? null)) {
				$pendingConfirms = $pendRes['data'];
			}
		}
		foreach ($pendingConfirms as $pc) {
			if (!is_array($pc)) {
				continue;
			}
			$url = trim((string)($pc['resume_url'] ?? ''));
			if ($url !== '') {
				$resumeUrl = $url;
				$reconcile = 'pending_handoff';
				break;
			}
		}
	}

	$withdrawId = is_array($withdraw) ? (int)($withdraw['id'] ?? 0) : 0;
	foreach ($batchLines as $bl) {
		$blId = (int)($bl['id'] ?? 0);
		if ($blId <= 0) {
			continue;
		}
		$curExt = (int)($bl['external_withdraw_id'] ?? 0);
		if ($withdrawId > 0) {
			if ($curExt !== $withdrawId && function_exists('pm_pbm_set_line_external_withdraw_id')) {
				pm_pbm_set_line_external_withdraw_id($db_Project, $blId, $withdrawId);
			} elseif ($curExt !== $withdrawId) {
				@mysqli_query(
					$db_Project,
					"UPDATE project_budget_disburse_line SET external_withdraw_id='" . $withdrawId . "' WHERE id='" . $blId . "' LIMIT 1"
				);
			}
		} elseif ($curExt > 0 && function_exists('pm_pbm_set_line_external_withdraw_id')) {
			// จับคู่ผิดไว้ก่อนหน้า — ล้างออก
			pm_pbm_set_line_external_withdraw_id($db_Project, $blId, null);
		}
	}
	$withdrawSystemUrl = '';
	if ($withdrawId > 0 && function_exists('pm_pbm_withdraw_system_view_url')) {
		$withdrawSystemUrl = pm_pbm_withdraw_system_view_url($projectCode, $withdrawId, $withdraw);
	}
	$openUrl = $withdrawSystemUrl !== '' ? $withdrawSystemUrl : $resumeUrl;

	// ถ้ายังไม่มีรายการในระบบเบิกจ่าย ให้สร้างมุมมองจากชุดที่ยืนยันในโครงการ
	if (!is_array($withdraw)) {
		$localStatus = $reconcile === 'pending_handoff'
			? 'รอบันทึกในระบบเบิกจ่าย'
			: 'ยืนยันแล้ว';
		$withdraw = [
			'id' => 0,
			'subject' => 'รายการเบิกจ่ายที่ยืนยันแล้ว' . ($activityName !== '' ? ' — ' . $activityName : ''),
			'project_code' => $projectCode,
			'project_name' => $projectName,
			'project_activity_name' => $activityName,
			'project_activity_detail' => $activityDetail,
			'amount' => $batchAmount > 0 ? $batchAmount : $lineAmount,
			'date' => (string)($lineRow['confirmed_at'] ?? ''),
			'raw_status' => $reconcile === 'pending_handoff' ? 'pending_handoff' : 'confirmed_local',
			'status' => $localStatus,
			'items' => $batchItems !== [] ? $batchItems : [[
				'name' => $lineDetail !== '' ? $lineDetail : 'รายการเบิกจ่าย',
				'category' => $itemName,
				'amount' => $lineAmount,
			]],
			'approval_steps' => [],
			'pdfs' => [],
			'from_local' => 1,
		];
	} elseif (empty($withdraw['items']) || !is_array($withdraw['items']) || count($withdraw['items']) < count($batchItems)) {
		// มี withdraw แต่ items ไม่ครบ — เติมจากชุดที่ยืนยันในโครงการ
		if (count($batchItems) > 1) {
			$withdraw['items'] = $batchItems;
			if (round((float)($withdraw['amount'] ?? 0), 2) <= 0) {
				$withdraw['amount'] = $batchAmount;
			}
		}
	}

	echo json_encode([
		'ok' => 1,
		'project_code' => $projectCode,
		'project_name' => $projectName,
		'line' => $lineSummary,
		'batch_lines' => $batchItems,
		'withdraw' => $withdraw,
		'withdraw_id' => $withdrawId,
		'withdraw_system_url' => $withdrawSystemUrl,
		'resume_url' => $resumeUrl,
		'open_url' => $openUrl,
		'reconcile' => $reconcile,
		'withdraw_fetch_ok' => $withdrawFetchOk ? 1 : 0,
		'meta' => $apiMeta,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// สร้างรายการการดำเนินการอื่นๆ (ขอยืมเงิน / ขออนุมัติเดินทาง)
if ($op === 'create_budget_other_action_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$action_type = isset($_POST['action_type']) ? trim((string)$_POST['action_type']) : '';
	if ($project_id <= 0 || !in_array($action_type, ['loan', 'travel'], true)) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ดำเนินการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureBudgetOtherActionSchema')) {
		ensureBudgetOtherActionSchema($db_Project);
	}
	$project_name = '';
	$qpr = @mysqli_query($db_Project, "SELECT name_project FROM pre_project WHERE id='" . (int)$project_id . "' LIMIT 1");
	if ($qpr && ($rpr = mysqli_fetch_assoc($qpr))) {
		$project_name = trim((string)($rpr['name_project'] ?? ''));
	}
	$budget_source = function_exists('resolveProjectBudgetSourceForDisplay')
		? resolveProjectBudgetSourceForDisplay($db_Project, $project_id)
		: '-';
	$typeLabel = pm_budget_other_action_type_label($action_type);
	$systemLabel = ($action_type === 'loan') ? 'ระบบยืมเงิน' : 'ระบบลาราชการ';
	$detail = 'โครงการ: ' . ($project_name !== '' ? $project_name : '-')
		. ' | แหล่งงบ: ' . ($budget_source !== '' ? $budget_source : '-')
		. ' (ดึงจาก' . $systemLabel . ' มาแสดง)';
	$status_label = 'ส่งคำขอแล้ว';
	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};
	$sqlIns = "INSERT INTO project_budget_other_action
		(project_id, action_type, project_name, budget_source, staff_insert, request_date, detail, amount, status_label, created_at, status)
		VALUES (
			'" . (int)$project_id . "',
			'" . $esc($action_type) . "',
			'" . $esc($project_name) . "',
			'" . $esc($budget_source) . "',
			'" . (int)$sid . "',
			NOW(),
			'" . $esc($detail) . "',
			'0',
			'" . $esc($status_label) . "',
			NOW(),
			'1'
		)";
	if (!@mysqli_query($db_Project, $sqlIns)) {
		echo json_encode(['ok' => 0, 'msg' => 'สร้างรายการไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$newId = (int)mysqli_insert_id($db_Project);
	echo json_encode([
		'ok' => 1,
		'msg' => 'สร้างรายการ' . $typeLabel . 'และส่งไประบบแล้ว',
		'id' => $newId,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

if ($op === 'get_project_evaluation_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	if ($project_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('ensureProjectEvaluationResultSchema')) {
		ensureProjectEvaluationResultSchema($db_Project);
	}
	$summary = pm_build_kpi_evaluation_summary($db_Project, $db_KPI, $project_id);
	$saved = pm_load_project_evaluation_result($db_Project, $project_id);
	$data = [
		'overall_status' => is_array($saved) ? (string)($saved['overall_status'] ?? '') : '',
		'problem_obstacle' => is_array($saved) ? (string)($saved['problem_obstacle'] ?? '') : '',
		'solution_suggestion' => is_array($saved) ? (string)($saved['solution_suggestion'] ?? '') : '',
		'has_saved' => is_array($saved),
	];
	echo json_encode(['ok' => 1, 'data' => $data, 'kpi_summary' => $summary], JSON_UNESCAPED_UNICODE);
	exit;
}

if ($op === 'save_project_evaluation_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$overall_status = isset($_POST['overall_status']) ? trim((string)$_POST['overall_status']) : '';
	$problem = isset($_POST['problem_obstacle']) ? trim((string)$_POST['problem_obstacle']) : '';
	$solution = isset($_POST['solution_suggestion']) ? trim((string)$_POST['solution_suggestion']) : '';
	if ($project_id <= 0 || !in_array($overall_status, ['achieved', 'not_achieved'], true)) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกการประเมินภาพรวมของโครงการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if ($overall_status === 'not_achieved' && ($problem === '' || $solution === '')) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุปัญหา/อุปสรรค และแนวทางแก้ไขเมื่อเลือกไม่บรรลุ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์บันทึกข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureProjectEvaluationResultSchema')) {
		ensureProjectEvaluationResultSchema($db_Project);
	}
	$summary = pm_build_kpi_evaluation_summary($db_Project, $db_KPI, $project_id);
	$kpiPct = $summary['overall_percent'];
	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};
	$existing = pm_load_project_evaluation_result($db_Project, $project_id);
	$pctSql = ($kpiPct === null) ? 'NULL' : ("'" . (int)$kpiPct . "'");
	if (is_array($existing) && (int)($existing['id'] ?? 0) > 0) {
		$rid = (int)$existing['id'];
		$sqlUp = "UPDATE project_evaluation_result SET
			overall_status='" . $esc($overall_status) . "',
			problem_obstacle='" . $esc($problem) . "',
			solution_suggestion='" . $esc($solution) . "',
			kpi_summary_percent=" . $pctSql . ",
			staff_insert='" . (int)$sid . "',
			updated_at=NOW()
			WHERE id='" . $rid . "' AND project_id='" . (int)$project_id . "' LIMIT 1";
		if (!@mysqli_query($db_Project, $sqlUp)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	} else {
		$sqlIns = "INSERT INTO project_evaluation_result
			(project_id, overall_status, problem_obstacle, solution_suggestion, kpi_summary_percent, staff_insert, created_at, status)
			VALUES (
				'" . (int)$project_id . "',
				'" . $esc($overall_status) . "',
				'" . $esc($problem) . "',
				'" . $esc($solution) . "',
				" . $pctSql . ",
				'" . (int)$sid . "',
				NOW(),
				'1'
			)";
		if (!@mysqli_query($db_Project, $sqlIns)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}
	echo json_encode(['ok' => 1, 'msg' => 'บันทึกการประเมินผลโครงการสำเร็จ'], JSON_UNESCAPED_UNICODE);
	exit;
}

