		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('ensureProjectResultReportSchema')) {
		ensureProjectResultReportSchema($db_Project);
	}
	$state = pm_get_project_result_report_state($db_Project, $project_id);
	$check = pm_check_project_report_completeness($db_Project, $db_KPI, $project_id);
	$prevCerts = [];
	if ($state['certifiers_json'] !== '') {
		$decoded = json_decode($state['certifiers_json'], true);
		if (is_array($decoded)) {
			$prevCerts = $decoded;
		}
	}
	$rejectedNote = '';
	$rejectedAt = '';
	$rejectedBySid = 0;
	$qRej = @mysqli_query($db_Project, "SELECT certifier_note, decided_at, decided_by_staff_id, staff_id FROM project_result_report_certifier_decision WHERE project_id='" . (int)$project_id . "' AND decision='rejected' ORDER BY decided_at DESC, sort_order DESC LIMIT 1");
	$rRej = $qRej ? mysqli_fetch_assoc($qRej) : null;
	if ($rRej) {
		$rejectedNote = trim((string)($rRej['certifier_note'] ?? ''));
		$rejectedAt = trim((string)($rRej['decided_at'] ?? ''));
		$rejectedBySid = (int)($rRej['decided_by_staff_id'] ?? ($rRej['staff_id'] ?? 0));
	}
	$prevReply = '';
	$qRep = @mysqli_query($db_Project, "SELECT result_report_submitter_reply_note FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
	$rRep = $qRep ? mysqli_fetch_assoc($qRep) : null;
	if ($rRep) {
		$prevReply = trim((string)($rRep['result_report_submitter_reply_note'] ?? ''));
	}
	echo json_encode([
		'ok' => 1,
		'complete' => !empty($check['ok']),
		'missing' => $check['missing'] ?? [],
		'state' => $state,
		'prev_certifiers' => $prevCerts,
		'is_resubmit' => !empty($state['is_rejected']),
		'rejection' => [
			'note' => $rejectedNote,
			'decided_at' => $rejectedAt,
			'decided_by_staff_id' => $rejectedBySid,
		],
		'prev_reply_note' => $prevReply,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

if ($op === 'submit_project_report_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	if ($project_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์บันทึกข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('ensureProjectResultReportSchema')) {
		ensureProjectResultReportSchema($db_Project);
	}
	$state = pm_get_project_result_report_state($db_Project, $project_id);
	if (empty($state['can_submit'])) {
		echo json_encode(['ok' => 0, 'msg' => 'รายงานถูกส่งแล้ว ไม่สามารถส่งซ้ำได้จนกว่าจะถูกตีกลับ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$check = pm_check_project_report_completeness($db_Project, $db_KPI, $project_id);
	if (empty($check['ok'])) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกรายงานให้ครบถ้วนก่อนส่ง', 'missing' => $check['missing'] ?? []], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
	$certArr = json_decode($certIn, true);
	$certNormalized = [];
	if (!is_array($certArr) || count($certArr) === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้ตรวจสอบอย่างน้อย 1 คน และเรียงลำดับการพิจารณา'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$o = 0;
	foreach ($certArr as $crow) {
		if (!is_array($crow)) {
			continue;
		}
		$cSid = (int)($crow['staff_id'] ?? 0);
		$cPos = trim((string)($crow['position'] ?? ''));
		if ($cSid <= 0 || $cPos === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้ตรวจสอบและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$o++;
		$certNormalized[] = ['sort_order' => $o, 'staff_id' => $cSid, 'position' => $cPos];
	}
	if ($o === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้ตรวจสอบอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$isResubmit = !empty($state['is_rejected']);
	$replyRaw = isset($_POST['submitter_reply_note']) ? trim((string)$_POST['submitter_reply_note']) : '';
	if ($isResubmit && $replyRaw === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุรายละเอียดการแก้ไขที่ส่งถึงผู้ตรวจสอบ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};
	$certJsonEsc = $esc(json_encode($certNormalized, JSON_UNESCAPED_UNICODE));
	$replySql = $isResubmit
		? "result_report_submitter_reply_note='" . $esc($replyRaw) . "',
		result_report_submitter_reply_updated_at=NOW(),
		result_report_submitter_reply_staff_id='" . (int)$sid . "'"
		: "result_report_submitter_reply_note=NULL,
		result_report_submitter_reply_updated_at=NULL,
		result_report_submitter_reply_staff_id=NULL";
	@mysqli_query($db_Project, "DELETE FROM project_result_report_certifier_decision WHERE project_id='" . (int)$project_id . "'");
	$sqlUp = "UPDATE pre_project SET
		result_report_certifiers_json='" . $certJsonEsc . "',
		result_report_submitted_at=NOW(),
		result_report_completed_at=NULL,
		" . $replySql . ",
		dates=NOW(),
		staff_insert='" . (int)$sid . "'
		WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1";
	if (!@mysqli_query($db_Project, $sqlUp) || mysqli_affected_rows($db_Project) < 1) {
		echo json_encode(['ok' => 0, 'msg' => 'ส่งรายงานไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$okMsg = $isResubmit
		? 'ส่งรายงานการแก้ไขโครงการแล้ว ระบบจะส่งตามลำดับผู้ตรวจสอบ'
		: 'ส่งรายงานผลโครงการแล้ว ระบบจะส่งตามลำดับผู้ตรวจสอบ';
	echo json_encode(['ok' => 1, 'msg' => $okMsg], JSON_UNESCAPED_UNICODE);
	exit;
}

if ($op === 'render_budget_table') {
	if (function_exists('mysqli_report')) {
		@mysqli_report(MYSQLI_REPORT_OFF);
	}
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	if ($project_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาเข้าสู่ระบบใหม่'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$canViewBudget = false;
	try {
		$canViewBudget = (defined('PLAN_ADMIN') && PLAN_ADMIN)
			|| (function_exists('staffCanViewPreProjectManageDetail') && staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code));
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'โหลดไม่สำเร็จ: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (!$canViewBudget) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงข้อมูล'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	try {
	$is_locked_project = false;
	$stp = @mysqli_query($db_Project, "SELECT status_project, notify_result FROM pre_project WHERE id='".(int)$project_id."' LIMIT 1");
	if ($stp && $rp = mysqli_fetch_assoc($stp)) {
		$stNow = (string)($rp['status_project'] ?? '');
		$nrNow = (string)($rp['notify_result'] ?? '');
		// สถานะ 4 + บรรจุแผน = แผนปฏิบัติการ (ขออนุมัติดำเนินโครงการ): อนุญาตแก้ไขงบรายกิจกรรมได้
		$is_locked_project = ($stNow !== '0' && $stNow !== '8' && $stNow !== '4');
		if (function_exists('pm_is_include_meeting_view_only') && pm_is_include_meeting_view_only($stNow, $nrNow)) {
			$is_locked_project = true;
		}
	}
	if (defined('PLAN_ADMIN') && PLAN_ADMIN && empty($is_locked_project)) {
		$is_locked_project = false;
	}
	if (function_exists('pm_project_is_result_report_plan_closed')
		&& pm_project_is_result_report_plan_closed($db_Project, (int)$project_id)) {
		$is_locked_project = true;
	}

	$is_budget_report_mode = pm_project_allows_kpi_result_fill($db_Project, $project_id);
	if ($is_budget_report_mode) {
		if (function_exists('ensureBudgetDisburseReportSchema')) {
			ensureBudgetDisburseReportSchema($db_Project);
		}
		if (function_exists('ensureBudgetOtherActionSchema')) {
			ensureBudgetOtherActionSchema($db_Project);
		}
		$budgetReportData = pm_collect_project_budget_report_data($db_Project, $project_id);
		$report_edit_allowed = !function_exists('pm_result_report_edit_blocked') || !pm_result_report_edit_blocked($db_Project, $project_id);
		ob_start();
		echo '<div class="pm-budget-report-mode">';
		pm_render_budget_plan_actual_summary($budgetReportData);
		pm_render_budget_expense_report_table($budgetReportData, $project_id, $report_edit_allowed);
		pm_render_budget_other_actions_table($db_Project, $db_person, $project_id, $report_edit_allowed);
		echo '</div>';
		$html = ob_get_clean();
		$jsonFlags = JSON_UNESCAPED_UNICODE;
		if (defined('JSON_INVALID_UTF8_SUBSTITUTE')) {
			$jsonFlags |= JSON_INVALID_UTF8_SUBSTITUTE;
		}
		echo json_encode([
			'ok' => 1,
			'html' => $html,
			'budget_warning' => '',
			'report_mode' => 1,
			'disburse_percent' => ($budgetReportData['project_plan_total'] > 0)
				? (int)round(($budgetReportData['project_disbursed_total'] / $budgetReportData['project_plan_total']) * 100, 0)
				: 0,
		], $jsonFlags);
		exit;
	}

	$acts = function_exists('getProjectActivityList') ? getProjectActivityList($db_Project, $project_id) : [];
	$monthMap = [
		'mon_10' => 'ต.ค.', 'mon_11' => 'พ.ย.', 'mon_12' => 'ธ.ค.',
		'mon_01' => 'ม.ค.', 'mon_02' => 'ก.พ.', 'mon_03' => 'มี.ค.',
		'mon_04' => 'เม.ย.', 'mon_05' => 'พ.ค.', 'mon_06' => 'มิ.ย.',
		'mon_07' => 'ก.ค.', 'mon_08' => 'ส.ค.', 'mon_09' => 'ก.ย.',
	];
	$monthCols = array_keys($monthMap);
	$fmt = function($v) {
		return pm_fmt_budget_money($v, true);
	};
	$fmtNum = function($v) {
		return pm_fmt_budget_money($v, false);
	};

	$budgetDescCol = function_exists('pmProjectActivityBudgetDescColumn')
		? pmProjectActivityBudgetDescColumn($db_Project)
		: '';
	$budgetWarnings = [];
	$planMissingCount = 0;
	$budgetItemsCount = 0;
	$budgetItemsMoneySum = 0.0;

	// schema-aware columns for budget_detail (บาง DB ไม่มี status/total)
	$detailCols = [];
	$colRes = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_activity_budget_detail");
	if ($colRes) {
		while ($c = mysqli_fetch_assoc($colRes)) {
			if (!empty($c['Field'])) $detailCols[(string)$c['Field']] = true;
		}
	}

	ob_start();
	?>
	<div class="table-responsive">
		<table class="table table-bordered table-hover mb-0 text-center table-kpi-project pm-budget-table" style="vertical-align:middle;">
			<thead>
				<tr class="kpi-head-1">
					<th>รายการค่าใช้จ่าย</th>
					<th style="width:140px;">รวม (บาท)</th>
					<th colspan="12">แผนการใช้จ่าย</th>
				</tr>
				<tr class="kpi-head-2">
					<th></th>
					<th></th>
					<?php foreach ($monthCols as $mc): ?>
						<th class="pm-month-th"><?= htmlspecialchars($monthMap[$mc]) ?></th>
					<?php endforeach ?>
				</tr>
			</thead>
			<tbody>
				<?php if (empty($acts)): ?>
					<tr><td colspan="14" class="text-muted text-center py-3">ยังไม่มีกิจกรรม</td></tr>
				<?php else: ?>
					<?php foreach ($acts as $a):
						$actId = (int)($a['id'] ?? 0);
						$items = function_exists('getProjectActivityBudgetList') ? getProjectActivityBudgetList($db_Project, $actId) : [];
						$max_no = 0;
						if (!empty($items)) {
							foreach ($items as $itTmp) {
								$n = (int)($itTmp['budget_no'] ?? 0);
								if ($n > $max_no) $max_no = $n;
							}
						}
						$next_no = $max_no + 1;
						// รวมแผนรายเดือนระดับ "กิจกรรม" จากรายการย่อยทั้งหมด (ให้ผลรวมตรง)
						$hasCodeActivityBudgetCol = isset($detailCols['code_activity_budget']);
						$activityPlanMonths = [];
						foreach ($monthCols as $mc) { $activityPlanMonths[$mc] = 0.0; }
						$activityPlanTotal = 0.0;
						$itemPlanMap = []; // cache แผนรายรายการย่อย
						$activityMoneyTotal = 0.0; // รวมเงินจากรายการย่อย (total)

						if (!empty($items) && $hasCodeActivityBudgetCol) {
							foreach ($items as $itTmp2) {
								$itemId2 = (int)($itTmp2['id'] ?? 0);
								if ($itemId2 <= 0) continue;
								$activityMoneyTotal += (float)($itTmp2['total'] ?? 0);
								$where2 = [];
								if (isset($detailCols['code_activity'])) $where2[] = "code_activity='".(int)$actId."'";
								if (isset($detailCols['code_pre_project'])) $where2[] = "code_pre_project='".(int)$project_id."'";
								$where2[] = "code_activity_budget='".(int)$itemId2."'";
								if (isset($detailCols['status'])) $where2[] = "status!='99'";
								$q2 = "SELECT * FROM project_activity_budget_detail";
								if (!empty($where2)) $q2 .= " WHERE " . implode(' AND ', $where2);
								$q2 .= " ORDER BY id DESC LIMIT 1";
								$rs2 = @mysqli_query($db_Project, $q2);
								$rw2 = ($rs2 && mysqli_num_rows($rs2) > 0) ? mysqli_fetch_assoc($rs2) : null;
								if (!is_array($rw2)) $rw2 = [];
								$itemPlanMap[$itemId2] = $rw2;
								foreach ($monthCols as $mc) {
									$activityPlanMonths[$mc] += (float)($rw2[$mc] ?? 0);
								}
							}
							foreach ($monthCols as $mc) { $activityPlanTotal += (float)$activityPlanMonths[$mc]; }
						} else {
							if (!empty($items)) {
								foreach ($items as $itTmp2) {
									$activityMoneyTotal += (float)($itTmp2['total'] ?? 0);
								}
							}
							// fallback: กรณี DB ยังไม่มี code_activity_budget ให้ใช้แผนระดับกิจกรรม (แบบเดิม) ถ้ามี
							$detail = function_exists('getProjectActivityBudgetDetail') ? getProjectActivityBudgetDetail($db_Project, $actId) : null;
							$d = is_array($detail) ? $detail : [];
							if (empty($d) || (!array_key_exists('mon_10', $d) && !array_key_exists('mon_01', $d))) {
								$where = [];
								if (isset($detailCols['code_activity'])) $where[] = "code_activity='".(int)$actId."'";
								if (isset($detailCols['code_pre_project'])) $where[] = "code_pre_project='".(int)$project_id."'";
								if (isset($detailCols['status'])) $where[] = "status!='99'";
								$q = "SELECT * FROM project_activity_budget_detail";
								if (!empty($where)) $q .= " WHERE " . implode(' AND ', $where);
								$q .= " ORDER BY id DESC LIMIT 1";
								$rs = @mysqli_query($db_Project, $q);
								$rw = ($rs && mysqli_num_rows($rs) > 0) ? mysqli_fetch_assoc($rs) : null;
								if (is_array($rw)) $d = $rw;
							}
							foreach ($monthCols as $mc) { $activityPlanMonths[$mc] = (float)($d[$mc] ?? 0); $activityPlanTotal += (float)($d[$mc] ?? 0); }
						}
						$activityBudgetLimit = function_exists('pmGetProjectActivityBudgetLimit')
							? pmGetProjectActivityBudgetLimit($db_Project, $actId)
							: (float)($a['budget'] ?? 0);
						$budgetOver = ($activityBudgetLimit > 0 && $activityMoneyTotal > ($activityBudgetLimit + 0.0001));
						$budgetCellVal = ($activityBudgetLimit > 0) ? $activityBudgetLimit : $activityMoneyTotal;
						if ($budgetOver) {
							$actLabel = trim((string)($a['activity_no'] ?? '')) . '. ' . trim((string)($a['activity_name'] ?? ''));
							$budgetWarnings[] = 'กิจกรรม ' . $actLabel . ' รวมรายการค่าใช้จ่าย '
								. $fmtNum($activityMoneyTotal) . ' บาท เกินงบประมาณกิจกรรม '
								. $fmtNum($activityBudgetLimit) . ' บาท';
						}
					?>
						<tr class="pm-budget-activity-row"
							data-activity-id="<?= $actId ?>"
							data-budget-limit="<?= htmlspecialchars(number_format($activityBudgetLimit, 2, '.', ''), ENT_QUOTES, 'UTF-8') ?>"
							data-items-sum="<?= htmlspecialchars(number_format($activityMoneyTotal, 2, '.', ''), ENT_QUOTES, 'UTF-8') ?>">
							<td class="text-left">
								<?php
								$actNoShow = trim((string)($a['activity_no'] ?? ''));
								if ($actNoShow !== '' && is_numeric($actNoShow)) {
									$actNoShow = pm_fmt_budget_money($actNoShow, false);
								}
								?>
								<span class="pm-budget-activity-title">
									<?= htmlspecialchars($actNoShow) ?>. <?= htmlspecialchars((string)($a['activity_name'] ?? '')) ?>
								</span>
								<?php if (!$is_locked_project): ?>
									<button type="button" class="btn btn-sm btn-primary ml-2 pm-budget-addbtn" data-action="budget-items" data-activity-id="<?= $actId ?>" data-next-no="<?= (int)$next_no ?>">
										<i class="fa fa-plus mr-1"></i> เพิ่มรายการค่าใช้จ่าย
									</button>
								<?php endif ?>
							</td>
							<td class="text-center font-weight-bold<?= $budgetOver ? ' text-danger' : '' ?>"><?= $fmtNum($budgetCellVal) ?></td>
							<?php foreach ($monthCols as $mc): ?>
								<td class="text-center"><?= $fmt($activityPlanMonths[$mc] ?? 0) ?></td>
							<?php endforeach ?>
						</tr>

						<?php if (!empty($items)): ?>
							<?php foreach ($items as $it):
								$itemId = (int)($it['id'] ?? 0);
								$budgetItemsCount++;
								$itemPlan = isset($itemPlanMap[$itemId]) && is_array($itemPlanMap[$itemId]) ? $itemPlanMap[$itemId] : [];
								$itemPlanSum = 0.0;
								foreach ($monthCols as $mc) {
									$itemPlanSum += (float)($itemPlan[$mc] ?? 0);
								}
								$itemTotalVal = (float)($it['total'] ?? 0);
								$isNoExpenseItem = function_exists('pm_expense_category_id_is_no_expense')
									&& pm_expense_category_id_is_no_expense($db_Project, (string)($it['code_expenses'] ?? ''));
								if ($isNoExpenseItem) {
									$itemTotalVal = 0.0;
								}
								$budgetItemsMoneySum += $itemTotalVal;
								$planEpsilon = 0.05;
								// ครบ = รวมแผนรายเดือนเท่ากับยอดรายการ (ยอด 0 / ไม่มีค่าใช้จ่าย = ไม่ต้องกรอกแผน)
								$itemPlanComplete = ($itemTotalVal <= 0.0001) || $isNoExpenseItem
									|| (abs($itemPlanSum - $itemTotalVal) <= $planEpsilon);
								// โครงสร้างเก่า: แผนอยู่ระดับกิจกรรม — เทียบกับยอดรวมทุกรายการในกิจกรรม
								if (!$hasCodeActivityBudgetCol && !$isNoExpenseItem) {
									$itemPlanComplete = ($itemTotalVal <= 0.0001)
										|| (($activityMoneyTotal > 0.0001) && (abs($activityPlanTotal - $activityMoneyTotal) <= $planEpsilon));
								}
								$itemPlanMissing = ($itemTotalVal > 0.0001) && !$itemPlanComplete && !$isNoExpenseItem;
								$itemPlanEmpty = ($itemTotalVal > 0.0001) && ($itemPlanSum <= 0.0001)
									&& ($hasCodeActivityBudgetCol || $activityPlanTotal <= 0.0001)
									&& !$isNoExpenseItem;
								if ($itemPlanMissing) {
									$planMissingCount++;
								}
								// payload สำหรับเปิด modal แผน (รายรายการย่อย)
								$planPayload = [
									'activity_id' => $actId,
									'project_activity_budget_id' => $itemId,
									'project_budget_detail_id' => (int)($itemPlan['id'] ?? 0),
									'item_total' => (float)($it['total'] ?? 0),
									'mon_10' => $itemPlan['mon_10'] ?? 0, 'mon_11' => $itemPlan['mon_11'] ?? 0, 'mon_12' => $itemPlan['mon_12'] ?? 0,
									'mon_01' => $itemPlan['mon_01'] ?? 0, 'mon_02' => $itemPlan['mon_02'] ?? 0, 'mon_03' => $itemPlan['mon_03'] ?? 0,
									'mon_04' => $itemPlan['mon_04'] ?? 0, 'mon_05' => $itemPlan['mon_05'] ?? 0, 'mon_06' => $itemPlan['mon_06'] ?? 0,
									'mon_07' => $itemPlan['mon_07'] ?? 0, 'mon_08' => $itemPlan['mon_08'] ?? 0, 'mon_09' => $itemPlan['mon_09'] ?? 0,
								];
								$planJson = htmlspecialchars(json_encode($planPayload, JSON_UNESCAPED_UNICODE), ENT_QUOTES, 'UTF-8');
								$budgetDescVal = function_exists('pmProjectActivityBudgetDescValue')
									? pmProjectActivityBudgetDescValue($it, $budgetDescCol)
									: trim((string)($it['detail'] ?? $it['budget_item'] ?? ''));
								$it_name = '';
								if ($isNoExpenseItem && function_exists('getSetExpenses')) {
									$exCat = getSetExpenses($db_Project, (string)($it['code_expenses'] ?? ''));
									$it_name = trim((string)($exCat['name'] ?? ''));
								}
								if ($it_name === '' && !empty($it['code_expenses_detail']) && function_exists('getSetExpensesDetailByID')) {
									$exd = getSetExpensesDetailByID($db_Project, $it['code_expenses_detail']);
									$it_name = trim((string)($exd['name'] ?? ''));
								}
								if ($it_name === '') $it_name = '-';
								$itPayload = [
									'project_activity_budget_id' => (int)($it['id'] ?? 0),
									'project_activity_id' => $actId,
									'budget_no' => (string)($it['budget_no'] ?? ''),
									'code_expenses' => (string)($it['code_expenses'] ?? ''),
									'code_expenses_detail' => (string)($it['code_expenses_detail'] ?? ''),
									'budget_item' => $budgetDescVal,
									'price' => (string)($it['price'] ?? ''),
									'qty1' => (string)($it['qty1'] ?? ''),
									'unit1' => (string)($it['unit1'] ?? ''),
									'qty2' => (string)($it['qty2'] ?? ''),
									'unit2' => (string)($it['unit2'] ?? ''),
									'total' => (string)($it['total'] ?? ''),
								];
								$itJson = htmlspecialchars(json_encode($itPayload, JSON_UNESCAPED_UNICODE), ENT_QUOTES, 'UTF-8');
								$calcTxt = function_exists('pm_budget_item_calc_text')
									? pm_budget_item_calc_text(is_array($it) ? $it : [])
									: trim(
										($it['price'] ?? '') . ' บาท x ' .
										($it['qty1'] ?? '') . ' ' . ($it['unit1'] ?? '') .
										((!empty($it['qty2']) && (float)$it['qty2'] > 0) ? (' x ' . ($it['qty2'] ?? '') . ' ' . ($it['unit2'] ?? '')) : '')
									);
							?>
								<tr class="pm-budget-item-row<?= $itemPlanMissing ? ' pm-budget-plan-missing' : '' ?>" data-activity-id="<?= $actId ?>" data-item-id="<?= $itemId ?>" data-plan-missing="<?= $itemPlanMissing ? '1' : '0' ?>">
									<td class="text-left">
										<div class="pm-budget-item-name">
											<span class="pm-dot"></span>
											<?= htmlspecialchars($it_name) ?>
											<?php if ($budgetDescVal !== ''): ?>
												<span class="text-muted text-90"> (<?= htmlspecialchars($budgetDescVal) ?>)</span>
											<?php endif ?>
										</div>
										<?php if ($calcTxt !== '' && $calcTxt !== ' บาท x  '): ?>
											<div class="pm-budget-item-calc text-muted text-90"><?= htmlspecialchars($calcTxt) ?></div>
										<?php endif ?>
										<?php if (!$is_locked_project): ?>
											<button type="button" class="btn btn-link p-0 ml-2 pm-inline-act pm-inline-act-edit" title="แก้ไข" data-action="budget-item-edit" data-item="<?= $itJson ?>">
												<i class="fa fa-pen"></i>
											</button>
											<button type="button" class="btn btn-link p-0 ml-1 pm-inline-act pm-inline-act-del" title="ลบ" data-action="budget-item-del" data-id="<?= (int)($it['id'] ?? 0) ?>" data-activity-id="<?= $actId ?>">
												<i class="far fa-trash-alt"></i>
											</button>
										<?php endif ?>
									</td>
									<td class="text-center">
										<div class="font-weight-bold text-95<?= $itemPlanMissing ? ' pm-budget-total-incomplete' : ' pm-budget-total-complete' ?>"><?= $fmtNum($isNoExpenseItem ? 0 : ($it['total'] ?? 0)) ?></div>
										<?php if (!$is_locked_project && !$isNoExpenseItem && $itemTotalVal > 0.0001): ?>
											<button type="button" class="btn btn-sm mt-1 <?= $itemPlanMissing ? 'btn-warning text-dark' : 'btn-light' ?>" data-action="budget-plan" data-plan="<?= $planJson ?>" title="<?= $itemPlanMissing ? ($itemPlanEmpty ? 'ยังไม่ได้กรอกแผนการใช้จ่าย' : 'กรอกแผนการใช้จ่ายยังไม่ครบตามยอดรายการ') : 'แก้ไขแผนการใช้จ่าย' ?>">
												<i class="fa fa-calendar-alt mr-1"></i> แผนการใช้จ่าย<?= $itemPlanMissing ? ' *' : '' ?>
											</button>
											<?php if ($itemPlanMissing): ?>
												<div class="text-danger text-90 mt-1"><i class="fa fa-exclamation-circle"></i> <?= $itemPlanEmpty ? 'ยังไม่ได้กรอกแผน' : 'กรอกแผนยังไม่ครบ' ?></div>
											<?php endif ?>
										<?php elseif ($isNoExpenseItem || $itemTotalVal <= 0.0001): ?>
											<div class="text-muted text-90 mt-1">ไม่ต้องกรอกแผนการใช้จ่าย</div>
										<?php endif ?>
									</td>
									<?php foreach ($monthCols as $mc): ?>
										<td class="text-center"><?= $fmt($itemPlan[$mc] ?? 0) ?></td>
									<?php endforeach ?>
								</tr>
							<?php endforeach ?>
						<?php endif ?>
					<?php endforeach ?>
				<?php endif ?>
			</tbody>
		</table>
	</div>
	<?php
	$html = ob_get_clean();
	$jsonFlags = JSON_UNESCAPED_UNICODE;
	if (defined('JSON_INVALID_UTF8_SUBSTITUTE')) {
		$jsonFlags |= JSON_INVALID_UTF8_SUBSTITUTE;
	}
	if ($planMissingCount > 0) {
		array_unshift(
			$budgetWarnings,
			'กรุณากรอกแผนการใช้จ่ายให้ครบทุกรายการค่าใช้จ่าย โดยยอดแผนรายเดือนต้องเท่ากับยอดรายการ (ยังไม่ครบ ' . (int)$planMissingCount . ' รายการ) — ไม่สามารถส่งร่างโครงการได้จนกว่าจะกรอกครบ'
		);
	}
	$budgetWarningStr = !empty($budgetWarnings) ? implode(' | ', $budgetWarnings) : '';
	$allNoExpense = ($budgetItemsCount > 0 && $budgetItemsMoneySum <= 0.0001);
	echo json_encode([
		'ok' => 1,
		'html' => $html,
		'budget_warning' => $budgetWarningStr,
		'budget_items_count' => (int)$budgetItemsCount,
		'budget_money_sum' => (float)$budgetItemsMoneySum,
		'all_no_expense' => $allNoExpense ? 1 : 0,
	], $jsonFlags);
	exit;
	} catch (Throwable $e) {
		while (ob_get_level() > 0) {
			@ob_end_clean();
		}
		echo json_encode(['ok' => 0, 'msg' => 'โหลดไม่สำเร็จ: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// บันทึกตัวชี้วัดเป้าหมายโครงการผ่าน AJAX (ไม่โหลดหน้า)
if ($op === 'save_data_kpi_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');

	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$type = isset($_POST['type']) ? trim((string)$_POST['type']) : '';
	$project_kpi_id = isset($_POST['project_kpi_id']) ? (int)$_POST['project_kpi_id'] : 0;

	if ($project_id <= 0 || ($type !== 'insert' && $type !== 'update' && $type !== 'delete')) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);

	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !function_exists('staffCanEditPreProjectRichFields') || !staffCanEditPreProjectRichFields($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$toDec = function($v) {
		$v = trim((string)$v);
		if ($v === '') return 0;
		$v = str_replace(',', '', $v);
		if (!is_numeric($v)) return 0;
		return (float)$v;
	};
	$esc = function($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};

	// ตรวจ schema ตาราง project_kpi เพื่อรองรับ DB ที่ไม่มีบางคอลัมน์ (เช่น kpi_name)
	if (function_exists('ensureProjectKpiSchema')) {
		ensureProjectKpiSchema($db_Project);
	}
	$kpiCols = [];
	$colRes = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_kpi");
	if ($colRes) {
		while ($c = mysqli_fetch_assoc($colRes)) {
			if (!empty($c['Field'])) $kpiCols[(string)$c['Field']] = true;
		}
	}
	$hasCodeKpiCol  = isset($kpiCols['code_kpi']);
	$hasCodeUnitCol = isset($kpiCols['code_unit']);
	$hasKpiNameCol  = isset($kpiCols['kpi_name']);
	$hasKpiUnitCol  = isset($kpiCols['kpi_unit']);

	if ($type === 'delete') {
		if ($project_kpi_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการที่ต้องการลบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$pid = (int)$project_kpi_id;
		$ok = mysqli_query($db_Project, "UPDATE project_kpi SET status='99', staff_insert='".(int)$sid."', dates=NOW() WHERE id='".$pid."' LIMIT 1");
		echo json_encode(['ok' => $ok ? 1 : 0, 'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$kpi_name = trim((string)($_POST['kpi_name'] ?? ''));
	$kpi_unit = trim((string)($_POST['kpi_unit'] ?? ''));
	$code_kpi = trim((string)($_POST['code_kpi'] ?? '0'));
	$code_unit = trim((string)($_POST['code_unit'] ?? '0'));
	if ($code_kpi === '') $code_kpi = '0';
	if ($code_unit === '') $code_unit = '0';

	// validation ตาม schema จริง
	if (($hasKpiNameCol || !$hasCodeKpiCol) && $kpi_name === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกชื่อตัวชี้วัด'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (($hasKpiUnitCol || !$hasCodeUnitCol) && $kpi_unit === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกหน่วยนับ'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$kpi_weight = $toDec($_POST['kpi_weight'] ?? 0);
	$mon = [];
	for ($i = 1; $i <= 12; $i++) {
		$key = sprintf('mon_%02d', $i);
		$mon[$key] = $toDec($_POST[$key] ?? 0);
	}
	if ($type === 'insert') {
		$cols = ['code_pre_project'];
		$vals = ["'".(int)$project_id."'"];

		// KPI identifier/name columns (รองรับได้ทั้ง code_kpi หรือ kpi_name หรือมีทั้งคู่)
		if ($hasCodeKpiCol) { $cols[] = 'code_kpi'; $vals[] = "'".$esc($code_kpi)."'"; }
		if ($hasKpiNameCol) { $cols[] = 'kpi_name'; $vals[] = "'".$esc($kpi_name)."'"; }

		// Unit columns (รองรับได้ทั้ง code_unit หรือ kpi_unit หรือมีทั้งคู่)
		if ($hasCodeUnitCol) { $cols[] = 'code_unit'; $vals[] = "'".$esc($code_unit)."'"; }
		if ($hasKpiUnitCol) { $cols[] = 'kpi_unit'; $vals[] = "'".$esc($kpi_unit)."'"; }

		$monthCols = ['mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09','mon_10','mon_11','mon_12'];
		foreach ($monthCols as $mc) { $cols[] = $mc; $vals[] = "'".$esc($mon[$mc] ?? 0)."'"; }
		$cols[] = 'kpi_weight';   $vals[] = "'".$esc($kpi_weight)."'";
		$cols[] = 'status';       $vals[] = "'1'";
		$cols[] = 'dates';        $vals[] = "NOW()";
		$cols[] = 'staff_insert'; $vals[] = "'".(int)$sid."'";

		$sql = "INSERT INTO project_kpi(" . implode(',', $cols) . ") VALUES (" . implode(',', $vals) . ")";
		$ok = mysqli_query($db_Project, $sql);
		$id = $ok ? (int)mysqli_insert_id($db_Project) : 0;
		$weightWarning = ($ok && function_exists('pmValidateProjectKpiWeightTotal'))
			? pmValidateProjectKpiWeightTotal($db_Project, $project_id)
			: null;
		echo json_encode([
			'ok' => $ok ? 1 : 0,
			'id' => $id,
			'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ'),
			'weight_warning' => $weightWarning,
			'kpi_weight_sum' => function_exists('pmGetProjectKpiWeightSum') ? pmGetProjectKpiWeightSum($db_Project, $project_id) : null,
		], JSON_UNESCAPED_UNICODE);
		exit;
	}

	// update
	if ($project_kpi_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบรายการที่ต้องการแก้ไข'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$pid = (int)$project_kpi_id;
		$sets = [];
	if ($hasCodeKpiCol)  $sets[] = "code_kpi='".$esc($code_kpi)."'";
	if ($hasKpiNameCol)  $sets[] = "kpi_name='".$esc($kpi_name)."'";
	if ($hasCodeUnitCol) $sets[] = "code_unit='".$esc($code_unit)."'";
	if ($hasKpiUnitCol)  $sets[] = "kpi_unit='".$esc($kpi_unit)."'";
		$monthCols = ['mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09','mon_10','mon_11','mon_12'];
		foreach ($monthCols as $mc) {
			$sets[] = $mc."='".$esc($mon[$mc] ?? 0)."'";
		}
		$sets[] = "kpi_weight='".$esc($kpi_weight)."'";
		$sets[] = "staff_insert='".(int)$sid."'";
		$sets[] = "dates=NOW()";
		$sql = "UPDATE project_kpi SET " . implode(',', $sets) . " WHERE id='".$pid."' LIMIT 1";
	$ok = mysqli_query($db_Project, $sql);
	$weightWarning = ($ok && function_exists('pmValidateProjectKpiWeightTotal'))
		? pmValidateProjectKpiWeightTotal($db_Project, $project_id)
		: null;
	echo json_encode([
		'ok' => $ok ? 1 : 0,
		'id' => $pid,
		'msg' => $ok ? '' : (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ'),
		'weight_warning' => $weightWarning,
		'kpi_weight_sum' => function_exists('pmGetProjectKpiWeightSum') ? pmGetProjectKpiWeightSum($db_Project, $project_id) : null,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// บันทึกผลตัวชี้วัดโครงการ (กรอกผล) — AJAX หลายเดือน + อัปโหลดหลายไฟล์
if ($op === 'save_kpi_result_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$project_kpi_id = isset($_POST['project_kpi_id']) ? (int)$_POST['project_kpi_id'] : 0;
	$result_entries_raw = isset($_POST['result_entries']) ? (string)$_POST['result_entries'] : '';
	$legacy_result_detail = isset($_POST['result_detail']) ? trim((string)$_POST['result_detail']) : '';

	if ($project_id <= 0 || $project_kpi_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$allowedMonths = array_column(pm_kpi_result_month_options(), 'val');
	$entries = [];
	$decoded = json_decode($result_entries_raw, true);
	if (is_array($decoded)) {
		foreach ($decoded as $row) {
			if (!is_array($row)) {
				continue;
			}
			$entries[] = [
				'month' => trim((string)($row['month'] ?? '')),
				'amount' => trim((string)($row['amount'] ?? '')),
				'detail' => trim((string)($row['detail'] ?? '')),
				'file_key' => trim((string)($row['file_key'] ?? '')),
			];
		}
	}
	// รองรับฟอร์มเดิม (เดือนเดียว)
	if (empty($entries)) {
		$result_month = isset($_POST['result_month']) ? trim((string)$_POST['result_month']) : '';
		$result_amount_raw = isset($_POST['result_amount']) ? trim((string)$_POST['result_amount']) : '';
		if ($result_month !== '' || $result_amount_raw !== '') {
			$entries[] = [
				'month' => $result_month,
				'amount' => $result_amount_raw,
				'detail' => $legacy_result_detail,
				'file_key' => 'e0',
			];
		}
	}
	if (empty($entries)) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาเพิ่มอย่างน้อย 1 เดือน'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$usedMonths = [];
	$normalizedEntries = [];
	foreach ($entries as $idx => $entry) {
		$result_month = (string)($entry['month'] ?? '');
		$result_amount_raw = (string)($entry['amount'] ?? '');
		if ($result_month === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกเดือนในแถวที่ ' . ($idx + 1)], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (!in_array($result_month, $allowedMonths, true)) {
			echo json_encode(['ok' => 0, 'msg' => 'เดือนในแถวที่ ' . ($idx + 1) . ' ไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (isset($usedMonths[$result_month])) {
			echo json_encode(['ok' => 0, 'msg' => 'ห้ามเลือกเดือนซ้ำ (เดือนที่ ' . ($idx + 1) . ')'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($result_amount_raw === '' || !is_numeric($result_amount_raw)) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกจำนวนในแถวที่ ' . ($idx + 1)], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$result_amount = (float)$result_amount_raw;
		if ($result_amount < 0) {
			echo json_encode(['ok' => 0, 'msg' => 'จำนวนในแถวที่ ' . ($idx + 1) . ' ต้องไม่ติดลบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$usedMonths[$result_month] = true;
		$file_key = trim((string)($entry['file_key'] ?? ''));
		if ($file_key === '') {
			$file_key = 'e' . ($idx + 1);
		}
		$normalizedEntries[] = [
			'month' => $result_month,
			'amount' => $result_amount,
			'detail' => trim((string)($entry['detail'] ?? '')),
			'file_key' => $file_key,
		];
	}

	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์กรอกผลตัวชี้วัดโครงการนี้'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureKpiResultSchema')) {
		ensureKpiResultSchema($db_Project);
	}

	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};
	$kpiChk = @mysqli_query($db_Project, "SELECT id FROM project_kpi WHERE id='" . (int)$project_kpi_id . "' AND code_pre_project='" . (int)$project_id . "' AND status='1' LIMIT 1");
	if (!$kpiChk || mysqli_num_rows($kpiChk) === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบตัวชี้วัดของโครงการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	foreach ($normalizedEntries as $entry) {
		if (pm_kpi_result_month_exists($db_Project, $project_id, $project_kpi_id, (string)$entry['month'])) {
			$monLbl = pm_kpi_result_month_display((string)$entry['month'], (string)($_POST['years_select'] ?? ''));
			echo json_encode(['ok' => 0, 'msg' => 'เดือน ' . $monLbl . ' มีข้อมูลแล้ว — กรุณาแก้ไขจากรายการด้านล่าง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}

	$result_ids = [];
	$result_ids_by_key = [];
	foreach ($normalizedEntries as $entry) {
		$sqlIns = "INSERT INTO project_kpi_result (project_id, project_kpi_id, result_month, result_amount, result_detail, staff_insert, created_at, status)
			VALUES ('" . (int)$project_id . "', '" . (int)$project_kpi_id . "', '" . $esc($entry['month']) . "', '" . $esc((string)$entry['amount']) . "', '" . $esc($entry['detail']) . "', '" . (int)$sid . "', NOW(), '1')";
		if (!@mysqli_query($db_Project, $sqlIns)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกข้อมูลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$rid = (int)mysqli_insert_id($db_Project);
		if ($rid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกข้อมูลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$result_ids[] = $rid;
		$result_ids_by_key[$entry['file_key']] = $rid;
	}

	$allowedExt = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png', 'gif', 'webp'];
	$maxBytes = 30 * 1024 * 1024;
	$uploadDir = realpath(__DIR__ . '/../document/kpi_result_files');
	if ($uploadDir === false) {
		$uploadDir = __DIR__ . '/../document/kpi_result_files';
		if (!is_dir($uploadDir)) {
			@mkdir($uploadDir, 0775, true);
		}
		$uploadDir = realpath($uploadDir);
	}
	$fileCount = 0;
	$fileErrors = [];
	$saveKpiResultFile = function ($result_id, $name, $tmp, $err, $size, $fileIdx) use ($db_Project, $uploadDir, $allowedExt, $maxBytes, $esc, &$fileCount, &$fileErrors) {
		if ($name === '' || $err === UPLOAD_ERR_NO_FILE) {
			return;
		}
		if ($err !== UPLOAD_ERR_OK) {
			$fileErrors[] = $name . ' (อัปโหลดไม่สำเร็จ)';
			return;
		}
		if ($size <= 0 || $size > $maxBytes) {
			$fileErrors[] = $name . ' (ขนาดไฟล์ไม่เหมาะสม)';
			return;
		}
		$ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
		if (!in_array($ext, $allowedExt, true)) {
			$fileErrors[] = $name . ' (นามสกุลไม่อนุญาต)';
			return;
		}
		$base = preg_replace('/[^a-zA-Z0-9._\-]+/', '_', basename($name));
		if ($base === '' || $base === '.' || $base === '..') {
			$base = 'file.' . $ext;
		}
		$newName = time() . '_' . (int)$result_id . '_' . (int)$fileIdx . '_' . mt_rand(10000, 99999) . '_' . $base;
		$targetFile = $uploadDir . DIRECTORY_SEPARATOR . $newName;
		if (!@move_uploaded_file($tmp, $targetFile)) {
			$fileErrors[] = $name . ' (บันทึกไฟล์ไม่สำเร็จ)';
			return;
		}
		$sqlFile = "INSERT INTO project_kpi_result_file (result_id, original_name, stored_file, created_at, status)
			VALUES ('" . (int)$result_id . "', '" . $esc($name) . "', '" . $esc($newName) . "', NOW(), '1')";
		if (@mysqli_query($db_Project, $sqlFile)) {
			$fileCount++;
		} else {
			@unlink($targetFile);
			$fileErrors[] = $name . ' (บันทึกฐานข้อมูลไม่สำเร็จ)';
		}
	};
	if ($uploadDir && is_dir($uploadDir) && is_writable($uploadDir) && !empty($result_ids_by_key)) {
		$fileNamesRoot = $_FILES['result_files']['name'] ?? null;
		if (is_array($fileNamesRoot)) {
			$isGrouped = false;
			foreach (array_keys($fileNamesRoot) as $k) {
				if (!is_int($k) && $k !== 0) {
					$isGrouped = true;
					break;
				}
			}
			if ($isGrouped) {
				foreach ($fileNamesRoot as $fileKey => $names) {
					if (!is_array($names) || !isset($result_ids_by_key[$fileKey])) {
						continue;
					}
					$result_id = (int)$result_ids_by_key[$fileKey];
					for ($i = 0; $i < count($names); $i++) {
						$name = isset($_FILES['result_files']['name'][$fileKey][$i]) ? (string)$_FILES['result_files']['name'][$fileKey][$i] : '';
						$tmp = $_FILES['result_files']['tmp_name'][$fileKey][$i] ?? '';
						$err = (int)($_FILES['result_files']['error'][$fileKey][$i] ?? UPLOAD_ERR_NO_FILE);
						$size = (int)($_FILES['result_files']['size'][$fileKey][$i] ?? 0);
						$saveKpiResultFile($result_id, $name, $tmp, $err, $size, $i);
					}
				}
			} elseif (count($normalizedEntries) === 1) {
				$firstKey = (string)($normalizedEntries[0]['file_key'] ?? '');
				$result_id = (int)($result_ids_by_key[$firstKey] ?? $result_ids[0] ?? 0);
				if ($result_id > 0) {
					for ($i = 0; $i < count($fileNamesRoot); $i++) {
						$name = isset($_FILES['result_files']['name'][$i]) ? (string)$_FILES['result_files']['name'][$i] : '';
						$tmp = $_FILES['result_files']['tmp_name'][$i] ?? '';
						$err = (int)($_FILES['result_files']['error'][$i] ?? UPLOAD_ERR_NO_FILE);
						$size = (int)($_FILES['result_files']['size'][$i] ?? 0);
						$saveKpiResultFile($result_id, $name, $tmp, $err, $size, $i);
					}
				}
			}
		}
	}

	$entryCount = count($normalizedEntries);
	$msg = 'บันทึกผลตัวชี้วัด ' . $entryCount . ' เดือนสำเร็จ';
	if ($fileCount > 0) {
		$msg .= ' (แนบ ' . $fileCount . ' ไฟล์)';
	}
	if (!empty($fileErrors)) {
		$msg .= ' — บางไฟล์ข้าม: ' . implode(' ', $fileErrors);
	}
	echo json_encode([
		'ok' => 1,
		'msg' => $msg,
		'result_ids' => $result_ids,
		'entry_count' => $entryCount,
		'file_count' => $fileCount,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

