			if ($stored !== '' && $uploadDir) {
				$path = $uploadDir . DIRECTORY_SEPARATOR . $stored;
				if (is_file($path)) {
					@unlink($path);
				}
			}
		}
	}
	@mysqli_query($db_Project, "UPDATE project_kpi_result_file SET status='0' WHERE result_id='" . (int)$result_id . "'");
	@mysqli_query(
		$db_Project,
		"UPDATE project_kpi_result SET status='0'
		 WHERE id='" . (int)$result_id . "' AND project_id='" . (int)$project_id . "' LIMIT 1"
	);
	echo json_encode(['ok' => 1, 'msg' => 'ลบข้อมูลสำเร็จ'], JSON_UNESCAPED_UNICODE);
	exit;
}

// ดึงข้อมูลเบิกจ่ายสำหรับกรอกผลกิจกรรม
if ($op === 'get_activity_disbursement_ajax') {
