// บันทึกเดือนที่เกิดผลกิจกรรม (ติ๊กในตาราง)
if ($op === 'save_activity_result_months_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;
	$result_months_raw = isset($_POST['result_months']) ? (string)$_POST['result_months'] : '';

	if ($project_id <= 0 || $activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์กรอกผลกิจกรรม'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureActivityResultSchema')) {
		ensureActivityResultSchema($db_Project);
	}

	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};

	$actChk = @mysqli_query(
		$db_Project,
		"SELECT id FROM project_activity WHERE id='" . (int)$activity_id . "' AND code_pre_project='" . (int)$project_id . "' AND status='1' LIMIT 1"
	);
	if (!$actChk || mysqli_num_rows($actChk) === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบกิจกรรมของโครงการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$months = pm_parse_activity_result_months_input($result_months_raw);
	$monthSqlSet = pm_activity_result_months_sql_set($months, $esc);

	$result_id = 0;
	$existQ = @mysqli_query(
		$db_Project,
		"SELECT id FROM project_activity_result WHERE project_id='" . (int)$project_id . "' AND project_activity_id='" . (int)$activity_id . "' AND status='1' ORDER BY id DESC LIMIT 1"
	);
	if ($existQ && ($existRow = mysqli_fetch_assoc($existQ))) {
		$result_id = (int)($existRow['id'] ?? 0);
	}

	if ($result_id > 0) {
		$sqlUp = "UPDATE project_activity_result SET " . $monthSqlSet . ", staff_insert='" . (int)$sid . "', updated_at=NOW() WHERE id='" . (int)$result_id . "' LIMIT 1";
		if (!@mysqli_query($db_Project, $sqlUp)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกเดือนที่เกิดผลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	} else {
		$sqlIns = "INSERT INTO project_activity_result (project_id, project_activity_id, result_detail, progress_percent, staff_insert, created_at, status, " . implode(', ', pm_activity_month_cols()) . ")
			VALUES ('" . (int)$project_id . "', '" . (int)$activity_id . "', '', NULL, '" . (int)$sid . "', NOW(), '1', " . implode(', ', array_map(function ($mc) use ($months, $esc) {
				return "'" . $esc((string)(int)($months[$mc] ?? 0)) . "'";
			}, pm_activity_month_cols())) . ")";
		if (!@mysqli_query($db_Project, $sqlIns)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกเดือนที่เกิดผลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$result_id = (int)mysqli_insert_id($db_Project);
	}

	echo json_encode([
		'ok' => 1,
		'result_id' => $result_id,
		'months' => $months,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// บันทึกผลกิจกรรม (ส่วนที่ 4)
if ($op === 'save_activity_result_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$activity_id = isset($_POST['project_activity_id']) ? (int)$_POST['project_activity_id'] : 0;
	$result_detail = isset($_POST['result_detail']) ? trim((string)$_POST['result_detail']) : '';
	$progress_percent_raw = isset($_POST['progress_percent']) ? trim((string)$_POST['progress_percent']) : '';
	$target_results_raw = isset($_POST['target_results']) ? (string)$_POST['target_results'] : '';
	$result_months_raw = isset($_POST['result_months']) ? (string)$_POST['result_months'] : '';

	if ($project_id <= 0 || $activity_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !staffCanFillKpiProjectResult($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์กรอกผลกิจกรรม'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	if (function_exists('ensureActivityResultSchema')) {
		ensureActivityResultSchema($db_Project);
	}

	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};

	$actChk = @mysqli_query(
		$db_Project,
		"SELECT id FROM project_activity WHERE id='" . (int)$activity_id . "' AND code_pre_project='" . (int)$project_id . "' AND status='1' LIMIT 1"
	);
	if (!$actChk || mysqli_num_rows($actChk) === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบกิจกรรมของโครงการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	if ($progress_percent_raw === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอก % ดำเนินการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if ($result_detail === '') {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกรายละเอียดการดำเนินการ'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$progress_percent = null;
	if (!is_numeric($progress_percent_raw)) {
		echo json_encode(['ok' => 0, 'msg' => '% ดำเนินการต้องเป็นตัวเลข'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$progress_percent = (float)$progress_percent_raw;
	if ($progress_percent < 0) {
		echo json_encode(['ok' => 0, 'msg' => '% ดำเนินการต้องไม่ติดลบ'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if ($progress_percent > 100) {
		echo json_encode(['ok' => 0, 'msg' => '% ดำเนินการต้องไม่เกิน 100'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$progress_percent = round($progress_percent, 2);

	$planTargetCodes = [];
	if (function_exists('getProjectActivityTargetList')) {
		foreach (getProjectActivityTargetList($db_Project, $activity_id) as $pt) {
			$code = trim((string)($pt['code_target'] ?? ''));
			if ($code !== '') {
				$planTargetCodes[] = $code;
			}
		}
	}

	$targetRows = [];
	$targetResultMap = [];
	$decodedTargets = json_decode($target_results_raw, true);
	if (is_array($decodedTargets)) {
		foreach ($decodedTargets as $tr) {
			if (!is_array($tr)) {
				continue;
			}
			$code = trim((string)($tr['code_target'] ?? ''));
			if ($code === '') {
				continue;
			}
			$amtRaw = trim((string)($tr['result_amount'] ?? ''));
			$targetResultMap[$code] = $amtRaw;
			if ($amtRaw === '' || !is_numeric($amtRaw)) {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผลกลุ่มเป้าหมายให้ครบทุกรายการ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$amt = (float)$amtRaw;
			if ($amt < 0) {
				echo json_encode(['ok' => 0, 'msg' => 'ผลกลุ่มเป้าหมายต้องไม่ติดลบ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$targetRows[] = ['code_target' => $code, 'result_amount' => $amt];
		}
	}
	foreach ($planTargetCodes as $planCode) {
		if (!array_key_exists($planCode, $targetResultMap)) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผลกลุ่มเป้าหมายให้ครบทุกรายการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}

	$months = pm_parse_activity_result_months_input($result_months_raw);
	$hasResultMonth = false;
	foreach ($months as $mv) {
		if (!empty($mv)) {
			$hasResultMonth = true;
			break;
		}
	}
	if (!$hasResultMonth) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาทำเครื่องหมาย X ในเดือนที่ดำเนินการอย่างน้อย 1 เดือน'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$monthSqlSet = pm_activity_result_months_sql_set($months, $esc);

	$result_id = 0;
	$isUpdate = false;
	$existQ = @mysqli_query(
		$db_Project,
		"SELECT id FROM project_activity_result WHERE project_id='" . (int)$project_id . "' AND project_activity_id='" . (int)$activity_id . "' AND status='1' ORDER BY id DESC LIMIT 1"
	);
	if ($existQ && ($existRow = mysqli_fetch_assoc($existQ))) {
		$result_id = (int)($existRow['id'] ?? 0);
		$isUpdate = ($result_id > 0);
	}

	if ($result_id > 0) {
		$progressSql = ($progress_percent === null) ? 'NULL' : ("'" . $esc((string)$progress_percent) . "'");
		$sqlUp = "UPDATE project_activity_result SET result_detail='" . $esc($result_detail) . "', progress_percent=" . $progressSql . ", " . $monthSqlSet . ", staff_insert='" . (int)$sid . "', updated_at=NOW() WHERE id='" . (int)$result_id . "' LIMIT 1";
		if (!@mysqli_query($db_Project, $sqlUp)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกข้อมูลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query($db_Project, "UPDATE project_activity_result_target SET status='0' WHERE result_id='" . (int)$result_id . "'");
	} else {
		$progressSql = ($progress_percent === null) ? 'NULL' : ("'" . $esc((string)$progress_percent) . "'");
		$monthCols = pm_activity_month_cols();
		$monthVals = [];
		foreach ($monthCols as $mc) {
			$monthVals[] = "'" . $esc((string)(int)($months[$mc] ?? 0)) . "'";
		}
		$sqlIns = "INSERT INTO project_activity_result (project_id, project_activity_id, result_detail, progress_percent, staff_insert, created_at, status, " . implode(', ', $monthCols) . ")
			VALUES ('" . (int)$project_id . "', '" . (int)$activity_id . "', '" . $esc($result_detail) . "', " . $progressSql . ", '" . (int)$sid . "', NOW(), '1', " . implode(', ', $monthVals) . ")";
		if (!@mysqli_query($db_Project, $sqlIns)) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกข้อมูลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$result_id = (int)mysqli_insert_id($db_Project);
		if ($result_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกข้อมูลไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
	}

	foreach ($targetRows as $tr) {
		$sqlT = "INSERT INTO project_activity_result_target (result_id, code_target, result_amount, status)
			VALUES ('" . (int)$result_id . "', '" . $esc($tr['code_target']) . "', '" . $esc((string)$tr['result_amount']) . "', '1')";
		@mysqli_query($db_Project, $sqlT);
	}

	$allowedExt = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png', 'gif', 'webp'];
	$maxBytes = 30 * 1024 * 1024;
	$uploadDir = realpath(__DIR__ . '/../document/activity_result_files');
	if ($uploadDir === false) {
		$uploadDir = __DIR__ . '/../document/activity_result_files';
		if (!is_dir($uploadDir)) {
			@mkdir($uploadDir, 0775, true);
		}
		$uploadDir = realpath($uploadDir);
	}
	$fileCount = 0;
	$fileErrors = [];
	if ($uploadDir && is_dir($uploadDir) && is_writable($uploadDir) && isset($_FILES['result_files'])) {
		$fileNames = $_FILES['result_files']['name'] ?? null;
		if (is_array($fileNames)) {
			for ($i = 0; $i < count($fileNames); $i++) {
				$name = isset($_FILES['result_files']['name'][$i]) ? (string)$_FILES['result_files']['name'][$i] : '';
				$tmp = $_FILES['result_files']['tmp_name'][$i] ?? '';
				$err = (int)($_FILES['result_files']['error'][$i] ?? UPLOAD_ERR_NO_FILE);
				$size = (int)($_FILES['result_files']['size'][$i] ?? 0);
				if ($name === '' || $err === UPLOAD_ERR_NO_FILE) {
					continue;
				}
				if ($err !== UPLOAD_ERR_OK) {
					$fileErrors[] = $name . ' (อัปโหลดไม่สำเร็จ)';
					continue;
				}
				if ($size <= 0 || $size > $maxBytes) {
					$fileErrors[] = $name . ' (ขนาดไฟล์ไม่เหมาะสม)';
					continue;
				}
				$ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
				if (!in_array($ext, $allowedExt, true)) {
					$fileErrors[] = $name . ' (นามสกุลไม่อนุญาต)';
					continue;
				}
				$base = preg_replace('/[^a-zA-Z0-9._\-]+/', '_', basename($name));
				if ($base === '' || $base === '.' || $base === '..') {
					$base = 'file.' . $ext;
				}
				$newName = time() . '_' . (int)$result_id . '_' . (int)$i . '_' . mt_rand(10000, 99999) . '_' . $base;
				$targetFile = $uploadDir . DIRECTORY_SEPARATOR . $newName;
				if (!@move_uploaded_file($tmp, $targetFile)) {
					$fileErrors[] = $name . ' (บันทึกไฟล์ไม่สำเร็จ)';
					continue;
				}
				$sqlFile = "INSERT INTO project_activity_result_file (result_id, original_name, stored_file, created_at, status)
					VALUES ('" . (int)$result_id . "', '" . $esc($name) . "', '" . $esc($newName) . "', NOW(), '1')";
				if (@mysqli_query($db_Project, $sqlFile)) {
					$fileCount++;
				} else {
					@unlink($targetFile);
					$fileErrors[] = $name . ' (บันทึกฐานข้อมูลไม่สำเร็จ)';
				}
			}
		}
	}

	$msg = $isUpdate ? 'บันทึก/แก้ไขผลกิจกรรมสำเร็จ' : 'บันทึกผลกิจกรรมสำเร็จ';
	if ($fileCount > 0) {
		$msg .= ' (แนบ ' . $fileCount . ' ไฟล์)';
	}
	if (!empty($fileErrors)) {
		$msg .= ' — บางไฟล์ข้าม: ' . implode(' ', $fileErrors);
	}
	echo json_encode([
		'ok' => 1,
		'msg' => $msg,
		'result_id' => $result_id,
		'file_count' => $fileCount,
	], JSON_UNESCAPED_UNICODE);
	exit;
}

// ลบไฟล์แนบผลกิจกรรม
if ($op === 'delete_activity_result_file_ajax') {
