		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขผลกิจกรรม'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	$chk = @mysqli_query(
		$db_Project,
		"SELECT f.id, f.stored_file FROM project_activity_result_file f
		 INNER JOIN project_activity_result r ON r.id = f.result_id
		 WHERE f.id='" . (int)$file_id . "' AND r.project_id='" . (int)$project_id . "' AND f.status='1' LIMIT 1"
	);
	if (!$chk || mysqli_num_rows($chk) === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่พบไฟล์'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$row = mysqli_fetch_assoc($chk);
	$stored = trim((string)($row['stored_file'] ?? ''));
	$uploadDir = realpath(__DIR__ . '/../document/activity_result_files');
	if ($stored !== '' && $uploadDir) {
		$path = $uploadDir . DIRECTORY_SEPARATOR . $stored;
		if (is_file($path)) {
			@unlink($path);
		}
	}
	@mysqli_query($db_Project, "UPDATE project_activity_result_file SET status='0' WHERE id='" . (int)$file_id . "' LIMIT 1");
	echo json_encode(['ok' => 1, 'msg' => 'ลบไฟล์สำเร็จ'], JSON_UNESCAPED_UNICODE);
	exit;
}

