// บันทึก Section 2 (reson, result, objective, target_project) + detail ผ่าน AJAX
if ($op === 'save_section2_field') {
	try {
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	$field = isset($_POST['field']) ? trim((string)$_POST['field']) : '';
		$allowed = [
			'reson', 'result', 'objective', 'target_project', 'detail', 'midyear_reason',
			// ส่วนที่ 6
			'follow_method', 'follow_tools', 'risk_expected', 'risk_prevent',
			'evaluate_type', 'evaluate_tool', 'risk_action', 'risk_stop'
		];
	if ($project_id <= 0 || !in_array($field, $allowed, true)) {
			pm_json_exit(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง']);
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			pm_json_exit(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้']);
		}
		$status_now = pm_get_project_status_now($db_Project, $project_id);
		$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
		if (!pm_can_edit_full_or_plan($status_now, $notify_result_now, function_exists('pm_get_project_user_fix_note') ? pm_get_project_user_fix_note($db_Project, $project_id) : '')) {
			pm_json_exit(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไข']);
		}
		if (pm_plan_restricts_like_user($status_now, $notify_result_now) && !in_array($field, ['reson', 'result', 'midyear_reason'], true)) {
			pm_json_exit(['ok' => 0, 'msg' => 'โหมดแผนปฏิบัติการ แก้ไขได้เฉพาะหลักการและเหตุผล/ทบทวนผลเดิม']);
		}
		$value = isset($_POST['value']) ? (string)$_POST['value'] : '';
		$sql = 'UPDATE pre_project SET `' . $field . '` = ? WHERE id = ? LIMIT 1';
		$stmt = mysqli_prepare($db_Project, $sql);
		if (!$stmt) {
			// ถ้าคอลัมน์ยังไม่มี ให้สร้างคอลัมน์แล้วลองใหม่ (รองรับหลาย field)
			@mysqli_query($db_Project, "ALTER TABLE pre_project ADD COLUMN `".$field."` TEXT NULL");
			$stmt = mysqli_prepare($db_Project, $sql);
			if (!$stmt) {
				pm_json_exit(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'เตรียมคำสั่ง SQL ไม่สำเร็จ')]);
			}
		}
		mysqli_stmt_bind_param($stmt, 'si', $value, $project_id);
		$ok = mysqli_stmt_execute($stmt);
		if (!$ok) {
			$em = mysqli_stmt_error($stmt);
			pm_json_exit(['ok' => 0, 'msg' => $em !== '' ? $em : 'บันทึกไม่สำเร็จ']);
		}
		pm_json_exit(['ok' => 1, 'msg' => 'บันทึกสำเร็จ']);
	} catch (Throwable $e) {
		pm_json_exit(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()]);
	}
}

// บันทึก Section 6 แบบ 2 ช่อง/ชุด ผ่าน AJAX
if ($op === 'save_section6_fields') {
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$group = isset($_POST['group']) ? trim((string)$_POST['group']) : '';
		$fields = $_POST['fields'] ?? null;

		if ($project_id <= 0 || ($group !== 'evaluate' && $group !== 'risk') || !is_array($fields)) {
			pm_json_exit(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง']);
		}
		pm_exit_if_result_report_edit_blocked($db_Project, $project_id);

		$allowedByGroup = [
			'evaluate' => ['evaluate_type', 'evaluate_tool'],
			'risk' => ['risk_action', 'risk_stop'],
		];
		$allowedFields = $allowedByGroup[$group] ?? [];

		// permission
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
	if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			pm_json_exit(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้']);
		}
	$status_now = pm_get_project_status_now($db_Project, $project_id);
	$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
	if (!pm_can_edit_full_or_plan($status_now, $notify_result_now, function_exists('pm_get_project_user_fix_note') ? pm_get_project_user_fix_note($db_Project, $project_id) : '')) {
		pm_json_exit(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไข']);
	}

		// ensure columns exist (avoid duplicate column)
		$preCols = [];
		$colRes = @mysqli_query($db_Project, "SHOW COLUMNS FROM pre_project");
		if ($colRes) {
			while ($c = mysqli_fetch_assoc($colRes)) {
				if (!empty($c['Field'])) $preCols[(string)$c['Field']] = true;
			}
		}
		foreach ($allowedFields as $f) {
			if (isset($preCols[$f])) continue;
			@mysqli_query($db_Project, "ALTER TABLE pre_project ADD COLUMN `".$f."` TEXT NULL");
		}

		$emptyS6 = [];
		foreach ($allowedFields as $f) {
			$chkVal = trim(strip_tags((string)($fields[$f] ?? '')));
			if ($chkVal === '') {
				$emptyS6[] = $f;
			}
		}
		if (!empty($emptyS6)) {
			pm_json_exit(['ok' => 0, 'msg' => 'กรุณากรอกทั้ง 2 ช่องให้ครบ']);
		}

		@mysqli_begin_transaction($db_Project);
		foreach ($allowedFields as $f) {
			if (pm_plan_restricts_like_user($status_now, $notify_result_now) && !in_array($f, ['reson', 'result'], true)) {
				continue;
			}
			$val = isset($fields[$f]) ? (string)$fields[$f] : '';
			$sql = 'UPDATE pre_project SET `'.$f.'` = ? WHERE id = ? LIMIT 1';
			$stmt = mysqli_prepare($db_Project, $sql);
			if (!$stmt) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมคำสั่ง SQL ไม่สำเร็จ');
			mysqli_stmt_bind_param($stmt, 'si', $val, $project_id);
			$ok = mysqli_stmt_execute($stmt);
			if (!$ok) throw new Exception(mysqli_stmt_error($stmt) ?: 'บันทึกไม่สำเร็จ');
		}
		@mysqli_commit($db_Project);
		pm_json_exit(['ok' => 1, 'msg' => 'บันทึกสำเร็จ']);
	} catch (Throwable $e) {
		@mysqli_rollback($db_Project);
		pm_json_exit(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: '.$e->getMessage()]);
	}
}

