		$notify_result_now = pm_get_project_notify_result($db_Project, $project_id);
		if (!pm_can_edit_full_or_plan($status_now, $notify_result_now, function_exists('pm_get_project_user_fix_note') ? pm_get_project_user_fix_note($db_Project, $project_id) : '')) {
			pm_json_exit(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไข']);
		}

		$head_staff = (int)($_POST['head_staff'] ?? 0);
		$head_phone = trim((string)($_POST['head_phone'] ?? ''));
		$coord_staff = (int)($_POST['coordinator_staff'] ?? 0);
		$coord_phone = trim((string)($_POST['coordinator_phone'] ?? ''));
		$code_unit = trim((string)($_POST['code_unit'] ?? ''));
		$code_nature = trim((string)($_POST['code_nature'] ?? ''));
		$code_type = trim((string)($_POST['code_type'] ?? ''));
		$code_budget = trim((string)($_POST['code_budget'] ?? '99'));
		$budget_other = trim((string)($_POST['budget_other'] ?? ''));
		$start_month = trim((string)($_POST['start_month'] ?? ''));
		$start_year = trim((string)($_POST['start_year'] ?? ''));
		$end_month = trim((string)($_POST['end_month'] ?? ''));
		$end_year = trim((string)($_POST['end_year'] ?? ''));
		$start_date_text = trim((string)($_POST['start_date_text'] ?? ''));
		$end_date_text = trim((string)($_POST['end_date_text'] ?? ''));
		$location = trim((string)($_POST['location'] ?? ''));
		$general_note = trim((string)($_POST['general_note'] ?? ''));
		if (function_exists('pm_ensure_general_note_schema')) {
			pm_ensure_general_note_schema($db_Project);
		}

		// fallback: บางครั้ง datepicker อาจไม่อัปเดต hidden fields แต่มี text (mm/yyyy) อยู่
		$parseMonthYear = function(string $txt): array {
			$txt = trim($txt);
			if ($txt === '') return ['', ''];
			if (!preg_match('/^\s*(\d{1,2})\s*\/\s*(\d{4})\s*$/', $txt, $m)) return ['', ''];
			$mm = (int)$m[1];
			$yy = (int)$m[2];
			if ($mm < 1 || $mm > 12) return ['', ''];
			return [(string)$mm, (string)$yy];
		};
		if (($start_month === '' || $start_year === '') && $start_date_text !== '') {
			[$sm2, $sy2] = $parseMonthYear($start_date_text);
			if ($sm2 !== '' && $sy2 !== '') { $start_month = $sm2; $start_year = $sy2; }
		}
		if (($end_month === '' || $end_year === '') && $end_date_text !== '') {
			[$em2, $ey2] = $parseMonthYear($end_date_text);
			if ($em2 !== '' && $ey2 !== '') { $end_month = $em2; $end_year = $ey2; }
		}

		// บังคับเก็บปีเป็น พ.ศ.
		if ($start_year !== '' && ctype_digit($start_year) && (int)$start_year > 0 && (int)$start_year < 2400) {
			$start_year = (string)((int)$start_year + 543);
		}
		if ($end_year !== '' && ctype_digit($end_year) && (int)$end_year > 0 && (int)$end_year < 2400) {
			$end_year = (string)((int)$end_year + 543);
		}
		$sm = (int) $start_month;
		$sy = (int) $start_year;
		$em = (int) $end_month;
		$ey = (int) $end_year;
		if ($sm >= 1 && $sm <= 12 && $sy > 0 && $em >= 1 && $em <= 12 && $ey > 0) {
			if (($ey * 12 + $em) < ($sy * 12 + $sm)) {
				pm_json_exit(['ok' => 0, 'msg' => 'เดือน/ปี สิ้นสุดต้องไม่น้อยกว่าเดือน/ปี เริ่มต้น']);
			}
		}

		$participant_staffs = $_POST['participant_staff'] ?? [];
		$participant_phones = $_POST['participant_phone'] ?? [];
		$unit_cos = $_POST['code_unit_co'] ?? [];
		$unit_co_others = $_POST['code_unit_co_other'] ?? [];
		if (!is_array($participant_staffs)) $participant_staffs = [];
		if (!is_array($participant_phones)) $participant_phones = [];
		if (!is_array($unit_cos)) $unit_cos = [];
		if (!is_array($unit_co_others)) $unit_co_others = [];
		$code_budget = '99';

		@mysqli_begin_transaction($db_Project);

		// pre_project fields
		if (pm_plan_restricts_like_user($status_now, $notify_result_now)) {
			// โหมดแผนปฏิบัติการ: เดิมล็อกไว้เฉพาะ "พื้นที่ดำเนินโครงการ"
			// แต่ฟิลด์ "ระยะเวลาดำเนินโครงการ" (เดือน/ปี เริ่มต้น-สิ้นสุด) ต้องบันทึกได้ตาม requirement ล่าสุด
			$stmtPre = mysqli_prepare($db_Project, "UPDATE pre_project SET start_month=?, start_year=?, end_month=?, end_year=?, location=?, general_note=?, dates=NOW(), staff_insert=? WHERE id=? LIMIT 1");
			if (!$stmtPre) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมคำสั่งไม่สำเร็จ');
			mysqli_stmt_bind_param($stmtPre, 'ssssssii', $start_month, $start_year, $end_month, $end_year, $location, $general_note, $sid, $project_id);
			if (!mysqli_stmt_execute($stmtPre)) throw new Exception(mysqli_stmt_error($stmtPre) ?: 'บันทึกข้อมูลโครงการไม่สำเร็จ');
		} else {
			$stmtPre = mysqli_prepare($db_Project, "UPDATE pre_project SET code_unit=?, code_nature=?, code_type=?, start_month=?, start_year=?, end_month=?, end_year=?, location=?, general_note=?, dates=NOW(), staff_insert=? WHERE id=? LIMIT 1");
			if (!$stmtPre) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมคำสั่งไม่สำเร็จ');
			mysqli_stmt_bind_param($stmtPre, 'sssssssssii', $code_unit, $code_nature, $code_type, $start_month, $start_year, $end_month, $end_year, $location, $general_note, $sid, $project_id);
			if (!mysqli_stmt_execute($stmtPre)) throw new Exception(mysqli_stmt_error($stmtPre) ?: 'บันทึกข้อมูลโครงการไม่สำเร็จ');
		}

		// project_head: keep one active row
		if (!pm_plan_restricts_like_user($status_now, $notify_result_now)) {
			@mysqli_query($db_Project, "UPDATE project_head SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE project_id='".(int)$project_id."' AND status!='99'");
			if ($head_staff > 0 || $head_phone !== '') {
				$sth = mysqli_prepare($db_Project, "INSERT INTO project_head (project_id, staff_project, phone, status, dates, staff_insert) VALUES (?, ?, ?, '1', NOW(), ?)");
				if (!$sth) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมบันทึกหัวหน้าโครงการไม่สำเร็จ');
				mysqli_stmt_bind_param($sth, 'iisi', $project_id, $head_staff, $head_phone, $sid);
				if (!mysqli_stmt_execute($sth)) throw new Exception(mysqli_stmt_error($sth) ?: 'บันทึกหัวหน้าโครงการไม่สำเร็จ');
			}
		}

		// project_staff (coordinator): keep one active row
		@mysqli_query($db_Project, "UPDATE project_staff SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE project_id='".(int)$project_id."' AND status!='99'");
		if ($coord_staff > 0 || $coord_phone !== '') {
			$sts = mysqli_prepare($db_Project, "INSERT INTO project_staff (project_id, staff_project, phone, status, dates, staff_insert) VALUES (?, ?, ?, '1', NOW(), ?)");
			if (!$sts) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมบันทึกผู้ประสานงานไม่สำเร็จ');
			mysqli_stmt_bind_param($sts, 'iisi', $project_id, $coord_staff, $coord_phone, $sid);
			if (!mysqli_stmt_execute($sts)) throw new Exception(mysqli_stmt_error($sts) ?: 'บันทึกผู้ประสานงานไม่สำเร็จ');
		}

		// project_person (participants): rewrite active rows
		if (!pm_plan_restricts_like_user($status_now, $notify_result_now)) {
			@mysqli_query($db_Project, "UPDATE project_person SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE project_id='".(int)$project_id."' AND status!='99'");
			$maxP = max(count($participant_staffs), count($participant_phones));
			for ($i = 0; $i < $maxP; $i++) {
				$ps = (int)($participant_staffs[$i] ?? 0);
				$pp = trim((string)($participant_phones[$i] ?? ''));
				if ($ps <= 0 && $pp === '') continue;
				$stp = mysqli_prepare($db_Project, "INSERT INTO project_person (project_id, staff_project, phone, status, dates, staff_insert) VALUES (?, ?, ?, '1', NOW(), ?)");
				if (!$stp) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมบันทึกผู้ร่วมโครงการไม่สำเร็จ');
				mysqli_stmt_bind_param($stp, 'iisi', $project_id, $ps, $pp, $sid);
				if (!mysqli_stmt_execute($stp)) throw new Exception(mysqli_stmt_error($stp) ?: 'บันทึกผู้ร่วมโครงการไม่สำเร็จ');
			}
		}

		// project_department level=1 (co-units): rewrite active rows
		if (!pm_plan_restricts_like_user($status_now, $notify_result_now)) {
			@mysqli_query($db_Project, "UPDATE project_department SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE project_id='".(int)$project_id."' AND level='1' AND status!='99'");
			$maxD = max(count($unit_cos), count($unit_co_others));
			for ($i = 0; $i < $maxD; $i++) {
				$u = trim((string)($unit_cos[$i] ?? ''));
				$uOther = trim((string)($unit_co_others[$i] ?? ''));
				if ($u === '') continue;
				$depVal = ($u === '99') ? $uOther : $u;
				if ($depVal === '') continue;
				$std = mysqli_prepare($db_Project, "INSERT INTO project_department (project_id, department_project, level, status, dates, staff_insert) VALUES (?, ?, '1', '1', NOW(), ?)");
				if (!$std) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมบันทึกหน่วยงานร่วมไม่สำเร็จ');
				mysqli_stmt_bind_param($std, 'isi', $project_id, $depVal, $sid);
				if (!mysqli_stmt_execute($std)) throw new Exception(mysqli_stmt_error($std) ?: 'บันทึกหน่วยงานร่วมไม่สำเร็จ');
			}
		}

		// project_budget: keep one active row
		if (!pm_plan_restricts_like_user($status_now, $notify_result_now)) {
			@mysqli_query($db_Project, "UPDATE project_budget SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE project_id='".(int)$project_id."' AND status!='99'");
			if ($budget_other !== '') {
				$stb = mysqli_prepare($db_Project, "INSERT INTO project_budget (project_id, code_budget, budget_other, status, dates, staff_insert) VALUES (?, ?, ?, '1', NOW(), ?)");
				if (!$stb) throw new Exception(mysqli_error($db_Project) ?: 'เตรียมบันทึกแหล่งงบไม่สำเร็จ');
				mysqli_stmt_bind_param($stb, 'issi', $project_id, $code_budget, $budget_other, $sid);
				if (!mysqli_stmt_execute($stb)) throw new Exception(mysqli_stmt_error($stb) ?: 'บันทึกแหล่งงบไม่สำเร็จ');
			}
		}

		@mysqli_commit($db_Project);
		$chk = @mysqli_query(
			$db_Project,
			"SELECT start_month, start_year, end_month, end_year FROM pre_project WHERE id='" . (int)$project_id . "' LIMIT 1"
		);
		$chkRow = $chk ? mysqli_fetch_assoc($chk) : null;
		pm_json_exit([
			'ok' => 1,
			'msg' => 'บันทึกสำเร็จ',
			'posted' => [
				'start_month' => $start_month,
				'start_year' => $start_year,
				'end_month' => $end_month,
				'end_year' => $end_year,
			],
			'saved' => [
				'start_month' => (string)($chkRow['start_month'] ?? ''),
				'start_year' => (string)($chkRow['start_year'] ?? ''),
				'end_month' => (string)($chkRow['end_month'] ?? ''),
				'end_year' => (string)($chkRow['end_year'] ?? ''),
			],
		]);
	} catch (Throwable $e) {
		@mysqli_rollback($db_Project);
		pm_json_exit(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: '.$e->getMessage()]);
	}
}

if ($op === 'save_midyear_reason_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		if (function_exists('pm_ensure_midyear_schema')) {
			pm_ensure_midyear_schema($db_Project);
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$reason = isset($_POST['midyear_reason']) ? trim((string)$_POST['midyear_reason']) : '';
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาบันทึกโครงการก่อน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_exit_if_project_plan_closed')) {
			pm_exit_if_project_plan_closed($db_Project, $project_id);
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$chk = @mysqli_query($db_Project, "SELECT id, midyear_request, status_project FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $chk ? mysqli_fetch_assoc($chk) : null;
		if (!$row || (int)($row['midyear_request'] ?? 0) !== 1) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่ใช่โครงการยื่นระหว่างปี'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stNow = (string)($row['status_project'] ?? '');
		if (!in_array($stNow, ['0', '8'], true) && !(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'สถานะโครงการนี้ไม่อนุญาตให้แก้ไขเหตุผล'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$esc = mysqli_real_escape_string($db_Project, $reason);
		$ok = @mysqli_query($db_Project, "UPDATE pre_project SET midyear_reason='" . $esc . "', dates=NOW() WHERE id='" . (int)$project_id . "' LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

if ($op === 'save_admin_tags_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'เฉพาะหน่วยแผนเท่านั้นที่แก้ไข Tags ได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_ensure_admin_tags_schema')) {
			pm_ensure_admin_tags_schema($db_Project);
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาบันทึกโครงการก่อน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_exit_if_project_plan_closed')) {
			pm_exit_if_project_plan_closed($db_Project, $project_id);
		}
		$chk = @mysqli_query($db_Project, "SELECT id FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $chk ? mysqli_fetch_assoc($chk) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$tagsIn = [];
		if (isset($_POST['tags_json'])) {
			$decoded = json_decode((string)$_POST['tags_json'], true);
			$tagsIn = is_array($decoded) ? $decoded : [];
		} elseif (isset($_POST['tags'])) {
			$tagsIn = (string)$_POST['tags'];
		}
		$tags = function_exists('pm_parse_admin_tags') ? pm_parse_admin_tags($tagsIn) : [];
		$stored = function_exists('pm_admin_tags_to_storage')
			? pm_admin_tags_to_storage($tags)
			: json_encode($tags, JSON_UNESCAPED_UNICODE);
		$esc = mysqli_real_escape_string($db_Project, $stored);
		$ok = @mysqli_query($db_Project, "UPDATE pre_project SET admin_tags='" . $esc . "', dates=NOW() WHERE id='" . (int)$project_id . "' LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		echo json_encode(['ok' => 1, 'tags' => $tags], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

