		);
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		echo json_encode(['ok' => 1, 'dept' => $dept, 'date' => $dateTxt], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ส่งร่างโครงการ (AJAX) -> เปลี่ยนสถานะเป็น "รอบรรจุโครงการ"
if ($op === 'submit_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		// permission
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanEditPreProjectRichFields') || !staffCanEditPreProjectRichFields($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$check = @mysqli_query($db_Project, "SELECT id, status_project, midyear_request, notify_result FROM pre_project WHERE id='".(int)$project_id."' LIMIT 1");
		$row = $check ? mysqli_fetch_assoc($check) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((int)($row['midyear_request'] ?? 0) === 1) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการยื่นระหว่างปีให้ใช้ปุ่มขออนุมัติดำเนินโครงการ ไม่ต้องส่งร่าง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((string)($row['status_project'] ?? '') === '8' && trim((string)($row['notify_result'] ?? '')) === 'บรรจุแผน') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการถูกตีกลับหลังขอดำเนินการ ให้ใช้ปุ่มยืนยันการแก้ไขและส่ง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stNow = (string)($row['status_project'] ?? '');
		$confirmedInclude = false;
		if (function_exists('ensureIncludeRequestTables')) {
			ensureIncludeRequestTables($db_Project);
			$qIncPend = @mysqli_query(
				$db_Project,
				"SELECT i.request_id, IFNULL(i.fix_note,'') AS fix_note
				 FROM project_include_request_item i
				 JOIN project_include_request r ON r.id = i.request_id
				 WHERE i.project_id='" . (int)$project_id . "'
				   AND IFNULL(i.return_selected,0)=1
				   AND IFNULL(i.fix_status,'') IN ('','pending')
				   AND r.status='rejected'
				 ORDER BY i.id DESC LIMIT 1"
			);
			$incPend = $qIncPend ? mysqli_fetch_assoc($qIncPend) : null;
			$incReqId = (int)($incPend['request_id'] ?? 0);
			if ($incReqId > 0) {
				$fixNote = trim((string)($incPend['fix_note'] ?? ''));
				if ($fixNote === '') {
					$fixNote = 'ส่งร่างโครงการหลังแก้ไข';
				}
				$fixEsc = mysqli_real_escape_string($db_Project, $fixNote);
				@mysqli_query(
					$db_Project,
					"UPDATE project_include_request_item
					 SET fix_note='" . $fixEsc . "',
					     fix_at=NOW(),
					     fix_staff_id='" . (int)$sid . "',
					     fix_status='confirmed'
					 WHERE request_id='" . $incReqId . "' AND project_id='" . (int)$project_id . "' LIMIT 1"
				);
				$confirmedInclude = true;
			}
		}

		if ($stNow === '2' || $stNow === '3') {
			$keepStatus = $stNow;
			if ($confirmedInclude && $stNow === '2') {
				@mysqli_query($db_Project, "UPDATE pre_project SET status_project='3', dates=NOW() WHERE id='".(int)$project_id."' AND status='1' LIMIT 1");
				$keepStatus = '3';
			}
			echo json_encode(['ok' => 1, 'already' => 1, 'status_project' => $keepStatus], JSON_UNESCAPED_UNICODE);
			exit;
		}

		if (function_exists('pmValidateProjectWeightRules')) {
			$weightErr = pmValidateProjectWeightRules($db_Project, $project_id);
			if ($weightErr !== null) {
				echo json_encode(['ok' => 0, 'msg' => $weightErr], JSON_UNESCAPED_UNICODE);
				exit;
			}
		}

		$nextStatus = $confirmedInclude ? '3' : '2';
		$ok = @mysqli_query($db_Project, "UPDATE pre_project SET status_project='".$nextStatus."', dates=NOW(), staff_insert='".(int)$sid."' WHERE id='".(int)$project_id."' LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'ส่งร่างไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		echo json_encode(['ok' => 1, 'status_project' => $nextStatus], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ขออนุมัติดำเนินโครงการ (AJAX) -> เปลี่ยนสถานะจาก "ขอบรรจุโครงการ" เป็น "อนุมัติ"
if ($op === 'request_operate_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (function_exists('ensureProjectExtraSchema')) {
			ensureProjectExtraSchema($db_Project);
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ขออนุมัติดำเนินโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$chk = @mysqli_query($db_Project, "SELECT id, status_project, notify_result, midyear_request, midyear_reason FROM pre_project WHERE id='".(int)$project_id."' AND status='1' LIMIT 1");
		$row = $chk ? mysqli_fetch_assoc($chk) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stNow = (string)($row['status_project'] ?? '');
		$isMidyear = (int)($row['midyear_request'] ?? 0) === 1;
		if ($stNow === '1') {
			echo json_encode(['ok' => 1, 'already' => 1], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($isMidyear) {
			if (!in_array($stNow, ['0', '8'], true)) {
				echo json_encode(['ok' => 0, 'msg' => 'ขออนุมัติดำเนินโครงการระหว่างปีได้เมื่อกรอกข้อมูลครบแล้วเท่านั้น'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			if (trim(strip_tags((string)($row['midyear_reason'] ?? ''))) === '') {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกเหตุผลการขอเพิ่มโครงการระหว่างปี'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			if (function_exists('pmValidateProjectWeightRules')) {
				$weightErr = pmValidateProjectWeightRules($db_Project, $project_id);
				if ($weightErr !== null) {
					echo json_encode(['ok' => 0, 'msg' => $weightErr], JSON_UNESCAPED_UNICODE);
					exit;
				}
			}
		} elseif ($stNow !== '4') {
			echo json_encode(['ok' => 0, 'msg' => 'ขออนุมัติดำเนินโครงการได้เฉพาะโครงการที่นำเข้าที่ประชุมแล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
		$certArr = json_decode($certIn, true);
		$certNormalized = [];
		if (!is_array($certArr) || count($certArr) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน และเรียงลำดับการพิจารณา'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		foreach ($certArr as $crow) {
			if (!is_array($crow)) {
				continue;
			}
			$cSid = (int)($crow['staff_id'] ?? 0);
			$cPos = trim((string)($crow['position'] ?? ''));
			if ($cSid <= 0 || $cPos === '') {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$certNormalized[] = ['staff_id' => $cSid, 'position' => $cPos];
		}
		if (count($certNormalized) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$certJsonEsc = mysqli_real_escape_string($db_Project, json_encode($certNormalized, JSON_UNESCAPED_UNICODE));

		if (function_exists('pm_ensure_operate_approver_schema')) {
			pm_ensure_operate_approver_schema($db_Project);
		}
		$stWhere = $isMidyear ? "status_project IN ('0','8')" : "status_project='4'";
		$ok = @mysqli_query($db_Project, "UPDATE pre_project SET status_project='1', dates=NOW(), staff_insert='".(int)$sid."', operate_certifiers_json='".$certJsonEsc."', operate_approvers_json=NULL, operate_submitter_reply_note=NULL, operate_submitter_reply_updated_at=NULL, operate_submitter_reply_staff_id=NULL, plan_admin_operate_rechain_submitted_at=NULL WHERE id='".(int)$project_id."' AND ".$stWhere." LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'ขออนุมัติดำเนินโครงการไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		// เริ่ม Flow ขอดำเนินการรอบใหม่: ล้างผลพิจารณาเดิมที่ค้างจากรอบก่อน
		@mysqli_query($db_Project, "DELETE FROM project_operate_certifier_decision WHERE project_id='".(int)$project_id."'");
		@mysqli_query($db_Project, "DELETE FROM project_operate_approver_decision WHERE project_id='".(int)$project_id."'");
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: '.$e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ขอเปลี่ยนแปลงโครงการ (AJAX) — ส่งผู้รับรองตามลำดับ
if ($op === 'request_change_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (function_exists('pm_ensure_change_request_schema')) {
			pm_ensure_change_request_schema($db_Project);
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ขอเปลี่ยนแปลงโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_project_is_result_report_plan_closed') && pm_project_is_result_report_plan_closed($db_Project, $project_id)) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ปิดแล้ว ไม่สามารถขอเปลี่ยนแปลงได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (!function_exists('pm_is_operate_final_approved') || !pm_is_operate_final_approved($db_Project, $project_id)) {
			echo json_encode(['ok' => 0, 'msg' => 'ขอเปลี่ยนแปลงได้เมื่อโครงการอนุมัติดำเนินการแล้วเท่านั้น'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_staff_is_reviewer_or_approver_on_project')
			&& pm_staff_is_reviewer_or_approver_on_project($db_Project, $project_id, $sid)) {
			echo json_encode(['ok' => 0, 'msg' => 'ผู้ตรวจสอบหรือผู้อนุมัติไม่สามารถขอเปลี่ยนแปลงโครงการได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_project_pending_change_request_id') && pm_project_pending_change_request_id($db_Project, $project_id) > 0) {
			echo json_encode(['ok' => 0, 'msg' => 'มีคำขอเปลี่ยนแปลงที่รอพิจารณาอยู่แล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$reason = trim((string)($_POST['reason'] ?? ''));
		if ($reason === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกเหตุผลการขอเปลี่ยนแปลง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$detailsIn = isset($_POST['details_json']) ? (string)$_POST['details_json'] : '[]';
		$detailsArr = json_decode($detailsIn, true);
		$detailsNormalized = [];
		if (is_array($detailsArr)) {
			foreach ($detailsArr as $drow) {
				if (!is_array($drow)) {
					continue;
				}
				$orig = trim((string)($drow['original'] ?? ''));
				$chg = trim((string)($drow['changed'] ?? ''));
				if ($orig === '' && $chg === '') {
					continue;
				}
				if ($orig === '' || $chg === '') {
					echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกรายละเอียดเดิมและรายละเอียดการเปลี่ยนแปลงให้ครบทุกแถว'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$detailsNormalized[] = ['original' => $orig, 'changed' => $chg];
			}
		}
		if (empty($detailsNormalized)) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุรายละเอียดการเปลี่ยนแปลงอย่างน้อย 1 รายการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
		$certArr = json_decode($certIn, true);
		$certNormalized = [];
		if (!is_array($certArr) || count($certArr) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน และเรียงลำดับการพิจารณา'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		foreach ($certArr as $crow) {
			if (!is_array($crow)) {
				continue;
			}
			$cSid = (int)($crow['staff_id'] ?? 0);
			$cPos = trim((string)($crow['position'] ?? ''));
			if ($cSid <= 0 || $cPos === '') {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$certNormalized[] = ['staff_id' => $cSid, 'position' => $cPos];
		}
		if (count($certNormalized) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$preRow = function_exists('getPreProjectID') ? getPreProjectID($db_Project, $project_id) : null;
		$project_name = is_array($preRow) ? trim((string)($preRow['name_project'] ?? '')) : '';
		$project_code = is_array($preRow) ? trim((string)($preRow['code_pre_project'] ?? '')) : '';
		$budget_source = function_exists('resolveProjectBudgetSourceForDisplay')
			? resolveProjectBudgetSourceForDisplay($db_Project, $project_id)
			: '-';
		$budget_amount = 0.0;
		$qSum = @mysqli_query($db_Project, "SELECT IFNULL(SUM(pa.total),0) AS t FROM project_activity_budget pa WHERE pa.code_pre_project='" . (int)$project_id . "' AND pa.status!='99'");
		$rSum = $qSum ? mysqli_fetch_assoc($qSum) : null;
		$budget_amount = (float)($rSum['t'] ?? 0);

		$esc = static function ($v) use ($db_Project) {
			return mysqli_real_escape_string($db_Project, (string)$v);
		};
		$okIns = @mysqli_query(
			$db_Project,
			"INSERT INTO project_change_request
				(project_id, reason, details_json, certifiers_json, project_name, project_code, budget_source, budget_amount, staff_insert, req_status, created_at, status)
			 VALUES (
				'" . (int)$project_id . "',
				'" . $esc($reason) . "',
				'" . $esc(json_encode($detailsNormalized, JSON_UNESCAPED_UNICODE)) . "',
				'" . $esc(json_encode($certNormalized, JSON_UNESCAPED_UNICODE)) . "',
				'" . $esc($project_name) . "',
				'" . $esc($project_code) . "',
				'" . $esc($budget_source) . "',
				'" . $esc(number_format($budget_amount, 2, '.', '')) . "',
				'" . (int)$sid . "',
				'pending', NOW(), '1'
			 )"
		);
		if (!$okIns) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกคำขอไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$request_id = (int)mysqli_insert_id($db_Project);
		if ($request_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกคำขอไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		foreach ($certNormalized as $i => $crow) {
			$sort = $i + 1;
			@mysqli_query(
				$db_Project,
				"INSERT INTO project_change_certifier_decision
					(request_id, project_id, sort_order, staff_id, decision, created_at)
				 VALUES (
					'" . (int)$request_id . "',
					'" . (int)$project_id . "',
					'" . (int)$sort . "',
					'" . (int)$crow['staff_id'] . "',
					'', NOW()
				 )"
			);
		}

		$uploadDir = realpath(__DIR__ . '/../document/project_change_files');
		if ($uploadDir === false) {
			$uploadDir = __DIR__ . '/../document/project_change_files';
			if (!is_dir($uploadDir)) {
				@mkdir($uploadDir, 0775, true);
			}
			$uploadDir = realpath($uploadDir);
		}
		$fileNames = $_FILES['change_files']['name'] ?? null;
		if (is_array($fileNames) && $uploadDir && is_dir($uploadDir) && is_writable($uploadDir)) {
			$maxBytes = 15 * 1024 * 1024;
			for ($i = 0; $i < count($fileNames); $i++) {
				$name = isset($_FILES['change_files']['name'][$i]) ? (string)$_FILES['change_files']['name'][$i] : '';
				$tmp = $_FILES['change_files']['tmp_name'][$i] ?? '';
				$err = (int)($_FILES['change_files']['error'][$i] ?? UPLOAD_ERR_NO_FILE);
				$size = (int)($_FILES['change_files']['size'][$i] ?? 0);
				if ($name === '' || $err === UPLOAD_ERR_NO_FILE) {
					continue;
				}
				if ($err !== UPLOAD_ERR_OK || $size <= 0 || $size > $maxBytes) {
					continue;
				}
				$ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
				if ($ext !== 'pdf') {
					echo json_encode(['ok' => 0, 'msg' => 'เอกสารแนบต้องเป็นไฟล์ PDF เท่านั้น'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$stored = $request_id . '_' . time() . '_' . $i . '_' . bin2hex(random_bytes(4)) . '.pdf';
				$dest = $uploadDir . DIRECTORY_SEPARATOR . $stored;
				if (!@move_uploaded_file((string)$tmp, $dest)) {
					continue;
				}
				@mysqli_query(
					$db_Project,
					"INSERT INTO project_change_request_file (request_id, original_name, stored_file, staff_insert, created_at, status)
					 VALUES ('" . (int)$request_id . "', '" . $esc($name) . "', '" . $esc($stored) . "', '" . (int)$sid . "', NOW(), '1')"
				);
			}
		} elseif (is_array($fileNames) && !empty($fileNames[0])) {
			$hasNamed = false;
			foreach ($fileNames as $fn) {
				if (trim((string)$fn) !== '') {
					$hasNamed = true;
					break;
				}
			}
			if ($hasNamed) {
				echo json_encode(['ok' => 0, 'msg' => 'ไม่สามารถบันทึกไฟล์แนบได้'], JSON_UNESCAPED_UNICODE);
				exit;
			}
		}

		$firstCert = (int)($certNormalized[0]['staff_id'] ?? 0);
		if ($firstCert > 0 && function_exists('pm_staff_notify')) {
			$link = '?page=project_approve&open_flow=change&open_project_id=' . (int)$project_id . '&change_request_id=' . (int)$request_id . '&project_id=' . (int)$project_id;
			$ttl = 'มีคำขอเปลี่ยนแปลงโครงการรอพิจารณา';
			$bdy = ($project_code !== '' ? $project_code . ' ' : '') . ($project_name !== '' ? $project_name : '');
			pm_staff_notify($db_Project, $firstCert, 'change_request', $ttl, $bdy, $link, 'project_change', $request_id);
		}

		echo json_encode(['ok' => 1, 'id' => $request_id, 'msg' => 'ส่งคำขอเปลี่ยนแปลงโครงการแล้ว ระบบจะส่งให้ผู้รับรองตามลำดับ'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

if ($op === 'request_cancel_project_ajax' || $op === 'get_cancel_request_ajax' || $op === 'delete_cancel_file_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (function_exists('pm_ensure_cancel_request_schema')) {
			pm_ensure_cancel_request_schema($db_Project);
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		$isPlanAdmin = (defined('PLAN_ADMIN') && PLAN_ADMIN);
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : (isset($_GET['project_id']) ? (int)$_GET['project_id'] : 0);
		if ($op === 'delete_cancel_file_ajax') {
			$file_id = isset($_POST['file_id']) ? (int)$_POST['file_id'] : 0;
			if ($file_id <= 0 || $sid <= 0) {
				echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$qF = @mysqli_query(
				$db_Project,
				"SELECT f.id, f.request_id, r.project_id, r.staff_insert, r.req_status
				 FROM project_cancel_request_file f
				 INNER JOIN project_cancel_request r ON r.id = f.request_id
				 WHERE f.id='" . $file_id . "' AND f.status='1' AND r.status='1' LIMIT 1"
			);
			$fr = $qF ? mysqli_fetch_assoc($qF) : null;
			if (!$fr) {
				echo json_encode(['ok' => 0, 'msg' => 'ไม่พบไฟล์'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$pidF = (int)($fr['project_id'] ?? 0);
			$stF = (string)($fr['req_status'] ?? '');
			if (!in_array($stF, ['draft', 'rejected'], true)) {
				echo json_encode(['ok' => 0, 'msg' => 'ไม่สามารถลบไฟล์เมื่อส่งคำขอแล้ว'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			if (!$isPlanAdmin && ((int)($fr['staff_insert'] ?? 0) !== $sid) && (!function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $pidF, $sid, $staff_code, $unit_code))) {
				echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ลบไฟล์นี้'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			@mysqli_query($db_Project, "UPDATE project_cancel_request_file SET status='99' WHERE id='" . $file_id . "' LIMIT 1");
			echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
			exit;
		}

		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($sid <= 0 || (!$isPlanAdmin && (!function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)))) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์เข้าถึงโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$packCancel = static function ($req) use ($db_Project) {
			if (!is_array($req)) {
				return null;
			}
			$rid = (int)($req['id'] ?? 0);
			$files = [];
			if ($rid > 0) {
				$qF = @mysqli_query($db_Project, "SELECT id, original_name FROM project_cancel_request_file WHERE request_id='" . $rid . "' AND status='1' ORDER BY id ASC");
				while ($qF && ($fr = mysqli_fetch_assoc($qF))) {
					$fid = (int)($fr['id'] ?? 0);
					$files[] = [
						'id' => $fid,
						'name' => (string)($fr['original_name'] ?? ''),
						'url' => '?page=project_approve&op=download_cancel_file&file_id=' . $fid,
					];
				}
			}
			return [
				'id' => $rid,
				'project_id' => (int)($req['project_id'] ?? 0),
				'reason' => (string)($req['reason'] ?? ''),
				'req_status' => (string)($req['req_status'] ?? ''),
				'decide_note' => (string)($req['decide_note'] ?? ''),
				'decided_at' => (string)($req['decided_at'] ?? ''),
				'submitted_at' => (string)($req['submitted_at'] ?? ''),
				'files' => $files,
			];
		};

		if ($op === 'get_cancel_request_ajax') {
			$req = function_exists('pm_load_project_cancel_request') ? pm_load_project_cancel_request($db_Project, $project_id) : null;
			echo json_encode(['ok' => 1, 'request' => $packCancel($req)], JSON_UNESCAPED_UNICODE);
			exit;
		}

		if (function_exists('pm_project_is_result_report_plan_closed') && pm_project_is_result_report_plan_closed($db_Project, $project_id)) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ปิดแล้ว ไม่สามารถขอยกเลิกได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (!function_exists('pm_is_operate_final_approved') || !pm_is_operate_final_approved($db_Project, $project_id)) {
			echo json_encode(['ok' => 0, 'msg' => 'ขอยกเลิกได้เมื่อโครงการอนุมัติดำเนินการแล้วเท่านั้น'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($op === 'request_cancel_project_ajax'
			&& function_exists('pm_staff_is_reviewer_or_approver_on_project')
			&& pm_staff_is_reviewer_or_approver_on_project($db_Project, $project_id, $sid)) {
			echo json_encode(['ok' => 0, 'msg' => 'ผู้ตรวจสอบหรือผู้อนุมัติไม่สามารถขอยกเลิกโครงการได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_project_is_cancelled') && pm_project_is_cancelled($db_Project, $project_id)) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ถูกยกเลิกแล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$intent = trim((string)($_POST['intent'] ?? 'save'));
		if ($intent !== 'submit') {
			$intent = 'save';
		}
		$reason = trim((string)($_POST['reason'] ?? ''));
		if ($intent === 'submit' && $reason === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกเหตุผลการขอยกเลิกโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$preRow = function_exists('getPreProjectID') ? getPreProjectID($db_Project, $project_id) : null;
		$project_name = is_array($preRow) ? trim((string)($preRow['name_project'] ?? '')) : '';
		$project_code = is_array($preRow) ? trim((string)($preRow['code_pre_project'] ?? '')) : '';
		$budget_source = function_exists('resolveProjectBudgetSourceForDisplay')
			? resolveProjectBudgetSourceForDisplay($db_Project, $project_id)
			: '-';
		$budget_amount = 0.0;
		$qSum = @mysqli_query($db_Project, "SELECT IFNULL(SUM(pa.total),0) AS t FROM project_activity_budget pa WHERE pa.code_pre_project='" . (int)$project_id . "' AND pa.status!='99'");
		$rSum = $qSum ? mysqli_fetch_assoc($qSum) : null;
		$budget_amount = (float)($rSum['t'] ?? 0);

		$esc = static function ($v) use ($db_Project) {
			return mysqli_real_escape_string($db_Project, (string)$v);
		};
		$req = function_exists('pm_load_project_cancel_request') ? pm_load_project_cancel_request($db_Project, $project_id) : null;
		$stNow = is_array($req) ? trim((string)($req['req_status'] ?? '')) : '';
		if ($stNow === 'pending') {
			echo json_encode(['ok' => 0, 'msg' => 'มีคำขอยกเลิกที่รอหน่วยแผนพิจารณาอยู่แล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($stNow === 'approved') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ถูกยกเลิกแล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$newStatus = $intent === 'submit' ? 'pending' : 'draft';
		$request_id = is_array($req) ? (int)($req['id'] ?? 0) : 0;
		if ($request_id > 0 && in_array($stNow, ['draft', 'rejected'], true)) {
			$extra = '';
			if ($newStatus === 'pending') {
				$extra = ", submitted_at=NOW(), decided_at=NULL, decided_by_staff_id=NULL, decide_note=NULL";
			}
			$okUp = @mysqli_query(
				$db_Project,
				"UPDATE project_cancel_request SET
					reason='" . $esc($reason) . "',
					project_name='" . $esc($project_name) . "',
					project_code='" . $esc($project_code) . "',
					budget_source='" . $esc($budget_source) . "',
					budget_amount='" . $esc(number_format($budget_amount, 2, '.', '')) . "',
					req_status='" . $esc($newStatus) . "',
					updated_at=NOW()
					" . $extra . "
				 WHERE id='" . $request_id . "' LIMIT 1"
			);
			if (!$okUp) {
				echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
				exit;
			}
		} else {
			$okIns = @mysqli_query(
				$db_Project,
				"INSERT INTO project_cancel_request
					(project_id, reason, project_name, project_code, budget_source, budget_amount, staff_insert, req_status, submitted_at, created_at, status)
				 VALUES (
					'" . (int)$project_id . "',
					'" . $esc($reason) . "',
					'" . $esc($project_name) . "',
					'" . $esc($project_code) . "',
					'" . $esc($budget_source) . "',
					'" . $esc(number_format($budget_amount, 2, '.', '')) . "',
					'" . (int)$sid . "',
					'" . $esc($newStatus) . "',
					" . ($newStatus === 'pending' ? 'NOW()' : 'NULL') . ",
					NOW(), '1'
				 )"
			);
			if (!$okIns) {
				echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$request_id = (int)mysqli_insert_id($db_Project);
		}
		if ($request_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$fileRes = function_exists('pm_save_cancel_request_files')
			? pm_save_cancel_request_files($db_Project, $request_id, $sid, 'cancel_files')
			: ['ok' => 1];
		if (empty($fileRes['ok'])) {
			echo json_encode(['ok' => 0, 'msg' => (string)($fileRes['msg'] ?? 'บันทึกไฟล์ไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$msg = $newStatus === 'pending'
			? 'ส่งคำขอยกเลิกโครงการแล้ว รอหน่วยแผนพิจารณา'
			: 'บันทึกร่างคำขอยกเลิกแล้ว ยังไม่ได้ส่งให้หน่วยแผน';
		echo json_encode(['ok' => 1, 'id' => $request_id, 'req_status' => $newStatus, 'msg' => $msg], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

if ($op === 'plan_admin_change_rechain_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้เมนู Plan Admin'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_ensure_change_request_schema')) {
			pm_ensure_change_request_schema($db_Project);
		}
		$request_id = isset($_POST['change_request_id']) ? (int)$_POST['change_request_id'] : 0;
		if ($request_id <= 0 && isset($_POST['request_id'])) {
			$request_id = (int)$_POST['request_id'];
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($request_id <= 0 && $project_id > 0 && function_exists('pm_project_pending_change_request_id')) {
			$request_id = pm_project_pending_change_request_id($db_Project, $project_id);
		}
		if ($request_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบคำขอเปลี่ยนแปลง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$qReq = @mysqli_query($db_Project, "SELECT * FROM project_change_request WHERE id='" . (int)$request_id . "' AND status='1' LIMIT 1");
		$req = $qReq ? mysqli_fetch_assoc($qReq) : null;
		if (!$req) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบคำขอเปลี่ยนแปลง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stReq = trim((string)($req['req_status'] ?? ''));
		if ($stReq !== 'waiting_plan' && $stReq !== 'pending') {
			echo json_encode(['ok' => 0, 'msg' => 'คำขอนี้ไม่อยู่ในสถานะที่หน่วยแผนเลือกผู้อนุมัติได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($req['plan_rechain_submitted_at'] ?? '')) !== '' || trim((string)($req['approvers_json'] ?? '')) !== '') {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกลำดับผู้อนุมัติสำหรับรอบนี้แล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$certArrOld = json_decode((string)($req['certifiers_json'] ?? ''), true);
		if (!is_array($certArrOld) || count($certArrOld) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบลำดับผู้รับรองเดิม'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$decMap = [];
		$qOD = @mysqli_query($db_Project, "SELECT sort_order, decision FROM project_change_certifier_decision WHERE request_id='" . (int)$request_id . "'");
		while ($qOD && ($od = mysqli_fetch_assoc($qOD))) {
			$so = (int)($od['sort_order'] ?? 0);
			if ($so > 0) {
				$decMap[$so] = (string)($od['decision'] ?? '');
			}
		}
		$seqNo = 0;
		foreach ($certArrOld as $__c) {
			if (!is_array($__c)) {
				continue;
			}
			$seqNo++;
			$so = (int)($__c['sort_order'] ?? 0);
			if ($so <= 0) {
				$so = $seqNo;
			}
			if ((string)($decMap[$so] ?? '') !== 'approved') {
				echo json_encode(['ok' => 0, 'msg' => 'ผู้รับรองยังไม่ผ่านครบ จึงยังเลือกผู้อนุมัติไม่ได้'], JSON_UNESCAPED_UNICODE);
				exit;
			}
		}
		$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
		$certArr = json_decode($certIn, true);
		$certNormalized = [];
		if (!is_array($certArr) || count($certArr) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้อนุมัติโครงการอย่างน้อย 1 คน และเรียงลำดับการพิจารณา'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$o = 0;
		foreach ($certArr as $crow) {
			if (!is_array($crow)) {
				continue;
			}
			$cSid = (int)($crow['staff_id'] ?? 0);
			$cPos = trim((string)($crow['position'] ?? ''));
			if ($cSid <= 0 || $cPos === '') {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้อนุมัติและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$o++;
			$certNormalized[] = ['sort_order' => $o, 'staff_id' => $cSid, 'position' => $cPos];
		}
		if ($o === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้อนุมัติโครงการอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$pid = (int)($req['project_id'] ?? 0);
		$esc = static function ($v) use ($db_Project) {
			return mysqli_real_escape_string($db_Project, (string)$v);
		};
		@mysqli_query($db_Project, "DELETE FROM project_change_approver_decision WHERE request_id='" . (int)$request_id . "'");
		$sidPlan = 0;
		$sess_email_re = $_SESSION['r_email'] ?? '';
		$sess_code_re = $_SESSION['code'] ?? '';
		if ($sess_email_re !== '' && $sess_code_re !== '') {
			$stRe = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($stRe, 'ss', $sess_email_re, $sess_code_re);
			mysqli_stmt_execute($stRe);
			$rsRe = mysqli_stmt_get_result($stRe);
			$rwRe = $rsRe ? mysqli_fetch_assoc($rsRe) : null;
			if ($rwRe) {
				$sidPlan = (int)($rwRe['id'] ?? 0);
			}
		}
		$okUp = @mysqli_query(
			$db_Project,
			"UPDATE project_change_request SET
				approvers_json='" . $esc(json_encode($certNormalized, JSON_UNESCAPED_UNICODE)) . "',
				plan_rechain_submitted_at=NOW(),
				plan_rechain_staff_id='" . (int)$sidPlan . "',
				req_status='pending_approve',
				updated_at=NOW()
			 WHERE id='" . (int)$request_id . "' AND status='1' LIMIT 1"
		);
		if (!$okUp) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		foreach ($certNormalized as $crow) {
			@mysqli_query(
				$db_Project,
				"INSERT INTO project_change_approver_decision
					(request_id, project_id, sort_order, staff_id, decision, created_at)
				 VALUES (
					'" . (int)$request_id . "',
					'" . (int)$pid . "',
					'" . (int)$crow['sort_order'] . "',
					'" . (int)$crow['staff_id'] . "',
					'', NOW()
				 )"
			);
		}
		$firstAppr = (int)($certNormalized[0]['staff_id'] ?? 0);
		if ($firstAppr > 0 && function_exists('pm_staff_notify')) {
			$pName = trim((string)($req['project_name'] ?? ''));
			$pCode = trim((string)($req['project_code'] ?? ''));
			$link = '?page=project_approve&open_flow=change&open_project_id=' . (int)$pid . '&change_request_id=' . (int)$request_id . '&project_id=' . (int)$pid;
			pm_staff_notify($db_Project, $firstAppr, 'change_request', 'มีคำขอเปลี่ยนแปลงโครงการรออนุมัติ', ($pCode !== '' ? $pCode . ' ' : '') . $pName, $link, 'project_change', $request_id);
		}
		echo json_encode(['ok' => 1, 'msg' => 'ส่งให้ผู้อนุมัติแล้ว ระบบจะส่งตามลำดับ'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

if ($op === 'plan_admin_apply_change_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'เฉพาะหน่วยแผนเท่านั้นที่แก้ไขโครงการตามคำขอเปลี่ยนแปลงได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_ensure_change_request_schema')) {
			pm_ensure_change_request_schema($db_Project);
		}
		$request_id = isset($_POST['change_request_id']) ? (int)$_POST['change_request_id'] : 0;
		if ($request_id <= 0 && isset($_POST['request_id'])) {
			$request_id = (int)$_POST['request_id'];
		}
		$apply_note = trim((string)($_POST['apply_note'] ?? ''));
		if ($request_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบคำขอเปลี่ยนแปลง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($apply_note === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุรายละเอียดที่แก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sid = 0;
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
			}
		}
		if ($sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบผู้ใช้งาน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$qReq = @mysqli_query($db_Project, "SELECT * FROM project_change_request WHERE id='" . (int)$request_id . "' AND status='1' LIMIT 1");
		$req = $qReq ? mysqli_fetch_assoc($qReq) : null;
		if (!$req) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบคำขอเปลี่ยนแปลง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($req['req_status'] ?? '')) !== 'approved') {
			echo json_encode(['ok' => 0, 'msg' => 'คำขอยังไม่ได้รับอนุมัติ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($req['applied_at'] ?? '')) !== '') {
			echo json_encode(['ok' => 0, 'msg' => 'คำขอนี้ถูกบันทึกการแก้ไขแล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$pid = (int)($req['project_id'] ?? 0);
		$esc = static function ($v) use ($db_Project) {
			return mysqli_real_escape_string($db_Project, (string)$v);
		};
		$okUp = @mysqli_query(
			$db_Project,
			"UPDATE project_change_request SET
				applied_at=NOW(),
				applied_by_staff_id='" . (int)$sid . "',
				apply_note='" . $esc($apply_note) . "',
				updated_at=NOW()
			 WHERE id='" . (int)$request_id . "' AND status='1' AND req_status='approved'
			   AND (applied_at IS NULL OR TRIM(IFNULL(applied_at,''))='')
			 LIMIT 1"
		);
		if (!$okUp || mysqli_affected_rows($db_Project) <= 0) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_change_apply_log (request_id, project_id, apply_note, details_json, staff_id, created_at)
			 VALUES (
				'" . (int)$request_id . "',
				'" . (int)$pid . "',
				'" . $esc($apply_note) . "',
				'" . $esc((string)($req['details_json'] ?? '')) . "',
				'" . (int)$sid . "',
				NOW()
			 )"
		);
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_plan_review_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			meta_json MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_pprl_project (project_id, created_at),
			KEY idx_pprl_actor (actor_staff_id)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$metaEsc = $esc(json_encode([
			'request_id' => $request_id,
			'apply_note' => $apply_note,
			'details' => json_decode((string)($req['details_json'] ?? ''), true),
		], JSON_UNESCAPED_UNICODE));
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$pid . "', 'change_apply', '" . (int)$sid . "', '" . $esc($apply_note) . "', '" . $metaEsc . "', NOW())"
		);
		$pName = trim((string)($req['project_name'] ?? ''));
		$pCode = trim((string)($req['project_code'] ?? ''));
		$linkManage = '?page=project_manage&op=add_project&project_id=' . (int)$pid;
		$submitter = (int)($req['staff_insert'] ?? 0);
		if ($submitter > 0 && function_exists('pm_staff_notify')) {
			pm_staff_notify(
				$db_Project,
				$submitter,
				'change_request',
				'หน่วยแผนแก้ไขโครงการตามคำขอเปลี่ยนแปลงแล้ว',
				($pCode !== '' ? $pCode . ' ' : '') . $pName,
				$linkManage,
				'project_change',
				$request_id
			);
		}
		echo json_encode(['ok' => 1, 'msg' => 'บันทึกการแก้ไขเรียบร้อย'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// Plan_Admin: หลังผู้ตรวจขั้นแรก (ฝั่งผู้ใช้) ผ่านครบ — ระบุลำดับผู้รับรองรอบองค์กร และส่งเข้ากระบวนการอีกครั้ง (แทนที่ลำดับเดิม / เริ่มต้นใหม่จาก project_operate_certifier_decision)
if ($op === 'plan_admin_operate_rechain_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้เมนู Plan Admin'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
			}
		}
		if ($sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบผู้ใช้งาน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$chkColPa = @mysqli_query($db_Project, "SHOW COLUMNS FROM pre_project LIKE 'plan_admin_operate_rechain_submitted_at'");
		if (!$chkColPa || mysqli_num_rows($chkColPa) === 0) {
			@mysqli_query($db_Project, "ALTER TABLE pre_project ADD COLUMN plan_admin_operate_rechain_submitted_at DATETIME NULL DEFAULT NULL");
		}
		if (function_exists('pm_ensure_operate_approver_schema')) {
			pm_ensure_operate_approver_schema($db_Project);
		}
		$row = null;
		$qP = @mysqli_query($db_Project, "SELECT id, status_project, notify_result, operate_certifiers_json, operate_approvers_json, plan_admin_operate_rechain_submitted_at, name_project, code_pre_project, staff_insert FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		if ($qP) {
			$row = mysqli_fetch_assoc($qP);
		}
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stProjRow = trim((string)($row['status_project'] ?? ''));
		if ($stProjRow !== '1' && $stProjRow !== '8') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการไม่อยู่ในสถานะรอการอนุมัติดำเนินการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$nr_row = trim((string)($row['notify_result'] ?? ''));
		$st_row = trim((string)($row['status_project'] ?? ''));
		if (!function_exists('pm_notify_allows_plan_admin_operate_rechain') || !pm_notify_allows_plan_admin_operate_rechain($nr_row, $st_row)) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้อยู่นอกเงื่อนไขการส่งขออนุมัติครั้งใหม่จาก Plan (ต้องเป็นขั้นดำเนินการ status=1 และไม่ผล “ไม่ผ่านการพิจารณา”)'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($row['plan_admin_operate_rechain_submitted_at'] ?? '')) !== ''
			|| trim((string)($row['operate_approvers_json'] ?? '')) !== '') {
			echo json_encode(['ok' => 0, 'msg' => 'บันทึกลำดับผู้อนุมัติ (หน่วยแผน) สำหรับรอบนี้แล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$certMap = [];
		$certRaw = trim((string)($row['operate_certifiers_json'] ?? ''));
		$certArrOld = ($certRaw !== '') ? json_decode($certRaw, true) : [];
		if (!is_array($certArrOld)) {
			$certArrOld = [];
		}
		$seqNo = 0;
		foreach ($certArrOld as $__c) {
			if (!is_array($__c)) {
				continue;
			}
			$seqNo++;
			$so = (int)($__c['sort_order'] ?? 0);
			if ($so <= 0) {
				$so = (int)$seqNo;
			}
			$sidC = (int)($__c['staff_id'] ?? 0);
			if ($sidC <= 0) {
				continue;
			}
			$certMap[$so] = ['staff_id' => $sidC];
		}
		$decMap = [];
		$qOD = @mysqli_query($db_Project, "SELECT sort_order, decision FROM project_operate_certifier_decision WHERE project_id='" . (int)$project_id . "'");
		while ($qOD && ($od = mysqli_fetch_assoc($qOD))) {
			$so = (int)($od['sort_order'] ?? 0);
			if ($so > 0) {
				$decMap[$so] = $od;
			}
		}
		$chainSortsCheckPa = array_keys($certMap);
		sort($chainSortsCheckPa, SORT_NUMERIC);
		if (!empty($chainSortsCheckPa)) {
			foreach ($chainSortsCheckPa as $__so_ck) {
				if ((string)($decMap[$__so_ck]['decision'] ?? '') !== 'approved') {
					echo json_encode(['ok' => 0, 'msg' => 'ผู้ตรวจในลำดับปัจจุบันยังไม่ครบผ่าน จึงยังไม่สามารถส่งข้อมูลรอบ Plan ได้'], JSON_UNESCAPED_UNICODE);
					exit;
				}
			}
		} else {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีลำดับผู้ตรวจเดิมในระบบ — ให้ผู้ใช้ส่งขอดำเนินการโครงการก่อน'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
		$certArr = json_decode($certIn, true);
		$certNormalized = [];
		if (!is_array($certArr) || count($certArr) === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้อนุมัติโครงการอย่างน้อย 1 คน และเรียงลำดับการพิจารณา'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$o = 0;
		foreach ($certArr as $crow) {
			if (!is_array($crow)) {
				continue;
			}
			$cSid = (int)($crow['staff_id'] ?? 0);
			$cPos = trim((string)($crow['position'] ?? ''));
			if ($cSid <= 0 || $cPos === '') {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้อนุมัติและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$o++;
			$certNormalized[] = ['sort_order' => $o, 'staff_id' => $cSid, 'position' => $cPos];
		}
		if ($o === 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้อนุมัติโครงการอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$certJsonEsc = mysqli_real_escape_string($db_Project, json_encode($certNormalized, JSON_UNESCAPED_UNICODE));

		@mysqli_query($db_Project, "DELETE FROM project_operate_approver_decision WHERE project_id='" . (int)$project_id . "'");
		$okUp = @mysqli_query(
			$db_Project,
			"UPDATE pre_project SET
				operate_approvers_json='" . $certJsonEsc . "',
				plan_admin_operate_rechain_submitted_at=NOW(),
				dates=NOW()
			 WHERE id='" . (int)$project_id . "' AND status='1' AND status_project='1' LIMIT 1"
		);
		if (!$okUp || mysqli_affected_rows($db_Project) < 1) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จหรือสถานะโครงการไม่ตรง')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query(
			$db_Project,
			"CREATE TABLE IF NOT EXISTS project_plan_review_log (
				id INT UNSIGNED NOT NULL AUTO_INCREMENT,
				project_id INT UNSIGNED NOT NULL,
				action_type VARCHAR(32) NOT NULL DEFAULT '',
				actor_staff_id INT UNSIGNED NULL,
				note MEDIUMTEXT NULL,
				meta_json MEDIUMTEXT NULL,
				created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
				PRIMARY KEY (id),
				KEY idx_pprl_project (project_id, created_at),
				KEY idx_pprl_actor (actor_staff_id)
			) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
		);
		$metaEsc = mysqli_real_escape_string($db_Project, $certJsonEsc);
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, meta_json, created_at)
			 VALUES ('" . (int)$project_id . "', 'plan_admin_operate_rechain', '" . (int)$sid . "', '" . $metaEsc . "', NOW())"
		);
		$firstApprSid = (int)($certNormalized[0]['staff_id'] ?? 0);
		$projLabelRc = trim((string)(($row['code_pre_project'] ?? '') . ' ' . ($row['name_project'] ?? '')));
		$linkApprRc = '?page=project_approve&flow=operate&tab=pending&open_project_id=' . (int)$project_id . '&project_id=' . (int)$project_id;
		if ($firstApprSid > 0 && function_exists('pm_staff_notify')) {
			pm_staff_notify(
				$db_Project,
				$firstApprSid,
				'operate_approve',
				'มีขอดำเนินการโครงการรออนุมัติ',
				$projLabelRc !== '' ? $projLabelRc : ('โครงการ #' . (int)$project_id),
				$linkApprRc,
				'pre_project',
				(int)$project_id
			);
		}
		echo json_encode(['ok' => 1, 'msg' => 'ส่งให้ผู้อนุมัติแล้ว ระบบจะส่งตามลำดับ'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// Plan Admin: ตีกลับขอดำเนินการให้ผู้ยื่นแก้ไข (ก่อนเลือกผู้อนุมัติ)
if ($op === 'plan_admin_operate_return_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้เมนู Plan Admin'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$return_note = trim((string)($_POST['certifier_note'] ?? $_POST['return_note'] ?? ''));
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($return_note === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกข้อเสนอแนะ/ข้อชี้แจงก่อนตีกลับ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
			}
		}
		if ($sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบผู้ใช้งาน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$row = null;
		$qP = @mysqli_query(
			$db_Project,
			"SELECT id, status_project, notify_result, operate_certifiers_json, operate_approvers_json,
			        plan_admin_operate_rechain_submitted_at, name_project, code_pre_project, staff_insert
			 FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1"
		);
		if ($qP) {
			$row = mysqli_fetch_assoc($qP);
		}
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($row['status_project'] ?? '')) !== '1') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการไม่อยู่ในสถานะที่หน่วยแผนตีกลับได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($row['operate_approvers_json'] ?? '')) !== ''
			|| trim((string)($row['plan_admin_operate_rechain_submitted_at'] ?? '')) !== '') {
			echo json_encode(['ok' => 0, 'msg' => 'เลือกผู้อนุมัติไปแล้ว จึงตีกลับจากขั้นนี้ไม่ได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$certsDone = function_exists('pm_compute_operate_chain_all_approved')
			&& pm_compute_operate_chain_all_approved($db_Project, (int)$project_id, (string)($row['operate_certifiers_json'] ?? ''));
		if (!$certsDone) {
			echo json_encode(['ok' => 0, 'msg' => 'ผู้รับรองยังไม่ผ่านครบ จึงยังไม่ถึงขั้นหน่วยแผน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$noteEsc = mysqli_real_escape_string($db_Project, $return_note);
		$okUp = @mysqli_query(
			$db_Project,
			"UPDATE pre_project
			 SET status_project='8',
			     dates=NOW(),
			     operate_submitter_reply_note=NULL,
			     operate_submitter_reply_updated_at=NULL,
			     operate_submitter_reply_staff_id=NULL
			 WHERE id='" . (int)$project_id . "' AND status='1' AND status_project='1'
			 LIMIT 1"
		);
		if (!$okUp || mysqli_affected_rows($db_Project) < 1) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_operate_action_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			sort_order TINYINT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_poal_project (project_id, created_at),
			KEY idx_poal_actor (actor_staff_id),
			KEY idx_poal_sort (project_id, sort_order)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_operate_action_log (project_id, action_type, actor_staff_id, sort_order, note, created_at)
			 VALUES ('" . (int)$project_id . "', 'plan_admin_operate_returned', '" . (int)$sid . "', 0, '" . $noteEsc . "', NOW())"
		);
		$submitter = (int)($row['staff_insert'] ?? 0);
		$projLabelRt = trim((string)(($row['code_pre_project'] ?? '') . ' ' . ($row['name_project'] ?? '')));
		$linkManageRt = '?page=project_manage&op=add_project&project_id=' . (int)$project_id;
		if ($submitter > 0 && $submitter !== $sid && function_exists('pm_staff_notify')) {
			pm_staff_notify(
				$db_Project,
				$submitter,
				'operate_returned',
				'หน่วยแผนตีกลับขอดำเนินการโครงการ',
				$projLabelRt !== '' ? $projLabelRt : ('โครงการ #' . (int)$project_id),
				$linkManageRt,
				'pre_project',
				(int)$project_id
			);
		}
		echo json_encode(['ok' => 1, 'msg' => 'ตีกลับให้ผู้ยื่นแก้ไขเรียบร้อย'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// Plan Admin: แก้ไขชื่อ/ตำแหน่งผู้พิจารณาในลำดับขอดำเนินการ (ยังไม่บันทึกผลผู้พิจารณาขั้นนั้น)
if ($op === 'plan_admin_edit_operate_cert_row_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		while (ob_get_level()) {
			@ob_end_clean();
		}
		@ob_start();
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้เมนู Plan Admin'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$sort_order = isset($_POST['sort_order']) ? (int)$_POST['sort_order'] : 0;
		$new_staff_id = isset($_POST['staff_id']) ? (int)$_POST['staff_id'] : 0;
		$position_txt = isset($_POST['position']) ? trim((string)$_POST['position']) : '';
		if ($project_id <= 0 || $sort_order <= 0 || $new_staff_id <= 0 || $position_txt === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้พิจารณาและตำแหน่งให้ครบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
			}
		}
		if ($sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบผู้ใช้งาน'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_ensure_operate_approver_schema')) {
			pm_ensure_operate_approver_schema($db_Project);
		}
		$row = null;
		$qP = @mysqli_query($db_Project, "SELECT id, status_project, operate_certifiers_json, operate_approvers_json FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		if ($qP) {
			$row = mysqli_fetch_assoc($qP);
		}
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stProj = trim((string)($row['status_project'] ?? ''));
		if ($stProj !== '1' && $stProj !== '8') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการไม่อยู่ในสถานะขั้นดำเนินการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$editApproverChain = trim((string)($row['operate_approvers_json'] ?? '')) !== '';
		$jsonCol = $editApproverChain ? 'operate_approvers_json' : 'operate_certifiers_json';
		$decTable = $editApproverChain ? 'project_operate_approver_decision' : 'project_operate_certifier_decision';
		$certRaw = trim((string)($row[$jsonCol] ?? ''));
		if ($certRaw === '') {
			echo json_encode(['ok' => 0, 'msg' => 'ยังไม่มีลำดับผู้พิจารณาในระบบ (ข้อมูลขอดำเนินการโครงการ)'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$arr = json_decode($certRaw, true);
		if (!is_array($arr)) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลลำดับผู้พิจารณาไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$qDec = @mysqli_query(
			$db_Project,
			"SELECT decision FROM `" . $decTable . "` WHERE project_id='" . (int)$project_id . "' AND sort_order='" . (int)$sort_order . "' LIMIT 1"
		);
		$drow = $qDec ? mysqli_fetch_assoc($qDec) : null;
		if ($drow && trim((string)($drow['decision'] ?? '')) !== '') {
			echo json_encode(['ok' => 0, 'msg' => 'ลำดับนี้บันทึกผลการพิจารณาแล้ว แก้ไขชื่อ/ตำแหน่งไม่ได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$found = false;
		$seqNo = 0;
		foreach ($arr as $k => &$it) {
			if (!is_array($it)) {
				continue;
			}
			$seqNo++;
			$soItem = (int)($it['sort_order'] ?? 0);
			if ($soItem <= 0) {
				$soItem = $seqNo;
			}
			if ($soItem === $sort_order) {
				$it['staff_id'] = $new_staff_id;
				$it['position'] = $position_txt;
				if (!isset($it['sort_order']) || (int)$it['sort_order'] <= 0) {
					$it['sort_order'] = $sort_order;
				}
				$found = true;
				break;
			}
		}
		unset($it);
		if (!$found) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบลำดับที่ระบุในลำดับผู้พิจารณา'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$newJson = json_encode($arr, JSON_UNESCAPED_UNICODE);
		if ($newJson === false || $newJson === '') {
			echo json_encode(['ok' => 0, 'msg' => 'สร้างข้อมูลลำดับใหม่ไม่สำเร็จ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$jsonEsc = mysqli_real_escape_string($db_Project, $newJson);
		$okUp = @mysqli_query(
			$db_Project,
			"UPDATE pre_project SET `" . $jsonCol . "`='" . $jsonEsc . "', dates=NOW()
			 WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1"
		);
		if (!$okUp) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		@mysqli_query(
			$db_Project,
			"UPDATE `" . $decTable . "` SET staff_id='" . (int)$new_staff_id . "'
			 WHERE project_id='" . (int)$project_id . "' AND sort_order='" . (int)$sort_order . "'
			   AND (decision IS NULL OR decision='')"
		);
		echo json_encode(['ok' => 1, 'msg' => 'บันทึกการแก้ไขผู้พิจารณาแล้ว'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// แจ้งผลพิจารณาโครงการจากหน่วยแผน (Plan Admin) สำหรับสถานะ 4
if ($op === 'notify_plan_result_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		if (ob_get_level() === 0) {
			@ob_start();
		}
		@ob_clean();
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้งานเมนูนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$budget_code = trim((string)($_POST['budget_code'] ?? ''));
		$budget_other = trim((string)($_POST['budget_other'] ?? ''));
		$approved_budget = isset($_POST['approved_budget']) ? (float)$_POST['approved_budget'] : 0.0;
		$notify_result = trim((string)($_POST['notify_result'] ?? ''));
		$notify_note = trim((string)($_POST['notify_note'] ?? ''));
		$show_on_leave_system = (isset($_POST['show_on_leave_system']) && (string)$_POST['show_on_leave_system'] === '1') ? 1 : 0;
		$allowedResults = ['included', 'included_edit', 'rejected'];
		if ($project_id <= 0 || !in_array($notify_result, $allowedResults, true)) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_exit_if_project_plan_closed')) {
			pm_exit_if_project_plan_closed($db_Project, $project_id);
		}
		if ($notify_result !== 'rejected' && $budget_code === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกแหล่งงบประมาณ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($notify_result === 'rejected') {
			$budget_code = '';
			$budget_other = '';
			$approved_budget = 0.0;
			$show_on_leave_system = 0;
		}
		if ($approved_budget < 0) {
			echo json_encode(['ok' => 0, 'msg' => 'จำนวนเงินอนุมัติต้องไม่ติดลบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (in_array($notify_result, ['included_edit', 'rejected'], true) && $notify_note === '') {
			echo json_encode(['ok' => 0, 'msg' => ($notify_result === 'rejected' ? 'กรุณาระบุเหตุผลที่ไม่ผ่านการพิจารณา' : 'กรุณาระบุรายละเอียดที่ให้แก้ไข')], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$q = @mysqli_query($db_Project, "SELECT id, status_project FROM pre_project WHERE id = " . (int)$project_id . " AND status='1' LIMIT 1");
		$row = $q ? mysqli_fetch_assoc($q) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((string)($row['status_project'] ?? '') !== '4') {
			echo json_encode(['ok' => 0, 'msg' => 'แจ้งผลได้เฉพาะโครงการสถานะนำเข้าที่ประชุม'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$newStatus = '4';
		$resultText = 'บรรจุแผน';
		if ($notify_result === 'included_edit') {
			$newStatus = '8'; // ส่งกลับให้แก้ไขได้
			$resultText = 'บรรจุแผนและแก้ไข';
		} elseif ($notify_result === 'rejected') {
			$newStatus = '9'; // ไม่ผ่าน
			$resultText = 'ไม่ผ่านการพิจารณา';
		}

		$escBudgetCode = mysqli_real_escape_string($db_Project, $budget_code);
		$escBudgetOther = mysqli_real_escape_string($db_Project, $budget_other);
		$escResult = mysqli_real_escape_string($db_Project, $resultText);
		$escNote = mysqli_real_escape_string($db_Project, $notify_note);
		$addColIfMissing = static function ($db, string $col, string $ddl): void {
			$esc = mysqli_real_escape_string($db, $col);
			$q = @mysqli_query($db, "SHOW COLUMNS FROM pre_project LIKE '$esc'");
			$exists = $q && mysqli_num_rows($q) > 0;
			if (!$exists) {
				@mysqli_query($db, "ALTER TABLE pre_project ADD COLUMN $ddl");
			}
		};
		$addColIfMissing($db_Project, 'notify_result', 'notify_result VARCHAR(100) NULL');
		$addColIfMissing($db_Project, 'notify_result_at', 'notify_result_at DATETIME NULL');
		$addColIfMissing($db_Project, 'notify_approved_budget', 'notify_approved_budget DECIMAL(15,2) NULL');
		$addColIfMissing($db_Project, 'notify_result_note', 'notify_result_note TEXT NULL');
		if (function_exists('pm_ensure_show_on_leave_system_schema')) {
			pm_ensure_show_on_leave_system_schema($db_Project);
		}

		$preCols = [];
		$qCols = @mysqli_query($db_Project, "SHOW COLUMNS FROM pre_project");
		if ($qCols) {
			while ($cr = mysqli_fetch_assoc($qCols)) {
				$fn = trim((string)($cr['Field'] ?? ''));
				if ($fn !== '') {
					$preCols[$fn] = true;
				}
			}
		}
		$sets = [];
		if ($notify_result !== 'rejected') {
			if (isset($preCols['code_budget'])) {
				$sets[] = "code_budget = '$escBudgetCode'";
			}
			if (isset($preCols['budget_other'])) {
				$sets[] = "budget_other = " . ($budget_code === '99' ? ("'" . $escBudgetOther . "'") : "IFNULL(budget_other,'')");
			}
			if (isset($preCols['notify_approved_budget'])) {
				$sets[] = "notify_approved_budget = '" . number_format($approved_budget, 2, '.', '') . "'";
			}
		}
		if (isset($preCols['notify_result'])) {
			$sets[] = "notify_result = '$escResult'";
		}
		if (isset($preCols['notify_result_note'])) {
			$sets[] = "notify_result_note = " . ($escNote !== '' ? ("'" . $escNote . "'") : "NULL");
		}
		if (isset($preCols['notify_result_at'])) {
			$sets[] = "notify_result_at = NOW()";
		}
		if (isset($preCols['show_on_leave_system'])) {
			$sets[] = "show_on_leave_system = '" . (int)$show_on_leave_system . "'";
		}
		$sets[] = "status_project = '$newStatus'";
		$sets[] = "dates = NOW()";

		$sql = "UPDATE pre_project
			SET " . implode(",\n\t\t\t\t", $sets) . "
			WHERE id = " . (int)$project_id . " LIMIT 1";
		$ok = @mysqli_query($db_Project, $sql);
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกแจ้งผลไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		// log: เก็บประวัติการแจ้งผล/ตีกลับจากหน่วยแผน
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_plan_review_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			meta_json MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_pprl_project (project_id, created_at),
			KEY idx_pprl_actor (actor_staff_id)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$meta = [
			'notify_result' => $resultText,
			'budget_code' => $budget_code,
			'budget_other' => $budget_other,
			'approved_budget' => $approved_budget,
			'new_status' => $newStatus,
			'show_on_leave_system' => (int)$show_on_leave_system,
		];
		$metaEsc = mysqli_real_escape_string($db_Project, json_encode($meta, JSON_UNESCAPED_UNICODE));
		$noteEsc = mysqli_real_escape_string($db_Project, $notify_note);
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$project_id . "', 'notify_plan_result', '" . (int)$sid . "', " . ($notify_note !== '' ? ("'".$noteEsc."'") : "NULL") . ", '".$metaEsc."', NOW())"
		);
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// Plan Admin: แก้ไขผู้ตรวจสอบ/ผู้พิจารณาในคำขอ "ขอบรรจุโครงการ" (ทุกลำดับ)
if ($op === 'plan_admin_edit_include_cert_row_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ใช้งานเมนูนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$request_id = isset($_POST['request_id']) ? (int)$_POST['request_id'] : 0;
		$sort_order = isset($_POST['sort_order']) ? (int)$_POST['sort_order'] : 0;
		$new_staff_id = isset($_POST['staff_id']) ? (int)$_POST['staff_id'] : 0;
		$position_txt = trim((string)($_POST['position'] ?? ''));
		if ($request_id <= 0 || $sort_order <= 0 || $new_staff_id <= 0 || $position_txt === '') {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ครบ'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		// ensure tables exist (บาง DB ยังไม่ถูก create)
		if (function_exists('ensureIncludeRequestTables')) {
			ensureIncludeRequestTables($db_Project);
		}

		$qDec = @mysqli_query(
			$db_Project,
			"SELECT decision FROM project_include_request_certifier_decision
			 WHERE request_id='" . (int)$request_id . "'
			   AND sort_order='" . (int)$sort_order . "'
			 LIMIT 1"
		);
		$drow = $qDec ? mysqli_fetch_assoc($qDec) : null;
		$existingDec = trim((string)($drow['decision'] ?? ''));
		if ($existingDec === 'approved') {
			echo json_encode(['ok' => 0, 'msg' => 'ผู้ตรวจสอบลำดับนี้ผ่านการพิจารณาแล้ว ไม่สามารถแก้ไขได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($existingDec === 'rejected') {
			echo json_encode(['ok' => 0, 'msg' => 'ผู้ตรวจสอบลำดับนี้บันทึกผลแล้ว ไม่สามารถแก้ไขได้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$posEsc = mysqli_real_escape_string($db_Project, $position_txt);
		$ok = @mysqli_query(
			$db_Project,
			"UPDATE project_include_request_certifier
			 SET staff_id='" . (int)$new_staff_id . "',
			     position_title='" . $posEsc . "'
			 WHERE request_id='" . (int)$request_id . "'
			   AND sort_order='" . (int)$sort_order . "'
			 LIMIT 1"
		);
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}

		// ถ้าแถว decision ยังไม่ตัดสิน ให้ sync staff_id ตามผู้ตรวจสอบใหม่
		@mysqli_query(
			$db_Project,
			"UPDATE project_include_request_certifier_decision
			 SET staff_id='" . (int)$new_staff_id . "'
			 WHERE request_id='" . (int)$request_id . "'
			   AND sort_order='" . (int)$sort_order . "'
			   AND (decision IS NULL OR decision='')"
		);

		// log (ถ้าตารางมี)
		$meta = [
			'action' => 'plan_admin_edit_include_cert_row',
			'request_id' => $request_id,
			'sort_order' => $sort_order,
			'new_staff_id' => $new_staff_id,
			'position' => $position_txt,
		];
		$metaEsc = mysqli_real_escape_string($db_Project, json_encode($meta, JSON_UNESCAPED_UNICODE));
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_include_request_action_log (request_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$request_id . "', 'plan_admin_edit_cert_row', '" . (int)$sid . "', NULL, '" . $metaEsc . "', NOW())"
		);

		echo json_encode(['ok' => 1, 'msg' => 'บันทึกการแก้ไขผู้ตรวจสอบแล้ว'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

