// ผู้ยื่นยืนยันการแก้ไขโครงการหลังถูกตีกลับขอบรรจุ (รายโครงการ)
if ($op === 'confirm_include_project_fix_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$request_id = isset($_POST['request_id']) ? (int)$_POST['request_id'] : 0;
		$fix_note = trim((string)($_POST['fix_note'] ?? ''));
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$scode = '';
		$cunit = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			if ($st) {
				mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
				mysqli_stmt_execute($st);
				$rs = mysqli_stmt_get_result($st);
				$rw = $rs ? mysqli_fetch_assoc($rs) : null;
				$sid = (int)($rw['id'] ?? 0);
				$scode = (string)($rw['code'] ?? '');
				$cunit = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($project_id <= 0 || $sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($fix_note === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกคำชี้แจงการแก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('ensureIncludeRequestTables')) {
			ensureIncludeRequestTables($db_Project);
		}
		if ($request_id <= 0) {
			$qFind = @mysqli_query(
				$db_Project,
				"SELECT i.request_id
				 FROM project_include_request_item i
				 JOIN project_include_request r ON r.id = i.request_id
				 WHERE i.project_id='" . (int)$project_id . "'
				   AND IFNULL(i.return_selected,0)=1
				   AND IFNULL(i.fix_status,'') IN ('','pending')
				   AND r.status='rejected'
				 ORDER BY i.id DESC LIMIT 1"
			);
			$fr = $qFind ? mysqli_fetch_assoc($qFind) : null;
			$request_id = (int)($fr['request_id'] ?? 0);
		}
		if ($request_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบคำขอตีกลับของโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$qItem = @mysqli_query(
			$db_Project,
			"SELECT i.*, r.submitter_staff_id, r.status AS req_status, p.code_pre_project, p.name_project, p.status_project
			 FROM project_include_request_item i
			 JOIN project_include_request r ON r.id = i.request_id
			 JOIN pre_project p ON p.id = i.project_id
			 WHERE i.request_id='" . (int)$request_id . "' AND i.project_id='" . (int)$project_id . "' LIMIT 1"
		);
		$item = $qItem ? mysqli_fetch_assoc($qItem) : null;
		if (!$item || (string)($item['req_status'] ?? '') !== 'rejected' || (int)($item['return_selected'] ?? 0) !== 1) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ไม่ได้อยู่ในรายการที่ถูกตีกลับ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$fst = trim((string)($item['fix_status'] ?? ''));
		if ($fst === 'confirmed' || $fst === 'admin_sent') {
			echo json_encode(['ok' => 0, 'msg' => 'ยืนยันการแก้ไขไปแล้ว'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$canEdit = ((int)($item['submitter_staff_id'] ?? 0) === $sid)
			|| (function_exists('staffCanEditPreProjectRichFields') && staffCanEditPreProjectRichFields($db_Project, $project_id, $sid, $scode, $cunit));
		if (!$canEdit) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ยืนยันการแก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$noteEsc = mysqli_real_escape_string($db_Project, $fix_note);
		@mysqli_query(
			$db_Project,
			"UPDATE project_include_request_item
			 SET fix_note='" . $noteEsc . "',
			     fix_at=NOW(),
			     fix_staff_id='" . (int)$sid . "',
			     fix_status='confirmed'
			 WHERE request_id='" . (int)$request_id . "' AND project_id='" . (int)$project_id . "' LIMIT 1"
		);
		@mysqli_query(
			$db_Project,
			"UPDATE pre_project SET status_project='3', dates=NOW()
			 WHERE id='" . (int)$project_id . "' AND status='1' AND status_project IN ('8','2','3') LIMIT 1"
		);
		$metaEsc = mysqli_real_escape_string($db_Project, json_encode([
			'project_id' => $project_id,
			'code' => (string)($item['code_pre_project'] ?? ''),
			'name' => (string)($item['name_project'] ?? ''),
			'fix_note' => $fix_note,
		], JSON_UNESCAPED_UNICODE));
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_include_request_action_log (request_id, action_type, actor_staff_id, sort_order, note, meta_json, created_at)
			 VALUES ('" . (int)$request_id . "', 'project_fix_confirmed', '" . (int)$sid . "', 0, '" . $noteEsc . "', '" . $metaEsc . "', NOW())"
		);
		$projLabel = trim((string)(($item['code_pre_project'] ?? '') . ' ' . ($item['name_project'] ?? '')));
		$link = '?page=project_approve&request_id=' . (int)$request_id . '&project_group=history';
		if (function_exists('pm_notify_unit_admins_for_project')) {
			pm_notify_unit_admins_for_project(
				$db_Project,
				$db_person,
				$project_id,
				'include_project_fix_confirmed',
				'ยืนยันการแก้ไขโครงการ',
				'ผู้ใช้ยืนยันการแก้ไขโครงการ: ' . ($projLabel !== '' ? $projLabel : ('#' . $project_id)),
				$link
			);
		}
		// แจ้งผู้ยื่นเสนอคำขอ (ถ้าไม่ใช่คนที่ยืนยันเอง)
		$submitterId = (int)($item['submitter_staff_id'] ?? 0);
		if ($submitterId > 0 && $submitterId !== $sid && function_exists('pm_staff_notify')) {
			pm_staff_notify(
				$db_Project,
				$submitterId,
				'include_project_fix_confirmed',
				'ยืนยันการแก้ไขโครงการ',
				'มีการยืนยันการแก้ไขโครงการในคำขอ #' . $request_id . ': ' . ($projLabel !== '' ? $projLabel : ('#' . $project_id)),
				$link,
				'include_request',
				$request_id
			);
		}
		echo json_encode([
			'ok' => 1,
			'msg' => 'ยืนยันการแก้ไขเรียบร้อย — โครงการถูกล็อกเป็นรอบรรจุแล้ว',
			'request_id' => $request_id,
			'status_project' => '3',
		], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ผู้ยื่นบันทึกรายละเอียดการแก้ไข (กรณีผลพิจารณา = บรรจุแผนและแก้ไข)
if ($op === 'save_user_fix_note_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$fix_note = trim((string)($_POST['fix_note'] ?? ''));
			$sess_email = $_SESSION['r_email'] ?? '';
			$sess_code = $_SESSION['code'] ?? '';
			$sid = 0;
			if ($sess_email !== '' && $sess_code !== '') {
				$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
				if ($st) {
					mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
					mysqli_stmt_execute($st);
					$rs = mysqli_stmt_get_result($st);
					$rw = $rs ? mysqli_fetch_assoc($rs) : null;
					$sid = (int)($rw['id'] ?? 0);
				}
			}
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (function_exists('pm_exit_if_project_plan_closed')) {
			pm_exit_if_project_plan_closed($db_Project, $project_id);
		}
		if ($sid <= 0) {
			// ต้องมี staff_id เพื่อเก็บลงฐานข้อมูลและแสดงชื่อในประวัติ
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเข้าสู่ระบบใหม่อีกครั้ง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($fix_note === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกรายละเอียดการแก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$q = @mysqli_query($db_Project, "SELECT id, status_project, notify_result FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $q ? mysqli_fetch_assoc($q) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$st = (string)($row['status_project'] ?? '');
		$nr = trim((string)($row['notify_result'] ?? ''));
		$nrOk = ($nr === 'บรรจุแผนและแก้ไข' || $nr === 'บรรจุและแก้ไข');
		if (!($st === '8' && $nrOk)) {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ไม่อยู่ในสถานะที่ต้องบันทึกรายละเอียดการแก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$addColIfMissing = static function ($db, string $col, string $ddl): void {
			$esc = mysqli_real_escape_string($db, $col);
			$qCol = @mysqli_query($db, "SHOW COLUMNS FROM pre_project LIKE '$esc'");
			if (!$qCol || mysqli_num_rows($qCol) === 0) {
				@mysqli_query($db, "ALTER TABLE pre_project ADD COLUMN $ddl");
			}
		};
		$addColIfMissing($db_Project, 'user_fix_note', 'user_fix_note TEXT NULL');
		$addColIfMissing($db_Project, 'user_fix_note_at', 'user_fix_note_at DATETIME NULL');
			$addColIfMissing($db_Project, 'user_fix_note_staff_id', 'user_fix_note_staff_id INT NULL');
		$escNote = mysqli_real_escape_string($db_Project, $fix_note);
			$ok = @mysqli_query($db_Project, "UPDATE pre_project SET user_fix_note='$escNote', user_fix_note_at=NOW(), user_fix_note_staff_id='" . (int)$sid . "', dates=NOW() WHERE id='" . (int)$project_id . "' LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		// log: เก็บประวัติการยืนยันการแก้ไขของผู้ยื่น
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_plan_review_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			meta_json MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_pprl_project (project_id, created_at),
			KEY idx_pprl_actor (actor_staff_id)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$noteEsc2 = mysqli_real_escape_string($db_Project, $fix_note);
		$metaEsc2 = mysqli_real_escape_string($db_Project, json_encode(['staff_id' => (int)$sid], JSON_UNESCAPED_UNICODE));
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$project_id . "', 'user_fix_note', '" . (int)$sid . "', " . ($fix_note !== '' ? ("'".$noteEsc2."'") : "NULL") . ", '".$metaEsc2."', NOW())"
		);
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ผู้ยื่นบันทึกคำชี้แจงกรณี "ขอดำเนินการโครงการ" ถูกตีกลับให้แก้ไข
if ($op === 'save_operate_submitter_reply_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		$reply_note = trim((string)($_POST['reply_note'] ?? ''));
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ($reply_note === '') {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกคำชี้แจงก่อนบันทึก'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			if ($st) {
				mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
				mysqli_stmt_execute($st);
				$rs = mysqli_stmt_get_result($st);
				$rw = $rs ? mysqli_fetch_assoc($rs) : null;
				if ($rw) {
					$sid = (int)($rw['id'] ?? 0);
					$staff_code = (string)($rw['code'] ?? '');
					$unit_code = (string)($rw['unit_code'] ?? '');
				}
			}
		}
		if ($sid <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเข้าสู่ระบบใหม่อีกครั้ง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (!function_exists('staffCanViewPreProjectManageDetail') || !staffCanViewPreProjectManageDetail($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$q = @mysqli_query($db_Project, "SELECT id, status_project, notify_result, operate_certifiers_json, operate_approvers_json, name_project, code_pre_project FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $q ? mysqli_fetch_assoc($q) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$stNow = (string)($row['status_project'] ?? '');
		$notifyResult = trim((string)($row['notify_result'] ?? ''));
		if ($stNow !== '8' || $notifyResult !== 'บรรจุแผน') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการนี้ยังไม่อยู่สถานะตีกลับเพื่อแก้ไขจากขั้นตอนขอดำเนินการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$addColIfMissing = static function ($db, string $col, string $ddl): void {
			$esc = mysqli_real_escape_string($db, $col);
			$qC = @mysqli_query($db, "SHOW COLUMNS FROM pre_project LIKE '$esc'");
			if (!$qC || mysqli_num_rows($qC) === 0) {
				@mysqli_query($db, "ALTER TABLE pre_project ADD COLUMN $ddl");
			}
		};
		$addColIfMissing($db_Project, 'operate_submitter_reply_note', 'operate_submitter_reply_note MEDIUMTEXT NULL');
		$addColIfMissing($db_Project, 'operate_submitter_reply_updated_at', 'operate_submitter_reply_updated_at DATETIME NULL');
		$addColIfMissing($db_Project, 'operate_submitter_reply_staff_id', 'operate_submitter_reply_staff_id INT UNSIGNED NULL');

		$escNote = mysqli_real_escape_string($db_Project, $reply_note);
		$ok = @mysqli_query(
			$db_Project,
			"UPDATE pre_project
			 SET operate_submitter_reply_note='" . $escNote . "',
			     operate_submitter_reply_updated_at=NOW(),
			     operate_submitter_reply_staff_id='" . (int)$sid . "',
			     status_project='1',
			     dates=NOW()
			 WHERE id='" . (int)$project_id . "'
			 LIMIT 1"
		);
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$replySort = 1;
		$decTableClear = 'project_operate_certifier_decision';
		$rejectedByApprover = false;
		$firstCertSid = 0;
		$certRawFirst = trim((string)($row['operate_certifiers_json'] ?? ''));
		$certArrFirst = $certRawFirst !== '' ? json_decode($certRawFirst, true) : [];
		if (is_array($certArrFirst)) {
			$nSoFirst = 0;
			$bestSoFirst = PHP_INT_MAX;
			foreach ($certArrFirst as $cFirst) {
				if (!is_array($cFirst)) {
					continue;
				}
				$nSoFirst++;
				$soFirst = (int)($cFirst['sort_order'] ?? 0);
				if ($soFirst <= 0) {
					$soFirst = $nSoFirst;
				}
				$sidFirst = (int)($cFirst['staff_id'] ?? 0);
				if ($sidFirst > 0 && $soFirst < $bestSoFirst) {
					$bestSoFirst = $soFirst;
					$firstCertSid = $sidFirst;
				}
			}
		}
		$qLastReject = @mysqli_query(
			$db_Project,
			"SELECT sort_order
			 FROM project_operate_certifier_decision
			 WHERE project_id='" . (int)$project_id . "' AND decision='rejected'
			 ORDER BY decided_at DESC, id DESC
			 LIMIT 1"
		);
		$rLastReject = $qLastReject ? mysqli_fetch_assoc($qLastReject) : null;
		if (!$rLastReject) {
			$qLastRejectAp = @mysqli_query(
				$db_Project,
				"SELECT sort_order
				 FROM project_operate_approver_decision
				 WHERE project_id='" . (int)$project_id . "' AND decision='rejected'
				 ORDER BY decided_at DESC, id DESC
				 LIMIT 1"
			);
			$rLastReject = $qLastRejectAp ? mysqli_fetch_assoc($qLastRejectAp) : null;
			if ($rLastReject) {
				$rejectedByApprover = true;
				$decTableClear = 'project_operate_approver_decision';
			}
		}
		$didClearReject = false;
		if ($rejectedByApprover) {
			$replySort = 1;
			$didClearReject = true;
			@mysqli_query(
				$db_Project,
				"DELETE FROM project_operate_certifier_decision
				 WHERE project_id='" . (int)$project_id . "'"
			);
			@mysqli_query(
				$db_Project,
				"DELETE FROM project_operate_approver_decision
				 WHERE project_id='" . (int)$project_id . "'"
			);
		} elseif ($rLastReject && (int)($rLastReject['sort_order'] ?? 0) > 0) {
			$replySort = (int)$rLastReject['sort_order'];
			$didClearReject = true;
			@mysqli_query(
				$db_Project,
				"DELETE FROM `" . $decTableClear . "`
				 WHERE project_id='" . (int)$project_id . "'
				   AND sort_order >= '" . (int)$replySort . "'"
			);
		}

		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_plan_review_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			meta_json MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_pprl_project (project_id, created_at),
			KEY idx_pprl_actor (actor_staff_id)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$metaEsc = mysqli_real_escape_string($db_Project, json_encode([
			'status_project' => $stNow,
			'notify_result' => $notifyResult,
			'reset_to_status' => '1',
			'cleared_from_sort' => (int)$replySort,
			'cleared_table' => $decTableClear,
			'rejected_by_approver' => $rejectedByApprover ? 1 : 0,
			'notify_first_certifier' => (int)$firstCertSid,
		], JSON_UNESCAPED_UNICODE));
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$project_id . "', 'operate_submitter_reply', '" . (int)$sid . "', '" . $escNote . "', '" . $metaEsc . "', NOW())"
		);
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_operate_action_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			sort_order TINYINT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_poal_project (project_id, created_at),
			KEY idx_poal_actor (actor_staff_id),
			KEY idx_poal_sort (project_id, sort_order)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		@mysqli_query(
			$db_Project,
			"INSERT INTO project_operate_action_log (project_id, action_type, actor_staff_id, sort_order, note, created_at)
			 VALUES ('" . (int)$project_id . "', 'submitter_reply_saved', '" . (int)$sid . "', '" . (int)$replySort . "', '" . $escNote . "', NOW())"
		);

		$notifySid = 0;
		if ($rejectedByApprover) {
			$notifySid = (int)$firstCertSid;
		} elseif (!empty($didClearReject)) {
			$chainRaw = trim((string)($row['operate_certifiers_json'] ?? ''));
			$chainArr = $chainRaw !== '' ? json_decode($chainRaw, true) : [];
			if (is_array($chainArr)) {
				$nSo = 0;
				foreach ($chainArr as $cN) {
					if (!is_array($cN)) {
						continue;
					}
					$nSo++;
					$soN = (int)($cN['sort_order'] ?? 0);
					if ($soN <= 0) {
						$soN = $nSo;
					}
					if ($soN === (int)$replySort) {
						$notifySid = (int)($cN['staff_id'] ?? 0);
						break;
					}
				}
			}
		} else {
			$qPaRet = @mysqli_query(
				$db_Project,
				"SELECT actor_staff_id
				 FROM project_operate_action_log
				 WHERE project_id='" . (int)$project_id . "' AND action_type='plan_admin_operate_returned'
				 ORDER BY id DESC LIMIT 1"
			);
			$rPaRet = $qPaRet ? mysqli_fetch_assoc($qPaRet) : null;
			$notifySid = (int)($rPaRet['actor_staff_id'] ?? 0);
		}
		if ($notifySid <= 0) {
			$notifySid = (int)$firstCertSid;
		}
		$projLabel = trim((string)(($row['code_pre_project'] ?? '') . ' ' . ($row['name_project'] ?? '')));
		$linkAppr = '?page=project_approve&flow=operate&tab=pending&open_project_id=' . (int)$project_id . '&project_id=' . (int)$project_id;
		if ($notifySid > 0 && $notifySid !== (int)$sid && function_exists('pm_staff_notify')) {
			pm_staff_notify(
				$db_Project,
				$notifySid,
				'operate_resubmit',
				'ผู้ยื่นแก้ไขส่งกลับให้ตรวจสอบ',
				($projLabel !== '' ? $projLabel : ('โครงการ #' . (int)$project_id)),
				$linkAppr,
				'pre_project',
				(int)$project_id
			);
		}
		if (function_exists('pm_approve_inbox_clear_read')) {
			pm_approve_inbox_clear_read($db_Project, 'operate', 'operate:' . (int)$project_id);
		}

		echo json_encode(['ok' => 1, 'msg' => 'ส่งกลับผู้รับรองเรียบร้อย'], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

