		$q = @mysqli_query($db_Project, "SELECT id, status_project, notify_result, user_fix_note FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $q ? mysqli_fetch_assoc($q) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((string)($row['status_project'] ?? '') !== '8') {
