			echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกความเห็นจากหน่วยแผนและงบประมาณก่อนตีกลับแก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id FROM staff WHERE email = ? AND code = ? LIMIT 1');
			if ($st) {
				mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
				mysqli_stmt_execute($st);
				$rs = mysqli_stmt_get_result($st);
				$rw = $rs ? mysqli_fetch_assoc($rs) : null;
				$sid = (int)($rw['id'] ?? 0);
			}
		}

		$q = @mysqli_query($db_Project, "SELECT id, staff_insert, code_pre_project, name_project, status_project, notify_result, user_fix_note FROM pre_project WHERE id='" . (int)$project_id . "' AND status='1' LIMIT 1");
		$row = $q ? mysqli_fetch_assoc($q) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((string)($row['status_project'] ?? '') !== '8') {
			echo json_encode(['ok' => 0, 'msg' => 'โครงการไม่อยู่ในสถานะตีกลับให้แก้ไข'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($row['notify_result'] ?? '')) !== 'บรรจุแผนและแก้ไข') {
			echo json_encode(['ok' => 0, 'msg' => 'ผลการพิจารณาไม่ตรงกับขั้นตอนนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (trim((string)($row['user_fix_note'] ?? '')) === '') {
			echo json_encode(['ok' => 0, 'msg' => 'ยังไม่มีการยืนยันการแก้ไขจากผู้ยื่น'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$addColIfMissing = static function ($db, string $col, string $ddl): void {
			$esc = mysqli_real_escape_string($db, $col);
			$qCol = @mysqli_query($db, "SHOW COLUMNS FROM pre_project LIKE '$esc'");
			if (!$qCol || mysqli_num_rows($qCol) === 0) {
				@mysqli_query($db, "ALTER TABLE pre_project ADD COLUMN $ddl");
			}
		};
		$addColIfMissing($db_Project, 'notify_result_note', 'notify_result_note TEXT NULL');
		$addColIfMissing($db_Project, 'notify_result_at', 'notify_result_at DATETIME NULL');
		$addColIfMissing($db_Project, 'plan_budget_unit_finalize_note', 'plan_budget_unit_finalize_note TEXT NULL');
		$addColIfMissing($db_Project, 'user_fix_note', 'user_fix_note TEXT NULL');
		$addColIfMissing($db_Project, 'user_fix_note_at', 'user_fix_note_at DATETIME NULL');
		$addColIfMissing($db_Project, 'user_fix_note_staff_id', 'user_fix_note_staff_id INT NULL');

		$escNote = mysqli_real_escape_string($db_Project, $review_note);
		$sets = [
			"status_project = '8'",
			"notify_result = 'บรรจุแผนและแก้ไข'",
			"notify_result_note = '" . $escNote . "'",
			"notify_result_at = NOW()",
			"plan_budget_unit_finalize_note = '" . $escNote . "'",
			"user_fix_note = NULL",
			"user_fix_note_at = NULL",
			"user_fix_note_staff_id = NULL",
			"dates = NOW()",
		];
		$sql = 'UPDATE pre_project SET ' . implode(', ', $sets) . " WHERE id='" . (int)$project_id . "' AND status='1' AND status_project='8' LIMIT 1";
		$ok = @mysqli_query($db_Project, $sql);
		if (!$ok || mysqli_affected_rows($db_Project) < 1) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'บันทึกไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		// log: ตีกลับแก้ไข (วนรอบ)
		@mysqli_query($db_Project, "CREATE TABLE IF NOT EXISTS project_plan_review_log (
			id INT UNSIGNED NOT NULL AUTO_INCREMENT,
			project_id INT UNSIGNED NOT NULL,
			action_type VARCHAR(32) NOT NULL DEFAULT '',
			actor_staff_id INT UNSIGNED NULL,
			note MEDIUMTEXT NULL,
			meta_json MEDIUMTEXT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY idx_pprl_project (project_id, created_at),
			KEY idx_pprl_actor (actor_staff_id)
		) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
		$noteEsc4 = mysqli_real_escape_string($db_Project, $review_note);
		@mysqli_query(
			$db_Project,
			"			INSERT INTO project_plan_review_log (project_id, action_type, actor_staff_id, note, meta_json, created_at)
			 VALUES ('" . (int)$project_id . "', 'return_edit', '" . (int)$sid . "', '" . $noteEsc4 . "', '', NOW())"
		);
		$submitterFix = (int)($row['staff_insert'] ?? 0);
		$pLabelFix = trim((string)(($row['code_pre_project'] ?? '') . ' ' . ($row['name_project'] ?? '')));
		$bodyFix = $pLabelFix !== '' ? $pLabelFix : ('โครงการ #' . (int)$project_id);
		if ($review_note !== '') {
			$bodyFix .= "\nข้อแก้ไข: " . $review_note;
		}
		$linkFix = '?page=project_approve&flow=include&tab=sent&open_project_id=' . (int)$project_id . '&project_id=' . (int)$project_id;
		if (function_exists('pm_notify_revision_needed')) {
			pm_notify_revision_needed($db_Project, [$submitterFix], 'include_plan_returned', 'หน่วยแผนตีกลับให้แก้ไขโครงการ', $bodyFix, $linkFix, 'pre_project', (int)$project_id, (int)$sid);
		} elseif ($submitterFix > 0 && $submitterFix !== (int)$sid && function_exists('pm_staff_notify')) {
			pm_staff_notify($db_Project, $submitterFix, 'include_plan_returned', 'หน่วยแผนตีกลับให้แก้ไขโครงการ', $bodyFix, $linkFix, 'pre_project', (int)$project_id);
		}
		if (function_exists('pm_approve_inbox_clear_read')) {
			pm_approve_inbox_clear_read($db_Project, 'include', 'include-fix:' . (int)$project_id);
		}
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: ' . $e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ลบโครงการ (เฉพาะสถานะร่าง) แบบ AJAX
if ($op === 'delete_draft_project_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
		if ($project_id <= 0) {
			echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || !function_exists('staffCanEditPreProjectRichFields') || !staffCanEditPreProjectRichFields($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์ลบโครงการนี้'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$chk = @mysqli_query($db_Project, "SELECT id, status_project, status FROM pre_project WHERE id='".(int)$project_id."' LIMIT 1");
		$row = $chk ? mysqli_fetch_assoc($chk) : null;
		if (!$row) {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if ((string)($row['status_project'] ?? '') !== '0') {
			echo json_encode(['ok' => 0, 'msg' => 'ลบได้เฉพาะโครงการสถานะร่างเท่านั้น'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		$ok = @mysqli_query($db_Project, "UPDATE pre_project SET status='99', dates=NOW(), staff_insert='".(int)$sid."' WHERE id='".(int)$project_id."' AND status_project='0' LIMIT 1");
		if (!$ok) {
			echo json_encode(['ok' => 0, 'msg' => (mysqli_error($db_Project) ?: 'ลบไม่สำเร็จ')], JSON_UNESCAPED_UNICODE);
			exit;
		}
		echo json_encode(['ok' => 1], JSON_UNESCAPED_UNICODE);
