	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: '.$e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ขอบรรจุโครงการ (Admin หน่วยงาน) แบบหลายรายการ
if ($op === 'request_include_projects_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	try {
		$listRaw = $_POST['project_ids'] ?? [];
		if (is_string($listRaw)) {
			$listRaw = explode(',', $listRaw);
		}
		if (!is_array($listRaw)) {
			$listRaw = [];
		}
		$projectIds = [];
		foreach ($listRaw as $v) {
			$id = (int)$v;
			if ($id > 0) $projectIds[$id] = $id;
		}
		$projectIds = array_values($projectIds);
		if (empty($projectIds)) {
			echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกโครงการ'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		$sess_email = $_SESSION['r_email'] ?? '';
		$sess_code = $_SESSION['code'] ?? '';
		$sid = 0;
		$staff_code = '';
		$unit_code = '';
		if ($sess_email !== '' && $sess_code !== '') {
			$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
			mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
			mysqli_stmt_execute($st);
			$rs = mysqli_stmt_get_result($st);
			$rw = $rs ? mysqli_fetch_assoc($rs) : null;
			if ($rw) {
				$sid = (int)($rw['id'] ?? 0);
				$staff_code = (string)($rw['code'] ?? '');
				$unit_code = (string)($rw['unit_code'] ?? '');
			}
		}
		if ($sid <= 0 || $staff_code === '') {
			echo json_encode(['ok' => 0, 'msg' => 'ไม่พบข้อมูลผู้ใช้'], JSON_UNESCAPED_UNICODE);
			exit;
		}
		if (!function_exists('isUnitAdmin') || !isUnitAdmin($db_Project, $staff_code, $unit_code, $sid)) {
			echo json_encode(['ok' => 0, 'msg' => 'เฉพาะ Admin หน่วยงานเท่านั้น'], JSON_UNESCAPED_UNICODE);
			exit;
		}

		if (function_exists('ensureProjectExtraSchema')) {
			ensureProjectExtraSchema($db_Project);
		}
		if (function_exists('ensureIncludeRequestTables')) {
			ensureIncludeRequestTables($db_Project);
		}

		$section_name = isset($_POST['section_name']) ? (string)$_POST['section_name'] : '';
		$subject = isset($_POST['subject']) ? (string)$_POST['subject'] : '';
		if (function_exists('pm_include_request_subject_label')) {
			$subject = pm_include_request_subject_label($subject);
		}
		$letter_body = isset($_POST['letter_body']) ? (string)$_POST['letter_body'] : '';
		$budget_year = isset($_POST['budget_year']) ? trim((string)$_POST['budget_year']) : '';

		$summaryIn = isset($_POST['summary_rows_json']) ? (string)$_POST['summary_rows_json'] : '';
		$summaryRows = json_decode($summaryIn, true);
		if (!is_array($summaryRows)) {
			$summaryRows = [];
		}

		$resubmitFromId = isset($_POST['resubmit_from_request_id']) ? (int)$_POST['resubmit_from_request_id'] : 0;
		$isResubmitFlow = false;
		$certNormalized = [];

		if ($resubmitFromId > 0) {
			if (!function_exists('ensureIncludeRequestTables')) {
				echo json_encode(['ok' => 0, 'msg' => 'ระบบคำขอไม่พร้อม'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			ensureIncludeRequestTables($db_Project);
			$qrq = @mysqli_query(
				$db_Project,
				"SELECT id, status FROM project_include_request WHERE id='" . $resubmitFromId . "' LIMIT 1"
			);
			$rrq = $qrq ? mysqli_fetch_assoc($qrq) : null;
			if (!$rrq || (string)($rrq['status'] ?? '') !== 'rejected') {
				echo json_encode(['ok' => 0, 'msg' => 'คำขอไม่ใช่สถานะตีกลับ หรือไม่พบคำขอ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$itemList = [];
			$qit = @mysqli_query(
				$db_Project,
				"SELECT project_id FROM project_include_request_item WHERE request_id='" . $resubmitFromId . "' ORDER BY sort_order ASC"
			);
			while ($qit && ($rit = mysqli_fetch_assoc($qit))) {
				$ip = (int)($rit['project_id'] ?? 0);
				if ($ip > 0) {
					$itemList[] = $ip;
				}
			}
			sort($itemList, SORT_NUMERIC);
			$selSorted = $projectIds;
			sort($selSorted, SORT_NUMERIC);
			if ($itemList !== $selSorted) {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกโครงการในคำขอที่ถูกตีกลับครบทุกรายการตามชุดเดิม'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			$isResubmitFlow = true;
			$qce = @mysqli_query(
				$db_Project,
				"SELECT staff_id, position_title FROM project_include_request_certifier WHERE request_id='" . (int)$resubmitFromId . "' ORDER BY sort_order ASC"
			);
			while ($qce && ($rce = mysqli_fetch_assoc($qce))) {
				$cSid = (int)($rce['staff_id'] ?? 0);
				$cPos = trim((string)($rce['position_title'] ?? ''));
				if ($cSid <= 0 || $cPos === '') {
					continue;
				}
				$certNormalized[] = ['staff_id' => $cSid, 'position' => $cPos];
			}
			if (count($certNormalized) === 0) {
				echo json_encode(['ok' => 0, 'msg' => 'ไม่พบข้อมูลผู้รับรองในคำขอเดิม กรุณาติดต่อผู้ดูแลระบบ'], JSON_UNESCAPED_UNICODE);
				exit;
			}
		} else {
			$certIn = isset($_POST['certifiers_json']) ? (string)$_POST['certifiers_json'] : '';
			$certArr = json_decode($certIn, true);
			if (!is_array($certArr) || count($certArr) === 0) {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน และเรียงลำดับการพิจารณา (คนสุดท้ายลงนามก่อนส่งแผน)'], JSON_UNESCAPED_UNICODE);
				exit;
			}
			foreach ($certArr as $crow) {
				if (!is_array($crow)) {
					continue;
				}
				$cSid = (int)($crow['staff_id'] ?? 0);
				$cPos = trim((string)($crow['position'] ?? ''));
				if ($cSid <= 0 || $cPos === '') {
					echo json_encode(['ok' => 0, 'msg' => 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับ'], JSON_UNESCAPED_UNICODE);
					exit;
				}
				$certNormalized[] = ['staff_id' => $cSid, 'position' => $cPos];
			}
			if (count($certNormalized) === 0) {
				echo json_encode(['ok' => 0, 'msg' => 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน'], JSON_UNESCAPED_UNICODE);
				exit;
			}
		}
		$certJsonEsc = mysqli_real_escape_string($db_Project, json_encode($certNormalized, JSON_UNESCAPED_UNICODE));

		$in = implode(',', array_map('intval', $projectIds));
		$staffIdSql = (int) $sid;
		$resubmitIdSql = (int)$resubmitFromId;
		// ขอบรรจุได้เฉพาะโครงการที่หน่วยของ Admin เป็นหน่วยงานหลัก (ไม่รวมหน่วยงานร่วม)
		$unitKeys = function_exists('planCollectStaffUnitScopeKeys')
			? planCollectStaffUnitScopeKeys($db_Project, $staffIdSql, (string)$unit_code)
			: [];
		$unitKeys = array_values(array_filter(array_map('strval', $unitKeys), static function ($k) {
			return trim($k) !== '';
		}));
		$mainUnitScopeSql = '1=0';
		if (!empty($unitKeys)) {
			$inList = [];
			foreach ($unitKeys as $uk) {
				$inList[] = "'" . mysqli_real_escape_string($db_Project, $uk) . "'";
			}
			$inSql = implode(',', $inList);
			$mainUnitScopeSql = "
				IFNULL(p.code_unit,'') <> ''
				AND (
					p.code_unit IN ($inSql)
					OR EXISTS (
						SELECT 1 FROM set_unit su
						WHERE su.status != '99'
						  AND (CAST(su.id AS CHAR) = p.code_unit OR IFNULL(su.code,'') = p.code_unit)
						  AND (CAST(su.id AS CHAR) IN ($inSql) OR IFNULL(su.code,'') IN ($inSql))
					)
				)
			";
		}
		$scopeAdminMatch = "($mainUnitScopeSql)";
		if ($isResubmitFlow) {
			$sql = "
			UPDATE pre_project p
			SET p.status_project = '3', p.dates = NOW(), p.include_certifiers_json = '$certJsonEsc'
			WHERE p.id IN ($in)
			  AND p.status = '1'
			  AND p.status_project IN ('2','8')
			  AND EXISTS (
				  SELECT 1 FROM project_include_request_item pi
				  WHERE pi.request_id = '".$resubmitIdSql."' AND pi.project_id = p.id
			  )
			  AND (
			  $scopeAdminMatch
			  )
		";
		} else {
			$sql = "
			UPDATE pre_project p
			SET p.status_project = '3', p.dates = NOW(), p.include_certifiers_json = '$certJsonEsc'
			WHERE p.id IN ($in)
			  AND p.status = '1'
			  AND p.status_project = '2'
			  AND (
			  $scopeAdminMatch
			  )
		";
		}

		@mysqli_begin_transaction($db_Project);
		try {
			// ตรวจสิทธิ์/สถานะก่อนบันทึกคำขอ — กันกรณีเห็นในรายการแต่ UPDATE ไม่ติด
			$preCheckSql = "
				SELECT p.id, p.status_project, p.code_unit
				FROM pre_project p
				WHERE p.id IN ($in)
				  AND p.status = '1'
			";
			$qPre = @mysqli_query($db_Project, $preCheckSql);
			$foundIds = [];
			$wrongStatus = [];
			while ($qPre && ($pr = mysqli_fetch_assoc($qPre))) {
				$pid = (int)($pr['id'] ?? 0);
				if ($pid <= 0) {
					continue;
				}
				$foundIds[$pid] = true;
				$st = (string)($pr['status_project'] ?? '');
				$okSt = $isResubmitFlow ? in_array($st, ['2', '8'], true) : ($st === '2');
				if (!$okSt) {
					$wrongStatus[] = $pid;
				}
			}
			$missing = [];
			foreach ($projectIds as $pid) {
				if (!isset($foundIds[(int)$pid])) {
					$missing[] = (int)$pid;
				}
			}
			if (!empty($missing)) {
				throw new RuntimeException('ไม่พบโครงการที่เลือก หรือโครงการถูกลบแล้ว');
			}
			if (!empty($wrongStatus)) {
				throw new RuntimeException(
					$isResubmitFlow
						? 'โครงการบางรายการไม่อยู่สถานะส่งร่าง/ตีกลับ จึงขอบรรจุซ้ำไม่ได้'
						: 'โครงการบางรายการยังไม่ได้ส่งร่างโครงการ กรุณากดส่งร่างก่อนแล้วจึงขอบรรจุ'
				);
			}
			$qScope = @mysqli_query(
				$db_Project,
				"SELECT COUNT(*) AS c FROM pre_project p WHERE p.id IN ($in) AND p.status='1' AND ($scopeAdminMatch)"
			);
			$rScope = $qScope ? mysqli_fetch_assoc($qScope) : null;
			if ((int)($rScope['c'] ?? 0) < count($projectIds)) {
				throw new RuntimeException('ไม่มีสิทธิ์ขอบรรจุบางโครงการในรายการที่เลือก (ต้องเป็นหน่วยงานหลักของโครงการเท่านั้น)');
			}

			if (!function_exists('insertProjectIncludeRequestBundle')) {
				throw new RuntimeException('ระบบบันทึกคำขอไม่พร้อม');
			}
			$requestId = insertProjectIncludeRequestBundle(
				$db_Project,
				$budget_year,
				$section_name,
				$subject,
				$letter_body,
				$sid,
				$projectIds,
				$certNormalized,
				$summaryRows
			);
			if ($requestId <= 0) {
				throw new RuntimeException('บันทึกข้อมูลคำขอขอบรรจุไม่สำเร็จ');
			}
			$ok = mysqli_query($db_Project, $sql);
			if (!$ok) {
				throw new RuntimeException(mysqli_error($db_Project) ?: 'ยื่นขอพิจารณาแผนไม่สำเร็จ');
			}
			$affected = (int)mysqli_affected_rows($db_Project);
			if ($affected <= 0) {
				throw new RuntimeException('ไม่มีรายการที่อัปเดตสถานะ (ตรวจสอบสิทธิ์/สถานะโครงการ)');
			}
			mysqli_commit($db_Project);
			echo json_encode(['ok' => 1, 'affected' => $affected, 'request_id' => $requestId], JSON_UNESCAPED_UNICODE);
		} catch (Throwable $e) {
			@mysqli_rollback($db_Project);
			echo json_encode(['ok' => 0, 'msg' => $e->getMessage()], JSON_UNESCAPED_UNICODE);
		}
		exit;
	} catch (Throwable $e) {
		echo json_encode(['ok' => 0, 'msg' => 'เกิดข้อผิดพลาด: '.$e->getMessage()], JSON_UNESCAPED_UNICODE);
		exit;
	}
}

// ส่วนที่ 7 เอกสารเพิ่มเติม — แสดงรายการ (AJAX)
