// ส่วนที่ 7 — อัปโหลดหลายไฟล์ (AJAX)
if ($op === 'upload_project_files_ajax') {
	header('Content-Type: application/json; charset=utf-8');
	$project_id = isset($_POST['project_id']) ? (int)$_POST['project_id'] : 0;
	if ($project_id <= 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ข้อมูลไม่ถูกต้อง'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	pm_exit_if_result_report_edit_blocked($db_Project, $project_id);
	$sess_email = $_SESSION['r_email'] ?? '';
	$sess_code = $_SESSION['code'] ?? '';
	$sid = 0;
	$staff_code = '';
	$unit_code = '';
	if ($sess_email !== '' && $sess_code !== '') {
		$st = mysqli_prepare($db_person, 'SELECT id, code, unit_code FROM staff WHERE email = ? AND code = ? LIMIT 1');
		mysqli_stmt_bind_param($st, 'ss', $sess_email, $sess_code);
		mysqli_stmt_execute($st);
		$rs = mysqli_stmt_get_result($st);
		$rw = $rs ? mysqli_fetch_assoc($rs) : null;
		if ($rw) {
			$sid = (int)($rw['id'] ?? 0);
			$staff_code = (string)($rw['code'] ?? '');
			$unit_code = (string)($rw['unit_code'] ?? '');
		}
	}
	if ($sid <= 0 || !function_exists('pm_staff_can_save_allowed_project_content') || !pm_staff_can_save_allowed_project_content($db_Project, $project_id, $sid, $staff_code, $unit_code)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีสิทธิ์แก้ไขโครงการนี้'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if (function_exists('ensureProjectExtraSchema')) {
		ensureProjectExtraSchema($db_Project);
	}

	$allowedExt = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png', 'gif', 'webp', 'zip'];
	$maxBytes = 30 * 1024 * 1024;
	$uploadDir = realpath(__DIR__ . '/../document/project_files');
	if ($uploadDir === false) {
		$uploadDir = __DIR__ . '/../document/project_files';
		if (!is_dir($uploadDir)) {
			@mkdir($uploadDir, 0777, true);
		}
		@chmod($uploadDir, 0777);
		$uploadDir = realpath($uploadDir);
	}
	if ($uploadDir !== false && is_dir($uploadDir) && !is_writable($uploadDir)) {
		@chmod($uploadDir, 0777);
	}
	if ($uploadDir === false || !is_dir($uploadDir) || !is_writable($uploadDir)) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่สามารถสร้างโฟลเดอร์เก็บไฟล์ได้'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$names = $_FILES['upload_files']['name'] ?? null;
	if (!is_array($names) || empty($names)) {
		echo json_encode(['ok' => 0, 'msg' => 'กรุณาเลือกไฟล์'], JSON_UNESCAPED_UNICODE);
		exit;
	}

	$inserted = 0;
	$errors = [];
	$esc = function ($v) use ($db_Project) {
		return mysqli_real_escape_string($db_Project, (string)$v);
	};

	for ($i = 0; $i < count($names); $i++) {
		$name = isset($_FILES['upload_files']['name'][$i]) ? (string)$_FILES['upload_files']['name'][$i] : '';
		$tmp = $_FILES['upload_files']['tmp_name'][$i] ?? '';
		$err = (int)($_FILES['upload_files']['error'][$i] ?? UPLOAD_ERR_NO_FILE);
		$size = (int)($_FILES['upload_files']['size'][$i] ?? 0);
		if ($name === '' || $err === UPLOAD_ERR_NO_FILE) {
			continue;
		}
		if ($err !== UPLOAD_ERR_OK) {
			$errors[] = $name . ' (อัปโหลดไม่สำเร็จ)';
			continue;
		}
		if ($size <= 0 || $size > $maxBytes) {
			$errors[] = $name . ' (ขนาดไฟล์ไม่เหมาะสม)';
			continue;
		}
		$ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
		if (!in_array($ext, $allowedExt, true)) {
			$errors[] = $name . ' (นามสกุลไม่อนุญาต)';
			continue;
		}
		$base = preg_replace('/[^a-zA-Z0-9._\-]+/', '_', basename($name));
		if ($base === '' || $base === '.' || $base === '..') {
			$base = 'file.' . $ext;
		}
		$newName = time() . '_' . $i . '_' . mt_rand(10000, 99999) . '_' . $base;
		$targetFile = $uploadDir . DIRECTORY_SEPARATOR . $newName;
		if (!@move_uploaded_file($tmp, $targetFile)) {
			$errors[] = $name . ' (บันทึกไฟล์ไม่สำเร็จ)';
			continue;
		}
		$origEsc = $esc($name);
		$storeEsc = $esc($newName);
		$hasStored = false;
		$cq = @mysqli_query($db_Project, "SHOW COLUMNS FROM project_file LIKE 'stored_file'");
		if ($cq && mysqli_num_rows($cq) > 0) {
			$hasStored = true;
		}
		if ($hasStored) {
			$sqlIns = "INSERT INTO project_file (code_pre_project, files, stored_file, dates, status, staff_insert)
				VALUES ('".(int)$project_id."', '".$origEsc."', '".$storeEsc."', NOW(), '1', '".(int)$sid."')";
		} else {
			$sqlIns = "INSERT INTO project_file (code_pre_project, files, dates, status, staff_insert)
				VALUES ('".(int)$project_id."', '".$origEsc."', NOW(), '1', '".(int)$sid."')";
		}
		if (@mysqli_query($db_Project, $sqlIns)) {
			$inserted++;
		} else {
			@unlink($targetFile);
			$errors[] = $name . ' (บันทึกฐานข้อมูลไม่สำเร็จ)';
		}
	}

	if ($inserted === 0 && !empty($errors)) {
		echo json_encode(['ok' => 0, 'msg' => implode(' ', $errors)], JSON_UNESCAPED_UNICODE);
		exit;
	}
	if ($inserted === 0) {
		echo json_encode(['ok' => 0, 'msg' => 'ไม่มีไฟล์ที่อัปโหลดได้'], JSON_UNESCAPED_UNICODE);
		exit;
	}
	$msg = $inserted . ' ไฟล์';
	if (!empty($errors)) {
		$msg .= ' (บางไฟล์ข้าม: ' . implode(' ', $errors) . ')';
	}
	echo json_encode(['ok' => 1, 'msg' => $msg, 'count' => $inserted], JSON_UNESCAPED_UNICODE);
	exit;
}

