}

// ซ่อมสถานะค้าง: โครงการที่อยู่ "รอบรรจุโครงการ"(3) แต่คำขอล่าสุดผ่านครบทุกลำดับแล้ว -> ย้ายเป็น "นำเข้าที่ประชุม"(4)
// (กรณีข้อมูลเดิมก่อนแก้ logic ในหน้าอนุมัติโครงการ)
if (defined('PLAN_ADMIN') && PLAN_ADMIN) {
	try {
	@mysqli_query(
		$db_Project,
		"UPDATE pre_project p
		 JOIN (
			SELECT i.project_id, MAX(i.request_id) AS rid
			FROM project_include_request_item i
			JOIN pre_project p2 ON p2.id = i.project_id AND p2.status='1' AND p2.status_project='3'
			GROUP BY i.project_id
		 ) x ON x.project_id = p.id
		 SET p.status_project='4', p.dates=NOW()
		 WHERE p.status='1'
		   AND p.status_project='3'
		   AND NOT EXISTS (
			 SELECT 1
			 FROM project_include_request_certifier c
			 LEFT JOIN project_include_request_certifier_decision d
				ON d.request_id=c.request_id AND d.sort_order=c.sort_order
			 WHERE c.request_id=x.rid
			   AND (d.decision IS NULL OR d.decision <> 'approved')
		   )
		   AND NOT EXISTS (
			 SELECT 1 FROM project_include_request_certifier_decision d2
			 WHERE d2.request_id=x.rid AND d2.decision='rejected'
		   )"
	);
	// reload list after repair
	$project_list  = getManageableProjectList($db_Project, $years_select, $staff_id, $staff_code, $is_unit_admin, $code_unit);
	if (!is_array($project_list)) {
		$project_list = [];
	}
	if (function_exists('pm_append_include_returned_projects_for_submitter')) {
		$project_list = pm_append_include_returned_projects_for_submitter($db_Project, $project_list, $years_select, $staff_id);
	}
	} catch (Throwable $e) {
		if (!is_array($project_list)) {
			$project_list = [];
		}
	}
}
try {
$year_list     = getYearSelect($db_pbmBudget);
$job_list      = function_exists('getJobSelect') ? getJobSelect($db_person) : [];
if (!is_array($year_list)) {
	$year_list = [];
}
if (!is_array($job_list)) {
	$job_list = [];
}
// แผนที่ชื่อหน่วยงานสำหรับแสดงผลรายการ — ไม่ใส่รหัสหน้าชื่อ
$unit_names = function_exists('planBuildSetUnitNamesMapNameOnly')
	? planBuildSetUnitNamesMapNameOnly($db_Project)
	: (function_exists('planBuildSetUnitNamesMap') ? planBuildSetUnitNamesMap($db_Project) : []);
if (!is_array($unit_names)) {
	$unit_names = [];
}
if ($db_person && function_exists('getUnitSelect')) {
	$__unitsHr = getUnitSelect($db_person);
	if (is_array($__unitsHr)) {
	foreach ($__unitsHr as $u) {
		$c = trim((string) ($u['code'] ?? ''));
		$nm = trim((string) ($u['name'] ?? ''));
		if (function_exists('planStripUnitCodeFromLabel')) {
			$nm = planStripUnitCodeFromLabel($nm);
		}
		if ($c !== '' && $nm !== '' && !isset($unit_names[$c])) {
			$unit_names[$c] = $nm;
		}
	}
	}
}
// ค่าเทียบหน่วยงานของผู้ใช้ (id/code) สำหรับตรวจว่าเป็นหน่วยงานร่วมของโครงการหรือไม่
$pm_viewer_unit_keys = [];
$__vu = trim((string) $code_unit);
if ($__vu !== '') {
	$pm_viewer_unit_keys[$__vu] = true;
	if (function_exists('planResolvePreProjectCodeUnit')) {
		$__vr = planResolvePreProjectCodeUnit($db_Project, $__vu);
		if ($__vr !== '') {
			$pm_viewer_unit_keys[$__vr] = true;
		}
	}
}
if (!empty($is_unit_admin) && (int) $staff_id > 0) {
	$qVu = @mysqli_query(
		$db_Project,
		"SELECT code_unit FROM set_project_personnel
		 WHERE staff_id='" . (int) $staff_id . "' AND is_unit_admin=1 AND status!='99'"
	);
	while ($qVu && ($rVu = mysqli_fetch_assoc($qVu))) {
		$cuAdmin = trim((string) ($rVu['code_unit'] ?? ''));
		if ($cuAdmin !== '') {
			$pm_viewer_unit_keys[$cuAdmin] = true;
		}
	}
}
$job_names = [];
foreach ($job_list as $j) {
	$job_names[(string)($j['code'] ?? '')] = $j['name'] ?? '-';
}
$include_finalize_staff_options = [];
$request_operate_staff_options = [];
$__staffOptsSource = (function_exists('getStaffSelect') ? getStaffSelect($db_person) : []);
if (!is_array($__staffOptsSource)) {
	$__staffOptsSource = [];
}
foreach ($__staffOptsSource as $__st) {
	$__sid = (int)($__st['id'] ?? 0);
	if ($__sid <= 0) {
		continue;
	}
	$__nm = trim((string)(($__st['fname'] ?? '') . ' ' . ($__st['lname'] ?? '')));
	if ($__nm === '') {
		$__nm = 'Staff #' . $__sid;
	}
	$__posLbl = function_exists('pm_staff_position_label') ? pm_staff_position_label($db_person, $__st) : '';
	$include_finalize_staff_options[] = [
		'id' => $__sid,
		'text' => $__nm,
		'position' => $__posLbl,
	];
	$request_operate_staff_options[] = [
		'id' => $__sid,
		'text' => $__nm,
		'position' => $__posLbl,
	];
}
} catch (Throwable $e) {
	$GLOBALS['pm_manage_error_shown'] = true;
	if (!isset($year_list) || !is_array($year_list)) {
		$year_list = [];
	}
	if (!isset($job_list) || !is_array($job_list)) {
		$job_list = [];
	}
	if (!isset($unit_names) || !is_array($unit_names)) {
		$unit_names = [];
	}
	if (!isset($job_names) || !is_array($job_names)) {
		$job_names = [];
	}
	if (!isset($pm_viewer_unit_keys) || !is_array($pm_viewer_unit_keys)) {
		$pm_viewer_unit_keys = [];
	}
	if (!isset($include_finalize_staff_options) || !is_array($include_finalize_staff_options)) {
		$include_finalize_staff_options = [];
	}
	if (!isset($request_operate_staff_options) || !is_array($request_operate_staff_options)) {
		$request_operate_staff_options = [];
	}
	echo '<div class="alert alert-danger">โหลดข้อมูลประกอบรายการโครงการไม่สำเร็จ: ' . htmlspecialchars($e->getMessage(), ENT_QUOTES, 'UTF-8') . '</div>';
}

// หน้าเพิ่มโครงการ (op=add_project)
if ($op === 'add_project') {
	$type_list   = getProjectTypeSelect($db_Project);
	$nature_list = getNatureSelect($db_Project);
	$staff_list  = getStaffSelect($db_person);
	$budget_set_list = getAddBudgetSelect($db_Project);
	$plan_unit_select_groups = getSetUnitSelectGroupsForPlan($db_Project);
	$plan_unit_groups_js = [];
	foreach ($plan_unit_select_groups as $_g) {
		$_opts = [];
		foreach (($_g['units'] ?? []) as $_u) {
			if (!is_array($_u)) {
				continue;
			}
			$_v = planSetUnitOptionValue($_u);
			if ($_v === '') {
				continue;
			}
			$_opts[] = ['val' => $_v, 'name' => planSetUnitOptionLabel($_u)];
		}
		$plan_unit_groups_js[] = ['label' => (string) ($_g['label'] ?? ''), 'options' => $_opts];
	}
	$year_short = substr($years_select, -2);
	$ref_placeholder = 'S' . $year_short . '-XXX';
	$ref_display = $ref_placeholder;

	$edit_project_id = isset($_GET['project_id']) ? (int)$_GET['project_id'] : 0;
	$pm_scroll_target = isset($_GET['pm_scroll']) ? trim((string)$_GET['pm_scroll']) : '';
	$pm_back_to = trim((string)($_GET['back_to'] ?? ''));
	if ($pm_back_to === '') {
		$pm_back_to = trim((string)($_GET['backto'] ?? ''));
		if ($pm_back_to !== '' && strpos($pm_back_to, '?') !== 0) {
			$pm_back_to = '?' . ltrim($pm_back_to, '?');
		}
	}
	$pm_from_approve_inbox = ($pm_back_to !== '' && strpos(urldecode($pm_back_to), 'project_approve') !== false);
	$pm_back_url = '?page=project_manage&years_select=' . rawurlencode((string)$years_select);
	if ($pm_back_to !== '' && strpos($pm_back_to, '?page=') === 0 && strpos($pm_back_to, "\n") === false && strpos($pm_back_to, "\r") === false) {
		$pm_back_url = $pm_back_to;
	}
	$saved_pre = null;
	$saved_heads = [];
	$saved_staffs = [];
	$saved_persons = [];
	$saved_deps = [];
	$saved_budgets = [];
	if ($edit_project_id > 0) {
		$saved_pre = getPreProjectID($db_Project, $edit_project_id);
		if (is_array($saved_pre)
			&& function_exists('pm_reopen_operate_queue_after_submitter_reply')
			&& (string)($saved_pre['status_project'] ?? '') === '8'
			&& trim((string)($saved_pre['operate_submitter_reply_note'] ?? '')) !== '') {
			pm_reopen_operate_queue_after_submitter_reply($db_Project, (int)$edit_project_id);
			$saved_pre = getPreProjectID($db_Project, $edit_project_id);
		}
		$saved_heads = getProjectHeadList($db_Project, $edit_project_id);
		$saved_staffs = getProjectStaffList($db_Project, $edit_project_id);
		$saved_persons = getProjectPersonList($db_Project, $edit_project_id);
		$saved_deps = getProjectDepartmentList($db_Project, $edit_project_id, 1);
		$saved_budgets = getProjectBudgetList($db_Project, $edit_project_id);
		if (is_array($saved_pre)) {
			$years_select = $saved_pre['year_project'] ?? $years_select;
			$code_unit = planResolvePreProjectCodeUnit($db_Project, (string) ($saved_pre['code_unit'] ?? ''));
			if ($code_unit === '') {
				$code_unit = planResolvePreProjectCodeUnit($db_Project, (string) ($r_staff['unit_code'] ?? ''));
			}
			$ref_display = $saved_pre['code_pre_project'] ?? $ref_placeholder;
		} else {
			$saved_pre = [];
		}
	}
	if (!is_array($saved_pre)) {
		$saved_pre = [];
	}
	$pm_is_midyear = ($edit_project_id > 0)
		? ((int)($saved_pre['midyear_request'] ?? 0) === 1)
		: (isset($_GET['midyear']) && (string)$_GET['midyear'] === '1');
	$pm_midyear_reason = trim((string)($saved_pre['midyear_reason'] ?? ''));
	$pm_sdgs_enabled = function_exists('pm_sdgs_consistency_enabled')
		? pm_sdgs_consistency_enabled($db_Project)
		: true;
	$pm_sdgs_id = function_exists('pm_sdgs_consistency_id')
		? pm_sdgs_consistency_id($db_Project)
		: 2;
	$pm_admin_tags = function_exists('pm_parse_admin_tags')
		? pm_parse_admin_tags($saved_pre['admin_tags'] ?? '')
		: [];
	if (!empty($pm_is_midyear) && trim((string)($pm_back_to ?? '')) === '') {
		$pm_back_url = '?page=project_manage&years_select=' . rawurlencode((string)$years_select) . '&project_group=plan';
	}
	if ($edit_project_id <= 0) {
		$code_unit = planResolvePreProjectCodeUnit($db_Project, (string) $code_unit);
	}
	$pm_can_fill_project_results = ($edit_project_id > 0)
		? pm_project_allows_kpi_result_fill($db_Project, $edit_project_id)
		: false;
	$pm_result_report_state = ($edit_project_id > 0 && function_exists('pm_get_project_result_report_state'))
		? pm_get_project_result_report_state($db_Project, $edit_project_id)
		: [
			'is_submitted' => false,
			'is_locked' => false,
			'is_rejected' => false,
			'is_completed' => false,
			'is_plan_closed' => false,
			'can_submit' => true,
			'submitted_at' => '',
			'completed_at' => '',
			'plan_closed_at' => '',
			'certifiers_json' => '',
		];
	$pm_can_edit_project_results = !empty($pm_can_fill_project_results) && !empty($pm_result_report_state['can_submit']);
	$pm_result_report_resubmit = !empty($pm_can_fill_project_results) && !empty($pm_result_report_state['is_rejected']);
	$pm_finish_report_btn_label = $pm_result_report_resubmit
		? 'ส่งรายงานการแก้ไขโครงการ'
		: 'เสร็จสิ้นโครงการและส่งรายงาน';
	$pm_is_result_report_frozen = !empty($pm_can_fill_project_results)
		&& empty($pm_result_report_state['can_submit'])
		&& (!empty($pm_result_report_state['is_locked']) || !empty($pm_result_report_state['is_completed']) || !empty($pm_result_report_state['is_plan_closed']));
	// ความสอดคล้อง - ต้องมี project_id (บันทึกแล้ว)
	// โครงสร้างจริง: set_type(ปี + child_kind) → set_side หรือ set_so ตามประเภท → (เชิงกลยุทธ์) AP ตาม SO
	$consistency_type_list = [];
	$consistency_ap_list = [];
	$consistency_side_list = [];
	$consistency_so_list = [];
	$consistency_side_by_type = [];
	$consistency_so_by_type = [];
	$consistency_ap_by_so = [];
	$consistency_current = null;
	$consistency_rows = [];
	$consistency_saved_sets = [];
	if ($edit_project_id > 0) {
		if (function_exists('kpi_type_year_ensure_schema')) {
			kpi_type_year_ensure_schema($db_KPI);
		}
		if (function_exists('kpi_type_list_by_year')) {
			$consistency_type_list = kpi_type_list_by_year($db_KPI, (string)$years_select);
		} elseif (function_exists('getKpiTypes')) {
			$consistency_type_list = getKpiTypes($db_KPI);
		}
		foreach ($consistency_type_list as $tRow) {
			$tid = (int)($tRow['id'] ?? 0);
			if ($tid <= 0) {
				continue;
			}
			$kind = function_exists('kpi_type_child_kind') ? kpi_type_child_kind($tRow) : 'side';
			$items = function_exists('kpi_type_items')
				? kpi_type_items($db_KPI, $tid, (string)$years_select, $kind)
				: [];
			$norm = [];
			foreach ($items as $it) {
				$iid = (int)($it['id'] ?? 0);
				if ($iid <= 0) {
					continue;
				}
				$norm[] = [
					'id' => (string)$iid,
					'name' => trim((string)($it['name'] ?? '')),
				];
			}
			if ($kind === 'so') {
				$consistency_so_by_type[(string)$tid] = $norm;
				foreach ($norm as $n) {
					$consistency_so_list[] = $n + ['code_type' => (string)$tid];
				}
			} else {
				$consistency_side_by_type[(string)$tid] = $norm;
				foreach ($norm as $n) {
					$consistency_side_list[] = $n + ['code_type' => (string)$tid];
				}
			}
		}
		$consistency_ap_list = function_exists('getAPList') ? getAPList($db_KPI) : [];
		// AP ที่ผูกกับ SO จากตัวชี้วัดปีนี้ (เฉพาะที่ส่งออกไปยังระบบโครงการ)
		$yrEsc = mysqli_real_escape_string($db_KPI, (string)$years_select);
		$yr2 = substr(preg_replace('/\D+/', '', (string)$years_select), -2);
		$yr2Esc = mysqli_real_escape_string($db_KPI, $yr2);
		$exportColOk = false;
		$chkExport = @mysqli_query($db_KPI, "SHOW COLUMNS FROM kpi_year_indicator LIKE 'export_to_project'");
		if ($chkExport && mysqli_num_rows($chkExport) > 0) {
			$exportColOk = true;
		} else {
			@mysqli_query(
				$db_KPI,
				"ALTER TABLE kpi_year_indicator ADD COLUMN export_to_project CHAR(1) NOT NULL DEFAULT '0' AFTER notify_months"
			);
			$chkExport2 = @mysqli_query($db_KPI, "SHOW COLUMNS FROM kpi_year_indicator LIKE 'export_to_project'");
			$exportColOk = ($chkExport2 && mysqli_num_rows($chkExport2) > 0);
		}
		$exportSql = $exportColOk ? "AND (yi.export_to_project = '1' OR yi.export_to_project = 1)" : '';
		$qApSo = @mysqli_query(
			$db_KPI,
			"SELECT DISTINCT yi.code_so, yi.code_ap, ap.name AS ap_name
			 FROM kpi_year_indicator yi
			 INNER JOIN kpi_year ky ON ky.id = yi.code_kpi_year
			 INNER JOIN set_ap ap ON ap.id = yi.code_ap AND ap.status = '1'
			 WHERE yi.status = '1'
			   {$exportSql}
			   AND yi.code_so IS NOT NULL AND yi.code_so <> '' AND yi.code_so <> '0'
			   AND yi.code_ap IS NOT NULL AND yi.code_ap <> '' AND yi.code_ap <> '0'
			   AND (ky.kpi_year = '{$yrEsc}' OR ky.kpi_year = '{$yr2Esc}')
			 ORDER BY yi.code_so ASC, yi.code_ap ASC"
		);
		if ($qApSo) {
			while ($ar = mysqli_fetch_assoc($qApSo)) {
				$soKey = (string)(int)($ar['code_so'] ?? 0);
				$apId = (string)(int)($ar['code_ap'] ?? 0);
				if ($soKey === '0' || $apId === '0') {
					continue;
				}
				if (!isset($consistency_ap_by_so[$soKey])) {
					$consistency_ap_by_so[$soKey] = [];
				}
				$consistency_ap_by_so[$soKey][$apId] = [
					'id' => $apId,
					'name' => trim((string)($ar['ap_name'] ?? '')),
				];
			}
			foreach ($consistency_ap_by_so as $soKey => $aps) {
				$consistency_ap_by_so[$soKey] = array_values($aps);
			}
		}
		$consistency_rows = function_exists('getProjectConsistencyRows')
			? getProjectConsistencyRows($db_Project, $edit_project_id)
			: [];
		$consistency_current = $consistency_rows[0] ?? getProjectConsistencyRow($db_Project, $edit_project_id);
		$consistency_saved_sets = [];
		foreach ($consistency_rows as $cRow) {
			$kpiIds = [];
			if (!empty($cRow['id']) && function_exists('getProjectConsistencyKPIDetail')) {
				foreach (getProjectConsistencyKPIDetail($db_Project, (int)$cRow['id']) as $kr) {
					$kid = trim((string)($kr['code_kpi_detail'] ?? ''));
					if ($kid !== '') {
						$kpiIds[] = $kid;
					}
				}
			}
			$consistency_saved_sets[] = [
				'id' => (int)($cRow['id'] ?? 0),
				'code_side' => (string)($cRow['code_side'] ?? ''),
				'code_so' => (string)($cRow['code_so'] ?? ''),
				'code_ap' => (string)($cRow['code_ap'] ?? ''),
				'kpis' => $kpiIds,
			];
		}
	}
	?>
