		.pm-project-eval-kpi-pct{
			display: inline-flex;
			align-items: center;
			justify-content: center;
			min-width: 2.4rem;
			padding: .08rem .55rem;
			border-radius: 999px;
			font-size: .92rem;
			font-weight: 900;
			margin-left: .15rem;
		}
		.pm-project-eval-kpi-pct.is-exact{ background: #dcfce7; color: #166534; }
		.pm-project-eval-kpi-pct.is-under{ background: #fef9c3; color: #854d0e; }
		.pm-project-eval-kpi-pct.is-over{ background: #dcfce7; color: #166534; }
		.pm-project-eval-kpi-pct.is-empty{ background: #f1f5f9; color: #64748b; }
		.pm-project-eval-kpi-lines{
			margin: 0;
			padding: 0;
			list-style: none;
		}
		.pm-project-eval-kpi-line{
			display: flex;
			align-items: center;
			justify-content: space-between;
			flex-wrap: wrap;
			gap: .35rem .75rem;
			padding: .42rem 0;
			border-top: 1px dashed #e2e8f0;
		}
		.pm-project-eval-kpi-line:first-child{ border-top: 0; padding-top: 0; }
		.pm-project-eval-kpi-line-name{
			font-weight: 700;
			color: #334155;
			flex: 1 1 auto;
			min-width: 0;
		}
		.pm-project-eval-kpi-line-stats{
			display: inline-flex;
			align-items: center;
			gap: .35rem;
			flex: 0 0 auto;
		}
		.pm-project-eval-kpi-stat{
			display: inline-flex;
			align-items: center;
			gap: .25rem;
			padding: .12rem .5rem;
			border-radius: .35rem;
			font-size: .78rem;
			font-weight: 800;
		}
		.pm-project-eval-kpi-stat.is-plan{
			background: #eff6ff;
			color: #1d4ed8;
			border: 1px solid #bfdbfe;
		}
		.pm-project-eval-kpi-stat.is-result{
			background: #ecfdf5;
			color: #15803d;
			border: 1px solid #bbf7d0;
		}
		.pm-project-eval-section{
			background: #fff;
			border: 1px solid #e2e8f0;
			border-radius: .75rem;
			padding: .85rem .9rem;
			margin-bottom: 1rem;
		}
		.pm-project-eval-section-title{
			font-weight: 900;
			color: #1e40af;
			font-size: .9rem;
			margin-bottom: .65rem;
		}
		.pm-project-eval-choices{
			display: grid;
			grid-template-columns: repeat(2, minmax(0, 1fr));
			gap: .65rem;
		}
		.pm-project-eval-choice{
			position: relative;
			display: flex;
			align-items: flex-start;
			gap: .55rem;
			margin: 0;
			padding: .7rem .75rem;
			border: 2px solid #e2e8f0;
			border-radius: .65rem;
			background: #f8fafc;
			cursor: pointer;
			transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;
		}
		.pm-project-eval-choice input{
			position: absolute;
			opacity: 0;
			pointer-events: none;
		}
		.pm-project-eval-choice-icon{
			width: 34px;
			height: 34px;
			border-radius: .5rem;
			display: flex;
			align-items: center;
			justify-content: center;
			font-size: .95rem;
			flex: 0 0 auto;
		}
		.pm-project-eval-choice--achieved .pm-project-eval-choice-icon{
			background: #dcfce7;
			color: #16a34a;
		}
		.pm-project-eval-choice--not .pm-project-eval-choice-icon{
			background: #fee2e2;
			color: #dc2626;
		}
		.pm-project-eval-choice-text{
			font-weight: 900;
			color: #0f172a;
			line-height: 1.35;
		}
		.pm-project-eval-choice-note{
			display: block;
			margin-top: .2rem;
			font-size: .74rem;
			font-weight: 600;
			color: #64748b;
			line-height: 1.35;
		}
		.pm-project-eval-choice:has(input:checked){
			box-shadow: 0 0 0 3px rgba(37, 99, 235, .14);
		}
		.pm-project-eval-choice--achieved:has(input:checked){
			border-color: #22c55e;
			background: #f0fdf4;
		}
		.pm-project-eval-choice--not:has(input:checked){
			border-color: #f87171;
			background: #fef2f2;
		}
		.pm-project-eval-feedback .pm-project-eval-field{
			background: #fff;
			border: 1px solid #e2e8f0;
			border-radius: .65rem;
			padding: .7rem .75rem;
			height: 100%;
		}
		.pm-project-eval-field-label{
			font-weight: 900;
			color: #0f172a;
			font-size: .88rem;
			margin-bottom: .45rem;
		}
		.pm-project-eval-oit-tag{
			color: #dc2626;
			font-weight: 800;
			font-size: .78rem;
		}
		.pm-project-eval-textarea{
			border: 1px solid #cbd5e1;
			border-radius: .5rem;
			min-height: 120px;
			resize: vertical;
			transition: border-color .15s ease, box-shadow .15s ease;
		}
		.pm-project-eval-textarea:focus{
			border-color: #60a5fa;
			box-shadow: 0 0 0 3px rgba(59, 130, 246, .15);
		}
		.pm-project-eval-footer{
			background: #f8fafc;
			border-top: 1px solid #e2e8f0;
			justify-content: center;
			padding: .85rem 1.25rem 1rem;
		}
		.pm-project-eval-footer .btn{
			min-width: 180px;
			font-weight: 900;
			border-radius: .55rem;
			padding: .55rem 1.25rem;
			box-shadow: 0 8px 18px -10px rgba(37, 99, 235, .65);
		}
		@media (max-width: 767.98px){
			.pm-project-eval-choices{ grid-template-columns: 1fr; }
			.pm-project-eval-kpi-line{ align-items: flex-start; }
		}
		.pm-finish-project-report-btn{
			font-weight: 900;
			letter-spacing: .01em;
			line-height: 1.3;
			white-space: normal;
		}
		.pm-finish-project-report-btn:disabled{
			opacity: .72;
			cursor: not-allowed;
			box-shadow: none !important;
		}
		@media (max-width: 767.98px){
			.pm-finish-project-report-btn{
				font-size: .92rem !important;
				padding: .55rem .85rem !important;
			}
		}
		/* ส่วนที่ 7 เอกสารแนบ */
		.pm-s7-files-root .pm-s7-file-row{
			border-radius: .5rem;
		}
		.pm-s7-files-root .pm-s7-fname{
			word-break: break-word;
			color: #0b4a6f;
		}
		.pm-s7-files-root .pm-s7-preview-inner{
			background: #f8fafc !important;
		}
		.pm-s7-files-root .pm-s7-preview-img{
			cursor: zoom-in;
		}
		.pm-month-grid label{
			display:flex; align-items:center; gap:8px;
			margin:0; font-weight:700; color:#111;
		}
		.pm-target-row .btn{ padding:.35rem .6rem; }
		.pm-target-help{ color:#7a7a7a; font-size:.92rem; }

		/* กล่องแยกแต่ละส่วน (card) */
		.pm-block {
			background: #fff;
			border: 1px solid #e8def2;
			border-radius: .55rem;
			padding: 1rem 1rem 1.1rem;
			box-shadow: none;
		}
		.pm-block + .pm-block { margin-top: 1rem; }
		/* ส่วนที่ 1: ให้ header เต็มกรอบเหมือนส่วนอื่น */
		.pm-ginfo-wrap { padding: 0 !important; }
		.pm-ginfo-wrap #general-info-summary { padding: 0 !important; }
		/* ทำ header ให้เต็มกรอบด้านบน (full-bleed) */
		.pm-block > .pm-block-title,
		.pm-block > .pm-section2-banner,
		.pm-block > .pm-section-title {
			display: flex;
			width: calc(100% + 2rem);
			margin: -1rem -1rem .85rem -1rem;
			border-radius: .55rem .55rem 0 0;
			border-left: 0;
			border-right: 0;
			border-top: 0;
		}
		/* กรณีหัวเป็น h6 ที่มี width:100% อยู่แล้ว */
		.pm-block > .pm-section-title[style*="width"] { width: calc(100% + 2rem) !important; }

		/* หัวข้อแบบแถบม่วงอ่อน */
		.pm-block-title,
		.pm-section-title {
			background: var(--pm-header-bg);
			border: 1px solid var(--pm-header-border);
			color: var(--pm-header-text);
			padding: .6rem .85rem;
			border-radius: .5rem;
			font-weight: 900;
			display: flex;
			align-items: center;
			gap: .55rem;
		}
		.pm-section-title.border-bottom { border-bottom: 0 !important; }
		.pm-section-title.pb-2 { padding-bottom: .65rem !important; }
		.pm-section-title.mb-3 { margin-bottom: .85rem !important; }

		.pm-wizard { --pm-accent: #926cb8; --pm-accent-soft: rgba(146,108,184,.14); --pm-surface: #faf7fc; --pm-border: #e6ddee; --pm-text: #2b2433; }
		.pm-hero {
			background: #fff;
			border: 1px solid var(--pm-border);
			border-radius: 1rem;
			box-shadow: none;
			padding: 1.35rem 1.65rem;
			margin-bottom: 1.5rem;
			position: relative;
			overflow: hidden;
		}
		.pm-hero::after {
			display: none;
		}
		.pm-section-card {
			border-radius: 1rem !important;
			border: none !important;
			box-shadow: none !important;
			background: transparent !important;
			overflow: hidden;
		}
		.pm-section-card .card-body { background: transparent; }
		.pm-section-title {
			display: inline-flex;
			align-items: center;
			gap: .5rem;
			font-weight: 700;
			color: var(--pm-accent);
			letter-spacing: .02em;
		}
		.pm-section-title i { opacity: .9; }
		.pm-pill-soft {
			background: var(--pm-accent-soft);
			color: var(--pm-accent);
			border-radius: 999px;
			padding: .25rem .6rem;
			font-size: .72rem;
			font-weight: 700;
		}
		.pm-list-card {
			border-radius: 1rem !important;
			border: none !important;
			box-shadow: 0 8px 30px -10px rgba(15, 23, 42, .2) !important;
			overflow: hidden;
		}
		.pm-list-card .card-header {
			background: linear-gradient(180deg, #faf7fc 0%, #f3eef8 100%) !important;
			color: #4a3263 !important;
			border: none !important;
			border-bottom: 1px solid #e8def2 !important;
		}
		.pm-list-card .card-header .card-title { color: #4a3263 !important; }
		.pm-table-wrap { border-radius: .75rem; overflow: hidden; border: 1px solid var(--pm-border); }
		.pm-table-wrap table { margin-bottom: 0 !important; }
		.pm-table-wrap thead th {
			background: #f3eef8 !important;
			color: #4a3263 !important;
			font-weight: 700;
			text-transform: none;
			border-color: var(--pm-border) !important;
			text-align: center !important;
			vertical-align: middle !important;
		}
		.pm-table-wrap tbody tr:hover { background: #fff !important; }
		.btn-pm-primary {
			background: linear-gradient(180deg, var(--pm-accent) 0%, #734d96 100%);
			border: none;
			box-shadow: 0 4px 14px -4px rgba(146, 108, 184, .65);
		}
		.btn-pm-primary:hover { filter: brightness(1.05); }
		#modalConsistencyAdd .modal-content { border-radius: 1rem; overflow: hidden; border: none; box-shadow: 0 20px 50px -12px rgba(0,0,0,.35); }
		#modalGeneralInfo .modal-content { border-radius: 1rem; border: none; box-shadow: 0 20px 50px -12px rgba(0,0,0,.3); overflow: visible !important; }
		#modalGeneralInfo .pm-row-actions{
			display:flex;
			flex-direction:column;
			align-items:stretch;
			gap:.28rem;
		}
		#modalGeneralInfo .pm-row-actions .btn{ white-space:nowrap; }
		.add-project-header { background: #fff; border-radius: 0.5rem; box-shadow: 0 1px 3px rgba(0,0,0,.08); padding: 1.25rem 1.5rem; margin-bottom: 1.5rem; }
		.pm-wizard.pm-hide-add-stepper .add-project-stepper{ display:none !important; }
		.pm-section-incomplete-msg{
			color: #dc3545 !important;
			font-weight: 800;
			font-size: .9rem;
			margin: .45rem 0 .35rem;
			line-height: 1.35;
		}
		/* ส่วนที่ 1 ไม่มี padding ของ .pm-block — ให้ชิดข้อความเท่าส่วนที่ 2 */
		#pm-section-1 .pm-section-incomplete-msg{
			padding: 0 1rem;
			margin: .45rem 0 .15rem;
		}
		/* Stepper (ส่วนที่ 1-5): ให้ดูโมเดิร์นขึ้น */
		.add-project-stepper{
			display:flex;
			align-items:flex-start;
			justify-content:center;
			max-width: 720px;
			margin: 1.2rem auto 0;
			gap: 0;
			padding: .25rem .35rem;
		}
		.add-project-step{
			display:flex;
			flex-direction:column;
			align-items:center;
			flex: 0 0 auto;
			min-width: 84px;
		}
		.add-project-step-line{
			flex: 1;
			min-width: 34px;
			max-width: 92px;
			height: 6px;
			border-radius: 999px;
			background: linear-gradient(90deg, rgba(148,163,184,.55), rgba(203,213,225,.35));
			margin-top: 15px;
			box-shadow: inset 0 1px 0 rgba(255,255,255,.6);
		}
		.add-project-step-line.done{
			background: #e8def2;
			box-shadow: none;
		}
		.add-project-step-circle{
			width: 38px;
			height: 38px;
			border-radius: 50%;
			display:flex;
			align-items:center;
			justify-content:center;
			font-size: .92rem;
			font-weight: 700;
			flex-shrink: 0;
			border: 2px solid #e2e8f0;
			box-shadow: none;
			position: relative;
		}
		.add-project-step-circle::after{
			display: none;
		}
		.add-project-step-circle.done{
			background: #f3eef8;
			color:#734d96;
			border-color: #e8def2;
			filter: none;
		}
		.add-project-step-circle.pending{
			background: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
			color:#64748b;
		}
		.add-project-step:hover .add-project-step-circle{ transform: translateY(-1px); }
		.add-project-step{ cursor: pointer; }
		.add-project-step-circle, .add-project-step-label{ cursor: pointer; }
		.pm-step-target-flash{
			animation: pmFlashTarget .85s ease-in-out;
		}
		@keyframes pmFlashTarget{
			0%{ box-shadow: 0 0 0 0 rgba(146, 108, 184, 0.0); }
			25%{ box-shadow: 0 0 0 4px rgba(146, 108, 184, 0.18); }
			55%{ box-shadow: 0 0 0 8px rgba(146, 108, 184, 0.12); }
			100%{ box-shadow: 0 0 0 0 rgba(146, 108, 184, 0.0); }
		}
		.add-project-step-label{
			font-size: .78rem;
			margin-top: .55rem;
			color: #334155;
			font-weight: 800;
			text-align: center;
			white-space: nowrap;
			letter-spacing: .1px;
		}
		.add-project-step-label-wrap{
			white-space: normal;
			max-width: 8.6rem;
			line-height: 1.25;
		}
		@media (max-width: 768px){
			.add-project-stepper{
				max-width: 100%;
				overflow-x: auto;
				-webkit-overflow-scrolling: touch;
				justify-content: flex-start;
				padding-bottom: .35rem;
			}
			.add-project-step{ min-width: 68px; }
			.add-project-step-label{
				font-size: .72rem;
				white-space: normal;
				max-width: 72px;
				line-height: 1.25;
			}
			.add-project-step-line{ min-width: 22px; max-width: 44px; height: 5px; }
		}
		/* เมื่อส่งร่างแล้ว: ปุ่ม add/edit ที่ถูกล็อก */
		.pm-lock-disabled{
			pointer-events: none !important;
			opacity: .5 !important;
			filter: grayscale(.15);
		}
		/* หลังส่งร่างแล้ว: ซ่อน control เพิ่ม/แก้ไข/ลบ โดยเฉพาะส่วนที่ 4/5 ให้เด็ดขาด */
		.pm-wizard.pm-submitted-lock [data-action="budget-items"],
