		.pm-wizard.pm-submitted-lock [data-action="open-s6-modal"],
		.pm-wizard.pm-submitted-lock #btnS7OpenUpload,
		.pm-wizard.pm-submitted-lock .pm-s7-file-delete,
		.pm-wizard.pm-result-report-lock [data-action="budget-items"],
		.pm-wizard.pm-result-report-lock [data-action="budget-item-edit"],
		.pm-wizard.pm-result-report-lock [data-action="budget-item-del"],
		.pm-wizard.pm-result-report-lock [data-action="budget-plan"],
		.pm-wizard.pm-result-report-lock #btnAddActivityTop,
		.pm-wizard.pm-result-report-lock .pm-activity-edit,
		.pm-wizard.pm-result-report-lock .pm-activity-del,
		.pm-wizard.pm-result-report-lock [data-kpi-goal-action],
		.pm-wizard.pm-result-report-lock .btn-section2-edit,
		.pm-wizard.pm-result-report-lock [data-action="open-s6-modal"],
		.pm-wizard.pm-result-report-lock #btnS7OpenUpload,
		.pm-wizard.pm-result-report-lock .pm-s7-file-delete,
		.pm-wizard.pm-project-name-lock #btnToggleHeaderEdit,
		.pm-wizard.pm-project-name-lock .pm-save-btn,
		.pm-wizard.pm-result-report-lock #btnToggleHeaderEdit,
		.pm-wizard.pm-result-report-lock .pm-save-btn,
		.pm-wizard.pm-result-report-lock #general-info-summary .pm-ginfo-banner button,
		.pm-wizard.pm-result-report-lock .btn-kpi-fill-result,
		.pm-wizard.pm-result-report-lock .btn-kpi-edit-result,
		.pm-wizard.pm-result-report-lock .btn-activity-fill-result,
		.pm-wizard.pm-result-report-lock .btn-activity-edit-result,
		.pm-wizard.pm-result-report-lock .pm-budget-disburse-open,
		.pm-wizard.pm-result-report-lock .pm-ber-disburse-btn,
		.pm-wizard.pm-result-report-lock .pm-budget-disburse-edit,
		.pm-wizard.pm-result-report-lock .pm-ber-line-edit-btn,
		.pm-wizard.pm-result-report-lock .pm-budget-other-action-create,
		.pm-wizard.pm-result-report-lock .pm-budget-other-action-btn,
		.pm-wizard.pm-result-report-lock #btnOpenProjectEvaluation,
		.pm-wizard.pm-result-report-lock button[data-target="#modalConsistencyAdd"],
		.pm-wizard.pm-operate-approved-lock #general-info-summary .pm-ginfo-banner button,
		.pm-wizard.pm-operate-approved-lock button[data-target="#modalConsistencyAdd"],
		.pm-wizard.pm-operate-approved-lock .btn-section2-edit,
		.pm-wizard.pm-operate-approved-lock [data-kpi-goal-action],
		.pm-wizard.pm-operate-approved-lock .btn-kpi-goal-edit,
		.pm-wizard.pm-operate-approved-lock .btn-kpi-goal-delete,
		.pm-wizard.pm-operate-approved-lock .pm-inline-act,
		.pm-wizard.pm-operate-approved-lock #btnAddActivityTop,
		.pm-wizard.pm-operate-approved-lock .pm-activity-edit,
		.pm-wizard.pm-operate-approved-lock .pm-activity-del,
		.pm-wizard.pm-operate-approved-lock [data-action="budget-items"],
		.pm-wizard.pm-operate-approved-lock [data-action="budget-item-edit"],
		.pm-wizard.pm-operate-approved-lock [data-action="budget-item-del"],
		.pm-wizard.pm-operate-approved-lock [data-action="budget-plan"],
		.pm-wizard.pm-operate-approved-lock [data-action="open-s6-modal"],
		.pm-wizard.pm-operate-approved-lock #btnS7OpenUpload,
		.pm-wizard.pm-operate-approved-lock .pm-s7-file-delete,
		.pm-wizard.pm-operate-approved-lock #btnToggleHeaderEdit,
