	<?php
		$pm_is_plan_admin = (defined('PLAN_ADMIN') && PLAN_ADMIN);
		$pm_change_history = [];
		$pm_chg_memos = [];
		$pm_approve_memo_ready = false;
		$pm_am_esign_ref = '';
		$pm_am_esign_footer = '';
		$pm_status_now_h = (string)($saved_pre['status_project'] ?? '0');
		$pm_notify_result_h = trim((string)($saved_pre['notify_result'] ?? ''));
		$pm_user_fix_note_h = trim((string)($saved_pre['user_fix_note'] ?? ''));
		$pm_is_plan_workflow = pm_is_editable_in_plan_mode($pm_status_now_h, $pm_notify_result_h, $pm_user_fix_note_h);
		$pm_is_notify_plan = (mb_strpos($pm_notify_result_h, 'บรรจุแผน') === 0);
		$pm_is_plan_badge = $pm_is_plan_workflow || (($pm_status_now_h === '1' || $pm_status_now_h === '4' || $pm_status_now_h === '8') && $pm_is_notify_plan);
		$pm_operate_reply_h = trim((string)($saved_pre['operate_submitter_reply_note'] ?? ''));
		$pm_is_operate_returned_partial = (!$pm_is_plan_admin)
			&& function_exists('pm_is_operate_returned_partial')
			&& pm_is_operate_returned_partial($pm_status_now_h, $pm_notify_result_h, $pm_operate_reply_h);
		$pm_is_annual_plan_partial = (!$pm_is_plan_admin) && (
			pm_is_annual_plan_pre_operate($pm_status_now_h, $pm_notify_result_h)
			|| !empty($pm_is_operate_returned_partial)
		);
		$pm_apply_workflow_ui_lock = pm_plan_restricts_like_user($pm_status_now_h, $pm_notify_result_h);
		$pm_lock_project_name = $pm_apply_workflow_ui_lock
			|| ($edit_project_id > 0 && function_exists('pm_project_allows_kpi_result_fill') && pm_project_allows_kpi_result_fill($db_Project, (int)$edit_project_id));
		$pm_is_hard_lock = (!$pm_is_plan_admin && !in_array($pm_status_now_h, ['0','8'], true) && empty($pm_is_annual_plan_partial));
		if (!$pm_is_plan_admin && $pm_notify_result_h === 'บรรจุแผน' && $pm_operate_reply_h !== '' && in_array($pm_status_now_h, ['1', '8'], true)) {
			$pm_is_hard_lock = true;
			$pm_lock_project_name = true;
		}
		$pm_include_meeting_lock = function_exists('pm_is_include_meeting_view_only')
			&& pm_is_include_meeting_view_only($pm_status_now_h, $pm_notify_result_h);
		if (!empty($pm_include_meeting_lock)) {
			$pm_is_hard_lock = true;
			$pm_lock_project_name = true;
		}
		$pm_plan_fix_resubmit_lock = function_exists('pm_is_plan_fix_awaiting_review')
			&& pm_is_plan_fix_awaiting_review($pm_status_now_h, $pm_notify_result_h, $pm_user_fix_note_h);
		if (!empty($pm_plan_fix_resubmit_lock)) {
			$pm_is_hard_lock = true;
			$pm_lock_project_name = true;
		}
		$pm_title_badge = $pm_is_plan_badge ? 'แผนปฏิบัติการ' : 'ร่าง';
		if (!empty($pm_is_midyear)) {
			$pm_title_badge = 'ยื่นระหว่างปี';
		}
		$pm_early_operate_chain_all_done = ($edit_project_id > 0 && function_exists('pm_is_operate_final_approved'))
			? pm_is_operate_final_approved($db_Project, (int)$edit_project_id, is_array($saved_pre) ? $saved_pre : null)
			: false;
		$pm_cancel_req = null;
		$pm_cancel_status = '';
		$pm_is_cancelled = false;
		$pm_cancel_pending = false;
		if ($edit_project_id > 0) {
			if (function_exists('pm_ensure_cancel_request_schema')) {
				pm_ensure_cancel_request_schema($db_Project);
			}
			$pm_is_cancelled = function_exists('pm_project_is_cancelled')
				&& pm_project_is_cancelled($db_Project, (int)$edit_project_id, is_array($saved_pre) ? $saved_pre : null);
			$pm_cancel_req = function_exists('pm_load_project_cancel_request')
				? pm_load_project_cancel_request($db_Project, (int)$edit_project_id)
				: null;
			$pm_cancel_status = is_array($pm_cancel_req) ? trim((string)($pm_cancel_req['req_status'] ?? '')) : '';
			if ($pm_cancel_status === 'approved') {
				$pm_is_cancelled = true;
			}
			$pm_cancel_pending = ($pm_cancel_status === 'pending');
			if (!empty($pm_is_cancelled)) {
				$pm_lock_project_name = true;
				$pm_hide_structure_edit_btns = true;
				$pm_is_hard_lock = true;
			}
		}
		// อนุมัติโดยผู้อนุมัติครบแล้ว: ซ่อนปุ่มแก้ไขโครงสร้าง — ยกเว้นกรณีตีกลับให้แก้บางข้อ
		$pm_hide_structure_edit_btns = (!$pm_is_plan_admin) && empty($pm_is_annual_plan_partial) && (
			!empty($pm_can_fill_project_results)
			|| !empty($pm_early_operate_chain_all_done)
		);
		if (!empty($pm_is_cancelled)) {
			$pm_lock_project_name = true;
			$pm_hide_structure_edit_btns = true;
			$pm_is_hard_lock = true;
		}
		if (!empty($pm_include_meeting_lock)) {
			$pm_lock_project_name = true;
			$pm_hide_structure_edit_btns = true;
			$pm_is_hard_lock = true;
		}
		if (!empty($pm_plan_fix_resubmit_lock)) {
			$pm_lock_project_name = true;
			$pm_hide_structure_edit_btns = true;
			$pm_is_hard_lock = true;
		}
		if (!$pm_is_plan_admin && $pm_notify_result_h === 'บรรจุแผน' && $pm_operate_reply_h !== '' && in_array($pm_status_now_h, ['1', '8'], true)) {
			$pm_lock_project_name = true;
			$pm_hide_structure_edit_btns = true;
			$pm_is_hard_lock = true;
		}
		$pm_is_plan_closed_h = !empty($pm_result_report_state['is_plan_closed'])
			|| (function_exists('pm_project_is_result_report_plan_closed')
				&& $edit_project_id > 0
				&& pm_project_is_result_report_plan_closed($db_Project, (int)$edit_project_id, is_array($saved_pre) ? $saved_pre : null));
		if (!empty($pm_is_plan_closed_h)) {
			$pm_lock_project_name = true;
			$pm_hide_structure_edit_btns = true;
			$pm_is_hard_lock = true;
			$pm_is_result_report_frozen = true;
		}
		// ตัดแถบขั้นตอนด้านบนออกแล้ว ใช้เครื่องหมาย * + ข้อความเตือนในแต่ละส่วนแทน
		$pm_hide_add_stepper = true;
		$pm_show_section_required_hints = ($edit_project_id <= 0)
			|| in_array($pm_status_now_h, ['0', '2', '8', ''], true);
	?>
	<div class="pm-wizard <?= $pm_is_hard_lock ? 'pm-submitted-lock' : '' ?><?= !empty($pm_is_annual_plan_partial) ? ' pm-annual-plan-partial-lock' : '' ?><?= !empty($pm_lock_project_name) ? ' pm-project-name-lock' : '' ?><?= !empty($pm_is_result_report_frozen) ? ' pm-result-report-lock' : '' ?><?= !empty($pm_hide_structure_edit_btns) ? ' pm-operate-approved-lock' : '' ?><?= !empty($pm_hide_add_stepper) ? ' pm-hide-add-stepper' : '' ?>">
	<form method="POST" action="?page=project_manage&op=save_project" enctype="multipart/form-data" id="form-add-project">
		<input type="hidden" name="op_from" value="add_project">
		<input type="hidden" name="years_select" value="<?= htmlspecialchars($years_select, ENT_QUOTES, 'UTF-8') ?>">
		<input type="hidden" name="project_id" value="<?= (int)$edit_project_id ?>">
		<input type="hidden" name="midyear_request" value="<?= !empty($pm_is_midyear) ? '1' : '0' ?>">
		<input type="hidden" id="edit_project_id" value="<?= (int)$edit_project_id ?>">
		<input type="hidden" id="status_project_now" value="<?= htmlspecialchars((string)($saved_pre['status_project'] ?? '0'), ENT_QUOTES, 'UTF-8') ?>">
		<script>
			window.PM_PLAN_ADMIN = <?= $pm_is_plan_admin ? 'true' : 'false' ?>;
			window.PM_CAN_FILL_PROJECT_RESULTS = <?= !empty($pm_can_fill_project_results) ? 'true' : 'false' ?>;
			window.PM_CAN_EDIT_PROJECT_RESULTS = <?= !empty($pm_can_edit_project_results) ? 'true' : 'false' ?>;
			window.PM_RESULT_REPORT_LOCKED = <?= !empty($pm_result_report_state['is_locked']) ? 'true' : 'false' ?>;
			window.PM_RESULT_REPORT_COMPLETE = <?= (!empty($pm_result_report_state['is_completed']) || !empty($pm_result_report_state['is_plan_closed'])) ? 'true' : 'false' ?>;
			window.PM_RESULT_REPORT_RESUBMIT = <?= !empty($pm_result_report_resubmit) ? 'true' : 'false' ?>;
			window.PM_LOCK_PROJECT_NAME = <?= !empty($pm_lock_project_name) ? 'true' : 'false' ?>;
			window.PM_OPERATE_APPROVED = <?= !empty($pm_hide_structure_edit_btns) ? 'true' : 'false' ?>;
			window.PM_ANNUAL_PLAN_PARTIAL = <?= !empty($pm_is_annual_plan_partial) ? 'true' : 'false' ?>;
			window.PM_INCLUDE_MEETING_LOCK = <?= !empty($pm_include_meeting_lock) ? 'true' : 'false' ?>;
			window.PM_PLAN_FIX_RESUBMIT_LOCK = <?= !empty($pm_plan_fix_resubmit_lock) ? 'true' : 'false' ?>;
			window.PM_OPERATE_REPLY_LOCK = <?= (!$pm_is_plan_admin && $pm_notify_result_h === 'บรรจุแผน' && $pm_operate_reply_h !== '' && in_array($pm_status_now_h, ['1', '8'], true)) ? 'true' : 'false' ?>;
			window.PM_OPERATE_RETURN_FIX = <?= !empty($pm_is_operate_returned_partial) ? 'true' : 'false' ?>;
			window.PM_IS_MIDYEAR = <?= !empty($pm_is_midyear) ? 'true' : 'false' ?>;
			window.PM_SDGS_ENABLED = <?= !empty($pm_sdgs_enabled) ? 'true' : 'false' ?>;
			window.PM_SHOW_SECTION_REQUIRED = <?= !empty($pm_show_section_required_hints) ? 'true' : 'false' ?>;
		</script>
			<?php
				// เงื่อนไข “ส่งร่างโครงการ” (คำนวณที่หัวหน้าได้เลย)
				$pm_s1_done_h = is_array($saved_pre)
					&& !empty((string)($saved_heads[0]['staff_project'] ?? ''))
					&& !empty(trim((string)($saved_heads[0]['phone'] ?? '')))
					&& !empty((string)($saved_staffs[0]['staff_project'] ?? ''))
					&& !empty(trim((string)($saved_staffs[0]['phone'] ?? '')))
					&& !empty(trim((string)($saved_pre['code_unit'] ?? '')))
					&& !empty(trim((string)($saved_pre['code_nature'] ?? '')))
					&& !empty(trim((string)($saved_pre['code_type'] ?? '')))
					&& (
						!empty(trim((string)($saved_pre['start_month'] ?? ''))) || !empty(trim((string)($saved_pre['start_year'] ?? '')))
					)
					&& (
						!empty(trim((string)($saved_pre['end_month'] ?? ''))) || !empty(trim((string)($saved_pre['end_year'] ?? '')))
					);
				$pm_s2_done_h = is_array($saved_pre)
					&& !empty(trim(strip_tags($saved_pre['reson'] ?? '')))
					&& !empty(trim(strip_tags($saved_pre['result'] ?? '')))
					&& !empty(trim(strip_tags($saved_pre['objective'] ?? '')))
					&& !empty(trim(strip_tags($saved_pre['target_project'] ?? '')))
					&& (empty($pm_is_midyear) || trim(strip_tags((string)($saved_pre['midyear_reason'] ?? ''))) !== '');
				$pm_s3_kpi_done_h = false;
				if ($edit_project_id > 0 && function_exists('getProjectKPIList')) {
					$pm_s3_kpi_list_h = getProjectKPIList($db_Project, $edit_project_id);
					$pm_s3_kpi_done_h = !empty($pm_s3_kpi_list_h);
				}
				$pm_section3_complete = !empty($pm_s2_done_h) && !empty($pm_s3_kpi_done_h);
				$pm_s3_done_h = false;
				if ($edit_project_id > 0 && !empty($consistency_rows) && is_array($consistency_rows)) {
					$pm_kpi_tmp = [];
					$pm_sdg_tmp = [];
					$pm_has_level2 = false;
					foreach ($consistency_rows as $cDone) {
						if (!empty($cDone['code_ap']) || !empty($cDone['code_side'])) {
							$pm_has_level2 = true;
						}
						if (!empty($cDone['id']) && function_exists('getProjectConsistencyKPIDetail')) {
							$pm_kpi_tmp = array_merge($pm_kpi_tmp, getProjectConsistencyKPIDetail($db_Project, (int)$cDone['id']));
						}
						if (!empty($cDone['id']) && function_exists('getSelectedConsistencyMap')) {
							$pm_sdg_tmp = array_merge($pm_sdg_tmp, getSelectedConsistencyMap($db_Project, (int)$cDone['id']));
						}
					}
					$pm_s3_done_h = (
						!empty($consistency_current['code_kpi_type'])
						|| $pm_has_level2
						|| !empty($pm_kpi_tmp)
						|| (!empty($pm_sdgs_enabled) && !empty($pm_sdg_tmp))
					);
				} elseif ($edit_project_id > 0 && !empty($consistency_current) && is_array($consistency_current)) {
					$pm_kpi_tmp = [];
					if (!empty($consistency_current['id']) && function_exists('getProjectConsistencyKPIDetail')) {
						$pm_kpi_tmp = getProjectConsistencyKPIDetail($db_Project, $consistency_current['id']);
					}
					$pm_sdg_tmp = [];
					if (!empty($consistency_current['id']) && function_exists('getSelectedConsistencyMap')) {
						$pm_sdg_tmp = getSelectedConsistencyMap($db_Project, $consistency_current['id']);
					}
					$pm_s3_done_h = (
						!empty($consistency_current['code_kpi_type'])
						|| !empty($consistency_current['code_ap'])
						|| !empty($consistency_current['code_side'])
						|| !empty($pm_kpi_tmp)
						|| (!empty($pm_sdgs_enabled) && !empty($pm_sdg_tmp))
					);
				}
				$pm_s4_done_h = false;
				$pm_acts_tmp = [];
				if ($edit_project_id > 0 && function_exists('getProjectActivityList')) {
					$pm_acts_tmp = getProjectActivityList($db_Project, $edit_project_id);
					$pm_s4_done_h = !empty($pm_acts_tmp);
				}
				$pm_s5_done_h = false;
				if (!empty($pm_acts_tmp) && function_exists('getProjectActivityBudgetList')) {
					foreach ($pm_acts_tmp as $aa) {
						$aid = (int)($aa['id'] ?? 0);
						if ($aid <= 0) continue;
						$it = getProjectActivityBudgetList($db_Project, $aid);
						if (!empty($it)) { $pm_s5_done_h = true; break; }
					}
				}
				$pm_s6_done_h = is_array($saved_pre)
					&& trim(strip_tags((string)($saved_pre['evaluate_type'] ?? ''))) !== ''
					&& trim(strip_tags((string)($saved_pre['evaluate_tool'] ?? ''))) !== ''
					&& trim(strip_tags((string)($saved_pre['risk_action'] ?? ''))) !== ''
					&& trim(strip_tags((string)($saved_pre['risk_stop'] ?? ''))) !== '';
				$pm_all_done_h = $pm_s1_done_h && !empty($pm_section3_complete) && $pm_s3_done_h && $pm_s4_done_h && $pm_s5_done_h && $pm_s6_done_h;
				if (!empty($pm_is_midyear)) {
					$pm_all_done_h = $pm_all_done_h && (trim(strip_tags((string)$pm_midyear_reason)) !== '');
				}
				$pm_is_returned_edit_h = ($pm_status_now_h === '8');
				// ส่งร่าง: เฉพาะสถานะร่าง (0) เท่านั้น; โครงการระหว่างปีไม่ส่งร่าง — เข้า flow ขอดำเนินการ
				$pm_can_submit_h = ($edit_project_id > 0) && $pm_all_done_h && ($pm_status_now_h === '0') && empty($pm_is_midyear) && empty($pm_is_operate_returned_partial);
				$pm_show_change_cancel_btns = ($edit_project_id > 0) && !empty($pm_early_operate_chain_all_done) && empty($pm_is_cancelled) && empty($pm_is_plan_closed_h);
				if (!empty($pm_from_approve_inbox)) {
					$pm_show_change_cancel_btns = false;
				}
				if (!empty($pm_show_change_cancel_btns) && !$pm_is_plan_admin && (int)$staff_id > 0
					&& function_exists('pm_staff_is_reviewer_or_approver_on_project')
					&& pm_staff_is_reviewer_or_approver_on_project($db_Project, (int)$edit_project_id, (int)$staff_id)) {
					$pm_show_change_cancel_btns = false;
				}
				if (!empty($pm_show_change_cancel_btns) && function_exists('pm_resolve_ab_status')) {
					$pm_ab_btn = pm_resolve_ab_status(is_array($saved_pre) ? $saved_pre : [], [
						'db' => $db_Project,
						'project_id' => (int)$edit_project_id,
					]);
					if (in_array((string)($pm_ab_btn['mod'] ?? ''), ['a1', 'a2', 'b2', 'b4', 'b4_done', 'b5'], true)) {
						$pm_show_change_cancel_btns = false;
					}
				}
				$pm_chg_pending = false;
				$pm_cancel_pending = false;
				$pm_cancel_status = '';
				$pm_chg_wait_apply = false;
				$pm_change_history = [];
				$pm_chg_memos = [];
				$pm_chg_name = trim((string)($saved_pre['name_project'] ?? ''));
				$pm_chg_code = (string)($ref_display ?? '');
				$pm_chg_budget_fmt = '0';
				$pm_chg_budget_src = '-';
				if ($pm_show_change_cancel_btns && $edit_project_id > 0) {
					if (function_exists('pm_ensure_change_request_schema')) {
						pm_ensure_change_request_schema($db_Project);
					}
					$pm_chg_pending = function_exists('pm_project_pending_change_request_id')
						&& pm_project_pending_change_request_id($db_Project, (int)$edit_project_id) > 0;
					$__sumChg = @mysqli_query($db_Project, "SELECT IFNULL(SUM(pa.total),0) AS t FROM project_activity_budget pa WHERE pa.code_pre_project='" . (int)$edit_project_id . "' AND pa.status!='99'");
					$__srChg = $__sumChg ? mysqli_fetch_assoc($__sumChg) : null;
					$pm_chg_budget_fmt = number_format((float)($__srChg['t'] ?? 0), 0, '.', ',');
					$__cbChg = trim((string)($saved_pre['code_budget'] ?? ''));
					$__boChg = trim((string)($saved_pre['budget_other'] ?? ''));
					if ($__cbChg === '' || $__cbChg === '0') {
						$__cbChg = trim((string)($saved_budgets[0]['code_budget'] ?? ''));
					}
					if ($__boChg === '') {
						$__boChg = trim((string)($saved_budgets[0]['budget_other'] ?? ''));
					}
					if (($__cbChg === '' || $__cbChg === '0' || $__cbChg === '99' || $__cbChg === '99.0') && $__boChg === '') {
						$__qpbChg = @mysqli_query(
							$db_Project,
							"SELECT code_budget, budget_other
							 FROM project_budget
							 WHERE project_id='" . (int)$edit_project_id . "'
							 ORDER BY (status='1') DESC, id DESC
							 LIMIT 1"
						);
						$__rpbChg = $__qpbChg ? mysqli_fetch_assoc($__qpbChg) : null;
						if ($__rpbChg) {
							if ($__cbChg === '' || $__cbChg === '0' || $__cbChg === '99' || $__cbChg === '99.0') {
								$__tcb = trim((string)($__rpbChg['code_budget'] ?? ''));
								if ($__tcb !== '') {
									$__cbChg = $__tcb;
								}
							}
							if ($__boChg === '') {
								$__boChg = trim((string)($__rpbChg['budget_other'] ?? ''));
							}
						}
					}
					$pm_chg_budget_src = function_exists('pm_format_budget_source_label')
						? pm_format_budget_source_label($db_Project, $__cbChg, $__boChg)
						: '';
					if ($pm_chg_budget_src === '' || $pm_chg_budget_src === '-') {
						$pm_chg_budget_src = function_exists('resolveProjectBudgetSourceForDisplay')
							? resolveProjectBudgetSourceForDisplay($db_Project, (int)$edit_project_id)
							: '-';
					}
					if ($pm_chg_budget_src === '' || $pm_chg_budget_src === 'แหล่งงบรหัส 99') {
						$pm_chg_budget_src = '-';
					}
				}
				if ($edit_project_id > 0 && function_exists('pm_load_project_change_requests')) {
					$pm_change_history = pm_load_project_change_requests($db_Project, (int)$edit_project_id);
					foreach ($pm_change_history as $__chRow) {
						if ((string)($__chRow['req_status'] ?? '') === 'approved' && trim((string)($__chRow['applied_at'] ?? '')) === '') {
							$pm_chg_wait_apply = true;
							break;
						}
					}
				}
				if ($edit_project_id > 0) {
					if (function_exists('pm_ensure_cancel_request_schema')) {
						pm_ensure_cancel_request_schema($db_Project);
					}
					$pm_is_cancelled = function_exists('pm_project_is_cancelled')
						&& pm_project_is_cancelled($db_Project, (int)$edit_project_id, is_array($saved_pre) ? $saved_pre : null);
					$pm_cancel_req = function_exists('pm_load_project_cancel_request')
						? pm_load_project_cancel_request($db_Project, (int)$edit_project_id)
						: null;
					$pm_cancel_status = is_array($pm_cancel_req) ? trim((string)($pm_cancel_req['req_status'] ?? '')) : '';
					if ($pm_cancel_status === 'approved') {
						$pm_is_cancelled = true;
					}
					$pm_cancel_pending = ($pm_cancel_status === 'pending');
					if (!empty($pm_is_cancelled)) {
						$pm_show_change_cancel_btns = false;
					}
				}
			?>
	<div class="pm-project-toolbar">
		<div class="pm-project-toolbar-left">
			<a href="<?= htmlspecialchars($pm_back_url, ENT_QUOTES, 'UTF-8') ?>" class="btn btn-outline-secondary btn-sm pm-project-back-btn">
				<i class="fa fa-arrow-left mr-1"></i> กลับ
			</a>
