			</div>
			<div class="pm-admin-tags-hint">เพิ่มได้หลายคำ ใช้ค้นหาในหน้ารายการโครงการ · กด Enter หรือจุลภาคเพื่อบันทึก</div>
		</div>
		<style>
			.pm-admin-tags-wrap{position:relative;z-index:2;}
			.pm-admin-tags-label{font-weight:900;color:#334155;font-size:.88rem;margin-bottom:.35rem;}
			.pm-admin-tags-box{
				display:flex;flex-wrap:wrap;align-items:center;gap:.4rem;
				min-height:42px;padding:.4rem .55rem;border-radius:.75rem;
				background:#fff;border:1px dashed #cbd5e1;
			}
			.pm-admin-tags-box.is-disabled{background:#f8fafc;opacity:.75;}
			.pm-admin-tags-box:focus-within{border-color:#64748b;box-shadow:0 0 0 .16rem rgba(100,116,139,.18);}
			.pm-admin-tag-chip{
				display:inline-flex;align-items:center;gap:.28rem;
				background:linear-gradient(135deg,#eef2ff 0%,#e0e7ff 100%);
				color:#3730a3;border:1px solid #c7d2fe;border-radius:999px;
				padding:.18rem .55rem .18rem .7rem;font-size:.8rem;font-weight:800;line-height:1.3;
			}
			.pm-admin-tag-remove{
				border:0;background:transparent;color:#4338ca;font-size:1.05rem;line-height:1;
				padding:0;margin:0;cursor:pointer;font-weight:900;
			}
			.pm-admin-tag-remove:hover{color:#b91c1c;}
			.pm-admin-tag-input{
				border:0;outline:none;flex:1;min-width:180px;background:transparent;
				font-size:.88rem;font-weight:650;color:#334155;padding:.15rem .2rem;
			}
			.pm-admin-tags-hint{font-size:.78rem;color:#64748b;font-weight:650;margin-top:.3rem;}
		</style>
		<script>
		(function($){
			if (!window.PM_PLAN_ADMIN) return;
			var $box = $('#pmAdminTagsBox');
			var $input = $('#pmAdminTagInput');
			if (!$box.length) return;
			var pid = parseInt($('#edit_project_id').val() || '0', 10);
			var saveTimer = null;
			function collectTags(){
				var tags = [];
				$box.find('.pm-admin-tag-chip').each(function(){
					var t = String($(this).attr('data-tag') || '').trim();
					if (t) tags.push(t);
				});
				return tags;
			}
			function hasTag(tag){
				var key = tag.toLowerCase();
				var found = false;
				collectTags().forEach(function(t){ if (String(t).toLowerCase() === key) found = true; });
				return found;
			}
			function addChip(raw){
				var tag = String(raw || '').replace(/,/g,' ').replace(/\s+/g,' ').trim();
				if (!tag || hasTag(tag) || pid <= 0) return;
				var $chip = $('<span class="pm-admin-tag-chip"/>').attr('data-tag', tag);
				$chip.append(document.createTextNode(tag));
				$chip.append($('<button type="button" class="pm-admin-tag-remove" aria-label="ลบแท็ก">&times;</button>'));
				$input.before($chip);
			}
			function splitAndAdd(val){
				String(val || '').split(/[,;\n]+/).forEach(function(p){ addChip(p); });
			}
			function saveTags(){
				if (pid <= 0) return;
				$.ajax({
					url: '?page=project_manage&op=save_admin_tags_ajax',
					type: 'POST',
					dataType: 'json',
					data: { op: 'save_admin_tags_ajax', project_id: pid, tags_json: JSON.stringify(collectTags()) }
				});
			}
			function scheduleSave(){
				if (saveTimer) clearTimeout(saveTimer);
				saveTimer = setTimeout(saveTags, 250);
			}
			$input.on('keydown', function(e){
				if (e.key === 'Enter' || e.key === ',') {
					e.preventDefault();
					splitAndAdd($input.val());
					$input.val('');
					scheduleSave();
				} else if (e.key === 'Backspace' && String($input.val() || '') === '') {
					var $last = $box.find('.pm-admin-tag-chip').last();
					if ($last.length) { $last.remove(); scheduleSave(); }
				}
			});
			$input.on('blur', function(){
				splitAndAdd($input.val());
				$input.val('');
				scheduleSave();
			});
			$box.on('click', '.pm-admin-tag-remove', function(e){
				e.preventDefault();
				$(this).closest('.pm-admin-tag-chip').remove();
				scheduleSave();
			});
			$box.on('click', function(){ try { $input.trigger('focus'); } catch(_e){} });
		})(jQuery);
		</script>
