				function prefillDatepickersFromSaved() {
					try {
						var sm = parseInt($('#start_month').val() || '0', 10);
						var sy = parseInt($('#start_year').val() || '0', 10);
						// รองรับทั้งปี พ.ศ. (2567) และ ค.ศ. (2024)
						var startYearCe = (sy > 2400) ? (sy - 543) : sy;
						if (sm >= 1 && sm <= 12 && sy > 1900) {
							var startD = new Date(startYearCe, sm - 1, 1);
							$('#project_start_date').datepicker('setDate', startD);
							setProjectMonthYearFields($('#project_start_date'), startD, 'start');
							$('#project_end_date').datepicker('setStartDate', startD);
						}
						var em = parseInt($('#end_month').val() || '0', 10);
						var ey = parseInt($('#end_year').val() || '0', 10);
						var endYearCe = (ey > 2400) ? (ey - 543) : ey;
						if (em >= 1 && em <= 12 && ey > 1900) {
							var endD = new Date(endYearCe, em - 1, 1);
							$('#project_end_date').datepicker('setDate', endD);
							setProjectMonthYearFields($('#project_end_date'), endD, 'end');
						}
					} catch(e) {}
				}
				function pmUnitSelect2Matcher(params, data) {
					if ($.trim(params.term) === '') {
						return data;
					}
					var term = String(params.term).toLowerCase();
					if (data.children && data.children.length) {
						var filtered = [];
						$.each(data.children, function(_, child) {
							var matched = pmUnitSelect2Matcher(params, child);
							if (matched) {
								filtered.push(matched);
							}
						});
						if (!filtered.length) {
							return null;
						}
						var group = $.extend(true, {}, data);
						group.children = filtered;
						return group;
					}
					var text = String(data.text || '').toLowerCase();
					return text.indexOf(term) !== -1 ? data : null;
				}
				function pmInitGeneralModalSelect2($scope){
					if (typeof $.fn.select2 !== 'function') return false;
					var $m = $('#modalGeneralInfo');
					if (!$m.length) return false;
					try { $m.appendTo('body'); } catch (_eAp) {}
					var $root = ($scope && $scope.length) ? $scope : $m;
					$root.find('select[name="code_nature"], select[name="code_type"]').each(function(){
						var $sel = $(this);
						try {
							if ($sel.hasClass('select2-hidden-accessible')) {
								$sel.select2('destroy');
							}
						} catch (e0) {}
						var ph = String($sel.attr('data-placeholder') || $sel.find('option[value=""]').first().text() || '').trim() || '- ค้นหา -';
						var opts = {
							placeholder: ph,
							allowClear: true,
							width: '100%',
							dropdownParent: $m,
							minimumResultsForSearch: 0,
							language: {
								noResults: function(){ return 'ไม่พบรายการ'; },
								searching: function(){ return 'กำลังค้นหา...'; }
							}
						};
						if ($sel.is('[name="code_unit"], [name="code_unit_co[]"]')) {
							opts.matcher = pmUnitSelect2Matcher;
						}
						$sel.select2(opts);
					});
					return true;
				}
