				function escapeHtml(str) {
					return String(str ?? '')
						.replace(/&/g, '&amp;')
						.replace(/</g, '&lt;')
						.replace(/>/g, '&gt;')
						.replace(/"/g, '&quot;')
						.replace(/'/g, '&#039;');
				}
				// เพิ่มหน่วยงานร่วม
				var planUnitGroupsJs = <?= json_encode($plan_unit_groups_js, JSON_UNESCAPED_UNICODE) ?>;
				function pmUnitComboFlatOptions(includeOther) {
					var out = [];
					(planUnitGroupsJs || []).forEach(function(g) {
						(g.options || []).forEach(function(x) {
							out.push({ val: String(x.val || ''), name: String(x.name || '') });
						});
					});
					if (includeOther) {
						out.push({ val: '99', name: '- อื่นๆ (ระบุ)' });
					}
					return out;
				}
				function pmUnitComboSyncFromSelect($combo) {
					var $sel = $combo.find('select');
					var $inp = $combo.find('.pm-unit-combo-input');
					if (!$sel.length || !$inp.length) return;
					var val = String($sel.val() || '');
					var txt = '';
					if (val) {
						txt = String($sel.find('option:selected').text() || '').trim();
						if (txt === '- ค้นหาหน่วยงาน -' || txt === 'พิมพ์ค้นหาหน่วยงาน...' || txt === '- ค้นหา -' || txt === 'พิมพ์ค้นหารายชื่อ...') txt = '';
						if (txt && $sel.is('[name="code_unit"], [name="code_unit_co[]"]')) {
							txt = stripUnitCodeLabel(txt);
						}
					}
					$inp.val(txt).data('picked-text', txt);
					if ($sel.hasClass('unit-co-select')) {
						var wrap = $combo.closest('.unit-co-row').find('.unit-co-other-wrap').get(0);
						if (wrap) wrap.classList.toggle('d-none', val !== '99');
					}
				}
				function pmUnitComboInitAll() {
					$('#modalGeneralInfo .pm-unit-combo').each(function(){
						pmUnitComboSyncFromSelect($(this));
					});
				}
				function pmUnitComboRender($combo, q) {
					var $sel = $combo.find('select');
					var isStaff = $sel.is('[name="head_staff"], [name="coordinator_staff"], [name="participant_staff[]"]');
					var items;
					if (isStaff) {
						items = [];
						$sel.find('option').each(function(){
							var val = String($(this).val() || '');
							var name = String($(this).text() || '').trim();
							if (!val) return;
							items.push({ val: val, name: name });
						});
					} else {
						items = pmUnitComboFlatOptions($sel.is('[name="code_unit_co[]"]'));
					}
					var needle = String(q || '').toLowerCase().trim();
					var html = '';
					var shown = 0;
					items.forEach(function(it) {
						if (shown >= 80) return;
						var name = isStaff ? String(it.name || '') : stripUnitCodeLabel(String(it.name || ''));
						var hay = (name + ' ' + it.val + ' ' + String(it.name || '')).toLowerCase();
						if (needle && hay.indexOf(needle) === -1) return;
						html += '<button type="button" class="pm-unit-combo-item" data-val="' + escapeHtml(it.val) + '" data-name="' + escapeHtml(name) + '">' + escapeHtml(name) + '</button>';
						shown++;
					});
					if (!html) {
						html = '<div class="pm-unit-combo-empty">' + (needle
							? (isStaff ? 'ไม่พบรายชื่อ' : 'ไม่พบหน่วยงาน')
							: (isStaff ? 'พิมพ์ชื่อเพื่อค้นหา' : 'พิมพ์ชื่อหน่วยงาน')) + '</div>';
					}
					$combo.find('.pm-unit-combo-list').html(html).addClass('is-open');
				}
				function pmUnitComboCloseAll(exceptEl) {
					$('#modalGeneralInfo .pm-unit-combo-list').each(function(){
						if (exceptEl && this === exceptEl) return;
						$(this).removeClass('is-open').empty();
					});
				}
				$(document).on('focus input', '#modalGeneralInfo .pm-unit-combo-input', function(){
					var $input = $(this);
					var $combo = $input.closest('.pm-unit-combo');
					var $sel = $combo.find('select');
					var typed = String($input.val() || '');
					if (typed !== String($input.data('picked-text') || '')) {
						$sel.val('').trigger('change');
					}
					pmUnitComboCloseAll($combo.find('.pm-unit-combo-list').get(0));
					pmUnitComboRender($combo, typed);
				});
				$(document).on('keydown', '#modalGeneralInfo .pm-unit-combo-input', function(e){
					var $combo = $(this).closest('.pm-unit-combo');
					var $list = $combo.find('.pm-unit-combo-list');
					if (!$list.hasClass('is-open')) return;
					var $items = $list.find('.pm-unit-combo-item');
					if (!$items.length) return;
					var $cur = $items.filter('.is-active').first();
					var idx = $items.index($cur);
					if (e.key === 'ArrowDown') {
						e.preventDefault();
						idx = Math.min($items.length - 1, idx + 1);
						$items.removeClass('is-active').eq(idx).addClass('is-active');
						$items.get(idx).scrollIntoView({ block: 'nearest' });
					} else if (e.key === 'ArrowUp') {
						e.preventDefault();
						idx = Math.max(0, idx < 0 ? 0 : idx - 1);
						$items.removeClass('is-active').eq(idx).addClass('is-active');
						$items.get(idx).scrollIntoView({ block: 'nearest' });
					} else if (e.key === 'Enter') {
						e.preventDefault();
						($cur.length ? $cur : $items.first()).trigger('mousedown');
					} else if (e.key === 'Escape') {
						pmUnitComboCloseAll();
					}
				});
				$(document).on('mousedown', '#modalGeneralInfo .pm-unit-combo-item', function(e){
					e.preventDefault();
					var $item = $(this);
					var $combo = $item.closest('.pm-unit-combo');
					var val = String($item.attr('data-val') || '');
					var name = String($item.attr('data-name') || '');
					$combo.find('select').val(val).trigger('change');
					$combo.find('.pm-unit-combo-input').val(name).data('picked-text', name);
					$combo.find('.pm-unit-combo-list').removeClass('is-open').empty();
				});
