				function optText(sel) {
					if (!sel) return '';
					var opt = sel.options[sel.selectedIndex];
					return (opt && opt.value) ? opt.text : '';
				}

				/** ตัดรหัสหน่วยงานหน้าชื่อ เช่น "U041 - หน่วย..." / "12010102 — หน่วย..." -> "หน่วย..." */
				function stripUnitCodeLabel(label) {
					var s = String(label || '').trim();
					if (!s) return '';
					var m = s.match(/^[A-Za-z0-9._]+\s*[—\-–]\s*(.+)$/);
					return m && m[1] ? String(m[1]).trim() : s;
				}

				function getInputVal(selector) {
					var el = document.querySelector(selector);
					return el ? (el.value || '') : '';
				}

				function getGeneralInfoStateStr() {
					var modal = document.getElementById('modalGeneralInfo');
					if (!modal) return '';

					function getValBySel(sel) {
						var el = modal.querySelector(sel);
						return el ? String(el.value || '').trim() : '';
					}

					var headStaff = getValBySel('select[name="head_staff"]');
					var headPhone = getValBySel('input[name="head_phone"]');
					var coordinatorStaff = getValBySel('select[name="coordinator_staff"]');
					var coordinatorPhone = getValBySel('input[name="coordinator_phone"]');

					var participantRows = Array.from(modal.querySelectorAll('#participant-rows-container .participant-row'));
					var participants = participantRows.map(function(row){
						var sel = row.querySelector('select[name="participant_staff[]"]');
						var phone = row.querySelector('input[name="participant_phone[]"]');
						return {
							staff: sel ? String(sel.value || '').trim() : '',
							phone: phone ? String(phone.value || '').trim() : ''
						};
					}).filter(function(x){
						return (x.staff || '').trim() !== '' || (x.phone || '').trim() !== '';
					});

					var unitMain = getValBySel('select[name="code_unit"]');
					var unitCoRows = Array.from(modal.querySelectorAll('#unit-co-rows-container .unit-co-row'));
					var unitCos = unitCoRows.map(function(row){
						var sel = row.querySelector('select[name="code_unit_co[]"]');
						var other = row.querySelector('.unit-co-other-wrap input[name="code_unit_co_other[]"]');
						return {
							unit: sel ? String(sel.value || '').trim() : '',
							other: other ? String(other.value || '').trim() : ''
						};
					}).filter(function(x){
						return (x.unit || '').trim() !== '' || (x.other || '').trim() !== '';
					});

					var nature = getValBySel('select[name="code_nature"]');
					var type = getValBySel('select[name="code_type"]');
					var budget = '99';
					var budgetOther = getValBySel('input[name="budget_other"]');

					// Date: ใช้ค่า raw เหมือนที่หน้ามีอยู่ (เพื่อเทียบง่าย)
					var startDateRaw = '';
					var projectStart = document.getElementById('project_start_date');
					var startDateText = document.getElementById('start_date_text');
					if (startDateText && startDateText.value) startDateRaw = String(startDateText.value || '').trim();
					else if (projectStart && projectStart.value) startDateRaw = String(projectStart.value || '').trim();
					else {
						var sm = getValBySel('#start_month');
						var sy = getValBySel('#start_year');
						startDateRaw = (sm && sy) ? (sm + '/' + sy) : '';
					}

					var endDateRaw = '';
					var projectEnd = document.getElementById('project_end_date');
					var endDateText = document.getElementById('end_date_text');
					if (endDateText && endDateText.value) endDateRaw = String(endDateText.value || '').trim();
					else if (projectEnd && projectEnd.value) endDateRaw = String(projectEnd.value || '').trim();
					else {
						var em = getValBySel('#end_month');
						var ey = getValBySel('#end_year');
						endDateRaw = (em && ey) ? (em + '/' + ey) : '';
					}

					var location = getValBySel('textarea[name="location"]');
					var generalNote = getValBySel('textarea[name="general_note"]');

					return JSON.stringify({
						headStaff: headStaff,
						headPhone: headPhone,
						coordinatorStaff: coordinatorStaff,
						coordinatorPhone: coordinatorPhone,
						participants: participants,
						unitMain: unitMain,
						unitCos: unitCos,
						nature: nature,
						type: type,
						budget: budget,
						budgetOther: budgetOther,
						startDateRaw: startDateRaw,
						endDateRaw: endDateRaw,
						location: location,
						generalNote: generalNote
					});
				}

				function syncGeneralInfoBannerButton() {
					var btn = document.querySelector('#general-info-summary .pm-ginfo-banner button[data-target="#modalGeneralInfo"]');
					if (!btn) return;
					btn.classList.remove('btn-pm-primary', 'btn-warning', 'text-white', 'text-dark');
					var hasData = (window.__ginfo_has_data === true);
					if (hasData) btn.classList.add('btn-warning', 'text-dark');
					else btn.classList.add('btn-pm-primary', 'text-white');
				}

				function updateGeneralInfoDirty() {
					var last = window.__ginfo_lastSavedStateStr || '';
					var cur = getGeneralInfoStateStr();
					var dirty = (cur !== last);
					window.__ginfo_dirty = dirty;
					syncGeneralInfoBannerButton();
				}

				function buildGeneralInfoSummary() {
					var markSaved = (arguments.length > 0 && !!arguments[0]);
					if (markSaved) {
						// เมื่อต้องการ “บันทึกในหน้าจอ” ให้ถือว่า baseline ใหม่ล่าสุดคือค่าปัจจุบัน
						window.__ginfo_lastSavedStateStr = getGeneralInfoStateStr();
						window.__ginfo_dirty = false;
					}

					var modal = document.getElementById('modalGeneralInfo');
					var headName = optText(modal ? modal.querySelector('select[name="head_staff"]') : null);
					var headPhone = modal ? getInputVal('#modalGeneralInfo input[name="head_phone"]') : '';
					var coordName = optText(modal ? modal.querySelector('select[name="coordinator_staff"]') : null);
					var coordPhone = modal ? getInputVal('#modalGeneralInfo input[name="coordinator_phone"]') : '';

					var participantRows = Array.from((modal ? modal : document).querySelectorAll('#participant-rows-container .participant-row'));
					var participants = participantRows.map(function(row) {
						var sel = row.querySelector('select[name="participant_staff[]"]');
						var phone = row.querySelector('input[name="participant_phone[]"]');
						var name = optText(sel);
						var ph = phone ? phone.value.trim() : '';
						if (!name && !ph) return null;
						return name + (ph ? ' (' + ph + ')' : '');
					}).filter(Boolean);

					var unitMain = stripUnitCodeLabel(optText(modal ? modal.querySelector('select[name="code_unit"]') : null));
					var unitCoRows = Array.from((modal ? modal : document).querySelectorAll('#unit-co-rows-container .unit-co-row'));
					var unitCos = unitCoRows.map(function(row) {
						var sel = row.querySelector('select[name="code_unit_co[]"]');
						var name = stripUnitCodeLabel(optText(sel));
						if (!name) return null;
						var otherWrap = row.querySelector('.unit-co-other-wrap input[name="code_unit_co_other[]"]');
						var otherVal = otherWrap ? otherWrap.value.trim() : '';
						if ((sel && sel.value === '99') && otherVal) {
							name = otherVal;
						}
						// หน่วยงานร่วม: ต่อท้ายวงเล็บตามที่ต้องการแสดงผล
						if (name.indexOf('(หน่วยงานร่วม)') === -1) {
							name = name + ' (หน่วยงานร่วม)';
						}
						return name;
					}).filter(Boolean);

					var nature = optText(modal ? modal.querySelector('select[name="code_nature"]') : null);
					var type = optText(modal ? modal.querySelector('select[name="code_type"]') : null);
					var budgetOther = modal ? getInputVal('#modalGeneralInfo input[name="budget_other"]') : '';
					var budgetName = budgetOther || '-';

					var startDateTxt = (document.getElementById('start_date_text')?.value || '').trim() || (document.getElementById('project_start_date')?.value || '').trim();
					var endDateTxt = (document.getElementById('end_date_text')?.value || '').trim() || (document.getElementById('project_end_date')?.value || '').trim();
					if (!startDateTxt) {
						var sm = getInputVal('#start_month'); var sy = getInputVal('#start_year');
						if (sm && sy) startDateTxt = sm + '/' + sy;
					}
					if (!endDateTxt) {
						var em = getInputVal('#end_month'); var ey = getInputVal('#end_year');
						if (em && ey) endDateTxt = em + '/' + ey;
					}
					function monthYearToThai(s) {
						if (!s || typeof s !== 'string') return s || '-';
						var parts = s.trim().split('/');
						var m = parseInt(parts[0], 10);
						var yRaw = String(parts[1] || '').trim();
						var yNum = parseInt(yRaw, 10);
						// แสดงเป็น พ.ศ. เสมอ (ถ้าได้ ค.ศ. ให้ +543)
						if (!isNaN(yNum) && yNum > 0 && yNum < 2400) {
							yRaw = String(yNum + 543);
						}
						var thaiMonths = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
						var monthName = (m >= 1 && m <= 12) ? thaiMonths[m - 1] : s;
						return monthName + (yRaw ? ' ' + yRaw : '');
					}
					startDateTxt = monthYearToThai(startDateTxt);
					endDateTxt = monthYearToThai(endDateTxt);

					var locEl = modal ? modal.querySelector('textarea[name="location"]') : null;
					var location = (locEl ? (locEl.value || '') : '').trim();
					var noteEl = modal ? modal.querySelector('textarea[name="general_note"]') : null;
					var generalNote = (noteEl ? (noteEl.value || '') : '').trim();

					// ปรับสีปุ่มในแถบสรุปตาม "มีข้อมูลแล้วหรือยัง"
					var hasData = Boolean(
						(headName && String(headName).trim()) ||
						(coordName && String(coordName).trim()) ||
						(participants && participants.length) ||
						(unitMain && String(unitMain).trim()) ||
						(unitCos && unitCos.length) ||
						(nature && String(nature).trim()) ||
						(type && String(type).trim()) ||
						(budgetName && String(budgetName).trim()) ||
						(location && String(location).trim()) ||
						(generalNote && String(generalNote).trim()) ||
						(startDateTxt && String(startDateTxt).trim()) ||
						(endDateTxt && String(endDateTxt).trim())
					);
					window.__ginfo_has_data = hasData;
					var btnClass = hasData
						? 'btn btn-sm btn-warning text-dark'
						: 'btn btn-sm btn-pm-primary text-white';
					var stNowGeneral = String($('#status_project_now').val() || '0');
					var reportFrozen = !!(window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE);
					var operateApproved = !!window.PM_OPERATE_APPROVED;
					var includeMeetingLock = !!window.PM_INCLUDE_MEETING_LOCK;
					var planFixResubmitLock = !!window.PM_PLAN_FIX_RESUBMIT_LOCK;
					var operateReplyLock = !!window.PM_OPERATE_REPLY_LOCK;
					var canEditGeneral = !reportFrozen && !operateApproved && !includeMeetingLock && !planFixResubmitLock && !operateReplyLock && (!!window.PM_PLAN_ADMIN || (stNowGeneral !== '1' && stNowGeneral !== '2' && stNowGeneral !== '3' && stNowGeneral !== '4'));
					var generalBtnTitle = reportFrozen
						? 'รอตรวจสอบรายงานผล แก้ไขไม่ได้จนกว่าจะถูกตีกลับ'
						: (includeMeetingLock
						? 'นำเข้าที่ประชุมแล้ว ไม่สามารถแก้ไขได้'
						: (planFixResubmitLock
						? 'ส่งแก้ไขกลับหน่วยแผนแล้ว ไม่สามารถแก้ไขได้จนกว่าจะถูกตีกลับ'
						: (operateApproved
						? 'อนุมัติดำเนินการแล้ว ไม่สามารถแก้ไขข้อมูลทั่วไปได้'
						: (canEditGeneral
						? 'แก้ไขข้อมูลทั่วไป'
						: 'รอผู้ตรวจสอบพิจารณา แก้ไขไม่ได้จนกว่าจะตีกลับให้แก้ไข'))));
					var generalBtnHtml = '';
					if (canEditGeneral) {
						generalBtnHtml = '    <button type="button" class="' + btnClass + '" title="' + escapeHtml(generalBtnTitle) + '" data-toggle="modal" data-target="#modalGeneralInfo"><i class="fa fa-edit mr-1"></i> แก้ไข</button>';
					}

					var left = [
						{ label: 'ผู้รับผิดชอบโครงการ', value: headName, phone: headPhone, required: true },
						{ label: 'ผู้ประสานงาน', value: coordName, phone: coordPhone, required: true },
						{ label: 'ผู้ร่วมโครงการ (ถ้ามี)', value: participants.length ? participants.join(', ') : '-' },
						{ label: 'หน่วยงานหลัก', value: unitMain || '-', required: true },
						{ label: 'หน่วยงานร่วม (ถ้ามี)', value: unitCos.length ? unitCos.join(', ') : '-' }
					];
					var right = [
						{ label: 'ลักษณะโครงการ', value: nature || '-', required: true },
						{ label: 'ประเภทโครงการ', value: type || '-', required: true },
						{ label: 'แหล่งงบที่ยื่นขอ (ถ้ามี)', value: budgetName || '-' },
						{ label: 'ระยะเวลาดำเนินโครงการ', value: (startDateTxt || endDateTxt) ? ('เริ่ม: ' + (startDateTxt || '-') + ' | สิ้นสุด: ' + (endDateTxt || '-')) : '-', required: true },
						{ label: 'พื้นที่ดำเนินโครงการ', value: location || '-' },
						{ label: 'หมายเหตุ (ถ้ามี)', value: generalNote || '-' }
					];

					function rowHtml(item) {
						var v = item.value ?? '-';
						if (item.phone !== undefined) {
							var phone = (item.phone || '').trim();
							v = (item.value || '-') + (phone ? ' (' + phone + ')' : '');
						}
						var req = (window.PM_SHOW_SECTION_REQUIRED && item.required) ? ' <span class="text-danger">*</span>' : '';
						return '<div class="d-flex py-1 align-items-start" style="gap:10px;">'
							+ '<div class="summary-label">' + escapeHtml(item.label) + req + ' :</div>'
							+ '<div class="summary-value flex-grow-1">' + escapeHtml(v) + '</div>'
							+ '</div>';
					}

					var s1Complete = !!(
						(headName && String(headName).trim()) &&
						(headPhone && String(headPhone).trim()) &&
						(coordName && String(coordName).trim()) &&
						(coordPhone && String(coordPhone).trim()) &&
						(unitMain && String(unitMain).trim() && unitMain !== '-') &&
						(nature && String(nature).trim() && nature !== '-') &&
						(type && String(type).trim() && type !== '-') &&
						startDateTxt && startDateTxt !== '-' &&
						endDateTxt && endDateTxt !== '-'
					);
					if (typeof setStepCircle === 'function') setStepCircle('#step-s1-circle', s1Complete);

					var s1IncHtml = window.PM_SHOW_SECTION_REQUIRED
						? ('<div id="pm-incomplete-s1" class="pm-section-incomplete-msg' + (s1Complete ? ' d-none' : '') + '">กรุณากรอกข้อมูลให้ครบถ้วน</div>')
						: '';
					var html = ''
						+ '<div class="pm-ginfo-single">'
						+ '  <div class="pm-section2-banner pm-ginfo-banner" style="justify-content:space-between;">'
						+ '    <span><i class="fa fa-info-circle"></i> ส่วนที่ 1 ข้อมูลทั่วไป' + (window.PM_SHOW_SECTION_REQUIRED ? ' <span class="text-danger">*</span>' : '') + '</span>'
						+ generalBtnHtml
						+ '  </div>'
						+ s1IncHtml
						+ '  <div class="p-3">'
						+ '    <div class="row">'
						+ '      <div class="col-md-6">' + left.map(rowHtml).join('') + '</div>'
						+ '      <div class="col-md-6">' + right.map(rowHtml).join('') + '</div>'
						+ '    </div>'
						+ '  </div>'
						+ '</div>';

					document.getElementById('general-info-summary').innerHTML = html;
				}

					document.getElementById('btnModalSaveGeneral').addEventListener('click', function(){
					var projectId = parseInt($('#edit_project_id').val() || '0', 10);
					if (projectId <= 0) {
						if (typeof Swal !== 'undefined') {
							Swal.fire({ icon: 'warning', title: 'กรุณาบันทึกโครงการก่อน', text: 'ต้องบันทึกโครงการให้ได้เลขโครงการก่อน จึงจะแก้ไขข้อมูลทั่วไปได้' });
						} else {
							alert('กรุณาบันทึกโครงการก่อน');
						}
						return;
					}
					// sync: กันกรณี datepicker ไม่ trigger changeDate แต่ text (mm/yyyy) มีค่า
					(function(){
						function parseMY(txt){
							txt = String(txt || '').trim();
							var m = txt.match(/^(\d{1,2})\s*\/\s*(\d{4})$/);
							if (!m) return null;
							var mm = parseInt(m[1], 10);
							var yy = parseInt(m[2], 10);
							if (!mm || mm < 1 || mm > 12 || !yy) return null;
							return { mm: String(mm), yy: String(yy), raw: (String(mm) + '/' + String(yy)) };
						}
						var s = parseMY($('#project_start_date').val());
						if (s) { $('#start_month').val(s.mm); $('#start_year').val(s.yy); $('#start_date_text').val(s.raw); }
						var e = parseMY($('#project_end_date').val());
						if (e) { $('#end_month').val(e.mm); $('#end_year').val(e.yy); $('#end_date_text').val(e.raw); }
					})();
					var periodErr = validateProjectPeriodRange();
					if (periodErr) {
						if (typeof Swal !== 'undefined') {
							Swal.fire({ icon: 'warning', title: 'วันที่ไม่ถูกต้อง', text: periodErr });
						} else {
							alert(periodErr);
						}
						$('#project_end_date').focus();
						return;
					}

					var payload = $('#modalGeneralInfo').find(':input[name]').serialize();
					payload += '&project_id=' + encodeURIComponent(String(projectId));

					$.ajax({
						url: '?page=project_manage&op=save_general_info_ajax',
						type: 'POST',
						dataType: 'text',
						data: payload
					}).done(function(respText){
						var r = null;
						try { r = JSON.parse(String(respText || '').replace(/^\uFEFF/, '').trim()); } catch(e0) {
							var t = String(respText || '');
							var i = t.indexOf('{'); var j = t.lastIndexOf('}');
							if (i >= 0 && j > i) { try { r = JSON.parse(t.substring(i, j + 1)); } catch(e1) {} }
						}
						if (r && (r.ok === 1 || r.ok === true || String(r.ok) === '1')) {
						// ตรวจเช็คว่า backend บันทึกค่าช่วงเวลาได้จริง (กันเคสขึ้นสำเร็จแต่ไม่ถูกบันทึก)
						try {
							var p = (r && r.posted) ? r.posted : {};
							var s = (r && r.saved) ? r.saved : {};
							var postedEnd = String((p.end_month || '')).trim() + '/' + String((p.end_year || '')).trim();
							var savedEnd = String((s.end_month || '')).trim() + '/' + String((s.end_year || '')).trim();
							var postedHasEnd = (String(p.end_month || '').trim() !== '' && String(p.end_year || '').trim() !== '');
							var savedHasEnd = (String(s.end_month || '').trim() !== '' && String(s.end_year || '').trim() !== '');
							if (postedHasEnd && !savedHasEnd) {
								var msg = 'ระบบแจ้งบันทึกสำเร็จ แต่เดือน/ปี สิ้นสุดยังไม่ถูกบันทึก (ส่งค่า ' + postedEnd + ', แต่บันทึกได้ ' + savedEnd + ')';
								if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ', text: msg });
								else alert(msg);
								return;
							}
						} catch(e) {}
						try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd) {}
						if (typeof Swal !== 'undefined') {
							Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', timer: 900, showConfirmButton: false });
						}
						setTimeout(function(){ window.location.reload(); }, 500);
						} else {
							var msg2 = (r && r.msg) ? r.msg : 'บันทึกไม่สำเร็จ';
							try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd2) {}
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ', text: msg2, confirmButtonText: 'ตกลง' });
							else alert(msg2);
						}
					}).fail(function(xhr){
						var r = null;
						try {
							var raw = String((xhr && xhr.responseText) || '');
							var i = raw.indexOf('{'); var j = raw.lastIndexOf('}');
							if (i >= 0 && j > i) r = JSON.parse(raw.substring(i, j + 1));
						} catch(e) {}
						if (r && (r.ok === 1 || r.ok === true || String(r.ok) === '1')) {
							try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd3) {}
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', timer: 900, showConfirmButton: false });
							setTimeout(function(){ window.location.reload(); }, 500);
							return;
						}
						var msg = (r && r.msg) ? r.msg : 'เกิดข้อผิดพลาดในการบันทึก';
						try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd4) {}
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'ผิดพลาด', text: msg, confirmButtonText: 'ตกลง' });
						else alert(msg);
					});
				});
				if (window.__autoBuildSummary) {
					setTimeout(function(){ try { buildGeneralInfoSummary(true); } catch(e){} }, 0);
				}

				function setHeaderMode(mode) {
					var isView = mode === 'view';
					var nameInput = document.getElementById('name_project_input');
					var nameText = document.getElementById('name_project_text');
					var nameReq = document.getElementById('name_project_req');
					var yearSel = document.getElementById('year_project_select');
					var yearText = document.getElementById('year_project_text');
					var yearReq = document.getElementById('year_project_req');
					var btnEdit = document.getElementById('btnToggleHeaderEdit');
					var saveBtns = document.querySelectorAll('.pm-save-btn');

					if (isView) {
						nameText.textContent = (nameInput.value || '').trim();
						yearText.textContent = yearSel.value || '';
						nameText.classList.remove('d-none');
						yearText.classList.remove('d-none');
						nameInput.classList.add('d-none');
						yearSel.classList.add('d-none');
						nameReq.classList.add('d-none');
						yearReq.classList.add('d-none');

						// ซ่อนปุ่มบันทึกทั้งหมดในโหมดแสดงผล
						saveBtns.forEach(function (b) { b.classList.add('d-none'); });

						// ปุ่มหลัก: แสดงเป็น "แก้ไข" (เหลือง) เมื่อมีชื่อโครงการแล้ว
						if (btnEdit) {
							btnEdit.classList.remove('btn-primary');
							btnEdit.classList.add('btn-pm-edit-orange');
							btnEdit.innerHTML = '<i class="fa fa-edit mr-1"></i> แก้ไข';
						}
					} else {
