						yearSel.classList.remove('d-none');
						yearReq.classList.remove('d-none');

						// โหมดแผนปฏิบัติการ: ห้ามแก้ชื่อโครงการ — แสดงเป็นข้อความเหมือนโหมดดู
						if (window.PM_LOCK_PROJECT_NAME) {
							nameText.textContent = (nameInput.value || '').trim();
							nameText.classList.remove('d-none');
							nameInput.classList.add('d-none');
							nameReq.classList.add('d-none');
						} else {
							nameText.classList.add('d-none');
							nameInput.classList.remove('d-none');
							nameReq.classList.remove('d-none');
							setTimeout(function(){ nameInput.focus(); }, 0);
						}

						// โชว์ปุ่มบันทึกเมื่อเข้าโหมดแก้ไข (ยกเว้นโครงการที่ล็อกชื่อแล้ว)
						if (!window.PM_LOCK_PROJECT_NAME) {
							saveBtns.forEach(function (b) { b.classList.remove('d-none'); });
						}

						// ปุ่มหลัก: กลับเป็น "ปิดการแก้ไข" (น้ำเงิน)
						if (btnEdit) {
							btnEdit.classList.remove('btn-pm-edit-orange');
							btnEdit.classList.add('btn-primary');
							btnEdit.innerHTML = '<i class="fa fa-times mr-1"></i> ปิดการแก้ไข';
						}
					}
				}

				(function(){
					var btnHdr = document.getElementById('btnToggleHeaderEdit');
					if (!btnHdr) return;
					btnHdr.addEventListener('click', function(){
						var nameInput = document.getElementById('name_project_input');
						var isCurrentlyView = nameInput.classList.contains('d-none');
						setHeaderMode(isCurrentlyView ? 'edit' : 'view');
					});
				})();

				(function(){
					var btnPrint = document.getElementById('btnPrintProject');
					if (btnPrint) {
						btnPrint.addEventListener('click', function(){
							var pid = parseInt(btnPrint.getAttribute('data-project-id') || '0', 10) || 0;
							if (pid <= 0) {
								if (typeof Swal !== 'undefined') {
									Swal.fire({ icon: 'info', title: 'กรุณาบันทึกโครงการก่อน', text: 'บันทึกโครงการให้ได้รหัสอ้างอิงก่อน จึงจะพิมพ์รายละเอียดได้' });
								} else {
									alert('กรุณาบันทึกโครงการก่อนพิมพ์');
								}
								return;
							}
							window.open('?page=project_manage&op=print_project&project_id=' + pid, '_blank', 'noopener');
						});
					}
				})();

				document.getElementById('name_project_input').addEventListener('input', function(){
					var t = document.getElementById('name_project_text');
					if (t) t.textContent = (this.value || '').trim();
				});
				document.getElementById('year_project_select').addEventListener('change', function(){
					var t = document.getElementById('year_project_text');
					if (t) t.textContent = this.value || '';
				});

				// ถ้ามีชื่อโครงการแล้ว ให้เริ่มต้นเป็นโหมดแสดงผล (และซ่อนปุ่มบันทึก)
				var __hasName = (String((document.getElementById('name_project_input')?.value || '')).trim() !== '');
				if (window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE || window.PM_LOCK_PROJECT_NAME) {
					setHeaderMode('view');
					var __btnHdrEdit = document.getElementById('btnToggleHeaderEdit');
					if (__btnHdrEdit) __btnHdrEdit.classList.add('d-none');
					document.querySelectorAll('.pm-save-btn').forEach(function(b){ b.classList.add('d-none'); });
				} else {
					setHeaderMode(__hasName ? 'view' : 'edit');
				}
				// เช็คเดือน/ปี: เดือน/ปี สิ้นสุดต้องไม่น้อยกว่าเดือน/ปี เริ่มต้น
				document.getElementById('form-add-project').addEventListener('submit', function(e){
					if ((window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE) && window.PM_CAN_FILL_PROJECT_RESULTS) {
						e.preventDefault();
						if (typeof Swal !== 'undefined') {
							Swal.fire({ icon: 'info', title: 'รอตรวจสอบรายงานผล', text: 'ไม่สามารถแก้ไขได้จนกว่าจะถูกตีกลับให้แก้ไข' });
						} else {
							alert('ไม่สามารถแก้ไขได้จนกว่าจะถูกตีกลับให้แก้ไข');
						}
						return false;
					}
					var periodErr = validateProjectPeriodRange();
					if (periodErr) {
						e.preventDefault();
						if (typeof Swal !== 'undefined') {
							Swal.fire({ icon: 'warning', title: 'วันที่ไม่ถูกต้อง', text: periodErr });
						} else {
							alert(periodErr);
						}
						$('#project_end_date').focus();
						return false;
					}
				});
