							<?php if ($has_val): ?>
										<?php
										$raw = (string)($f['saved'] ?? '');
										$raw = trim($raw);
										// sanitize ขั้นพื้นฐาน: ตัด script/style และ event handlers ออก แล้วคง tag ที่ใช้จัดรูปแบบไว้
										$raw = preg_replace('#<(script|style)\b[^>]*>.*?</\1>#is', '', $raw);
										$raw = preg_replace('/\son\w+="[^"]*"/i', '', $raw);
										$raw = preg_replace("/\son\w+='[^']*'/i", '', $raw);
										// ตัด font/size/style จาก Word/Summernote ให้แสดงฟอนต์ปกติ
										$raw = preg_replace('#</?font\b[^>]*>#i', '', $raw);
										$raw = preg_replace('/\s(style|face|color|size)\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i', '', $raw);
