				<script>
				(function(){
					var currentField = null;
					var $editor = null;
					$(document).on('click', '.btn-section2-edit', function(){
						var field = $(this).data('field');
						var label = $(this).data('label');
						var ta = document.getElementById('section2-' + field);
						var val = ta ? ta.value : '';
						currentField = field;
						$('#modalSection2EditorTitle').text(label);
						$('#section2-summernote-editor').val(val);
						if ($editor && $editor.length) { try { $editor.summernote('destroy'); } catch(e){} }
						$editor = $('#section2-summernote-editor');
						$editor.summernote({
							height: 320,
							toolbar: [['style',['style']],['font',['bold','italic','underline','clear']],['para',['ul','ol','paragraph']],['insert',['link']],['view',['fullscreen','codeview']]],
							placeholder: (field === 'midyear_reason'
								? 'ระบุ GAP ที่พบ และเหตุผลความจำเป็นของโครงการในการขับเคลื่อนให้บรรลุเป้าหมายของคณะ'
								: 'กรอก'),
							callbacks: {
								onInit: function(){
									try {
										$('#modalSection2Editor .note-editable').css({
											fontFamily: 'inherit',
											fontSize: '1rem',
											fontWeight: '400',
											lineHeight: '1.65',
											color: '#212529'
										});
									} catch(eInit) {}
								}
							}
						});
						$('#modalSection2Editor').modal('show');
					});
					function pmNormalizeSection2Html(html){
						var t = String(html || '');
						t = t.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
						t = t.replace(/\son\w+=("[^"]*"|'[^']*'|[^\s>]+)/gi, '');
						t = t.replace(/<\/?font\b[^>]*>/gi, '');
						t = t.replace(/\s(style|face|color|size)=("[^"]*"|'[^']*'|[^\s>]+)/gi, '');
						return t;
					}
					$('#btnSection2ModalSave').on('click', function(){
						if (!currentField) return;
						var html = pmNormalizeSection2Html($editor.summernote('code') || '');
						$('#section2-' + currentField).val(html);
						var viewEl = document.getElementById('section2-view-' + currentField);
						if (viewEl) {
							var emptyHint = String($(viewEl).attr('data-empty-hint') || 'กรอก');
							viewEl.innerHTML = html ? '<div class="section2-content">' + html + '</div>' : '<div class="pm-s3-empty-hint"></div>';
							if (!html) $(viewEl).find('.pm-s3-empty-hint').text(emptyHint);
						}
						var $btn = $('.btn-section2-edit[data-field="' + currentField + '"]');
						$btn.removeClass('btn-primary btn-warning').addClass(html ? 'btn-warning' : 'btn-primary');
						$btn.html(html ? '<i class="fa fa-edit mr-1"></i> แก้ไข' : '<i class="fa fa-plus mr-1"></i> เพิ่ม');
						var projectId = parseInt($('#edit_project_id').val() || '0', 10);
						var fieldSaved = currentField;
						function pmParseAjaxJson(raw){
							var t = String(raw || '').replace(/^\uFEFF/, '').trim();
							if (!t) return null;
							try { return JSON.parse(t); } catch(e0) {}
							var i = t.indexOf('{');
							var j = t.lastIndexOf('}');
							if (i >= 0 && j > i) {
								try { return JSON.parse(t.substring(i, j + 1)); } catch(e1) {}
							}
							return null;
						}
						function pmClearModalTrap(){
							try {
								$('body').removeClass('modal-open').css('padding-right', '');
								$('.modal-backdrop').remove();
							} catch(e) {}
						}
						function pmShowSaveResult(ok, msg){
							pmClearModalTrap();
							if (typeof Swal === 'undefined') {
								alert(ok ? 'บันทึกสำเร็จ' : (msg || 'บันทึกไม่สำเร็จ'));
								return;
							}
							if (ok) {
								Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', showConfirmButton: false, timer: 1500 });
							} else {
								Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ', text: msg || 'กรุณาลองใหม่', confirmButtonText: 'ตกลง' }).then(function(){
									pmClearModalTrap();
								});
							}
						}
						if (projectId > 0) {
							$.ajax({
								url: '?page=project_manage&op=save_section2_field',
								type: 'POST',
								data: { project_id: projectId, field: fieldSaved, value: html },
								dataType: 'text'
							}).done(function(respText) {
								var r = pmParseAjaxJson(respText);
								if (r && (r.ok === 1 || r.ok === true || String(r.ok) === '1')) {
									pmShowSaveResult(true);
								} else {
									pmShowSaveResult(false, (r && r.msg) ? r.msg : 'กรุณาลองใหม่');
								}
							}).fail(function(xhr) {
								var r = pmParseAjaxJson(xhr && xhr.responseText);
								if (r && (r.ok === 1 || r.ok === true || String(r.ok) === '1')) {
									pmShowSaveResult(true);
									return;
								}
								pmShowSaveResult(false, (r && r.msg) ? r.msg : 'เกิดข้อผิดพลาดในการบันทึก');
							});
						}
						try { $editor.summernote('destroy'); } catch(e){}
						try { $('#modalSection2Editor').modal('hide'); } catch(e){}
						setTimeout(pmClearModalTrap, 220);
						try { $('#section2-' + fieldSaved).trigger('change'); } catch(eCh) {}
						updateStep2Circle();
						currentField = null;
					});
					function setStepCircle(sel, done) {
						var $c = $(sel);
						if (!$c.length) return;
						if (sel === '#step-s3-circle') {
							done = pmSection3IsComplete();
						}
						$c.removeClass('done pending').addClass(done ? 'done' : 'pending');
						$c.find('i').removeClass('fa-check fa-times').addClass(done ? 'fa-check' : 'fa-times')
							.css('font-size', done ? '0.9rem' : '0.65rem');
						try { pmToggleSectionIncomplete(sel, done); } catch (eInc) {}
						try { updateSubmitDraftButton(); } catch(e) {}
					}
					function pmSection3TextsOk() {
						var r = ($('#section2-reson').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var s = ($('#section2-result').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var o = ($('#section2-objective').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var t = ($('#section2-target_project').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var m = !window.PM_IS_MIDYEAR || String($('#section2-midyear_reason').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim() !== '';
						return !!(r && s && o && t && m);
					}
					function pmSection3KpiOk() {
						var $w = $('#kpi-goal-table-wrap');
						if (!$w.length) return false;
						return $w.text().indexOf('ยังไม่มีตัวชี้วัดของโครงการ') === -1;
					}
					function pmSection3IsComplete() {
						return pmSection3TextsOk() && pmSection3KpiOk();
					}
					window.pmSection3Complete = pmSection3IsComplete;
					function pmToggleSectionIncomplete(sel, done) {
						if (!window.PM_SHOW_SECTION_REQUIRED) return;
						var map = {
							'#step-s1-circle': '#pm-incomplete-s1',
							'#step-s2-circle': '#pm-incomplete-s2',
							'#step-s3-circle': '#pm-incomplete-s3',
							'#step-s4-circle': '#pm-incomplete-s4',
							'#step-s5-circle': '#pm-incomplete-s5'
						};
						var mid = map[sel];
						if (!mid) return;
						$(mid).toggleClass('d-none', !!done);
					}
					function setStepLine(sel, done){
						var $l = $(sel);
						if (!$l.length) return;
						$l.removeClass('done pending').addClass(done ? 'done' : 'pending');
						try { updateSubmitDraftButton(); } catch(e) {}
					}
					function pmScrollToStepTarget(sel){
						var $t = $(sel);
						if (!$t.length) return;
						var top = $t.offset().top || 0;
						var offset = 86; // เผื่อ header/spacing
						$('html, body').stop(true).animate({ scrollTop: Math.max(0, top - offset) }, 350, function(){
							$t.addClass('pm-step-target-flash');
							setTimeout(function(){ $t.removeClass('pm-step-target-flash'); }, 850);
						});
					}
					$(document).on('click', '.add-project-step, .add-project-step-circle, .add-project-step-label', function(e){
						// อนุญาตคลิกทั้งวงกลม/ตัวหนังสือ/กรอบ step
						var $step = $(this).closest('.add-project-step');
						var target = String($step.attr('data-step-target') || '').trim();
						if (!target) return;
						e.preventDefault();
						pmScrollToStepTarget(target);
					});
					window.pmSection6Complete = function(){
						function txt(sel){
							return String($(sel).val() || '').replace(/<[^>]*>/g, '').trim();
						}
						if (!$('#s6-evaluate_type').length) return true;
						return !!(txt('#s6-evaluate_type') && txt('#s6-evaluate_tool') && txt('#s6-risk_action') && txt('#s6-risk_stop'));
					};
					function updateSubmitDraftButton(){
						var $btns = $('.pm-submit-draft');
						var $badgeTop = $('#submitStatusBadgeTop');
						var $badgeBottom = $('#submitStatusBadgeBottom');
						var $reqWiz = $('.pm-wizard-request-operate');
						var $finishReport = $('.pm-finish-project-report-btn');
						var stNow = String($('#status_project_now').val() || '0');
						if (!$btns.length && !$badgeTop.length && !$badgeBottom.length && !$reqWiz.length && !$finishReport.length) return;
						if (window.PM_CAN_FILL_PROJECT_RESULTS && (stNow === '1' || stNow === '8')) {
							$btns.addClass('d-none');
							$badgeTop.removeClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.addClass('d-none');
							$finishReport.removeClass('d-none');
							return;
						}
						if (window.PM_CAN_FILL_PROJECT_RESULTS) {
							$badgeTop.removeClass('d-none');
							$badgeBottom.addClass('d-none');
						}
						$finishReport.addClass('d-none');
						if (window.PM_INCLUDE_MEETING_LOCK) {
							$btns.addClass('d-none');
							$badgeTop.removeClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.addClass('d-none');
							return;
						}
						if (window.PM_PLAN_FIX_RESUBMIT_LOCK) {
							$btns.addClass('d-none');
							$badgeTop.removeClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.addClass('d-none');
							return;
						}
						if (window.PM_OPERATE_REPLY_LOCK || window.PM_OPERATE_RETURN_FIX) {
							$btns.addClass('d-none');
							$badgeTop.removeClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.addClass('d-none');
							return;
						}
						var ok = $('#step-s1-circle').hasClass('done')
							&& $('#step-s2-circle').hasClass('done')
							&& (typeof window.pmSection3Complete === 'function' ? window.pmSection3Complete() : $('#step-s3-circle').hasClass('done'))
							&& $('#step-s4-circle').hasClass('done')
							&& $('#step-s5-circle').hasClass('done')
							&& window.pmSection6Complete();
						if (window.PM_IS_MIDYEAR) {
							$btns.addClass('d-none');
							var reasonOk = String($('#section2-midyear_reason').val() || $('#pmMidyearReason').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim() !== '';
							if (stNow === '0' || stNow === '8') {
								$reqWiz.toggleClass('d-none', !(ok && reasonOk));
								$badgeTop.toggleClass('d-none', false);
								$badgeBottom.addClass('d-none');
							} else {
								$reqWiz.addClass('d-none');
							}
							return;
						}
						if (window.PM_PLAN_ADMIN) {
							$btns.toggleClass('d-none', !ok);
							$badgeTop.addClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.addClass('d-none');
							return;
						}
						if (stNow === '4') {
							$btns.addClass('d-none');
							$badgeTop.addClass('d-none');
							$badgeBottom.addClass('d-none');
							$reqWiz.removeClass('d-none');
							return;
						}
						$reqWiz.addClass('d-none');
						var isSubmitted = (stNow !== '0' && stNow !== '8');
						if (isSubmitted) {
							$btns.addClass('d-none');
							var showBadges = (stNow === '2' || stNow === '3');
							$badgeTop.toggleClass('d-none', !showBadges);
							$badgeBottom.addClass('d-none');
							if (showBadges) {
								var bh = '<i class="fa fa-hourglass-half mr-1"></i> อยู่ระหว่างพิจารณา';
								$badgeTop.html(bh);
							}
							return;
						}
						$btns.toggleClass('d-none', !ok);
						$badgeTop.addClass('d-none');
						$badgeBottom.addClass('d-none');
					}
					window.updateSubmitDraftButton = updateSubmitDraftButton;
					window.setStepCircle = setStepCircle;
					window.setStepLine = setStepLine;
					$(document).on('input change', '#pmMidyearReason, #section2-midyear_reason', function(){
						if (typeof window.updateSubmitDraftButton === 'function') window.updateSubmitDraftButton();
					});
					$(document).on('blur', '#pmMidyearReason, #section2-midyear_reason', function(){
						if (!window.PM_IS_MIDYEAR) return;
						var pid = parseInt($('#edit_project_id').val() || '0', 10);
						if (!pid) return;
						$.ajax({
							url: '?page=project_manage&op=save_midyear_reason_ajax',
							type: 'POST',
							dataType: 'json',
							data: { op:'save_midyear_reason_ajax', project_id: pid, midyear_reason: String($(this).val() || '') }
						});
					});
					function updateStep2Circle() {
						var r = ($('#section2-reson').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var s = ($('#section2-result').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var o = ($('#section2-objective').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var t = ($('#section2-target_project').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
						var m = !window.PM_IS_MIDYEAR || String($('#section2-midyear_reason').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim() !== '';
						setStepCircle('#step-s3-circle', !!(r && s && o && t && m));
						setStepLine('#step-line-3', !!(r && s && o && t && m));
					}
					$(document).on('click', '#modalSection2Editor .btn-section2-close', function(){
						try { if ($editor && $editor.length) $editor.summernote('destroy'); } catch(e){}
						$('#modalSection2Editor').modal('hide');
					});
					$('#modalSection2Editor').on('hidden.bs.modal', function(){
						if ($editor && $editor.length) { try { $editor.summernote('destroy'); } catch(e){} }
					});
					window.pmRefreshConsistencyStepper = function(done) {
						setStepCircle('#step-s2-circle', !!done);
						setStepLine('#step-line-2', !!done);
					};
					var pmScrollInit = <?= json_encode($pm_scroll_target, JSON_UNESCAPED_UNICODE) ?>;
					if (pmScrollInit === 'report') {
						setTimeout(function () { pmScrollToStepTarget('#pm-kpi-goal-section'); }, 450);
					} else if (pmScrollInit === 'pmChangeHistory') {
						setTimeout(function () {
							var el = document.getElementById('pmChangeHistory');
							if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
						}, 450);
					}
				})();
				</script>

