						&& $pm_approver_json_txt === ''
						&& $pm_pa_rechain_at_txt === '';
					if ($edit_project_id > 0 && function_exists('pm_ensure_operate_approver_schema')) {
						pm_ensure_operate_approver_schema($db_Project);
					}
					if ($edit_project_id > 0 && $pm_approver_json_txt !== '' && isset($getStaffName)) {
						$apprMap = function_exists('pm_parse_operate_chain_json')
							? pm_parse_operate_chain_json($pm_approver_json_txt)
							: [];
						$apprDecMap = function_exists('pm_load_operate_decision_map')
							? pm_load_operate_decision_map($db_Project, (int)$edit_project_id, 'project_operate_approver_decision')
							: [];
						$apprSorts = array_unique(array_merge(array_keys($apprMap), array_keys($apprDecMap)));
						sort($apprSorts, SORT_NUMERIC);
						foreach ($apprSorts as $__so) {
							$dv = (string)($apprDecMap[$__so]['decision'] ?? '');
							$st = 'waiting_queue';
							if ($dv === 'approved') {
								$st = 'approved';
							} elseif ($dv === 'rejected') {
								$st = 'rejected';
								$pm_approver_has_rejected = true;
							} else {
								$prevOk = true;
								foreach ($apprSorts as $__pso) {
									if ($__pso >= $__so) {
										break;
									}
									if ((string)($apprDecMap[$__pso]['decision'] ?? '') !== 'approved') {
										$prevOk = false;
										break;
									}
								}
								$st = $prevOk ? 'waiting_turn' : 'waiting_queue';
							}
							$sidC = (int)($apprMap[$__so]['staff_id'] ?? ($apprDecMap[$__so]['staff_id'] ?? 0));
							$noteTxt = trim((string)($apprDecMap[$__so]['certifier_note'] ?? ''));
							$dtTxt = trim((string)($apprDecMap[$__so]['decided_at'] ?? ''));
							$dtTh = $dtTxt;
							if ($dtTxt !== '') {
								try {
									$__ts3 = strtotime($dtTxt);
									if ($__ts3 !== false) {
										$__m3 = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
										$__d3 = (int)date('j', $__ts3);
										$__mi3 = (int)date('n', $__ts3);
										$__y3 = ((int)date('Y', $__ts3) + 543) % 100;
										$__t3 = date('H:i', $__ts3);
										$dtTh = $__d3 . ' ' . $__m3[max(0, min(11, $__mi3 - 1))] . ' ' . str_pad((string)$__y3, 2, '0', STR_PAD_LEFT) . ' ' . $__t3 . ' น.';
									}
								} catch (Throwable $e) {
									$dtTh = $dtTxt;
								}
							}
							$pm_approver_rows[] = [
								'sort_order' => (int)$__so,
								'status' => $st,
								'decision' => $dv,
								'staff_id' => (int)$sidC,
								'decided_by_staff_id' => (int)($apprDecMap[$__so]['decided_by_staff_id'] ?? 0),
								'staff_name' => $getStaffName($sidC),
								'position_title' => (string)($apprMap[$__so]['position_title'] ?? ''),
								'note' => $noteTxt,
								'decided_at' => $dtTxt,
								'decided_at_th' => $dtTh,
							];
						}
						$pm_all_approvers_approved = function_exists('pm_compute_operate_approver_chain_all_approved')
							? pm_compute_operate_approver_chain_all_approved($db_Project, (int)$edit_project_id, is_array($saved_pre) ? $saved_pre : null)
							: false;
					} elseif ($pm_is_legacy_operate_approver) {
						$pm_approver_rows = $pm_operate_rows;
						$pm_all_approvers_approved = !empty($pm_all_operate_approved_seq);
					}
					if (
						empty($pm_operate_show_reply_box)
						&& !empty($pm_approver_has_rejected)
						&& !(defined('PLAN_ADMIN') && PLAN_ADMIN)
						&& (string)($saved_pre['status_project'] ?? '') === '8'
						&& $pm_notify_result_txt === 'บรรจุแผน'
						&& $pm_operate_reply_note_txt === ''
					) {
						$pm_operate_show_reply_box = true;
					}
					$pm_operate_reply_hist = [];
					$pm_plan_admin_return_hist = [];
					if ($edit_project_id > 0 && function_exists('pm_collect_operate_action_hist')) {
						try {
							$__opHist = pm_collect_operate_action_hist(
								$db_Project,
								$db_person,
								(int)$edit_project_id,
								(string)$pm_pa_rechain_at_txt,
								is_array($pm_operate_rows) ? $pm_operate_rows : [],
								is_array($pm_approver_rows) ? $pm_approver_rows : [],
								!empty($pm_is_legacy_operate_approver)
							);
							$pm_operate_reply_hist = is_array($__opHist['replies'] ?? null) ? $__opHist['replies'] : [];
							$pm_plan_admin_return_hist = is_array($__opHist['plan_returns'] ?? null) ? $__opHist['plan_returns'] : [];
							$pm_operate_has_nested_reply = false;
							$__certHist = is_array($__opHist['cert'] ?? null) ? $__opHist['cert'] : [];
							$__apprHist = is_array($__opHist['appr'] ?? null) ? $__opHist['appr'] : [];
							foreach ($pm_operate_rows as $__hi => $__hr) {
								$__soh = (int)($__hr['sort_order'] ?? 0);
								$pm_operate_rows[$__hi]['hist'] = ($__soh > 0 && isset($__certHist[$__soh]) && is_array($__certHist[$__soh])) ? $__certHist[$__soh] : [];
							}
							foreach ($pm_approver_rows as $__hi => $__hr) {
								$__soh = (int)($__hr['sort_order'] ?? 0);
								$pm_approver_rows[$__hi]['hist'] = ($__soh > 0 && isset($__apprHist[$__soh]) && is_array($__apprHist[$__soh])) ? $__apprHist[$__soh] : [];
							}
						} catch (Throwable $e) {
							$pm_operate_reply_hist = [];
							$pm_plan_admin_return_hist = [];
						}
					}
					$pm_include_stage_txt = '';
					$pm_include_stage_badge_cls = 'warn';
					$pm_status_now_include = (string)($saved_pre['status_project'] ?? '');
					if ($pm_notify_result_txt === 'บรรจุแผน' || $pm_notify_result_txt === 'บรรจุแผนและแก้ไข') {
						$pm_include_stage_txt = 'ผ่านขั้นยื่นขอพิจารณาแผนแล้ว';
						$pm_include_stage_badge_cls = 'ok';
					} elseif ($pm_status_now_include === '9' || $pm_notify_result_txt === 'ไม่ผ่านการพิจารณา') {
						$pm_include_stage_txt = 'ไม่ผ่านการพิจารณา';
						$pm_include_stage_badge_cls = 'no';
					} elseif ($pm_status_now_include === '8') {
						$pm_include_stage_txt = 'ตีกลับให้แก้ไข';
						$pm_include_stage_badge_cls = 'no';
					} elseif (in_array($pm_status_now_include, ['2', '3'], true)) {
						$pm_include_stage_txt = 'อยู่ระหว่างพิจารณา';
						$pm_include_stage_badge_cls = 'warn';
					}

					// ลำดับการตรวจสอบ "ขอบรรจุโครงการ" (อิงคำขอล่าสุดของโครงการ) — แสดงในกรอบรายละเอียดโครงการ
					$pm_include_seq_rows = [];
					if ($edit_project_id > 0) {
						$pm_inc_req_id = 0;
						$qRid = @mysqli_query(
							$db_Project,
							"SELECT MAX(request_id) AS rid
							 FROM project_include_request_item
							 WHERE project_id='" . (int)$edit_project_id . "'"
						);
						$rRid = $qRid ? mysqli_fetch_assoc($qRid) : null;
						$pm_inc_req_id = (int)($rRid['rid'] ?? 0);

						if ($pm_inc_req_id > 0) {
							$pm_inc_staff_cache = [];
							$pm_inc_staff_name = function ($sidNm) use ($db_person, &$pm_inc_staff_cache) {
								$sidNm = (int)$sidNm;
								if ($sidNm <= 0) return '-';
								if (isset($pm_inc_staff_cache[$sidNm])) return $pm_inc_staff_cache[$sidNm];
								$q = @mysqli_query($db_person, "SELECT CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n FROM staff WHERE id='" . (int)$sidNm . "' LIMIT 1");
								$r = $q ? mysqli_fetch_assoc($q) : null;
								$nm = trim((string)($r['n'] ?? ''));
								if ($nm === '') $nm = 'Staff #' . $sidNm;
								$pm_inc_staff_cache[$sidNm] = $nm;
								return $nm;
							};
							$pm_inc_fmt_dt = function ($dtTxt) {
								$dtTxt = trim((string)$dtTxt);
								if ($dtTxt === '' || $dtTxt === '0000-00-00 00:00:00') return '';
								$ts = strtotime($dtTxt);
								if ($ts === false) return $dtTxt;
								$m = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
								$d = (int)date('j', $ts);
								$mi = (int)date('n', $ts);
								$y = ((int)date('Y', $ts) + 543) % 100;
								return $d . ' ' . $m[max(0, min(11, $mi - 1))] . ' ' . str_pad((string)$y, 2, '0', STR_PAD_LEFT);
							};

							$certMapInc = [];
							$qC = @mysqli_query(
								$db_Project,
								"SELECT sort_order, staff_id, position_title
								 FROM project_include_request_certifier
								 WHERE request_id='" . (int)$pm_inc_req_id . "'
								 ORDER BY sort_order ASC"
							);
							while ($qC && ($cr = mysqli_fetch_assoc($qC))) {
								$so = (int)($cr['sort_order'] ?? 0);
								if ($so <= 0) continue;
								$certMapInc[$so] = [
									'staff_id' => (int)($cr['staff_id'] ?? 0),
									'position_title' => trim((string)($cr['position_title'] ?? '')),
								];
							}

							$decMapInc = [];
							$qD = @mysqli_query(
								$db_Project,
								"SELECT sort_order, decision, decided_at, certifier_note
								 FROM project_include_request_certifier_decision
								 WHERE request_id='" . (int)$pm_inc_req_id . "'"
							);
							while ($qD && ($dr = mysqli_fetch_assoc($qD))) {
								$so = (int)($dr['sort_order'] ?? 0);
								if ($so <= 0) continue;
								$decMapInc[$so] = $dr;
							}

							$orders = array_keys($certMapInc);
							sort($orders, SORT_NUMERIC);
							foreach ($orders as $__so) {
								$staffId = (int)($certMapInc[$__so]['staff_id'] ?? 0);
								$pos = (string)($certMapInc[$__so]['position_title'] ?? '');
								$dv = (string)($decMapInc[$__so]['decision'] ?? '');
								$dt = (string)($decMapInc[$__so]['decided_at'] ?? '');
								$note = trim((string)($decMapInc[$__so]['certifier_note'] ?? ''));

								$st = 'pending';
								if ($dv === 'approved') $st = 'approved';
								else if ($dv === 'rejected') $st = 'rejected';

								$pm_include_seq_rows[] = [
									'sort_order' => (int)$__so,
									'staff_name' => $pm_inc_staff_name($staffId),
									'position_title' => $pos,
									'decision' => $dv,
									'status' => $st,
									'decided_at_th' => $pm_inc_fmt_dt($dt),
									'note' => $note,
									'hist' => [],
								];
							}
							$qIncLog = @mysqli_query(
								$db_Project,
								"SELECT action_type, sort_order, note, created_at
								 FROM project_include_request_action_log
								 WHERE request_id='" . (int)$pm_inc_req_id . "'
								 ORDER BY id ASC"
							);
							$__incHistMap = [];
							$__lastIncRejSo = 0;
							while ($qIncLog && ($il = mysqli_fetch_assoc($qIncLog))) {
								$__ityp = (string)($il['action_type'] ?? '');
								$__iso = (int)($il['sort_order'] ?? 0);
								$__inote = trim((string)($il['note'] ?? ''));
								if ($__ityp === 'admin_fix_sent') {
									continue;
								}
								if ($__inote === '') {
									if ($__ityp === 'certifier_rejected' && $__iso > 0) {
										$__lastIncRejSo = $__iso;
									}
									continue;
								}
								$__isReply = in_array($__ityp, ['submitter_reply_saved', 'submitter_reply_kept', 'project_fix_confirmed'], true);
								$__isDec = in_array($__ityp, ['certifier_rejected', 'certifier_approved', 'certifier_recheck_approved'], true);
								if (!$__isReply && !$__isDec) {
									continue;
								}
								if ($__ityp === 'certifier_rejected' && $__iso > 0) {
									$__lastIncRejSo = $__iso;
								}
								if ($__isReply) {
									if ($__iso <= 0) {
										$__iso = $__lastIncRejSo;
									}
									if ($__iso <= 0) {
										continue;
									}
									$__dupReply = false;
									foreach ((array)($__incHistMap[$__iso] ?? []) as $__prevH) {
										$__pt = (string)($__prevH['action_type'] ?? '');
										if (!in_array($__pt, ['submitter_reply_saved', 'project_fix_confirmed'], true)) {
											continue;
										}
										if (trim((string)($__prevH['note'] ?? '')) !== $__inote) {
											continue;
										}
										$__dupReply = true;
										break;
									}
									if ($__dupReply) {
										continue;
									}
								} elseif ($__iso <= 0) {
									continue;
								}
								$__incHistMap[$__iso][] = [
									'action_type' => $__ityp,
									'note' => $__inote,
									'created_at' => (string)($il['created_at'] ?? ''),
									'created_at_th' => function_exists('pm_fmt_operate_hist_dt') ? pm_fmt_operate_hist_dt((string)($il['created_at'] ?? '')) : (string)($il['created_at'] ?? ''),
								];
							}
							if (!empty($__incHistMap)) {
								foreach ($pm_include_seq_rows as $__ii => $__ir) {
									$__iso = (int)($__ir['sort_order'] ?? 0);
									$pm_include_seq_rows[$__ii]['hist'] = ($__iso > 0 && isset($__incHistMap[$__iso])) ? $__incHistMap[$__iso] : [];
								}
							}
						}
					}
				?>
				<?php if ($pm_include_stage_txt !== '' || !empty($pm_include_seq_rows)): ?>
				<?php $pm_include_fold_done = (($pm_include_stage_badge_cls ?? '') === 'ok'); ?>
				<details class="alert mt-3 mb-2 pm-notify-result-card pm-stage-fold" <?= $pm_include_fold_done ? '' : 'open' ?>>
					<summary class="pm-notify-result-title pm-stage-fold-sum">การขอบรรจุแผน</summary>
					<?php
						$pm_include_hide_stage_badge = ($pm_include_stage_txt === 'ตีกลับให้แก้ไข' && !empty($pm_include_seq_rows));
					?>
					<?php if ($pm_include_stage_txt !== '' && empty($pm_include_hide_stage_badge)): ?>
						<div class="mb-2">
							<span class="pm-notify-result-badge <?= htmlspecialchars($pm_include_stage_badge_cls, ENT_QUOTES, 'UTF-8') ?>">
								<i class="fa <?= $pm_include_stage_badge_cls === 'ok' ? 'fa-check-circle' : ($pm_include_stage_badge_cls === 'no' ? 'fa-times-circle' : 'fa-hourglass-half') ?>"></i>
								<?= htmlspecialchars($pm_include_stage_txt, ENT_QUOTES, 'UTF-8') ?>
							</span>
						</div>
					<?php endif; ?>
					<?php if (!empty($pm_include_seq_rows)): ?>
						<div class="pm-review-timeline mt-2">
							<div class="pm-review-timeline-title">ลำดับการตรวจสอบ</div>
							<?php foreach ($pm_include_seq_rows as $__sr): ?>
								<?php
									$__st = (string)($__sr['status'] ?? 'pending');
									$__badge = $__st === 'approved' ? 'ok' : ($__st === 'rejected' ? 'no' : 'warn');
									$__icon = $__st === 'approved' ? 'fa-check-circle' : ($__st === 'rejected' ? 'fa-times-circle' : 'fa-hourglass-half');
									$__label = $__st === 'approved' ? 'ผ่านแล้ว' : ($__st === 'rejected' ? 'ตีกลับ' : 'รอดำเนินการ');
									$__dt = trim((string)($__sr['decided_at_th'] ?? ''));
									$__note = trim((string)($__sr['note'] ?? ''));
								?>
								<div class="pm-review-item">
									<div class="pm-review-dot"><?= (int)($__sr['sort_order'] ?? 0) ?></div>
									<div class="pm-review-content">
										<div class="pm-review-head">
											<span class="pm-review-label"><?= htmlspecialchars((string)($__sr['staff_name'] ?? '-'), ENT_QUOTES, 'UTF-8') ?></span>
											<span class="pm-review-meta">
												<?= htmlspecialchars((string)($__sr['position_title'] ?? ''), ENT_QUOTES, 'UTF-8') ?>
											</span>
										</div>
										<div class="pm-review-status-row">
											<span class="pm-notify-result-badge <?= htmlspecialchars($__badge, ENT_QUOTES, 'UTF-8') ?>">
												<i class="fa <?= htmlspecialchars($__icon, ENT_QUOTES, 'UTF-8') ?>"></i>
												<?= htmlspecialchars($__label, ENT_QUOTES, 'UTF-8') ?>
											</span>
											<?php if ($__dt !== ''): ?>
												<span class="pm-review-when"><?= htmlspecialchars($__dt, ENT_QUOTES, 'UTF-8') ?></span>
											<?php endif; ?>
										</div>
										<?php
											if (function_exists('pm_render_operate_review_hist')) {
												pm_render_operate_review_hist(
													is_array($__sr['hist'] ?? null) ? $__sr['hist'] : [],
													$__note,
													$__st
												);
											} elseif ($__note !== '') {
												echo '<div class="pm-review-note">' . nl2br(htmlspecialchars($__note, ENT_QUOTES, 'UTF-8')) . '</div>';
											}
										?>
									</div>
									<?php if (defined('PLAN_ADMIN') && PLAN_ADMIN && !empty($pm_inc_req_id) && $__st === 'pending'): ?>
										<div class="pm-review-actions">
											<button
												type="button"
												class="btn btn-sm btn-pm-edit-orange pm-inc-edit-cert-row"
												data-request-id="<?= (int)$pm_inc_req_id ?>"
												data-sort-order="<?= (int)($__sr['sort_order'] ?? 0) ?>"
												data-staff-id="<?= (int)($certMapInc[(int)($__sr['sort_order'] ?? 0)]['staff_id'] ?? 0) ?>"
												data-position="<?= htmlspecialchars((string)($__sr['position_title'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"
												title="แก้ไขผู้ตรวจสอบ/ตำแหน่ง"
											>
												<i class="fa fa-edit"></i> แก้ไข
											</button>
										</div>
									<?php endif; ?>
								</div>
							<?php endforeach; ?>
						</div>
					<?php endif; ?>
				</details>
				<?php endif; ?>
				<?php if ($pm_notify_result_txt !== '' || $pm_notify_note_txt !== '' || $pm_notify_budget_amt > 0): ?>
				<?php $pm_notify_fold_done = ($pm_notify_result_txt === 'บรรจุแผน'); ?>
				<details class="alert mt-3 mb-2 pm-notify-result-card pm-stage-fold" <?= $pm_notify_fold_done ? '' : 'open' ?>>
					<summary class="pm-notify-result-title pm-stage-fold-sum">ผลการบรรจุแผน</summary>
					<?php
						$pm_notify_badge_cls = 'warn';
						$pm_notify_icon = 'fa-question-circle';
						if ($pm_notify_result_txt === 'บรรจุแผน') {
							$pm_notify_badge_cls = 'ok';
							$pm_notify_icon = 'fa-check-circle';
						} elseif ($pm_notify_result_txt === 'บรรจุแผนและแก้ไข') {
							$pm_notify_badge_cls = 'warn';
							$pm_notify_icon = 'fa-edit';
						} elseif ($pm_notify_result_txt === 'ไม่ผ่านการพิจารณา') {
							$pm_notify_badge_cls = 'no';
							$pm_notify_icon = 'fa-times-circle';
						}
					?>
					<div class="pm-notify-result-grid">
						<div class="k">แหล่งงบประมาณ :</div>
						<div class="v"><?= htmlspecialchars($pm_notify_budget_src, ENT_QUOTES, 'UTF-8') ?></div>
						<div class="k">วงเงิน :</div>
						<div class="v"><?= number_format($pm_notify_budget_amt, 2) ?> บาท</div>
						<div class="k">ผลการพิจารณา :</div>
						<div class="v">
							<span class="pm-notify-result-badge <?= htmlspecialchars($pm_notify_badge_cls, ENT_QUOTES, 'UTF-8') ?>">
								<i class="fa <?= htmlspecialchars($pm_notify_icon, ENT_QUOTES, 'UTF-8') ?>"></i>
								<?= htmlspecialchars($pm_notify_result_txt !== '' ? $pm_notify_result_txt : '-', ENT_QUOTES, 'UTF-8') ?>
							</span>
						</div>
						<?php if ($pm_notify_result_txt !== 'ไม่ผ่านการพิจารณา'): ?>
						<div class="k">ระบบลาราชการ :</div>
						<div class="v">
							<?php if (!empty($pm_show_on_leave_system)): ?>
								<span class="pm-notify-result-badge ok"><i class="fa fa-check-square"></i> แสดงรายการที่ระบบลาราชการ</span>
							<?php else: ?>
								<span class="text-muted">ไม่แสดง</span>
							<?php endif; ?>
						</div>
						<?php endif; ?>
					</div>
					<?php if ($pm_notify_note_txt !== '' && $pm_notify_result_txt !== 'บรรจุแผน'): ?>
