				<?php if (!empty($pm_all_operate_approved_seq) || !empty($pm_approver_rows)): ?>
				<?php
					$pm_approve_source_rows = !empty($pm_approver_rows) ? $pm_approver_rows : [];
					$pm_approve_dt_txt = '';
					$pm_approve_staff_txt = '-';
					$pm_approve_count = count($pm_approve_source_rows);
					$pm_approve_ok_count = 0;
					$pm_approve_memo_approver_name = '';
					$pm_approve_memo_approver_pos = '';
					$pm_approve_memo_approver_date = '';
					$pm_approve_memo_approver_date_raw = '';
					$pm_approve_memo_approver_sid = 0;
					foreach ($pm_approve_source_rows as $__apRow) {
						if ((string)($__apRow['status'] ?? '') === 'approved') {
							$pm_approve_ok_count++;
							$pm_approve_memo_approver_name = trim((string)($__apRow['staff_name'] ?? ''));
							$pm_approve_memo_approver_pos = trim((string)($__apRow['position_title'] ?? ''));
							$pm_approve_memo_approver_date = trim((string)($__apRow['decided_at_th'] ?? ''));
							$pm_approve_memo_approver_date_raw = trim((string)($__apRow['decided_at'] ?? ''));
							$__apBy = (int)($__apRow['decided_by_staff_id'] ?? 0);
							$pm_approve_memo_approver_sid = $__apBy > 0 ? $__apBy : (int)($__apRow['staff_id'] ?? 0);
							if ($pm_approve_dt_txt === '' && $pm_approve_memo_approver_date !== '') {
								$pm_approve_dt_txt = $pm_approve_memo_approver_date;
								$pm_approve_staff_txt = $pm_approve_memo_approver_name !== '' ? $pm_approve_memo_approver_name : '-';
							} else {
								// ผู้อนุมัติล่าสุด = คนสุดท้ายในลำดับที่ approved
								$pm_approve_dt_txt = $pm_approve_memo_approver_date !== '' ? $pm_approve_memo_approver_date : $pm_approve_dt_txt;
								$pm_approve_staff_txt = $pm_approve_memo_approver_name !== '' ? $pm_approve_memo_approver_name : $pm_approve_staff_txt;
							}
						}
					}

					$pm_approve_memo_ready = !empty($pm_all_approvers_approved) && (string)($saved_pre['status_project'] ?? '') === '1';
					$pm_am_unit = '-';
					$pm_am_code = (string)($ref_display ?? '');
					$pm_am_name = trim((string)($saved_pre['name_project'] ?? ''));
					$pm_am_budget_fmt = '0';
					$pm_am_budget_src = trim((string)($pm_notify_budget_src ?? '-'));
					$pm_am_dept = '';
					$pm_am_doc_no = 'อว /ผ001';
					$pm_am_date = '';
					$pm_am_proposer_name = '';
					$pm_am_proposer_pos = '';
					$pm_am_proposer_date = '';
					$pm_am_proposer_sid = 0;
					$pm_am_proposer_sig = '';
					$pm_am_approver_sig = '';
					$pm_am_proposer_sig_alts = [];
					$pm_am_approver_sig_alts = [];
					$pm_am_approver_date_only = '';
					if ($pm_approve_memo_ready && $edit_project_id > 0) {
						$__ucAm = trim((string)($saved_pre['code_unit'] ?? ''));
						if ($__ucAm !== '' && isset($unit_names[$__ucAm])) {
							$pm_am_unit = (string)$unit_names[$__ucAm];
						}
						$pm_am_dept = ($pm_am_unit !== '-' && $pm_am_unit !== '' ? $pm_am_unit : 'หน่วยงาน') . ' คณะเภสัชศาสตร์ โทร.44344';
						$__paperName = 'อว';
						$__paperStart = '1';
						if ($__ucAm !== '') {
							$__ucEsc = mysqli_real_escape_string($db_Project, $__ucAm);
							$__hasPaperName = false;
							$__hasPaperStart = false;
							$qColsU = @mysqli_query($db_Project, "SHOW COLUMNS FROM set_unit");
							while ($qColsU && ($cu = mysqli_fetch_assoc($qColsU))) {
								$fn = strtolower(trim((string)($cu['Field'] ?? '')));
								if ($fn === 'paper_name') $__hasPaperName = true;
								if ($fn === 'paper_start') $__hasPaperStart = true;
							}
							$selPaper = 'name';
							if ($__hasPaperName) $selPaper .= ', paper_name';
							if ($__hasPaperStart) $selPaper .= ', paper_start';
							$qPaper = @mysqli_query(
								$db_Project,
								"SELECT {$selPaper} FROM set_unit
								 WHERE (CAST(id AS CHAR)='{$__ucEsc}' OR TRIM(CAST(IFNULL(code,'') AS CHAR))='{$__ucEsc}')
								   AND IFNULL(status,'') NOT IN ('99','99.0')
								 LIMIT 1"
							);
							$rPaper = $qPaper ? mysqli_fetch_assoc($qPaper) : null;
							if ($rPaper) {
								$pn = $__hasPaperName ? trim((string)($rPaper['paper_name'] ?? '')) : '';
								$ps = $__hasPaperStart ? trim((string)($rPaper['paper_start'] ?? '')) : '';
								if ($pn !== '') $__paperName = $pn;
								if ($ps !== '') $__paperStart = $ps;
								if ($pm_am_unit === '-' || $pm_am_unit === '') {
									$pm_am_unit = trim((string)($rPaper['name'] ?? '')) ?: $pm_am_unit;
									$pm_am_dept = ($pm_am_unit !== '-' && $pm_am_unit !== '' ? $pm_am_unit : 'หน่วยงาน') . ' คณะเภสัชศาสตร์ โทร.44344';
								}
							}
						}
						$pm_am_doc_no = function_exists('pm_unit_paper_doc_no')
							? pm_unit_paper_doc_no(
								$__paperName,
								$__paperStart,
								((($edit_project_id % 999) ?: 0) + 1)
							)
							: (rtrim($__paperName, " \t/") . '/' . ltrim((string)$__paperStart, " \t/"));

						$__amtAm = isset($saved_pre['notify_approved_budget']) ? (float)$saved_pre['notify_approved_budget'] : 0.0;
						if ($__amtAm <= 0) {
							$__sumAm = @mysqli_query($db_Project, "SELECT IFNULL(SUM(pa.total),0) AS t FROM project_activity_budget pa WHERE pa.code_pre_project='" . (int)$edit_project_id . "' AND pa.status!='99'");
							$__srAm = $__sumAm ? mysqli_fetch_assoc($__sumAm) : null;
							$__amtAm = (float)($__srAm['t'] ?? 0);
						}
						$pm_am_budget_fmt = number_format($__amtAm, 0, '.', ',');
						if ($pm_am_budget_src === '' || $pm_am_budget_src === '-') {
							if (function_exists('resolveProjectBudgetSourceForDisplay')) {
								$pm_am_budget_src = resolveProjectBudgetSourceForDisplay($db_Project, (int)$edit_project_id);
							}
						}

						$fmtThaiLong = static function ($ts) {
							if ($ts === false || $ts <= 0) return '';
							$m = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
							$d = (int)date('j', $ts);
							$mi = (int)date('n', $ts);
							$y = (int)date('Y', $ts) + 543;
							return $d . ' ' . $m[max(0, min(11, $mi - 1))] . ' ' . $y;
						};
						$pm_am_date = $fmtThaiLong(time());
						$pm_am_proposer_date = $pm_am_date;
						// วันที่ขอ = วันที่ยื่นขอดำเนินการ (ถ้าหาได้)
						$qReqAt = @mysqli_query(
							$db_Project,
							"SELECT created_at FROM project_plan_review_log
							 WHERE project_id='" . (int)$edit_project_id . "'
							   AND action_type IN ('request_operate','request_operate_project')
							 ORDER BY id DESC LIMIT 1"
						);
						$rReqAt = $qReqAt ? mysqli_fetch_assoc($qReqAt) : null;
						if ($rReqAt && trim((string)($rReqAt['created_at'] ?? '')) !== '') {
							$tsReq = strtotime((string)$rReqAt['created_at']);
							if ($tsReq) $pm_am_date = $fmtThaiLong($tsReq);
						} elseif (!empty($saved_pre['dates'])) {
							$tsDates = strtotime((string)$saved_pre['dates']);
							if ($tsDates) $pm_am_date = $fmtThaiLong($tsDates);
						}

						// ผู้เสนอ = หัวหน้าโครงการ (แสดงตำแหน่งจริงจาก position_code)
						$pm_am_proposer_key = '';
						$pm_am_proposer_pos = '';
						if (!empty($saved_heads) && is_array($saved_heads)) {
							$__h = $saved_heads[0];
							$pm_am_proposer_key = trim((string)($__h['staff_project'] ?? $__h['staff_id'] ?? ''));
							$__hsid = (int)$pm_am_proposer_key;
							if ($__hsid > 0) {
								$pm_am_proposer_sid = $__hsid;
							}
							if ($pm_am_proposer_key !== '') {
								$__hkEsc = mysqli_real_escape_string($db_person, $pm_am_proposer_key);
								$qHn = @mysqli_query(
									$db_person,
									"SELECT id, files_sig, position_code, position_dean, prefix_code,
									        CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n
									 FROM staff
									 WHERE id='" . (int)$pm_am_proposer_key . "'
									    OR TRIM(CAST(IFNULL(code,'') AS CHAR))='" . $__hkEsc . "'
									 LIMIT 1"
								);
								$rHn = $qHn ? mysqli_fetch_assoc($qHn) : null;
								if ($rHn) {
									$pm_am_proposer_sid = (int)($rHn['id'] ?? $pm_am_proposer_sid);
									$__pfxName = '';
									$__px = trim((string)($rHn['prefix_code'] ?? ''));
									if ($__px !== '' && function_exists('getPrefix')) {
										$__rpx = getPrefix($db_person, $__px);
										if (is_array($__rpx)) {
											$__pfxName = trim((string)($__rpx['name'] ?? ''));
										}
									}
									$pm_am_proposer_name = trim($__pfxName . ' ' . trim((string)($rHn['n'] ?? '')));
									$pm_am_proposer_sig_file = trim((string)($rHn['files_sig'] ?? ''));
									$__pc = trim((string)($rHn['position_code'] ?? ''));
									if ($__pc !== '' && function_exists('getPosition')) {
										$__rp = getPosition($db_person, $__pc);
										if (is_array($__rp)) {
											$pm_am_proposer_pos = trim((string)($__rp['name'] ?? ''));
										}
									}
								}
							}
						}
						if ($pm_am_proposer_name === '') {
							$__mePfx = '';
							$__mePx = trim((string)($r_staff['prefix_code'] ?? ''));
							if ($__mePx !== '' && function_exists('getPrefix')) {
								$__rpm = getPrefix($db_person, $__mePx);
								if (is_array($__rpm)) {
									$__mePfx = trim((string)($__rpm['name'] ?? ''));
								}
							}
							$pm_am_proposer_name = trim($__mePfx . ' ' . trim((string)(($r_staff['fname'] ?? '') . ' ' . ($r_staff['lname'] ?? ''))));
							$pm_am_proposer_sid = (int)($r_staff['id'] ?? $staff_id ?? 0);
							$pm_am_proposer_sig_file = trim((string)($r_staff['files_sig'] ?? ''));
							if ($pm_am_proposer_pos === '') {
								$__pcMe = trim((string)($r_staff['position_code'] ?? ''));
								if ($__pcMe !== '' && function_exists('getPosition')) {
									$__rpMe = getPosition($db_person, $__pcMe);
									if (is_array($__rpMe)) {
										$pm_am_proposer_pos = trim((string)($__rpMe['name'] ?? ''));
									}
								}
							}
						}
						if ($pm_am_proposer_pos === '') {
							$pm_am_proposer_pos = 'หัวหน้าโครงการ';
						}

						// ผู้อนุมัติ = แสดงตำแหน่งบริหาร (position_dean)
						$pm_approve_memo_approver_pos_admin = '';
						if ($pm_approve_memo_approver_sid > 0) {
							$qApPos = @mysqli_query(
								$db_person,
								"SELECT position_dean, position_code, prefix_code, fname, lname
								 FROM staff WHERE id='" . (int)$pm_approve_memo_approver_sid . "' LIMIT 1"
							);
							$rApPos = $qApPos ? mysqli_fetch_assoc($qApPos) : null;
							if ($rApPos) {
								$__pd = trim((string)($rApPos['position_dean'] ?? ''));
								if ($__pd !== '' && function_exists('getPositionDean')) {
									$__rpd = getPositionDean($db_person, $__pd);
									if (is_array($__rpd)) {
										$pm_approve_memo_approver_pos_admin = trim((string)($__rpd['name'] ?? ''));
									}
								}
								$__apFn = trim((string)($rApPos['fname'] ?? ''));
								$__apLn = trim((string)($rApPos['lname'] ?? ''));
								if ($__apFn !== '' || $__apLn !== '') {
									$__apPfx = '';
									$__apPx = trim((string)($rApPos['prefix_code'] ?? ''));
									if ($__apPx !== '' && function_exists('getPrefix')) {
										$__rpxa = getPrefix($db_person, $__apPx);
										if (is_array($__rpxa)) {
											$__apPfx = trim((string)($__rpxa['name'] ?? ''));
										}
									}
									$pm_approve_memo_approver_name = trim($__apPfx . ' ' . trim($__apFn . ' ' . $__apLn));
								}
							}
						}
						if ($pm_approve_memo_approver_pos_admin !== '') {
							$pm_approve_memo_approver_pos = $pm_approve_memo_approver_pos_admin;
						} elseif ($pm_approve_memo_approver_pos === '') {
							$pm_approve_memo_approver_pos = 'คณบดีคณะเภสัชศาสตร์';
						}

						// วันที่ลงนามผู้ขอ ใช้วันที่ยื่น (รูปแบบเต็ม)
						$pm_am_proposer_date = $pm_am_date;
						// วันที่ผู้อนุมัติ = วันที่ตัดสินจริง รูปแบบเต็มเหมือนด้านบน
						$pm_am_approver_date_only = $pm_am_date;
						if ($pm_approve_memo_approver_date_raw !== '') {
							$tsAp = strtotime($pm_approve_memo_approver_date_raw);
							if ($tsAp) {
								$pm_am_approver_date_only = $fmtThaiLong($tsAp);
							}
						}
						$__savedMemoDept = trim((string)($saved_pre['approve_memo_dept'] ?? ''));
						$__savedMemoDate = trim((string)($saved_pre['approve_memo_date'] ?? ''));
						if ($__savedMemoDept !== '') {
							$pm_am_dept = $__savedMemoDept;
						}
						if ($__savedMemoDate !== '') {
							$pm_am_date = $__savedMemoDate;
						}
						if (function_exists('pm_get_or_create_approve_memo_esign_ref')) {
							$pm_am_esign_ref = pm_get_or_create_approve_memo_esign_ref(
								$db_Project,
								(int)$edit_project_id,
								(string)($pm_am_code ?? ''),
								'operate',
								0
							);
							$pm_am_esign_footer = function_exists('pm_approve_memo_esign_footer_text')
								? pm_approve_memo_esign_footer_text((string)$pm_am_esign_ref)
								: '';
						}

						// ลายเซ็นจาก $path_sig + staff.files_sig (มี URL สำรองถ้าโหลดไม่ขึ้น)
						$__pathSigBase = isset($path_sig) ? rtrim((string)$path_sig, '/') : '';
						if ($__pathSigBase === '' && isset($path_picture)) {
							$__pathSigBase = preg_replace('#/files_person$#', '/files_sig', rtrim((string)$path_picture, '/'));
						}
						if ($__pathSigBase === '') {
							$__pathSigBase = 'https://backoffice.pharmacy.cmu.ac.th/person/files_sig';
						}
						$__pathSigAlts = [
							'https://mis.pharmacy.cmu.ac.th/person/MS/files_sig',
							'https://backoffice.pharmacy.cmu.ac.th/person/files_sig',
						];
						$pmBuildSigUrl = static function ($file, $base) {
							$file = trim((string)$file);
							$base = rtrim((string)$base, '/');
							if ($file === '' || $base === '') {
								return '';
							}
							if (preg_match('#^https?://#i', $file)) {
								return $file;
							}
							$file = preg_replace('#^files_sig/#i', '', $file);
							return $base . '/' . ltrim($file, '/');
						};
						$pmResolveStaffSigPack = static function ($db_person, $staffKey, $base, $alts, $fallbackFile = '') use ($pmBuildSigUrl) {
							$file = trim((string)$fallbackFile);
							$staffKey = trim((string)$staffKey);
							if ($file === '' && $staffKey !== '' && ($db_person instanceof mysqli)) {
								$keyEsc = mysqli_real_escape_string($db_person, $staffKey);
								$q = @mysqli_query(
									$db_person,
									"SELECT files_sig FROM staff
									 WHERE id='" . (int)$staffKey . "'
									    OR TRIM(CAST(IFNULL(code,'') AS CHAR))='" . $keyEsc . "'
									 LIMIT 1"
								);
								$r = $q ? mysqli_fetch_assoc($q) : null;
								$file = trim((string)($r['files_sig'] ?? ''));
							}
							if ($file === '') {
								return ['url' => '', 'alts' => []];
							}
							if (preg_match('#^https?://#i', $file)) {
								return ['url' => $file, 'alts' => []];
							}
							$primary = $pmBuildSigUrl($file, $base);
							$altUrls = [];
							foreach ((array)$alts as $ab) {
								$u = $pmBuildSigUrl($file, $ab);
								if ($u !== '' && $u !== $primary) {
									$altUrls[] = $u;
								}
							}
							return ['url' => $primary, 'alts' => $altUrls];
						};
						if (!isset($pm_am_proposer_sig_file)) {
							$pm_am_proposer_sig_file = '';
						}
						$pm_am_proposer_sig_pack = $pmResolveStaffSigPack(
							$db_person,
							$pm_am_proposer_sid > 0 ? (string)$pm_am_proposer_sid : $pm_am_proposer_key,
							$__pathSigBase,
							$__pathSigAlts,
							$pm_am_proposer_sig_file
						);
						$pm_am_approver_sig_pack = $pmResolveStaffSigPack(
							$db_person,
							(string)$pm_approve_memo_approver_sid,
							$__pathSigBase,
							$__pathSigAlts,
							((int)($r_staff['id'] ?? 0) === (int)$pm_approve_memo_approver_sid)
								? trim((string)($r_staff['files_sig'] ?? ''))
								: ''
						);
						$pm_am_proposer_sig = (string)($pm_am_proposer_sig_pack['url'] ?? '');
						$pm_am_proposer_sig_alts = (array)($pm_am_proposer_sig_pack['alts'] ?? []);
						$pm_am_approver_sig = (string)($pm_am_approver_sig_pack['url'] ?? '');
						$pm_am_approver_sig_alts = (array)($pm_am_approver_sig_pack['alts'] ?? []);
						// ถ้าใช้ decided_by ให้ sync ชื่อให้ตรงกับคนที่ลงนามจริง
						if ($pm_approve_memo_approver_sid > 0) {
							$qApNm = @mysqli_query(
								$db_person,
								"SELECT CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n
								 FROM staff WHERE id='" . (int)$pm_approve_memo_approver_sid . "' LIMIT 1"
							);
							$rApNm = $qApNm ? mysqli_fetch_assoc($qApNm) : null;
							$__apNm = trim((string)($rApNm['n'] ?? ''));
							if ($__apNm !== '') {
								$pm_approve_memo_approver_name = $__apNm;
							}
						}
					}
