				.pm-pa-lbl-inline{gap:.4rem;}
				.pm-pa-certifiers-rows{display:flex;flex-direction:column;gap:1rem;}
				.pm-pa-cert-row{display:flex;gap:.5rem;align-items:flex-start;padding:.75rem .85rem;border:1px solid rgba(52,211,153,.45);border-radius:10px;background:rgba(255,255,255,.97);box-shadow:0 10px 20px -16px rgba(5,150,105,.22);}
				.pm-pa-cert-row .pm-ro-cert-fields{min-width:0;}
				.pm-pa-cert-side{flex:0 0 1.75rem;text-align:center;padding-top:.45rem;}
				.pm-pa-cert-lbl{font-weight:700;font-size:.95rem;color:#0f172a;margin-bottom:.35rem;}
				.pm-pa-cert-lbl-hint{font-size:.8rem;font-weight:500;color:#64748b;white-space:nowrap;}
				.pm-pa-cert-position{border-radius:.35rem;font-weight:400;font-family:inherit;}
				.pm-pa-combo{position:relative;}
				.pm-pa-combo-input{border-radius:.35rem;min-height:38px;}
