				@media (max-width:576px){.pm-pa-cert-lbl-hint{white-space:normal;text-align:right;max-width:9rem;}}
				</style>
				<script>
				(function($){
					if (window.pmPaOperateChainUiBound) return;
					window.pmPaOperateChainUiBound = true;
					var pmPaStaffOptions = <?= json_encode($request_operate_staff_options ?? [], JSON_UNESCAPED_UNICODE) ?>;
					if (!Array.isArray(pmPaStaffOptions)) pmPaStaffOptions = [];

					function pmPaEsc(s){
						return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
					}
					function pmPaCloseAllCombos(except){
						$('#pmPaCertifiersRows .pm-pa-combo-list').each(function(){
							if (except && this === except) return;
							$(this).removeClass('is-open').empty();
						});
					}
					function pmPaRenderComboList($combo, q){
						var $list = $combo.find('.pm-pa-combo-list');
						var needle = String(q || '').trim().toLowerCase();
						var html = '';
						var shown = 0;
						(pmPaStaffOptions || []).forEach(function(o){
							if (shown >= 40) return;
							var id = String(o.id || '');
							var text = String(o.text || '');
							var pos = String(o.position || '');
							if (!id) return;
							if (needle && (text + ' ' + id + ' ' + pos).toLowerCase().indexOf(needle) === -1) return;
							html += '<button type="button" class="pm-pa-combo-item" data-id="'+pmPaEsc(id)+'" data-text="'+pmPaEsc(text)+'" data-position="'+pmPaEsc(pos)+'">'+pmPaEsc(text)+(pos ? ' <span class="text-muted">('+pmPaEsc(pos)+')</span>' : '')+'</button>';
							shown++;
						});
						if (!html) {
							html = '<div class="pm-pa-combo-empty">'+(needle ? 'ไม่พบรายชื่อ' : 'พิมพ์ชื่อเพื่อค้นหา')+'</div>';
						}
						$list.html(html).addClass('is-open');
					}
					function pmPaRenumber(){
						$('#pmPaCertifiersRows .pm-pa-cert-row').each(function(i){
							$(this).find('.pm-pa-cert-lbl-idx').text('('+String(i+1)+')');
						});
					}
					function pmPaSyncRm(){
						var n = $('#pmPaCertifiersRows .pm-pa-cert-row').length;
						$('#pmPaCertifiersRows .pm-pa-remove').css('visibility', n>1?'visible':'hidden');
					}
					function pmPaAddRow(){
						var $w = $('#pmPaCertifiersRows');
						if(!$w.length) return;
						var n = $w.find('.pm-pa-cert-row').length+1;
						var rm = '<button type="button" class="btn btn-sm btn-link text-danger p-0 pm-pa-remove" title="ลบแถว"><i class="fa fa-times"></i></button>';
						var $row = $('<div class="pm-pa-cert-row">'+
							'<div class="pm-pa-cert-side">'+rm+'</div>'+
							'<div class="pm-ro-cert-fields flex-grow-1 w-100">'+
								'<div class="row mx-0">'+
									'<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2">'+
										'<div class="pm-pa-lbl-inline d-flex flex-wrap justify-content-between align-items-baseline mb-1">'+
											'<label class="pm-pa-cert-lbl mb-0">ผู้อนุมัติโครงการ <span class="text-danger">*</span> <span class="pm-pa-cert-lbl-idx text-muted">('+n+')</span></label>'+
											'<span class="pm-pa-cert-lbl-hint">พิมพ์ค้นหาได้</span>'+
										'</div>'+
										'<div class="pm-pa-combo">'+
											'<input type="text" class="form-control pm-pa-combo-input" placeholder="- พิมพ์เพื่อค้นหา -" autocomplete="off">'+
											'<input type="hidden" class="pm-pa-cert-id" value="">'+
											'<div class="pm-pa-combo-list"></div>'+
										'</div>'+
									'</div>'+
									'<div class="col-md-6 col-12 pl-md-2">'+
										'<label class="d-block pm-pa-cert-lbl mb-1">ตำแหน่ง <span class="text-danger">*</span></label>'+
										'<input type="text" class="form-control pm-pa-cert-position pm-pa-pos" placeholder="ตำแหน่ง* (กรอก)" autocomplete="off">'+
									'</div>'+
								'</div>'+
							'</div>'+
						'</div>');
						$w.append($row);
						pmPaRenumber();
						pmPaSyncRm();
					}
					function pmPaResetRows(){
						$('#pmPaCertifiersRows').empty();
						pmPaAddRow();
						pmPaSyncRm();
					}
					function pmPaCollect(){
						var out=[];
						var err='';
						$('#pmPaCertifiersRows .pm-pa-cert-row').each(function(){
							var $r=$(this);
							var sid=String($r.find('.pm-pa-cert-id').val()||'').trim();
							var pos=String($r.find('input.pm-pa-pos').val()||'').trim();
							var typed=String($r.find('.pm-pa-combo-input').val()||'').trim();
							if(sid===''&&pos===''&&typed==='')return;
							if(sid===''||pos===''){ err='กรุณากรอกผู้อนุมัติและตำแหน่งให้ครบทุกลำดับที่ระบุ'; return false; }
							out.push({staff_id:parseInt(sid,10),position:pos});
						});
						if(err===''&&out.length===0) err='กรุณาระบุผู้อนุมัติโครงการอย่างน้อย 1 คน';
						return {ok: err===''&&out.length>0, err:err, rows:out};
					}

					$(document).on('click','#btnPmPaCertAdd',function(){ pmPaAddRow(); });
					$(document).on('click','#pmPaCertifiersRows .pm-pa-remove',function(){
						var $w=$('#pmPaCertifiersRows');
						if($w.find('.pm-pa-cert-row').length<=1)return;
						$(this).closest('.pm-pa-cert-row').remove();
						pmPaRenumber();
						pmPaSyncRm();
					});
					$(document).on('focus input', '#pmPaCertifiersRows .pm-pa-combo-input', function(){
						var $input = $(this);
						var $combo = $input.closest('.pm-pa-combo');
						pmPaCloseAllCombos($combo.find('.pm-pa-combo-list').get(0));
						// ถ้าพิมพ์ใหม่หลังเลือกแล้ว ให้เคลียร์ id
						if ($input.data('picked-text') && String($input.val()||'') !== String($input.data('picked-text')||'')) {
							$combo.find('.pm-pa-cert-id').val('');
							$input.removeData('picked-text');
						}
						pmPaRenderComboList($combo, $input.val());
					});
					$(document).on('keydown', '#pmPaCertifiersRows .pm-pa-combo-input', function(e){
						var $combo = $(this).closest('.pm-pa-combo');
						var $list = $combo.find('.pm-pa-combo-list');
						if (!$list.hasClass('is-open')) return;
						var $items = $list.find('.pm-pa-combo-item');
						if (!$items.length) return;
						var $cur = $items.filter('.is-active');
						var idx = $items.index($cur);
						if (e.key === 'ArrowDown') {
							e.preventDefault();
							idx = Math.min($items.length - 1, idx + 1);
							$items.removeClass('is-active').eq(idx).addClass('is-active');
						} else if (e.key === 'ArrowUp') {
							e.preventDefault();
							idx = Math.max(0, idx <= 0 ? 0 : idx - 1);
							$items.removeClass('is-active').eq(idx).addClass('is-active');
						} else if (e.key === 'Enter') {
							e.preventDefault();
							($cur.length ? $cur : $items.first()).trigger('mousedown');
						} else if (e.key === 'Escape') {
							pmPaCloseAllCombos();
						}
					});
					$(document).on('mousedown', '#pmPaCertifiersRows .pm-pa-combo-item', function(e){
						e.preventDefault();
						var $item = $(this);
						var $combo = $item.closest('.pm-pa-combo');
						var $row = $item.closest('.pm-pa-cert-row');
						var id = String($item.attr('data-id') || '');
						var text = String($item.attr('data-text') || $item.text() || '');
						var pos = String($item.attr('data-position') || '');
						$combo.find('.pm-pa-cert-id').val(id);
						$combo.find('.pm-pa-combo-input').val(text).data('picked-text', text);
						// ดึงตำแหน่งจากข้อมูลบุคคลมาเป็นค่าเริ่มต้น (ยังพิมพ์แก้ได้)
						$row.find('input.pm-pa-pos').val(pos);
						pmPaCloseAllCombos();
					});
					$(document).on('blur', '#pmPaCertifiersRows .pm-pa-combo-input', function(){
						var $input = $(this);
						setTimeout(function(){
							var $combo = $input.closest('.pm-pa-combo');
							$combo.find('.pm-pa-combo-list').removeClass('is-open').empty();
							// ถ้าไม่ได้เลือกจากรายการ ให้เคลียร์ข้อความค้าง
							if (!$combo.find('.pm-pa-cert-id').val()) {
								$input.val('');
							}
						}, 150);
					});
					$(document).on('click', function(e){
						if ($(e.target).closest('.pm-pa-combo').length) return;
						pmPaCloseAllCombos();
					});

					$(document).ready(function(){
						if (!$('#pmPlanAdminOperateCard').length) return;
						pmPaResetRows();
					});
					$(document).on('click','#btnPmPaOperateSubmit',function(){
						var id=parseInt($('#pmPaOperateProjectId').val()||'0',10);
						if(!id)return;
						var pack=pmPaCollect();
						if(!pack.ok){
							if(typeof Swal!=='undefined') Swal.fire({icon:'warning',title:'กรุณากรอกข้อมูล',text:pack.err||''});
							else alert(pack.err||'ข้อมูลไม่ครบ');
							return;
						}
						var $b=$(this).prop('disabled',true);
						$.ajax({
							url: '?page=project_manage&op=plan_admin_operate_rechain_ajax',
							type: 'POST',
							dataType: 'json',
							data: {
								page: 'project_manage',
								op: 'plan_admin_operate_rechain_ajax',
								project_id: id,
								certifiers_json: JSON.stringify(pack.rows)
							}
						}).done(function(res){
							if(res&&Number(res.ok)===1){
								if(typeof Swal!=='undefined') Swal.fire({icon:'success',title:String(res.msg||'บันทึกเรียบร้อย'),timer:1200,showConfirmButton:false}).then(function(){window.location.reload();});
								else window.location.reload();
								return;
							}
							var msg=(res&&res.msg)?res.msg:'บันทึกไม่สำเร็จ';
							if(typeof Swal!=='undefined') Swal.fire({icon:'error',title:'ไม่สำเร็จ',text:msg});
							else alert(msg);
						}).fail(function(){
							if(typeof Swal!=='undefined') Swal.fire({icon:'error',title:'ไม่สำเร็จ',text:'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้'});
							else alert('เกิดข้อผิดพลาด');
						}).always(function(){ $b.prop('disabled',false); });
					});
				})(jQuery);
				</script>
				<?php endif; ?>

