						<i class="fa <?= htmlspecialchars($pm_status_badge_icon, ENT_QUOTES, 'UTF-8') ?> mr-1"></i> <?= htmlspecialchars($pm_status_badge_txt, ENT_QUOTES, 'UTF-8') ?>
					</span>
				</div>
				<script>
				(function () {
					var $form = $('#form-add-project');
					if (!$form.length) return;
					$form.on('submit', function (e) {
						e.preventDefault();
						var submitter = e.originalEvent && e.originalEvent.submitter;
						var isHeaderSave = !submitter || submitter.id === 'btnHeaderSave' || (submitter.classList && submitter.classList.contains('pm-save-btn'));
						if (isHeaderSave) {
							var nameVal = String($('#name_project_input').val() || '').trim();
							if (!nameVal) {
								if (typeof Swal !== 'undefined') {
									Swal.fire({ icon: 'warning', title: 'กรุณากรอกชื่อโครงการ', text: 'ชื่อโครงการเป็นข้อมูลที่จำเป็น' });
								} else {
									alert('กรุณากรอกชื่อโครงการ');
								}
								$('#name_project_input').focus();
								return;
							}
						}
						var fd = new FormData(this);
						var $btns = $form.find('button[type="submit"]');
						$btns.prop('disabled', true);
						$.ajax({
							url: $form.attr('action'),
							type: 'POST',
							data: fd,
							processData: false,
							contentType: false,
							dataType: 'json'
						}).done(function (res) {
							if (res && res.ok === 1 && res.redirect) {
								if (typeof Swal !== 'undefined') {
									Swal.fire({ icon: 'success', title: 'บันทึกโครงการสำเร็จ', showConfirmButton: false, timer: 1000 }).then(function () {
										window.location.href = res.redirect;
									});
								} else {
									window.location.href = res.redirect;
								}
								return;
							}
							var msg = (res && res.msg) ? res.msg : 'ไม่สามารถบันทึกข้อมูลได้';
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ', text: msg });
							} else {
								alert(msg);
							}
						}).fail(function (xhr) {
							var msg = 'ไม่สามารถบันทึกข้อมูลได้';
							try {
								var j = JSON.parse(xhr.responseText || '{}');
								if (j && j.msg) msg = j.msg;
							} catch (err) { /* ignore */ }
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด', text: msg });
							} else {
								alert(msg);
							}
						}).always(function () {
							$btns.prop('disabled', false);
						});
					});
				})();
				</script>
