				<script>
				(function(){
					var $modal = $('#modalKpiGoalProject');
					var $form = $('#formKpiGoalProject');
					if (!$modal.length || !$form.length) return;

					function forceHideModal(){
						try { $modal.modal('hide'); } catch(e) {}
						try {
							var el = $modal.get(0);
							if (el) {
								el.classList.remove('show');
								el.style.display = 'none';
								el.setAttribute('aria-hidden', 'true');
							}
							document.body.classList.remove('modal-open');
							var backs = document.querySelectorAll('.modal-backdrop');
							backs.forEach(function(b){ if (b && b.parentNode) b.parentNode.removeChild(b); });
						} catch(e) {}
						setTimeout(function(){
							try { $modal.modal('hide'); } catch(e) {}
						}, 50);
					}

					var $txtKpiName = $('#kpiProjectTextKpiName');
					var $txtKpiUnit = $('#kpiProjectTextKpiUnit');
					var $hidCodeKpi = $('#kpiProjectHiddenCodeKpi');
					var $hidCodeUnit = $('#kpiProjectHiddenCodeUnit');

					function resetFields(){
						$('#kpiGoalType').val('insert');
						$('#kpiGoalProjectKpiId').val('');
						$('#kpiProjectWeight').val('');
						$txtKpiName.val('');
						$txtKpiUnit.val('');
						$hidCodeKpi.val('0');
						$hidCodeUnit.val('0');
						['mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09','mon_10','mon_11','mon_12'].forEach(function(name){
							var $el = $form.find('[name="'+name+'"]');
							if ($el && $el.length) $el.val('');
						});
					}

					function fillFromPayload(p){
						if (!p) return;
						$('#kpiGoalType').val('update');
						$('#kpiGoalProjectKpiId').val(p.project_kpi_id || '');
						$txtKpiName.val(p.kpi_name || '');
						$txtKpiUnit.val(p.kpi_unit || '');
						$hidCodeKpi.val((p.code_kpi !== undefined && p.code_kpi !== null && p.code_kpi !== '') ? p.code_kpi : '0');
						$hidCodeUnit.val((p.code_unit !== undefined && p.code_unit !== null && p.code_unit !== '') ? p.code_unit : '0');
						$('#kpiProjectWeight').val(p.kpi_weight || '');
						['mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09','mon_10','mon_11','mon_12'].forEach(function(name){
							var v = (p[name] !== undefined && p[name] !== null) ? p[name] : '';
							var $el = $form.find('[name="'+name+'"]');
							if ($el && $el.length) $el.val(v);
						});
					}

					$form.on('submit', function(e){
						var kpiVal = ($txtKpiName.val() || '').toString().trim();
						var unitVal = ($txtKpiUnit.val() || '').toString().trim();
						if (!kpiVal) {
							e.preventDefault();
							if (window.Swal && Swal.fire) {
								Swal.fire({ icon: 'warning', title: 'กรุณากรอกชื่อตัวชี้วัด', confirmButtonText: 'ตกลง' });
							} else {
								alert('กรุณากรอกชื่อตัวชี้วัด');
							}
							$txtKpiName.trigger('focus');
							return false;
						}
						if (!unitVal) {
							e.preventDefault();
							if (window.Swal && Swal.fire) {
								Swal.fire({ icon: 'warning', title: 'กรุณากรอกหน่วยนับ', confirmButtonText: 'ตกลง' });
							} else {
								alert('กรุณากรอกหน่วยนับ');
							}
							$txtKpiUnit.trigger('focus');
							return false;
						}
						e.preventDefault();
						var actionUrl = $form.attr('action') || '';
						var payload = $form.serialize();
						$form.find('button[type="submit"]').prop('disabled', true);
						$.ajax({
							url: actionUrl,
							method: 'POST',
							data: payload,
							dataType: 'text'
						}).done(function(respText){
							var r = null;
							try { r = JSON.parse(respText); } catch(e) { r = null; }
							if (!r) {
								var show = (respText || '').toString().substring(0, 600);
								if (window.Swal && Swal.fire) {
									Swal.fire({
										icon: 'error',
										title: 'เซิร์ฟเวอร์ตอบกลับไม่ถูกต้อง',
										html: '<pre style="text-align:left;white-space:pre-wrap;">'+String(show).replace(/[<>&]/g,function(c){return({'<':'&lt;','>':'&gt;','&':'&amp;'})[c];})+'</pre>',
										confirmButtonText: 'ตกลง'
									});
								} else {
									alert('เซิร์ฟเวอร์ตอบกลับไม่ถูกต้อง\n' + show);
								}
								return;
							}
							if (r && (r.ok === 1 || r.ok === true)) {
								if (window.Swal && Swal.fire) {
									Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', timer: 1200, showConfirmButton: false });
								}
								if (r.weight_warning && window.Swal && Swal.fire) {
									setTimeout(function () {
										Swal.fire({ icon: 'warning', title: 'ค่าน้ำหนักตัวชี้วัด', text: String(r.weight_warning) });
									}, 300);
								}
								forceHideModal();
								// refresh เฉพาะตาราง KPI โดยไม่โหลดหน้า
								var pid = ($form.find('[name="project_id"]').val() || '').toString().trim();
								$.ajax({
									url: '?page=project_manage&op=render_kpi_goal_table',
									method: 'POST',
									data: { project_id: pid },
									dataType: 'text'
								}).done(function(rrText){
									var rr = null;
									try { rr = JSON.parse(rrText); } catch(e) { rr = null; }
									if (rr && (rr.ok === 1 || rr.ok === true) && rr.html) {
										$('#kpi-goal-table-wrap').html(rr.html);
										if (typeof pmShowKpiWeightBanner === 'function') {
											pmShowKpiWeightBanner(rr.weight_warning);
										}
										// อัปเดต step ข้อมูลโครงการ (ตัวชี้วัดอยู่ในส่วนที่ 3)
										var hasRows = ($('#kpi-goal-table-wrap').text().indexOf('ยังไม่มีตัวชี้วัดของโครงการ') === -1);
										if (typeof setStepCircle === 'function') setStepCircle('#step-s3-circle', !!hasRows);
										if (typeof setStepLine === 'function') setStepLine('#step-line-3', !!hasRows);
									}
								});
							} else {
								var msg = (r && (r.msg || r.message)) ? (r.msg || r.message) : 'บันทึกไม่สำเร็จ';
								if (window.Swal && Swal.fire) {
									Swal.fire({ icon: 'error', title: msg, confirmButtonText: 'ตกลง' });
								} else {
									alert(msg);
								}
							}
						}).fail(function(jqXHR, textStatus, errorThrown){
							var msg = 'เชื่อมต่อไม่สำเร็จ';
							try {
								var status = (jqXHR && jqXHR.status) ? jqXHR.status : '';
								var rt = (jqXHR && jqXHR.responseText) ? jqXHR.responseText : '';
								var head = ('status=' + status + ' textStatus=' + (textStatus || '') + ' error=' + (errorThrown || '')).trim();
								msg = msg + '\n' + head;
								if (rt) msg = msg + '\n' + rt.substring(0, 600);
							} catch(e) {}
							if (window.Swal && Swal.fire) {
								Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ', html: '<pre style="text-align:left;white-space:pre-wrap;">'+String(msg).replace(/[<>&]/g,function(c){return({'<':'&lt;','>':'&gt;','&':'&amp;'})[c];})+'</pre>', confirmButtonText: 'ตกลง' });
							} else {
								alert(msg);
							}
						}).always(function(){
							$form.find('button[type="submit"]').prop('disabled', false);
						});
						return false;
					});

					$(document).on('click', '[data-kpi-goal-action="add"]', function(){
						resetFields();
						$('#modalKpiGoalTitle').html('<i class="fa fa-plus-circle mr-1"></i> เพิ่มตัวชี้วัดเป้าหมายโครงการ');
					});

					$(document).on('click', '[data-kpi-goal-action="edit"]', function(){
						var raw = $(this).attr('data-kpi-goal-row') || '{}';
						var p = {};
						try { p = JSON.parse(raw); } catch(e){ p = {}; }
						fillFromPayload(p);
						$('#modalKpiGoalTitle').html('<i class="fa fa-edit mr-1"></i> แก้ไขตัวชี้วัดเป้าหมายโครงการ');
					});

					$(document).on('click', '[data-kpi-goal-action="delete"]', function(){
						var id = parseInt($(this).attr('data-kpi-goal-id') || '0', 10) || 0;
						if (!id) return;
						var doDelete = function(){
							var pid = ($form.find('[name="project_id"]').val() || '').toString().trim();
							$form.find('button[type="submit"]').prop('disabled', true);
							$.ajax({
								url: '?page=project_manage&op=save_data_kpi_project_ajax',
								method: 'POST',
								data: { project_id: pid, type: 'delete', project_kpi_id: id, ajax: 1 },
								dataType: 'text'
							}).done(function(respText){
								var r = null;
								try { r = JSON.parse(respText); } catch(e) { r = null; }
								if (!r || !(r.ok === 1 || r.ok === true)) {
									var msg = (r && (r.msg || r.message)) ? (r.msg || r.message) : (respText || 'ลบไม่สำเร็จ');
									if (window.Swal && Swal.fire) Swal.fire({ icon: 'error', title: 'ลบไม่สำเร็จ', text: String(msg) });
									else alert('ลบไม่สำเร็จ: ' + msg);
									return;
								}
								if (window.Swal && Swal.fire) Swal.fire({ icon: 'success', title: 'ลบสำเร็จ', timer: 900, showConfirmButton: false });
								$.ajax({
									url: '?page=project_manage&op=render_kpi_goal_table',
									method: 'POST',
									data: { project_id: pid },
									dataType: 'text'
								}).done(function(rrText){
									var rr = null;
									try { rr = JSON.parse(rrText); } catch(e) { rr = null; }
									if (rr && (rr.ok === 1 || rr.ok === true) && rr.html) {
										$('#kpi-goal-table-wrap').html(rr.html);
										if (typeof pmShowKpiWeightBanner === 'function') {
											pmShowKpiWeightBanner(rr.weight_warning);
										}
										var hasRows = ($('#kpi-goal-table-wrap').text().indexOf('ยังไม่มีตัวชี้วัดของโครงการ') === -1);
										if (typeof setStepCircle === 'function') setStepCircle('#step-s3-circle', !!hasRows);
										if (typeof setStepLine === 'function') setStepLine('#step-line-3', !!hasRows);
									}
								});
							}).always(function(){
								$form.find('button[type="submit"]').prop('disabled', false);
							});
						};

						if (window.Swal && Swal.fire) {
							Swal.fire({
								icon: 'warning',
								title: 'ยืนยันการลบ?',
								text: 'ต้องการลบตัวชี้วัดรายการนี้หรือไม่',
								showCancelButton: true,
								confirmButtonText: 'ลบ',
								cancelButtonText: 'ยกเลิก'
							}).then(function(res){
								if (res && res.isConfirmed) doDelete();
							});
						} else {
							if (confirm('ต้องการลบตัวชี้วัดรายการนี้หรือไม่?')) doDelete();
						}
					});
				})();
				</script>
				<?php if (!empty($pm_can_fill_project_results)): ?>
				<script>
				(function(){
					var $modal = $('#modalKpiResultFill');
					var $form = $('#formKpiResultFill');
					if (!$modal.length || !$form.length) return;

					function forceHideKpiResultModal(){
						try { $modal.modal('hide'); } catch(err) {}
						try {
							var el = $modal.get(0);
							if (el) {
								el.classList.remove('show');
								el.style.display = 'none';
								el.setAttribute('aria-hidden', 'true');
							}
							document.body.classList.remove('modal-open');
							document.body.style.removeProperty('padding-right');
							document.querySelectorAll('.modal-backdrop').forEach(function(b){
								if (b && b.parentNode) b.parentNode.removeChild(b);
							});
						} catch(err) {}
						setTimeout(function(){
							try { $modal.modal('hide'); } catch(err) {}
						}, 50);
					}

					var pmKpiMonthPlanDefs = <?= json_encode(pm_kpi_month_plan_fields(), JSON_UNESCAPED_UNICODE) ?>;
					var currentKpiPlan = {};
					var currentKpiActual = {};
					var currentKpiSavedItems = [];
					var currentKpiUnit = '';

					function formatKpiPlanNum(v){
						var n = parseFloat(v);
						if (isNaN(n) || n === 0) return '-';
						if (Math.abs(n - Math.round(n)) < 0.0001) {
							return String(Math.round(n));
						}
						return String(n);
					}

					function kpiComputeSuccessPercent(plan, result){
						plan = parseFloat(plan) || 0;
						result = parseFloat(result) || 0;
						if (plan <= 0) return result > 0 ? 101 : 0;
						return Math.max(0, Math.round((result / plan) * 100));
					}

					function kpiSuccessPercentTone(pct){
						pct = parseInt(pct, 10) || 0;
						if (pct > 100) return 'is-over';
						if (pct < 100) return 'is-under';
						return 'is-exact';
					}

					function buildKpiTrioHtml(plan, result, monthLabel){
						plan = parseFloat(plan) || 0;
						result = parseFloat(result) || 0;
						var pct = kpiComputeSuccessPercent(plan, result);
						var pctTone = kpiSuccessPercentTone(pct);
						var planShow = plan > 0 ? formatKpiPlanNum(plan) : '-';
						var resultShow = result > 0 ? formatKpiPlanNum(result) : '-';
						var monthHtml = monthLabel ? '<div class="pm-kpi-goal-trio-month-label">' + monthLabel + '</div>' : '';
						return '<div class="pm-kpi-goal-trio pm-kpi-goal-trio-month">' + monthHtml +
							'<div class="pm-kpi-goal-trio-body">' +
								'<div class="pm-kpi-goal-trio-group"><span class="pm-kpi-goal-trio-label">ค่าเป้าหมาย</span><span class="pm-kpi-goal-trio-box">' + planShow + '</span></div>' +
								'<div class="pm-kpi-goal-trio-group"><span class="pm-kpi-goal-trio-label">ผล</span><span class="pm-kpi-goal-trio-box pm-kpi-goal-trio-box-result">' + resultShow + '</span></div>' +
								'<div class="pm-kpi-goal-trio-group pm-kpi-goal-trio-group-pct"><span class="pm-kpi-goal-trio-label">ร้อยละความสำเร็จของตัวชี้วัด</span><span class="pm-kpi-goal-trio-bar ' + pctTone + '"><span>' + pct + '%</span></span></div>' +
							'</div>' +
						'</div>';
					}

					function kpiSumPlanTotal(plan){
						var sum = 0;
						pmKpiMonthPlanDefs.forEach(function(m){
							sum += parseFloat((plan || {})[m.field]) || 0;
						});
						return sum;
					}

					function kpiSumResultTotal(actualMap){
						var sum = 0;
						pmKpiMonthPlanDefs.forEach(function(m){
							sum += parseFloat((actualMap || {})[m.val]) || 0;
						});
						return sum;
					}

					function renderKpiResultActualStrip(plan, actualMap){
						currentKpiActual = actualMap || {};
						var $wrap = $('#kpiResultActualWrap');
						var resultSum = kpiSumResultTotal(currentKpiActual);
						if (resultSum <= 0) {
							$wrap.addClass('d-none').empty();
							return;
						}
						var planSum = kpiSumPlanTotal(plan);
						var html = '<div class="pm-kpi-result-actual-title"><i class="fa fa-chart-bar mr-1"></i>ผลที่บันทึกแล้ว</div>';
						html += buildKpiTrioHtml(planSum, resultSum, '');
						$wrap.removeClass('d-none').html(html);
					}

					function escapeKpiHtml(s){
						return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
					}

					function linkifyKpiDetailHtml(detail){
						detail = (detail || '').toString().trim();
						if (!detail) return '<span class="text-muted">-</span>';
						var escaped = escapeKpiHtml(detail).replace(/\n/g, '<br>');
						return escaped.replace(/(https?:\/\/[^\s<]+|www\.[^\s<]+)/gi, function(m){
							var href = /^https?:\/\//i.test(m) ? m : ('http://' + m);
							return '<a href="' + escapeKpiHtml(href) + '" target="_blank" rel="noopener">' + escapeKpiHtml(m) + '</a>';
						});
					}

					function setKpiResultEditMode(isEdit){
						if (isEdit) {
							$('#btnKpiResultSaveText').text('บันทึกการแก้ไข');
							$('#btnKpiResultAddEntry').prop('disabled', true);
						} else {
							$('#kpiResultEditId').val('');
							$('#btnKpiResultSaveText').text('บันทึกผล');
							$('#btnKpiResultAddEntry').prop('disabled', false);
							$('#kpiResultEditHint').remove();
						}
					}

					function buildKpiSavedFileHtml(files){
						if (!files || !files.length) return '<span class="text-muted">-</span>';
						var html = '<div class="pm-kpi-result-saved-files">';
						files.forEach(function(f){
							var name = escapeKpiHtml(f.name || 'file');
							var url = escapeKpiHtml(f.url || '#');
							var icon = (f.is_pdf || f.ext === 'pdf') ? 'fa-file-pdf' : 'fa-file';
							html += '<a class="pm-kpi-result-saved-file" href="' + url + '" target="_blank" rel="noopener">';
							html += '<i class="fa ' + icon + '"></i><span>' + name + '</span></a>';
						});
						html += '</div>';
						return html;
					}

					function renderKpiResultSavedList(items){
						currentKpiSavedItems = items || [];
						var $list = $('#kpiResultSavedList');
						var $empty = $('#kpiResultSavedEmpty');
						if (!currentKpiSavedItems.length) {
							$list.empty();
							$empty.removeClass('d-none');
							return;
						}
						$empty.addClass('d-none');
						var html = '';
						currentKpiSavedItems.forEach(function(it){
							var id = parseInt(it.id, 10) || 0;
							html += '<div class="pm-kpi-result-saved-item" data-result-id="' + id + '">';
							html += '<div class="pm-kpi-result-saved-actions">';
							html += '<button type="button" class="btn btn-success btn-sm btn-kpi-result-saved-edit" data-result-id="' + id + '">แก้ไข</button>';
							html += '<button type="button" class="btn btn-danger btn-sm btn-kpi-result-saved-delete" data-result-id="' + id + '">ลบ</button>';
							html += '</div>';
							html += '<table class="pm-kpi-result-saved-table"><tbody>';
							html += '<tr><th>เดือนที่เกิดผล</th><td>' + escapeKpiHtml(it.month_label || it.month || '-') + '</td></tr>';
							html += '<tr><th>รายละเอียด</th><td>' + linkifyKpiDetailHtml(it.detail) + '</td></tr>';
							html += '<tr><th>จำนวน</th><td><strong>' + escapeKpiHtml(formatKpiPlanNum(it.amount)) + '</strong></td></tr>';
							html += '<tr><th>ไฟล์แนบ</th><td>' + buildKpiSavedFileHtml(it.files) + '</td></tr>';
							html += '</tbody></table></div>';
						});
						$list.html(html);
					}

					function rebuildKpiActualFromItems(items, plan){
						var actualMap = {};
						(items || []).forEach(function(it){
							var m = (it.month || '').toString();
							if (!m) return;
							actualMap[m] = (parseFloat(actualMap[m]) || 0) + (parseFloat(it.amount) || 0);
						});
						renderKpiResultActualStrip(plan, actualMap);
					}

					function loadKpiResultSavedList(){
						var pid = ($('#kpiResultProjectId').val() || '').toString().trim();
						var kpiId = ($('#kpiResultProjectKpiId').val() || '').toString().trim();
						if (!pid || !kpiId) {
							renderKpiResultSavedList([]);
							$('#kpiResultActualWrap').addClass('d-none').empty();
							return;
						}
						$.ajax({
							url: '?page=project_manage&op=list_kpi_result_ajax',
							method: 'POST',
							data: {
								project_id: pid,
								project_kpi_id: kpiId,
								years_select: ($('#kpiResultYearsSelect').val() || '').toString()
							},
							dataType: 'text'
						}).done(function(txt){
							var r = null;
							try { r = JSON.parse(txt); } catch(err) { r = null; }
							if (r && (r.ok === 1 || r.ok === true)) {
								renderKpiResultSavedList(r.items || []);
								rebuildKpiActualFromItems(r.items || [], currentKpiPlan);
							}
						});
					}

					function startKpiResultEdit(item){
						if (!item) return;
						setKpiResultEditMode(true);
						$('#kpiResultEditId').val(String(item.id || ''));
						kpiResultEntrySeq = 0;
						$('#kpiResultEntriesWrap').empty();
						var $row = addKpiResultEntryRow(item.month, item.amount);
						$row.find('.kpi-result-entry-detail').val(item.detail || '');
						if (item.files && item.files.length) {
							var names = item.files.map(function(f){ return f.name; }).join(', ');
							$row.append('<div class="pm-kpi-result-edit-hint mt-2"><i class="fa fa-paperclip mr-1"></i>ไฟล์เดิม: ' + escapeKpiHtml(names) + ' (อัปโหลดใหม่เพื่อเพิ่มไฟล์)</div>');
						}
						$('#kpiResultEditHint').remove();
						$('#kpiResultEntriesWrap').before(
							'<div id="kpiResultEditHint" class="pm-kpi-result-edit-hint"><i class="fa fa-edit mr-1"></i>กำลังแก้ไขข้อมูลเดือน ' +
							escapeKpiHtml(item.month_label || '') +
							' — <a href="#" class="pm-kpi-result-cancel-edit">ยกเลิก</a></div>'
						);
						syncKpiResultPlanHighlights();
					}

					function resetKpiResultEntryFormOnly(){
						setKpiResultEditMode(false);
						resetKpiResultEntries();
					}

					var kpiResultEntrySeq = 0;

					function buildKpiResultMonthOptions(selectedVal){
						var html = '<option value="">- เลือกเดือน -</option>';
						pmKpiMonthPlanDefs.forEach(function(m){
							var sel = (selectedVal === m.val) ? ' selected' : '';
							html += '<option value="' + m.val + '"' + sel + '>' + m.lbl + '</option>';
						});
						return html;
					}

					function getKpiMonthDef(monthVal){
						for (var i = 0; i < pmKpiMonthPlanDefs.length; i++) {
							if (pmKpiMonthPlanDefs[i].val === monthVal) return pmKpiMonthPlanDefs[i];
						}
						return null;
					}

					function getSelectedEntryMonths(){
						var months = [];
						$('#kpiResultEntriesWrap .kpi-result-entry-month').each(function(){
							var v = ($(this).val() || '').toString().trim();
							if (v) months.push(v);
						});
						return months;
					}

					function syncKpiResultPlanHighlights(){
						var months = getSelectedEntryMonths();
						var $cells = $('#kpiResultPlanGrid .pm-kpi-result-plan-cell');
						$cells.removeClass('is-selected');
						months.forEach(function(mv){
							$cells.filter('[data-month="' + mv + '"]').addClass('is-selected');
						});
						var $selected = $('#kpiResultPlanSelected');
						if (!months.length) {
							$selected.addClass('d-none').empty();
							return;
						}
						if (months.length === 1) {
							var def = getKpiMonthDef(months[0]);
							if (!def) {
								$selected.addClass('d-none').empty();
								return;
							}
							var planVal = parseFloat(currentKpiPlan[def.field]) || 0;
							var unitTxt = currentKpiUnit ? (' ' + currentKpiUnit) : '';
							if (planVal > 0) {
								$selected.removeClass('d-none').html(
									'<i class="fa fa-bullseye mr-1"></i>เป้าหมายเดือน ' + def.short + ': <strong>' + formatKpiPlanNum(planVal) + unitTxt + '</strong>'
								);
							} else {
								$selected.removeClass('d-none').html(
									'<i class="fa fa-info-circle mr-1"></i>เดือน ' + def.short + ' ไม่ได้กำหนดเป้าหมายไว้ในแผน'
								);
							}
							return;
						}
						$selected.removeClass('d-none').html(
							'<i class="fa fa-check-double mr-1"></i>กำลังกรอกผล ' + months.length + ' เดือน'
						);
					}

					function renderKpiResultPlanGrid(plan){
						currentKpiPlan = plan || {};
						var html = '';
						var total = 0;
						pmKpiMonthPlanDefs.forEach(function(m){
							var raw = currentKpiPlan[m.field];
							var n = parseFloat(raw);
							var hasVal = !isNaN(n) && n !== 0;
							if (hasVal) total += n;
							html += '<div class="pm-kpi-result-plan-cell' + (hasVal ? ' has-value' : '') + '" data-month="' + m.val + '" title="คลิกเพื่อเพิ่ม/เลือกรายการเดือนนี้">' +
								'<div class="pm-kpi-result-plan-month">' + m.short + '</div>' +
								'<div class="pm-kpi-result-plan-val">' + (hasVal ? formatKpiPlanNum(n) : '-') + '</div>' +
								'</div>';
						});
						$('#kpiResultPlanGrid').html(html);
						$('#kpiResultPlanTotal').text(total > 0 ? formatKpiPlanNum(total) : '-');
						syncKpiResultPlanHighlights();
					}

					var pmKpiResultFileAccept = '.pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.gif,.webp,image/*,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

					function refreshKpiResultEntryLabels(){
						$('#kpiResultEntriesWrap .pm-kpi-result-entry-row').each(function(idx){
							$(this).find('.pm-kpi-result-entry-no').text('รายการที่ ' + (idx + 1));
						});
					}

					function addKpiResultEntryRow(monthVal, amountVal){
						kpiResultEntrySeq += 1;
						var rowId = kpiResultEntrySeq;
						var fileKey = 'e' + rowId;
						var fileInputId = 'kpiResultFiles_' + fileKey;
						var amount = (amountVal !== undefined && amountVal !== null) ? amountVal : '';
						var html = '<div class="pm-kpi-result-entry-row" data-entry-id="' + rowId + '" data-entry-key="' + fileKey + '">' +
							'<div class="pm-kpi-result-entry-head">' +
								'<span class="pm-kpi-result-entry-no">รายการที่ 1</span>' +
								'<button type="button" class="btn btn-outline-danger btn-sm pm-kpi-result-entry-remove" title="ลบรายการ"><i class="fa fa-times"></i></button>' +
							'</div>' +
							'<div class="form-row align-items-end">' +
								'<div class="col-sm-6">' +
									'<label class="pm-kpi-result-label">เดือนที่เกิดผล <span class="text-danger">*</span></label>' +
									'<select class="form-control form-control-sm pm-kpi-result-control kpi-result-entry-month">' +
										buildKpiResultMonthOptions(monthVal || '') +
									'</select>' +
								'</div>' +
								'<div class="col-sm-6">' +
									'<label class="pm-kpi-result-label">จำนวน <span class="text-danger">*</span></label>' +
									'<input type="number" class="form-control form-control-sm pm-kpi-result-control kpi-result-entry-amount" min="0" step="0.01" placeholder="กรอกจำนวน" value="' + String(amount).replace(/"/g, '&quot;') + '">' +
								'</div>' +
							'</div>' +
							'<div class="form-group pm-kpi-result-field mb-2 mt-2">' +
								'<label class="pm-kpi-result-label">รายละเอียด</label>' +
								'<textarea class="form-control form-control-sm pm-kpi-result-control kpi-result-entry-detail" rows="2" placeholder="อธิบายรายละเอียดผลของเดือนนี้ (ถ้ามี)"></textarea>' +
							'</div>' +
							'<div class="form-group pm-kpi-result-field mb-0">' +
								'<label class="pm-kpi-result-label d-block mb-1">ไฟล์แนบ</label>' +
								'<label for="' + fileInputId + '" class="pm-kpi-result-entry-upload">' +
									'<i class="fa fa-paperclip"></i><span>เลือกไฟล์ (หลายไฟล์ได้)</span>' +
								'</label>' +
								'<input type="file" class="d-none kpi-result-entry-files" id="' + fileInputId + '" multiple accept="' + pmKpiResultFileAccept + '">' +
								'<small class="text-muted d-block mt-1">PDF, Word, Excel, รูปภาพ · สูงสุด 30MB/ไฟล์</small>' +
								'<div class="pm-kpi-result-file-list kpi-result-entry-file-list"></div>' +
							'</div>' +
						'</div>';
						$('#kpiResultEntriesWrap').append(html);
						refreshKpiResultEntryLabels();
						syncKpiResultPlanHighlights();
						return $('#kpiResultEntriesWrap .pm-kpi-result-entry-row[data-entry-id="' + rowId + '"]');
					}

					function ensureKpiResultEntryForMonth(monthVal){
						var $existing = null;
						$('#kpiResultEntriesWrap .kpi-result-entry-month').each(function(){
							if (($(this).val() || '').toString().trim() === monthVal) {
								$existing = $(this).closest('.pm-kpi-result-entry-row');
							}
						});
						if ($existing && $existing.length) {
							$existing.find('.kpi-result-entry-amount').trigger('focus');
							return $existing;
						}
						var $row = addKpiResultEntryRow(monthVal, '');
						$row.find('.kpi-result-entry-amount').trigger('focus');
						return $row;
					}

					function resetKpiResultEntries(){
						kpiResultEntrySeq = 0;
						$('#kpiResultEntriesWrap').empty();
						addKpiResultEntryRow('', '');
					}

					function rowHasEntryData($row){
						var month = ($row.find('.kpi-result-entry-month').val() || '').toString().trim();
						var amount = ($row.find('.kpi-result-entry-amount').val() || '').toString().trim();
						var detail = ($row.find('.kpi-result-entry-detail').val() || '').toString().trim();
						var inp = $row.find('.kpi-result-entry-files')[0];
						var hasFiles = !!(inp && inp.files && inp.files.length);
						return month !== '' || amount !== '' || detail !== '' || hasFiles;
					}

					function clearKpiResultEntryRow($row){
						$row.find('.kpi-result-entry-month').val('');
						$row.find('.kpi-result-entry-amount').val('');
						$row.find('.kpi-result-entry-detail').val('');
						var inp = $row.find('.kpi-result-entry-files')[0];
						if (inp) inp.value = '';
						$row.find('.kpi-result-entry-file-list').empty();
					}

					function collectKpiResultEntries(){
						var entries = [];
						var seen = {};
						var rowNo = 0;
						$('#kpiResultEntriesWrap .pm-kpi-result-entry-row').each(function(){
							var $row = $(this);
							if (!rowHasEntryData($row)) return;
							rowNo += 1;
							var month = ($row.find('.kpi-result-entry-month').val() || '').toString().trim();
							var amount = ($row.find('.kpi-result-entry-amount').val() || '').toString().trim();
							var detail = ($row.find('.kpi-result-entry-detail').val() || '').toString().trim();
							var fileKey = ($row.attr('data-entry-key') || '').toString().trim();
							if (month === '') {
								throw { type: 'month', row: rowNo };
							}
							if (amount === '' || isNaN(parseFloat(amount))) {
								throw { type: 'amount', row: rowNo };
							}
							if (seen[month]) {
								throw { type: 'dup', row: rowNo };
							}
							seen[month] = true;
							entries.push({ month: month, amount: amount, detail: detail, file_key: fileKey });
						});
						return entries;
					}

					function resetKpiResultForm(){
						$form[0].reset();
						$('#kpiResultProjectKpiId').val('');
						$('#kpiResultKpiLabel').text('-');
						currentKpiPlan = {};
						currentKpiActual = {};
						currentKpiSavedItems = [];
						currentKpiUnit = '';
						$('#kpiResultPlanGrid').empty();
						$('#kpiResultPlanTotal').text('-');
						$('#kpiResultPlanSelected').addClass('d-none').empty();
						$('#kpiResultActualWrap').addClass('d-none').empty();
						$('#kpiResultSavedList').empty();
						$('#kpiResultSavedEmpty').removeClass('d-none');
						setKpiResultEditMode(false);
						resetKpiResultEntries();
					}

					function kpiResultAfterSaveSuccess(r){
						resetKpiResultEntryFormOnly();
						loadKpiResultSavedList();
						pmRefreshKpiGoalTable();
						if (window.Swal && Swal.fire) {
							Swal.fire({ icon: 'success', title: 'บันทึกสำเร็จ', text: String((r && r.msg) ? r.msg : ''), timer: 1600, showConfirmButton: false });
						}
					}

					function pmRefreshKpiGoalTable(){
						var pid = ($('#kpiResultProjectId').val() || $('#edit_project_id').val() || '').toString().trim();
						if (!pid) return;
						$.ajax({
							url: '?page=project_manage&op=render_kpi_goal_table',
							method: 'POST',
							data: { project_id: pid },
							dataType: 'text'
						}).done(function(txt){
							var rr = null;
							try { rr = JSON.parse(txt); } catch(err) { rr = null; }
							if (rr && (rr.ok === 1 || rr.ok === true) && rr.html) {
								$('#kpi-goal-table-wrap').html(rr.html);
							}
						});
					}

					var pmKpiResultAllowedExt = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png', 'gif', 'webp'];

					function isKpiResultFileAllowed(fileName){
						var ext = String(fileName || '').split('.').pop().toLowerCase();
						return pmKpiResultAllowedExt.indexOf(ext) !== -1;
					}

					function showKpiResultEntryFileNames(inp){
						if (!inp) return;
						var $row = $(inp).closest('.pm-kpi-result-entry-row');
						var $list = $row.find('.kpi-result-entry-file-list');
						if (!inp.files || !inp.files.length) {
							$list.empty();
							return;
						}
						var invalid = [];
						var chips = [];
						for (var i = 0; i < inp.files.length; i++) {
							var rawName = String(inp.files[i].name || '');
							if (!isKpiResultFileAllowed(rawName)) {
								invalid.push(rawName);
								continue;
							}
							var name = rawName.replace(/[<>&]/g, function(c){
								return ({'<':'&lt;','>':'&gt;','&':'&amp;'})[c];
							});
							chips.push('<span class="pm-kpi-result-file-chip"><i class="fa fa-paperclip"></i><span>' + name + '</span></span>');
						}
						if (invalid.length) {
							inp.value = '';
							$list.empty();
							var msg = 'อนุญาตเฉพาะ PDF, Word, Excel และรูปภาพเท่านั้น';
							if (window.Swal && Swal.fire) {
								Swal.fire({ icon: 'warning', title: 'ไฟล์ไม่รองรับ', text: msg, confirmButtonText: 'ตกลง' });
							} else {
								alert(msg);
							}
							return;
						}
						$list.html(chips.join(''));
					}

					$(document).on('click', '.btn-kpi-fill-result', function(){
						var $btn = $(this);
						var kpiId = parseInt($btn.attr('data-kpi-result-id') || '0', 10) || 0;
						var kpiName = ($btn.attr('data-kpi-result-name') || '-').toString();
						var kpiUnit = ($btn.attr('data-kpi-result-unit') || '').toString().trim();
						var planRaw = $btn.attr('data-kpi-result-plan') || '{}';
						var plan = {};
						try { plan = JSON.parse(planRaw); } catch(err) { plan = {}; }
						resetKpiResultForm();
						$('#kpiResultProjectKpiId').val(kpiId > 0 ? String(kpiId) : '');
						var label = kpiName;
						if (kpiUnit) label += ' (' + kpiUnit + ')';
						$('#kpiResultKpiLabel').text(label);
						currentKpiUnit = kpiUnit;
						renderKpiResultPlanGrid(plan);
						resetKpiResultEntries();
						loadKpiResultSavedList();
						var hasSaved = ($btn.attr('data-kpi-result-has') || '0') === '1';
						$('#modalKpiResultFillTitle').html(
							hasSaved
								? '<i class="fa fa-edit mr-1"></i> แก้ไขผลตัวชี้วัด'
								: '<i class="fa fa-pen-square mr-1"></i> กรอกผลตัวชี้วัด'
						);
					});

					function renderKpiResultViewList(items){
						var $list = $('#kpiResultViewList');
						var $empty = $('#kpiResultViewEmpty');
						if (!items || !items.length) {
							$list.empty();
							$empty.removeClass('d-none');
							return;
						}
						$empty.addClass('d-none');
						var html = '';
						items.forEach(function(it){
							html += '<div class="pm-kpi-result-view-item">';
							html += '<table><tbody>';
							html += '<tr><th>เดือนที่เกิดผล</th><td>' + escapeKpiHtml(it.month_label || it.month || '-') + '</td></tr>';
							html += '<tr><th>จำนวน</th><td><strong>' + escapeKpiHtml(formatKpiPlanNum(it.amount)) + '</strong></td></tr>';
							html += '<tr><th>รายละเอียด</th><td>' + linkifyKpiDetailHtml(it.detail) + '</td></tr>';
							html += '<tr><th>ไฟล์แนบ</th><td>' + buildKpiSavedFileHtml(it.files) + '</td></tr>';
							html += '</tbody></table></div>';
						});
						$list.html(html);
					}

					$(document).on('click', '.btn-kpi-view-result', function(){
						var $btn = $(this);
						var kpiId = parseInt($btn.attr('data-kpi-result-id') || '0', 10) || 0;
						var kpiName = ($btn.attr('data-kpi-result-name') || '-').toString();
						var kpiUnit = ($btn.attr('data-kpi-result-unit') || '').toString().trim();
						var pid = ($('#kpiResultProjectId').val() || $('#edit_project_id').val() || '').toString().trim();
						if (!kpiId || !pid) return;
						var label = kpiName;
						if (kpiUnit) label += ' (' + kpiUnit + ')';
						$('#kpiResultViewKpiLabel').text(label);
						$('#kpiResultViewList').html('<div class="text-muted small">กำลังโหลด...</div>');
						$('#kpiResultViewEmpty').addClass('d-none');
						$('#modalKpiResultView').modal('show');
						$.ajax({
							url: '?page=project_manage&op=list_kpi_result_ajax',
							method: 'POST',
							data: {
								project_id: pid,
								project_kpi_id: kpiId,
								years_select: ($('#kpiResultYearsSelect').val() || '').toString()
							},
							dataType: 'text'
						}).done(function(txt){
							var r = null;
							try { r = JSON.parse(txt); } catch(err) { r = null; }
							if (r && (r.ok === 1 || r.ok === true)) {
								renderKpiResultViewList(r.items || []);
							} else {
								$('#kpiResultViewList').empty();
								$('#kpiResultViewEmpty').removeClass('d-none').text((r && r.msg) ? String(r.msg) : 'โหลดข้อมูลไม่สำเร็จ');
							}
						}).fail(function(){
							$('#kpiResultViewList').empty();
							$('#kpiResultViewEmpty').removeClass('d-none').text('เชื่อมต่อเซิร์ฟเวอร์ไม่สำเร็จ');
						});
					});

					$(document).on('click', '.btn-kpi-result-saved-edit', function(){
						var id = parseInt($(this).attr('data-result-id') || '0', 10) || 0;
						if (!id) return;
						var item = null;
						for (var i = 0; i < currentKpiSavedItems.length; i++) {
							if (parseInt(currentKpiSavedItems[i].id, 10) === id) {
								item = currentKpiSavedItems[i];
								break;
							}
						}
						if (!item) return;
						startKpiResultEdit(item);
					});

					$(document).on('click', '.pm-kpi-result-cancel-edit', function(e){
						e.preventDefault();
						resetKpiResultEntryFormOnly();
					});

					$(document).on('click', '.btn-kpi-result-saved-delete', function(){
						var id = parseInt($(this).attr('data-result-id') || '0', 10) || 0;
						if (!id) return;
						var doDelete = function(){
							var pid = ($('#kpiResultProjectId').val() || '').toString();
							var kpiId = ($('#kpiResultProjectKpiId').val() || '').toString();
							$.ajax({
								url: '?page=project_manage&op=delete_kpi_result_ajax',
								method: 'POST',
								data: { project_id: pid, project_kpi_id: kpiId, result_id: id },
								dataType: 'text'
							}).done(function(respText){
								var r = null;
								try { r = JSON.parse(respText); } catch(err) { r = null; }
								if (r && (r.ok === 1 || r.ok === true)) {
									if (parseInt($('#kpiResultEditId').val() || '0', 10) === id) {
										resetKpiResultEntryFormOnly();
									}
									loadKpiResultSavedList();
									pmRefreshKpiGoalTable();
									if (window.Swal && Swal.fire) {
										Swal.fire({ icon: 'success', title: 'ลบสำเร็จ', timer: 1200, showConfirmButton: false });
									}
								} else {
									var msg = (r && (r.msg || r.message)) ? (r.msg || r.message) : 'ลบไม่สำเร็จ';
									if (window.Swal && Swal.fire) Swal.fire({ icon: 'error', title: msg, confirmButtonText: 'ตกลง' });
									else alert(msg);
								}
							}).fail(function(){
								if (window.Swal && Swal.fire) Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ', confirmButtonText: 'ตกลง' });
								else alert('เชื่อมต่อไม่สำเร็จ');
							});
						};
						if (window.Swal && Swal.fire) {
							Swal.fire({
								icon: 'warning',
								title: 'ยืนยันการลบ?',
								text: 'ต้องการลบข้อมูลรายการนี้หรือไม่',
								showCancelButton: true,
								confirmButtonText: 'ลบ',
								cancelButtonText: 'ยกเลิก',
								confirmButtonColor: '#dc2626'
							}).then(function(res){ if (res && res.isConfirmed) doDelete(); });
						} else if (confirm('ต้องการลบข้อมูลรายการนี้หรือไม่?')) {
							doDelete();
						}
					});

					$('#btnKpiResultAddEntry').on('click', function(){
						addKpiResultEntryRow('', '');
					});

					$(document).on('click', '.pm-kpi-result-entry-remove', function(){
						var $wrap = $('#kpiResultEntriesWrap');
						var $row = $(this).closest('.pm-kpi-result-entry-row');
						if ($wrap.find('.pm-kpi-result-entry-row').length <= 1) {
							clearKpiResultEntryRow($row);
							syncKpiResultPlanHighlights();
							return;
						}
						$row.remove();
						refreshKpiResultEntryLabels();
						syncKpiResultPlanHighlights();
					});

					$(document).on('change', '.kpi-result-entry-month', function(){
						syncKpiResultPlanHighlights();
					});

					$(document).on('click', '#kpiResultPlanGrid .pm-kpi-result-plan-cell', function(){
						var monthVal = ($(this).attr('data-month') || '').toString().trim();
						if (!monthVal) return;
						ensureKpiResultEntryForMonth(monthVal);
						syncKpiResultPlanHighlights();
					});

					$(document).on('change', '.kpi-result-entry-files', function(){
						showKpiResultEntryFileNames(this);
					});

					$form.on('submit', function(e){
						e.preventDefault();
						var editId = parseInt($('#kpiResultEditId').val() || '0', 10) || 0;
						var entries = [];
						try {
							entries = collectKpiResultEntries();
						} catch (err) {
							var msg = 'กรุณาตรวจสอบข้อมูล';
							if (err && err.type === 'month') msg = 'กรุณาเลือกเดือนในรายการที่ ' + err.row;
							else if (err && err.type === 'amount') msg = 'กรุณากรอกจำนวนในรายการที่ ' + err.row;
							else if (err && err.type === 'dup') msg = 'ห้ามเลือกเดือนซ้ำ (รายการที่ ' + err.row + ')';
							if (window.Swal && Swal.fire) Swal.fire({ icon: 'warning', title: msg, confirmButtonText: 'ตกลง' });
							else alert(msg);
							return false;
						}
						if (!entries.length) {
							if (window.Swal && Swal.fire) Swal.fire({ icon: 'warning', title: 'กรุณาเพิ่มอย่างน้อย 1 เดือน', confirmButtonText: 'ตกลง' });
							else alert('กรุณาเพิ่มอย่างน้อย 1 เดือน');
							return false;
						}
						var fd = new FormData();
						fd.append('project_id', ($('#kpiResultProjectId').val() || '').toString());
						fd.append('project_kpi_id', ($('#kpiResultProjectKpiId').val() || '').toString());
						fd.append('years_select', ($('#kpiResultYearsSelect').val() || '').toString());
						var ajaxUrl = '?page=project_manage&op=save_kpi_result_ajax';
						if (editId > 0) {
							if (entries.length !== 1) {
								if (window.Swal && Swal.fire) Swal.fire({ icon: 'warning', title: 'แก้ไขได้ครั้งละ 1 รายการ', confirmButtonText: 'ตกลง' });
								else alert('แก้ไขได้ครั้งละ 1 รายการ');
								return false;
							}
							ajaxUrl = '?page=project_manage&op=update_kpi_result_ajax';
							fd.append('result_id', String(editId));
							fd.append('result_month', entries[0].month);
							fd.append('result_amount', entries[0].amount);
							fd.append('result_detail', entries[0].detail);
							var inpEdit = $('#kpiResultEntriesWrap .pm-kpi-result-entry-row').first().find('.kpi-result-entry-files')[0];
							if (inpEdit && inpEdit.files) {
								for (var fi = 0; fi < inpEdit.files.length; fi++) {
									fd.append('result_files[]', inpEdit.files[fi]);
								}
							}
						} else {
							fd.append('result_entries', JSON.stringify(entries));
							$('#kpiResultEntriesWrap .pm-kpi-result-entry-row').each(function(){
								var fileKey = ($(this).attr('data-entry-key') || '').toString().trim();
								var inp = $(this).find('.kpi-result-entry-files')[0];
								if (!fileKey || !inp || !inp.files) return;
								for (var i = 0; i < inp.files.length; i++) {
									fd.append('result_files[' + fileKey + '][]', inp.files[i]);
								}
							});
						}
						var $btn = $form.find('button[type="submit"]');
						$btn.prop('disabled', true);
						$.ajax({
							url: ajaxUrl,
							method: 'POST',
							data: fd,
							processData: false,
							contentType: false,
							dataType: 'text'
						}).done(function(respText){
							var r = null;
							try { r = JSON.parse(respText); } catch(err) { r = null; }
							if (r && (r.ok === 1 || r.ok === true)) {
								kpiResultAfterSaveSuccess(r);
							} else {
								var msg = (r && (r.msg || r.message)) ? (r.msg || r.message) : 'บันทึกไม่สำเร็จ';
								if (window.Swal && Swal.fire) Swal.fire({ icon: 'error', title: msg, confirmButtonText: 'ตกลง' });
								else alert(msg);
							}
						}).fail(function(){
							if (window.Swal && Swal.fire) Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ', confirmButtonText: 'ตกลง' });
							else alert('เชื่อมต่อไม่สำเร็จ');
						}).always(function(){
							$btn.prop('disabled', false);
						});
						return false;
					});

					$modal.on('hidden.bs.modal', function(){
						resetKpiResultForm();
					});
				})();
				</script>
				<?php endif; ?>
				<?php endif; ?>
				<?php if ($edit_project_id > 0 && !empty($consistency_type_list)): ?>
				<!-- Modal ความสอดคล้อง: อยู่นอก form หลัก (HTML ห้ามซ้อน form) -->
				<div class="modal fade modal-lg" id="modalConsistencyAdd" tabindex="-1">
					<div class="modal-dialog modal-lg">
						<form id="form-consistency-kpi" method="POST" action="?page=project_manage&op=save_data_consistency_kpi_project">
							<input type="hidden" name="ajax" value="1">
							<div class="modal-content">
