				</div>
				<script>
				(function(){
					var projectId = <?= (int)$edit_project_id ?>;
					var yearValStatic = <?= json_encode((string)$years_select, JSON_UNESCAPED_UNICODE) ?>;
					var sideByType = <?= json_encode($consistency_side_by_type, JSON_UNESCAPED_UNICODE) ?>;
					var soByType = <?= json_encode($consistency_so_by_type, JSON_UNESCAPED_UNICODE) ?>;
					var apBySo = <?= json_encode($consistency_ap_by_so, JSON_UNESCAPED_UNICODE) ?>;
					var allAps = <?= json_encode(array_values(array_map(static function ($ap) {
						return ['id' => (string)($ap['id'] ?? ''), 'name' => trim((string)($ap['name'] ?? ''))];
					}, $consistency_ap_list)), JSON_UNESCAPED_UNICODE) ?>;
					var savedSets = <?= json_encode($consistency_saved_sets, JSON_UNESCAPED_UNICODE) ?>;
					var setState = [];
					var kpiUrl = 'get_kpi.php';

					function consistencyYear(){
						var ySel = document.getElementById('year_project_select');
						var fromSel = ySel ? String(ySel.value || '').trim() : '';
						if (fromSel) return fromSel;
						var hid = document.querySelector('#form-consistency-kpi input[name="years_select"]');
						var fromHid = hid ? String(hid.value || '').trim() : '';
						return fromHid || String(yearValStatic || '').trim();
					}
					function yearScopedAps(){
						var map = {};
						Object.keys(apBySo || {}).forEach(function(soKey){
							(apBySo[soKey] || []).forEach(function(ap){
								var id = String((ap && ap.id) || '');
								if (!id || map[id]) return;
								map[id] = { id: id, name: String((ap && ap.name) || '') };
							});
						});
						var list = Object.keys(map).map(function(k){ return map[k]; });
						return list.length ? list : (allAps || []);
					}
					function esc(s){
						return String(s == null ? '' : s)
							.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
							.replace(/"/g,'&quot;');
					}
					function fillSelect(sel, items, selected, placeholder){
						if (!sel) return;
						var html = '<option value="">' + esc(placeholder || '- เลือก -') + '</option>';
						(items || []).forEach(function(it){
							var id = String(it.id || '');
							var name = String(it.name || '');
							if (!id) return;
							html += '<option value="'+esc(id)+'"'+(selected && String(selected)===id ? ' selected' : '')+'>'+esc(name)+'</option>';
						});
						sel.innerHTML = html;
					}
					function childKind(){
						var tEl = document.getElementById('selectConsistencyType');
						if (!tEl) return '';
						var opt = tEl.options[tEl.selectedIndex];
						return opt ? String(opt.getAttribute('data-child-kind') || '').trim() : '';
					}
					function typeId(){
						var tEl = document.getElementById('selectConsistencyType');
						return tEl ? String(tEl.value || '').trim() : '';
					}
					function typeGroup(){
						var tEl = document.getElementById('selectConsistencyType');
						if (!tEl) return 'other';
						var opt = tEl.options[tEl.selectedIndex];
						if (!opt || !tEl.value) return 'other';
						var g = String(opt.getAttribute('data-type-group') || '').trim();
						if (g && g !== 'other') return g;
						var name = String(opt.text || '');
						if (/กลยุทธ์|กลยุทธ|ยุทธศาสตร์/.test(name)) return 'strategy';
						if (/พันธกิจ/.test(name)) return 'mission';
						if (/พัฒนา/.test(name)) return 'develop';
						if (g) return g;
						if (childKind() === 'so') return 'strategy';
						return 'other';
					}
					function setCopy(isPrimary){
						var g = typeGroup();
						var role = isPrimary ? 'หลัก' : 'ร่วม';
						var out = {
							level2Label: isPrimary ? 'ด้าน/แผนปฏิบัติการ (AP)' : 'ด้าน/แผนปฏิบัติการ (AP) ร่วม',
							hint: '',
							addBtn: '+ เพิ่มรายการและตัวชี้วัด',
							need: 'กรุณาเลือกรายการ',
							placeholder: '- เลือก -'
						};
						if (g === 'strategy') {
							out.level2Label = isPrimary ? 'แผนปฏิบัติการ (AP)' : 'แผนปฏิบัติการ (AP) ร่วม';
							out.hint = 'เลือกแผนปฏิบัติการ' + role + 'ที่โครงการมีส่วนสนับสนุนให้บรรลุเป้าหมาย';
							out.addBtn = '+ เพิ่มแผนปฏิบัติการและตัวชี้วัด';
							out.need = 'กรุณาเลือกแผนปฏิบัติการ (AP)';
							out.placeholder = '- เลือก AP -';
						} else if (g === 'mission') {
							out.level2Label = isPrimary ? 'พันธกิจที่สนับสนุน' : 'พันธกิจที่สนับสนุนร่วม';
							out.hint = 'เลือกพันธกิจ' + role + 'ที่โครงการมีส่วนสนับสนุน';
							out.addBtn = '+ เพิ่มพันธกิจที่สนับสนุนและตัวชี้วัด';
							out.need = 'กรุณาเลือกพันธกิจที่สนับสนุน';
							out.placeholder = '- เลือกพันธกิจ -';
						} else if (g === 'develop') {
							out.level2Label = isPrimary ? 'ด้านที่พัฒนา' : 'ด้านที่พัฒนาร่วม';
							out.hint = 'เลือกด้าน' + role + 'ที่โครงการมุ่งให้เกิดการเปลี่ยนแปลงหรือปรับปรุง';
							out.addBtn = '+ เพิ่มด้านที่พัฒนาและตัวชี้วัด';
							out.need = 'กรุณาเลือกด้านที่พัฒนา';
							out.placeholder = '- เลือกด้าน -';
						} else if (childKind() === 'so') {
							out.level2Label = isPrimary ? 'แผนปฏิบัติการ (AP)' : 'แผนปฏิบัติการ (AP) ร่วม';
							out.hint = 'เลือกแผนปฏิบัติการ' + role + 'ที่โครงการมีส่วนสนับสนุนให้บรรลุเป้าหมาย';
							out.addBtn = '+ เพิ่มแผนปฏิบัติการและตัวชี้วัด';
							out.need = 'กรุณาเลือกแผนปฏิบัติการ (AP)';
							out.placeholder = '- เลือก AP -';
						}
						return out;
					}
					window.pmConsistencyUiLabels = function(name, kind){
						var g = 'other';
						var n = String(name || '');
						var k = String(kind || '');
						if (/กลยุทธ์|กลยุทธ|ยุทธศาสตร์/.test(n)) g = 'strategy';
						else if (/พันธกิจ/.test(n)) g = 'mission';
						else if (/พัฒนา/.test(n)) g = 'develop';
						else if (k === 'so') g = 'strategy';
						var L = {
							typeLabel: 'กรอบแผนของโครงการ',
							level2Label: 'ด้าน/แผนปฏิบัติการ (AP)',
							group: g
						};
						if (g === 'mission') L.level2Label = 'พันธกิจที่สนับสนุน';
						else if (g === 'develop') L.level2Label = 'ด้านที่พัฒนา';
						else if (g === 'strategy') L.level2Label = 'แผนปฏิบัติการ (AP)';
						return L;
					};
					function cloneSavedSets(){
						return (savedSets || []).map(function(s){
							return {
								code_ap: String(s.code_ap || ''),
								code_side: String(s.code_side || ''),
								kpis: Array.isArray(s.kpis) ? s.kpis.slice() : []
							};
						});
					}
					function optionHtml(items, selected, placeholder){
						var html = '<option value="">' + esc(placeholder || '- เลือก -') + '</option>';
						(items || []).forEach(function(it){
							var id = String(it.id || '');
							var name = String(it.name || '');
							if (!id) return;
							html += '<option value="'+esc(id)+'"'+(selected && String(selected)===id ? ' selected' : '')+'>'+esc(name)+'</option>';
						});
						return html;
					}
					function renderSets(){
						var wrap = document.getElementById('boxConsistencySets');
						var addWrap = document.getElementById('boxConsistencyAddWrap');
						var addBtn = document.getElementById('btnAddConsistencySet');
						if (!wrap) return;
						var tid = typeId();
						var kind = childKind();
						if (!tid) {
							wrap.innerHTML = '<div class="alert alert-info text-center mb-0">กรุณาเลือกกรอบแผนของโครงการก่อน</div>';
							if (addWrap) addWrap.style.display = 'none';
							return;
						}
						if (!setState.length) setState = [{ code_ap: '', code_side: '', kpis: [] }];
						var copy0 = setCopy(true);
						if (addBtn) addBtn.textContent = copy0.addBtn;
						if (addWrap) addWrap.style.display = 'block';
						var itemsBase = (kind === 'so') ? yearScopedAps() : (sideByType[tid] || []);
						var html = '';
						setState.forEach(function(st, idx){
							var copy = setCopy(idx === 0);
							var selName = (kind === 'so')
								? 'sets['+idx+'][code_ap]'
								: 'sets['+idx+'][code_side]';
							var selVal = (kind === 'so') ? (st.code_ap || '') : (st.code_side || '');
							var items = itemsBase.slice();
							if (selVal && !items.some(function(it){ return String(it.id) === String(selVal); })) {
								items.push({ id: String(selVal), name: 'รายการที่เลือกไว้' });
							}
							html += '<div class="pm-cons-set" data-set-index="'+idx+'">';
							html += '<div class="pm-cons-set-head">';
							html += '<div><label class="font-weight-bold mb-0">'+esc(copy.level2Label)+'</label>';
							if (copy.hint) html += '<div class="pm-cons-hint">'+esc(copy.hint)+'</div>';
							html += '</div>';
							if (idx > 0) {
								html += '<button type="button" class="pm-cons-set-remove" data-remove-set="'+idx+'">ลบชุดนี้</button>';
							}
							html += '</div>';
							html += '<select class="form-control mb-3 pm-cons-set-select" name="'+esc(selName)+'" data-set-index="'+idx+'">'+optionHtml(items, selVal, copy.placeholder)+'</select>';
							html += '<label class="font-weight-bold">ตัวชี้วัด</label>';
							html += '<div class="border rounded p-3 bg-light pm-cons-kpi-box" data-set-index="'+idx+'"><div class="alert alert-info text-center mb-0">'+esc(copy.need)+'</div></div>';
							html += '</div>';
						});
						wrap.innerHTML = html;
						setState.forEach(function(st, idx){ loadSetKPI(idx); });
					}
					function loadSetKPI(idx){
						var box = document.querySelector('.pm-cons-kpi-box[data-set-index="'+idx+'"]');
						if (!box) return;
						var st = setState[idx] || { code_ap: '', code_side: '', kpis: [] };
						var typeVal = typeId();
						var kind = childKind();
						var copy = setCopy(idx === 0);
						if (!typeVal) {
							box.innerHTML = '<div class="alert alert-info text-center mb-0">กรุณาเลือกกรอบแผนของโครงการก่อน</div>';
							return;
						}
						var apVal = kind === 'so' ? String(st.code_ap || '') : '';
						var sideVal = kind === 'side' ? String(st.code_side || '') : '';
						if (kind === 'so' && !apVal) {
							box.innerHTML = '<div class="alert alert-info text-center mb-0">'+esc(copy.need)+'</div>';
							return;
						}
						if (kind === 'side' && !sideVal) {
							box.innerHTML = '<div class="alert alert-info text-center mb-0">'+esc(copy.need)+'</div>';
							return;
						}
						box.innerHTML = '<div class="alert alert-info text-center mb-0">กำลังโหลดตัวชี้วัด...</div>';
						var yearNow = consistencyYear();
						var yearHid = document.querySelector('#form-consistency-kpi input[name="years_select"]');
						if (yearHid && yearNow) yearHid.value = yearNow;
						$.ajax({
							url: kpiUrl,
							type: 'POST',
							dataType: 'json',
							data: {
								project_id: projectId,
								type: typeVal,
								so: '',
								ap: apVal,
								side: sideVal,
								year: yearNow || '',
								selected_ids: JSON.stringify(st.kpis || [])
							}
						}).done(function(res){
							var html = '';
							if (!res || !res.length) {
								html = '<div class="alert alert-warning mb-0">ไม่พบตัวชี้วัดตามประเภท/รายการที่เลือก</div>';
							} else {
								res.forEach(function(item){
									html += '<div class="form-check mb-1">'
										+ '<input type="checkbox" name="sets['+idx+'][kpi_list][]" value="'+esc(item.kpi_id)+'" class="form-check-input" '+(item.checked?'checked':'')+'>'
										+ '<label class="form-check-label">'+esc(item.kpi_name||'')+'</label>'
										+ '</div>';
								});
							}
							box.innerHTML = html;
						}).fail(function(){
							box.innerHTML = '<div class="alert alert-danger mb-0">โหลดตัวชี้วัดไม่สำเร็จ</div>';
						});
					}
					function captureSetKpis(){
						setState.forEach(function(st, idx){
							var ids = [];
							document.querySelectorAll('.pm-cons-kpi-box[data-set-index="'+idx+'"] input[type="checkbox"]:checked').forEach(function(cb){
								ids.push(String(cb.value || ''));
							});
							st.kpis = ids;
						});
					}
					window.pmConsistencySnapshot = function(){
						captureSetKpis();
						var kind = childKind();
						var typeText = '';
						var tEl = document.getElementById('selectConsistencyType');
						if (tEl && tEl.selectedIndex >= 0) {
							typeText = String(tEl.options[tEl.selectedIndex].text || '').trim();
							if (/^-\s*เลือก/.test(typeText)) typeText = '';
						}
						var sets = [];
						setState.forEach(function(st, idx){
							var copy = setCopy(idx === 0);
							var sel = document.querySelector('.pm-cons-set-select[data-set-index="'+idx+'"]');
							var name = '';
							if (sel && sel.selectedIndex >= 0) {
								name = String(sel.options[sel.selectedIndex].text || '').trim();
								if (!sel.value || /^-\s*เลือก/.test(name)) name = '';
							}
							var kpis = [];
							document.querySelectorAll('.pm-cons-kpi-box[data-set-index="'+idx+'"] input[type="checkbox"]:checked').forEach(function(cb){
								var lab = cb.closest('.form-check');
								var txt = lab ? String((lab.querySelector('label') || {}).textContent || '').trim() : '';
								if (txt) kpis.push(txt);
							});
							sets.push({ label: copy.level2Label, name: name, kpis: kpis, hasVal: !!(sel && sel.value) });
						});
						return { typeText: typeText, kind: kind, group: typeGroup(), sets: sets };
					};
					window.pmConsistencyValidate = function(){
						if (!typeId()) return 'กรุณาเลือกกรอบแผนของโครงการก่อน';
						var snap = window.pmConsistencySnapshot();
						if (!snap.sets.length) return 'กรุณาเพิ่มรายการอย่างน้อย 1 ชุด';
						for (var i = 0; i < snap.sets.length; i++) {
							if (!snap.sets[i].hasVal) return setCopy(i === 0).need;
						}
						return '';
					};
					var typeEl = document.getElementById('selectConsistencyType');
					if (typeEl) {
						typeEl.addEventListener('change', function(){
							setState = [{ code_ap: '', code_side: '', kpis: [] }];
							renderSets();
						});
					}
					var setsWrap = document.getElementById('boxConsistencySets');
					if (setsWrap) {
						setsWrap.addEventListener('change', function(e){
							var sel = e.target && e.target.classList && e.target.classList.contains('pm-cons-set-select') ? e.target : null;
							if (!sel) return;
							var idx = parseInt(sel.getAttribute('data-set-index') || '0', 10);
							if (!setState[idx]) return;
							if (childKind() === 'so') {
								setState[idx].code_ap = String(sel.value || '');
								setState[idx].code_side = '';
							} else {
								setState[idx].code_side = String(sel.value || '');
								setState[idx].code_ap = '';
							}
							setState[idx].kpis = [];
							loadSetKPI(idx);
						});
						setsWrap.addEventListener('click', function(e){
							var btn = e.target && e.target.closest ? e.target.closest('[data-remove-set]') : null;
							if (!btn) return;
							e.preventDefault();
							captureSetKpis();
							var idx = parseInt(btn.getAttribute('data-remove-set') || '0', 10);
							if (idx > 0) {
								setState.splice(idx, 1);
								renderSets();
							}
						});
					}
					var addBtn = document.getElementById('btnAddConsistencySet');
					if (addBtn) {
						addBtn.addEventListener('click', function(){
							if (!typeId()) return;
							captureSetKpis();
							setState.push({ code_ap: '', code_side: '', kpis: [] });
							renderSets();
						});
					}
					function bootSets(){
						setState = cloneSavedSets();
						if (!typeId()) setState = [];
						else if (!setState.length) setState = [{ code_ap: '', code_side: '', kpis: [] }];
						renderSets();
					}
					$('#modalConsistencyAdd').on('shown.bs.modal', function(){
						setTimeout(bootSets, 50);
					});
					$(function(){ try { bootSets(); } catch(e) {} });
					window.pmConsistencyRememberSets = function(){
						captureSetKpis();
						savedSets = setState.map(function(st){
							return {
								code_ap: String(st.code_ap || ''),
								code_side: String(st.code_side || ''),
								kpis: Array.isArray(st.kpis) ? st.kpis.slice() : []
							};
						});
					};
					window.pmConsistencyShowBoxes = bootSets;
				})();
				</script>
				<script>
				(function () {
					var $fc = $('#form-consistency-kpi');
					if (!$fc.length) return;
					var consistencyUrl = $fc.attr('action');
					function forceHideConsistencyModal(){
						try { $('#modalConsistencyAdd').modal('hide'); } catch(e) {}
						try {
							var m = document.getElementById('modalConsistencyAdd');
							if (!m) return;
							m.classList.remove('show');
							m.style.display = 'none';
							m.setAttribute('aria-hidden', 'true');
							document.body.classList.remove('modal-open');
							var backs = document.querySelectorAll('.modal-backdrop');
							backs.forEach(function(b){ try { b.parentNode && b.parentNode.removeChild(b); } catch(e){} });
						} catch(e) {}
						setTimeout(function(){ try { $('#modalConsistencyAdd').modal('hide'); } catch(e) {} }, 50);
					}
					$fc.on('submit', function (e) {
						e.preventDefault();
						var errMsg = (typeof window.pmConsistencyValidate === 'function') ? window.pmConsistencyValidate() : '';
						if (errMsg) {
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'warning', title: 'ข้อมูลไม่ครบ', text: errMsg });
							} else {
								alert(errMsg);
							}
							return;
						}
						var fd = new FormData(this);
						fd.set('ajax', '1');
						fd.set('code_so', '');
						var $sub = $fc.find('button[type="submit"]');
						$sub.prop('disabled', true);
						$.ajax({
							url: consistencyUrl,
							type: 'POST',
							data: fd,
							processData: false,
							contentType: false,
							dataType: 'json'
						}).done(function (res) {
							if (res && res.ok === 1) {
								// อัปเดต summary ในหน้าเดิม (ไม่ reload)
								try {
									var snap = (typeof window.pmConsistencySnapshot === 'function') ? window.pmConsistencySnapshot() : { typeText: '', sets: [] };
									var typeText = snap.typeText || '';
									var consUi = (typeof window.pmConsistencyUiLabels === 'function')
										? window.pmConsistencyUiLabels(typeText, snap.kind)
										: { typeLabel: 'กรอบแผนของโครงการ', level2Label: 'ด้าน/แผนปฏิบัติการ (AP)' };
									var sdgs = [];
									$('#boxConsistencySDGs input[name="consistency_detail[]"]:checked').each(function(){
										var $row = $(this).closest('.form-check');
										var label = ($row.find('label').text() || '').trim();
										if (label) sdgs.push(label);
									});
									var html = '';
									html += '<div class="pm-consistency-rows">';
									html += '  <div class="pm-consistency-row">';
									html += '    <div class="pm-consistency-label">' + $('<div/>').text((consUi.typeLabel || 'กรอบแผนของโครงการ') + ' :').html() + '</div>';
									html += '    <div class="pm-consistency-value">' + $('<div/>').text(typeText || '-').html() + '</div>';
									html += '  </div>';
									var joinedLevel2 = [];
									var joinedKpis = [];
									var seenKpi = {};
									(snap.sets || []).forEach(function(st){
										var nm = String(st.name || '').trim();
										if (nm) joinedLevel2.push(nm);
										(st.kpis || []).forEach(function(n){
											n = String(n || '').trim();
											if (!n || seenKpi[n]) return;
											seenKpi[n] = true;
											joinedKpis.push(n);
										});
									});
									html += '  <div class="pm-consistency-row">';
									html += '    <div class="pm-consistency-label">' + $('<div/>').text((consUi.level2Label || 'ด้าน/แผนปฏิบัติการ (AP)') + ' :').html() + '</div>';
									html += '    <div class="pm-consistency-value">' + $('<div/>').text(joinedLevel2.length ? joinedLevel2.join(', ') : '-').html() + '</div>';
									html += '  </div>';
									html += '  <div class="pm-consistency-row">';
									html += '    <div class="pm-consistency-label">ตัวชี้วัดเชิงพันธกิจ/ตัวชี้วัดเชิงกลยุทธ์ (KR) :</div>';
									html += '    <div class="pm-consistency-value">' + $('<div/>').text(joinedKpis.length ? joinedKpis.join(', ') : '-').html() + '</div>';
									html += '  </div>';
									if (window.PM_SDGS_ENABLED) {
									html += '  <div class="pm-consistency-row">';
									html += '    <div class="pm-consistency-label">SDGs :</div>';
									html += '    <div class="pm-consistency-value">';
									if (sdgs.length) {
										sdgs.forEach(function(n){
											html += '<div class="pm-subline">- ' + $('<div/>').text(n).html() + '</div>';
										});
									} else {
										html += '-';
									}
									html += '    </div>';
									html += '  </div>';
									}
									html += '</div>';
									var hasSet = (snap.sets || []).some(function(st){ return !!(st.name || (st.kpis && st.kpis.length)); });
									if (!hasSet && !sdgs.length && !typeText) {
										html = '<small class="text-muted">คลิกปุ่ม เพิ่ม/แก้ไข เพื่อระบุแผน ด้าน และตัวชี้วัดของคณะที่โครงการมีส่วนสนับสนุน</small>';
									}
									$('#consistency-summary').html(html);

									var $btn = $('button[data-target="#modalConsistencyAdd"]');
									if ($btn.length) {
										var hasAny = !!(hasSet || sdgs.length || (typeText && typeText !== '-'));
										$btn.removeClass('btn-primary btn-warning text-dark btn-pm-edit-orange');
										$btn.find('i').removeClass('fa-plus fa-edit');
										$btn.contents().filter(function(){ return this.nodeType === 3; }).remove();
										if (hasAny) {
											$btn.addClass('btn-pm-edit-orange');
											$btn.find('i').addClass('fa fa-edit mr-1');
											$btn.append(' แก้ไข');
										} else {
											$btn.addClass('btn-primary');
											$btn.find('i').addClass('fa fa-plus mr-1');
											$btn.append(' เพิ่มข้อมูล');
										}
									}
								} catch(e) {}

								try {
									var _snap = (typeof window.pmConsistencySnapshot === 'function') ? window.pmConsistencySnapshot() : { sets: [] };
									var _t = String($('#selectConsistencyType').val() || '').trim();
									var _hasCons = !!(_t || (_snap.sets || []).some(function(st){ return !!st.hasVal || (st.kpis && st.kpis.length); }) || $('#boxConsistencySDGs input[name="consistency_detail[]"]:checked').length);
									if (typeof window.pmRefreshConsistencyStepper === 'function') {
										window.pmRefreshConsistencyStepper(_hasCons);
									}
								} catch (eStep) {}
								try {
									if (typeof window.pmConsistencyRememberSets === 'function') {
										window.pmConsistencyRememberSets();
									}
								} catch (eMem) {}

								// ปิด modal + แจ้งสำเร็จ
								forceHideConsistencyModal();
								if (typeof Swal !== 'undefined') {
									Swal.fire({ icon: 'success', title: 'บันทึกความสอดคล้องแล้ว', showConfirmButton: false, timer: 1100 });
								}
							} else {
								var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
								if (typeof Swal !== 'undefined') {
									Swal.fire({ icon: 'error', title: 'ผิดพลาด', text: msg });
								} else {
									alert(msg);
								}
							}
						}).fail(function (xhr) {
							var msg = 'เกิดข้อผิดพลาด';
							try {
								var j = JSON.parse(xhr.responseText || '{}');
								if (j && j.msg) { msg = j.msg; }
							} catch (err) { /* ignore */ }
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'error', title: 'ผิดพลาด', text: msg });
							} else {
								alert(msg);
							}
						}).always(function () {
							$sub.prop('disabled', false);
						});
					});
					// ปุ่มลบความสอดคล้องถูกเอาออกตาม requirement
				})();
				</script>

