		<script>
		(function(){
				var projectId = <?= (int)$edit_project_id ?>;
			if (!projectId) return;

			window.pmWeightIsHundredJs = function (w) {
				return Math.abs((parseFloat(w) || 0) - 100) <= 0.05;
			};
			window.pmRenderWeightSumAlert = function ($wrap, warningMsg) {
				if (!$wrap || !$wrap.length) return;
				if (!warningMsg) {
					$wrap.empty();
					return;
				}
				var esc = function (s) {
					return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
				};
				$wrap.html(
					'<div class="alert alert-warning py-2 mb-0 text-90 pm-weight-sum-alert">' +
					'<i class="fa fa-exclamation-triangle mr-1 text-danger"></i>' +
					'<span class="text-danger">' + esc(warningMsg) + '</span></div>'
				);
			};
			window.pmShowKpiWeightBanner = function (warningMsg) {
				var $w = $('#kpi-weight-alert-wrap');
				if (!$w.length) {
					$w = $('<div id="kpi-weight-alert-wrap" class="mb-2"></div>');
					$('#kpi-goal-table-wrap').before($w);
				}
				pmRenderWeightSumAlert($w, warningMsg);
			};
			window.pmShowActivityWeightBanner = function (warningMsg) {
				var $w = $('#activity-weight-alert-wrap');
				if (!$w.length) {
					$w = $('<div id="activity-weight-alert-wrap" class="mb-2"></div>');
					$('#activity-table-wrap').before($w);
				}
				pmRenderWeightSumAlert($w, warningMsg);
			};
			window.pmShowBudgetItemsBanner = function (warningMsg) {
				var $w = $('#budget-items-alert-wrap');
				if (!$w.length) {
					$w = $('<div id="budget-items-alert-wrap" class="mb-2"></div>');
					$('#budget-table-wrap').before($w);
				}
				pmRenderWeightSumAlert($w, warningMsg);
			};
			window.pmCheckActivityBudgetBeforeSave = function (activityId, newTotal, excludeItemId) {
				activityId = parseInt(activityId || '0', 10);
				newTotal = parseFloat(newTotal) || 0;
				excludeItemId = parseInt(excludeItemId || '0', 10);
				if (!activityId) return null;
				var $actRow = $('#budget-table-wrap tr.pm-budget-activity-row[data-activity-id="' + activityId + '"]');
				if (!$actRow.length) return null;
				var limit = parseFloat($actRow.attr('data-budget-limit') || '0') || 0;
				if (limit <= 0) return null;
				var itemsSum = 0;
				$('#budget-table-wrap tr.pm-budget-item-row[data-activity-id="' + activityId + '"]').each(function () {
					var iid = parseInt($(this).attr('data-item-id') || '0', 10);
					if (excludeItemId > 0 && iid === excludeItemId) return;
					var txt = ($(this).find('td').eq(1).find('.font-weight-bold').first().text() || '').replace(/,/g, '').trim();
					var v = parseFloat(txt);
					if (!isNaN(v)) itemsSum += v;
				});
				var projected = itemsSum + newTotal;
				if (projected <= (limit + 0.0001)) return null;
				return 'รวมรายการค่าใช้จ่ายของกิจกรรมนี้ต้องไม่เกินงบประมาณกิจกรรม (งบประมาณ '
					+ limit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })
					+ ' บาท, ปัจจุบันรวม '
					+ projected.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })
					+ ' บาท)';
			};
				var stNow = String($('#status_project_now').val() || '0');
				var isPlanWorkflowEditable = !!window.PM_ANNUAL_PLAN_PARTIAL;
				var isSubmitted = (stNow !== '0' && stNow !== '8' && stNow !== '4');
				if (window.PM_CAN_FILL_PROJECT_RESULTS && (stNow === '1' || stNow === '8')) {
					isSubmitted = false;
				}
				if (window.PM_INCLUDE_MEETING_LOCK) {
					isSubmitted = true;
					isPlanWorkflowEditable = false;
				} else if (window.PM_PLAN_FIX_RESUBMIT_LOCK || window.PM_OPERATE_REPLY_LOCK) {
					isSubmitted = true;
					isPlanWorkflowEditable = false;
				} else if (window.PM_PLAN_ADMIN) {
					isSubmitted = false;
					isPlanWorkflowEditable = false;
				}

			function applyPlanWorkflowState(){
				if (!isPlanWorkflowEditable) return;
				$('.pm-submit-draft').addClass('d-none');
				$('#submitStatusBadgeBottom').addClass('d-none');
				$('.pm-wizard-request-operate').removeClass('d-none');

				// ส่วนที่ 1: อนุญาตเฉพาะผู้ประสานงานและพื้นที่ดำเนินการ
				var $m = $('#modalGeneralInfo');
				// NOTE: requirement ล่าสุดต้องให้แก้ "ระยะเวลาดำเนินโครงการ" ได้ (เดือน/ปี เริ่มต้น-สิ้นสุด)
				// ดังนั้นอย่าปิด #project_start_date/#project_end_date ในโหมดนี้
				$m.find('select[name="head_staff"], input[name="head_phone"], select[name="code_unit"], select[name="code_nature"], select[name="code_type"], select[name="code_budget"], input[name="budget_other"], select[name="participant_staff[]"], input[name="participant_phone[]"], select[name="code_unit_co[]"], input[name="code_unit_co_other[]"]')
					.prop('disabled', true).prop('readonly', true);
				$m.find('.btn-add-participant, .btn-add-unit-co, .btn-remove-participant, .btn-remove-unit-co').prop('disabled', true).addClass('disabled');
				$m.find('select[name="coordinator_staff"], input[name="coordinator_phone"], textarea[name="location"], textarea[name="general_note"], #project_start_date, #project_end_date').prop('disabled', false).prop('readonly', false);

				// ส่วนที่ 3: อนุญาตเฉพาะ reson/result
				$('.btn-section2-edit').each(function(){
					var f = String($(this).data('field') || '');
					var ok = (f === 'reson' || f === 'result');
					$(this).prop('disabled', !ok).toggleClass('disabled', !ok);
				});
				$('[data-kpi-goal-action], .btn-kpi-goal-edit, .btn-kpi-goal-delete').prop('disabled', true).addClass('disabled');

				// ส่วนที่ 2 ความสอดคล้อง / ส่วนที่ 6: ไม่อนุญาตแก้ไข
				$('button[data-target="#modalConsistencyAdd"]').addClass('d-none').prop('disabled', true);
				$('[data-action="open-s6-modal"]').prop('disabled', true).addClass('disabled');
				$('[data-action="budget-plan"]').prop('disabled', true).addClass('disabled');

				// ส่วนที่ 4/5/7: อนุญาตเพิ่ม-แก้ไขกิจกรรม, รายการค่าใช้จ่าย และไฟล์
				$('#btnAddActivityTop, .pm-activity-edit, .pm-activity-del, [data-action="budget-items"], [data-action="budget-item-edit"], [data-action="budget-item-del"], #btnS7OpenUpload, .pm-s7-file-delete')
					.prop('disabled', false).removeClass('disabled pm-lock-disabled d-none');
			}

			function lockAddEditButtons(){
				var selectors = [
					'#btnToggleHeaderEdit',
					'#general-info-summary button[data-target="#modalGeneralInfo"]',
					'.btn-section2-edit',
					'button[data-target="#modalConsistencyAdd"]',
					'[data-kpi-goal-action="add"]', '[data-kpi-goal-action="edit"]', '[data-kpi-goal-action="delete"]',
					'.btn-kpi-goal-edit', '.btn-kpi-goal-delete',
					'#btnAddActivityTop', '.pm-activity-edit', '.pm-activity-del',
					'[data-action="budget-items"]', '[data-action="budget-item-edit"]', '[data-action="budget-item-del"]', '[data-action="budget-plan"]',
					'[data-action="open-s6-modal"]',
					'#btnS7OpenUpload', '.pm-s7-file-delete',
					'#btnModalSaveGeneral', '#btnSection2ModalSave',
					'#formKpiGoalProject button[type="submit"]',
					'#formActivityProject button[type="submit"]',
					'#formBudgetItem button[type="submit"]',
					'#formBudgetPlan button[type="submit"]',
					'#formSection6 button[type="submit"]',
					'#formProjectFilesUpload button[type="submit"]',
					'button[data-target="#modalKpiGoalProject"]',
					'button[data-target="#modalActivityProject"]',
					'button[data-target="#modalActivityBudgetItems"]',
					'button[data-target="#modalBudgetPlan"]',
					'button[data-target="#modalSection6"]',
					'button[data-target="#modalProjectFilesUpload"]'
				];
				var freezeResults = !!(window.PM_CAN_FILL_PROJECT_RESULTS && (window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE));
				if (!window.PM_CAN_FILL_PROJECT_RESULTS || freezeResults) {
					selectors = selectors.concat([
						'.pm-budget-disburse-open', '.pm-ber-disburse-btn', '.pm-budget-disburse-edit', '.pm-ber-line-edit-btn', '.pm-budget-other-action-create',
						'.btn-kpi-fill-result', '.btn-kpi-edit-result', '.btn-activity-fill-result', '.btn-activity-edit-result',
						'#btnOpenProjectEvaluation', '#btnSaveProjectEvaluation'
					]);
				}
				$(selectors.join(',')).each(function(){
					var $el = $(this);
					if (this.tagName === 'A') {
						$el.addClass('pm-lock-disabled').attr('aria-disabled', 'true').attr('tabindex', '-1');
					} else {
						$el.prop('disabled', true).addClass('disabled pm-lock-disabled');
					}
				});

				// ซ่อนปุ่ม/ไอคอนในส่วนที่ user แจ้งว่ายังเหลือ (งบประมาณ/กิจกรรม)
				$([
					'[data-action="budget-items"]',
					'[data-action="budget-item-edit"]',
					'[data-action="budget-item-del"]',
					'[data-action="budget-plan"]',
					'#btnAddActivityTop',
					'.pm-activity-edit',
					'.pm-activity-del'
				].join(',')).addClass('d-none');
			}
			function isSubmittedNow(){
				if (window.PM_INCLUDE_MEETING_LOCK || window.PM_PLAN_FIX_RESUBMIT_LOCK || window.PM_OPERATE_REPLY_LOCK) return true;
				var v = String($('#status_project_now').val() || '0');
				return (v !== '0' && v !== '8' && v !== '4');
			}

			function applySubmittedState(nextStatus){
				if (window.PM_PLAN_ADMIN && !window.PM_INCLUDE_MEETING_LOCK && !window.PM_PLAN_FIX_RESUBMIT_LOCK && !window.PM_OPERATE_REPLY_LOCK) {
					return;
				}
				if (window.PM_CAN_FILL_PROJECT_RESULTS && !window.PM_INCLUDE_MEETING_LOCK && !window.PM_PLAN_FIX_RESUBMIT_LOCK && !window.PM_OPERATE_REPLY_LOCK) {
					$('#submitStatusBadgeBottom').addClass('d-none');
					$('#submitStatusBadgeTop').removeClass('d-none');
					return;
				}
				isSubmitted = true;
				$('#submitStatusBadgeBottom').addClass('d-none');
				if (window.PM_INCLUDE_MEETING_LOCK) {
					$('#submitStatusBadgeTop').removeClass('d-none');
				} else if (window.PM_PLAN_FIX_RESUBMIT_LOCK || window.PM_OPERATE_REPLY_LOCK) {
					$('#submitStatusBadgeTop').removeClass('d-none');
				} else {
					var st = String(nextStatus || $('#status_project_now').val() || '2');
					if (st !== '2' && st !== '3') {
						st = '2';
					}
					$('#status_project_now').val(st);
					$('#submitStatusBadgeTop').removeClass('d-none');
				}
				$('.pm-wizard').addClass('pm-submitted-lock');
				$('.pm-submit-draft').addClass('d-none');
				$('#btnToggleHeaderEdit, .pm-save-btn').addClass('d-none');
				lockAddEditButtons();
			}
			if (isSubmitted) {
				applySubmittedState();
			} else if (window.PM_CAN_FILL_PROJECT_RESULTS) {
				$('#submitStatusBadgeBottom').addClass('d-none');
				$('#submitStatusBadgeTop').removeClass('d-none');
			}
			applyPlanWorkflowState();

			// กัน event ทุกจุด add/edit/delete เผื่อ element ถูก re-render ใหม่จาก AJAX
			$(document).on('click', [
				'#btnToggleHeaderEdit',
				'#general-info-summary button[data-target="#modalGeneralInfo"]',
				'.btn-section2-edit',
				'button[data-target="#modalConsistencyAdd"]',
				'[data-kpi-goal-action]',
				'#btnAddActivityTop', '.pm-activity-edit', '.pm-activity-del',
				'[data-action="budget-items"]', '[data-action="budget-item-edit"]', '[data-action="budget-item-del"]', '[data-action="budget-plan"]',
				'[data-action="open-s6-modal"]',
				'#btnS7OpenUpload', '.pm-s7-file-delete',
				'.pm-budget-disburse-open', '.pm-ber-disburse-btn', '.pm-budget-disburse-edit', '.pm-ber-line-edit-btn', '.pm-budget-other-action-create',
				'#btnModalSaveGeneral', '#btnSection2ModalSave'
			].join(','), function(e){
				if (window.PM_PLAN_ADMIN && !window.PM_INCLUDE_MEETING_LOCK && !window.PM_PLAN_FIX_RESUBMIT_LOCK && !window.PM_OPERATE_REPLY_LOCK) return;
				var isResultUi = $(this).is('.pm-budget-disburse-open, .pm-ber-disburse-btn, .pm-budget-disburse-edit, .pm-ber-line-edit-btn, .pm-budget-other-action-create');
				if (window.PM_OPERATE_APPROVED && !isResultUi) {
					e.preventDefault();
					e.stopImmediatePropagation();
					return false;
				}
				if ((window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE) && window.PM_CAN_FILL_PROJECT_RESULTS) {
					e.preventDefault();
					e.stopImmediatePropagation();
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon: 'info', title: 'รอตรวจสอบรายงานผล', text: 'ไม่สามารถแก้ไขได้จนกว่าจะถูกตีกลับให้แก้ไข' });
					}
					return false;
				}
				if (isResultUi && window.PM_CAN_FILL_PROJECT_RESULTS) {
					return;
				}
				if (isPlanWorkflowEditable) {
					if ($(this).is('button[data-target="#modalConsistencyAdd"], [data-kpi-goal-action], [data-action="open-s6-modal"], [data-action="budget-plan"]')) {
						e.preventDefault();
						e.stopImmediatePropagation();
						return false;
					}
					var field = String($(this).data('field') || '');
					if (field && field !== 'reson' && field !== 'result') {
						e.preventDefault();
						e.stopImmediatePropagation();
						return false;
					}
				}
				if (!isSubmittedNow()) return;
				e.preventDefault();
				e.stopImmediatePropagation();
				return false;
			});
			$(document).on('submit', [
				'#formKpiGoalProject',
				'#formActivityProject',
				'#formBudgetItem',
				'#formBudgetPlan',
				'#formSection6',
				'#formProjectFilesUpload'
			].join(','), function(e){
				if (window.PM_PLAN_ADMIN && !window.PM_INCLUDE_MEETING_LOCK && !window.PM_PLAN_FIX_RESUBMIT_LOCK && !window.PM_OPERATE_REPLY_LOCK) return;
				if (isPlanWorkflowEditable && (this.id === 'formSection6' || this.id === 'formKpiGoalProject' || this.id === 'formBudgetPlan')) {
					e.preventDefault();
					e.stopImmediatePropagation();
					return false;
				}
				if (!isSubmittedNow()) return;
				e.preventDefault();
				e.stopImmediatePropagation();
				return false;
			});

			$(document).on('click', '.pm-submit-draft', function(e){
				e.preventDefault();
				if (isSubmittedNow()) {
					return;
				}
				if (typeof window.pmSection6Complete === 'function' && !window.pmSection6Complete()) {
					var msg = 'กรุณากรอกการติดตามประเมินผล และการประเมินความเสี่ยง ให้ครบก่อนส่งร่างโครงการ';
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon: 'warning', title: 'กรุณากรอกส่วนที่ 6', text: msg });
					} else {
						alert(msg);
					}
					var $s6 = $('#pm-section-6');
					if ($s6.length) {
						$('html, body').stop(true).animate({ scrollTop: Math.max(0, ($s6.offset().top || 0) - 86) }, 350);
					}
					return;
				}
				var doSubmit = function(){
					$.ajax({
						url: '?page=project_manage&op=submit_project_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId }
					}).done(function(res){
						if (res && res.ok === 1) {
							applySubmittedState(res.status_project);
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon:'success', title:'ส่งร่างโครงการแล้ว', text:'สถานะ: อยู่ระหว่างพิจารณา', timer: 1400, showConfirmButton:false });
							}
							return;
						}
						var msg = (res && res.msg) ? res.msg : 'ส่งร่างโครงการไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'ไม่สำเร็จ', text: msg });
						else alert(msg);
					}).fail(function(xhr){
						var msg = 'ส่งร่างโครงการไม่สำเร็จ';
						try { var j = JSON.parse(xhr.responseText || '{}'); if (j && j.msg) msg = j.msg; } catch(_e) {}
						if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'เกิดข้อผิดพลาด', text: msg });
						else alert(msg);
					});
				};

				if (typeof Swal !== 'undefined') {
					Swal.fire({
						icon: 'warning',
						title: 'ยืนยันการส่งร่างโครงการ',
						html: 'หากยืนยันการส่งร่างโครงการแล้ว<br><strong>จะไม่สามารถแก้ไขข้อมูลได้อีก</strong>',
						showCancelButton: true,
						confirmButtonText: 'ยืนยันส่งร่าง',
						cancelButtonText: 'ยกเลิก',
						confirmButtonColor: '#dc3545'
					}).then(function(r){
						if (r && r.isConfirmed) doSubmit();
					});
				} else if (confirm('หากยืนยันการส่งร่างโครงการแล้ว จะไม่สามารถแก้ไขข้อมูลได้อีก\nยืนยันส่งร่างโครงการหรือไม่?')) {
					doSubmit();
				}
			});

			function forceHideActivityModal(){
				try { $('#modalActivityProject').modal('hide'); } catch(e){}
				setTimeout(function(){
					$('body').removeClass('modal-open');
					$('.modal-backdrop').remove();
				}, 50);
			}

			// ให้ปุ่มปิดทั้ง 2 จุดทำงานชัวร์ (กันกรณี backdrop ค้าง)
			$(document).on('click', '#modalActivityProject .btn-activity-close', function(e){
				e.preventDefault();
				forceHideActivityModal();
			});
			$('#modalActivityProject').on('hidden.bs.modal', function(){
				$('body').removeClass('modal-open');
				$('.modal-backdrop').remove();
			});

			function resetActivityModal(){
				var $f = $('#formActivityProject');
				if (!$f.length) return;
				$f[0].reset();
				$f.find('input[name="type"]').val('insert');
				$f.find('input[name="project_activity_id"]').val('0');
				$('#modalActivityTitle').text('เพิ่ม/แก้ไขกิจกรรม');

				var $c = $('#activityTargetContainer');
				var $first = $c.find('.pm-target-row').first().clone();
				$first.find('select').val('');
				$first.find('input').val('');
				$first.find('button').attr('data-action','add-target-row')
					.removeClass('btn-outline-danger').addClass('btn-outline-primary')
					.html('<i class="fa fa-plus mr-1"></i> เพิ่ม');
