			}

			function loadActivityTable(){
				var $wrap = $('#activity-table-wrap');
				if (!$wrap.length) return;
				$wrap.html('<small class="text-muted">กำลังโหลด...</small>');
				$.ajax({
					url: '?page=project_manage&op=render_activity_table',
					type: 'POST',
					dataType: 'json',
					data: { project_id: projectId }
				}).done(function(res){
					if (res && res.ok === 1) {
						$wrap.html(res.html || '');
						if (typeof pmShowActivityWeightBanner === 'function') {
							pmShowActivityWeightBanner(res.weight_warning);
						}
						// ส่วนที่ 4: มีรายการกิจกรรม => done
						var has = ($wrap.find('tbody tr.pm-activity-plan-month-row').length > 0) && ($wrap.text().indexOf('ยังไม่มีกิจกรรม') === -1);
						setStepCircle('#step-s4-circle', !!has);
						setStepLine('#step-line-4', !!has);
						if (window.PM_INCLUDE_MEETING_LOCK || window.PM_PLAN_FIX_RESUBMIT_LOCK || window.PM_OPERATE_REPLY_LOCK || (!window.PM_PLAN_ADMIN && isSubmittedNow())) { lockAddEditButtons(); }
						return;
					}
					var errMsg = (res && res.msg) ? String(res.msg) : 'โหลดไม่สำเร็จ';
					$wrap.html('<div class="text-danger">' + errMsg.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</div>');
				}).fail(function(){
					$wrap.html('<div class="text-danger">โหลดไม่สำเร็จ</div>');
				});
			}

			var pmActivityMonthSaveTimers = {};
			function collectActivityResultMonthsFromRow($tr){
				var months = {};
				$tr.find('.pm-activity-result-month-cb').each(function(){
					var key = ($(this).attr('data-month') || '').toString();
					if (!key) return;
					months[key] = $(this).prop('checked') ? 1 : 0;
				});
				return months;
			}
			$(document).on('change', '.pm-activity-result-month-cb', function(){
				var $cb = $(this);
				var actId = parseInt($cb.attr('data-activity-id'), 10) || 0;
				var $tr = $cb.closest('tr.pm-activity-result-month-row');
				if (!actId || !$tr.length || !projectId) return;
				clearTimeout(pmActivityMonthSaveTimers[actId]);
				pmActivityMonthSaveTimers[actId] = setTimeout(function(){
					$tr.find('.pm-activity-result-month-cb').prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=save_activity_result_months_ajax',
						type: 'POST',
						dataType: 'json',
						data: {
							project_id: projectId,
							project_activity_id: actId,
							result_months: JSON.stringify(collectActivityResultMonthsFromRow($tr))
						}
					}).done(function(res){
						if (!res || res.ok !== 1) {
							var msg = (res && res.msg) ? res.msg : 'บันทึกเดือนที่เกิดผลไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: msg, timer: 2200, showConfirmButton: false });
							else alert(msg);
						}
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'บันทึกเดือนที่เกิดผลไม่สำเร็จ', timer: 2200, showConfirmButton: false });
						else alert('บันทึกเดือนที่เกิดผลไม่สำเร็จ');
					}).always(function(){
						$tr.find('.pm-activity-result-month-cb').prop('disabled', false);
					});
				}, 250);
			});

			<?php if (!empty($pm_can_fill_project_results)): ?>
			(function initActivityResultFill(){
				var $modal = $('#modalActivityResultFill');
				var $form = $('#formActivityResultFill');
				if (!$modal.length || !$form.length) return;

				var activityFileWebBase = '../document/activity_result_files/';
				var currentActivityTargets = [];
				var currentActivityResult = null;
				var activityMonthDefs = <?= json_encode(array_map(static function ($k, $v) {
					return ['key' => $k, 'label' => $v];
				}, array_keys(pm_activity_month_map()), array_values(pm_activity_month_map())), JSON_UNESCAPED_UNICODE) ?: '[]' ?>;
				var $disburseModal = $('#modalActivityDisbursementPull');

				function pmHideActivityDisburseModal(){
					if (!$disburseModal.length) return;
					try { $disburseModal.modal('hide'); } catch(err) {}
					$disburseModal.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
					$('.modal-backdrop.pm-activity-disburse-backdrop').remove();
					if ($modal.hasClass('show')) {
						$('body').addClass('modal-open');
						if (!$('.modal-backdrop').not('.pm-activity-disburse-backdrop').length) {
							$('body').append('<div class="modal-backdrop fade show"></div>');
						}
					} else if (!$('.modal.show, .modal.in').length) {
						$('body').removeClass('modal-open');
						$('.modal-backdrop').remove();
					}
				}

				function forceHideActivityResultModal(){
					pmHideActivityDisburseModal();
					try { $modal.modal('hide'); } catch(err) {}
					try {
						var el = $modal.get(0);
						if (el) {
							el.classList.remove('show');
							el.style.display = 'none';
							el.setAttribute('aria-hidden', 'true');
							el.removeAttribute('aria-modal');
						}
						document.body.classList.remove('modal-open');
						document.body.style.removeProperty('padding-right');
						document.querySelectorAll('.modal-backdrop').forEach(function(b){
							if (b && b.parentNode) b.parentNode.removeChild(b);
						});
					} catch(err) {}
					resetActivityResultForm();
					setTimeout(function(){
						try { $modal.modal('hide'); } catch(err) {}
					}, 50);
				}

				function pmOpenActivityDisburseModal(){
					if (!$disburseModal.length) return;
					try { $disburseModal.appendTo('body'); } catch(err) {}
					if (!$('.modal-backdrop.pm-activity-disburse-backdrop').length) {
						$('body').append('<div class="modal-backdrop fade show pm-activity-disburse-backdrop"></div>');
					}
					$('body').addClass('modal-open');
					$disburseModal.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
				}

				function escHtml(s){
					return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
				}

				function formatPlanNum(v){
					var n = parseFloat(v);
					if (isNaN(n) || n === 0) return '0';
					if (Math.abs(n - Math.round(n)) < 0.0001) return String(Math.round(n));
					return String(n);
				}

				function renderActivityTargetInputs(targets, savedTargets){
					savedTargets = savedTargets || {};
					var html = '';
					if (!targets || !targets.length) {
						html = '<div class="pm-activity-result-targets-empty"><i class="fa fa-users-slash mr-1"></i>ไม่มีกลุ่มเป้าหมายในแผนกิจกรรม</div>';
					} else {
						html += '<div class="pm-activity-result-targets-head">';
						html += '<span>กลุ่มเป้าหมาย</span><span class="text-center">แผน</span><span class="text-center">ผล</span>';
						html += '</div>';
						(targets || []).forEach(function(t){
							var code = (t.code_target || '').toString();
							var name = (t.name || code || '-').toString();
							var plan = formatPlanNum(t.target_amount);
							var resultVal = savedTargets[code] !== undefined ? savedTargets[code] : '';
							html += '<div class="pm-activity-result-target-row" data-code-target="' + escHtml(code) + '">';
							html += '<span class="pm-activity-result-target-name">' + escHtml(name) + '</span>';
							html += '<span class="pm-activity-result-target-plan"><span class="pm-activity-result-target-plan-num">' + escHtml(plan) + '</span> คน</span>';
							html += '<span class="pm-activity-result-target-result"><input type="number" class="form-control form-control-sm activity-result-target-input" min="0" step="1" placeholder="0" value="' + escHtml(resultVal === '' ? '' : String(resultVal)) + '" data-code-target="' + escHtml(code) + '"></span>';
							html += '</div>';
						});
					}
					$('#activityResultTargetsWrap').html(html);
				}

				function syncActivityMonthPickState($lab){
					if (!$lab || !$lab.length) return;
					var on = $lab.find('input').prop('checked');
					$lab.toggleClass('is-on', !!on);
				}
				function renderActivityMonthInputs(savedMonths){
					savedMonths = savedMonths || {};
					var html = '';
					(activityMonthDefs || []).forEach(function(m){
						var key = (m.key || '').toString();
						if (!key) return;
						var on = !!savedMonths[key];
						html += '<label class="pm-activity-result-month-pick' + (on ? ' is-on' : '') + '">';
						html += '<input type="checkbox" class="activity-result-month-input" value="' + escHtml(key) + '"' + (on ? ' checked' : '') + '>';
						html += '<span class="pm-activity-result-month-pick-label">' + escHtml(m.label || key) + '</span>';
						html += '<span class="pm-activity-result-month-pick-x" aria-hidden="true">X</span>';
						html += '</label>';
					});
					$('#activityResultMonthsWrap').html(html).removeClass('is-invalid');
				}
				function collectActivityResultMonths(){
					var months = {};
					(activityMonthDefs || []).forEach(function(m){
						var key = (m.key || '').toString();
						if (key) months[key] = 0;
					});
					$('#activityResultMonthsWrap .activity-result-month-input').each(function(){
						var key = ($(this).val() || '').toString();
						if (!key) return;
						months[key] = $(this).prop('checked') ? 1 : 0;
					});
					return months;
				}
				$(document).on('change', '#activityResultMonthsWrap .activity-result-month-input', function(){
					syncActivityMonthPickState($(this).closest('.pm-activity-result-month-pick'));
					$('#activityResultMonthsWrap').removeClass('is-invalid');
				});

				function renderActivityFileNames(input){
					var $label = $('#activityResultFileNames');
					if (!$label.length) return;
					if (!input || !input.files || !input.files.length) {
						$label.text('ยังไม่ได้เลือกไฟล์').removeClass('text-dark font-weight-bold').addClass('text-muted');
						return;
					}
					var names = [];
					for (var i = 0; i < input.files.length; i++) {
						names.push(input.files[i].name);
					}
					$label.text(names.join(', ')).removeClass('text-muted').addClass('text-dark font-weight-bold');
				}

				function renderActivityExistingFiles(files){
					var html = '';
					if (!files || !files.length) {
						$('#activityResultExistingFiles').empty();
						return;
					}
					(files || []).forEach(function(f){
						var fid = parseInt(f.id, 10) || 0;
						var name = escHtml(f.original_name || 'file');
						var url = escHtml(activityFileWebBase + (f.stored_file || ''));
						html += '<span class="pm-activity-result-existing-file" data-file-id="' + fid + '">';
						html += '<a href="' + url + '" target="_blank" rel="noopener"><i class="fa fa-file-alt mr-1"></i>' + name + '</a>';
						html += '<button type="button" class="btn btn-link btn-sm text-danger p-0 ml-1 btn-activity-result-file-del" data-file-id="' + fid + '" title="ลบไฟล์"><i class="fa fa-times-circle"></i></button>';
						html += '</span>';
					});
					$('#activityResultExistingFiles').html(html);
				}

				function resetActivityResultForm(){
					$('#activityResultDetail').val('').removeClass('is-invalid');
					$('#activityResultProgressPercent').val('').removeClass('is-invalid');
					$('#activityResultFiles').val('');
					renderActivityFileNames(null);
					$('#activityResultExistingFiles').empty();
					$('#activityResultMonthsWrap').empty().removeClass('is-invalid');
					$('#activityResultActivityLabel').text('-');
					currentActivityTargets = [];
					currentActivityResult = null;
					$('#btnActivityResultSaveText').text('บันทึก');
				}

				function collectActivityTargetResults(){
					var rows = [];
					$('#activityResultTargetsWrap .activity-result-target-input').each(function(){
						var code = ($(this).attr('data-code-target') || '').toString();
						if (!code) return;
						rows.push({
							code_target: code,
							result_amount: ($(this).val() || '').toString()
						});
					});
					return rows;
				}

				function openActivityResultModal($btn){
					var actId = parseInt($btn.attr('data-activity-result-id') || '0', 10);
					var actName = ($btn.attr('data-activity-result-name') || '-').toString();
					var targets = [];
					var resultData = null;
					try { targets = JSON.parse($btn.attr('data-activity-result-targets') || '[]'); } catch(err) { targets = []; }
					try { resultData = JSON.parse($btn.attr('data-activity-result-data') || 'null'); } catch(err) { resultData = null; }

					currentActivityTargets = targets;
					currentActivityResult = resultData;

					$('#activityResultActivityId').val(String(actId));
					$('#modalActivityResultFillTitle').html('<i class="fa fa-clipboard-list mr-2"></i>รายงานการจัดกิจกรรม');
					$('#activityResultActivityLabel').text(actName);
					$('#activityResultDetail').val(resultData && resultData.result_detail ? resultData.result_detail : '');
					var prog = (resultData && resultData.progress_percent !== undefined && resultData.progress_percent !== null && resultData.progress_percent !== '')
						? resultData.progress_percent : '';
					$('#activityResultProgressPercent').val(prog === '' ? '' : String(prog)).removeClass('is-invalid');
					renderActivityTargetInputs(targets, (resultData && resultData.targets) ? resultData.targets : {});
					renderActivityMonthInputs((resultData && resultData.months) ? resultData.months : {});
					renderActivityExistingFiles(resultData && resultData.files ? resultData.files : []);
					$('#btnActivityResultSaveText').text('บันทึก');
				}

				$(document).on('click', '.btn-activity-fill-result, .btn-activity-edit-result', function(e){
					e.preventDefault();
					openActivityResultModal($(this));
				});

				$('#activityResultFiles').on('change', function(){
					renderActivityFileNames(this);
				});

				$('#activityResultProgressPercent').on('input change', function(){
					var v = parseFloat(String($(this).val() || '').replace(/,/g, ''));
					if (!isNaN(v) && v > 100) {
						$(this).val('100').addClass('is-invalid');
					} else {
						$(this).removeClass('is-invalid');
					}
				});

				function validateActivityProgressPercent(){
					var $inp = $('#activityResultProgressPercent');
					var raw = ($inp.val() || '').toString().trim();
					if (raw === '') {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณากรอก % ดำเนินการ' });
						else alert('กรุณากรอก % ดำเนินการ');
						$inp.addClass('is-invalid').focus();
						return false;
					}
					var v = parseFloat(raw.replace(/,/g, ''));
					if (isNaN(v)) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: '% ดำเนินการต้องเป็นตัวเลข' });
						else alert('% ดำเนินการต้องเป็นตัวเลข');
						$inp.addClass('is-invalid').focus();
						return false;
					}
					if (v < 0 || v > 100) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: '% ดำเนินการต้องอยู่ระหว่าง 0–100' });
						else alert('% ดำเนินการต้องอยู่ระหว่าง 0–100');
						$inp.addClass('is-invalid').focus();
						return false;
					}
					$inp.removeClass('is-invalid');
					return true;
				}

				function validateActivityResultForm(){
					if (!validateActivityProgressPercent()) return false;
					var $detail = $('#activityResultDetail');
					var detail = ($detail.val() || '').toString().trim();
					if (!detail) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณากรอกรายละเอียดการดำเนินการ' });
						else alert('กรุณากรอกรายละเอียดการดำเนินการ');
						$detail.addClass('is-invalid').focus();
						return false;
					}
					$detail.removeClass('is-invalid');

					var targetOk = true;
					var $firstBad = null;
					$('#activityResultTargetsWrap .activity-result-target-input').each(function(){
						var $inp = $(this);
						var val = ($inp.val() || '').toString().trim();
						if (val === '' || isNaN(parseFloat(val)) || parseFloat(val) < 0) {
							targetOk = false;
							$inp.addClass('is-invalid');
							if (!$firstBad) $firstBad = $inp;
						} else {
							$inp.removeClass('is-invalid');
						}
					});
					if (!targetOk) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณากรอกผลกลุ่มเป้าหมายให้ครบทุกรายการ' });
						else alert('กรุณากรอกผลกลุ่มเป้าหมายให้ครบทุกรายการ');
						if ($firstBad && $firstBad.length) $firstBad.focus();
						return false;
					}

					var months = collectActivityResultMonths();
					var hasMonth = false;
					Object.keys(months).forEach(function(k){
						if (months[k]) hasMonth = true;
					});
					if (!hasMonth) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณาทำเครื่องหมาย X ในเดือนที่ดำเนินการอย่างน้อย 1 เดือน' });
						else alert('กรุณาทำเครื่องหมาย X ในเดือนที่ดำเนินการอย่างน้อย 1 เดือน');
						$('#activityResultMonthsWrap').addClass('is-invalid');
						return false;
					}
					$('#activityResultMonthsWrap').removeClass('is-invalid');
					return true;
				}

				$modal.on('show.bs.modal', function(e){
					var $btn = $(e.relatedTarget);
					if ($btn && $btn.length && ($btn.hasClass('btn-activity-fill-result') || $btn.hasClass('btn-activity-edit-result'))) {
						openActivityResultModal($btn);
					}
				});

				$('#btnActivityResultPullDisburse').on('click', function(){
					var actId = parseInt($('#activityResultActivityId').val() || '0', 10);
					if (!actId) return;
					$.ajax({
						url: '?page=project_manage&op=get_activity_disbursement_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId, project_activity_id: actId }
					}).done(function(res){
						if (!res || res.ok !== 1) {
							var msg = (res && res.msg) ? res.msg : 'ดึงข้อมูลไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: msg });
							else alert(msg);
							return;
						}
						if (!res.has_data) {
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'info', title: 'ไม่พบข้อมูลเบิกจ่ายสำหรับกิจกรรมนี้' });
							else alert('ไม่พบข้อมูลเบิกจ่ายสำหรับกิจกรรมนี้');
							return;
						}
						$('#activityDisbursementPullText').val(res.text || '');
						pmOpenActivityDisburseModal();
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
