				$('#btnActivityDisbursementApply').on('click', function(){
					var txt = ($('#activityDisbursementPullText').val() || '').toString();
					if (!txt) {
						pmHideActivityDisburseModal();
						return;
					}
					var $ta = $('#activityResultDetail');
					var cur = ($ta.val() || '').toString().trim();
					$ta.val(cur ? (cur + '\n\n' + txt) : txt);
