				$(document).on('click', '#modalActivityDisbursementPull .pm-activity-disburse-close', function(e){
					e.preventDefault();
					e.stopPropagation();
					pmHideActivityDisburseModal();
				});

				$(document).on('keydown.pmActivityDisburse', function(e){
					if (!$disburseModal.hasClass('show')) return;
					if (e.key === 'Escape' || e.keyCode === 27) {
						e.preventDefault();
						pmHideActivityDisburseModal();
					}
				});

				$(document).on('click', '.modal-backdrop.pm-activity-disburse-backdrop', function(e){
					e.preventDefault();
					pmHideActivityDisburseModal();
				});

				$(document).on('click', '.btn-activity-result-file-del', function(e){
					e.preventDefault();
					var fileId = parseInt($(this).attr('data-file-id') || '0', 10);
					if (!fileId) return;
					var doDel = function(){
						$.ajax({
							url: '?page=project_manage&op=delete_activity_result_file_ajax',
							type: 'POST',
							dataType: 'json',
							data: { project_id: projectId, file_id: fileId }
						}).done(function(res){
							if (res && res.ok === 1) {
								$('.pm-activity-result-existing-file[data-file-id="' + fileId + '"]').remove();
								if (currentActivityResult && currentActivityResult.files) {
									currentActivityResult.files = currentActivityResult.files.filter(function(f){
										return parseInt(f.id, 10) !== fileId;
									});
								}
								return;
							}
							var msg = (res && res.msg) ? res.msg : 'ลบไฟล์ไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: msg });
							else alert(msg);
						});
					};
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon: 'warning', title: 'ลบไฟล์แนบนี้?', showCancelButton: true, confirmButtonText: 'ลบ', cancelButtonText: 'ยกเลิก' })
							.then(function(r){ if (r.isConfirmed) doDel(); });
					} else if (confirm('ลบไฟล์แนบนี้?')) {
						doDel();
					}
				});

				function saveActivityResult(){
					if (!validateActivityResultForm()) return;
					var fd = new FormData($form[0]);
					fd.append('target_results', JSON.stringify(collectActivityTargetResults()));
					fd.append('result_months', JSON.stringify(collectActivityResultMonths()));
					var $btnSave = $('#btnActivityResultSave');
					$btnSave.prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=save_activity_result_ajax',
						method: 'POST',
						data: fd,
						processData: false,
						contentType: false,
						dataType: 'json'
					}).done(function(res){
						if (res && res.ok === 1) {
							loadActivityTable();
							forceHideActivityResultModal();
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'success', title: res.msg || 'บันทึกสำเร็จ', timer: 1200, showConfirmButton: false });
							}
							return;
						}
						var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: msg });
						else alert(msg);
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
						else alert('เชื่อมต่อไม่สำเร็จ');
					}).always(function(){
						$btnSave.prop('disabled', false);
					});
				}

				$form.on('submit', function(e){
					e.preventDefault();
					saveActivityResult();
					return false;
				});

				$(document).on('click', '#modalActivityResultFill .pm-activity-result-close, #modalActivityResultFill .pm-activity-result-btn-cancel', function(e){
					e.preventDefault();
					forceHideActivityResultModal();
				});

				$modal.on('hidden.bs.modal', function(){
					resetActivityResultForm();
				});
			})();
