			<?php if (!empty($pm_can_fill_project_results)): ?>
			function pmBudgetDisburseBlocked(){
				return window.PM_CAN_FILL_PROJECT_RESULTS && (window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE);
			}
			(function initBudgetDisburseReport(){
				var $modal = $('#modalBudgetDisburseReport');
				if (!$modal.length) return;
				var currentItems = [];
				var currentActivityId = 0;
				var currentSaveMode = 'add';
				var currentProjectRemain = 0;
				var currentEditOriginalAmount = 0;

				function fmtMoney(n){
					if (typeof window.pmFmtBudgetNum === 'function') return window.pmFmtBudgetNum(n);
					var v = parseFloat(n);
					if (isNaN(v)) v = 0;
					var rounded = Math.round(v * 100) / 100;
					if (Math.abs(rounded - Math.round(rounded)) < 1e-9) {
						return Math.round(rounded).toLocaleString('en-US', { maximumFractionDigits: 0 });
					}
					return rounded.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
				}
				function pmHideBudgetDisburseModal(){
					try { $modal.modal('hide'); } catch(err) {}
					$modal.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
					if (!$('.modal.show, .modal.in').not($modal).length) {
						$('body').removeClass('modal-open').css('padding-right', '');
						$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
					}
				}
				function pmOpenBudgetDisburseModal(){
					try { $modal.appendTo('body'); } catch(err) {}
					try {
						$modal.modal({ backdrop: true, keyboard: true, show: true });
					} catch(err) {
						$modal.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
						if (!$('.modal-backdrop').not('.pm-activity-disburse-backdrop').length) {
							$('body').append('<div class="modal-backdrop fade show"></div>');
						}
						$('body').addClass('modal-open');
					}
				}
				function cloneBudgetDisburseLineRow(){
					var tpl = document.getElementById('tplBudgetDisburseLine');
					if (!tpl || !tpl.content) return null;
					var frag = tpl.content.cloneNode(true);
					var el = frag.querySelector('.pm-budget-disburse-line') || frag.firstElementChild;
					return el ? $(el) : null;
				}
				function getDisburseFormTotal(){
					var sum = 0;
					$('#budgetDisburseLinesContainer .pm-bd-line-amount').each(function(){
						var v = parseFloat($(this).val() || '0');
						if (!isNaN(v)) sum += v;
					});
					return sum;
				}
				function getDisburseAvailableRemain(){
					var remain = parseFloat(currentProjectRemain) || 0;
					var orig = parseFloat(currentEditOriginalAmount) || 0;
					return remain + orig;
				}
				function isDisburseOverBudget(){
					return (getDisburseFormTotal() - getDisburseAvailableRemain()) > 0.005;
				}
				function updateDisburseOverBudgetWarn(){
					var over = isDisburseOverBudget();
					$('#budgetDisburseOverBudgetWarn').toggleClass('d-none', !over);
					$('#budgetDisburseTotalShow').toggleClass('is-over', over);
				}
				function showDisburseOverBudgetBlock(){
					var msg = 'งบประมาณคงเหลือไม่เพียงพอ ไม่สามารถทำรายการได้';
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon: 'error', title: msg });
					} else {
						alert(msg);
					}
				}
				function updateDisburseTotal(){
					var sum = getDisburseFormTotal();
					$('#budgetDisburseTotalShow').text(fmtMoney(sum));
					updateDisburseOverBudgetWarn();
				}
				function buildItemOptions($sel, selectedId){
					var html = '<option value="">- เลือกรายการ -</option>';
					currentItems.forEach(function(it){
						var id = parseInt(it.id, 10) || 0;
						if (!id) return;
						var label = (it.budget_no ? (it.budget_no + ' ') : '') + (it.name || '');
						html += '<option value="'+id+'"'+(selectedId === id ? ' selected' : '')+'>'+String(label).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</option>';
					});
					$sel.html(html);
				}
				function addDisburseLine(pref){
					pref = pref || {};
					var $row = cloneBudgetDisburseLineRow();
					if (!$row || !$row.length) return;
					var lineId = parseInt(pref.id, 10) || 0;
					$row.find('.pm-bd-line-id').val(lineId > 0 ? lineId : '0');
					buildItemOptions($row.find('.pm-bd-line-item'), parseInt(pref.project_activity_budget_id, 10) || 0);
					$row.find('.pm-bd-line-detail').val(pref.line_detail || '');
					$row.find('.pm-bd-line-amount').val(pref.amount !== undefined && pref.amount !== null && pref.amount !== '' ? pref.amount : '');
					$row.find('.pm-bd-line-month').val(pref.disburse_month || '');
					var itemId = parseInt(pref.project_activity_budget_id, 10) || 0;
					var itemName = '';
					currentItems.forEach(function(it){
						if ((parseInt(it.id, 10) || 0) === itemId) itemName = it.name || '';
					});
					if (itemName) $row.find('.pm-bd-line-item-label').text(itemName);
					$row.find('.pm-bd-line-remove').removeClass('d-none');
					$('#budgetDisburseLinesContainer').append($row);
					updateDisburseRemoveButtons();
					updateDisburseTotal();
				}
				function updateDisburseRemoveButtons(){
					var $rows = $('#budgetDisburseLinesContainer .pm-budget-disburse-line');
					var canRemove = $rows.length > 1;
					$rows.each(function(){
						$(this).find('.pm-bd-line-remove').toggleClass('d-none', !canRemove);
					});
				}
				function applyBudgetDisburseModalMode(mode){
					currentSaveMode = (mode === 'edit') ? 'edit' : 'add';
					$('#budgetDisburseSaveMode').val(currentSaveMode);
					var isEdit = currentSaveMode === 'edit';
					$('#btnAddBudgetDisburseLine').removeClass('d-none');
					$('#btnSaveBudgetDisburseReport').html(isEdit
						? '<i class="fa fa-save mr-1"></i> บันทึกการแก้ไข'
						: '<i class="fa fa-save mr-1"></i> บันทึก/แก้ไข');
				}
				function fillBudgetDisburseModal(data, label, projectRemain, mode, extra){
					data = data || {};
					extra = extra || {};
					mode = (mode === 'edit') ? 'edit' : 'add';
					applyBudgetDisburseModalMode(mode);
					currentActivityId = parseInt(data.project_activity_id, 10) || 0;
					currentItems = Array.isArray(data.items) ? data.items : [];
					currentProjectRemain = parseFloat(projectRemain) || 0;
					currentEditOriginalAmount = (mode === 'edit')
						? (parseFloat(extra.edit_line_amount) || 0)
						: 0;
					var titlePrefix = mode === 'edit' ? 'แก้ไขรายการเบิกจ่าย' : 'เพิ่มรายการเบิกจ่าย';
					$('#modalBudgetDisburseReportTitle').text(titlePrefix + ' : ' + (label || ''));
					$('#budgetDisburseProjectRemainShow').text(fmtMoney(projectRemain || 0));
					$('#budgetDisburseActivityId').val(currentActivityId);
					$('#budgetDisburseActivityDetail').val(data.activity_detail || '');
					var editLineId = 0;
					var lines = Array.isArray(data.lines) ? data.lines : [];
					if (mode === 'edit' && lines.length) {
						editLineId = parseInt(lines[0].id, 10) || 0;
						if (!(currentEditOriginalAmount > 0)) {
							var sumOrig = 0;
							lines.forEach(function(ln){ sumOrig += parseFloat(ln.amount) || 0; });
							currentEditOriginalAmount = sumOrig;
						}
					}
					$('#budgetDisburseLineId').val(editLineId);
					$('#budgetDisburseLinesContainer').empty();
					if (lines.length) {
						lines.forEach(function(ln){ addDisburseLine(ln); });
					} else {
						addDisburseLine({});
					}
					updateDisburseRemoveButtons();
					pmOpenBudgetDisburseModal();
				}
				function collectDisburseLines(){
					var lines = [];
					$('#budgetDisburseLinesContainer .pm-budget-disburse-line').each(function(){
						var $r = $(this);
						var row = {
							project_activity_budget_id: parseInt($r.find('.pm-bd-line-item').val() || '0', 10) || 0,
							line_detail: ($r.find('.pm-bd-line-detail').val() || '').trim(),
							amount: ($r.find('.pm-bd-line-amount').val() || '').trim(),
							disburse_month: ($r.find('.pm-bd-line-month').val() || '').trim()
						};
						var lid = parseInt($r.find('.pm-bd-line-id').val() || '0', 10) || 0;
						if (lid > 0) row.id = lid;
						lines.push(row);
					});
					return lines;
				}
				function validateDisburseLines(lines){
					if (!lines || !lines.length) return 'กรุณากรอกรายการเบิกจ่ายอย่างน้อย 1 รายการ';
					for (var i = 0; i < lines.length; i++) {
						var ln = lines[i] || {};
						var itemId = parseInt(ln.project_activity_budget_id || 0, 10) || 0;
						var amount = parseFloat(String(ln.amount || '').replace(/,/g, ''));
						var month = String(ln.disburse_month || '').trim();
						if (!itemId && !String(ln.line_detail || '').trim() && !(amount > 0)) continue;
						if (!itemId) return 'กรุณาเลือกรายการค่าใช้จ่าย';
						if (!(amount > 0)) return 'กรุณาระบุจำนวนเงินเบิกจ่ายให้มากกว่า 0';
						if (!month) return 'กรุณาเลือกเดือนเบิกจ่าย';
					}
					var hasValid = lines.some(function(ln){
						return (parseInt(ln.project_activity_budget_id || 0, 10) > 0)
							&& (parseFloat(String(ln.amount || '').replace(/,/g, '')) > 0)
							&& String(ln.disburse_month || '').trim() !== '';
					});
					return hasValid ? '' : 'กรุณากรอกรายการเบิกจ่ายอย่างน้อย 1 รายการ';
				}
				function openDisburseExternalSystem(url, payload){
					url = String(url || '').trim();
					if (!url) return;
					payload = (payload && typeof payload === 'object') ? payload : null;
					if (!payload) {
						try { window.open(url, '_blank', 'noopener'); } catch (eOpen) {
							window.location.href = url;
						}
						return;
					}
					try {
						var form = document.createElement('form');
						form.method = 'POST';
						form.action = url;
						form.target = '_blank';
						form.acceptCharset = 'UTF-8';
						form.style.display = 'none';
						form.setAttribute('rel', 'noopener');
						var appendField = function(name, value){
							var input = document.createElement('input');
							input.type = 'hidden';
							input.name = name;
							input.value = (value === null || value === undefined) ? '' : String(value);
							form.appendChild(input);
						};
						Object.keys(payload).forEach(function(key){
							var val = payload[key];
							if (key === 'items' && Array.isArray(val)) {
								val.forEach(function(item, idx){
									if (!item || typeof item !== 'object') return;
									Object.keys(item).forEach(function(ik){
										appendField('items[' + idx + '][' + ik + ']', item[ik]);
									});
								});
								appendField('items_json', JSON.stringify(val));
								return;
							}
							if (val !== null && typeof val === 'object') {
								appendField(key, JSON.stringify(val));
								return;
							}
							appendField(key, val);
						});
						appendField('payload_json', JSON.stringify(payload));
						document.body.appendChild(form);
						form.submit();
						setTimeout(function(){
							try { form.parentNode && form.parentNode.removeChild(form); } catch (eRm) {}
						}, 1500);
					} catch (eForm) {
						try { window.open(url, '_blank', 'noopener'); } catch (eOpen2) {
							window.location.href = url;
						}
					}
				}
				function saveDisburseReport(andConfirm){
					var actId = parseInt($('#budgetDisburseActivityId').val() || '0', 10);
					var saveMode = ($('#budgetDisburseSaveMode').val() || 'add').toString();
					var lineId = parseInt($('#budgetDisburseLineId').val() || '0', 10);
					var pid = parseInt(projectId || 0, 10) || parseInt($('#edit_project_id').val() || '0', 10) || 0;
					if (!actId || !pid) {
						var miss = !pid ? 'ไม่พบรหัสโครงการ' : 'ไม่พบรหัสกิจกรรม';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: miss });
						else alert(miss);
						return;
					}
					var lines = collectDisburseLines();
					var vmsg = validateDisburseLines(lines);
					if (vmsg) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: vmsg });
						else alert(vmsg);
						return;
					}
					if (andConfirm && isDisburseOverBudget()) {
						showDisburseOverBudgetBlock();
						return;
					}
					var $saveBtn = $('#btnSaveBudgetDisburseReport');
					var $confirmBtn = $('#btnConfirmBudgetDisburseReport');
					$saveBtn.prop('disabled', true);
					$confirmBtn.prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=save_budget_disburse_report_ajax',
						type: 'POST',
						dataType: 'text',
						data: {
							project_id: pid,
							project_activity_id: actId,
							activity_detail: ($('#budgetDisburseActivityDetail').val() || '').trim(),
							save_mode: saveMode,
							line_id: lineId,
							confirm: andConfirm ? '1' : '0',
							lines: JSON.stringify(lines)
						}
					}).done(function(raw){
						var res = null;
						try { res = JSON.parse(String(raw || '')); } catch(e) { res = null; }
						if (res && Number(res.ok) === 1) {
							pmHideBudgetDisburseModal();
							if (typeof loadBudgetTable === 'function') loadBudgetTable();
							var msg = andConfirm
								? (res.msg || 'ยืนยันและจัดทำเอกสารเบิกจ่ายแล้ว')
								: (res.msg || 'บันทึกสำเร็จ');
							var extUrl = String(res.external_url || '').trim();
							var extPayload = (res.external_payload && typeof res.external_payload === 'object')
								? res.external_payload
								: null;
							if (andConfirm && extUrl) {
								openDisburseExternalSystem(extUrl, extPayload);
							}
							if (typeof Swal !== 'undefined') {
								Swal.fire({
									icon: 'success',
									title: msg,
									text: (andConfirm && extUrl) ? 'เปิดระบบเบิกจ่ายแล้ว' : '',
									timer: andConfirm ? 1600 : 1400,
									showConfirmButton: false
								});
							} else {
								alert(msg);
							}
							return;
						}
						var err = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: err });
						else alert(err);
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ' });
						else alert('บันทึกไม่สำเร็จ');
					}).always(function(){
						$saveBtn.prop('disabled', false);
						$confirmBtn.prop('disabled', false);
					});
				}

				function loadBudgetDisburseModal($btn, actId, label, mode, lineId){
					if (!actId || !projectId) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'ไม่พบข้อมูลกิจกรรม' });
						else alert('ไม่พบข้อมูลกิจกรรม');
						return;
					}
					$btn.prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=get_budget_disburse_report_ajax',
						type: 'POST',
						dataType: 'json',
						data: {
							project_id: projectId,
							project_activity_id: actId,
							mode: mode || 'add',
							line_id: lineId || 0
						}
					}).done(function(res){
						if (!res || res.ok !== 1 || !res.data) {
							var msg = (res && res.msg) ? res.msg : 'โหลดข้อมูลรายงานเบิกจ่ายไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: msg });
							else alert(msg);
							return;
						}
						fillBudgetDisburseModal(res.data, label, res.project_remain_total, mode || 'add', {
							edit_line_amount: res.edit_line_amount,
							project_remain_available: res.project_remain_available
						});
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
						else alert('เชื่อมต่อไม่สำเร็จ');
					}).always(function(){
						$btn.prop('disabled', false);
					});
				}

				$(document).on('click', '.pm-budget-disburse-open', function(e){
					e.preventDefault();
					if (pmBudgetDisburseBlocked()) return;
					var $btn = $(this);
					var actId = parseInt($btn.attr('data-activity-id') || '0', 10);
					var label = $btn.attr('data-activity-label') || '';
					loadBudgetDisburseModal($btn, actId, label, 'add', 0);
				});
				$(document).on('click', '.pm-budget-disburse-edit', function(e){
					e.preventDefault();
					if (pmBudgetDisburseBlocked()) return;
					var $btn = $(this);
					var actId = parseInt($btn.attr('data-activity-id') || '0', 10);
					var lineId = parseInt($btn.attr('data-line-id') || '0', 10);
					var label = $btn.attr('data-activity-label') || '';
					if (!lineId) return;
					loadBudgetDisburseModal($btn, actId, label, 'edit', lineId);
				});
				$('#btnAddBudgetDisburseLine').on('click', function(){
					addDisburseLine({});
				});
				$(document).on('click', '.pm-bd-line-remove', function(){
					var $rows = $('#budgetDisburseLinesContainer .pm-budget-disburse-line');
					if ($rows.length <= 1) return;
					$(this).closest('.pm-budget-disburse-line').remove();
					updateDisburseRemoveButtons();
					updateDisburseTotal();
				});
				$(document).on('input change', '.pm-bd-line-amount', updateDisburseTotal);
				$(document).on('change', '.pm-bd-line-item', function(){
					var $row = $(this).closest('.pm-budget-disburse-line');
					var itemId = parseInt($(this).val() || '0', 10) || 0;
					var itemName = 'รายการค่าใช้จ่าย';
					currentItems.forEach(function(it){
						if ((parseInt(it.id, 10) || 0) === itemId) itemName = it.name || itemName;
					});
					$row.find('.pm-bd-line-item-label').text(itemName);
				});
				$(document).off('click.pmBdSaveDeleg').on('click.pmBdSaveDeleg', '#btnSaveBudgetDisburseReport', function(e){
					e.preventDefault();
					e.stopPropagation();
					saveDisburseReport(false);
				});
				$(document).off('click.pmBdConfirmDeleg').on('click.pmBdConfirmDeleg', '#btnConfirmBudgetDisburseReport', function(e){
					e.preventDefault();
					e.stopPropagation();
					if (isDisburseOverBudget()) {
						showDisburseOverBudgetBlock();
						return;
					}
					if (typeof Swal !== 'undefined') {
						Swal.fire({
							icon: 'question',
							title: 'ยืนยันและจัดทำเอกสารเบิกจ่าย?',
							text: 'หลังยืนยันแล้วจะไม่สามารถแก้ไขรายการนี้ และระบบจะเปิดไปยังระบบเบิกจ่าย',
							showCancelButton: true,
							confirmButtonText: 'ยืนยัน',
							cancelButtonText: 'ยกเลิก'
						}).then(function(r){
							if (r && r.isConfirmed) saveDisburseReport(true);
						});
					} else if (window.confirm('ยืนยันและจัดทำเอกสารเบิกจ่าย?')) {
						saveDisburseReport(true);
					}
				});
				$(document).on('click', '#modalBudgetDisburseReport .pm-budget-disburse-close', function(e){
					e.preventDefault();
					pmHideBudgetDisburseModal();
				});
				$modal.on('hidden.bs.modal', function(){
					if (!$('.modal.show, .modal.in').length) {
						$('body').removeClass('modal-open').css('padding-right', '');
						$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
					}
				});
			})();

			(function initBudgetDisburseExternalDoc(){
				var $modal = $('#modalBudgetDisburseExternal');
				if (!$modal.length || !projectId) return;

				function escHtml(s){
					return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
				}
				function fmtMoney(v){
					var n = parseFloat(v);
					if (isNaN(n)) return escHtml(String(v || '-'));
					return escHtml(n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
				}
				function fmtThaiDateTime(dt){
					if (!dt) return '-';
					var s = String(dt).trim();
					if (!s) return '-';
					if (/[\u0E00-\u0E7F]/.test(s) && !/^\d{4}-\d{2}-\d{2}/.test(s)) {
						return s;
					}
					var d = new Date(s.replace(' ', 'T'));
					if (isNaN(d.getTime())) return s;
					var months = ['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
					var day = d.getDate();
					var mon = months[d.getMonth()] || '';
					var y = d.getFullYear() + 543;
					var txt = day + ' ' + mon + ' ' + y;
					if (s.indexOf(':') >= 0) {
						txt += ' เวลา ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0') + ' น.';
					}
					return txt;
				}
				function statusClass(raw){
					var r = String(raw || '').toLowerCase();
					if (r === 'approved') return 'is-approved';
					if (r === 'cancelled') return 'is-cancelled';
					if (r === 'pending_handoff') return 'is-handoff';
					if (r === 'confirmed_local') return 'is-local';
					if (r.indexOf('pending') === 0 || r === 'saved') return 'is-pending';
					return '';
				}
				function stepInfo(st){
					var s = String(st || '').toLowerCase();
					if (s === 'approved') {
						return { cls: 'is-approved', label: 'ผ่านการอนุมัติ', icon: 'fa-check-circle' };
					}
					if (s === 'rejected' || s === 'cancelled') {
						return { cls: 'is-rejected', label: 'ไม่ผ่านการอนุมัติ', icon: 'fa-times-circle' };
					}
					if (s === 'skipped') {
						return { cls: 'is-pending', label: 'ข้ามขั้นตอน', icon: 'fa-minus-circle' };
					}
					return { cls: 'is-pending', label: 'รออนุมัติ', icon: 'fa-clock' };
				}
				function pdfLink(name, url, desc){
					if (!url) return '';
					var descHtml = desc ? '<span class="pm-bdext-doc-desc">' + escHtml(desc) + '</span>' : '';
					return '<li><a href="' + escHtml(url) + '" target="_blank" rel="noopener"><i class="fa fa-file-pdf text-danger"></i><span class="pm-bdext-doc-link-text"><span class="pm-bdext-doc-name">' + escHtml(name || 'เอกสาร PDF') + '</span>' + descHtml + '</span></a></li>';
				}
				function renderPdfGroup(title, titleCls, itemsHtml){
					if (!itemsHtml) return '';
					return '<div class="pm-bdext-doc-group">'
						+ '<div class="pm-bdext-doc-group-title ' + (titleCls || '') + '">' + escHtml(title) + '</div>'
						+ '<ul class="pm-bdext-pdf-list">' + itemsHtml + '</ul>'
						+ '</div>';
				}
				function normPdfUrl(u){
					if (!u) return '';
					var s = String(u).trim();
					try {
						var a = document.createElement('a');
						a.href = s;
						return (a.pathname || s.split('?')[0]).toLowerCase();
					} catch (e) {
						return s.split('?')[0].toLowerCase();
					}
				}
				function normPdfName(n){
					return String(n || '').trim().toLowerCase().replace(/\s+/g, ' ');
				}
				function isSamePdfFile(a, b){
					if (!a || !b) return false;
					var urlA = normPdfUrl(a.url || '');
					var urlB = normPdfUrl(b.url || '');
					if (urlA && urlB && urlA === urlB) return true;
					var idA = String(a.file_id || a.id || '').trim();
					var idB = String(b.file_id || b.id || '').trim();
					if (idA && idB && idA === idB) return true;
					var nameA = normPdfName(a.name);
					var nameB = normPdfName(b.name);
					return nameA !== '' && nameA === nameB;
				}
				function isApproveMemoUpload(file, approveMemo){
					if (!file) return false;
					if (approveMemo && isSamePdfFile(file, approveMemo)) return true;
					var nm = normPdfName(file.name);
					return nm.indexOf('บันทึกอนุมัติโครงการ') >= 0
						|| nm.indexOf('บันทกอนุมัติโครงการ') >= 0
						|| nm.indexOf('approve memo') >= 0;
				}
				function renderPdfSection(pdfs){
					pdfs = pdfs || {};
					var html = '';
					var mainDocs = '';
					var attachDocs = '';
					var seenAttach = {};

					if (pdfs.memo_pdf && pdfs.memo_pdf.url) {
						mainDocs += pdfLink(
							pdfs.memo_pdf.name || 'บันทึกข้อความขอเบิกจ่าย',
							pdfs.memo_pdf.url,
							'เอกสารหลัก — บันทึกข้อความขอเบิกจ่าย'
						);
					}
					var approveMemo = (pdfs.approve_memo_pdf && pdfs.approve_memo_pdf.url) ? pdfs.approve_memo_pdf : null;
					if (approveMemo) {
						var approveKey = normPdfUrl(approveMemo.url) || normPdfName(approveMemo.name);
						if (approveKey) seenAttach[approveKey] = true;
						attachDocs += pdfLink(
							approveMemo.name || 'บันทึกอนุมัติโครงการ',
							approveMemo.url,
							'ไฟล์แนบ — บันทึกอนุมัติโครงการ'
						);
					}
					var uploads = Array.isArray(pdfs.uploaded_files) ? pdfs.uploaded_files : [];
					uploads.forEach(function(f){
						if (!f || !f.url) return;
						if (approveMemo && (isSamePdfFile(f, approveMemo) || isApproveMemoUpload(f, approveMemo))) return;
						var key = normPdfUrl(f.url) || normPdfName(f.name);
						if (key && seenAttach[key]) return;
						if (key) seenAttach[key] = true;
						attachDocs += pdfLink(f.name || 'เอกสารแนบ', f.url, 'ไฟล์แนบ');
					});

					if (mainDocs || attachDocs) {
						html += '<div class="pm-bdext-section"><div class="pm-bdext-section-title"><i class="fa fa-file-alt"></i>เอกสาร</div>';
						if (mainDocs) {
							html += renderPdfGroup('เอกสารหลัก', 'is-main', mainDocs);
						}
						if (attachDocs) {
							html += renderPdfGroup('ไฟล์แนบ', 'is-attach', attachDocs);
						}
						html += '</div>';
					}
					var proc = Array.isArray(pdfs.procurement) ? pdfs.procurement : [];
					if (proc.length) {
						html += '<div class="pm-bdext-section"><div class="pm-bdext-section-title"><i class="fa fa-shopping-cart"></i>เอกสารจัดซื้อจัดจ้าง</div>';
						proc.forEach(function(p){
							html += '<div class="pm-bdext-proc">';
							html += '<div class="pm-bdext-proc-label">' + escHtml(p.type_label || 'รายการจัดซื้อจัดจ้าง') + '</div>';
							var procMain = '';
							var procAttach = '';
							var seenProc = {};
							var procMainRef = p.pdf_url ? { url: p.pdf_url, name: p.type_label || 'เอกสารจัดซื้อจัดจ้าง' } : null;
							if (p.pdf_url) {
								var procMainName = p.type_label || 'เอกสารจัดซื้อจัดจ้าง';
								procMain += pdfLink(procMainName, p.pdf_url, 'เอกสารจัดซื้อจัดจ้าง');
								var mainKey = normPdfUrl(p.pdf_url) || normPdfName(procMainName);
								if (mainKey) seenProc[mainKey] = true;
							}
							var att = Array.isArray(p.attachments) ? p.attachments : [];
							att.forEach(function(f){
								if (!f || !f.url) return;
								if (procMainRef && isSamePdfFile(f, procMainRef)) return;
								var key = normPdfUrl(f.url) || normPdfName(f.name);
								if (key && seenProc[key]) return;
								if (key) seenProc[key] = true;
								procAttach += pdfLink(f.name || 'เอกสารแนบ', f.url, 'ไฟล์แนบ');
							});
							if (procMain) {
								html += renderPdfGroup('เอกสารจัดซื้อจัดจ้าง', 'is-main', procMain);
							}
							if (procAttach) {
								html += renderPdfGroup('ไฟล์แนบ', 'is-attach', procAttach);
							}
							html += '</div>';
						});
						html += '</div>';
					}
					if (!html) {
						html = '<div class="pm-bdext-section"><div class="pm-bdext-empty"><i class="fa fa-info-circle mr-1"></i>ไม่มีเอกสาร PDF ในระบบเบิกจ่าย</div></div>';
					}
					return html;
				}
				function renderWithdrawDetail(res){
					var w = (res && res.withdraw) ? res.withdraw : {};
					var line = (res && res.line) ? res.line : {};
					var rawSt = String(w.raw_status || '');
					var stLabel = String(w.status || rawSt || '-');
					var reconcile = String((res && res.reconcile) || '');
					var fromLocal = !!(w.from_local || reconcile === 'pending_handoff' || reconcile === 'confirmed_no_withdraw');
					var html = '';

					html += '<div class="pm-bdext-hero">';
					html += '<div class="pm-bdext-hero-top">';
					html += '<div class="pm-bdext-hero-subject">' + escHtml(w.subject || line.line_detail || 'รายการเบิกจ่าย') + '</div>';
					html += '<div class="pm-bdext-hero-amount">' + fmtMoney(w.amount != null ? w.amount : line.amount) + ' <small class="text-muted font-weight-bold">บาท</small></div>';
					html += '</div>';
					html += '<div class="pm-bdext-hero-meta">';
					html += '<span class="pm-bdext-status ' + statusClass(rawSt) + '"><i class="fa fa-flag"></i>' + escHtml(stLabel) + '</span>';
					if (w.date || line.confirmed_at) {
						html += '<span class="pm-bdext-chip"><i class="fa fa-calendar-alt"></i>' + escHtml(fmtThaiDateTime(w.date || line.confirmed_at)) + '</span>';
					}
					html += '<span class="pm-bdext-chip"><i class="fa fa-barcode"></i>' + escHtml(res.project_code || w.project_code || '-') + '</span>';
					html += '</div>';
					if (fromLocal) {
						html += '<div class="pm-bdext-local-note mt-2"><i class="fa fa-info-circle mr-1"></i>';
						if (reconcile === 'pending_handoff') {
							html += 'ยืนยันในรายงานการใช้จ่ายแล้ว แต่ยังรอบันทึกเอกสารในระบบเบิกจ่าย';
						} else if (reconcile === 'confirmed_no_withdraw') {
							html += 'ยืนยันในรายงานการใช้จ่ายแล้ว ยังไม่พบรายการในระบบเบิกจ่าย';
						} else {
							html += 'แสดงจากข้อมูลที่ยืนยันในระบบโครงการ';
						}
						html += '</div>';
					}
					html += '</div>';

					html += '<div class="pm-bdext-grid">';
					if (w.project_name || res.project_name) {
						html += '<div class="pm-bdext-info-card"><div class="pm-bdext-info-label">ชื่อโครงการ</div><div class="pm-bdext-info-value">' + escHtml(w.project_name || res.project_name || '') + '</div></div>';
					}
					if (line.activity_name || w.project_activity_name) {
						html += '<div class="pm-bdext-info-card"><div class="pm-bdext-info-label">กิจกรรม</div><div class="pm-bdext-info-value">' + escHtml(line.activity_name || w.project_activity_name || '') + '</div></div>';
					}
					if (line.line_detail) {
						html += '<div class="pm-bdext-info-card"><div class="pm-bdext-info-label">รายการในโครงการ</div><div class="pm-bdext-info-value">' + escHtml(line.line_detail) + '</div></div>';
					}
					if (line.disburse_month_label || line.disburse_month) {
						html += '<div class="pm-bdext-info-card"><div class="pm-bdext-info-label">เดือนเบิกจ่าย</div><div class="pm-bdext-info-value">' + escHtml(line.disburse_month_label || line.disburse_month) + '</div></div>';
					}
					if (line.confirmed_at) {
						html += '<div class="pm-bdext-info-card"><div class="pm-bdext-info-label">วันที่ยืนยันในระบบโครงการ</div><div class="pm-bdext-info-value">' + escHtml(fmtThaiDateTime(line.confirmed_at)) + '</div></div>';
					}
					if (line.activity_detail || w.project_activity_detail) {
						html += '<div class="pm-bdext-info-card pm-bdext-info-card-wide"><div class="pm-bdext-info-label">รายละเอียดการจัดกิจกรรม</div><div class="pm-bdext-info-value">' + escHtml(line.activity_detail || w.project_activity_detail || '') + '</div></div>';
					}
					html += '</div>';

					var items = Array.isArray(w.items) ? w.items : [];
					if ((!items.length) && res && Array.isArray(res.batch_lines) && res.batch_lines.length) {
						items = res.batch_lines;
					}
					if (items.length) {
						var itemsTitle = 'รายการค่าใช้จ่ายที่เบิกจ่าย';
						if (items.length > 1) {
							itemsTitle += ' (' + items.length + ' รายการ)';
						}
						html += '<div class="pm-bdext-section"><div class="pm-bdext-section-title"><i class="fa fa-list"></i>' + escHtml(itemsTitle) + '</div>';
						html += '<div class="table-responsive"><table class="pm-bdext-items-table"><thead><tr><th>รายการ</th><th class="text-right">จำนวนเงิน (บาท)</th></tr></thead><tbody>';
						var sumAmt = 0;
						items.forEach(function(it){
							var nm = escHtml(it.name || '-');
							if (it.category) nm += ' <span class="text-muted">(' + escHtml(it.category) + ')</span>';
							sumAmt += parseFloat(it.amount) || 0;
							html += '<tr><td>' + nm + '</td><td class="amt">' + fmtMoney(it.amount) + '</td></tr>';
						});
						if (items.length > 1) {
							html += '<tr class="pm-bdext-items-total"><td><strong>รวม</strong></td><td class="amt"><strong>' + fmtMoney(sumAmt) + '</strong></td></tr>';
						}
						html += '</tbody></table></div></div>';
					}

					var steps = Array.isArray(w.approval_steps) ? w.approval_steps : [];
					if (steps.length) {
						html += '<div class="pm-bdext-section"><div class="pm-bdext-section-title"><i class="fa fa-tasks"></i>ลำดับการอนุมัติ</div><ul class="pm-bdext-steps">';
						steps.forEach(function(s, idx){
							var info = stepInfo(s.status);
							html += '<li class="pm-bdext-step ' + info.cls + '">';
							html += '<span class="pm-bdext-step-no">' + (idx + 1) + '</span>';
							html += '<div class="pm-bdext-step-body">';
							html += '<div class="pm-bdext-step-name">' + escHtml(s.step_name || s.step_code || ('ขั้นตอนที่ ' + (idx + 1))) + '</div>';
							html += '<div class="pm-bdext-step-meta">';
							if (s.staff_name) {
								html += '<span class="pm-bdext-chip"><i class="fa fa-user"></i>' + escHtml(s.staff_name) + '</span>';
							}
							if (s.approved_at) {
								html += '<span class="pm-bdext-chip"><i class="fa fa-calendar-check"></i>' + escHtml(fmtThaiDateTime(s.approved_at)) + '</span>';
							}
							html += '</div>';
							html += '</div>';
							html += '<span class="pm-bdext-step-badge ' + info.cls + '"><i class="fa ' + info.icon + '"></i>' + escHtml(info.label) + '</span>';
							html += '</li>';
						});
						html += '</ul></div>';
					}

					html += renderPdfSection(w.pdfs || {});
					return html;
				}
				function pmHideExtModal(){
					try { $modal.modal('hide'); } catch(err) {}
					$modal.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
					if (!$('.modal.show, .modal.in').not($modal).length) {
						$('body').removeClass('modal-open').css('padding-right', '');
						$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
					}
				}
				function pmOpenExtModal(){
					try { $modal.appendTo('body'); } catch(err) {}
					try {
						$modal.modal({ backdrop: true, keyboard: true, show: true });
					} catch(err) {
						$modal.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
						if (!$('.modal-backdrop').not('.pm-activity-disburse-backdrop').length) {
							$('body').append('<div class="modal-backdrop fade show"></div>');
						}
						$('body').addClass('modal-open');
					}
				}
				function showError(msg){
					$('#modalBudgetDisburseExternalBody').html('<div class="alert alert-danger mb-0">' + escHtml(msg || 'โหลดข้อมูลไม่สำเร็จ') + '</div>');
					setWithdrawOpenButton('', '');
				}
				function setWithdrawOpenButton(url, reconcile){
					url = String(url || '').trim();
					reconcile = String(reconcile || '').trim();
					var $btn = $('#btnBudgetDisburseExternalOpenSystem');
					if (!$btn.length) return;
					if (url) {
						$modal.data('withdraw-open-url', url);
						var label = (reconcile === 'pending_handoff')
							? '<i class="fa fa-external-link-alt mr-1"></i> ทำเอกสารในระบบเบิกจ่ายต่อ'
							: '<i class="fa fa-external-link-alt mr-1"></i> เปิดในระบบเบิกจ่าย';
						$btn.html(label).removeClass('d-none').prop('disabled', false);
					} else {
						$modal.removeData('withdraw-open-url');
						$btn.addClass('d-none').prop('disabled', true);
					}
				}
				function openExternalDoc(lineId, docLabel){
					lineId = parseInt(lineId || '0', 10);
					if (!lineId) return;
					if (!$modal.length) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'info', title: 'ไม่พบหน้าต่างรายละเอียด' });
						return;
					}
					var title = (docLabel || 'รายละเอียดการเบิกจ่าย').toString();
					$('#modalBudgetDisburseExternalTitle').text(title);
					$('.pm-bdext-header-sub').text('รายการที่ยืนยันจากรายงานการใช้จ่าย');
					$('#modalBudgetDisburseExternalBody').html('<div class="text-center text-muted py-4"><i class="fa fa-spinner fa-spin mr-1"></i> กำลังโหลดรายการเบิกจ่าย...</div>');
					setWithdrawOpenButton('', '');
					pmOpenExtModal();
					$.ajax({
						url: '?page=project_manage&op=get_budget_disburse_external_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId, line_id: lineId }
					}).done(function(res){
						if (res && res.ok === 1) {
							$('#modalBudgetDisburseExternalBody').html(renderWithdrawDetail(res));
							var openUrl = (res.open_url || res.withdraw_system_url || res.resume_url || '');
							setWithdrawOpenButton(openUrl, res.reconcile || '');
							return;
						}
						showError((res && res.msg) ? res.msg : 'โหลดข้อมูลไม่สำเร็จ');
					}).fail(function(xhr){
						var msg = 'เชื่อมต่อไม่สำเร็จ';
						try {
							var j = JSON.parse(xhr.responseText || '{}');
							if (j && j.msg) msg = j.msg;
						} catch (e) {}
						showError(msg);
					});
				}
				$(document).on('click', '#btnBudgetDisburseExternalOpenSystem', function(e){
					e.preventDefault();
					var url = String($modal.data('withdraw-open-url') || '').trim();
					if (!url) return;
					try {
						window.open(url, '_blank', 'noopener');
					} catch (err) {
						window.location.href = url;
					}
				});
				$(document).on('click', '.pm-ber-disburse-doc-btn', function(e){
					e.preventDefault();
					e.stopPropagation();
					var $btn = $(this);
					openExternalDoc($btn.attr('data-line-id'), $btn.attr('data-doc-label') || 'รายละเอียดการเบิกจ่าย');
				});
				$(document).on('click', '#modalBudgetDisburseExternal .pm-budget-disburse-ext-close', function(e){
					e.preventDefault();
					pmHideExtModal();
				});
			})();

			(function initBudgetOtherActions(){
				var actionLabels = { loan: 'ขอยืมเงิน', travel: 'ขออนุมัติเดินทาง' };
				function confirmCreateOtherAction(actionType, $btn){
					if (!projectId) return;
					var label = actionLabels[actionType] || 'รายการนี้';
					var doCreate = function(){
						$btn.prop('disabled', true);
						$.ajax({
							url: '?page=project_manage&op=create_budget_other_action_ajax',
							type: 'POST',
							dataType: 'json',
							data: { project_id: projectId, action_type: actionType }
						}).done(function(res){
							if (res && res.ok === 1) {
								loadBudgetTable();
								var msg = (res && res.msg) ? res.msg : 'สร้างรายการสำเร็จ';
								if (typeof Swal !== 'undefined') Swal.fire({ icon: 'success', title: msg, timer: 1800, showConfirmButton: false });
								else alert(msg);
								return;
							}
							var err = (res && res.msg) ? res.msg : 'สร้างรายการไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: err });
							else alert(err);
						}).fail(function(){
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
							else alert('เชื่อมต่อไม่สำเร็จ');
						}).always(function(){
							$btn.prop('disabled', false);
						});
					};
					var confirmText = 'ต้องการสร้างรายการ' + label + ' หรือไม่?\nระบบจะส่งคำขอไประบบทันที พร้อมดึงชื่อโครงการและแหล่งงบประมาณ';
					if (typeof Swal !== 'undefined') {
						Swal.fire({
							icon: 'question',
							title: 'ยืนยันสร้างรายการ',
							text: confirmText,
							showCancelButton: true,
							confirmButtonText: 'ใช่',
							cancelButtonText: 'ยกเลิก'
						}).then(function(r){ if (r.isConfirmed) doCreate(); });
					} else if (confirm(confirmText)) {
						doCreate();
					}
				}
				$(document).on('click', '.pm-budget-other-action-create', function(e){
					e.preventDefault();
					if (pmBudgetDisburseBlocked()) return;
					var $btn = $(this);
					var actionType = ($btn.attr('data-action-type') || '').toString();
					if (actionType !== 'loan' && actionType !== 'travel') return;
					confirmCreateOtherAction(actionType, $btn);
				});
			})();

			(function initProjectEvaluation(){
				var $modal = $('#modalProjectEvaluation');
				var $btnOpen = $('#btnOpenProjectEvaluation');
				if (!$modal.length || !$btnOpen.length) return;

				function escHtml(s){
					return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
				}
				function nl2brEsc(s){
					return escHtml(s).replace(/\r\n|\r|\n/g, '<br>');
				}
				function pmHideProjectEvalModal(){
					try { $modal.modal('hide'); } catch(err) {}
					$modal.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
					if (!$('.modal.show, .modal.in').not($modal).length) {
						$('body').removeClass('modal-open').css('padding-right', '');
						$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
					}
				}
				function pmOpenProjectEvalModal(){
					try { $modal.appendTo('body'); } catch(err) {}
					try {
						$modal.modal({ backdrop: true, keyboard: true, show: true });
					} catch(err) {
						$modal.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
						if (!$('.modal-backdrop').not('.pm-activity-disburse-backdrop').length) {
							$('body').append('<div class="modal-backdrop fade show"></div>');
						}
						$('body').addClass('modal-open');
					}
				}
				function kpiPctTone(pct){
					if (pct === null || pct === undefined || pct === '') return 'is-empty';
					var v = parseFloat(pct);
					if (isNaN(v)) return 'is-empty';
					if (v >= 100) return 'is-exact';
					if (v >= 80) return 'is-over';
					return 'is-under';
				}
				function fillKpiSummary(summary){
					summary = summary || {};
					var pct = summary.overall_percent;
					var $pct = $('#pmProjectEvalKpiOverall');
					if (pct === null || pct === undefined || pct === '') {
						$pct.text('-').attr('class', 'pm-project-eval-kpi-pct is-empty');
					} else {
						$pct.text(String(pct)).attr('class', 'pm-project-eval-kpi-pct ' + kpiPctTone(pct));
					}
					var $lines = $('#pmProjectEvalKpiLines');
					$lines.empty();
					var items = Array.isArray(summary.lines) ? summary.lines : [];
					if (!items.length) {
						$lines.append('<li class="pm-project-eval-kpi-line"><span class="pm-project-eval-kpi-line-name text-muted">-</span></li>');
						return;
					}
					items.forEach(function(it, idx){
						var name = it.name || '';
						var plan = it.plan !== undefined ? it.plan : 0;
						var result = it.result !== undefined ? it.result : 0;
						if (!name && it.text) {
							$lines.append('<li class="pm-project-eval-kpi-line"><span class="pm-project-eval-kpi-line-name">' + escHtml(it.text) + '</span></li>');
							return;
						}
						var html = '<li class="pm-project-eval-kpi-line">'
							+ '<span class="pm-project-eval-kpi-line-name">' + escHtml((idx + 1) + '. ' + name) + '</span>'
							+ '<span class="pm-project-eval-kpi-line-stats">'
							+ '<span class="pm-project-eval-kpi-stat is-plan"><i class="fa fa-bullseye"></i> เป้า ' + escHtml(String(plan)) + '</span>'
							+ '<span class="pm-project-eval-kpi-stat is-result"><i class="fa fa-check"></i> ผล ' + escHtml(String(result)) + '</span>'
							+ '</span></li>';
						$lines.append(html);
					});
				}
				function fillEvalForm(data){
					data = data || {};
					var st = (data.overall_status || '').toString();
					$('input[name="pmProjectEvalOverall"]').prop('checked', false);
					if (st === 'achieved') $('#pmProjectEvalAchieved').prop('checked', true);
					if (st === 'not_achieved') $('#pmProjectEvalNotAchieved').prop('checked', true);
					$('#pmProjectEvalProblem').val(data.problem_obstacle || '');
					$('#pmProjectEvalSolution').val(data.solution_suggestion || '');
				}
				function updateEvalSummaryOnPage(data){
					data = data || {};
					var st = (data.overall_status || '').toString();
					var stText = st === 'achieved' ? 'บรรลุ' : (st === 'not_achieved' ? 'ไม่บรรลุ' : '-');
					var stClass = st === 'achieved' ? 'is-achieved' : (st === 'not_achieved' ? 'is-not-achieved' : '');
					$('#pmProjectEvalSummaryStatus').text(stText).attr('class', 'pm-project-eval-summary-badge ' + stClass);
					$('#pmProjectEvalSummaryProblem').html(nl2brEsc(data.problem_obstacle || ''));
					$('#pmProjectEvalSummarySolution').html(nl2brEsc(data.solution_suggestion || ''));
					$('#pmProjectEvalSummaryWrap').removeClass('d-none');
					$('#pmProjectEvalRequiredAlert').addClass('d-none');
					$btnOpen
						.removeClass('btn-primary pm-project-eval-btn-required')
						.addClass('btn-pm-edit-orange')
						.html('<i class="fa fa-edit mr-1"></i> ประเมินผลโครงการ');
				}
				function loadProjectEvaluation(){
					if (!projectId) return;
					$btnOpen.prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=get_project_evaluation_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId }
					}).done(function(res){
						if (!res || res.ok !== 1) {
							var msg = (res && res.msg) ? res.msg : 'โหลดข้อมูลการประเมินผลไม่สำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: msg });
							else alert(msg);
							return;
						}
						fillKpiSummary(res.kpi_summary || {});
						fillEvalForm(res.data || {});
						pmOpenProjectEvalModal();
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
						else alert('เชื่อมต่อไม่สำเร็จ');
					}).always(function(){
						$btnOpen.prop('disabled', false);
					});
				}
				function saveProjectEvaluation(){
					if (!projectId) return;
					var overall = ($('input[name="pmProjectEvalOverall"]:checked').val() || '').toString();
					var problem = ($('#pmProjectEvalProblem').val() || '').trim();
					var solution = ($('#pmProjectEvalSolution').val() || '').trim();
					if (overall !== 'achieved' && overall !== 'not_achieved') {
						var msgPick = 'กรุณาเลือกการประเมินภาพรวมของโครงการ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: msgPick });
						else alert(msgPick);
						return;
					}
					if (overall === 'not_achieved' && (!problem || !solution)) {
						var msgReq = 'กรุณาระบุปัญหา/อุปสรรค และแนวทางแก้ไขเมื่อเลือกไม่บรรลุ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: msgReq });
						else alert(msgReq);
						return;
					}
					$('#btnSaveProjectEvaluation').prop('disabled', true);
					$.ajax({
						url: '?page=project_manage&op=save_project_evaluation_ajax',
						type: 'POST',
						dataType: 'json',
						data: {
							project_id: projectId,
							overall_status: overall,
							problem_obstacle: problem,
							solution_suggestion: solution
						}
					}).done(function(res){
						if (res && res.ok === 1) {
							pmHideProjectEvalModal();
							updateEvalSummaryOnPage({
								overall_status: overall,
								problem_obstacle: problem,
								solution_suggestion: solution
							});
							if (typeof window.pmRefreshFinishReportButtons === 'function') {
								window.pmRefreshFinishReportButtons();
							}
							var msg = (res && res.msg) ? res.msg : 'บันทึกสำเร็จ';
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'success', title: msg, timer: 1800, showConfirmButton: false });
							else alert(msg);
							return;
						}
						var err = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: err });
						else alert(err);
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'บันทึกไม่สำเร็จ' });
						else alert('บันทึกไม่สำเร็จ');
					}).always(function(){
						$('#btnSaveProjectEvaluation').prop('disabled', false);
					});
				}

				$btnOpen.on('click', function(e){
					e.preventDefault();
					loadProjectEvaluation();
				});
				$('#btnSaveProjectEvaluation').on('click', function(e){
					e.preventDefault();
					saveProjectEvaluation();
				});
				$(document).on('click', '#modalProjectEvaluation .pm-project-eval-close', function(e){
					e.preventDefault();
					pmHideProjectEvalModal();
				});
				$modal.on('hidden.bs.modal', function(){
					if (!$('.modal.show, .modal.in').length) {
						$('body').removeClass('modal-open').css('padding-right', '');
						$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
					}
				});
			})();
			<?php endif; ?>

			<?php if (!empty($pm_can_fill_project_results)): ?>
			function applyResultReportFreeze(){
				if (!window.PM_CAN_FILL_PROJECT_RESULTS) return;
				if (!window.PM_RESULT_REPORT_LOCKED && !window.PM_RESULT_REPORT_COMPLETE) return;
				$('.pm-wizard').addClass('pm-submitted-lock pm-result-report-lock');
				$('#btnToggleHeaderEdit, .pm-save-btn').addClass('d-none');
				$('.btn-kpi-fill-result, .btn-kpi-edit-result, .btn-activity-fill-result, .btn-activity-edit-result, .pm-budget-disburse-open, .pm-ber-disburse-btn, .pm-budget-disburse-edit, .pm-ber-line-edit-btn, .pm-budget-other-action-create, .pm-budget-other-action-btn, #btnOpenProjectEvaluation, #btnSaveProjectEvaluation').prop('disabled', true).addClass('pm-result-report-locked');
				if (typeof lockAddEditButtons === 'function') {
					lockAddEditButtons();
				}
			}
			window.pmApplyResultReportFreezeUi = applyResultReportFreeze;
			applyResultReportFreeze();
			<?php endif; ?>

			window.pmFmtBudgetNum = function(n, emptyZero){
				var v = parseFloat(n);
				if (isNaN(v)) v = 0;
				if (emptyZero && Math.abs(v) < 1e-9) return '';
				var rounded = Math.round(v * 100) / 100;
				if (Math.abs(rounded - Math.round(rounded)) < 1e-9) {
					return Math.round(rounded).toLocaleString('en-US', { maximumFractionDigits: 0 });
				}
				return rounded.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
			};
			function loadBudgetTable(){
				var $wrap = $('#budget-table-wrap');
				if (!$wrap.length) return;
				$wrap.html('<small class="text-muted">กำลังโหลด...</small>');
				$.ajax({
					url: '?page=project_manage&op=render_budget_table',
					type: 'POST',
					dataType: 'json',
					data: { project_id: projectId }
				}).done(function(res){
					if (res && res.ok === 1) {
						$wrap.html(res.html || '');
						if (typeof pmShowBudgetItemsBanner === 'function') {
							pmShowBudgetItemsBanner((res && res.budget_warning) ? String(res.budget_warning) : '');
						}
						var sum = 0;
						var allNoExpense = Number(res.all_no_expense || 0) === 1;
						if (res.report_mode === 1) {
							var $totalRow = $wrap.find('tr.pm-ber-total-row td').eq(1);
							var totalTxt = ($totalRow.text() || '').replace(/,/g,'').trim();
							sum = parseFloat(totalTxt);
							if (isNaN(sum)) sum = 0;
						} else {
							if (typeof res.budget_money_sum !== 'undefined') {
								sum = parseFloat(res.budget_money_sum);
								if (isNaN(sum)) sum = 0;
							} else {
								$wrap.find('tbody tr.pm-budget-item-row').each(function(){
									var txt = ($(this).find('td').eq(1).find('.font-weight-bold').first().text() || '').replace(/,/g,'').trim();
									var v = parseFloat(txt);
									if (!isNaN(v)) sum += v;
								});
							}
							if (!allNoExpense && Number(res.budget_items_count || 0) > 0 && Math.abs(sum) < 1e-9) {
								allNoExpense = true;
							}
						}
						if (allNoExpense) {
							$('#pm-budget-grand-total').text('ไม่มีค่าใช้จ่าย');
							$('#pm-budget-grand-unit').text('');
						} else {
							$('#pm-budget-grand-total').text(window.pmFmtBudgetNum(sum));
							$('#pm-budget-grand-unit').text(' บาท');
						}
						var hasItems = res.report_mode === 1
							? ($wrap.find('tbody tr.pm-ber-item-row').length > 0)
							: ($wrap.find('tbody tr.pm-budget-item-row').length > 0);
						setStepCircle('#step-s5-circle', !!hasItems);
						if (typeof window.pmApplyResultReportFreezeUi === 'function') {
							window.pmApplyResultReportFreezeUi();
						} else if (window.PM_INCLUDE_MEETING_LOCK || window.PM_PLAN_FIX_RESUBMIT_LOCK || window.PM_OPERATE_REPLY_LOCK || (!window.PM_PLAN_ADMIN && isSubmittedNow())) {
							lockAddEditButtons();
						}
						return;
					}
					var errMsg = (res && res.msg) ? String(res.msg) : 'โหลดไม่สำเร็จ';
					$wrap.html('<div class="text-danger">' + errMsg.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</div>');
				}).fail(function(xhr){
					var errMsg = 'โหลดไม่สำเร็จ';
					try {
						var j = JSON.parse(xhr.responseText || '{}');
						if (j && j.msg) errMsg = String(j.msg);
					} catch (e) {}
					$wrap.html('<div class="text-danger">' + errMsg.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</div>');
				});
			}

			function openEditActivity(payload){
				resetActivityModal();
				var $f = $('#formActivityProject');
				$f.find('input[name="type"]').val('update');
				$f.find('input[name="project_activity_id"]').val(payload.id || 0);
				$f.find('input[name="activity_no"]').val(payload.activity_no || '');
				$f.find('input[name="activity_name"]').val(payload.activity_name || '');
				$f.find('textarea[name="activity_detail"]').val(payload.activity_detail || '');
				if ($f.find('input[name="activity_budget"]').length) {
					$f.find('input[name="activity_budget"]').val(payload.activity_budget || '');
				}
				$f.find('input[name="activity_weight"]').val(payload.activity_weight || '');

				if (payload.months) {
					Object.keys(payload.months).forEach(function(k){
						$f.find('input[type="checkbox"][name="'+k+'"]').prop('checked', !!payload.months[k]);
					});
				}

				var $c = $('#activityTargetContainer');
				// ใช้ template row ก่อนเคลียร์ container (กันกรณี clone ไม่เจอ)
				var $tpl = $c.find('.pm-target-row').first().clone();
				$c.empty();
				var targets = (payload.targets && payload.targets.length) ? payload.targets : [{code_target:'', target_amount:''}];
				targets.forEach(function(t, idx){
					var $row = $tpl.clone();
					$row.find('select[name="target_group[]"]').val(t.code_target || '');
					$row.find('input[name="target_amount[]"]').val(t.target_amount || '');
					var $btn = $row.find('button');
					if (idx === targets.length - 1) {
						$btn.attr('data-action','add-target-row').removeClass('btn-outline-danger').addClass('btn-outline-primary').html('<i class="fa fa-plus mr-1"></i> เพิ่ม');
					} else {
						$btn.attr('data-action','remove-target-row').removeClass('btn-outline-primary').addClass('btn-outline-danger').html('<i class="fa fa-trash mr-1"></i> ลบ');
					}
					$c.append($row);
				});
			}

