			$('#formActivityProject').on('submit', function(e){
				e.preventDefault();
				var $f = $(this);
				var actW = parseFloat(String($f.find('[name="activity_weight"]').val() || '0').replace(/,/g, '')) || 0;
				if (actW < 0 || actW > 100) {
					var actMsg = 'ค่าน้ำหนักกิจกรรมต้องอยู่ระหว่าง 0-100';
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon: 'warning', title: 'ค่าน้ำหนักไม่ถูกต้อง', text: actMsg });
					} else {
						alert(actMsg);
					}
					return;
				}
				var data = $f.serialize();
				var monKeys = ['mon_10','mon_11','mon_12','mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09'];
				var monthlySum = 0;
				monKeys.forEach(function(k){
					var v = parseFloat(String($f.find('[name="'+k+'"]').val() || '0').replace(/,/g,'')) || 0;
					monthlySum += v;
				});
				var itemLimit = parseFloat(String($('#budgetPlanItemTotal').val() || '0').replace(/,/g,'')) || 0;
				if (itemLimit > 0 && monthlySum > (itemLimit + 0.0001)) {
					if (typeof Swal !== 'undefined') Swal.fire({icon:'warning', title:'ยอดเกินวงเงินรวม', text:'ยอดแผนรายเดือนต้องไม่เกินวงเงินรวมของรายการค่าใช้จ่าย'});
					else alert('ยอดแผนรายเดือนต้องไม่เกินวงเงินรวมของรายการค่าใช้จ่าย');
					return;
				}
				$f.find('button[type="submit"]').prop('disabled', true);
				$.ajax({
					url: '?page=project_manage&op=save_data_activity_project_ajax',
					type: 'POST',
					dataType: 'json',
					data: data
				}).done(function(res){
					if (res && res.ok === 1) {
						if (typeof Swal !== 'undefined') Swal.fire({icon:'success', title:'บันทึกสำเร็จ', timer:900, showConfirmButton:false});
						forceHideActivityModal();
						loadActivityTable();
						loadBudgetTable();
						return;
					}
					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'บันทึกไม่สำเร็จ', text: msg});
					else alert(msg);
				}).fail(function(){
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'เกิดข้อผิดพลาด', text:'บันทึกไม่สำเร็จ'});
				}).always(function(){
					$f.find('button[type="submit"]').prop('disabled', false);
				});
			});

