			function resetBudgetItemForm(){
				var $f = $('#formBudgetItem');
				if (!$f.length) return;
				$f[0].reset();
				$f.find('input[name="type"]').val('insert');
				$f.find('input[name="project_activity_budget_id"]').val('0');
				$f.find('select[name="code_expenses_detail"]').html('<option value="">- เลือก -</option>');
				$('#pmExpenseConditionBox').empty();
				pmApplyNoExpenseBudgetMode(false);
			}

			function pmIsNoExpenseCategorySelected(){
				var $opt = $('#formBudgetItem select[name="code_expenses"] option:selected');
				if (!$opt.length) return false;
				if (String($opt.attr('data-no-expense') || '') === '1') return true;
				var txt = String($opt.text() || '').trim();
				return txt.indexOf('ไม่มีค่าใช้จ่าย') !== -1 || txt.indexOf('ไม่ใช้งบประมาณ') !== -1;
			}

			function pmApplyNoExpenseBudgetMode(on){
				var $f = $('#formBudgetItem');
				if (!$f.length) return;
				on = !!on;
				$f.toggleClass('pm-budget-no-expense-mode', on);
				$('#pmBudgetNoExpenseHint').toggleClass('d-none', !on);
				$f.find('.pm-budget-item-extra-field').toggleClass('d-none', on);
				var $detail = $f.find('select[name="code_expenses_detail"]');
				if (on) {
					$detail.prop('required', false);
					$f.find('input[name="budget_item"]').val('');
					$f.find('input[name="price"]').val('0');
					$f.find('input[name="qty1"]').val('0');
					$f.find('input[name="qty2"]').val('0');
					$f.find('input[name="unit1"]').val('');
					$f.find('input[name="unit2"]').val('');
					$f.find('input[name="total"]').val('0');
					$('#pmExpenseConditionBox').empty();
				} else {
					$detail.prop('required', true);
				}
			}

			function pmBudgetUnitSuggestList(){
				var out = [];
				var seen = {};
				try {
					var local = JSON.parse(localStorage.getItem('pmBudgetUnits') || '[]');
					if (Array.isArray(local)) {
						local.forEach(function(u){
							u = String(u || '').trim();
							if (u && !seen[u]) { seen[u] = true; out.push(u); }
						});
					}
				} catch (e) {}
				$('#pm-budget-unit-suggest option').each(function(){
					var u = String($(this).attr('value') || '').trim();
					if (u && !seen[u]) { seen[u] = true; out.push(u); }
				});
				return out;
			}
			function pmFillBudgetUnitDatalist(units){
				var $dl = $('#pm-budget-unit-suggest');
				if (!$dl.length) return;
				var seen = {};
				$dl.empty();
				(units || []).forEach(function(u){
					u = String(u || '').trim();
					if (!u || seen[u]) return;
					seen[u] = true;
					$dl.append($('<option>').attr('value', u));
				});
			}
			function pmAddBudgetUnitSuggest(u){
				u = String(u || '').trim();
				if (!u) return;
				var $dl = $('#pm-budget-unit-suggest');
				if ($dl.length) {
					var exists = false;
					$dl.find('option').each(function(){
						if (String($(this).attr('value') || '') === u) { exists = true; return false; }
					});
					if (!exists) $dl.prepend($('<option>').attr('value', u));
				}
				try {
					var extra = [];
					try { extra = JSON.parse(localStorage.getItem('pmBudgetUnits') || '[]'); } catch (e) { extra = []; }
					if (!Array.isArray(extra)) extra = [];
					extra = extra.filter(function(x){ return String(x || '').trim() !== u; });
					extra.unshift(u);
					localStorage.setItem('pmBudgetUnits', JSON.stringify(extra.slice(0, 50)));
				} catch (e) {}
			}
			function pmLoadBudgetUnitSuggest(){
				$.ajax({
					url: '?page=project_manage&op=budget_unit_suggest_ajax',
					type: 'GET',
					dataType: 'json'
				}).done(function(res){
					var units = (res && res.ok === 1 && Array.isArray(res.units)) ? res.units.slice() : [];
					try {
						var local = JSON.parse(localStorage.getItem('pmBudgetUnits') || '[]');
						if (Array.isArray(local)) {
							local.slice().reverse().forEach(function(u){
								u = String(u || '').trim();
								if (u && units.indexOf(u) === -1) units.unshift(u);
							});
						}
					} catch (e) {}
					pmFillBudgetUnitDatalist(units);
				});
			}
			function pmHideBudgetUnitMenu(){
				$('.pm-unit-suggest-menu').remove();
			}
			var pmUnitSuggestTarget = null;
			function pmShowBudgetUnitMenu($inp){
				pmHideBudgetUnitMenu();
				if (!$inp || !$inp.length) return;
				pmUnitSuggestTarget = $inp;
				var q = String($inp.val() || '').trim().toLowerCase();
				var items = pmBudgetUnitSuggestList().filter(function(u){
					if (!q) return true;
					return String(u).toLowerCase().indexOf(q) !== -1;
				}).slice(0, 12);
				if (!items.length) return;
				var off = $inp.offset() || { top: 0, left: 0 };
				var $menu = $('<div class="pm-unit-suggest-menu" role="listbox"></div>');
				items.forEach(function(u, idx){
					var $it = $('<div class="pm-unit-suggest-item"></div>').text(u).attr('data-value', u);
					if (idx === 0) $it.addClass('is-active');
					$menu.append($it);
				});
				$('body').append($menu);
				$menu.css({
					top: (off.top + $inp.outerHeight() + 2) + 'px',
					left: off.left + 'px',
					width: Math.max(120, $inp.outerWidth()) + 'px'
				});
			}
			$(document).on('focus input', '#formBudgetItem input[name="unit1"], #formBudgetItem input[name="unit2"]', function(){
				pmShowBudgetUnitMenu($(this));
			});
			$(document).on('mousedown', '.pm-unit-suggest-item', function(e){
				e.preventDefault();
				var v = String($(this).attr('data-value') || '');
				if (pmUnitSuggestTarget && pmUnitSuggestTarget.length) {
					pmUnitSuggestTarget.val(v).trigger('change');
				}
				pmHideBudgetUnitMenu();
			});
			$(document).on('keydown', '#formBudgetItem input[name="unit1"], #formBudgetItem input[name="unit2"]', function(e){
				var $menu = $('.pm-unit-suggest-menu');
				if (!$menu.length) return;
				var $cur = $menu.find('.pm-unit-suggest-item.is-active');
				if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
					e.preventDefault();
					var $items = $menu.find('.pm-unit-suggest-item');
					var i = $items.index($cur);
					if (e.key === 'ArrowDown') i = Math.min($items.length - 1, i + 1);
					else i = Math.max(0, i - 1);
					$items.removeClass('is-active').eq(i).addClass('is-active');
					return;
				}
				if (e.key === 'Enter' && $cur.length) {
					e.preventDefault();
					$cur.trigger('mousedown');
					return;
				}
				if (e.key === 'Escape') pmHideBudgetUnitMenu();
			});
			$(document).on('blur', '#formBudgetItem input[name="unit1"], #formBudgetItem input[name="unit2"]', function(){
				setTimeout(pmHideBudgetUnitMenu, 120);
			});
			pmLoadBudgetUnitSuggest();
			function calcBudgetTotal(){
				var $f = $('#formBudgetItem');
				var price = parseFloat(($f.find('[name="price"]').val() || '0').replace(/,/g,'')) || 0;
				var qty1  = parseFloat(($f.find('[name="qty1"]').val() || '0').replace(/,/g,'')) || 0;
				var qty2  = parseFloat(($f.find('[name="qty2"]').val() || '0').replace(/,/g,'')) || 0;
				var total = price * qty1 * (qty2 ? qty2 : 1);
				var totalTxt = '0';
				if (total) {
					var rounded = Math.round(total * 100) / 100;
					totalTxt = (Math.abs(rounded - Math.round(rounded)) < 1e-9)
						? String(Math.round(rounded))
						: rounded.toFixed(2);
				}
				$f.find('[name="total"]').val(totalTxt);
			}

			$(document).on('input', '#formBudgetItem .pm-money', calcBudgetTotal);

			function populateExpenseDetailOptions(code, selectedId){
				var $detail = $('#formBudgetItem select[name="code_expenses_detail"]');
				$detail.html('<option value="">กำลังโหลด...</option>');
				if (!code) {
					$detail.html('<option value="">- เลือก -</option>');
					pmApplyNoExpenseBudgetMode(false);
					return;
				}
				var noExpense = pmIsNoExpenseCategorySelected();
				$.ajax({
					url: '?page=project_manage&op=get_expense_detail_ajax',
					type: 'POST',
					dataType: 'json',
					data: { code_expenses: code }
				}).done(function(list){
					var html = '<option value="">- เลือก -</option>';
					var hasSelected = false;
					var firstId = '';
					if (Array.isArray(list) && list.length) {
						list.forEach(function(it){
							var vid = String(it.id || '');
							if (!firstId && vid) firstId = vid;
							if (selectedId !== undefined && selectedId !== null && selectedId !== '' && vid === String(selectedId)) {
								hasSelected = true;
							}
							html += '<option value="'+vid+'">'+$('<div>').text(it.name||'').html()+'</option>';
						});
					} else {
						html += '<option value="" disabled>ไม่พบประเภทค่าใช้จ่ายในหมวดนี้</option>';
					}
					$detail.html(html);
					if (noExpense) {
						var pick = (selectedId !== undefined && selectedId !== null && selectedId !== '')
							? String(selectedId)
							: firstId;
						if (pick) {
							$detail.val(pick);
							if ($detail.val() !== pick) {
								$detail.append('<option value="'+pick+'" selected>ไม่มีค่าใช้จ่าย</option>');
							}
						} else {
							$detail.html('<option value="0" selected>ไม่มีค่าใช้จ่าย</option>');
						}
						pmApplyNoExpenseBudgetMode(true);
						return;
					}
					if (selectedId !== undefined && selectedId !== null && selectedId !== '') {
						$detail.val(String(selectedId));
						if (!hasSelected && $detail.val() !== String(selectedId)) {
							$detail.append('<option value="'+String(selectedId)+'" selected>(รายการเดิม)</option>');
						}
						$detail.trigger('change');
					} else {
						$('#pmExpenseConditionBox').empty();
					}
					pmApplyNoExpenseBudgetMode(false);
				}).fail(function(){
					$detail.html('<option value="">โหลดไม่สำเร็จ</option>');
				});
			}

			$(document).on('change', '#formBudgetItem select[name="code_expenses"]', function(){
				var code = $(this).val() || '';
				var $detail = $('#formBudgetItem select[name="code_expenses_detail"]');
				var pending = $detail.data('pending');
				$detail.removeData('pending');
				var noExpense = pmIsNoExpenseCategorySelected();
				pmApplyNoExpenseBudgetMode(noExpense);
				populateExpenseDetailOptions(code, pending);
				$('#pmExpenseConditionBox').empty();
			});
			$(document).on('change', '#formBudgetItem select[name="code_expenses_detail"]', function(){
				if (pmIsNoExpenseCategorySelected()) return;
				var detailId = $(this).val() || '';
				var $box = $('#pmExpenseConditionBox');
				$box.empty();
				if (!detailId) return;
				$.ajax({
					url: '?page=project_manage&op=get_expense_condition_ajax',
					type: 'POST',
					dataType: 'json',
					data: { id: detailId }
				}).done(function(res){
					if (!res || res.status !== 'success') return;
					var html = '<div class="alert alert-warning mb-0 py-2">';
					html += '<i class="fas fa-info-circle"></i> <b>เกณฑ์/ระเบียบ:</b><br>' + $('<div>').text(res.detail || '-').html();
					if (res.attach_url) {
						var an = $('<div>').text(res.attach_name || 'ดาวน์โหลด').html();
						var au = String(res.attach_url || '').replace(/"/g, '&quot;');
						html += '<div class="mt-1"><a href="'+au+'" target="_blank" rel="noopener"><i class="fa fa-paperclip"></i> เอกสารแนบ: '+an+'</a></div>';
					}
					html += '</div>';
					$box.html(html);
				});
			});

			$(document).on('click', '[data-action="budget-items"]', function(e){
				if (isSubmittedNow()) { e.preventDefault(); return; }
				e.preventDefault();
				var aid = parseInt($(this).attr('data-activity-id') || '0', 10);
				var nextNo = parseInt($(this).attr('data-next-no') || '1', 10);
				if (!aid) return;
				resetBudgetItemForm();
				$('#formBudgetItem input[name="project_activity_id"]').val(aid);
				$('#formBudgetItem input[name="budget_no"]').val(nextNo > 0 ? nextNo : 1); // auto แต่แก้ได้
				$('#modalActivityBudgetItems').modal('show');
