			$(document).on('click', '[data-action="budget-item-del"]', function(e){
				if (isSubmittedNow()) { e.preventDefault(); return; }
				e.preventDefault();
				var id = parseInt($(this).attr('data-id') || '0', 10);
				var aid = parseInt($(this).attr('data-activity-id') || '0', 10);
				if (!id || !aid) return;
				var doDel = function(){
					$.ajax({
						url: '?page=project_manage&op=save_activity_budget_item_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId, project_activity_id: aid, type: 'delete', project_activity_budget_id: id }
					}).done(function(res){
						if (res && res.ok === 1) {
							if (typeof Swal !== 'undefined') Swal.fire({icon:'success', title:'ลบสำเร็จ', timer:900, showConfirmButton:false});
							loadBudgetTable();
							return;
						}
						var msg = (res && res.msg) ? res.msg : 'ลบไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'ลบไม่สำเร็จ', text: msg});
						else alert(msg);
					}).fail(function(){
						if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'เกิดข้อผิดพลาด', text:'ลบไม่สำเร็จ'});
					});
				};
				if (typeof Swal !== 'undefined') {
					Swal.fire({icon:'warning', title:'ยืนยันการลบ?', showCancelButton:true, confirmButtonText:'ลบ', cancelButtonText:'ยกเลิก'})
						.then(function(r){ if (r.isConfirmed) doDel(); });
				} else {
					if (confirm('ยืนยันการลบ?')) doDel();
				}
			});

			$('#formBudgetItem').on('submit', function(e){
				e.preventDefault();
				var $f = $(this);
				if (pmIsNoExpenseCategorySelected()) {
					pmApplyNoExpenseBudgetMode(true);
					var $detail = $f.find('select[name="code_expenses_detail"]');
					if (!$detail.val()) {
						$detail.html('<option value="0" selected>ไม่มีค่าใช้จ่าย</option>');
					}
				}
				calcBudgetTotal();
				var aid = parseInt($f.find('[name="project_activity_id"]').val() || '0', 10);
				var itemId = parseInt($f.find('[name="project_activity_budget_id"]').val() || '0', 10);
				var saveType = String($f.find('[name="type"]').val() || 'insert');
				var newTotal = pmIsNoExpenseCategorySelected() ? 0 : (parseFloat($f.find('[name="total"]').val()) || 0);
				if (typeof pmCheckActivityBudgetBeforeSave === 'function') {
					var budgetErr = pmCheckActivityBudgetBeforeSave(aid, newTotal, (saveType === 'update' ? itemId : 0));
					if (budgetErr) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'งบประมาณไม่เพียงพอ', text: budgetErr });
						else alert(budgetErr);
						return;
					}
				}
				var data = $f.serialize();
				$f.find('button[type="submit"]').prop('disabled', true);
				$.ajax({
					url: '?page=project_manage&op=save_activity_budget_item_ajax',
					type: 'POST',
					dataType: 'json',
					data: data
				}).done(function(res){
					if (res && res.ok === 1) {
						if (typeof pmAddBudgetUnitSuggest === 'function') {
							pmAddBudgetUnitSuggest($f.find('[name="unit1"]').val());
							pmAddBudgetUnitSuggest($f.find('[name="unit2"]').val());
						}
						if (typeof Swal !== 'undefined') Swal.fire({icon:'success', title:'บันทึกสำเร็จ', timer:900, showConfirmButton:false});
						forceHideBudgetItemModal();
						loadBudgetTable();
						return;
					}
					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'บันทึกไม่สำเร็จ', text: msg});
					else alert(msg);
				}).fail(function(){
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'เกิดข้อผิดพลาด', text:'บันทึกไม่สำเร็จ'});
				}).always(function(){
					$f.find('button[type="submit"]').prop('disabled', false);
				});
			});

			var pmBudgetPlanMonthKeys = ['mon_10','mon_11','mon_12','mon_01','mon_02','mon_03','mon_04','mon_05','mon_06','mon_07','mon_08','mon_09'];
			window.pmGetBudgetPlanMonthsSum = function ($f) {
				var sum = 0;
				if (!$f || !$f.length) return 0;
				pmBudgetPlanMonthKeys.forEach(function (k) {
					var v = parseFloat(String($f.find('[name="' + k + '"]').val() || '').replace(/,/g, ''));
					if (!isNaN(v)) sum += v;
				});
				return sum;
			};
			window.pmUpdateBudgetPlanSummary = function () {
				var $f = $('#formBudgetPlan');
				if (!$f.length) return;
				var itemTotal = parseFloat(String($('#budgetPlanItemTotal').val() || '0').replace(/,/g, '')) || 0;
				var monthsSum = pmGetBudgetPlanMonthsSum($f);
				var fmt = function (n) {
					return (typeof window.pmFmtBudgetNum === 'function')
						? window.pmFmtBudgetNum(n)
						: n.toLocaleString('en-US', { maximumFractionDigits: 2 });
				};
				$('#budgetPlanItemTotalDisplay').text(fmt(itemTotal));
				var $sumEl = $('#budgetPlanMonthsSumDisplay');
				$sumEl.text(fmt(monthsSum));
				var over = (itemTotal > 0 && monthsSum > (itemTotal + 0.0001));
				$sumEl.toggleClass('text-danger font-weight-bold', over);
				var $alert = $('#budgetPlanOverAlert');
				if (over) {
					$('#budgetPlanOverAlertText').text(
						'รวมแผนรายเดือน (' + fmt(monthsSum) + ' บาท) เกินค่าใช้จ่ายรวมของรายการ (' + fmt(itemTotal) + ' บาท)'
					);
					$alert.removeClass('d-none');
				} else {
					$alert.addClass('d-none');
					$('#budgetPlanOverAlertText').text('');
				}
				return { itemTotal: itemTotal, monthsSum: monthsSum, over: over };
			};
			window.pmValidateBudgetPlanBeforeSave = function () {
				var info = pmUpdateBudgetPlanSummary();
				if (info.itemTotal > 0 && info.monthsSum <= 0.0001) {
					return 'กรุณากรอกแผนการใช้จ่ายอย่างน้อย 1 เดือน (บังคับทุกรายการค่าใช้จ่าย)';
				}
				if (info.itemTotal > 0 && info.over) {
					return 'รวมแผนการใช้จ่ายรายเดือนต้องไม่เกินค่าใช้จ่ายรวมของรายการ (ค่าใช้จ่ายรวม '
						+ (typeof window.pmFmtBudgetNum === 'function' ? window.pmFmtBudgetNum(info.itemTotal) : info.itemTotal)
						+ ' บาท, แผนรายเดือนรวม '
						+ (typeof window.pmFmtBudgetNum === 'function' ? window.pmFmtBudgetNum(info.monthsSum) : info.monthsSum)
						+ ' บาท)';
				}
				return null;
			};
			$(document).on('input change', '#formBudgetPlan input[type="number"]', function () {
				pmUpdateBudgetPlanSummary();
			});
			$(document).on('click', '[data-action="budget-plan"]', function(e){
				if (isSubmittedNow()) { e.preventDefault(); return; }
				e.preventDefault();
				var raw = $(this).attr('data-plan') || '{}';
				var p = {};
				try { p = JSON.parse(raw); } catch(err) {}
				var $f = $('#formBudgetPlan');
				$f[0].reset();
				$f.find('[name="project_activity_id"]').val(p.activity_id || 0);
				$f.find('[name="project_activity_budget_id"]').val(p.project_activity_budget_id || 0);
				$f.find('[name="project_budget_detail_id"]').val(p.project_budget_detail_id || 0);
				var itemTotal = parseFloat(String(p.item_total || '0').replace(/,/g, '')) || 0;
				$f.find('[name="item_total"]').val(itemTotal);
				pmBudgetPlanMonthKeys.forEach(function(k){
					var v = (p && Object.prototype.hasOwnProperty.call(p, k)) ? p[k] : '';
					var n = parseFloat(String(v).replace(/,/g,''));
					$f.find('[name="'+k+'"]').val((!v || isNaN(n) || n === 0) ? '' : v);
				});
				pmUpdateBudgetPlanSummary();
				$('#modalBudgetPlan').modal('show');
			});

