					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'บันทึกไม่สำเร็จ', text: msg});
					else alert(msg);
				}).fail(function(){
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'เกิดข้อผิดพลาด', text:'บันทึกไม่สำเร็จ'});
				}).always(function(){
					$f.find('button[type="submit"]').prop('disabled', false);
				});
