			$('#formSection6').on('submit', function(e){
				e.preventDefault();
				var $f = $(this);
				var v1 = String($('#s6-field-1').val() || '').trim();
				var v2 = String($('#s6-field-2').val() || '').trim();
				if (!v1 || !v2) {
					var missMsg = 'กรุณากรอกทั้ง 2 ช่องให้ครบ';
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณากรอกให้ครบ', text: missMsg });
					else alert(missMsg);
					if (!v1) $('#s6-field-1').focus();
					else $('#s6-field-2').focus();
					return;
				}
				var data = $f.serialize();
				$f.find('button[type="submit"]').prop('disabled', true);
				$.ajax({
					url: '?page=project_manage&op=save_section6_fields',
					type: 'POST',
					dataType: 'text',
					data: data
				}).done(function(respText){
					var res = null;
					try { res = JSON.parse(String(respText || '').replace(/^\uFEFF/, '').trim()); } catch(e0) {
						var t = String(respText || '');
						var i = t.indexOf('{'); var j = t.lastIndexOf('}');
						if (i >= 0 && j > i) { try { res = JSON.parse(t.substring(i, j + 1)); } catch(e1) {} }
					}
					if (res && (res.ok === 1 || res.ok === true || String(res.ok) === '1')) {
						function escHtml(s){
							return String(s||'')
								.replace(/&/g,'&amp;')
								.replace(/</g,'&lt;')
								.replace(/>/g,'&gt;')
								.replace(/"/g,'&quot;')
								.replace(/'/g,'&#039;');
						}
						function toDisplay(s){
							var t = String(s||'');
							if (!t.trim()) return '<span class="text-muted">-</span>';
							return '<div class="section2-content text-dark">' + escHtml(t).replace(/\r\n|\r|\n/g,'<br>') + '</div>';
						}
						// update local caches + view
						var group = $f.find('input[name="group"]').val() || '';
						if (group === 'evaluate') {
							var v1 = $f.find('[name="fields[evaluate_type]"]').val() || '';
							var v2 = $f.find('[name="fields[evaluate_tool]"]').val() || '';
							$('#s6-evaluate_type').val(v1);
							$('#s6-evaluate_tool').val(v2);
							$('#s6-view-evaluate_type').html(toDisplay(v1));
							$('#s6-view-evaluate_tool').html(toDisplay(v2));
							// update button: เพิ่ม (primary) / แก้ไข (เหลือง)
							var has = !!(String(v1||'').trim() || String(v2||'').trim());
							var $btn = $('#btnS6Evaluate');
							if ($btn.length) {
								$btn.removeClass('btn-primary btn-pm-edit-orange').addClass(has ? 'btn-pm-edit-orange' : 'btn-primary');
								$btn.find('i').removeClass('fa-plus fa-edit').addClass(has ? 'fa-edit' : 'fa-plus');
								$btn.contents().filter(function(){ return this.nodeType === 3; }).remove();
								$btn.append(' ' + (has ? 'แก้ไข' : 'เพิ่ม'));
							}
						} else {
							var r1 = $f.find('[name="fields[risk_action]"]').val() || '';
							var r2 = $f.find('[name="fields[risk_stop]"]').val() || '';
							$('#s6-risk_action').val(r1);
							$('#s6-risk_stop').val(r2);
							$('#s6-view-risk_action').html(toDisplay(r1));
							$('#s6-view-risk_stop').html(toDisplay(r2));
							var hasR = !!(String(r1||'').trim() || String(r2||'').trim());
							var $btnR = $('#btnS6Risk');
							if ($btnR.length) {
								$btnR.removeClass('btn-primary btn-pm-edit-orange').addClass(hasR ? 'btn-pm-edit-orange' : 'btn-primary');
								$btnR.find('i').removeClass('fa-plus fa-edit').addClass(hasR ? 'fa-edit' : 'fa-plus');
								$btnR.contents().filter(function(){ return this.nodeType === 3; }).remove();
								$btnR.append(' ' + (hasR ? 'แก้ไข' : 'เพิ่ม'));
							}
						}
						try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd) {}
						if (typeof Swal !== 'undefined') Swal.fire({icon:'success', title:'บันทึกสำเร็จ', timer:900, showConfirmButton:false});
						forceHideSection6Modal();
						if (typeof window.pmSection6Complete === 'function') {
							var s6ok = window.pmSection6Complete();
							var $s6alert = $('#pmS6DraftRequiredAlert');
							if ($s6alert.length) $s6alert.toggleClass('d-none', !!s6ok);
							$('#pm-incomplete-s6').toggleClass('d-none', !!s6ok);
						}
						try {
							if (typeof window.updateSubmitDraftButton === 'function') window.updateSubmitDraftButton();
						} catch (e) {}
						return;
