					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd2) {}
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'บันทึกไม่สำเร็จ', text: msg, confirmButtonText: 'ตกลง'});
					else alert(msg);
