					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					try { $('body').removeClass('modal-open').css('padding-right', ''); $('.modal-backdrop').remove(); } catch(eBd4) {}
					if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'เกิดข้อผิดพลาด', text: msg, confirmButtonText: 'ตกลง'});
					else alert(msg);
				}).always(function(){
					$f.find('button[type="submit"]').prop('disabled', false);
				});
