			// ===== ส่วนที่ 7 เอกสารแนบ =====
			function forceHideProjectFilesModal(){
				try { $('#modalProjectFilesUpload').modal('hide'); } catch(e){}
				setTimeout(function(){
					$('body').removeClass('modal-open');
					$('.modal-backdrop').remove();
					$('body').css('padding-right', '');
				}, 80);
			}
			$(document).on('click', '#modalProjectFilesUpload .pm-s7-modal-close', function(e){
				e.preventDefault();
				forceHideProjectFilesModal();
			});
			$('#modalProjectFilesUpload').on('hidden.bs.modal', function(){
				$('body').removeClass('modal-open');
				$('.modal-backdrop').remove();
			});

			function loadProjectFileList(){
				var $w = $('#pm-s7-files-wrap');
				if (!$w.length) return;
				$.ajax({
					url: '?page=project_manage&op=render_project_file_list',
					type: 'POST',
					dataType: 'json',
					data: { project_id: projectId }
				}).done(function(res){
					if (res && res.ok === 1) {
						$w.html(res.html || '');
						return;
					}
					$w.html('<div class="text-danger small">โหลดรายการไฟล์ไม่สำเร็จ</div>');
				}).fail(function(){
					$w.html('<div class="text-danger small">โหลดรายการไฟล์ไม่สำเร็จ</div>');
				});
			}

			$('#formProjectFilesUpload').on('submit', function(e){
				e.preventDefault();
				var $f = $(this);
				var inp = document.getElementById('pmS7FileInput');
				if (!inp || !inp.files || !inp.files.length) {
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณาเลือกไฟล์' });
					else alert('กรุณาเลือกไฟล์');
					return;
				}
				var fd = new FormData();
				fd.append('project_id', String(projectId));
				for (var i = 0; i < inp.files.length; i++) {
					fd.append('upload_files[]', inp.files[i]);
				}
				$f.find('button[type="submit"]').prop('disabled', true);
				$.ajax({
					url: '?page=project_manage&op=upload_project_files_ajax',
					type: 'POST',
					data: fd,
					processData: false,
					contentType: false,
					dataType: 'json'
				}).done(function(res){
					if (res && res.ok === 1) {
						inp.value = '';
						// ปิด modal ก่อน แล้วค่อยแจ้งสำเร็จ (กัน Swal ทับแล้ว backdrop ค้าง)
						forceHideProjectFilesModal();
						loadProjectFileList();
						var m = (res && res.msg) ? res.msg : 'อัปโหลดสำเร็จ';
						setTimeout(function(){
							if (typeof Swal !== 'undefined') {
								Swal.fire({ icon: 'success', title: m, timer: 1100, showConfirmButton: false });
							} else {
								alert(m);
							}
						}, 120);
						return;
					}
					var msg = (res && res.msg) ? res.msg : 'อัปโหลดไม่สำเร็จ';
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'อัปโหลดไม่สำเร็จ', text: msg });
					else alert(msg);
				}).fail(function(xhr){
					var msg = 'อัปโหลดไม่สำเร็จ';
					try { var j = JSON.parse(xhr.responseText || '{}'); if (j && j.msg) msg = j.msg; } catch(e){}
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด', text: msg });
					else alert(msg);
				}).always(function(){
					$f.find('button[type="submit"]').prop('disabled', false);
				});
			});

			$(document).on('click', '.pm-s7-file-delete', function(e){
				e.preventDefault();
				var fid = parseInt($(this).attr('data-file-id') || '0', 10);
				if (!fid) return;
				var run = function(){
					$.ajax({
						url: '?page=project_manage&op=delete_project_file_ajax',
						type: 'POST',
						dataType: 'json',
						data: { project_id: projectId, project_file_id: fid }
					}).done(function(res){
						if (res && res.ok === 1) {
							if (typeof Swal !== 'undefined') Swal.fire({ icon: 'success', title: 'ลบสำเร็จ', timer: 900, showConfirmButton: false });
							loadProjectFileList();
							return;
						}
						var msg = (res && res.msg) ? res.msg : 'ลบไม่สำเร็จ';
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'ลบไม่สำเร็จ', text: msg });
						else alert(msg);
					}).fail(function(xhr){
						var msg = 'ลบไม่สำเร็จ';
						try { var j = JSON.parse(xhr.responseText || '{}'); if (j && j.msg) msg = j.msg; } catch(e){}
						if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เกิดข้อผิดพลาด', text: msg });
						else alert(msg);
					});
				};
				if (typeof Swal !== 'undefined') {
					Swal.fire({ icon: 'warning', title: 'ยืนยันการลบไฟล์นี้?', showCancelButton: true, confirmButtonText: 'ลบ', cancelButtonText: 'ยกเลิก' })
						.then(function(r){ if (r.isConfirmed) run(); });
				} else if (confirm('ยืนยันการลบไฟล์นี้?')) {
					run();
				}
			});

			loadActivityTable();
			loadBudgetTable();
		})();
		</script>
				<?php endif ?>
		</div>
	</div>
	<?php
		if (!isset($pm_chg_memos) || !is_array($pm_chg_memos)) {
			$pm_chg_memos = [];
		}
		if ($edit_project_id > 0 && !empty($pm_change_history) && is_array($pm_change_history)) {
			$pmChgFmtThaiLong = static function ($ts) {
				if ($ts === false || $ts <= 0) {
					return '';
				}
				$m = ['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
				$d = (int)date('j', $ts);
				$mi = (int)date('n', $ts);
				$y = (int)date('Y', $ts) + 543;
				return $d . ' ' . $m[max(0, min(11, $mi - 1))] . ' ' . $y;
			};
			$__chgPathSigBase = isset($path_sig) ? rtrim((string)$path_sig, '/') : '';
			if ($__chgPathSigBase === '' && isset($path_picture)) {
				$__chgPathSigBase = preg_replace('#/files_person$#', '/files_sig', rtrim((string)$path_picture, '/'));
			}
			if ($__chgPathSigBase === '') {
				$__chgPathSigBase = 'https://backoffice.pharmacy.cmu.ac.th/person/files_sig';
			}
			$__chgPathSigAlts = [
				'https://mis.pharmacy.cmu.ac.th/person/MS/files_sig',
				'https://backoffice.pharmacy.cmu.ac.th/person/files_sig',
			];
			$pmChgBuildSigUrl = static function ($file, $base) {
				$file = trim((string)$file);
				$base = rtrim((string)$base, '/');
				if ($file === '' || $base === '') {
					return '';
				}
				if (preg_match('#^https?://#i', $file)) {
					return $file;
				}
				$file = preg_replace('#^files_sig/#i', '', $file);
				return $base . '/' . ltrim($file, '/');
			};
			$pmChgResolveStaffSigPack = static function ($db_person, $staffKey, $base, $alts, $fallbackFile = '') use ($pmChgBuildSigUrl) {
				$file = trim((string)$fallbackFile);
				$staffKey = trim((string)$staffKey);
				if ($file === '' && $staffKey !== '' && ($db_person instanceof mysqli)) {
					$keyEsc = mysqli_real_escape_string($db_person, $staffKey);
					$q = @mysqli_query(
						$db_person,
						"SELECT files_sig FROM staff
						 WHERE id='" . (int)$staffKey . "'
						    OR TRIM(CAST(IFNULL(code,'') AS CHAR))='" . $keyEsc . "'
						 LIMIT 1"
					);
					$r = $q ? mysqli_fetch_assoc($q) : null;
					$file = trim((string)($r['files_sig'] ?? ''));
				}
				if ($file === '') {
					return ['url' => '', 'alts' => []];
				}
				if (preg_match('#^https?://#i', $file)) {
					return ['url' => $file, 'alts' => []];
				}
				$primary = $pmChgBuildSigUrl($file, $base);
				$altUrls = [];
				foreach ((array)$alts as $ab) {
					$u = $pmChgBuildSigUrl($file, $ab);
					if ($u !== '' && $u !== $primary) {
						$altUrls[] = $u;
					}
				}
				return ['url' => $primary, 'alts' => $altUrls];
			};

			$pm_chg_am_unit = trim((string)($pm_am_unit ?? ''));
			if ($pm_chg_am_unit === '' || $pm_chg_am_unit === '-') {
				$__ucChg = trim((string)($saved_pre['code_unit'] ?? ''));
				if ($__ucChg !== '' && isset($unit_names[$__ucChg])) {
					$pm_chg_am_unit = (string)$unit_names[$__ucChg];
				} else {
					$pm_chg_am_unit = 'หน่วยงาน';
				}
			}
			$pm_chg_am_dept = trim((string)($pm_am_dept ?? ''));
			if ($pm_chg_am_dept === '') {
				$pm_chg_am_dept = ($pm_chg_am_unit !== '-' && $pm_chg_am_unit !== '' ? $pm_chg_am_unit : 'หน่วยงาน') . ' คณะเภสัชศาสตร์ โทร.44344';
			}
			$pm_chg_am_doc_no = trim((string)($pm_am_doc_no ?? ''));
			if ($pm_chg_am_doc_no === '') {
				$pm_chg_am_doc_no = function_exists('pm_unit_paper_doc_no') ? pm_unit_paper_doc_no('อว', 'ผ001') : 'อว/ผ001';
			}
			$pm_chg_am_proposer_name = trim((string)($pm_am_proposer_name ?? ''));
			$pm_chg_am_proposer_pos = trim((string)($pm_am_proposer_pos ?? ''));
			$pm_chg_am_proposer_sid = (int)($pm_am_proposer_sid ?? 0);
			$pm_chg_am_proposer_sig = trim((string)($pm_am_proposer_sig ?? ''));
			$pm_chg_am_proposer_sig_alts = is_array($pm_am_proposer_sig_alts ?? null) ? $pm_am_proposer_sig_alts : [];
			if ($pm_chg_am_proposer_name === '' && !empty($saved_heads) && is_array($saved_heads)) {
				$__hChg = $saved_heads[0];
				$__hkChg = trim((string)($__hChg['staff_project'] ?? $__hChg['staff_id'] ?? ''));
				if ($__hkChg !== '' && isset($db_person) && ($db_person instanceof mysqli)) {
					$__hkEsc = mysqli_real_escape_string($db_person, $__hkChg);
					$qHnChg = @mysqli_query(
						$db_person,
						"SELECT id, files_sig, position_code,
						        CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n
						 FROM staff
						 WHERE id='" . (int)$__hkChg . "'
						    OR TRIM(CAST(IFNULL(code,'') AS CHAR))='" . $__hkEsc . "'
						 LIMIT 1"
					);
					$rHnChg = $qHnChg ? mysqli_fetch_assoc($qHnChg) : null;
					if ($rHnChg) {
						$pm_chg_am_proposer_sid = (int)($rHnChg['id'] ?? 0);
						$pm_chg_am_proposer_name = trim((string)($rHnChg['n'] ?? ''));
						$__pcChg = trim((string)($rHnChg['position_code'] ?? ''));
						if ($__pcChg !== '' && function_exists('getPosition')) {
							$__rpChg = getPosition($db_person, $__pcChg);
							if (is_array($__rpChg)) {
								$pm_chg_am_proposer_pos = trim((string)($__rpChg['name'] ?? ''));
							}
						}
						$__packHead = $pmChgResolveStaffSigPack($db_person, (string)$pm_chg_am_proposer_sid, $__chgPathSigBase, $__chgPathSigAlts, trim((string)($rHnChg['files_sig'] ?? '')));
						$pm_chg_am_proposer_sig = (string)($__packHead['url'] ?? '');
						$pm_chg_am_proposer_sig_alts = (array)($__packHead['alts'] ?? []);
					}
				}
			}
			if ($pm_chg_am_proposer_pos === '') {
				$pm_chg_am_proposer_pos = 'หัวหน้าโครงการ';
			}

			$pm_chg_year = trim((string)($saved_pre['year_project'] ?? ''));
			if ($pm_chg_year !== '' && ctype_digit($pm_chg_year) && (int)$pm_chg_year > 0 && (int)$pm_chg_year < 2400) {
				$pm_chg_year = (string)((int)$pm_chg_year + 543);
			}

			$approvedChgIds = [];
			foreach ($pm_change_history as $__chMemo) {
				if ((string)($__chMemo['req_status'] ?? '') === 'approved') {
					$rid = (int)($__chMemo['id'] ?? 0);
					if ($rid > 0) {
						$approvedChgIds[$rid] = $rid;
					}
				}
			}
			$lastChgAppr = [];
			if (!empty($approvedChgIds)) {
				$qLastAp = @mysqli_query(
					$db_Project,
					"SELECT request_id, staff_id, decided_by_staff_id, decided_at, sort_order
					 FROM project_change_approver_decision
					 WHERE request_id IN (" . implode(',', $approvedChgIds) . ")
					   AND decision='approved'
					 ORDER BY request_id ASC, sort_order ASC"
				);
				while ($qLastAp && ($rLa = mysqli_fetch_assoc($qLastAp))) {
					$lastChgAppr[(int)($rLa['request_id'] ?? 0)] = $rLa;
				}
			}

			foreach ($pm_change_history as $__chMemo) {
				if ((string)($__chMemo['req_status'] ?? '') !== 'approved') {
					continue;
				}
				$rid = (int)($__chMemo['id'] ?? 0);
				if ($rid <= 0) {
					continue;
				}
				$tsReq = strtotime((string)($__chMemo['created_at'] ?? ''));
				$dateReq = $tsReq ? $pmChgFmtThaiLong($tsReq) : '';
				$snapName = trim((string)($__chMemo['project_name'] ?? ''));
				if ($snapName === '') {
					$snapName = trim((string)($saved_pre['name_project'] ?? ($pm_am_name ?? '')));
				}
				$snapCode = trim((string)($__chMemo['project_code'] ?? ''));
				if ($snapCode === '') {
					$snapCode = trim((string)($ref_display ?? ($pm_am_code ?? '')));
				}
				$snapSrc = trim((string)($__chMemo['budget_source'] ?? ''));
				if ($snapSrc === '' || $snapSrc === '-') {
					$snapSrc = trim((string)($pm_chg_budget_src ?? ($pm_am_budget_src ?? '')));
				}
				if ($snapSrc === '') {
					$snapSrc = '-';
				}
				$snapAmt = (float)($__chMemo['budget_amount'] ?? 0);
				$snapAmtFmt = $snapAmt > 0
					? number_format($snapAmt, 0, '.', ',')
					: trim((string)($pm_chg_budget_fmt ?? ($pm_am_budget_fmt ?? '0')));
				if ($snapAmtFmt === '') {
					$snapAmtFmt = '0';
				}
				$detailsMemo = is_array($__chMemo['details'] ?? null) ? $__chMemo['details'] : [];
				$detailsOut = [];
				foreach ($detailsMemo as $drow) {
					if (!is_array($drow)) {
						continue;
					}
					$detailsOut[] = [
						'original' => trim((string)($drow['original'] ?? '')),
						'changed' => trim((string)($drow['changed'] ?? '')),
					];
				}

				$apName = '';
				$apPos = '';
				$apDate = $dateReq;
				$apSid = 0;
				$apSig = '';
				$apSigAlts = [];
				$la = $lastChgAppr[$rid] ?? null;
				if (is_array($la)) {
					$apBy = (int)($la['decided_by_staff_id'] ?? 0);
					$apSid = $apBy > 0 ? $apBy : (int)($la['staff_id'] ?? 0);
					$tsAp = strtotime((string)($la['decided_at'] ?? ''));
					if ($tsAp) {
						$apDate = $pmChgFmtThaiLong($tsAp);
					}
					if ($apSid > 0 && isset($db_person) && ($db_person instanceof mysqli)) {
						$qAp = @mysqli_query(
							$db_person,
							"SELECT id, files_sig, position_dean, position_code,
							        CONCAT(TRIM(IFNULL(fname,'')),' ',TRIM(IFNULL(lname,''))) AS n
							 FROM staff WHERE id='" . $apSid . "' LIMIT 1"
						);
						$rAp = $qAp ? mysqli_fetch_assoc($qAp) : null;
						if ($rAp) {
							$apName = trim((string)($rAp['n'] ?? ''));
							$__pd = trim((string)($rAp['position_dean'] ?? ''));
							if ($__pd !== '' && function_exists('getPositionDean')) {
								$__rpd = getPositionDean($db_person, $__pd);
								if (is_array($__rpd)) {
									$apPos = trim((string)($__rpd['name'] ?? ''));
								}
							}
							$__packAp = $pmChgResolveStaffSigPack(
								$db_person,
								(string)$apSid,
								$__chgPathSigBase,
								$__chgPathSigAlts,
								trim((string)($rAp['files_sig'] ?? ''))
							);
							$apSig = (string)($__packAp['url'] ?? '');
							$apSigAlts = (array)($__packAp['alts'] ?? []);
						}
					}
				}
				if ($apPos === '') {
					$apPos = 'คณบดีคณะเภสัชศาสตร์';
				}
				$__chgEsignRef = '';
				$__chgEsignFooter = '';
				if (function_exists('pm_get_or_create_approve_memo_esign_ref')) {
					$__chgEsignRef = pm_get_or_create_approve_memo_esign_ref(
						$db_Project,
						(int)$edit_project_id,
						(string)$snapCode,
						'change',
						(int)$rid
					);
					$__chgEsignFooter = function_exists('pm_approve_memo_esign_footer_text')
						? pm_approve_memo_esign_footer_text($__chgEsignRef)
						: '';
				}

				$pm_chg_memos[(string)$rid] = [
					'request_id' => $rid,
					'project_id' => (int)$edit_project_id,
					'dept' => $pm_chg_am_dept,
					'doc_no' => $pm_chg_am_doc_no,
					'date' => $dateReq,
					'unit' => ($pm_chg_am_unit !== '-' && $pm_chg_am_unit !== '') ? $pm_chg_am_unit : 'หน่วยงาน',
					'name' => $snapName,
					'year' => $pm_chg_year,
					'code' => $snapCode,
					'budget' => $snapAmtFmt,
					'budget_src' => $snapSrc,
					'reason' => trim((string)($__chMemo['reason'] ?? '')),
					'details' => $detailsOut,
					'proposer_name' => $pm_chg_am_proposer_name,
					'proposer_pos' => $pm_chg_am_proposer_pos,
					'proposer_date' => $dateReq,
					'proposer_sig' => $pm_chg_am_proposer_sig,
					'proposer_sig_alts' => $pm_chg_am_proposer_sig_alts,
					'approver_name' => $apName,
					'approver_pos' => $apPos,
					'approver_date' => $apDate,
					'approver_sig' => $apSig,
					'approver_sig_alts' => $apSigAlts,
					'esign_ref' => $__chgEsignRef,
					'esign_footer' => $__chgEsignFooter,
				];
			}
		}
