	<script>
	(function($){
		if (window.pmApproveMemoBound) return;
		window.pmApproveMemoBound = true;
		window.pmAmSigFallback = function(img){
			try {
				var raw = (img.getAttribute('data-alts') || '').trim();
				var alts = raw ? raw.split('|').filter(Boolean) : [];
				var tried = parseInt(img.getAttribute('data-tried') || '0', 10) || 0;
				if (tried < alts.length) {
					img.setAttribute('data-tried', String(tried + 1));
					img.src = alts[tried];
					return;
				}
				img.style.display = 'none';
				var f = img.nextElementSibling;
				if (f) f.style.display = 'flex';
			} catch (e) {
				img.style.display = 'none';
			}
		};
		function pmAmShowModal(){
			var $modal = $('#modalApproveOperateMemo');
			if (!$modal.length) {
				if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'ไม่พบแบบฟอร์มบันทึกข้อความ'});
				else alert('ไม่พบแบบฟอร์มบันทึกข้อความ');
				return;
			}
			try { $modal.appendTo(document.body); } catch (e0) {}
			if (typeof $.fn.modal === 'function') {
				$modal.modal('show');
				return;
			}
			$modal.addClass('show').css('display','block').attr('aria-hidden','false');
			if (!$('.modal-backdrop.pm-am-backdrop').length) {
				$('<div class="modal-backdrop fade show pm-am-backdrop"></div>').appendTo(document.body);
			}
			$('body').addClass('modal-open');
		}
		function pmAmHideModal(){
			var $modal = $('#modalApproveOperateMemo');
			if (typeof $.fn.modal === 'function') {
				$modal.modal('hide');
				return;
			}
			$modal.removeClass('show').css('display','none').attr('aria-hidden','true');
			$('.modal-backdrop.pm-am-backdrop').remove();
			$('body').removeClass('modal-open');
		}
		function pmAmWrapPrintTableCells(root){
			if (!root || !root.querySelectorAll) return;
			root.querySelectorAll('table.pm-am-table th, table.pm-am-table td').forEach(function(cell){
				if (cell.querySelector('.pm-am-print-cell')) return;
				var wrap = document.createElement('div');
				wrap.className = 'pm-am-print-cell';
				wrap.setAttribute('style', 'font-family:"TH Sarabun New",Sarabun,Tahoma,sans-serif;font-size:20pt;font-weight:normal;line-height:1.45;color:#000;');
				while (cell.firstChild) wrap.appendChild(cell.firstChild);
				var id = String(cell.id || '');
				var label = String((cell.previousElementSibling && cell.previousElementSibling.textContent) || '');
				if (id.indexOf('BudgetSrc') !== -1 || label.indexOf('แหล่งงบประมาณ') !== -1) {
					wrap.textContent = String(wrap.textContent || '').replace(/\s*\/\s*/g, ' / ');
				}
				cell.appendChild(wrap);
			});
		}
		window.pmAmWrapPrintTableCells = pmAmWrapPrintTableCells;
		window.pmAmPlacePrintFooter = function(mount){
			if (!mount || !mount.querySelector) return;
			var foot = mount.querySelector('.pm-am-esign-footer');
			if (!foot) return;
			if (foot.parentNode !== mount) {
				mount.appendChild(foot);
			}
			var raw = String(foot.textContent || '').replace(/\s+/g, ' ').trim();
			var paper = mount.querySelector('.pm-am-paper');
			var ref = paper ? String(paper.getAttribute('data-esign-ref') || '').trim() : '';
			var m = raw.match(/รหัสอ้างอิงเลขที่\s*:\s*(.+)$/);
			if (m && String(m[1] || '').trim()) ref = String(m[1] || '').trim();
			if (!ref) ref = '-';
			var line1 = 'เอกสารฉบับนี้ใช้ลายมือชื่ออิเล็กทรอนิกส์ ตามพระราชบัญญัติว่าด้วยธุรกรรมทางอิเล็กทรอนิกส์ พ.ศ.2544';
			var line2 = 'และข้อบังคับมหาวิทยาลัยเชียงใหม่ ว่าด้วยการให้ใช้ลายมือชื่ออิเล็กทรอนิกส์ พ.ศ.2564 ในระบบ PlanWise ตามรหัสอ้างอิงเลขที่ : ' + ref;
			foot.textContent = '';
			var a = document.createElement('div');
			a.className = 'pm-am-esign-line';
			a.textContent = line1;
			var b = document.createElement('div');
			b.className = 'pm-am-esign-line';
			b.textContent = line2;
			foot.appendChild(a);
			foot.appendChild(b);
			foot.style.cssText = 'display:block!important;position:static!important;margin:16mm 0 0 0!important;padding:0!important;font-family:"TH Sarabun New","Sarabun",Tahoma,sans-serif!important;font-size:12pt!important;line-height:1.35!important;color:#222!important;font-weight:400!important;text-align:left!important;';
		};
		function pmAmClonePaper(){
			var paper = document.getElementById('pmAmPaper');
			if (!paper) return null;
			var clone = paper.cloneNode(true);
			clone.removeAttribute('id');
			try {
				clone.querySelectorAll('.pm-am-save-corner, #pmAmSaveBtn').forEach(function(el){
					if (el && el.parentNode) el.parentNode.removeChild(el);
				});
				var liveDept = document.getElementById('pmAmDept');
				var liveDate = document.getElementById('pmAmDate');
				var liveUnit = document.getElementById('pmAmUnitInline');
				clone.querySelectorAll('input.pm-am-edit').forEach(function(inp){
					var val = '';
					if (inp.id === 'pmAmDept' && liveDept) val = String(liveDept.value || '');
					else if (inp.id === 'pmAmDate' && liveDate) val = String(liveDate.value || '');
					else val = String(inp.value || '');
					var span = document.createElement('div');
					span.className = 'pm-am-print-text';
					span.textContent = val;
					inp.parentNode.replaceChild(span, inp);
				});
				if (liveUnit) {
					var u = clone.querySelector('#pmAmUnitInline');
					if (u) u.textContent = liveUnit.textContent || '';
				}
				clone.querySelectorAll('img').forEach(function(img){
					try { img.setAttribute('src', img.src); } catch (eImg) {}
				});
				pmAmWrapPrintTableCells(clone);
				var foot = clone.querySelector('.pm-am-esign-footer');
				var ref = String(paper.getAttribute('data-esign-ref') || '').trim();
				if (foot) {
					if (ref && String(foot.textContent || '').indexOf(ref) === -1) {
						foot.textContent = String(foot.textContent || '').replace(/\s*$/, '') + (String(foot.textContent || '').trim() ? ' ' : '') + ref;
					}
				}
			} catch (eSync) {}
			return clone;
		}
		function pmAmIsHeaderDirty(){
			var $dept = $('#pmAmDept');
			var $date = $('#pmAmDate');
			if (!$dept.length && !$date.length) return false;
			var deptNow = String($dept.val() || '').trim();
			var dateNow = String($date.val() || '').trim();
			var deptSaved = String($dept.attr('data-saved') || '').trim();
			var dateSaved = String($date.attr('data-saved') || '').trim();
			return deptNow !== deptSaved || dateNow !== dateSaved;
		}
		function pmAmSyncSaveBtn(){
			var dirty = pmAmIsHeaderDirty();
			$('#pmAmSaveBtn').toggleClass('d-none', !dirty);
			$('#pmAmPdfBtn, #pmAmPrintBtn').prop('disabled', dirty).toggleClass('disabled', dirty);
		}
		function pmAmNeedSaveFirst(){
			if (!pmAmIsHeaderDirty()) return false;
			if (typeof Swal !== 'undefined') {
				Swal.fire({ icon: 'warning', title: 'กรุณาบันทึกก่อน', text: 'มีการแก้ไขส่วนงานหรือวันที่ กรุณากดปุ่มบันทึกก่อนพิมพ์หรือดาวน์โหลด PDF' });
			} else {
				alert('มีการแก้ไขส่วนงานหรือวันที่ กรุณากดปุ่มบันทึกก่อน');
			}
			try { $('#pmAmSaveBtn').removeClass('d-none'); } catch (_e) {}
			return true;
		}
		$(document).on('click', '[data-action="open-approve-memo"], #btnOpenApproveMemo', function(e){
			e.preventDefault();
			e.stopPropagation();
			pmAmShowModal();
			setTimeout(pmAmSyncSaveBtn, 50);
		});
		$(document).on('click', '#modalApproveOperateMemo [data-dismiss="modal"]', function(e){
			e.preventDefault();
			pmAmHideModal();
		});
		$(document).on('click', '#pmAmPrintBtn', function(e){
			e.preventDefault();
			if (pmAmNeedSaveFirst()) return;
			try {
				var clone = pmAmClonePaper();
				if (!clone) {
					alert('ไม่พบเนื้อหาบันทึกข้อความ');
					return;
				}
				var mount = document.getElementById('pmAmPrintMount');
				if (!mount) {
					mount = document.createElement('div');
					mount.id = 'pmAmPrintMount';
					document.body.appendChild(mount);
				}
				mount.innerHTML = '';
				mount.appendChild(clone);
				if (typeof window.pmAmPlacePrintFooter === 'function') {
					window.pmAmPlacePrintFooter(mount);
				}

				var cleanup = function(){
					document.body.classList.remove('pm-am-printing');
					if (mount) mount.innerHTML = '';
					window.removeEventListener('afterprint', cleanup);
				};
				window.addEventListener('afterprint', cleanup);
				document.body.classList.add('pm-am-printing');
				setTimeout(function(){
					try { window.print(); } catch (e1) { cleanup(); }
				}, 80);
			} catch (e2) {
				document.body.classList.remove('pm-am-printing');
				alert('พิมพ์ไม่สำเร็จ');
			}
		});
		$(document).on('click', '#pmAmPdfBtn', function(e){
			e.preventDefault();
			if (pmAmNeedSaveFirst()) return;
			var $btn = $(this);
			if ($btn.data('busy')) return;
			var projectId = parseInt(String($btn.attr('data-project-id') || $('#pmAmPaper').attr('data-project-id') || $('#edit_project_id').val() || '0'), 10) || 0;
			if (projectId <= 0) {
				alert('ไม่พบรหัสโครงการ');
				return;
			}
			var btnHtml = $btn.html();
			$btn.data('busy', 1).prop('disabled', true).html('<i class="fas fa-spinner fa-spin mr-1"></i> กำลังสร้าง PDF...');

			function valText(sel, fallback){
				var $el = $(sel);
				if (!$el.length) return fallback || '';
				if ($el.is('input,textarea,select')) return String($el.val() || '').trim();
				return String($el.text() || '').trim() || (fallback || '');
			}

			var payload = {
				project_id: projectId,
				dept: valText('#pmAmDept'),
				doc_no: valText('#pmAmDocNo'),
				date: valText('#pmAmDate'),
				unit: valText('#pmAmUnitInline', 'หน่วยงาน'),
				code: valText('#pmAmCodeVal'),
				name: valText('#pmAmNameVal'),
				budget: valText('#pmAmBudgetVal'),
				budget_src: valText('#pmAmBudgetSrcVal'),
				proposer_name: valText('#pmAmProposerName'),
				proposer_pos: valText('#pmAmProposerPos'),
				proposer_date: valText('#pmAmProposerDate'),
				proposer_sig: String($('#pmAmProposerSig').prop('src') || $('#pmAmProposerSig').attr('src') || ''),
				approver_name: valText('#pmAmApproverName'),
				approver_pos: valText('#pmAmApproverPos'),
				approver_date: valText('#pmAmApproverDate'),
				approver_sig: String($('#pmAmApproverSig').prop('src') || $('#pmAmApproverSig').attr('src') || '')
			};

			try {
				var form = document.createElement('form');
				form.method = 'POST';
				form.action = (String(location.pathname || '').indexOf('/Plan/') !== -1)
					? '../User/approve_memo_pdf.php'
					: 'approve_memo_pdf.php';
				form.target = '_blank';
				form.style.display = 'none';
				Object.keys(payload).forEach(function(k){
					var input = document.createElement('input');
					input.type = 'hidden';
					input.name = k;
					input.value = payload[k] == null ? '' : String(payload[k]);
					form.appendChild(input);
				});
				document.body.appendChild(form);
				form.submit();
				setTimeout(function(){
					try { document.body.removeChild(form); } catch (eR) {}
					$btn.data('busy', 0).prop('disabled', false).html(btnHtml);
				}, 800);
			} catch (eSub) {
				$btn.data('busy', 0).prop('disabled', false).html(btnHtml);
				alert('สร้าง PDF ไม่สำเร็จ');
			}
		});
		$(document).on('input', '#pmAmDept, #pmAmDate', function(){
			if (this.id === 'pmAmDept') {
				var v = String($(this).val() || '').trim();
				var unit = v.replace(/\s*คณะเภสัชศาสตร์.*$/u, '').trim();
				if (unit) $('#pmAmUnitInline').text(unit);
			}
			pmAmSyncSaveBtn();
		});
		$(document).on('click', '#pmAmSaveBtn', function(e){
			e.preventDefault();
			var $btn = $(this);
			if ($btn.data('busy')) return;
			var projectId = parseInt(String($('#pmAmPaper').attr('data-project-id') || $('#edit_project_id').val() || '0'), 10) || 0;
			if (projectId <= 0) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'ไม่พบโครงการ' });
				else alert('ไม่พบโครงการ');
				return;
			}
			var dept = String($('#pmAmDept').val() || '').trim();
			var dateTxt = String($('#pmAmDate').val() || '').trim();
			var html = $btn.html();
			$btn.data('busy', 1).prop('disabled', true).html('<i class="fa fa-spinner fa-spin mr-1"></i> กำลังบันทึก...');
			$.ajax({
				url: '?page=project_manage&op=save_approve_memo_header_ajax',
				type: 'POST',
				dataType: 'json',
				data: { op: 'save_approve_memo_header_ajax', project_id: projectId, dept: dept, date: dateTxt }
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					$('#pmAmDept').attr('data-saved', dept);
					$('#pmAmDate').attr('data-saved', dateTxt);
					pmAmSyncSaveBtn();
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'success', title: 'บันทึกแล้ว', timer: 1100, showConfirmButton: false });
				} else {
					var msg = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'ไม่สำเร็จ', text: msg });
					else alert(msg);
				}
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'ไม่สำเร็จ', text: 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้' });
				else alert('ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้');
			}).always(function(){
				$btn.data('busy', 0).prop('disabled', false).html(html);
				pmAmSyncSaveBtn();
			});
		});
	})(jQuery);
	</script>
	<?php endif; ?>

