	<script>
	(function($){
		if (window.pmChangeMemoBound) return;
		window.pmChangeMemoBound = true;
		if (typeof window.pmAmSigFallback !== 'function') {
			window.pmAmSigFallback = function(img){
				try {
					var raw = (img.getAttribute('data-alts') || '').trim();
					var alts = raw ? raw.split('|').filter(Boolean) : [];
					var tried = parseInt(img.getAttribute('data-tried') || '0', 10) || 0;
					if (tried < alts.length) {
						img.setAttribute('data-tried', String(tried + 1));
						img.src = alts[tried];
						return;
					}
					img.style.display = 'none';
					var f = img.nextElementSibling;
					if (f) f.style.display = 'flex';
				} catch (e) {
					img.style.display = 'none';
				}
			};
		}
		function pmChgMemoMap(){
			try {
				var el = document.getElementById('pmChgMemoData');
				if (!el) return {};
				var j = JSON.parse(el.textContent || '{}');
				return (j && typeof j === 'object') ? j : {};
			} catch (e) {
				return {};
			}
		}
		function pmChgSetText(id, val, fallback){
			var el = document.getElementById(id);
			if (!el) return;
			el.textContent = (val != null && String(val).trim() !== '') ? String(val) : (fallback || '');
		}
		function pmChgRenderSig(wrapId, url, alts, altText){
			var wrap = document.getElementById(wrapId);
			if (!wrap) return;
			wrap.innerHTML = '';
			url = String(url || '').trim();
			var altStr = Array.isArray(alts) ? alts.join('|') : String(alts || '');
			if (url) {
				var img = document.createElement('img');
				img.className = 'pm-am-sig-img';
				img.src = url;
				img.setAttribute('data-alts', altStr);
				img.setAttribute('alt', altText || 'ลายเซ็น');
				img.onerror = function(){ if (window.pmAmSigFallback) window.pmAmSigFallback(img); };
				wrap.appendChild(img);
				var fb = document.createElement('div');
				fb.className = 'pm-am-sig-fallback';
				fb.style.display = 'none';
				fb.textContent = 'Digitally signed by';
				wrap.appendChild(fb);
			} else {
				var fb2 = document.createElement('div');
				fb2.className = 'pm-am-sig-fallback';
				fb2.textContent = 'Digitally signed by';
				wrap.appendChild(fb2);
			}
		}
		function pmChgFillMemo(data){
			if (!data) return;
			var paper = document.getElementById('pmChgAmPaper');
			if (paper) {
				paper.setAttribute('data-request-id', String(data.request_id || ''));
				paper.setAttribute('data-project-id', String(data.project_id || ''));
			}
			var dept = document.getElementById('pmChgAmDept');
			if (dept) dept.value = String(data.dept || '');
			var dateEl = document.getElementById('pmChgAmDate');
			if (dateEl) dateEl.value = String(data.date || '');
			pmChgSetText('pmChgAmDocNo', data.doc_no, '');
			pmChgSetText('pmChgAmSubjectName', data.name, '…');
			pmChgSetText('pmChgAmUnitInline', data.unit, 'หน่วยงาน');
			pmChgSetText('pmChgAmUnitInline2', data.unit, 'หน่วยงาน');
			pmChgSetText('pmChgAmNameInline', data.name, '…');
			pmChgSetText('pmChgAmYearVal', data.year, '…');
			pmChgSetText('pmChgAmCodeVal', data.code, '-');
			pmChgSetText('pmChgAmBudgetSrcVal', data.budget_src, '-');
			pmChgSetText('pmChgAmBudgetVal', data.budget, '0');
			pmChgSetText('pmChgAmReasonVal', data.reason, '…');
			pmChgSetText('pmChgAmProposerName', data.proposer_name, '........................');
			pmChgSetText('pmChgAmProposerPos', data.proposer_pos, '........................');
			pmChgSetText('pmChgAmProposerDate', data.proposer_date || data.date, '....................');
			pmChgSetText('pmChgAmApproverName', data.approver_name, '........................');
			pmChgSetText('pmChgAmApproverPos', data.approver_pos, '........................');
			pmChgSetText('pmChgAmApproverDate', data.approver_date, '....................');
			pmChgRenderSig('pmChgAmProposerSigWrap', data.proposer_sig, data.proposer_sig_alts, 'ลายเซ็นผู้เสนอ');
			pmChgRenderSig('pmChgAmApproverSigWrap', data.approver_sig, data.approver_sig_alts, 'ลายเซ็นผู้อนุมัติ');
			pmChgSetText('pmChgAmEsignFooter', data.esign_footer, '');
			var tb = document.getElementById('pmChgAmDetailsBody');
			if (tb) {
				tb.innerHTML = '';
				var rows = Array.isArray(data.details) ? data.details : [];
				if (!rows.length) {
					tb.innerHTML = '<tr><td>1</td><td>-</td><td>-</td></tr>';
				} else {
					rows.forEach(function(row, idx){
						var tr = document.createElement('tr');
						var tdN = document.createElement('td');
						tdN.textContent = String(idx + 1);
						var tdO = document.createElement('td');
						tdO.textContent = String((row && row.original) || '');
						var tdC = document.createElement('td');
						tdC.textContent = String((row && row.changed) || '');
						tr.appendChild(tdN);
						tr.appendChild(tdO);
						tr.appendChild(tdC);
						tb.appendChild(tr);
					});
				}
			}
		}
		function pmChgShowModal(){
			var $modal = $('#modalChangeApproveMemo');
			if (!$modal.length) {
				if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'ไม่พบแบบฟอร์มบันทึกข้อความ'});
				else alert('ไม่พบแบบฟอร์มบันทึกข้อความ');
				return;
			}
			try { $modal.appendTo(document.body); } catch (e0) {}
			if (typeof $.fn.modal === 'function') {
				$modal.modal('show');
				return;
			}
			$modal.addClass('show').css('display','block').attr('aria-hidden','false');
			if (!$('.modal-backdrop.pm-chg-am-backdrop').length) {
				$('<div class="modal-backdrop fade show pm-chg-am-backdrop"></div>').appendTo(document.body);
			}
			$('body').addClass('modal-open');
		}
		function pmChgHideModal(){
			var $modal = $('#modalChangeApproveMemo');
			if (typeof $.fn.modal === 'function') {
				$modal.modal('hide');
				return;
			}
			$modal.removeClass('show').css('display','none').attr('aria-hidden','true');
			$('.modal-backdrop.pm-chg-am-backdrop').remove();
			$('body').removeClass('modal-open');
		}
		function pmChgClonePaper(){
			var paper = document.getElementById('pmChgAmPaper');
			if (!paper) return null;
			var clone = paper.cloneNode(true);
			clone.removeAttribute('id');
			try {
				var liveDept = document.getElementById('pmChgAmDept');
				var liveDate = document.getElementById('pmChgAmDate');
				clone.querySelectorAll('input.pm-am-edit').forEach(function(inp){
					var val = '';
					if (inp.id === 'pmChgAmDept' && liveDept) val = String(liveDept.value || '');
					else if (inp.id === 'pmChgAmDate' && liveDate) val = String(liveDate.value || '');
					else val = String(inp.value || '');
					var span = document.createElement('div');
					span.className = 'pm-am-print-text';
					span.textContent = val;
					inp.parentNode.replaceChild(span, inp);
				});
				clone.querySelectorAll('img').forEach(function(img){
					try { img.setAttribute('src', img.src); } catch (eImg) {}
				});
				if (typeof window.pmAmWrapPrintTableCells === 'function') {
					window.pmAmWrapPrintTableCells(clone);
				}
				var foot = clone.querySelector('.pm-am-esign-footer');
				if (foot) {
					foot.style.setProperty('font-size', '7pt', 'important');
					foot.style.setProperty('line-height', '1.25', 'important');
				}
			} catch (eSync) {}
			return clone;
		}
		$(document).on('click', '.pm-chg-open-memo', function(e){
			e.preventDefault();
			e.stopPropagation();
			var rid = String($(this).attr('data-request-id') || '').trim();
			var map = pmChgMemoMap();
			var data = map[rid] || null;
			if (!data) {
				if (typeof Swal !== 'undefined') Swal.fire({icon:'error', title:'ไม่พบบันทึกข้อความของคำขอนี้'});
				else alert('ไม่พบบันทึกข้อความของคำขอนี้');
				return;
			}
			pmChgFillMemo(data);
			pmChgShowModal();
		});
		$(document).on('click', '#modalChangeApproveMemo [data-dismiss="modal"]', function(e){
			e.preventDefault();
			pmChgHideModal();
		});
		$(document).on('click', '#pmChgAmPrintBtn', function(e){
			e.preventDefault();
			try {
				var clone = pmChgClonePaper();
				if (!clone) {
					alert('ไม่พบเนื้อหาบันทึกข้อความ');
					return;
				}
				var mount = document.getElementById('pmAmPrintMount');
				if (!mount) {
					mount = document.createElement('div');
					mount.id = 'pmAmPrintMount';
					document.body.appendChild(mount);
				}
				mount.innerHTML = '';
				mount.appendChild(clone);
				if (typeof window.pmAmPlacePrintFooter === 'function') {
					window.pmAmPlacePrintFooter(mount);
				}
				var cleanup = function(){
					document.body.classList.remove('pm-am-printing');
					if (mount) mount.innerHTML = '';
					window.removeEventListener('afterprint', cleanup);
				};
				window.addEventListener('afterprint', cleanup);
				document.body.classList.add('pm-am-printing');
				setTimeout(function(){
					try { window.print(); } catch (e1) { cleanup(); }
				}, 80);
			} catch (e2) {
				document.body.classList.remove('pm-am-printing');
				alert('พิมพ์ไม่สำเร็จ');
			}
		});
		$(document).on('click', '#pmChgAmPdfBtn', function(e){
			e.preventDefault();
			var $btn = $(this);
			if ($btn.data('busy')) return;
			var paper = document.getElementById('pmChgAmPaper');
			var projectId = parseInt(String($btn.attr('data-project-id') || (paper && paper.getAttribute('data-project-id')) || $('#edit_project_id').val() || '0'), 10) || 0;
			var requestId = parseInt(String((paper && paper.getAttribute('data-request-id')) || '0'), 10) || 0;
			if (projectId <= 0 || requestId <= 0) {
				alert('ไม่พบรหัสโครงการหรือคำขอเปลี่ยนแปลง');
				return;
			}
			var btnHtml = $btn.html();
			$btn.data('busy', 1).prop('disabled', true).html('<i class="fas fa-spinner fa-spin mr-1"></i> กำลังสร้าง PDF...');
			function valText(sel, fallback){
				var $el = $(sel);
				if (!$el.length) return fallback || '';
				if ($el.is('input,textarea,select')) return String($el.val() || '').trim();
				return String($el.text() || '').trim() || (fallback || '');
			}
			var details = [];
			$('#pmChgAmDetailsBody tr').each(function(){
				var tds = $(this).find('td');
				if (tds.length < 3) return;
				details.push({
					original: String($(tds[1]).text() || ''),
					changed: String($(tds[2]).text() || '')
				});
			});
			var payload = {
				memo_type: 'change',
				project_id: projectId,
				request_id: requestId,
				dept: valText('#pmChgAmDept'),
				doc_no: valText('#pmChgAmDocNo'),
				date: valText('#pmChgAmDate'),
				unit: valText('#pmChgAmUnitInline', 'หน่วยงาน'),
				code: valText('#pmChgAmCodeVal'),
				name: valText('#pmChgAmNameInline'),
				year: valText('#pmChgAmYearVal'),
				budget: valText('#pmChgAmBudgetVal'),
				budget_src: valText('#pmChgAmBudgetSrcVal'),
				reason: valText('#pmChgAmReasonVal'),
				details_json: JSON.stringify(details),
				proposer_name: valText('#pmChgAmProposerName'),
				proposer_pos: valText('#pmChgAmProposerPos'),
				proposer_date: valText('#pmChgAmProposerDate'),
				proposer_sig: String($('#pmChgAmProposerSigWrap img').prop('src') || $('#pmChgAmProposerSigWrap img').attr('src') || ''),
				approver_name: valText('#pmChgAmApproverName'),
				approver_pos: valText('#pmChgAmApproverPos'),
				approver_date: valText('#pmChgAmApproverDate'),
				approver_sig: String($('#pmChgAmApproverSigWrap img').prop('src') || $('#pmChgAmApproverSigWrap img').attr('src') || '')
			};
			try {
				var form = document.createElement('form');
				form.method = 'POST';
				form.action = (String(location.pathname || '').indexOf('/Plan/') !== -1)
					? '../User/approve_memo_pdf.php'
					: 'approve_memo_pdf.php';
				form.target = '_blank';
				form.style.display = 'none';
				Object.keys(payload).forEach(function(k){
					var input = document.createElement('input');
					input.type = 'hidden';
					input.name = k;
					input.value = payload[k] == null ? '' : String(payload[k]);
					form.appendChild(input);
				});
				document.body.appendChild(form);
				form.submit();
				setTimeout(function(){
					try { document.body.removeChild(form); } catch (eR) {}
					$btn.data('busy', 0).prop('disabled', false).html(btnHtml);
				}, 800);
			} catch (eSub) {
				$btn.data('busy', 0).prop('disabled', false).html(btnHtml);
				alert('สร้าง PDF ไม่สำเร็จ');
			}
		});
		$(document).on('input', '#pmChgAmDept', function(){
			var v = String($(this).val() || '').trim();
			var unit = v.replace(/\s*คณะเภสัชศาสตร์.*$/u, '').trim();
			if (unit) {
				$('#pmChgAmUnitInline, #pmChgAmUnitInline2').text(unit);
			}
		});
	})(jQuery);
	</script>
	<?php endif; ?>
	<?php endif; ?>

