	<script>
	(function($){
		if (window.pmRrMemoUiBound) return;
		window.pmRrMemoUiBound = true;
		if (!window.PM_CAN_FILL_PROJECT_RESULTS) return;
		var projectId = <?= (int)$edit_project_id ?>;
		if (!projectId) return;
		var pmRrCertStaffOptions = <?= json_encode($request_operate_staff_options ?? [], JSON_UNESCAPED_UNICODE) ?>;
		var $modalRr = $('#modalFinishProjectReport');
		if (!$modalRr.length) return;
		try { $modalRr.appendTo('body'); } catch (err0) {}

		function pmRrInitCertSelect($sel) {
			if (!$sel || !$sel.length || typeof $.fn.select2 !== 'function') return;
			try { if ($sel.hasClass('select2-hidden-accessible')) $sel.select2('destroy'); } catch (e0) {}
			$sel.select2({
				placeholder: '- เลือก -',
				allowClear: true,
				width: '100%',
				dropdownParent: $modalRr.length ? $modalRr : $(document.body)
			});
			$sel.off('change.pmCertPos').on('change.pmCertPos', function(){
				var $s = $(this);
				var pos = String($s.find('option:selected').attr('data-position') || '');
				$s.closest('.pm-ro-cert-row').find('input.pm-ro-cert-position').val(pos);
			});
		}
		function pmRrRenumberCertRows() {
			var $wrap = $('#pmRrCertifiersRows');
			if (!$wrap.length) return;
			$wrap.find('.pm-ro-cert-row').each(function(i){
				$(this).find('.pm-ro-cert-lbl-idx').text('(' + (i + 1) + ')');
			});
		}
		function pmRrSyncCertRemoveVisibility() {
			var $wrap = $('#pmRrCertifiersRows');
			if (!$wrap.length) return;
			var n = $wrap.find('.pm-ro-cert-row').length;
			$wrap.find('.pm-ro-cert-remove').css('visibility', n > 1 ? 'visible' : 'hidden');
		}
		function pmRrAddCertRow(staffId, position) {
			var $wrap = $('#pmRrCertifiersRows');
			if (!$wrap.length) return;
			var n = $wrap.find('.pm-ro-cert-row').length + 1;
			var remBtn = '<button type="button" class="btn btn-sm btn-link text-danger p-0 pm-ro-cert-remove" title="ลบแถว"><i class="fa fa-times"></i></button>';
			var $row = $(
				'<div class="pm-ro-cert-row">' +
					'<div class="pm-ro-cert-side">' + remBtn + '</div>' +
					'<div class="pm-ro-cert-fields flex-grow-1">' +
						'<div class="row mx-0">' +
							'<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2">' +
								'<label class="d-block pm-ro-cert-lbl">ผู้ตรวจสอบ <span class="text-danger">*</span> <span class="pm-ro-cert-lbl-idx text-muted font-weight-bold">(' + n + ')</span></label>' +
								'<select class="form-control pm-ro-cert-select"></select>' +
							'</div>' +
							'<div class="col-md-6 col-12 pl-md-2">' +
								'<label class="d-block pm-ro-cert-lbl">ตำแหน่ง <span class="text-danger">*</span></label>' +
								'<input type="text" class="form-control pm-ro-cert-position" placeholder="ตำแหน่ง* (กรอก)" autocomplete="off">' +
							'</div>' +
						'</div>' +
					'</div>' +
				'</div>'
			);
			$wrap.append($row);
			var $sel = $row.find('select');
			$sel.append(new Option('- เลือก -', '', false, false));
			(pmRrCertStaffOptions || []).forEach(function(o){
				var opt = new Option(o.text, String(o.id), false, false);
				if (o && o.position) $(opt).attr('data-position', String(o.position));
				$sel.append(opt);
			});
			if (staffId) $sel.val(String(staffId));
			pmRrInitCertSelect($sel);
			if (position) $row.find('.pm-ro-cert-position').val(position);
			pmRrRenumberCertRows();
			pmRrSyncCertRemoveVisibility();
		}
		function pmRrResetCertRows(prevCerts) {
			var $wrap = $('#pmRrCertifiersRows');
			if (!$wrap.length) return;
			$wrap.find('.pm-ro-cert-select').each(function(){
				try { if ($(this).hasClass('select2-hidden-accessible')) $(this).select2('destroy'); } catch (e1) {}
			});
			$wrap.empty();
			prevCerts = Array.isArray(prevCerts) ? prevCerts : [];
			if (prevCerts.length) {
				prevCerts.forEach(function(c){
					pmRrAddCertRow(parseInt(c.staff_id || '0', 10) || '', String(c.position || c.position_title || ''));
				});
			} else {
				pmRrAddCertRow('', '');
			}
			pmRrSyncCertRemoveVisibility();
		}
		function pmRrCollectCertPayload() {
			var $wrap = $('#pmRrCertifiersRows');
			var out = [];
			var err = '';
			if (!$wrap.length) return { ok: false, err: 'ไม่พบแบบฟอร์มผู้ตรวจสอบ', rows: [] };
			$wrap.find('.pm-ro-cert-row').each(function(){
				var $r = $(this);
				var sid = String($r.find('select').val() || '').trim();
				var pos = String($r.find('input.pm-ro-cert-position').val() || '').trim();
				if (sid === '' && pos === '') return;
				if (sid === '' || pos === '') {
					err = 'กรุณากรอกผู้ตรวจสอบและตำแหน่งให้ครบทุกลำดับที่ระบุ';
					return false;
				}
				out.push({ staff_id: parseInt(sid, 10), position: pos });
			});
			if (err === '' && out.length === 0) err = 'กรุณาระบุผู้ตรวจสอบอย่างน้อย 1 คน';
			return { ok: err === '' && out.length > 0, err: err, rows: out };
		}
		function pmRrIsResubmitMode() {
			return !!window.PM_RESULT_REPORT_RESUBMIT;
		}
		function pmRrApplyModalMode() {
			var resubmit = pmRrIsResubmitMode();
			$('#pmRrResubmitWrap').toggleClass('d-none', !resubmit);
			$('#pmRrMemoTitle').text(resubmit ? 'ส่งรายงานการแก้ไขโครงการ' : 'เสร็จสิ้นโครงการและส่งรายงาน');
			$('#pmRrMemoHeadTitle').text(resubmit ? 'ส่งรายงานการแก้ไขกลับผู้ตรวจสอบ' : 'ยืนยันการส่งรายงานผลโครงการ');
			$('#pmRrMemoHeadSub').text(resubmit
				? 'ระบุรายละเอียดการแก้ไขและยืนยันผู้ตรวจสอบตามลำดับ ก่อนกดส่ง'
				: 'ตรวจสอบข้อมูลและเลือกผู้ตรวจสอบตามลำดับ ก่อนกดส่ง');
			$('#pmRrLockHintText').text(resubmit
				? 'เมื่อกดส่งรายงานการแก้ไขแล้ว จะไม่สามารถแก้ไขข้อมูลได้จนกว่าจะถูกตีกลับอีกครั้ง'
				: 'เมื่อกดส่งรายงานแล้ว จะไม่สามารถแก้ไขข้อมูลได้จนกว่าจะถูกตีกลับ');
			$('.pm-rr-confirm-label').text(resubmit ? 'ส่งรายงานการแก้ไข' : 'ส่งรายงานผลโครงการ');
			var $icon = $('.pm-rr-confirm-icon');
			$icon.removeClass('fa-paper-plane fa-redo').addClass(resubmit ? 'fa-redo' : 'fa-paper-plane');
			var $headIcon = $('.pm-rr-memo-icon');
			$headIcon.css({
				background: resubmit ? 'linear-gradient(180deg,#fde68a 0%,#d97706 100%)' : 'linear-gradient(180deg,#bfdbfe 0%,#2563eb 100%)',
				color: resubmit ? '#78350f' : '#1e3a8a'
			});
			$headIcon.find('i').removeClass('fa-paper-plane fa-redo').addClass(resubmit ? 'fa-redo' : 'fa-paper-plane');
		}
		function setFinishButtonsEnabled(enabled, missing) {
			missing = Array.isArray(missing) ? missing : [];
			var resubmit = pmRrIsResubmitMode();
			var title = enabled
				? (resubmit ? 'กรอกรายละเอียดการแก้ไขแล้วส่งกลับผู้ตรวจสอบ' : 'กดส่งแล้วจะแก้ไขไม่ได้จนกว่าจะถูกตีกลับ')
				: (missing.length ? ('รายงานยังไม่ครบ:\n' + missing.slice(0, 5).join('\n')) : 'จะกดได้เมื่อรายงานครบถ้วน');
			$('.pm-finish-project-report-btn')
				.prop('disabled', !enabled)
				.attr('title', title)
				.attr('data-missing', missing.length ? JSON.stringify(missing.slice(0, 8)) : '');
		}
		window.pmRefreshFinishReportButtons = function(){
			if (!window.PM_CAN_FILL_PROJECT_RESULTS || !projectId || window.PM_RESULT_REPORT_LOCKED || window.PM_RESULT_REPORT_COMPLETE) {
				return;
			}
			$.ajax({
				url: '?page=project_manage&op=get_project_report_submit_ajax',
				type: 'POST',
				dataType: 'json',
				data: { project_id: projectId, op: 'get_project_report_submit_ajax' }
			}).done(function(res){
				if (!res || res.ok !== 1) return;
				setFinishButtonsEnabled(!!res.complete, res.missing || []);
			});
		};
		function pmRrHideModal() {
			try { $modalRr.modal('hide'); } catch (err) {}
			$modalRr.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
			if (!$('.modal.show, .modal.in').not($modalRr).length) {
				$('body').removeClass('modal-open').css('padding-right', '');
				$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
			}
		}
		function pmRrOpenModal() {
			pmRrApplyModalMode();
			$('#pmRrSubmitterReplyNote').val('');
			$('#pmRrRejectedNoteText').text('-');
			pmRrResetCertRows([]);
			try { $modalRr.modal({ backdrop: 'static', keyboard: true, show: true }); } catch (err) {
				$modalRr.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
				if (!$('.modal-backdrop').not('.pm-activity-disburse-backdrop').length) {
					$('body').append('<div class="modal-backdrop fade show"></div>');
				}
				$('body').addClass('modal-open');
			}
			$.ajax({
				url: '?page=project_manage&op=get_project_report_submit_ajax',
				type: 'POST',
				dataType: 'json',
				data: { project_id: projectId, op: 'get_project_report_submit_ajax' }
			}).done(function(res){
				if (!res || res.ok !== 1) return;
				if (Array.isArray(res.prev_certifiers) && res.prev_certifiers.length) {
					pmRrResetCertRows(res.prev_certifiers);
				}
				if (res.is_resubmit) {
					var rejNote = (res.rejection && res.rejection.note) ? String(res.rejection.note).trim() : '';
					$('#pmRrRejectedNoteText').text(rejNote !== '' ? rejNote : 'ไม่มีข้อความจากผู้ตรวจสอบ');
					if (res.prev_reply_note) {
						$('#pmRrSubmitterReplyNote').val(String(res.prev_reply_note));
					}
				}
			});
		}
		window.pmOpenFinishProjectReportModal = pmRrOpenModal;

		if (!window.PM_RESULT_REPORT_LOCKED && !window.PM_RESULT_REPORT_COMPLETE) {
			window.pmRefreshFinishReportButtons();
		}

		$(document).on('click', '#modalFinishProjectReport .pm-rr-memo-close, #modalFinishProjectReport [data-dismiss="modal"], #modalFinishProjectReport [data-bs-dismiss="modal"]', function(e){
			e.preventDefault();
			pmRrHideModal();
		});
		$modalRr.on('hidden.bs.modal', function(){
			if (!$('.modal.show, .modal.in').length) {
				$('body').removeClass('modal-open').css('padding-right', '');
				$('.modal-backdrop').not('.pm-activity-disburse-backdrop').remove();
			}
		});

		$(document).on('click', '#btnPmRrCertAdd', function(){ pmRrAddCertRow('', ''); });
		$(document).on('click', '#pmRrCertifiersRows .pm-ro-cert-remove', function(){
			var $wrap = $('#pmRrCertifiersRows');
			if ($wrap.find('.pm-ro-cert-row').length <= 1) return;
			var $row = $(this).closest('.pm-ro-cert-row');
			try { $row.find('select').select2('destroy'); } catch (e2) {}
			$row.remove();
			pmRrRenumberCertRows();
			pmRrSyncCertRemoveVisibility();
		});
		$(document).on('click', '[data-action="finish-project-report"], .pm-finish-project-report-btn', function(e){
			e.preventDefault();
			if ($(this).prop('disabled')) {
				var missing = [];
				try {
					var rawMissing = $(this).attr('data-missing') || '';
					if (rawMissing) missing = JSON.parse(rawMissing);
				} catch (err) { missing = []; }
				if (!Array.isArray(missing)) missing = [];
				var needsEval = missing.some(function(m){ return String(m || '').indexOf('ประเมินผลโครงการ') !== -1; });
				var esc = function(s){
					return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
				};
				if (typeof Swal !== 'undefined') {
					var html = missing.length
						? ('<ul style="text-align:left;margin:0;padding-left:1.25em;">' + missing.map(function(m){ return '<li>' + esc(m) + '</li>'; }).join('') + '</ul>')
						: 'จะกดได้เมื่อรายงานครบถ้วน';
					Swal.fire({
						icon: 'info',
						title: 'รายงานยังไม่ครบถ้วน',
						html: html,
						confirmButtonText: needsEval ? 'ไปประเมินผลโครงการ' : 'ตกลง'
					}).then(function(r){
						if (!needsEval || !r || !r.isConfirmed) return;
						var $evalBtn = $('#btnOpenProjectEvaluation');
						if (!$evalBtn.length) return;
						try {
							$('html, body').animate({ scrollTop: Math.max(0, ($evalBtn.offset() || {}).top - 120) }, 280);
						} catch (err2) {}
						$evalBtn.trigger('click');
					});
				} else {
					alert(missing.length ? ('รายงานยังไม่ครบ:\n' + missing.join('\n')) : 'จะกดได้เมื่อรายงานครบถ้วน');
				}
				return;
			}
			pmRrOpenModal();
		});
		$(document).on('click', '#pmRrMemoBtnConfirm', function(){
			var certPack = pmRrCollectCertPayload();
			if (!certPack.ok) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณากรอกข้อมูล', text: certPack.err || 'ข้อมูลไม่ครบ' });
				else alert(certPack.err || 'ข้อมูลไม่ครบ');
				return;
			}
			var replyNote = '';
			if (pmRrIsResubmitMode()) {
				replyNote = String($('#pmRrSubmitterReplyNote').val() || '').trim();
				if (replyNote === '') {
					if (typeof Swal !== 'undefined') Swal.fire({ icon: 'warning', title: 'กรุณาระบุรายละเอียดการแก้ไข', text: 'ต้องกรอกรายละเอียดการแก้ไขที่ส่งถึงผู้ตรวจสอบ' });
					else alert('กรุณาระบุรายละเอียดการแก้ไขที่ส่งถึงผู้ตรวจสอบ');
					return;
				}
			}
			var $btn = $(this).prop('disabled', true);
			var postData = { project_id: projectId, certifiers_json: JSON.stringify(certPack.rows), op: 'submit_project_report_ajax' };
			if (pmRrIsResubmitMode()) {
				postData.submitter_reply_note = replyNote;
			}
			$.ajax({
				url: '?page=project_manage&op=submit_project_report_ajax',
				type: 'POST',
				dataType: 'json',
				data: postData
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					pmRrHideModal();
					if (typeof Swal !== 'undefined') {
						var okTitle = pmRrIsResubmitMode() ? 'ส่งรายงานการแก้ไขแล้ว' : 'ส่งรายงานผลโครงการแล้ว';
						Swal.fire({ icon: 'success', title: okTitle, text: res.msg || '', timer: 1400, showConfirmButton: false })
							.then(function(){ window.location.reload(); });
					} else {
						window.location.reload();
					}
					return;
				}
				var msg = (res && res.msg) ? res.msg : 'ส่งรายงานไม่สำเร็จ';
				var missing = (res && Array.isArray(res.missing)) ? res.missing : [];
				if (typeof window.pmRefreshFinishReportButtons === 'function') {
					window.pmRefreshFinishReportButtons();
				}
				if (typeof Swal !== 'undefined') {
					var esc = function(s){
						return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
					};
					var needsEval = missing.some(function(m){ return String(m || '').indexOf('ประเมินผลโครงการ') !== -1; });
					Swal.fire({
						icon: 'error',
						title: msg,
						html: missing.length
							? ('<ul style="text-align:left;margin:0;padding-left:1.25em;">' + missing.map(function(m){ return '<li>' + esc(m) + '</li>'; }).join('') + '</ul>')
							: undefined,
						confirmButtonText: needsEval ? 'ไปประเมินผลโครงการ' : 'ตกลง'
					}).then(function(r){
						if (!needsEval || !r || !r.isConfirmed) return;
						pmRrHideModal();
						var $evalBtn = $('#btnOpenProjectEvaluation');
						if (!$evalBtn.length) return;
						try {
							$('html, body').animate({ scrollTop: Math.max(0, ($evalBtn.offset() || {}).top - 120) }, 280);
						} catch (err3) {}
						$evalBtn.trigger('click');
					});
				} else {
					alert(msg + (missing.length ? ('\n' + missing.join('\n')) : ''));
				}
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon: 'error', title: 'เชื่อมต่อไม่สำเร็จ' });
			}).always(function(){ $btn.prop('disabled', false); });
		});
	})(jQuery);
	</script>
	<?php endif ?>
