		#modalRequestChangeProject .pm-chg-detail-row{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:.7rem;padding:.85rem .9rem .75rem;border-radius:.95rem;background:#fff;border:1px solid #e2e8f0;box-shadow:0 8px 18px -16px rgba(15,23,42,.35);}
		#modalRequestChangeProject .pm-chg-detail-col{min-width:0;}
		#modalRequestChangeProject .pm-chg-detail-lbl{display:flex;align-items:center;justify-content:space-between;font-weight:800;font-size:.82rem;margin-bottom:.35rem;}
		#modalRequestChangeProject .pm-chg-detail-lbl.orig{color:#334155;}
		#modalRequestChangeProject .pm-chg-detail-lbl.chg{color:#c2410c;}
		#modalRequestChangeProject .pm-chg-detail-row .pm-chg-detail-col:last-child .pm-chg-detail-lbl{padding-right:1.8rem;}
		#modalRequestChangeProject .pm-chg-detail-rm{position:absolute;top:.45rem;right:.45rem;width:1.7rem;height:1.7rem;border:0;border-radius:999px;background:#fff1f2;color:#e11d48;display:inline-flex;align-items:center;justify-content:center;}
		#modalRequestChangeProject .pm-chg-drop{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.2rem;padding:1.05rem .9rem;border-radius:.95rem;border:1.5px dashed #fdba74;background:linear-gradient(180deg,#fffbeb 0%,#fff 100%);cursor:pointer;margin:0;}
		#modalRequestChangeProject .pm-chg-drop:hover,#modalRequestChangeProject .pm-chg-drop.is-drag{border-color:#f97316;background:#fff7ed;}
		#modalRequestChangeProject .pm-chg-drop input{position:absolute;opacity:0;width:0;height:0;}
		#modalRequestChangeProject .pm-chg-drop-icon{width:2.4rem;height:2.4rem;border-radius:.75rem;display:flex;align-items:center;justify-content:center;background:#fee2e2;color:#dc2626;font-size:1.05rem;margin-bottom:.15rem;}
		#modalRequestChangeProject .pm-chg-drop-title{font-weight:800;color:#9a3412;}
		#modalRequestChangeProject .pm-chg-drop-sub{font-size:.8rem;color:#94a3b8;font-weight:650;}
		#modalRequestChangeProject .pm-chg-file-list{display:flex;flex-wrap:wrap;gap:.4rem;margin-top:.55rem;}
		#modalRequestChangeProject .pm-chg-file-chip{display:inline-flex;align-items:center;gap:.4rem;padding:.32rem .65rem;border-radius:999px;background:#fff;border:1px solid #fecaca;color:#7f1d1d;font-weight:700;font-size:.82rem;}
		#modalRequestChangeProject .pm-chg-cert-box{padding:1rem 1.05rem .9rem;border-radius:1rem;border:1px solid #e2e8f0;background:#fff;box-shadow:0 10px 22px -20px rgba(15,23,42,.4);}
		#modalRequestChangeProject .pm-chg-cert-rows{display:flex;flex-direction:column;gap:.75rem;margin-top:.15rem;}
		#modalRequestChangeProject .pm-chg-cert-row{display:flex;gap:.55rem;align-items:flex-start;padding:.75rem .8rem .7rem;border-radius:.85rem;background:#f8fafc;border:1px solid #e2e8f0;}
		#modalRequestChangeProject .pm-chg-cert-side{flex:0 0 auto;display:flex;flex-direction:column;align-items:center;gap:.35rem;padding-top:.15rem;}
		#modalRequestChangeProject .pm-chg-cert-no{width:1.65rem;height:1.65rem;border-radius:999px;background:#ffedd5;color:#c2410c;font-weight:900;font-size:.78rem;display:flex;align-items:center;justify-content:center;}
		#modalRequestChangeProject .pm-chg-cert-rm{width:1.5rem;height:1.5rem;border:0;border-radius:999px;background:#fff;color:#e11d48;display:inline-flex;align-items:center;justify-content:center;}
		#modalRequestChangeProject .pm-chg-combo{position:relative;}
		#modalRequestChangeProject .pm-chg-combo-list{display:none;position:absolute;left:0;right:0;top:calc(100% + 4px);max-height:220px;overflow:auto;z-index:80;background:#fff;border:1px solid #fdba74;border-radius:.65rem;box-shadow:0 16px 32px -18px rgba(154,52,18,.4);}
		#modalRequestChangeProject .pm-chg-combo-list.is-open{display:block;}
		#modalRequestChangeProject .pm-chg-combo-item{display:block;width:100%;text-align:left;border:0;background:#fff;padding:.5rem .8rem;font-size:.9rem;cursor:pointer;}
		#modalRequestChangeProject .pm-chg-combo-item:hover,#modalRequestChangeProject .pm-chg-combo-item.is-active{background:#fff7ed;color:#9a3412;}
		#modalRequestChangeProject .pm-chg-footer{background:#fff7ed;border-top:1px solid rgba(253,186,116,.45);padding:.8rem 1.15rem;}
		#modalRequestChangeProject .pm-chg-btn-close{border-radius:.7rem;border:1px solid #cbd5e1;background:#fff;color:#334155;font-weight:800;padding:.42rem 1.05rem;}
		#modalRequestChangeProject .pm-chg-btn-submit{border-radius:.75rem;border:0;background:linear-gradient(135deg,#fb923c 0%,#ea580c 100%);color:#fff;font-weight:900;padding:.48rem 1.2rem;box-shadow:0 12px 22px -14px rgba(234,88,12,.95);}
		#modalRequestChangeProject .pm-chg-btn-submit:hover{filter:brightness(1.04);color:#fff;}
		#modalRequestChangeProject .pm-chg-btn-submit:disabled{opacity:.65;}
		@media (max-width:767px){
			#modalRequestChangeProject .pm-chg-grid{grid-template-columns:1fr;}
			#modalRequestChangeProject .pm-chg-detail-row{grid-template-columns:1fr;}
			#modalRequestChangeProject .pm-chg-fill-hint-row{grid-template-columns:1fr;gap:.1rem;}
			#modalRequestChangeProject .pm-chg-fill-eq{display:none;}
			#modalRequestChangeProject .pm-chg-section-head{flex-wrap:wrap;}
		}
	</style>
	<script>
	(function($){
		if (window.pmChgModalBound) return;
		window.pmChgModalBound = true;
		var pmChgStaffOptions = <?= (json_encode($request_operate_staff_options ?? [], JSON_UNESCAPED_UNICODE) ?: '[]') ?>;
		if (!Array.isArray(pmChgStaffOptions)) pmChgStaffOptions = [];
		var $modal = $('#modalRequestChangeProject');
		if (!$modal.length) return;
		try { $modal.appendTo(document.body); } catch (e0) {}
		function pmChgEsc(s){
			return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
		}
		function pmChgShow(){
			if (typeof $.fn.modal === 'function') { $modal.modal({ backdrop:'static', keyboard:true, show:true }); return; }
			$modal.addClass('show').css('display','block').attr('aria-hidden','false');
			if (!$('.modal-backdrop.pm-chg-backdrop').length) $('<div class="modal-backdrop fade show pm-chg-backdrop"></div>').appendTo(document.body);
			$('body').addClass('modal-open');
		}
		function pmChgHide(){
			try { $modal.modal('hide'); } catch (e1) {}
			$modal.removeClass('show').css('display','none').attr('aria-hidden','true');
			$('.modal-backdrop.pm-chg-backdrop').remove();
			if (!$('.modal.show, .modal.in').length) $('body').removeClass('modal-open').css('padding-right','');
		}
		function pmChgAddDetail(){
			var n = $('#pmChgDetailRows .pm-chg-detail-row').length + 1;
			var $row = $('<div class="pm-chg-detail-row">'+
				'<button type="button" class="pm-chg-detail-rm" title="ลบรายการ"><i class="fa fa-times"></i></button>'+
				'<div class="pm-chg-detail-col">'+
					'<div class="pm-chg-detail-lbl orig">รายละเอียดเดิม <span class="pm-chg-detail-n text-muted">('+n+')</span></div>'+
					'<textarea class="form-control pm-chg-orig" rows="3" placeholder="รายละเอียดเดิม ('+n+')"></textarea>'+
				'</div>'+
				'<div class="pm-chg-detail-col">'+
					'<div class="pm-chg-detail-lbl chg">รายละเอียดการเปลี่ยนแปลง <span class="pm-chg-detail-n text-muted">('+n+')</span></div>'+
					'<textarea class="form-control pm-chg-new" rows="3" placeholder="รายละเอียดการเปลี่ยนแปลง ('+n+')"></textarea>'+
				'</div>'+
			'</div>');
			$('#pmChgDetailRows').append($row);
			pmChgSyncDetailRm();
		}
		function pmChgRenumberDetail(){
			$('#pmChgDetailRows .pm-chg-detail-row').each(function(i){
				var n = i + 1;
				$(this).find('.pm-chg-detail-n').text('('+n+')');
				$(this).find('.pm-chg-orig').attr('placeholder', 'รายละเอียดเดิม ('+n+')');
				$(this).find('.pm-chg-new').attr('placeholder', 'รายละเอียดการเปลี่ยนแปลง ('+n+')');
			});
		}
		function pmChgSyncDetailRm(){
			var n = $('#pmChgDetailRows .pm-chg-detail-row').length;
			$('#pmChgDetailRows .pm-chg-detail-rm').css('visibility', n>1 ? 'visible' : 'hidden');
		}
		function pmChgCloseCombos(except){
			$('#pmChgCertRows .pm-chg-combo-list').each(function(){
				if (except && this === except) return;
				$(this).removeClass('is-open').empty();
			});
		}
		function pmChgRenderCombo($combo, q){
			var $list = $combo.find('.pm-chg-combo-list');
			var needle = String(q||'').trim().toLowerCase();
			var html = '', shown = 0;
			(pmChgStaffOptions||[]).forEach(function(o){
				if (shown >= 40) return;
				var id = String(o.id||''), text = String(o.text||''), pos = String(o.position||'');
				if (!id) return;
				if (needle && (text+' '+id+' '+pos).toLowerCase().indexOf(needle) === -1) return;
				html += '<button type="button" class="pm-chg-combo-item" data-id="'+pmChgEsc(id)+'" data-text="'+pmChgEsc(text)+'" data-position="'+pmChgEsc(pos)+'">'+pmChgEsc(text)+(pos ? ' <span class="text-muted">('+pmChgEsc(pos)+')</span>' : '')+'</button>';
				shown++;
			});
			if (!html) html = '<div class="px-2 py-2 text-muted">'+(needle ? 'ไม่พบรายชื่อ' : 'พิมพ์ชื่อเพื่อค้นหา')+'</div>';
			$list.html(html).addClass('is-open');
		}
		function pmChgRenumberCert(){
			$('#pmChgCertRows .pm-chg-cert-row').each(function(i){
				$(this).find('.pm-chg-cert-idx').text('('+(i+1)+')');
				$(this).find('.pm-chg-cert-no').text(String(i+1));
			});
		}
		function pmChgSyncCertRm(){
			var n = $('#pmChgCertRows .pm-chg-cert-row').length;
			$('#pmChgCertRows .pm-chg-cert-rm').css('visibility', n>1 ? 'visible' : 'hidden');
		}
		function pmChgAddCert(){
			var n = $('#pmChgCertRows .pm-chg-cert-row').length + 1;
			var $row = $('<div class="pm-chg-cert-row">'+
				'<div class="pm-chg-cert-side">'+
					'<span class="pm-chg-cert-no">'+n+'</span>'+
					'<button type="button" class="pm-chg-cert-rm" title="ลบลำดับ"><i class="fa fa-times"></i></button>'+
				'</div>'+
				'<div class="flex-grow-1 w-100">'+
					'<div class="row mx-0">'+
						'<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2">'+
							'<div class="d-flex flex-wrap justify-content-between align-items-baseline mb-1">'+
								'<label class="font-weight-bold mb-0">ผู้รับรองโครงการ <span class="text-danger">*</span> <span class="pm-chg-cert-idx text-muted">('+n+')</span></label>'+
								'<span class="text-muted" style="font-size:.8rem;">พิมพ์ค้นหาได้</span>'+
							'</div>'+
							'<div class="pm-chg-combo">'+
								'<input type="text" class="form-control pm-chg-combo-input" placeholder="- เลือก - พิมพ์ค้นหาได้" autocomplete="off">'+
								'<input type="hidden" class="pm-chg-cert-id" value="">'+
								'<div class="pm-chg-combo-list"></div>'+
							'</div>'+
						'</div>'+
						'<div class="col-md-6 col-12 pl-md-2">'+
							'<label class="d-block font-weight-bold mb-1">ตำแหน่ง <span class="text-danger">*</span></label>'+
							'<input type="text" class="form-control pm-chg-cert-pos" placeholder="ตำแหน่ง* (ดึงมาแต่ให้แก้ไขได้)" autocomplete="off">'+
						'</div>'+
					'</div>'+
				'</div>'+
			'</div>');
			$('#pmChgCertRows').append($row);
			pmChgRenumberCert();
			pmChgSyncCertRm();
		}
		function pmChgReset(){
			$('#pmChgReason').val('');
			$('#pmChgFiles').val('');
			$('#pmChgFileList').empty();
			$('#pmChgDetailRows').empty();
			pmChgAddDetail();
			$('#pmChgCertRows').empty();
			pmChgAddCert();
		}
		function pmChgCollectDetails(){
			var out=[], err='';
			$('#pmChgDetailRows .pm-chg-detail-row').each(function(){
				var orig = String($(this).find('.pm-chg-orig').val()||'').trim();
				var chg = String($(this).find('.pm-chg-new').val()||'').trim();
				if (!orig && !chg) return;
				if (!orig || !chg) { err = 'กรุณากรอกรายละเอียดเดิมและรายละเอียดการเปลี่ยนแปลงให้ครบทุกแถว'; return false; }
				out.push({ original: orig, changed: chg });
			});
			if (!err && !out.length) err = 'กรุณาระบุรายละเอียดการเปลี่ยนแปลงอย่างน้อย 1 รายการ';
			return { ok: !err && out.length>0, err: err, rows: out };
		}
		function pmChgCollectCert(){
			var out=[], err='';
			$('#pmChgCertRows .pm-chg-cert-row').each(function(){
				var sid = String($(this).find('.pm-chg-cert-id').val()||'').trim();
				var pos = String($(this).find('.pm-chg-cert-pos').val()||'').trim();
				var typed = String($(this).find('.pm-chg-combo-input').val()||'').trim();
				if (!sid && !pos && !typed) return;
				if (!sid || !pos) { err = 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับ'; return false; }
				out.push({ staff_id: parseInt(sid,10), position: pos });
			});
			if (!err && !out.length) err = 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน';
			return { ok: !err && out.length>0, err: err, rows: out };
		}
		$(document).on('click', '#btnPmChgDetailAdd', function(){ pmChgAddDetail(); });
		$(document).on('click', '#pmChgDetailRows .pm-chg-detail-rm', function(){
			if ($('#pmChgDetailRows .pm-chg-detail-row').length <= 1) return;
			$(this).closest('.pm-chg-detail-row').remove();
			pmChgRenumberDetail();
			pmChgSyncDetailRm();
		});
		$(document).on('click', '#btnPmChgCertAdd', function(){ pmChgAddCert(); });
		$(document).on('click', '#pmChgCertRows .pm-chg-cert-rm', function(){
			if ($('#pmChgCertRows .pm-chg-cert-row').length <= 1) return;
			$(this).closest('.pm-chg-cert-row').remove();
			pmChgRenumberCert();
			pmChgSyncCertRm();
		});
		$(document).on('focus input', '#pmChgCertRows .pm-chg-combo-input', function(){
			var $input = $(this);
			var $combo = $input.closest('.pm-chg-combo');
			pmChgCloseCombos($combo.find('.pm-chg-combo-list').get(0));
			pmChgRenderCombo($combo, $input.val());
		});
		$(document).on('mousedown', '#pmChgCertRows .pm-chg-combo-item', function(e){
			e.preventDefault();
			var $item = $(this);
			var $combo = $item.closest('.pm-chg-combo');
			var text = $item.attr('data-text') || '';
			var pos = $item.attr('data-position') || '';
			$combo.find('.pm-chg-cert-id').val($item.attr('data-id') || '');
			$combo.find('.pm-chg-combo-input').val(text).data('picked-text', text);
			$combo.closest('.pm-chg-cert-row').find('.pm-chg-cert-pos').val(pos);
			$combo.find('.pm-chg-combo-list').removeClass('is-open').empty();
		});
		$(document).on('blur', '#pmChgCertRows .pm-chg-combo-input', function(){
			var $input = $(this);
			setTimeout(function(){
				var $combo = $input.closest('.pm-chg-combo');
				$combo.find('.pm-chg-combo-list').removeClass('is-open').empty();
				if (String($input.val()||'') !== String($input.data('picked-text')||'')) {
					$combo.find('.pm-chg-cert-id').val('');
				}
			}, 180);
		});
		$(document).on('click', function(e){
			if ($(e.target).closest('.pm-chg-combo').length) return;
			pmChgCloseCombos();
		});
		$(document).on('change', '#pmChgFiles', function(){
			var files = this.files || [];
			var names = [];
			for (var i=0;i<files.length;i++) names.push(String(files[i].name||''));
			$('#pmChgFileList').html(names.length ? names.map(function(n){ return '<span class="pm-chg-file-chip"><i class="fa fa-file-pdf"></i>'+pmChgEsc(n)+'</span>'; }).join('') : '');
		});
		$(document).on('dragover dragenter', '#modalRequestChangeProject .pm-chg-drop', function(e){
			e.preventDefault();
			e.stopPropagation();
			$(this).addClass('is-drag');
		});
		$(document).on('dragleave drop', '#modalRequestChangeProject .pm-chg-drop', function(e){
			e.preventDefault();
			e.stopPropagation();
			$(this).removeClass('is-drag');
		});
		$(document).on('drop', '#modalRequestChangeProject .pm-chg-drop', function(e){
			var dt = e.originalEvent && e.originalEvent.dataTransfer;
			var incoming = dt && dt.files ? dt.files : null;
			var input = document.getElementById('pmChgFiles');
			if (!incoming || !incoming.length || !input) return;
			try { input.files = incoming; } catch (errDrop) {}
			$(input).trigger('change');
		});
		$(document).on('click', '#modalRequestChangeProject .pm-chg-close, #modalRequestChangeProject [data-dismiss="modal"]', function(e){
			e.preventDefault();
			pmChgHide();
		});
		$(document).on('click', '.pm-request-change-project', function(e){
			e.preventDefault();
			e.stopPropagation();
			var $btn = $(this);
			if (String($btn.attr('data-pending')||'') === '1' || $btn.prop('disabled')) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'info', title:'มีคำขอเปลี่ยนแปลงรอพิจารณา', text:'รอผู้รับรองพิจารณาตามลำดับ' });
				else alert('มีคำขอเปลี่ยนแปลงรอพิจารณา');
				return;
			}
			var pid = parseInt($btn.attr('data-id')||'0',10);
			if (!pid) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'ไม่พบโครงการ' });
				return;
			}
			$('#pmChgProjectId').val(String(pid));
			$('#pmChgName, #pmChgName2').text($btn.attr('data-name') || '-');
			$('#pmChgCode, #pmChgCode2').text($btn.attr('data-code') || '-');
			$('#pmChgBudgetSrc').text($btn.attr('data-budget-src') || $btn.data('budgetSrc') || '-');
			$('#pmChgBudget, #pmChgBudget2').text($btn.attr('data-budget') || '0');
			pmChgReset();
			pmChgShow();
		});
		$(document).on('click', '#btnPmChgSubmit', function(){
			var pid = parseInt($('#pmChgProjectId').val()||'0',10);
			var reason = String($('#pmChgReason').val()||'').trim();
			if (!pid) return;
			if (!reason) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'กรุณากรอกเหตุผลการขอเปลี่ยนแปลง' });
				else alert('กรุณากรอกเหตุผลการขอเปลี่ยนแปลง');
				return;
			}
			var details = pmChgCollectDetails();
			if (!details.ok) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title: details.err });
				else alert(details.err);
				return;
			}
			var certs = pmChgCollectCert();
			if (!certs.ok) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title: certs.err });
				else alert(certs.err);
				return;
			}
			var files = document.getElementById('pmChgFiles');
			if (files && files.files && files.files.length) {
				for (var i=0;i<files.files.length;i++) {
					var nm = String(files.files[i].name||'').toLowerCase();
					if (!nm.endsWith('.pdf')) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'เอกสารแนบต้องเป็นไฟล์ PDF เท่านั้น' });
						else alert('เอกสารแนบต้องเป็นไฟล์ PDF เท่านั้น');
						return;
					}
				}
			}
			var fd = new FormData();
			fd.append('project_id', String(pid));
			fd.append('reason', reason);
			fd.append('details_json', JSON.stringify(details.rows));
			fd.append('certifiers_json', JSON.stringify(certs.rows));
			if (files && files.files) {
				for (var j=0;j<files.files.length;j++) fd.append('change_files[]', files.files[j]);
			}
			var $sub = $('#btnPmChgSubmit').prop('disabled', true);
			$.ajax({
				url: '?page=project_manage&op=request_change_project_ajax',
				type: 'POST',
				data: fd,
				processData: false,
				contentType: false,
				dataType: 'json'
			}).done(function(res){
				if (res && res.ok === 1) {
					pmChgHide();
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon:'success', title: (res.msg || 'ส่งคำขอแล้ว'), timer: 1800, showConfirmButton:false }).then(function(){ window.location.reload(); });
					} else {
						alert(res.msg || 'ส่งคำขอแล้ว');
						window.location.reload();
					}
					return;
				}
				var err = (res && res.msg) ? res.msg : 'ส่งคำขอไม่สำเร็จ';
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title: err });
				else alert(err);
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'เชื่อมต่อไม่สำเร็จ' });
				else alert('เชื่อมต่อไม่สำเร็จ');
			}).always(function(){ $sub.prop('disabled', false); });
		});
	})(jQuery);
	</script>

