	<script>
	(function($){
		if (window.pmCancelProjectBound) return;
		window.pmCancelProjectBound = true;
		var pmCanSavedFiles = [];
		function pmCanEsc(s){ return $('<div/>').text(String(s||'')).html(); }
		function pmCanShow(){
			var $m = $('#modalRequestCancelProject');
			try { $m.appendTo(document.body); } catch(e){}
			if (typeof $.fn.modal === 'function') $m.modal('show');
			else $m.addClass('show').css('display','block');
		}
		function pmCanHide(){
			var $m = $('#modalRequestCancelProject');
			if (typeof $.fn.modal === 'function') $m.modal('hide');
			else $m.removeClass('show').css('display','none');
		}
		function pmCanRenderFiles(){
			var html = '';
			pmCanSavedFiles.forEach(function(f){
				html += '<span class="pm-can-file-chip" data-saved-id="'+f.id+'"><i class="fa fa-file-pdf"></i>'+pmCanEsc(f.name)+' <button type="button" class="pm-can-file-del" data-id="'+f.id+'" title="ลบ">&times;</button></span>';
			});
			var input = document.getElementById('pmCanFiles');
			if (input && input.files) {
				for (var i=0;i<input.files.length;i++) {
					html += '<span class="pm-can-file-chip"><i class="fa fa-file-pdf"></i>'+pmCanEsc(input.files[i].name)+'</span>';
				}
			}
			$('#pmCanFileList').html(html);
		}
		function pmCanLoad(pid){
			$.ajax({
				url: '?page=project_manage&op=get_cancel_request_ajax',
				type: 'POST',
				dataType: 'json',
				data: { op:'get_cancel_request_ajax', project_id: pid }
			}).done(function(res){
				var req = (res && res.request) ? res.request : null;
				pmCanSavedFiles = (req && Array.isArray(req.files)) ? req.files : [];
				$('#pmCanReason').val(req ? String(req.reason||'') : '');
				var st = req ? String(req.req_status||'') : '';
				if (st === 'rejected' && req && String(req.decide_note||'').trim() !== '') {
					$('#pmCanRejectNote').removeClass('d-none').text('ถูกตีกลับ: ' + req.decide_note);
				} else {
					$('#pmCanRejectNote').addClass('d-none').text('');
				}
				var locked = (st === 'pending' || st === 'approved');
				$('#pmCanReason, #pmCanFiles, #btnPmCanSave, #btnPmCanSubmit').prop('disabled', locked);
				pmCanRenderFiles();
			});
		}
		function pmCanSend(intent){
			var pid = parseInt($('#pmCanProjectId').val()||'0',10);
			var reason = String($('#pmCanReason').val()||'').trim();
			if (!pid) return;
			if (intent === 'submit' && !reason) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'กรุณากรอกเหตุผลการขอยกเลิกโครงการ' });
				else alert('กรุณากรอกเหตุผลการขอยกเลิกโครงการ');
				return;
			}
			var files = document.getElementById('pmCanFiles');
			if (files && files.files && files.files.length) {
				for (var i=0;i<files.files.length;i++) {
					if (!String(files.files[i].name||'').toLowerCase().endsWith('.pdf')) {
						if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'เอกสารแนบต้องเป็นไฟล์ PDF เท่านั้น' });
						else alert('เอกสารแนบต้องเป็นไฟล์ PDF เท่านั้น');
						return;
					}
				}
			}
			var fd = new FormData();
			fd.append('project_id', String(pid));
			fd.append('reason', reason);
			fd.append('intent', intent);
			if (files && files.files) {
				for (var j=0;j<files.files.length;j++) fd.append('cancel_files[]', files.files[j]);
			}
			var $btns = $('#btnPmCanSave, #btnPmCanSubmit').prop('disabled', true);
			$.ajax({
				url: '?page=project_manage&op=request_cancel_project_ajax',
				type: 'POST',
				data: fd,
				processData: false,
				contentType: false,
				dataType: 'json'
			}).done(function(res){
				if (res && res.ok === 1) {
					pmCanHide();
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon:'success', title: (res.msg || 'บันทึกแล้ว'), timer: 1800, showConfirmButton:false }).then(function(){ window.location.reload(); });
					} else {
						alert(res.msg || 'บันทึกแล้ว');
						window.location.reload();
					}
					return;
				}
				var err = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title: err });
				else alert(err);
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'เชื่อมต่อไม่สำเร็จ' });
				else alert('เชื่อมต่อไม่สำเร็จ');
			}).always(function(){ $btns.prop('disabled', false); });
		}
		$(document).on('click', '.pm-request-cancel-project', function(e){
			e.preventDefault();
			e.stopPropagation();
			var $btn = $(this);
			if (String($btn.attr('data-pending')||'') === '1' || $btn.prop('disabled')) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'info', title:'มีคำขอยกเลิกรอพิจารณา', text:'รอหน่วยแผนพิจารณาอนุมัติการยกเลิก' });
				else alert('มีคำขอยกเลิกรอหน่วยแผนพิจารณา');
				return;
			}
			var pid = parseInt($btn.attr('data-id')||'0',10);
			if (!pid) return;
			$('#pmCanProjectId').val(String(pid));
			$('#pmCanName, #pmCanName2').text($btn.attr('data-name') || '-');
			$('#pmCanCode').text($btn.attr('data-code') || '-');
			$('#pmCanBudgetSrc').text($btn.attr('data-budget-src') || '-');
			$('#pmCanBudget').text($btn.attr('data-budget') || '0');
			$('#pmCanFiles').val('');
			pmCanSavedFiles = [];
			pmCanRenderFiles();
			pmCanLoad(pid);
			pmCanShow();
		});
		$(document).on('click', '#modalRequestCancelProject .pm-can-close, #modalRequestCancelProject [data-dismiss="modal"]', function(e){
			e.preventDefault();
			pmCanHide();
		});
		$(document).on('change', '#pmCanFiles', function(){ pmCanRenderFiles(); });
		$(document).on('dragover dragenter', '#modalRequestCancelProject .pm-can-drop', function(e){ e.preventDefault(); e.stopPropagation(); $(this).addClass('is-drag'); });
		$(document).on('dragleave drop', '#modalRequestCancelProject .pm-can-drop', function(e){ e.preventDefault(); e.stopPropagation(); $(this).removeClass('is-drag'); });
		$(document).on('drop', '#modalRequestCancelProject .pm-can-drop', function(e){
			var dt = e.originalEvent && e.originalEvent.dataTransfer;
			var incoming = dt && dt.files ? dt.files : null;
			var input = document.getElementById('pmCanFiles');
			if (!incoming || !incoming.length || !input) return;
			try { input.files = incoming; } catch (errDrop) {}
			$(input).trigger('change');
		});
		$(document).on('click', '#pmCanFileList .pm-can-file-del', function(e){
			e.preventDefault();
			var fid = parseInt($(this).attr('data-id')||'0',10);
			if (!fid) return;
			$.ajax({
				url: '?page=project_manage&op=delete_cancel_file_ajax',
				type: 'POST',
				dataType: 'json',
				data: { op:'delete_cancel_file_ajax', file_id: fid }
			}).done(function(res){
				if (res && res.ok === 1) {
					pmCanSavedFiles = pmCanSavedFiles.filter(function(f){ return Number(f.id) !== fid; });
					pmCanRenderFiles();
				}
			});
		});
		$(document).on('click', '#btnPmCanSave', function(){ pmCanSend('save'); });
		$(document).on('click', '#btnPmCanSubmit', function(){ pmCanSend('submit'); });
	})(jQuery);
	</script>
	<?php endif ?>
	<?php if (!empty($pm_is_plan_admin) && !empty($pm_change_history)): ?>
	<script>
	(function($){
		$(document).on('click', '.pm-chg-apply-btn', function(){
			var $btn = $(this);
			var rid = parseInt($btn.attr('data-request-id') || '0', 10);
			var note = String($btn.closest('.pm-chg-hist-apply').find('.pm-chg-apply-note').val() || '').trim();
			if (!rid) return;
			if (!note) {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'กรุณาระบุรายละเอียดที่แก้ไข' });
				else alert('กรุณาระบุรายละเอียดที่แก้ไข');
				return;
			}
			$btn.prop('disabled', true);
			$.ajax({
				url: '?page=project_manage&op=plan_admin_apply_change_ajax',
				type: 'POST',
				dataType: 'json',
				data: { op: 'plan_admin_apply_change_ajax', change_request_id: rid, apply_note: note }
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon:'success', title: (res.msg || 'บันทึกแล้ว'), timer: 1400, showConfirmButton:false }).then(function(){ window.location.reload(); });
					} else {
						alert(res.msg || 'บันทึกแล้ว');
						window.location.reload();
					}
					return;
				}
				var err = (res && res.msg) ? res.msg : 'บันทึกไม่สำเร็จ';
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title: err });
				else alert(err);
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'เชื่อมต่อไม่สำเร็จ' });
				else alert('เชื่อมต่อไม่สำเร็จ');
			}).always(function(){ $btn.prop('disabled', false); });
		});
	})(jQuery);
	</script>
	<?php endif ?>
