	<script>
	(function($){
		if (window.pmRoMemoUiBound) return;
		window.pmRoMemoUiBound = true;
		var pmRoCertStaffOptions = <?= (json_encode($request_operate_staff_options ?? [], JSON_UNESCAPED_UNICODE) ?: '[]') ?>;
		if (!Array.isArray(pmRoCertStaffOptions)) pmRoCertStaffOptions = [];
		var $modalRo = $('#modalRequestOperateMemo');
		if (!$modalRo.length) return;
		// ย้ายออกจาก .pm-wizard (overflow-x:clip) ไม่งั้น modal โชว์ไม่ขึ้น
		try { $modalRo.appendTo(document.body); } catch (errAppendRo) {}
		function pmRoShowAlert(icon, title, text) {
			if (typeof Swal !== 'undefined') Swal.fire({ icon: icon || 'error', title: title || 'ไม่สำเร็จ', text: text || '' });
			else alert((title ? title + '\n' : '') + (text || ''));
		}
		function pmRoShowModal() {
			if (typeof $.fn.modal === 'function') {
				$modalRo.modal({ backdrop: 'static', keyboard: true, show: true });
				return true;
			}
			$modalRo.addClass('show').css('display', 'block').attr('aria-hidden', 'false').attr('aria-modal', 'true');
			if (!$('.modal-backdrop.pm-ro-memo-backdrop').length) {
				$('<div class="modal-backdrop fade show pm-ro-memo-backdrop"></div>').appendTo(document.body);
			}
			$('body').addClass('modal-open');
			return true;
		}
		function pmRoHideModal() {
			var $modals = $('#modalRequestOperateMemo');
			$modals.each(function(){
				var el = this;
				try { $(el).modal('hide'); } catch (_e0) {}
				try {
					if (window.bootstrap && window.bootstrap.Modal) {
						var ins = window.bootstrap.Modal.getInstance(el);
						if (ins) ins.hide();
					}
				} catch (_e1) {}
				try {
					el.classList.remove('show', 'in');
					el.style.display = 'none';
					el.setAttribute('aria-hidden', 'true');
					el.removeAttribute('aria-modal');
				} catch (_e2) {}
			});
			try {
				if (!document.querySelector('.modal.show, .modal.in')) {
					document.body.classList.remove('modal-open');
					document.body.style.removeProperty('padding-right');
					document.querySelectorAll('.modal-backdrop').forEach(function(b){
						try { b.parentNode && b.parentNode.removeChild(b); } catch (_e3) {}
					});
				} else {
					$('.modal-backdrop.pm-ro-memo-backdrop').remove();
				}
			} catch (_e4) {}
		}
		function pmRoInitCertSelect($sel) {
			if (!$sel || !$sel.length || typeof $.fn.select2 !== 'function') return;
			try { if ($sel.hasClass('select2-hidden-accessible')) $sel.select2('destroy'); } catch (e0) {}
			$sel.select2({
				placeholder: '- เลือก -',
				allowClear: true,
				width: '100%',
				dropdownParent: $modalRo.length ? $modalRo : $(document.body)
			});
			$sel.off('change.pmCertPos').on('change.pmCertPos', function(){
				var $s = $(this);
				var pos = String($s.find('option:selected').attr('data-position') || '');
				$s.closest('.pm-ro-cert-row').find('input.pm-ro-cert-position').val(pos);
			});
		}
		function pmRoRenumberCertRows() {
			var $wrap = $('#pmRoCertifiersRows');
			if (!$wrap.length) return;
			$wrap.find('.pm-ro-cert-row').each(function(i){
				var t = '(' + (i + 1) + ')';
				$(this).find('.pm-ro-cert-lbl-idx').text(t);
			});
		}
		function pmRoSyncCertRemoveVisibility() {
			var $wrap = $('#pmRoCertifiersRows');
			if (!$wrap.length) return;
			var n = $wrap.find('.pm-ro-cert-row').length;
			$wrap.find('.pm-ro-cert-remove').css('visibility', n > 1 ? 'visible' : 'hidden');
		}
		function pmRoAddCertRow() {
			var $wrap = $('#pmRoCertifiersRows');
			if (!$wrap.length) return;
			var n = $wrap.find('.pm-ro-cert-row').length + 1;
			var remBtn = '<button type="button" class="btn btn-sm btn-link text-danger p-0 pm-ro-cert-remove" title="ลบแถว"><i class="fa fa-times"></i></button>';
			var $row = $(
				'<div class="pm-ro-cert-row">' +
					'<div class="pm-ro-cert-side">' + remBtn + '</div>' +
					'<div class="pm-ro-cert-fields flex-grow-1">' +
						'<div class="row mx-0">' +
							'<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2">' +
								'<label class="d-block pm-ro-cert-lbl">ผู้รับรองโครงการ <span class="text-danger">*</span> <span class="pm-ro-cert-lbl-idx text-muted font-weight-bold">(' + n + ')</span></label>' +
								'<select class="form-control pm-ro-cert-select"></select>' +
								'<small class="text-muted d-block mt-1" style="font-size:.78rem;">พิมพ์ค้นหาได้</small>' +
							'</div>' +
							'<div class="col-md-6 col-12 pl-md-2">' +
								'<label class="d-block pm-ro-cert-lbl">ตำแหน่ง <span class="text-danger">*</span></label>' +
								'<input type="text" class="form-control pm-ro-cert-position" placeholder="ตำแหน่ง* (กรอก)" autocomplete="off">' +
							'</div>' +
						'</div>' +
					'</div>' +
				'</div>'
			);
			$wrap.append($row);
			var $sel = $row.find('select');
			$sel.append(new Option('- เลือก -', '', false, false));
			(pmRoCertStaffOptions || []).forEach(function(o){
				if (!o) return;
				var opt = new Option(String(o.text || ('Staff #' + o.id)), String(o.id || ''), false, false);
				if (o.position) $(opt).attr('data-position', String(o.position));
				$sel.append(opt);
			});
			pmRoInitCertSelect($sel);
			pmRoRenumberCertRows();
			pmRoSyncCertRemoveVisibility();
		}
		function pmRoResetCertRows() {
			var $wrap = $('#pmRoCertifiersRows');
			if (!$wrap.length) return;
			$wrap.find('.pm-ro-cert-select').each(function(){
				try { if ($(this).hasClass('select2-hidden-accessible')) $(this).select2('destroy'); } catch (e1) {}
			});
			$wrap.empty();
			pmRoAddCertRow();
			pmRoSyncCertRemoveVisibility();
		}
		function pmRoCollectCertPayload() {
			var $wrap = $('#pmRoCertifiersRows');
			var out = [];
			var err = '';
			if (!$wrap.length) return { ok: false, err: 'ไม่พบแบบฟอร์มผู้รับรอง', rows: [] };
			$wrap.find('.pm-ro-cert-row').each(function(){
				var $r = $(this);
				var sid = String($r.find('select').val() || '').trim();
				var pos = String($r.find('input.pm-ro-cert-position').val() || '').trim();
				if (sid === '' && pos === '') return;
				if (sid === '' || pos === '') {
					err = 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับที่ระบุ';
					return false;
				}
				out.push({ staff_id: parseInt(sid, 10), position: pos });
			});
			if (err === '' && out.length === 0) err = 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน';
			return { ok: err === '' && out.length > 0, err: err, rows: out };
		}
		function pmRoMemoFillFromBtn($btn) {
			var unit = $btn.attr('data-memo-unit') || '-';
			$('#pmRoMemoProjectId').val($btn.attr('data-id') || '0');
			$('#pmRoMemoTblUnit').text((unit || '').trim() || '-');
			var code = $btn.attr('data-memo-code') || '-';
			var name = $btn.attr('data-memo-name') || '-';
			$('#pmRoMemoTblCode').text(code);
			$('#pmRoMemoTblName').text(name);
			$('#pmRoMemoTblCode2').text(code);
			$('#pmRoMemoTblName2').text(name);
			$('#pmRoMemoTblBudget').text($btn.attr('data-memo-budget') || '0');
			$('#pmRoMemoTblBudgetSrc').text($btn.attr('data-memo-budget-src') || '-');
			pmRoResetCertRows();
		}
		$(document).on('click', '#btnPmRoCertAdd', function(){ pmRoAddCertRow(); });
		$(document).on('click', '.pm-ro-cert-remove', function(){
			var $wrap = $('#pmRoCertifiersRows');
			if ($wrap.find('.pm-ro-cert-row').length <= 1) return;
			var $row = $(this).closest('.pm-ro-cert-row');
			try { $row.find('select').select2('destroy'); } catch (e2) {}
			$row.remove();
			pmRoRenumberCertRows();
			pmRoSyncCertRemoveVisibility();
		});
		$(document).on('click', '#modalRequestOperateMemo .pm-ro-memo-close, #modalRequestOperateMemo [data-dismiss="modal"], #modalRequestOperateMemo [data-bs-dismiss="modal"]', function(e){
			if ($(this).is('#pmRoMemoBtnConfirm')) return;
			e.preventDefault();
			e.stopPropagation();
			pmRoHideModal();
		});
		$(document).on('keydown.pmRoMemoClose', function(e){
			if (e.key !== 'Escape' && e.keyCode !== 27) return;
			if (!$('#modalRequestOperateMemo').hasClass('show')) return;
			pmRoHideModal();
		});
			$(document).on('click', '[data-action="request-operate-project"]', function(e){
			e.preventDefault();
			e.stopPropagation();
			var $b = $(this);
			if (window.PM_IS_MIDYEAR && String($('#section2-midyear_reason').val() || $('#pmMidyearReason').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim() === '') {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'กรุณากรอกเหตุผลการขอเพิ่มโครงการระหว่างปี' });
				else alert('กรุณากรอกเหตุผลการขอเพิ่มโครงการระหว่างปี');
				try {
					var $mid = $('#section2-midyear_reason').closest('.pm-section2-item');
					if ($mid.length) {
						$('html, body').animate({ scrollTop: Math.max(0, $mid.offset().top - 90) }, 280);
						$mid.find('.btn-section2-edit').trigger('click');
					}
				} catch(eF){}
				return;
			}
			var pid = parseInt($b.attr('data-id') || '0', 10);
			if (!pid) {
				pmRoShowAlert('warning', 'ไม่พบโครงการ', 'ไม่สามารถเปิดแบบฟอร์มขออนุมัติดำเนินโครงการได้');
				return;
			}
			try {
				pmRoMemoFillFromBtn($b);
				pmRoShowModal();
			} catch (errOpen) {
				pmRoShowAlert('error', 'เปิดแบบฟอร์มไม่สำเร็จ', (errOpen && errOpen.message) ? String(errOpen.message) : 'เกิดข้อผิดพลาดในหน้าเว็บ');
			}
		});
		$(document).on('click', '#pmRoMemoBtnConfirm', function(){
			var id = parseInt($('#pmRoMemoProjectId').val() || '0', 10);
			if (!id) {
				pmRoShowAlert('warning', 'ไม่พบโครงการ', 'กรุณาปิดแล้วเปิดแบบฟอร์มใหม่');
				return;
			}
			var certPack = pmRoCollectCertPayload();
			if (!certPack.ok) {
				pmRoShowAlert('warning', 'กรุณากรอกข้อมูล', certPack.err || 'ข้อมูลไม่ครบ');
				return;
			}
			var $btn = $(this).prop('disabled', true);
			$.ajax({
				url: '?page=project_manage&op=request_operate_project_ajax',
				type: 'POST',
				dataType: 'json',
				data: { project_id: id, certifiers_json: JSON.stringify(certPack.rows) }
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					try { pmRoHideModal(); } catch (err) {}
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon:'success', title:'ส่งคำขออนุมัติดำเนินโครงการแล้ว', timer:1100, showConfirmButton:false })
							.then(function(){ window.location.reload(); });
					} else {
						window.location.reload();
					}
					return;
				}
				var msg = (res && res.msg) ? res.msg : 'ไม่สามารถขออนุมัติดำเนินโครงการได้';
				pmRoShowAlert('error', 'ไม่สำเร็จ', msg);
			}).fail(function(xhr){
				var dbg = '';
				try {
					var raw = String((xhr && xhr.responseText) || '').trim();
					if (raw) dbg = ' (ตอบกลับ: ' + raw.substring(0, 180) + ')';
				} catch (_e) {}
				pmRoShowAlert('error', 'ไม่สำเร็จ', 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้' + dbg);
			}).always(function(){ $btn.prop('disabled', false); });
		});
	})(jQuery);
	</script>
	<?php endif ?>
