	<script>
	(function($){
		if (window.pmIncEditCertUiBound) return;
		window.pmIncEditCertUiBound = true;

		function initIncEditSelect(){
			var $sel = $('#pmIncEditStaff');
			if (!$sel.length || typeof $.fn.select2 !== 'function') return;
			try { if ($sel.hasClass('select2-hidden-accessible')) $sel.select2('destroy'); } catch(_e0){}
			var $dd = $('#modalEditIncludeCertRow .modal-body');
			if (!$dd.length) $dd = $('#modalEditIncludeCertRow .modal-content');
			$sel.select2({ placeholder: '- เลือก -', allowClear: true, width: '100%', dropdownParent: $dd });
			$sel.off('change.pmCertPos').on('change.pmCertPos', function(){
				var p = String($(this).find('option:selected').attr('data-position') || '');
				$('#pmIncEditPosition').val(p);
			});
		}

		function pmHideIncEditModal(){
			var $m = $('#modalEditIncludeCertRow');
			if (!$m.length) return;
			try { $m.modal('hide'); } catch(_e1){}
			try {
				if (window.bootstrap && window.bootstrap.Modal) {
					var el = document.getElementById('modalEditIncludeCertRow');
					if (el) {
						var ins = window.bootstrap.Modal.getInstance(el);
						if (ins) ins.hide();
					}
				}
			} catch(_e2){}
			$m.removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
			$('.modal-backdrop.pm-inc-edit-backdrop').remove();
			if (!$('.modal.show, .modal.in').length) $('body').removeClass('modal-open');
		}

		function pmOpenIncEditModal(){
			var $m = $('#modalEditIncludeCertRow');
			if (!$m.length) return;
			try { $m.appendTo('body'); } catch(_eAppend){}
			$('.modal.show, .modal.in').not($m).each(function(){
				try { $(this).modal('hide'); } catch(_e3){}
				$(this).removeClass('show in').css('display', 'none').attr('aria-hidden', 'true').removeAttr('aria-modal');
			});
			$('.modal-backdrop').not('.pm-inc-edit-backdrop').remove();
			try {
				if (typeof $m.modal === 'function') {
					$m.modal({ backdrop: 'static', keyboard: true, show: true });
					return;
				}
			} catch(_e4){}
			try {
				var el = document.getElementById('modalEditIncludeCertRow');
				if (window.bootstrap && window.bootstrap.Modal && el) {
					window.bootstrap.Modal.getOrCreateInstance(el, { backdrop: 'static', keyboard: true }).show();
					return;
				}
			} catch(_e5){}
			if (!$('.modal-backdrop.pm-inc-edit-backdrop').length) {
				$('body').append('<div class="modal-backdrop fade show pm-inc-edit-backdrop"></div>');
			}
			$('body').addClass('modal-open');
			$m.addClass('show').css({ display: 'block' }).attr('aria-modal', 'true').removeAttr('aria-hidden');
		}

		$(document).on('click', '.pm-inc-edit-cert-row', function(e){
			e.preventDefault();
			e.stopPropagation();
			var $b = $(this);
			var rid = parseInt($b.attr('data-request-id') || '0', 10) || 0;
			var so = parseInt($b.attr('data-sort-order') || '0', 10) || 0;
			var sid = parseInt($b.attr('data-staff-id') || '0', 10) || 0;
			var pos = String($b.attr('data-position') || '').trim();
			if (!rid || !so) return;
			$('#pmIncEditReqId').val(String(rid));
			$('#pmIncEditSortOrder').val(String(so));
			$('#pmIncEditSortLabel').text(String(so));
			$('#pmIncEditPosition').val(pos);
			$('#pmIncEditStaff').val(sid ? String(sid) : '');
			$('#pmIncEditMsg').addClass('d-none').text('');
			initIncEditSelect();
			$('#pmIncEditPosition').val(pos);
			pmOpenIncEditModal();
		});

		$(document).on('click', '#pmIncEditSaveBtn', function(){
			var $btn = $(this).prop('disabled', true);
			var rid = parseInt($('#pmIncEditReqId').val() || '0', 10) || 0;
			var so = parseInt($('#pmIncEditSortOrder').val() || '0', 10) || 0;
			var sid = parseInt($('#pmIncEditStaff').val() || '0', 10) || 0;
			var pos = String($('#pmIncEditPosition').val() || '').trim();
			var $msg = $('#pmIncEditMsg');
			if (!rid || !so || !sid || !pos) {
				$msg.removeClass('d-none').text('กรุณากรอกผู้ตรวจสอบและตำแหน่งให้ครบ');
				$btn.prop('disabled', false);
				return;
			}
			$msg.addClass('d-none').text('');
			$.ajax({
				url: '?page=project_manage&op=plan_admin_edit_include_cert_row_ajax',
				type: 'POST',
				dataType: 'json',
				data: { op:'plan_admin_edit_include_cert_row_ajax', request_id: rid, sort_order: so, staff_id: sid, position: pos }
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					pmHideIncEditModal();
					if (typeof Swal !== 'undefined') {
						Swal.fire({ icon:'success', title: String(res.msg || 'บันทึกเรียบร้อย'), timer: 1100, showConfirmButton: false })
							.then(function(){ window.location.reload(); });
					} else {
						window.location.reload();
					}
					return;
				}
				$msg.removeClass('d-none').text((res && res.msg) ? String(res.msg) : 'บันทึกไม่สำเร็จ');
			}).fail(function(xhr){
				var t = '';
				try { t = String(xhr && xhr.responseText ? xhr.responseText : '').trim(); } catch(_e6){}
				if (t.length > 240) t = t.slice(0, 240) + '...';
				$msg.removeClass('d-none').text(t || 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้');
			}).always(function(){ $btn.prop('disabled', false); });
		});

		$('#modalEditIncludeCertRow').on('hidden.bs.modal', function(){
			$('.modal-backdrop.pm-inc-edit-backdrop').remove();
		});
		$(document).on('click', '#modalEditIncludeCertRow [data-dismiss="modal"], #modalEditIncludeCertRow .close', function(){
			pmHideIncEditModal();
		});
	})(jQuery);
	</script>
	<?php endif ?>
	</div><!-- /.pm-wizard -->
	<?php
	return;
}
?>
<?php
try {
$project_group = isset($_GET['project_group']) ? trim((string)$_GET['project_group']) : 'draft';
if ($project_group !== 'draft' && $project_group !== 'plan') {
	$project_group = 'draft';
}
$pm_status_filter = isset($_GET['status_filter']) ? trim((string)$_GET['status_filter']) : '';
$pm_status_filter_options = [];
$include_request_id = isset($_GET['include_request_id']) ? (int)$_GET['include_request_id'] : 0;
$include_request_project_ids = [];
$include_resubmit_certifiers_for_js = [];
$include_resubmit_certifiers_locked = false;
if ($include_request_id > 0) {
	if (function_exists('ensureIncludeRequestTables')) {
		ensureIncludeRequestTables($db_Project);
	}
	$qirIr = @mysqli_query(
		$db_Project,
		"SELECT id, submitter_staff_id, status,
		        IFNULL(submitter_reply_note,'') AS submitter_reply_note,
		        IFNULL(submitter_reply_updated_at,'') AS submitter_reply_updated_at,
		        IFNULL(admin_fix_sent_at,'') AS admin_fix_sent_at
		 FROM project_include_request WHERE id='" . $include_request_id . "' LIMIT 1"
	);
	$irReqRow = $qirIr ? mysqli_fetch_assoc($qirIr) : null;
	if ($irReqRow && (string)($irReqRow['status'] ?? '') === 'rejected') {
		// โหลดเฉพาะโครงการที่ถูกเลือกตีกลับ (return_selected=1)
		$include_returned_pending_ids = [];
		$include_returned_confirmed_ids = [];
		$qpiIr = @mysqli_query(
			$db_Project,
			"SELECT project_id, IFNULL(return_selected,0) AS return_selected, IFNULL(fix_status,'') AS fix_status
			 FROM project_include_request_item WHERE request_id='" . $include_request_id . "' ORDER BY sort_order ASC"
		);
		while ($qpiIr && ($pir = mysqli_fetch_assoc($qpiIr))) {
			$ipid = (int)($pir['project_id'] ?? 0);
			if ($ipid <= 0) {
				continue;
			}
			if ((int)($pir['return_selected'] ?? 0) !== 1) {
				continue;
			}
			$include_request_project_ids[$ipid] = $ipid;
			$fst = trim((string)($pir['fix_status'] ?? ''));
			if ($fst === '' || $fst === 'pending') {
				$include_returned_pending_ids[$ipid] = $ipid;
			} else {
				$include_returned_confirmed_ids[$ipid] = $ipid;
			}
		}

		// สิทธิ์เข้าดู/แก้ไข: ผู้ยื่นเสนอ "หรือ" เจ้าของ/ผู้ร่วมโครงการ
		$is_submitter_for_req = ((int)($irReqRow['submitter_staff_id'] ?? 0) === (int)$staff_id);
		$allowed_by_owner = false;
		if (!$is_submitter_for_req && !empty($include_request_project_ids) && function_exists('staffCanEditPreProjectRichFields')) {
			foreach ($include_request_project_ids as $pid) {
				if (staffCanEditPreProjectRichFields($db_Project, (int)$pid, (int)$staff_id, (string)$staff_code, (string)$code_unit)) {
					$allowed_by_owner = true;
					break;
				}
			}
		}
		if (!$is_submitter_for_req && !$allowed_by_owner) {
			$include_request_id = 0;
			$include_request_project_ids = [];
			$include_resubmit_certifiers_for_js = [];
			$include_resubmit_certifiers_locked = false;
		} else {
			if (!empty($include_returned_pending_ids)) {
				$inPend = implode(',', array_map('intval', array_values($include_returned_pending_ids)));
				$healIds = [];
				$qHealSent = @mysqli_query(
					$db_Project,
					"SELECT id FROM pre_project
					 WHERE status='1'
					   AND id IN (" . $inPend . ")
					   AND status_project='2'"
				);
				while ($qHealSent && ($hr = mysqli_fetch_assoc($qHealSent))) {
					$hid = (int)($hr['id'] ?? 0);
					if ($hid > 0) {
						$healIds[$hid] = $hid;
					}
				}
				if (!empty($healIds)) {
					$inHeal = implode(',', array_map('intval', array_values($healIds)));
					$healSid = (int)$staff_id;
					@mysqli_query(
						$db_Project,
						"UPDATE project_include_request_item
						 SET fix_status='confirmed',
						     fix_at=NOW(),
						     fix_staff_id='" . $healSid . "',
						     fix_note=IF(TRIM(IFNULL(fix_note,''))='', 'ส่งร่างโครงการหลังแก้ไข', fix_note)
						 WHERE request_id='" . $include_request_id . "'
						   AND project_id IN (" . $inHeal . ")
						   AND IFNULL(return_selected,0)=1
						   AND IFNULL(fix_status,'') IN ('','pending')"
					);
					@mysqli_query(
						$db_Project,
						"UPDATE pre_project
						 SET status_project='3', dates=NOW()
						 WHERE status='1'
						   AND id IN (" . $inHeal . ")
						   AND status_project='2'"
					);
					foreach ($healIds as $hid) {
						unset($include_returned_pending_ids[$hid]);
						$include_returned_confirmed_ids[$hid] = $hid;
					}
				}
				if (!empty($include_returned_pending_ids)) {
					$inPend = implode(',', array_map('intval', array_values($include_returned_pending_ids)));
					@mysqli_query(
						$db_Project,
						"UPDATE pre_project
						 SET status_project='8', dates=NOW()
						 WHERE status='1'
						   AND id IN (" . $inPend . ")
						   AND status_project IN ('3','4','9')"
					);
				}
			}
			if (!empty($include_returned_confirmed_ids)) {
				$inConf = implode(',', array_map('intval', array_values($include_returned_confirmed_ids)));
				@mysqli_query(
					$db_Project,
					"UPDATE pre_project
					 SET status_project='3', dates=NOW()
					 WHERE status='1'
					   AND id IN (" . $inConf . ")
					   AND status_project IN ('8','2')"
				);
			}
			// ล็อกโหมดยื่นซ้ำเมื่อยืนยันครบแล้ว (หรือ Admin ส่งแล้ว)
			$include_resubmit_certifiers_locked = empty($include_returned_pending_ids)
				|| trim((string)($irReqRow['admin_fix_sent_at'] ?? '')) !== '';

			// เติมข้อมูลโครงการในคำขอเข้ามาในรายการ (กรณีผู้ยื่น/เจ้าของ ไม่ใช่ staff_insert)
			$existingIds = [];
			if (!empty($project_list)) {
				foreach ($project_list as $__p) {
					$existingIds[(int)($__p['id'] ?? 0)] = 1;
				}
			} else {
				$project_list = [];
			}
			$need = [];
			foreach ($include_request_project_ids as $pid) {
				$pid = (int)$pid;
				if ($pid > 0 && empty($existingIds[$pid])) {
					$need[$pid] = $pid;
				}
			}
			if (!empty($need)) {
				$in = implode(',', array_map('intval', array_values($need)));
				$yearsEsc2 = mysqli_real_escape_string($db_Project, (string)$years_select);
				$qAdd = @mysqli_query($db_Project, "
					SELECT p.*,
						   IFNULL((SELECT SUM(pa.total) FROM project_activity_budget pa WHERE pa.code_pre_project = p.id AND pa.status != '99'), 0) AS budget_total
					FROM pre_project p
					WHERE p.status='1'
					  AND p.year_project='".$yearsEsc2."'
					  AND p.id IN (".$in.")
				");
				while ($qAdd && ($ar = mysqli_fetch_assoc($qAdd))) {
					$pid = (int)($ar['id'] ?? 0);
					if ($pid <= 0) continue;
					if ($is_submitter_for_req) {
						$project_list[] = $ar;
						$existingIds[$pid] = 1;
						continue;
					}
					if (function_exists('staffCanEditPreProjectRichFields') && staffCanEditPreProjectRichFields($db_Project, $pid, (int)$staff_id, (string)$staff_code, (string)$code_unit)) {
						$project_list[] = $ar;
						$existingIds[$pid] = 1;
					}
				}
			}

			// ผู้รับรองจากคำขอเดิม (ยื่นซ้ำหลังตีกลับ — ใช้ชุดเดิม แก้ไขไม่ได้)
			$__reqCertId = (int)$include_request_id;
			$__qCert = @mysqli_query(
				$db_Project,
				"SELECT sort_order, staff_id, position_title FROM project_include_request_certifier
				 WHERE request_id='" . $__reqCertId . "' ORDER BY sort_order ASC"
			);
			while ($__qCert && ($__cr = mysqli_fetch_assoc($__qCert))) {
				$__csid = (int)($__cr['staff_id'] ?? 0);
				if ($__csid <= 0) {
					continue;
				}
				$__cnm = 'Staff #' . $__csid;
				$__qs = @mysqli_query($db_person, "SELECT fname, lname FROM staff WHERE id='" . $__csid . "' LIMIT 1");
				if ($__qs && ($__sr = mysqli_fetch_assoc($__qs))) {
					$__cnm = trim((string)(($__sr['fname'] ?? '') . ' ' . ($__sr['lname'] ?? '')));
					if ($__cnm === '') {
						$__cnm = 'Staff #' . $__csid;
					}
				}
				$include_resubmit_certifiers_for_js[] = [
					'staff_id' => $__csid,
					'position' => trim((string)($__cr['position_title'] ?? '')),
					'name' => $__cnm,
				];
			}
			if (count($include_resubmit_certifiers_for_js) > 0 && empty($include_returned_pending_ids)) {
				$include_resubmit_certifiers_locked = true;
			}
		}
	} else {
		$include_request_id = 0;
		$include_request_project_ids = [];
		$include_resubmit_certifiers_for_js = [];
		$include_resubmit_certifiers_locked = false;
	}
}
$pmKeepIncludeQs = ($include_request_id > 0) ? ('&include_request_id=' . (int)$include_request_id . '&project_group=draft') : '';

$project_list_filtered = [];
// สำหรับ modal "ขอบรรจุโครงการ" (เฉพาะ Admin): สถานะส่งร่าง + หน่วยตัวเองเป็นหน่วยงานหลักเท่านั้น
$include_candidates = [];
if (!empty($project_list)) {
	foreach ($project_list as $pr) {
		$st = (string)($pr['status_project'] ?? '0');
		$nrRow = trim((string)($pr['notify_result'] ?? ''));
		$__pid = (int)($pr['id'] ?? 0);
		$__isMidyear = (int)($pr['midyear_request'] ?? 0) === 1;
		$__canIncludeMain = $is_unit_admin
			&& function_exists('staffMatchesProjectMainUnitForInclude')
			&& staffMatchesProjectMainUnitForInclude($db_Project, $pr, (int)$staff_id, (string)$code_unit);
		if ($__canIncludeMain && $st === '2') {
			$include_candidates[] = $pr;
		} elseif ($__canIncludeMain && $include_request_id > 0 && $st === '8' && isset($include_request_project_ids[$__pid])) {
			// ยื่นขอบรรจุซ้ำหลังตีกลับ: โครงการสถานะ 8 ในคำขอเดิม
			$include_candidates[] = $pr;
		}
		if ($project_group === 'draft') {
			// แท็บ ร่างโครงการ:
			// - แสดง 0/2/3/9 เสมอ
			// - แสดง 4 ที่ยังไม่บรรจุแผน (รอหน่วยแผน) ให้ผู้ใช้เห็นเป็นรอบรรจุบนหน้าร่าง
			// - แสดง 8 เฉพาะกรณี "ยังไม่อยู่แผน" (ถ้าเคยบรรจุแผนแล้ว จะไปอยู่แท็บแผนแทน)
			// - Plan(Admin): สถานะ 4 ที่ "ยังไม่แจ้งผล" ให้อยู่แท็บร่าง (เพื่อให้กดแจ้งผลได้)
			// - ค่าว่าง/null ของ status_project ถือเป็นร่าง
			if ($__isMidyear) {
				continue;
			}
			$pm_is_notified_included = in_array($nrRow, ['บรรจุแผน', 'บรรจุแผนและแก้ไข'], true);
			$allowDraft = in_array($st, ['0','2','3','9',''], true)
				|| ($st === '4' && !$pm_is_notified_included)
				|| ($st === '8' && $nrRow !== 'บรรจุแผน');
			if ($allowDraft) {
				if (!empty($include_request_project_ids) && !isset($include_request_project_ids[(int)($pr['id'] ?? 0)])) {
					continue;
				}
				$project_list_filtered[] = $pr;
			}
		} else {
			// แท็บ แผนปฏิบัติการประจำปี:
			// - ผู้ใช้ทั่วไป: แสดงเฉพาะสถานะอนุมัติดำเนินการแล้ว (1)
			// - Plan Admin: แสดงสถานะ 4 เฉพาะเมื่อ "แจ้งผลแล้ว" (บรรจุแผน / บรรจุแผนและแก้ไข)
			if (defined('PLAN_ADMIN') && PLAN_ADMIN) {
				$pm_is_notified_included = in_array($nrRow, ['บรรจุแผน', 'บรรจุแผนและแก้ไข'], true);
				$allowPlan = ($st === '1')
					|| ($st === '4' && $pm_is_notified_included)
					|| ($st === '8' && $nrRow === 'บรรจุแผน')
					|| $__isMidyear;
			} else {
				// ฝั่ง User:
				// - เห็น "อนุมัติ" (1)
				// - เห็น "บรรจุแผน" (4 + notify_result=บรรจุแผน)
				// - เห็น "ตีกลับเพื่อแก้ไขหลังขอดำเนินการ" (8 + notify_result=บรรจุแผน)
				$allowPlan = ($st === '1')
					|| ($st === '4' && $nrRow === 'บรรจุแผน')
					|| ($st === '8' && $nrRow === 'บรรจุแผน')
					|| $__isMidyear;
			}
			if ($allowPlan) {
				if (!empty($include_request_project_ids) && !isset($include_request_project_ids[(int)($pr['id'] ?? 0)])) {
					continue;
				}
				$project_list_filtered[] = $pr;
			}
		}
	}
}

// Plan Admin: กรองตามสถานะที่แสดง (A/B) ไม่เปลี่ยนรหัสใน DB
$pm_ab_filter_fallback_labels = [
	'a0' => 'A0 ร่าง',
	'a1' => 'A1 รอส่งตรวจสอบ',
	'a2' => 'A2 อยู่ระหว่างพิจารณา',
	'a_fix' => 'A รอแก้ไข',
	'a_reject' => 'A ไม่ผ่านการพิจารณา',
	'midyear' => 'ยื่นระหว่างปี',
	'b1' => 'B1 รอยื่นอนุมัติดำเนินการ',
	'b_fix' => 'B รอแก้ไข',
	'b2' => 'B2 อยู่ระหว่างตรวจสอบ',
	'b3' => 'B3 อนุมัติ/อยู่ระหว่างดำเนินการ',
	'b4' => 'B4 อยู่ระหว่างตรวจรายงาน',
	'b4_done' => 'B4 รายงานผลเรียบร้อย',
	'b5' => 'B5 ปิดโครงการ',
	'changing' => 'เปลี่ยนแปลง',
	'cancel_pending' => 'ขอยกเลิก',
	'cancelled' => 'ยกเลิก',
];
$pm_ab_mod_order = [
	'a0' => 10, 'a1' => 20, 'a2' => 30, 'a_fix' => 40, 'a_reject' => 50,
	'midyear' => 60, 'b1' => 70, 'b_fix' => 80, 'b2' => 90, 'b3' => 100,
	'b4' => 110, 'b4_done' => 115, 'b5' => 120, 'changing' => 130, 'cancel_pending' => 140, 'cancelled' => 150,
];
if (defined('PLAN_ADMIN') && PLAN_ADMIN && function_exists('pm_resolve_ab_status')) {
	if (!isset($GLOBALS['pm_list_ab_status_cache']) || !is_array($GLOBALS['pm_list_ab_status_cache'])) {
		$GLOBALS['pm_list_ab_status_cache'] = [];
	}
	$pm_ab_seed_mods = ($project_group === 'plan')
		? ['b1', 'a_fix', 'b_fix', 'b2', 'b3', 'b4', 'b4_done', 'b5', 'midyear', 'changing', 'cancel_pending', 'cancelled']
		: ['a0', 'a1', 'a2', 'a_fix', 'a_reject'];
	foreach ($pm_ab_seed_mods as $_mod) {
		$pm_status_filter_options[$_mod] = $pm_ab_filter_fallback_labels[$_mod] ?? $_mod;
	}
	foreach ($project_list_filtered as $_pr) {
		$_ab = pm_resolve_ab_status($_pr, ['db' => $db_Project]);
		$_pid = (int)($_pr['id'] ?? 0);
		if ($_pid > 0) {
			$GLOBALS['pm_list_ab_status_cache'][$_pid] = $_ab;
		}
		$_mod = trim((string)($_ab['mod'] ?? ''));
		if ($_mod === '' || $_mod === 'unknown') {
			continue;
		}
		$_lbl = trim((string)($_ab['label'] ?? ''));
		$_lbl = trim((string)preg_replace('/\s+\d+\s*\/\s*\d+\s*$/u', '', $_lbl));
		if ($_lbl === '') {
			$_lbl = $pm_ab_filter_fallback_labels[$_mod] ?? $_mod;
		}
		if (!isset($pm_status_filter_options[$_mod]) || mb_strlen($_lbl) < mb_strlen((string)$pm_status_filter_options[$_mod])) {
			$pm_status_filter_options[$_mod] = $_lbl;
		}
	}
	if ($pm_status_filter !== '' && !isset($pm_ab_mod_order[$pm_status_filter])) {
		$pm_status_filter = '';
	}
	if ($pm_status_filter !== '' && !isset($pm_status_filter_options[$pm_status_filter])) {
		$pm_status_filter_options[$pm_status_filter] = $pm_ab_filter_fallback_labels[$pm_status_filter] ?? $pm_status_filter;
	}
	uksort($pm_status_filter_options, function ($a, $b) use ($pm_ab_mod_order) {
		$oa = $pm_ab_mod_order[$a] ?? 999;
		$ob = $pm_ab_mod_order[$b] ?? 999;
		if ($oa === $ob) {
			return strcmp((string)$a, (string)$b);
		}
		return $oa <=> $ob;
	});
	if ($pm_status_filter !== '') {
		$__keep_by_status = [];
		foreach ($project_list_filtered as $_pr) {
			$_pid = (int)($_pr['id'] ?? 0);
			if ($_pid > 0 && isset($GLOBALS['pm_list_ab_status_cache'][$_pid])) {
				$_ab = $GLOBALS['pm_list_ab_status_cache'][$_pid];
			} else {
				$_ab = pm_resolve_ab_status($_pr, ['db' => $db_Project]);
			}
			if (trim((string)($_ab['mod'] ?? '')) === $pm_status_filter) {
				$__keep_by_status[] = $_pr;
			}
		}
		$project_list_filtered = $__keep_by_status;
	}
}

// Fallback: รองรับการเรียงลำดับแบบ server-side (กรณี JS ไม่ทำงาน)
$pm_sort_key = isset($_GET['s']) ? trim((string) $_GET['s']) : '';
$pm_sort_dir = isset($_GET['d']) ? trim((string) $_GET['d']) : 'asc';
$pm_sort_dir = ($pm_sort_dir === 'desc') ? 'desc' : 'asc';
if ($pm_sort_key !== '' && !empty($project_list_filtered)) {
	$pm_sort_allowed = ['code', 'name', 'unit', 'budget', 'status'];
	if (in_array($pm_sort_key, $pm_sort_allowed, true)) {
		$__unit_names_local = isset($unit_names) && is_array($unit_names) ? $unit_names : [];
		usort($project_list_filtered, function ($a, $b) use ($pm_sort_key, $pm_sort_dir, $__unit_names_local) {
			$dirMul = ($pm_sort_dir === 'desc') ? -1 : 1;
			$va = '';
			$vb = '';
			if ($pm_sort_key === 'budget') {
				$va = (float) ($a['budget_total'] ?? 0);
				$vb = (float) ($b['budget_total'] ?? 0);
			} elseif ($pm_sort_key === 'status') {
				$va = (int) ($a['status_project'] ?? 0);
				$vb = (int) ($b['status_project'] ?? 0);
			} elseif ($pm_sort_key === 'code') {
				$va = strtolower((string) ($a['code_pre_project'] ?? ''));
				$vb = strtolower((string) ($b['code_pre_project'] ?? ''));
			} elseif ($pm_sort_key === 'name') {
				$va = strtolower((string) ($a['name_project'] ?? ''));
				$vb = strtolower((string) ($b['name_project'] ?? ''));
			} elseif ($pm_sort_key === 'unit') {
				$ua = (string) ($a['code_unit'] ?? '');
				$ub = (string) ($b['code_unit'] ?? '');
				$va = strtolower((string) ($__unit_names_local[$ua] ?? $ua));
				$vb = strtolower((string) ($__unit_names_local[$ub] ?? $ub));
			}
			if ($va === $vb) return 0;
			return ($va < $vb ? -1 : 1) * $dirMul;
		});
	}
}
// แมปชื่อ AP / ด้าน สำหรับ modal ขอบรรจุ (สรุปตามความสอดคล้อง)
$include_ap_name_by_id = [];
$include_side_name_by_id = [];
if ($is_unit_admin) {
	if (function_exists('getAPList')) {
		$__apList = getAPList($db_KPI);
		if (is_array($__apList)) {
		foreach ($__apList as $__aprow) {
			$__apid = (string)($__aprow['id'] ?? '');
			if ($__apid !== '') {
				$include_ap_name_by_id[$__apid] = (string)($__aprow['name'] ?? '');
			}
		}
		}
	}
	if (function_exists('getSideList')) {
		$__sideList = getSideList($db_KPI);
		if (is_array($__sideList)) {
		foreach ($__sideList as $__sdrow) {
			$__sid = (string)($__sdrow['id'] ?? '');
			if ($__sid !== '') {
				$include_side_name_by_id[$__sid] = (string)($__sdrow['name'] ?? '');
			}
		}
		}
	}
}
} catch (Throwable $e) {
	$GLOBALS['pm_manage_error_shown'] = true;
	if (!isset($project_group) || ($project_group !== 'draft' && $project_group !== 'plan')) {
		$project_group = 'draft';
	}
	if (!isset($include_request_id)) {
		$include_request_id = 0;
	}
	if (!isset($include_request_project_ids) || !is_array($include_request_project_ids)) {
		$include_request_project_ids = [];
	}
	if (!isset($include_resubmit_certifiers_for_js) || !is_array($include_resubmit_certifiers_for_js)) {
		$include_resubmit_certifiers_for_js = [];
	}
	if (!isset($include_resubmit_certifiers_locked)) {
		$include_resubmit_certifiers_locked = false;
	}
	if (!isset($project_list) || !is_array($project_list)) {
		$project_list = [];
	}
	if (!isset($project_list_filtered) || !is_array($project_list_filtered)) {
		$project_list_filtered = is_array($project_list) ? $project_list : [];
	}
	if (!isset($pm_status_filter)) {
		$pm_status_filter = isset($_GET['status_filter']) ? trim((string)$_GET['status_filter']) : '';
	}
	if (!isset($pm_status_filter_options) || !is_array($pm_status_filter_options)) {
		$pm_status_filter_options = [];
	}
	if (!isset($year_list) || !is_array($year_list)) {
		$year_list = [];
	}
	if (!isset($include_ap_name_by_id) || !is_array($include_ap_name_by_id)) {
		$include_ap_name_by_id = [];
	}
	if (!isset($include_side_name_by_id) || !is_array($include_side_name_by_id)) {
		$include_side_name_by_id = [];
	}
	if (!isset($pmKeepIncludeQs)) {
		$pmKeepIncludeQs = ($include_request_id > 0) ? ('&include_request_id=' . (int)$include_request_id . '&project_group=draft') : '';
	}
	echo '<div class="alert alert-danger">ไม่สามารถแสดงรายการโครงการได้: ' . htmlspecialchars($e->getMessage() . ' @ ' . basename($e->getFile()) . ':' . $e->getLine(), ENT_QUOTES, 'UTF-8') . '</div>';
}
?>
