					<?php if (!empty($project_list_filtered)): ?>
						<?php
							$head_name_cache = [];
							$fix_editor_name_cache = [];
							$pm_budget_src_cache = [];
							$pm_rr_rejected_ids = [];
							$__rrPendingIds = [];
							$pm_chg_pending_ids = [];
							$pm_chg_unapplied_ids = [];
							$pm_cancel_maps = ['pending' => [], 'cancelled' => []];
							foreach ($project_list_filtered as $__prRr) {
								$__pidRr = (int)($__prRr['id'] ?? 0);
								$__subRr = trim((string)($__prRr['result_report_submitted_at'] ?? ''));
								$__doneRr = trim((string)($__prRr['result_report_completed_at'] ?? ''));
								if ($__pidRr > 0 && $__subRr !== '' && $__doneRr === '') {
									$__rrPendingIds[] = $__pidRr;
								}
							}
							if (function_exists('pm_load_pending_change_project_ids')) {
								$__chgIds = [];
								foreach ($project_list_filtered as $__prChg) {
									$__pidChg = (int)($__prChg['id'] ?? 0);
									if ($__pidChg > 0) {
										$__chgIds[] = $__pidChg;
									}
								}
								$pm_chg_pending_ids = pm_load_pending_change_project_ids($db_Project, $__chgIds);
								$pm_chg_unapplied_ids = function_exists('pm_load_unapplied_change_project_ids')
									? pm_load_unapplied_change_project_ids($db_Project, $__chgIds)
									: [];
							}
							if (function_exists('pm_load_cancel_status_maps')) {
								$__canIds = [];
								foreach ($project_list_filtered as $__prCan) {
									$__pidCan = (int)($__prCan['id'] ?? 0);
									if ($__pidCan > 0) {
										$__canIds[] = $__pidCan;
									}
								}
								$pm_cancel_maps = pm_load_cancel_status_maps($db_Project, $__canIds);
							}
							if (!empty($__rrPendingIds)) {
								$__rrIn = implode(',', array_map('intval', array_unique($__rrPendingIds)));
								$qRrRej = @mysqli_query(
									$db_Project,
									"SELECT DISTINCT project_id FROM project_result_report_certifier_decision
									 WHERE project_id IN (" . $__rrIn . ") AND decision='rejected'"
								);
								while ($qRrRej && ($__rrj = mysqli_fetch_assoc($qRrRej))) {
									$__ridj = (int)($__rrj['project_id'] ?? 0);
									if ($__ridj > 0) {
										$pm_rr_rejected_ids[$__ridj] = true;
									}
								}
							}
							$getFixEditorName = function($sid) use ($db_person, &$fix_editor_name_cache) {
								$sid = (int)$sid;
								if ($sid <= 0) {
									return '-';
								}
								if (isset($fix_editor_name_cache[$sid])) {
									return $fix_editor_name_cache[$sid];
								}
								$q = @mysqli_query($db_person, "SELECT fname, lname FROM staff WHERE id='" . $sid . "' LIMIT 1");
								$r = $q ? mysqli_fetch_assoc($q) : null;
								$name = trim((string)(($r['fname'] ?? '') . ' ' . ($r['lname'] ?? '')));
								if ($name === '') {
									$name = '-';
								}
								$fix_editor_name_cache[$sid] = $name;
								return $name;
							};
							$getHeadName = function($pid) use ($db_Project, $db_person, &$head_name_cache) {
								$pid = (int)$pid;
								if ($pid <= 0) return '-';
								if (isset($head_name_cache[$pid])) return $head_name_cache[$pid];
								$heads = function_exists('getProjectHeadList') ? getProjectHeadList($db_Project, $pid) : [];
								if (empty($heads) || empty($heads[0]['staff_project'])) {
									$head_name_cache[$pid] = '-';
									return '-';
								}
								$sid = (int)$heads[0]['staff_project'];
								$q = @mysqli_query($db_person, "SELECT fname, lname FROM staff WHERE id='".$sid."' LIMIT 1");
								$r = $q ? mysqli_fetch_assoc($q) : null;
								$name = trim((string)(($r['fname'] ?? '') . ' ' . ($r['lname'] ?? '')));
								if ($name === '') $name = '-';
								$head_name_cache[$pid] = $name;
								return $name;
							};
							$pm_list_budget_labels = [];
							if (function_exists('getAddBudgetSelect')) {
								foreach (getAddBudgetSelect($db_Project) as $__blr) {
									$__lid = (string)($__blr['id'] ?? '');
									$__lname = trim((string)($__blr['name'] ?? ''));
									if ($__lid !== '') {
										$pm_list_budget_labels[$__lid] = $__lname;
									}
									$__lcode = trim((string)($__blr['code'] ?? ''));
									if ($__lcode !== '' && !isset($pm_list_budget_labels[$__lcode])) {
										$pm_list_budget_labels[$__lcode] = $__lname;
									}
								}
							}
						?>
						<?php foreach ($project_list_filtered as $idx => $row):
							$pm_list_row_id = (int)($row['id'] ?? 0);
							$code_unit_row = trim((string)($row['code_unit'] ?? ''));
							$unit_name = '-';
							if ($code_unit_row !== '') {
								if (isset($unit_names[$code_unit_row]) && trim((string)$unit_names[$code_unit_row]) !== '') {
									$unit_name = (string)$unit_names[$code_unit_row];
								} elseif (function_exists('planResolvePreProjectCodeUnit')) {
									$resolved_cu = planResolvePreProjectCodeUnit($db_Project, $code_unit_row);
									if ($resolved_cu !== '' && isset($unit_names[$resolved_cu]) && trim((string)$unit_names[$resolved_cu]) !== '') {
										$unit_name = (string)$unit_names[$resolved_cu];
									}
								}
								if ($unit_name === '-' || $unit_name === $code_unit_row) {
									// fallback เดิม แล้วตัดรหัสออก
									$fallback = isset($unit_names[$code_unit_row]) ? (string)$unit_names[$code_unit_row] : $code_unit_row;
									if (function_exists('planStripUnitCodeFromLabel')) {
										$fallback = planStripUnitCodeFromLabel($fallback);
									}
									$unit_name = $fallback !== '' ? $fallback : '-';
								}
								if (function_exists('planStripUnitCodeFromLabel')) {
									$unit_name = planStripUnitCodeFromLabel($unit_name);
								}
							}
							$budget = isset($row['budget_total']) ? (float)$row['budget_total'] : 0;
							$head_name = $getHeadName($pm_list_row_id);
							$pm_list_cb = (string)($row['code_budget'] ?? '');
							$pm_list_bo = trim((string)($row['budget_other'] ?? ''));
							// fallback: ถ้าไม่ได้เก็บไว้ใน pre_project ให้ดึงจากตาราง project_budget (ล่าสุด)
							if (($pm_list_cb === '' || $pm_list_cb === '0') && $pm_list_row_id > 0) {
								if (!isset($pm_budget_src_cache[$pm_list_row_id])) {
									$pm_budget_src_cache[$pm_list_row_id] = ['cb' => '', 'bo' => ''];
									$qpb = @mysqli_query(
										$db_Project,
										"SELECT code_budget, budget_other
										 FROM project_budget
										 WHERE project_id='" . (int)$pm_list_row_id . "' AND status='1'
										 ORDER BY id DESC
										 LIMIT 1"
									);
									$rpb = $qpb ? mysqli_fetch_assoc($qpb) : null;
									if ($rpb) {
										$pm_budget_src_cache[$pm_list_row_id] = [
											'cb' => trim((string)($rpb['code_budget'] ?? '')),
											'bo' => trim((string)($rpb['budget_other'] ?? '')),
										];
									}
								}
								if ($pm_list_cb === '' || $pm_list_cb === '0') {
									$pm_list_cb = (string)($pm_budget_src_cache[$pm_list_row_id]['cb'] ?? '');
								}
								if ($pm_list_bo === '') {
									$pm_list_bo = (string)($pm_budget_src_cache[$pm_list_row_id]['bo'] ?? '');
								}
							}
							if ($pm_list_cb === '99' && $pm_list_bo !== '') {
								$pm_list_budget_src_lbl = $pm_list_bo;
							} elseif ($pm_list_cb !== '' && isset($pm_list_budget_labels[$pm_list_cb]) && $pm_list_budget_labels[$pm_list_cb] !== '') {
								$pm_list_budget_src_lbl = $pm_list_budget_labels[$pm_list_cb];
							} elseif ($pm_list_cb !== '' && function_exists('getSetBudget')) {
								$__gsb = getSetBudget($db_Project, $pm_list_cb);
								$__gsbn = trim((string)($__gsb['name'] ?? ''));
								$pm_list_budget_src_lbl = $__gsbn !== '' ? $__gsbn : $pm_list_cb;
							} elseif ($pm_list_cb !== '') {
								$pm_list_budget_src_lbl = $pm_list_cb;
							} else {
								$pm_list_budget_src_lbl = '-';
							}
							$pm_list_at_no = 'อว /ผ' . str_pad((string)((($pm_list_row_id % 999) ?: 0) + 1), 3, '0', STR_PAD_LEFT);
							$pm_list_nm = trim((string)($row['name_project'] ?? ''));
							$pm_list_cd = (string)($row['code_pre_project'] ?? '');
							$pm_list_budget_fmt = number_format($budget, 0, '.', ',');
							$pm_list_subject = 'ขออนุมัติดำเนินโครงการ ' . ($pm_list_nm !== '' ? $pm_list_nm : '…') . ' (' . ($pm_list_cd !== '' ? $pm_list_cd : '…') . ')';
							$notify_result_note = trim((string)($row['notify_result_note'] ?? ''));
							$pm_row_user_fix = trim((string)($row['user_fix_note'] ?? ''));
							$pm_plan_admin_confirm_fix = (defined('PLAN_ADMIN') && PLAN_ADMIN)
								&& (string)($row['status_project'] ?? '') === '8'
								&& $pm_row_user_fix !== '';
							$pm_operate_all_approved = false;
							$pm_operate_waiting_plan_row = false;
							if (in_array((string)($row['status_project'] ?? ''), ['1', '8'], true)) {
								if (function_exists('pm_is_operate_final_approved')) {
									$pm_operate_all_approved = pm_is_operate_final_approved(
										$db_Project,
										(int)$pm_list_row_id,
										$row
									);
								}
								if (!$pm_operate_all_approved && function_exists('pm_is_operate_waiting_plan_approver')) {
									$pm_operate_waiting_plan_row = pm_is_operate_waiting_plan_approver(
										$db_Project,
										(int)$pm_list_row_id,
										$row
									);
								}
							}
							$pm_rr_sub_at = trim((string)($row['result_report_submitted_at'] ?? ''));
							$pm_rr_done_at = trim((string)($row['result_report_completed_at'] ?? ''));
							$pm_rr_plan_closed_at = trim((string)($row['result_report_plan_closed_at'] ?? ''));
							$pm_ab = function_exists('pm_resolve_ab_status')
								? pm_resolve_ab_status($row, [
									'db' => $db_Project,
									'user_fix_note' => $pm_row_user_fix,
									'operate_all_approved' => !empty($pm_operate_all_approved),
									'operate_waiting_plan' => !empty($pm_operate_waiting_plan_row),
									'report_submitted_at' => $pm_rr_sub_at,
									'report_completed_at' => $pm_rr_done_at,
									'report_plan_closed_at' => $pm_rr_plan_closed_at,
									'report_rejected' => !empty($pm_rr_rejected_ids[$pm_list_row_id]),
									'cancelled' => !empty($pm_cancel_maps['cancelled'][$pm_list_row_id]),
									'cancel_pending' => !empty($pm_cancel_maps['pending'][$pm_list_row_id]),
									'change_pending' => !empty($pm_chg_pending_ids[$pm_list_row_id]),
									'change_wait_apply' => !empty($pm_chg_unapplied_ids[$pm_list_row_id]),
								])
								: [
									'label' => '-',
									'mod' => 'unknown',
									'icon' => 'fa-minus-circle',
								];
							$status_txt = (string)($pm_ab['label'] ?? '-');
							$status_mod = (string)($pm_ab['mod'] ?? 'unknown');
							$status_icon = (string)($pm_ab['icon'] ?? 'fa-minus-circle');
							$pm_list_show_report_btn = in_array($status_mod, ['b3', 'b4', 'b4_done', 'approved', 'report_pending', 'report_done'], true)
								|| !empty($pm_operate_all_approved)
								|| ($pm_rr_sub_at !== '')
								|| ($pm_rr_done_at !== '');
							$pm_row_status = (string)($row['status_project'] ?? '');
							$pm_row_notify_result = trim((string)($row['notify_result'] ?? ''));
							$is_draft = in_array($pm_row_status, ['0','8'], true);
							$is_queue = in_array((string)($row['status_project'] ?? ''), ['2','3'], true);
							$ir_row_hl = !empty($include_request_project_ids) && isset($include_request_project_ids[(int)($row['id'] ?? 0)]);
							// คำขอตีกลับ: แก้ได้เฉพาะโครงการที่ยังสถานะ 8 (ยังไม่ยืนยันส่งกลับผู้ตรวจสอบ)
							$can_edit_row = $is_draft
								|| ($include_request_id > 0 && $ir_row_hl && $pm_row_status === '8' && empty($include_resubmit_certifiers_locked))
								|| pm_is_editable_in_plan_mode($pm_row_status, $pm_row_notify_result, $pm_row_user_fix)
								|| (function_exists('pm_is_annual_plan_pre_operate') && pm_is_annual_plan_pre_operate($pm_row_status, $pm_row_notify_result));
							if (!(defined('PLAN_ADMIN') && PLAN_ADMIN)
								&& $pm_row_status === '8'
								&& $pm_row_notify_result === 'บรรจุแผน'
								&& trim((string)($row['operate_submitter_reply_note'] ?? '')) !== '') {
								$can_edit_row = false;
							}
							$pm_row_fix_awaiting = function_exists('pm_is_plan_fix_awaiting_review')
								&& pm_is_plan_fix_awaiting_review($pm_row_status, $pm_row_notify_result, $pm_row_user_fix);
							if ($pm_row_fix_awaiting && !(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
								$can_edit_row = false;
								$is_draft = false;
								$is_queue = true;
							}
							// หลังแผนกดนำเข้าที่ประชุม (status=4) — User ดูอย่างเดียว ยกเว้นบรรจุแผนแล้วยังไม่ขอดำเนินการ
							if ($pm_row_status === '4' && !(defined('PLAN_ADMIN') && PLAN_ADMIN)) {
								$can_edit_row = function_exists('pm_is_annual_plan_pre_operate')
									&& pm_is_annual_plan_pre_operate($pm_row_status, $pm_row_notify_result);
							}
							if (defined('PLAN_ADMIN') && PLAN_ADMIN) {
								$can_edit_row = true; // Plan(Admin): แก้ไขได้ทุกสถานะ
								if (function_exists('pm_is_include_meeting_view_only')
									&& pm_is_include_meeting_view_only($pm_row_status, $pm_row_notify_result)) {
									$can_edit_row = false; // นำเข้าที่ประชุมแล้ว ยังไม่แจ้งผล → ดูอย่างเดียว
								}
								if ($pm_plan_admin_confirm_fix) {
									$can_edit_row = false; // ผู้ยื่นส่งกลับแล้ว → เปิดดูรายละเอียด (ไม่ใช่ปุ่มยืนยัน)
								}
							}
							if (!empty($pm_cancel_maps['cancelled'][$pm_list_row_id])) {
								$can_edit_row = false;
								$pm_list_show_report_btn = false;
							}
							if ($status_mod === 'b5' || $pm_rr_plan_closed_at !== '') {
								$can_edit_row = false;
								$pm_list_show_report_btn = false;
							}
							$pm_row_tags = function_exists('pm_parse_admin_tags')
								? pm_parse_admin_tags($row['admin_tags'] ?? '')
								: [];
							$pm_row_tags_search = function_exists('pm_admin_tags_search_text')
								? pm_admin_tags_search_text($row['admin_tags'] ?? '')
								: implode(' ', $pm_row_tags);
							$search_text = strtolower(trim(
								(string)($row['code_pre_project'] ?? '') . ' ' .
								(string)($row['name_project'] ?? '') . ' ' .
								(string)$unit_name . ' ' .
								(string)$pm_row_tags_search
							));
						?>
							<tr class="<?= trim(($is_draft ? 'pm-row-draft' : ($is_queue ? 'pm-row-queue' : '')) . ($ir_row_hl ? ' pm-row-include-request' : '')) ?>"
								data-project-row="1"
								data-search="<?= htmlspecialchars($search_text, ENT_QUOTES, 'UTF-8') ?>"
								data-project-id="<?= (int)($row['id'] ?? 0) ?>"
								data-code="<?= htmlspecialchars((string)($row['code_pre_project'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"
								data-name="<?= htmlspecialchars((string)($row['name_project'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"
								data-unit="<?= htmlspecialchars((string)$unit_name, ENT_QUOTES, 'UTF-8') ?>"
								data-budget="<?= htmlspecialchars(number_format((float)$budget, 2, '.', ''), ENT_QUOTES, 'UTF-8') ?>"
								data-status="<?= htmlspecialchars((string)($row['status_project'] ?? ''), ENT_QUOTES, 'UTF-8') ?>">
								<td class="text-center pm-col-no"><?= $idx + 1 ?></td>
								<td><?= htmlspecialchars($row['code_pre_project'] ?? '') ?></td>
								<td>
									<div class="pm-project-name"><?= htmlspecialchars($row['name_project'] ?? '') ?></div>
									<?php if ($pm_plan_admin_confirm_fix): ?>
										<small class="pm-project-head"><i class="fa fa-user-edit mr-1"></i><?= htmlspecialchars('แก้ไขโดย : ' . $getFixEditorName((int)($row['user_fix_note_staff_id'] ?? 0)), ENT_QUOTES, 'UTF-8') ?></small>
									<?php else: ?>
										<small class="pm-project-head"><i class="fa fa-user-tie mr-1"></i><?= htmlspecialchars($head_name, ENT_QUOTES, 'UTF-8') ?></small>
									<?php endif; ?>
									<?php if (defined('PLAN_ADMIN') && PLAN_ADMIN && !empty($pm_row_tags)): ?>
										<div class="pm-list-tags mt-1">
											<?php foreach ($pm_row_tags as $__ltag): ?>
												<span class="pm-list-tag-chip"><?= htmlspecialchars($__ltag, ENT_QUOTES, 'UTF-8') ?></span>
											<?php endforeach; ?>
										</div>
									<?php endif; ?>
								</td>
								<td><?= htmlspecialchars($unit_name) ?></td>
								<td class="text-right"><?= number_format($budget, 2) ?></td>
								<td class="text-center">
									<?= function_exists('pm_render_ab_badge')
										? pm_render_ab_badge(isset($pm_ab) && is_array($pm_ab) ? $pm_ab : [
											'label' => $status_txt,
											'mod' => $status_mod,
										])
										: '<span class="pm-status-badge pm-status-'.htmlspecialchars($status_mod, ENT_QUOTES, 'UTF-8').'"><i class="fa '.htmlspecialchars($status_icon, ENT_QUOTES, 'UTF-8').'"></i> '.htmlspecialchars($status_txt, ENT_QUOTES, 'UTF-8').'</span>'
									?>
								</td>
								<td class="text-left">
									<div class="pm-action-wrap">
										<?php
											$pm_action_btn_cls = $can_edit_row ? 'btn-warning' : 'btn-info';
											$pm_action_icon = $can_edit_row ? 'fa-edit' : 'fa-file-alt';
											$pm_action_label = $can_edit_row ? 'แก้ไข' : 'รายละเอียด';
											$pm_action_title = '';
											if (!$can_edit_row) {
												if ($pm_plan_admin_confirm_fix) {
													$pm_action_title = 'เปิดหน้ารายละเอียดโครงการเพื่อตรวจสอบการแก้ไข';
												} elseif ($pm_row_status === '1') {
													$pm_action_title = 'รอผู้ตรวจสอบพิจารณา แก้ไขไม่ได้จนกว่าจะตีกลับให้แก้ไข';
												} else {
													$pm_action_title = 'ดูรายละเอียด (ไม่สามารถแก้ไข)';
												}
											} elseif ($project_group === 'plan') {
												$pm_action_title = 'เปิดเพื่อแก้ไขได้บางหัวข้อ (ตามสิทธิ์/สถานะโครงการ)';
												$pm_action_icon = 'fa-edit';
												$pm_action_btn_cls = 'btn-warning';
											}
										?>
										<?php
											$pm_list_page = isset($_GET['p']) ? (int)$_GET['p'] : 1;
											if ($pm_list_page <= 0) $pm_list_page = 1;
											$pm_back_list = '?page=project_manage&years_select=' . rawurlencode((string)$years_select)
												. '&project_group=' . rawurlencode((string)$project_group)
												. ($include_request_id > 0 ? ('&include_request_id=' . (int)$include_request_id) : '')
												. '&p=' . (int)$pm_list_page;
										?>
										<?php if (!empty($pm_list_show_report_btn)): ?>
											<a href="?page=project_manage&op=add_project&project_id=<?= (int)($row['id'] ?? 0) ?>&years_select=<?= htmlspecialchars($years_select, ENT_QUOTES, 'UTF-8') ?><?= htmlspecialchars($pmKeepIncludeQs, ENT_QUOTES, 'UTF-8') ?>&pm_scroll=report&back_to=<?= rawurlencode($pm_back_list) ?>"
												class="btn btn-success btn-xs font-weight-bold"
												title="ดำเนินการ / รายงานผลตัวชี้วัดเป้าหมายโครงการ">
												<i class="fa fa-chart-bar mr-1"></i> ดำเนินการ/รายงานผล
											</a>
										<?php else: ?>
										<a href="?page=project_manage&op=add_project&project_id=<?= (int)($row['id'] ?? 0) ?>&years_select=<?= htmlspecialchars($years_select, ENT_QUOTES, 'UTF-8') ?><?= htmlspecialchars($pmKeepIncludeQs, ENT_QUOTES, 'UTF-8') ?>&back_to=<?= rawurlencode($pm_back_list) ?>"
											class="btn <?= $pm_action_btn_cls ?> btn-xs<?= !$can_edit_row ? ' font-weight-bold' : '' ?>"
											<?= $pm_action_title !== '' ? ' title="'.htmlspecialchars($pm_action_title, ENT_QUOTES, 'UTF-8').'"' : '' ?>>
											<i class="fa <?= htmlspecialchars($pm_action_icon, ENT_QUOTES, 'UTF-8') ?><?= !$can_edit_row ? ' mr-1' : '' ?>"></i> <?= htmlspecialchars($pm_action_label, ENT_QUOTES, 'UTF-8') ?>
										</a>
										<?php endif; ?>
										<?php if ($pm_row_status === '0' && !(defined('PLAN_ADMIN') && PLAN_ADMIN)): ?>
											<button type="button" class="btn btn-outline-danger btn-xs" data-action="delete-project-draft" data-id="<?= (int)($row['id'] ?? 0) ?>">
												<i class="fa fa-trash"></i> ลบ
											</button>
										<?php endif ?>
										<?php
											$pm_row_notify_trim = trim((string)($row['notify_result'] ?? ''));
											$pm_can_notify_plan_result = ((string)($row['status_project'] ?? '') === '4')
												&& (defined('PLAN_ADMIN') && PLAN_ADMIN)
												// แสดงปุ่มเมื่ออยู่สถานะ “นำเข้าที่ประชุม” (ยังไม่ถูกยืนยันเป็นบรรจุแผน)
												&& $pm_row_notify_trim !== 'บรรจุแผน';
										?>
										<?php if ($pm_can_notify_plan_result): ?>
											<button type="button"
												class="btn btn-info btn-xs"
												data-action="open-notify-result"
												data-id="<?= (int)($row['id'] ?? 0) ?>"
												data-notify-name="<?= htmlspecialchars($pm_list_nm, ENT_QUOTES, 'UTF-8') ?>"
												data-notify-unit="<?= htmlspecialchars($unit_name, ENT_QUOTES, 'UTF-8') ?>"
												data-notify-budget-code="<?= htmlspecialchars((string)$pm_list_cb, ENT_QUOTES, 'UTF-8') ?>"
												data-notify-budget-label="<?= htmlspecialchars((string)$pm_list_budget_src_lbl, ENT_QUOTES, 'UTF-8') ?>"
												data-notify-budget-other="<?= htmlspecialchars((string)$pm_list_bo, ENT_QUOTES, 'UTF-8') ?>"
												data-notify-budget-total="<?= htmlspecialchars((string)$budget, ENT_QUOTES, 'UTF-8') ?>">
												<i class="fa fa-bullhorn"></i> แจ้งผล
											</button>
										<?php endif ?>
										<?php if ((string)($row['status_project'] ?? '') === '4' && trim((string)($row['notify_result'] ?? '')) === 'บรรจุแผน'): ?>
											<button type="button"
												class="btn btn-success btn-xs font-weight-bold"
												data-action="request-operate-project"
												data-id="<?= (int)($row['id'] ?? 0) ?>"
												data-memo-unit="<?= htmlspecialchars($unit_name, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-code="<?= htmlspecialchars($pm_list_cd, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-name="<?= htmlspecialchars($pm_list_nm, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-budget="<?= htmlspecialchars($pm_list_budget_fmt, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-budget-src="<?= htmlspecialchars($pm_list_budget_src_lbl, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-at="<?= htmlspecialchars($pm_list_at_no, ENT_QUOTES, 'UTF-8') ?>"
												data-memo-subject="<?= htmlspecialchars($pm_list_subject, ENT_QUOTES, 'UTF-8') ?>"
												title="ส่งคำขออนุมัติดำเนินโครงการ">
												<i class="fa fa-play mr-1"></i> ขอดำเนินการ
											</button>
										<?php endif ?>
									</div>
								</td>
							</tr>
						<?php endforeach ?>
					<?php else: ?>
						<tr id="project-empty-row"><td colspan="7" class="text-center text-secondary py-4"><?= $project_group === 'plan' ? 'ไม่พบโครงการที่นำเข้าที่ประชุมแล้ว' : 'ไม่พบโครงการที่ยังไม่ได้รับการอนุมัติ' ?></td></tr>
					<?php endif ?>
				</tbody>
			</table>
		</div>
		<div class="d-flex justify-content-between align-items-center mt-3">
			<div class="text-muted small" id="projectListSummary">-</div>
			<div class="d-flex align-items-center gap-1 pm-manage-pager" id="projectListPager"></div>
	</div>
</div>
