<?php
	$pm_notify_budget_opts = [];
	$pm_notify_budget_years = [];
	$pm_notify_year_target = trim((string)$years_select);
	$pm_notify_year_key = preg_replace('/\D+/', '', $pm_notify_year_target);
	if ($pm_notify_year_key !== '') {
		$pm_notify_year_key = substr($pm_notify_year_key, -2);
	}
	$pm_year_match = static function (string $yearVal, string $yearKey): bool {
		if ($yearKey === '') {
			return true;
		}
		$digits = preg_replace('/\D+/', '', $yearVal);
		if ($digits === '') {
			return false;
		}
		return substr($digits, -2) === $yearKey;
	};
	if (function_exists('getAddBudgetSelect')) {
		foreach (getAddBudgetSelect($db_Project) as $__bopt) {
			if (!is_array($__bopt)) {
				continue;
			}
			$__id = trim((string)($__bopt['id'] ?? ($__bopt['code'] ?? '')));
			if ($__id === '') {
				continue;
			}
			$__name = trim((string)($__bopt['name'] ?? ''));
			$__year = trim((string)($__bopt['year'] ?? ''));
			$__yearRaw = trim((string)($__bopt['year_raw'] ?? ''));
			$__amt = (float)($__bopt['amount'] ?? 0);
			if ($pm_notify_year_key !== '' && !$pm_year_match($__year, $pm_notify_year_key) && !$pm_year_match($__yearRaw, $pm_notify_year_key)) {
				continue;
			}
			$pm_notify_budget_opts[] = [
				'id' => $__id,
				'code' => trim((string)($__bopt['code'] ?? $__id)),
				'name' => $__name !== '' ? $__name : $__id,
				'year' => $__year !== '' ? $__year : $pm_notify_year_target,
				'amount' => $__amt,
			];
			if ($__year !== '') {
				$pm_notify_budget_years[$__year] = $__year;
			}
		}
	}
	krsort($pm_notify_budget_years, SORT_STRING);
	$pm_notify_budget_opts[] = [
		'id' => '99',
		'code' => '99',
		'name' => 'อื่น ๆ (ระบุเอง)',
		'year' => $pm_notify_year_target,
		'amount' => 0,
	];
?>
