<script>
(function($){
	if (window.pmRoMemoUiBound) return;
	window.pmRoMemoUiBound = true;
	var pmRoCertStaffOptions = <?= (json_encode($request_operate_staff_options ?? [], JSON_UNESCAPED_UNICODE) ?: '[]') ?>;
	if (!Array.isArray(pmRoCertStaffOptions)) pmRoCertStaffOptions = [];
	var $modalRo = $('#modalRequestOperateMemo');
	if (!$modalRo.length) return;
	try { $modalRo.appendTo(document.body); } catch (errAppendRo) {}
	function pmRoShowAlert(icon, title, text) {
		if (typeof Swal !== 'undefined') Swal.fire({ icon: icon || 'error', title: title || 'ไม่สำเร็จ', text: text || '' });
		else alert((title ? title + '\n' : '') + (text || ''));
	}
	function pmRoShowModal() {
		if (typeof $.fn.modal === 'function') {
			$modalRo.modal({ backdrop: 'static', keyboard: true, show: true });
			return true;
		}
		$modalRo.addClass('show').css('display', 'block').attr('aria-hidden', 'false').attr('aria-modal', 'true');
		if (!$('.modal-backdrop.pm-ro-memo-backdrop').length) {
			$('<div class="modal-backdrop fade show pm-ro-memo-backdrop"></div>').appendTo(document.body);
		}
		$('body').addClass('modal-open');
		return true;
	}
	function pmRoHideModal() {
		var $modals = $('#modalRequestOperateMemo');
		$modals.each(function(){
			var el = this;
			try { $(el).modal('hide'); } catch (_e0) {}
			try {
				if (window.bootstrap && window.bootstrap.Modal) {
					var ins = window.bootstrap.Modal.getInstance(el);
					if (ins) ins.hide();
				}
			} catch (_e1) {}
			try {
				el.classList.remove('show', 'in');
				el.style.display = 'none';
				el.setAttribute('aria-hidden', 'true');
				el.removeAttribute('aria-modal');
			} catch (_e2) {}
		});
		try {
			if (!document.querySelector('.modal.show, .modal.in')) {
				document.body.classList.remove('modal-open');
				document.body.style.removeProperty('padding-right');
				document.querySelectorAll('.modal-backdrop').forEach(function(b){
					try { b.parentNode && b.parentNode.removeChild(b); } catch (_e3) {}
				});
			} else {
				$('.modal-backdrop.pm-ro-memo-backdrop').remove();
			}
		} catch (_e4) {}
	}
	function pmRoInitCertSelect($sel) {
		if (!$sel || !$sel.length || typeof $.fn.select2 !== 'function') return;
		try { if ($sel.hasClass('select2-hidden-accessible')) $sel.select2('destroy'); } catch (e0) {}
		$sel.select2({
			placeholder: '- เลือก -',
			allowClear: true,
			width: '100%',
			dropdownParent: $modalRo.length ? $modalRo : $(document.body)
		});
		$sel.off('change.pmCertPos').on('change.pmCertPos', function(){
			var $s = $(this);
			var pos = String($s.find('option:selected').attr('data-position') || '');
			$s.closest('.pm-ro-cert-row').find('input.pm-ro-cert-position').val(pos);
		});
	}
	function pmRoRenumberCertRows() {
		var $wrap = $('#pmRoCertifiersRows');
		if (!$wrap.length) return;
		$wrap.find('.pm-ro-cert-row').each(function(i){
			$(this).find('.pm-ro-cert-lbl-idx').text('(' + (i + 1) + ')');
		});
	}
	function pmRoSyncCertRemoveVisibility() {
		var $wrap = $('#pmRoCertifiersRows');
		if (!$wrap.length) return;
		var n = $wrap.find('.pm-ro-cert-row').length;
		$wrap.find('.pm-ro-cert-remove').css('visibility', n > 1 ? 'visible' : 'hidden');
	}
	function pmRoAddCertRow() {
		var $wrap = $('#pmRoCertifiersRows');
		if (!$wrap.length) return;
		var n = $wrap.find('.pm-ro-cert-row').length + 1;
		var remBtn = '<button type="button" class="btn btn-sm btn-link text-danger p-0 pm-ro-cert-remove" title="ลบแถว"><i class="fa fa-times"></i></button>';
		var $row = $(
			'<div class="pm-ro-cert-row">' +
				'<div class="pm-ro-cert-side">' + remBtn + '</div>' +
				'<div class="pm-ro-cert-fields flex-grow-1">' +
					'<div class="row mx-0">' +
						'<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2">' +
							'<label class="d-block pm-ro-cert-lbl">ผู้รับรองโครงการ <span class="text-danger">*</span> <span class="pm-ro-cert-lbl-idx text-muted font-weight-bold">(' + n + ')</span></label>' +
							'<select class="form-control pm-ro-cert-select"></select>' +
							'<small class="text-muted d-block mt-1" style="font-size:.78rem;">พิมพ์ค้นหาได้</small>' +
						'</div>' +
						'<div class="col-md-6 col-12 pl-md-2">' +
							'<label class="d-block pm-ro-cert-lbl">ตำแหน่ง <span class="text-danger">*</span></label>' +
							'<input type="text" class="form-control pm-ro-cert-position" placeholder="ตำแหน่ง* (กรอก)" autocomplete="off">' +
						'</div>' +
					'</div>' +
				'</div>' +
			'</div>'
		);
		$wrap.append($row);
		var $sel = $row.find('select');
		$sel.append(new Option('- เลือก -', '', false, false));
		(pmRoCertStaffOptions || []).forEach(function(o){
			if (!o) return;
			var opt = new Option(String(o.text || ('Staff #' + o.id)), String(o.id || ''), false, false);
			if (o.position) $(opt).attr('data-position', String(o.position));
			$sel.append(opt);
		});
		pmRoInitCertSelect($sel);
		pmRoRenumberCertRows();
		pmRoSyncCertRemoveVisibility();
	}
	function pmRoResetCertRows() {
		var $wrap = $('#pmRoCertifiersRows');
		if (!$wrap.length) return;
		$wrap.find('.pm-ro-cert-select').each(function(){
			try { if ($(this).hasClass('select2-hidden-accessible')) $(this).select2('destroy'); } catch (e1) {}
		});
		$wrap.empty();
		pmRoAddCertRow();
		pmRoSyncCertRemoveVisibility();
	}
	function pmRoCollectCertPayload() {
		var $wrap = $('#pmRoCertifiersRows');
		var out = [];
		var err = '';
		if (!$wrap.length) return { ok: false, err: 'ไม่พบแบบฟอร์มผู้รับรอง', rows: [] };
		$wrap.find('.pm-ro-cert-row').each(function(){
			var $r = $(this);
			var sid = String($r.find('select').val() || '').trim();
			var pos = String($r.find('input.pm-ro-cert-position').val() || '').trim();
			if (sid === '' && pos === '') return;
			if (sid === '' || pos === '') {
				err = 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับที่ระบุ';
				return false;
			}
			out.push({ staff_id: parseInt(sid, 10), position: pos });
		});
		if (err === '' && out.length === 0) err = 'กรุณาระบุผู้รับรองโครงการอย่างน้อย 1 คน';
		return { ok: err === '' && out.length > 0, err: err, rows: out };
	}
	function pmRoMemoFillFromBtn($btn) {
		var unit = $btn.attr('data-memo-unit') || '-';
		$('#pmRoMemoProjectId').val($btn.attr('data-id') || '0');
		$('#pmRoMemoTblUnit').text((unit || '').trim() || '-');
		var code = $btn.attr('data-memo-code') || '-';
		var name = $btn.attr('data-memo-name') || '-';
		$('#pmRoMemoTblCode').text(code);
		$('#pmRoMemoTblName').text(name);
		$('#pmRoMemoTblCode2').text(code);
		$('#pmRoMemoTblName2').text(name);
		$('#pmRoMemoTblBudget').text($btn.attr('data-memo-budget') || '0');
		$('#pmRoMemoTblBudgetSrc').text($btn.attr('data-memo-budget-src') || '-');
		pmRoResetCertRows();
	}
	$(document).on('click', '#btnPmRoCertAdd', function(){ pmRoAddCertRow(); });
	$(document).on('click', '.pm-ro-cert-remove', function(){
		var $wrap = $('#pmRoCertifiersRows');
		if ($wrap.find('.pm-ro-cert-row').length <= 1) return;
		var $row = $(this).closest('.pm-ro-cert-row');
		try { $row.find('select').select2('destroy'); } catch (e2) {}
		$row.remove();
		pmRoRenumberCertRows();
		pmRoSyncCertRemoveVisibility();
	});
	$(document).on('click', '#modalRequestOperateMemo .pm-ro-memo-close, #modalRequestOperateMemo [data-dismiss="modal"], #modalRequestOperateMemo [data-bs-dismiss="modal"]', function(e){
		if ($(this).is('#pmRoMemoBtnConfirm')) return;
		e.preventDefault();
		e.stopPropagation();
		pmRoHideModal();
	});
	$(document).on('keydown.pmRoMemoClose', function(e){
		if (e.key !== 'Escape' && e.keyCode !== 27) return;
		if (!$('#modalRequestOperateMemo').hasClass('show')) return;
		pmRoHideModal();
	});
			$(document).on('click', '[data-action="request-operate-project"]', function(e){
			e.preventDefault();
			e.stopPropagation();
			var $b = $(this);
			if (window.PM_IS_MIDYEAR && String($('#section2-midyear_reason').val() || $('#pmMidyearReason').val() || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim() === '') {
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'warning', title:'กรุณากรอกเหตุผลการขอเพิ่มโครงการระหว่างปี' });
				else alert('กรุณากรอกเหตุผลการขอเพิ่มโครงการระหว่างปี');
				try {
					var $mid = $('#section2-midyear_reason').closest('.pm-section2-item');
					if ($mid.length) {
						$('html, body').animate({ scrollTop: Math.max(0, $mid.offset().top - 90) }, 280);
						$mid.find('.btn-section2-edit').trigger('click');
					}
				} catch(eF){}
				return;
			}
		var pid = parseInt($b.attr('data-id') || '0', 10);
		if (!pid) {
			pmRoShowAlert('warning', 'ไม่พบโครงการ', 'ไม่สามารถเปิดแบบฟอร์มขออนุมัติดำเนินโครงการได้');
			return;
		}
		try {
			pmRoMemoFillFromBtn($b);
			pmRoShowModal();
		} catch (errOpen) {
			pmRoShowAlert('error', 'เปิดแบบฟอร์มไม่สำเร็จ', (errOpen && errOpen.message) ? String(errOpen.message) : 'เกิดข้อผิดพลาดในหน้าเว็บ');
		}
	});
	$(document).on('click', '#pmRoMemoBtnConfirm', function(){
		var id = parseInt($('#pmRoMemoProjectId').val() || '0', 10);
		if (!id) {
			pmRoShowAlert('warning', 'ไม่พบโครงการ', 'กรุณาปิดแล้วเปิดแบบฟอร์มใหม่');
			return;
		}
		var certPack = pmRoCollectCertPayload();
		if (!certPack.ok) {
			pmRoShowAlert('warning', 'กรุณากรอกข้อมูล', certPack.err || 'ข้อมูลไม่ครบ');
			return;
		}
		var $btn = $(this).prop('disabled', true);
		$.ajax({
			url: '?page=project_manage&op=request_operate_project_ajax',
			type: 'POST',
			dataType: 'json',
			data: { project_id: id, certifiers_json: JSON.stringify(certPack.rows) }
		}).done(function(res){
			if (res && Number(res.ok) === 1) {
				try { pmRoHideModal(); } catch (err) {}
				if (typeof Swal !== 'undefined') {
					Swal.fire({ icon:'success', title:'ส่งคำขออนุมัติดำเนินโครงการแล้ว', timer:1100, showConfirmButton:false })
						.then(function(){ window.location.reload(); });
				} else {
					window.location.reload();
				}
				return;
			}
			var msg = (res && res.msg) ? res.msg : 'ไม่สามารถขออนุมัติดำเนินโครงการได้';
			pmRoShowAlert('error', 'ไม่สำเร็จ', msg);
		}).fail(function(xhr){
			var dbg = '';
			try {
				var raw = String((xhr && xhr.responseText) || '').trim();
				if (raw) dbg = ' (ตอบกลับ: ' + raw.substring(0, 180) + ')';
			} catch (_e) {}
			pmRoShowAlert('error', 'ไม่สำเร็จ', 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้' + dbg);
		}).always(function(){ $btn.prop('disabled', false); });
	});
})(jQuery);
</script>
<script>
(function($){
	if (window.pmNotifyResultBound) return;
	window.pmNotifyResultBound = true;

	var pmNotifyBudgetOptions = <?= json_encode($pm_notify_budget_opts, JSON_UNESCAPED_UNICODE) ?: '[]' ?>;
	if (!Array.isArray(pmNotifyBudgetOptions)) pmNotifyBudgetOptions = [];
	var notifyBudgetPage = 1;
	var notifyBudgetPerPage = 10;

	function fmtMoney(n){
		var x = Number(n || 0);
		if (!Number.isFinite(x)) x = 0;
		return x.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
	}
	function findNotifyBudgetOpt(code){
		var c = String(code || '').trim();
		if (!c) return null;
		for (var i = 0; i < pmNotifyBudgetOptions.length; i++) {
			var it = pmNotifyBudgetOptions[i] || {};
			if (String(it.id || '') === c || String(it.code || '') === c || String(it.budget_manage_id || '') === c) {
				return it;
			}
		}
		return null;
	}
	function renderNotifyBudgetSelected(code, override){
		var $box = $('#notifyResultBudgetSelected');
		var $main = $box.find('.nr-budget-selected-main');
		var c = String(code || '').trim();
		$('#notifyResultBudgetCode').val(c);
		if (!c) {
			$box.addClass('is-empty');
			$main.html('ยังไม่ได้เลือกแหล่งงบประมาณ');
			return;
		}
		var opt = findNotifyBudgetOpt(c) || {};
		if (override && typeof override === 'object') {
			if (override.code != null && String(override.code).trim() !== '') opt.code = String(override.code).trim();
			if (override.name != null && String(override.name).trim() !== '') opt.name = String(override.name).trim();
			if (override.amount != null && Number(override.amount) > 0) opt.amount = Number(override.amount);
			if (!opt.id) opt.id = c;
		}
		var codeShow = String(opt.code || opt.id || c).trim();
		var nameShow = String(opt.name || '').trim();
		if (!nameShow || nameShow === codeShow || /^รหัสแหล่งงบ\s*/.test(nameShow)) {
			// ถ้าไม่มีชื่อที่ใช้ได้ ลองหาจากรายการอีกครั้งด้วย code
			var byCode = findNotifyBudgetOpt(codeShow);
			if (byCode && String(byCode.name || '').trim() !== '') {
				nameShow = String(byCode.name).trim();
				if (!opt.amount && Number(byCode.amount || 0) > 0) opt.amount = Number(byCode.amount);
			}
		}
		$box.removeClass('is-empty');
		if (nameShow && nameShow !== codeShow) {
			var html = '<span class="nr-budget-code">' + $('<div/>').text(codeShow).html() + '</span>'
				+ '<div class="nr-budget-name" title="' + $('<div/>').text(nameShow).html() + '">' + $('<div/>').text(nameShow).html() + '</div>';
			if (String(opt.id || c) !== '99' && Number(opt.amount || 0) > 0) {
				html += '<div class="nr-budget-amt-chip">จำนวนเงินในระบบ: ' + fmtMoney(opt.amount) + ' บาท</div>';
			}
			$main.html(html);
		} else {
			$main.html('<span class="nr-budget-code">' + $('<div/>').text(codeShow).html() + '</span>'
				+ '<div class="nr-budget-name">' + $('<div/>').text(nameShow || codeShow).html() + '</div>');
		}
	}
	function yearKey(y){
		var d = String(y || '').replace(/\D+/g, '');
		if (!d) return '';
		return d.slice(-2);
	}
	function getFilteredNotifyBudgets(){
		var q = String($('#notifyResultBudgetSearch').val() || '').toLowerCase().trim();
		var yrKey = yearKey($('#notifyResultBudgetYear').val() || $('#notifyResultDefaultYear').val() || '');
		var out = [];
		for (var i = 0; i < pmNotifyBudgetOptions.length; i++) {
			var it = pmNotifyBudgetOptions[i];
			var id = String(it.id || '');
			var year = String(it.year || '');
			if (id === '99') {
				if (!q || ('อื่น ๆ ระบุเอง 99 อื่นๆ').indexOf(q) !== -1 || String(it.name || '').toLowerCase().indexOf(q) !== -1) {
					out.push(it);
				}
				continue;
			}
			if (yrKey) {
				var itKey = yearKey(year);
				if (itKey && itKey !== yrKey) continue;
			}
			var hay = (String(it.code || '') + ' ' + String(it.name || '') + ' ' + year).toLowerCase();
			if (q && hay.indexOf(q) === -1) continue;
			out.push(it);
		}
		return out;
	}
	function renderNotifyBudgetPager(totalPages){
		var $pager = $('#notifyResultBudgetPickPager');
		$pager.empty();
		if (totalPages <= 1) return;
		function addBtn(label, page, disabled, active){
			var $b = $('<button type="button" class="btn btn-sm"></button>')
				.addClass(active ? 'btn-primary active' : 'btn-outline-secondary')
				.text(label)
				.prop('disabled', !!disabled);
			$b.on('click', function(){
				if (disabled || page === notifyBudgetPage) return;
				notifyBudgetPage = page;
				renderNotifyBudgetPickList(false);
			});
			$pager.append($b);
		}
		addBtn('‹', Math.max(1, notifyBudgetPage - 1), notifyBudgetPage <= 1, false);
		var start = Math.max(1, notifyBudgetPage - 2);
		var end = Math.min(totalPages, start + 4);
		start = Math.max(1, end - 4);
		for (var p = start; p <= end; p++) addBtn(String(p), p, false, p === notifyBudgetPage);
		addBtn('›', Math.min(totalPages, notifyBudgetPage + 1), notifyBudgetPage >= totalPages, false);
	}
	function renderNotifyBudgetPickList(resetPage){
		if (resetPage !== false) notifyBudgetPage = 1;
		var matched = getFilteredNotifyBudgets();
		var total = matched.length;
		var totalPages = Math.max(1, Math.ceil(total / notifyBudgetPerPage));
		if (notifyBudgetPage > totalPages) notifyBudgetPage = totalPages;
		var startIdx = (notifyBudgetPage - 1) * notifyBudgetPerPage;
		var endIdx = Math.min(startIdx + notifyBudgetPerPage, total);
		var selected = String($('#notifyResultBudgetCode').val() || '');
		var $body = $('#notifyResultBudgetPickBody').empty();
		if (!total) {
			$body.append('<tr><td colspan="3" class="text-center text-muted py-3 font-weight-bold">ไม่พบรายการ</td></tr>');
		} else {
			for (var i = startIdx; i < endIdx; i++) {
				var it = matched[i];
				var id = String(it.id || '');
				var $tr = $('<tr></tr>').attr('data-budget-id', id);
				if (id === selected) $tr.addClass('is-active');
				var amtHtml = (id === '99') ? '-' : fmtMoney(it.amount || 0);
				$tr.append('<td><span class="nr-budget-code">' + $('<div/>').text(String(it.code || id)).html() + '</span></td>');
				$tr.append('<td><div class="nr-budget-pick-name" title="' + $('<div/>').text(String(it.name || '')).html() + '">' + $('<div/>').text(String(it.name || '')).html() + '</div></td>');
				$tr.append('<td class="nr-budget-pick-money">' + amtHtml + '</td>');
				$body.append($tr);
			}
		}
		var summary = total === 0
			? 'ไม่พบรายการ'
			: ('แสดง ' + (startIdx + 1) + '-' + endIdx + ' จาก ' + total + ' รายการ');
		$('#notifyResultBudgetPickSummary').text(summary);
		renderNotifyBudgetPager(totalPages);
	}
	function openNotifyBudgetPicker(){
		var $panel = $('#notifyResultBudgetPickPanel');
		var defYear = String($('#notifyResultDefaultYear').val() || '').trim();
		$('#notifyResultBudgetYear').val(defYear);
		$panel.removeClass('d-none');
		renderNotifyBudgetPickList(true);
		try { $('#notifyResultBudgetSearch').trigger('focus'); } catch (e) {}
	}
	try { $('#modalNotifyResult').appendTo(document.body); } catch (eAppendNr) {}
	function closeNotifyBudgetPicker(){
		$('#notifyResultBudgetPickPanel').addClass('d-none');
	}
	function syncNotifyBudgetOther(){
		var code = String($('#notifyResultBudgetCode').val() || '');
		var $other = $('#notifyResultBudgetOther');
		if (code === '99') {
			$other.removeClass('d-none');
		} else {
			$other.addClass('d-none').val('');
		}
	}
	function syncNotifyResultNote(){
		var decision = String($('#notifyResultDecision').val() || '').trim();
		var $wrap = $('#notifyResultNoteWrap');
		var $note = $('#notifyResultNote');
		var $lbl = $('#notifyResultNoteLabel');
		var $budgetSrc = $('#notifyResultBudgetSrcWrap');
		var $budgetAmt = $('#notifyResultBudgetAmtWrap');
		if (decision === 'rejected') {
			$budgetSrc.addClass('d-none');
			$budgetAmt.addClass('d-none');
			closeNotifyBudgetPicker();
			$('#notifyResultLeaveWrap').addClass('d-none');
			$('#notifyResultShowLeave').prop('checked', false);
		} else {
			$budgetSrc.removeClass('d-none');
			$budgetAmt.removeClass('d-none');
			$('#notifyResultLeaveWrap').removeClass('d-none');
		}
		if (decision === 'included_edit' || decision === 'rejected') {
			$wrap.removeClass('d-none');
			if ($lbl.length) {
				$lbl.text(decision === 'rejected' ? 'รายละเอียด/เหตุผลที่ไม่ผ่านการพิจารณา (จำเป็น) :' : 'รายละเอียดที่ให้แก้ไข (จำเป็น) :');
			}
		} else {
			$wrap.addClass('d-none');
			$note.val('');
		}
	}
	function parseBudgetNumber(raw){
		var s = String(raw || '').replace(/,/g, '').trim();
		if (!s) return NaN;
		var n = Number(s);
		return Number.isFinite(n) ? n : NaN;
	}
	function formatBudgetInput(raw){
		var s = String(raw || '').replace(/,/g, '').trim();
		if (!s) return '';
		if (!/^\d*\.?\d*$/.test(s)) return '';
		var p = s.split('.');
		var intPart = (p[0] || '').replace(/^0+(?=\d)/, '');
		if (intPart === '') intPart = '0';
		var decPart = p.length > 1 ? p[1] : '';
		intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
		return decPart !== '' ? (intPart + '.' + decPart) : intPart;
	}

	$(document).on('click', '[data-action="open-notify-result"]', function(e){
		e.preventDefault();
		var $b = $(this);
		$('#notifyResultProjectId').val($b.attr('data-id') || '0');
		$('#notifyResultUnitName').text($b.attr('data-notify-name') || $b.attr('data-notify-unit') || '-');
		var code = String($b.attr('data-notify-budget-code') || '').trim();
		var label = String($b.attr('data-notify-budget-label') || '').trim();
		if (label === '-' || /^แหล่งงบรหัส\s*/.test(label) || /^รหัสแหล่งงบ\s*/.test(label)) {
			label = '';
		}
		renderNotifyBudgetSelected(code, label !== '' ? { name: label, code: code } : null);
		$('#notifyResultBudgetOther').val($b.attr('data-notify-budget-other') || '');
		var amtRaw = String($b.attr('data-notify-budget-total') || '');
		$('#notifyResultBudgetAmount').val(formatBudgetInput(amtRaw));
		$('#notifyResultDecision').val('');
		$('#notifyResultNote').val('');
		$('#notifyResultShowLeave').prop('checked', false);
		$('#notifyResultLeaveWrap').removeClass('d-none');
		$('#notifyResultBudgetSearch').val('');
		closeNotifyBudgetPicker();
		syncNotifyBudgetOther();
		syncNotifyResultNote();
		$('#modalNotifyResult').modal('show');
	});

	$(document).on('click', '#notifyResultBudgetPickBtn', function(e){
		e.preventDefault();
		openNotifyBudgetPicker();
	});
	$(document).on('click', '#notifyResultBudgetPickClose', function(e){
		e.preventDefault();
		closeNotifyBudgetPicker();
	});
	$(document).on('input', '#notifyResultBudgetSearch', function(){ renderNotifyBudgetPickList(true); });
	$(document).on('click', '#notifyResultBudgetPickBody tr[data-budget-id]', function(){
		var $tr = $(this);
		var id = String($tr.attr('data-budget-id') || '').trim();
		if (!id) return;
		var codeTxt = String($tr.find('.nr-budget-code').first().text() || '').trim();
		var nameTxt = String($tr.find('.nr-budget-pick-name').first().text() || '').trim();
		var amtTxt = String($tr.find('.nr-budget-pick-money').first().text() || '').replace(/,/g, '').trim();
		var amtNum = Number(amtTxt);
		renderNotifyBudgetSelected(id, {
			code: codeTxt || id,
			name: nameTxt,
			amount: Number.isFinite(amtNum) ? amtNum : 0
		});
		syncNotifyBudgetOther();
		closeNotifyBudgetPicker();
	});

	$(document).on('change', '#notifyResultDecision', syncNotifyResultNote);
	$(document).on('input', '#notifyResultBudgetAmount', function(){
		var cur = String($(this).val() || '');
		var fmt = formatBudgetInput(cur);
		if (fmt === '' && cur.trim() !== '') return;
		$(this).val(fmt);
	});

	$(document).on('click', '#notifyResultSubmitBtn', function(){
		var projectId = parseInt($('#notifyResultProjectId').val() || '0', 10);
		var budgetCode = String($('#notifyResultBudgetCode').val() || '').trim();
		var budgetOther = String($('#notifyResultBudgetOther').val() || '').trim();
		var budgetAmountRaw = String($('#notifyResultBudgetAmount').val() || '').trim();
		var decision = String($('#notifyResultDecision').val() || '').trim();
		var note = String($('#notifyResultNote').val() || '').trim();
		var budgetAmountNum = parseBudgetNumber(budgetAmountRaw);
		if (!projectId) return;
		if (!decision) {
			Swal.fire({icon:'warning', title:'กรุณาเลือกผลการพิจารณา'});
			return;
		}
		if (decision !== 'rejected') {
			if (!budgetCode) {
				Swal.fire({icon:'warning', title:'กรุณาเลือกแหล่งงบประมาณ'});
				return;
			}
			if (budgetCode === '99' && !budgetOther) {
				Swal.fire({icon:'warning', title:'กรุณาระบุแหล่งงบประมาณอื่น ๆ'});
				return;
			}
			if (budgetAmountRaw === '' || Number.isNaN(budgetAmountNum) || budgetAmountNum < 0) {
				Swal.fire({icon:'warning', title:'กรุณากรอกวงเงินอนุมัติให้ถูกต้อง'});
				return;
			}
		} else {
			budgetCode = '';
			budgetOther = '';
			budgetAmountNum = 0;
		}
		if ((decision === 'included_edit' || decision === 'rejected') && !note) {
			Swal.fire({icon:'warning', title:(decision === 'rejected' ? 'กรุณาระบุเหตุผลที่ไม่ผ่านการพิจารณา' : 'กรุณาระบุรายละเอียดที่ให้แก้ไข')});
			return;
		}
		var $btn = $(this).prop('disabled', true);
		$.ajax({
			url: '?page=project_manage',
			type: 'POST',
			dataType: 'text',
			data: {
				op: 'notify_plan_result_ajax',
				project_id: projectId,
				budget_code: budgetCode,
				budget_other: budgetOther,
				approved_budget: budgetAmountNum,
				notify_result: decision,
				notify_note: note,
				show_on_leave_system: ($('#notifyResultShowLeave').is(':checked') && decision !== 'rejected') ? 1 : 0
			}
		}).done(function(raw){
			var res = null;
			try { res = JSON.parse(String(raw || '')); } catch (e) { res = null; }
			if (res && Number(res.ok) === 1) {
				try { $('#modalNotifyResult').modal('hide'); } catch(e){}
				Swal.fire({icon:'success', title:'แจ้งผลเรียบร้อย', timer:1000, showConfirmButton:false})
					.then(function(){ window.location.reload(); });
			} else {
				var msg = (res && res.msg) ? String(res.msg) : '';
				if (!msg) {
					msg = String(raw || '').trim();
					if (msg.length > 300) msg = msg.slice(0, 300) + '...';
				}
				Swal.fire({icon:'error', title:'ไม่สำเร็จ', text: msg || 'แจ้งผลไม่สำเร็จ'});
			}
		}).fail(function(xhr){
			var msg = '';
			try { msg = String(xhr && xhr.responseText ? xhr.responseText : '').trim(); } catch (e) {}
			if (msg.length > 300) msg = msg.slice(0, 300) + '...';
			Swal.fire({icon:'error', title:'ไม่สำเร็จ', text: msg || 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้'});
		}).always(function(){
			$btn.prop('disabled', false);
		});
	});
})(jQuery);
</script>
<?php if ($is_unit_admin): ?>
<div class="modal fade" id="modalRequestIncludeProject" tabindex="-1" role="dialog" aria-hidden="true" data-backdrop="static">
	<div class="modal-dialog" role="document" style="max-width: 82%;">
