<script>
(function(){
	var $table = $('#projectManageTable');
	if (!$table.length) return;
	var perPage = 20;
	var currentPage = 1;
	var $rows = $table.find('tbody tr[data-project-row="1"]');
	var $search = $('#projectListSearch');
	var $pager = $('#projectListPager');
	var $summary = $('#projectListSummary');
	var $btnInclude = $('#btnRequestIncludeProject');
	var $modalInclude = $('#modalRequestIncludeProject');
	var $modalIncludeSelectAll = $('#modalIncludeSelectAll');
	var $modalIncludeRows = $('.pm-include-modal-row');
	var $btnConfirmInclude = $('#btnConfirmIncludeProject');
	var $modalIncludeFinalize = $('#modalRequestIncludeFinalize');
	var $includeIdsHidden = $('#includeSelectedIdsHidden');
	var $includeCountText = $('#includeSelectedCountText');
	var $btnSubmitIncludeRequest = $('#btnSubmitIncludeRequest');
	var includeSelectedIds = [];
	var includeSelectedMeta = [];
	var includeCertStaffOptions = <?= json_encode($include_finalize_staff_options, JSON_UNESCAPED_UNICODE) ?>;
	var includeBudgetYear = <?= json_encode((string)$years_select, JSON_UNESCAPED_UNICODE) ?>;
	var includeResubmitFromRequestId = <?= (int)(!empty($include_resubmit_certifiers_locked) ? $include_request_id : 0) ?>;
	var includeLockedCertifiers = <?= json_encode($include_resubmit_certifiers_for_js, JSON_UNESCAPED_UNICODE) ?>;
	window.includeCertifiersUiLocked = false;
	var urlObj = new URL(window.location.href);
	var sortKey = String(urlObj.searchParams.get('s') || '');
	var sortDir = String(urlObj.searchParams.get('d') || 'asc');
	var qInit = String(urlObj.searchParams.get('q') || '').trim();
	var pInit = parseInt(urlObj.searchParams.get('p') || '1', 10);
	if (!isNaN(pInit) && pInit > 0) currentPage = pInit;
	if (qInit !== '') $search.val(qInit);

	function syncUrlState(){
		var u = new URL(window.location.href);
		var q = String($search.val() || '').trim();
		if (q) u.searchParams.set('q', q);
		else u.searchParams.delete('q');
		u.searchParams.set('p', String(currentPage));
		if (sortKey) {
			u.searchParams.set('s', sortKey);
			u.searchParams.set('d', sortDir);
		} else {
			u.searchParams.delete('s');
			u.searchParams.delete('d');
		}
		window.history.replaceState({}, '', u.toString());
	}

	function getFilteredRows(){
		var q = String($search.val() || '').toLowerCase().trim();
		if (!q) return $rows;
		return $rows.filter(function(){
			return String($(this).attr('data-search') || '').indexOf(q) !== -1;
		});
	}

	function getSortValue($tr){
		var key = sortKey || '';
		if (!key) return '';
		if (key === 'budget') {
			var raw = String($tr.attr('data-budget') || '0');
			raw = raw.replace(/,/g, '');
			return parseFloat(raw) || 0;
		}
		if (key === 'status') return parseInt($tr.attr('data-status') || '0', 10) || 0;
		if (key === 'code') return String($tr.attr('data-code') || '').toLowerCase();
		if (key === 'name') return String($tr.attr('data-name') || '').toLowerCase();
		if (key === 'unit') return String($tr.attr('data-unit') || '').toLowerCase();
		return '';
	}

	function sortRows($filtered){
		var arr = $filtered.toArray();
		if (!sortKey) return arr;
		arr.sort(function(a, b){
			var $a = $(a), $b = $(b);
			var va = getSortValue($a), vb = getSortValue($b);
			if (va < vb) return sortDir === 'asc' ? -1 : 1;
			if (va > vb) return sortDir === 'asc' ? 1 : -1;
			return 0;
		});
		return arr;
	}

	function updateSortButtons(){
		$table.find('.pm-sort-btn').removeClass('active');
		if (!sortKey) return;
		var $btn = $table.find('.pm-sort-btn[data-sort-key="' + sortKey + '"][data-sort-dir="' + sortDir + '"]');
		if (!$btn.length) return;
		$btn.addClass('active');
	}

	function renderPager(totalPages){
		$pager.empty();
		if (totalPages <= 1) return;
		var addBtn = function(label, page, disabled, active){
			var cls = 'btn btn-sm btn-outline-secondary';
			if (active) cls += ' active';
			var dis = disabled ? ' disabled' : '';
			$pager.append('<button type="button" class="'+cls+dis+'" data-page="'+page+'">'+label+'</button>');
		};
		addBtn('&laquo;', currentPage - 1, currentPage <= 1, false);
		for (var p = 1; p <= totalPages; p++) addBtn(String(p), p, false, p === currentPage);
		addBtn('&raquo;', currentPage + 1, currentPage >= totalPages, false);
	}

	function renderTable(){
		var filtered = getFilteredRows();
		var sorted = sortRows(filtered);
		var total = sorted.length;
		var totalPages = Math.max(1, Math.ceil(total / perPage));
		if (currentPage > totalPages) currentPage = totalPages;
		if (currentPage < 1) currentPage = 1;
		var start = (currentPage - 1) * perPage;
		var end = start + perPage;
		var $tbody = $table.find('tbody');

		// จัดลำดับแถวใน DOM ให้ตรงกับผลการเรียง (hide/show อย่างเดียวไม่เปลี่ยนลำดับบนจอ)
		for (var si = 0; si < sorted.length; si++) {
			$tbody.append(sorted[si]);
		}

		$rows.hide();
		$(sorted.slice(start, end)).show().each(function(i){
			$(this).find('td.pm-col-no').text(start + i + 1);
		});

		$('#project-empty-row').remove();
		if (total === 0) {
			$table.find('tbody').append('<tr id="project-empty-row"><td colspan="7" class="text-center text-secondary py-4">ไม่พบโครงการ</td></tr>');
		}
		$summary.text('ทั้งหมด ' + total + ' โครงการ | หน้า ' + currentPage + '/' + totalPages + ' | แสดงครั้งละ ' + perPage + ' โครงการ');
		renderPager(totalPages);
		updateSortButtons();
		syncUrlState();
	}

	$search.on('input', function(){ currentPage = 1; renderTable(); });
	$pager.on('click', 'button[data-page]', function(){
		var p = parseInt($(this).attr('data-page') || '1', 10);
		if (isNaN(p) || $(this).is(':disabled')) return;
		currentPage = p < 1 ? 1 : p;
		renderTable();
	});
	$table.on('click', '.pm-sort-btn', function(){
		var k = String($(this).attr('data-sort-key') || '');
		var d = String($(this).attr('data-sort-dir') || '');
		if (!k) return;
		sortKey = k;
		sortDir = (d === 'desc') ? 'desc' : 'asc';
		currentPage = 1;
		renderTable();
	});
	if ($btnInclude.length) {
		$btnInclude.on('click', function(e){
			e.preventDefault();
			if (!$modalInclude.length) return;
			try {
				$modalInclude.modal('show');
			} catch (errShow) {
				try {
					var el = document.getElementById('modalRequestIncludeProject');
					if (window.bootstrap && bootstrap.Modal && el) {
						bootstrap.Modal.getOrCreateInstance(el).show();
					}
				} catch (errBs) {}
			}
			setTimeout(function(){
				var el2 = document.getElementById('modalRequestIncludeProject');
				if (el2 && !el2.classList.contains('show')) {
					el2.classList.add('show');
					el2.style.display = 'block';
					el2.style.zIndex = '1060';
					el2.removeAttribute('aria-hidden');
					document.body.classList.add('modal-open');
					if (!document.querySelector('.modal-backdrop')) {
						var bd = document.createElement('div');
						bd.className = 'modal-backdrop fade show';
						bd.style.zIndex = '1055';
						document.body.appendChild(bd);
					}
				}
			}, 180);
		});
	}
	function updateModalIncludeControls(){
		if (!$btnConfirmInclude.length) return;
		var checkedCount = $modalIncludeRows.filter(':checked').length;
		$btnConfirmInclude.prop('disabled', checkedCount <= 0);
		if ($modalIncludeSelectAll.length) {
			var allChecked = ($modalIncludeRows.length > 0 && checkedCount === $modalIncludeRows.length);
			$modalIncludeSelectAll.prop('checked', allChecked);
			$modalIncludeSelectAll.prop('indeterminate', !allChecked && checkedCount > 0);
		}
	}
	if ($modalInclude.length && includeResubmitFromRequestId > 0) {
		$modalInclude.on('shown.bs.modal', function(){
			$modalIncludeRows.prop('checked', true);
			updateModalIncludeControls();
		});
	}
	function forceHideModalById(id){
		var el = document.getElementById(id);
		if (!el) return;
		try { $('#' + id).modal('hide'); } catch(e) {}
		try {
			if (window.bootstrap && window.bootstrap.Modal) {
				var bm = window.bootstrap.Modal.getInstance(el);
				if (bm) bm.hide();
			}
		} catch(eb) {}
		try {
			el.classList.remove('show');
			el.style.display = 'none';
			el.style.removeProperty('z-index');
			el.setAttribute('aria-hidden', 'true');
		} catch(e2){}
		try {
			if (!document.querySelector('.modal.show, .modal.in')) {
				document.body.classList.remove('modal-open');
				document.body.style.removeProperty('padding-right');
				var backs = document.querySelectorAll('.modal-backdrop');
				backs.forEach(function(b){ try { b.parentNode && b.parentNode.removeChild(b); } catch(_e){} });
			}
		} catch(e3){}
	}
	/* ปิด modal ขอบรรจุ: หน้าโหลด Bootstrap 4+5 ปนกัน + มี fallback เปิดแบบ manual จึง bind ปิดชัดเจน */
	$(document).on('click', '#modalRequestIncludeProject .close, #modalRequestIncludeProject [data-dismiss="modal"], #modalRequestIncludeProject [data-bs-dismiss="modal"]', function(e){
		e.preventDefault();
		e.stopPropagation();
		forceHideModalById('modalRequestIncludeProject');
	});
	if ($modalIncludeFinalize.length) {
		$modalIncludeFinalize.on('click', 'button[data-dismiss="modal"], button[data-bs-dismiss="modal"], .close', function(e){
			var $btn = $(this);
			if ($btn.is('#btnSubmitIncludeRequest')) return;
			e.preventDefault();
			e.stopPropagation();
			forceHideModalById('modalRequestIncludeFinalize');
		});
	}
	updateModalIncludeControls();
	function escapeIncludeHtml(s){
		return String(s)
			.replace(/&/g, '&amp;')
			.replace(/</g, '&lt;')
			.replace(/"/g, '&quot;')
			.replace(/'/g, '&#39;');
	}
	function renderFinalizeSummary(){
		var $body = $('#includeSummaryBodyV2').length ? $('#includeSummaryBodyV2') : $('#includeSummaryBody');
		var $cnt = $('#includeSummaryCount');
		var $sum = $('#includeSummaryBudget');
		if (!$body.length) return;
		if (!includeSelectedMeta.length) {
			$body.html('<tr><td colspan="' + ($('#includeSummaryBodyV2').length ? 5 : 3) + '" class="text-center text-muted">ไม่พบรายการที่เลือก</td></tr>');
			if ($cnt.length) $cnt.text('0');
			if ($sum.length) $sum.text('0');
			return;
		}
		var buckets = {};
		var total = 0;
		includeSelectedMeta.forEach(function(it){
			var b = Number(it.budget || 0);
			total += b;
			var kind = String(it.consistencyKind || '');
			var key = String(it.consistencyKey || '');
			var label = String(it.consistencyLabel || 'ยังไม่ระบุความสอดคล้อง');
			if (!key) {
				kind = '';
				key = 'unassigned';
			}
			var bid = kind + '\0' + key;
			if (!buckets[bid]) {
				buckets[bid] = { kind: kind, key: key, label: label, count: 0, sum: 0 };
			}
			buckets[bid].count += 1;
			buckets[bid].sum += b;
		});
		var strategic = [];
		var mission = [];
		var other = [];
		Object.keys(buckets).forEach(function(bid){
			var o = buckets[bid];
			if (o.kind === 'strategic') strategic.push(o);
			else if (o.kind === 'mission') mission.push(o);
			else other.push(o);
		});
		function sortByLabel(a, b){
			return String(a.label).localeCompare(String(b.label), 'th');
		}
		strategic.sort(sortByLabel);
		mission.sort(sortByLabel);
		other.sort(sortByLabel);
		var isV2 = $('#includeSummaryBodyV2').length > 0;
		var html = '';
		function buildProjectsHtml(o){
			var items = (o.items || []);
			if (!items.length) return '-';
			var out = '<ol class="mb-0 pl-3">';
			items.forEach(function(p){
				var pid = String(p.id || '');
				var name = escapeIncludeHtml(String(p.name || '-'));
				if (/^\d+$/.test(pid)) {
					out += '<li><a href="?page=project_manage&op=add_project&project_id=' + encodeURIComponent(pid) + '&years_select=' + encodeURIComponent(String(includeBudgetYear||'')) + '" target="_blank" rel="noopener">' + name + '</a></li>';
				} else {
					out += '<li>' + name + '</li>';
				}
			});
			out += '</ol>';
			return out;
		}
		function buildKpiHtml(o){
			var items = (o.items || []);
			var uniq = {};
			items.forEach(function(p){
				var list = Array.isArray(p.kpiLabels) ? p.kpiLabels : [];
				list.forEach(function(t){
					t = String(t || '').trim();
					if (t) uniq[t] = true;
				});
			});
			var keys = Object.keys(uniq);
			if (!keys.length) return '-';
			keys.sort(function(a,b){ return a.localeCompare(b,'th'); });
			var out = '<ol class="mb-0 pl-3">';
			keys.forEach(function(t){ out += '<li>' + escapeIncludeHtml(t) + '</li>'; });
			out += '</ol>';
			return out;
		}
		function appendSection(title, rows){
			if (!rows.length) return;
			if (!isV2) {
				html += '<tr class="pm-inc-sec-head"><td colspan="3"><strong>' + escapeIncludeHtml(title) + '</strong></td></tr>';
			} else {
				html += '<tr class="pm-inc-sec-head"><td colspan="5"><strong>' + escapeIncludeHtml(title) + '</strong></td></tr>';
			}
			rows.forEach(function(o){
				if (!isV2) {
					html += '<tr class="pm-inc-data">'
						+ '<td>' + escapeIncludeHtml(o.label) + '</td>'
						+ '<td class="text-center">' + escapeIncludeHtml(String(o.count)) + '</td>'
						+ '<td class="text-right">' + o.sum.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 }) + '</td>'
						+ '</tr>';
					return;
				}
				html += '<tr class="pm-inc-data">'
					+ '<td>' + escapeIncludeHtml(o.label) + '</td>'
					+ '<td class="text-center">' + escapeIncludeHtml(String(o.count)) + '</td>'
					+ '<td class="text-right">' + o.sum.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 }) + '</td>'
					+ '<td>' + buildProjectsHtml(o) + '</td>'
					+ '<td>' + buildKpiHtml(o) + '</td>'
					+ '</tr>';
			});
		}
		// เติมรายการโครงการย่อยในแต่ละ bucket
		Object.keys(buckets).forEach(function(bid){
			if (!buckets[bid].items) buckets[bid].items = [];
		});
		includeSelectedMeta.forEach(function(it){
			var kind = String(it.consistencyKind || '');
			var key = String(it.consistencyKey || '');
			if (!key) { kind = ''; key = 'unassigned'; }
			var bid = kind + '\0' + key;
			if (!buckets[bid]) return;
			buckets[bid].items.push({
				id: it.id,
				name: it.name,
				kpiLabels: Array.isArray(it.kpiLabels) ? it.kpiLabels : []
			});
		});
		appendSection('เชิงยุทธศาสตร์', strategic);
		appendSection('เชิงพันธกิจ', mission);
		appendSection('ยังไม่ระบุ / อื่น ๆ', other);
		if (!html) {
			html = '<tr><td colspan="' + (isV2 ? 5 : 3) + '" class="text-center text-muted">ไม่พบข้อมูลจัดกลุ่ม</td></tr>';
		}
		$body.html(html);
		if ($cnt.length) $cnt.text(String(includeSelectedMeta.length));
		if ($sum.length) $sum.text(total.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 }));
	}
	function buildIncludeSummaryRowsForSave(){
		var rows = [];
		if (!includeSelectedMeta.length) {
			return rows;
		}
		var buckets = {};
		var total = 0;
		includeSelectedMeta.forEach(function(it){
			var b = Number(it.budget || 0);
			total += b;
			var kind = String(it.consistencyKind || '');
			var key = String(it.consistencyKey || '');
			var label = String(it.consistencyLabel || 'ยังไม่ระบุความสอดคล้อง');
			if (!key) {
				kind = '';
				key = 'unassigned';
			}
			var bid = kind + '\0' + key;
			if (!buckets[bid]) {
				buckets[bid] = { kind: kind, key: key, label: label, count: 0, sum: 0 };
			}
			buckets[bid].count += 1;
			buckets[bid].sum += b;
		});
		var strategic = [];
		var mission = [];
		var other = [];
		Object.keys(buckets).forEach(function(bid){
			var o = buckets[bid];
			if (o.kind === 'strategic') {
				strategic.push(o);
			} else if (o.kind === 'mission') {
				mission.push(o);
			} else {
				other.push(o);
			}
		});
		function sortByLabel(a, b){
			return String(a.label).localeCompare(String(b.label), 'th');
		}
		strategic.sort(sortByLabel);
		mission.sort(sortByLabel);
		other.sort(sortByLabel);
		var sort = 0;
		function appendSection(title, sg, list){
			if (!list.length) {
				return;
			}
			rows.push({
				row_kind: 'header',
				section_group: sg,
				consistency_label: title,
				project_count: null,
				budget_baht: null,
				sort_order: sort++
			});
			list.forEach(function(o){
				rows.push({
					row_kind: 'data',
					section_group: sg,
					consistency_label: o.label,
					project_count: o.count,
					budget_baht: o.sum,
					sort_order: sort++
				});
			});
		}
		appendSection('เชิงยุทธศาสตร์', 'strategic', strategic);
		appendSection('เชิงพันธกิจ', 'mission', mission);
		appendSection('ยังไม่ระบุ / อื่น ๆ', 'other', other);
		rows.push({
			row_kind: 'total',
			section_group: null,
			consistency_label: 'รวม',
			project_count: includeSelectedMeta.length,
			budget_baht: total,
			sort_order: sort++
		});
		return rows;
	}
	function renderFinalizeLetterText(){
		var yearText = '<?= htmlspecialchars((string)$years_select, ENT_QUOTES, 'UTF-8') ?>';
		var names = [];
		includeSelectedMeta.forEach(function(it){
			// ต้องยึด "หน่วยงาน" จากตารางเลือกโครงการเป็นหลัก (ให้ตรงกับรายการที่ผู้ใช้เห็น)
			var un = String(it.unit || '').trim();
			if (!un || un === '-') {
				un = '';
			}
			if (un && names.indexOf(un) === -1) names.push(un);
		});
		var unitNameText = names.length ? names.join(', ') : '........................';
		var sectionText = unitNameText;
		if (sectionText !== '........................') {
			sectionText = String(sectionText).replace(/^\s*เรียน\s+/u, '').trim();
			sectionText = sectionText.replace(/\s*\(job_code:\s*[^)]+\)/gi, '').trim();
		}
		var subjectText = 'ขอพิจารณาแผนงานประจำปีงบประมาณ พ.ศ. ' + yearText + ' (' + unitNameText + ')';
		var letterText = 'เรียน  คณบดีคณะเภสัชศาสตร์\n'
			+ '      ด้วย  ' + unitNameText + ' มีความประสงค์ขอเสนอบรรจุโครงการ ไว้ในแผนปฏิบัติการคณะเภสัชศาสตร์\n'
			+ 'ประจำปีงบประมาณ พ.ศ.' + yearText + ' โดยมีรายละเอียด ดังนี้';
		$('#includeSectionNameText').val(sectionText);
		$('#includeSubjectText').val(subjectText);
		$('#includeLetterBodyText').text(letterText);
	}
	function includeCertEsc(s){
		return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
	}
	function includeCertPositionForStaffId(sid){
		sid = String(sid || '').trim();
		if (!sid) return '';
		var list = includeCertStaffOptions || [];
		for (var i = 0; i < list.length; i++) {
			if (String(list[i].id) === sid) return String(list[i].position || '');
		}
		return '';
	}
	function includeCertCloseCombos(except){
		$('#includeCertifiersRows .pm-include-cert-combo-list').each(function(){
			if (except && this === except) return;
			$(this).removeClass('is-open').empty();
		});
	}
	function includeCertRenderCombo($combo, q){
		var $list = $combo.find('.pm-include-cert-combo-list');
		var needle = String(q || '').trim().toLowerCase();
		var html = '';
		var shown = 0;
		(includeCertStaffOptions || []).forEach(function(o){
			if (shown >= 40) return;
			var id = String(o.id || '');
			var text = String(o.text || '');
			var pos = String(o.position || '');
			if (!id) return;
			if (needle && (text + ' ' + id + ' ' + pos).toLowerCase().indexOf(needle) === -1) return;
			html += '<button type="button" class="pm-include-cert-combo-item" data-id="'+includeCertEsc(id)+'" data-text="'+includeCertEsc(text)+'" data-position="'+includeCertEsc(pos)+'">'+includeCertEsc(text)+(pos ? ' <span class="text-muted">('+includeCertEsc(pos)+')</span>' : '')+'</button>';
			shown++;
		});
		if (!html) {
			html = '<div class="pm-include-cert-combo-empty">'+(needle ? 'ไม่พบรายชื่อ' : 'พิมพ์ชื่อเพื่อค้นหา')+'</div>';
		}
		$list.html(html).addClass('is-open');
	}
	function fillIncludeCertPosition($row, sid, posHint){
		var $pos = $row.find('input.pm-include-cert-position');
		$pos.prop({ readonly: false, disabled: false }).removeAttr('readonly').removeAttr('disabled');
		var pos = String(posHint || '').trim();
		if (!pos) pos = includeCertPositionForStaffId(sid);
		$pos.val(pos);
	}
	function renumberIncludeCertRows(){
		var $wrap = $('#includeCertifiersRows');
		if (!$wrap.length) return;
		$wrap.find('.pm-include-cert-row').each(function(i){
			$(this).find('.pm-include-cert-idx').text('(' + (i + 1) + ')');
		});
	}
	function syncIncludeCertRemoveVisibility(){
		var $wrap = $('#includeCertifiersRows');
		if (!$wrap.length) return;
		var n = $wrap.find('.pm-include-cert-row').length;
		$wrap.find('.pm-include-cert-remove').css('visibility', n > 1 ? 'visible' : 'hidden');
	}
	function syncIncludeCertLockUi(locked){
		window.includeCertifiersUiLocked = !!locked;
		var $add = $('#btnIncludeCertAdd');
		var $box = $('#modalRequestIncludeFinalize .pm-include-certifiers-box');
		if (locked) {
			$add.addClass('d-none').hide();
			$box.addClass('pm-include-cert-readonly');
		} else {
			$add.removeClass('d-none').show();
			$box.removeClass('pm-include-cert-readonly');
		}
	}
