		var n = $wrap.find('.pm-include-cert-row').length + 1;
		var remBtn = '<button type="button" class="btn btn-sm btn-link text-danger pm-include-cert-remove" title="ลบแถว"><i class="fa fa-times"></i></button>';
		var $row = $(
			'<div class="pm-include-cert-row">'
				+ '<div class="pm-include-cert-side">'
				+ remBtn
				+ '<span class="pm-include-cert-idx">(' + n + ')</span>'
				+ '</div>'
				+ '<div class="pm-include-cert-fields">'
				+ '<div class="row mx-0">'
				+ '<div class="col-md-6 col-12 mb-2 mb-md-0 pr-md-2 pm-include-cert-col">'
				+ '<label class="d-block pm-include-cert-lbl">ผู้รับรองโครงการ <span class="text-danger">*</span></label>'
				+ '<div class="pm-include-cert-combo">'
				+ '<input type="text" class="form-control pm-include-cert-combo-input" placeholder="- พิมพ์เพื่อค้นหา -" autocomplete="off">'
				+ '<input type="hidden" class="pm-include-cert-id" value="">'
				+ '<div class="pm-include-cert-combo-list"></div>'
				+ '</div>'
				+ '<small class="text-muted pm-include-cert-sub">พิมพ์ค้นหาได้</small>'
				+ '</div>'
				+ '<div class="col-md-6 col-12 pl-md-2 pm-include-cert-col">'
				+ '<label class="d-block pm-include-cert-lbl">ตำแหน่ง <span class="text-danger">*</span></label>'
				+ '<input type="text" class="form-control pm-include-cert-position" placeholder="ตำแหน่ง* (ดึงมาแต่ให้แก้ไขได้)" autocomplete="off">'
				+ '<small class="pm-include-cert-sub pm-include-cert-sub-spacer invisible text-muted" aria-hidden="true">พิมพ์ค้นหาได้</small>'
				+ '</div>'
				+ '</div>'
				+ '</div>'
				+ '</div>'
		);
		$wrap.append($row);
		renumberIncludeCertRows();
		syncIncludeCertRemoveVisibility();
