	function resetIncludeCertifiers(){
		var $wrap = $('#includeCertifiersRows');
		if (!$wrap.length) return;
		$wrap.empty();
		if (includeResubmitFromRequestId > 0 && includeLockedCertifiers && includeLockedCertifiers.length) {
			renderIncludeCertifiersLocked();
		} else {
			syncIncludeCertLockUi(false);
			addIncludeCertRow();
			syncIncludeCertRemoveVisibility();
		}
	}
	function collectIncludeCertifiersPayload(){
		if (window.includeCertifiersUiLocked && includeLockedCertifiers && includeLockedCertifiers.length) {
			var out = [];
			var i;
			for (i = 0; i < includeLockedCertifiers.length; i++) {
				var r = includeLockedCertifiers[i];
				out.push({
					staff_id: parseInt(r.staff_id, 10) || 0,
					position: String(r.position || '')
				});
			}
			return { ok: true, err: '', rows: out };
		}
		var $wrap = $('#includeCertifiersRows');
		var out = [];
		var err = '';
		if (!$wrap.length) {
			return { ok: false, err: 'ไม่พบแบบฟอร์มผู้รับรอง', rows: [] };
		}
		$wrap.find('.pm-include-cert-row').each(function(){
			var $r = $(this);
			var sid = String($r.find('.pm-include-cert-id').val() || '').trim();
			var pos = String($r.find('input.pm-include-cert-position').val() || '').trim();
			if (sid === '' && pos === '') {
				return;
			}
			if (sid === '' || pos === '') {
				err = 'กรุณากรอกผู้รับรองและตำแหน่งให้ครบทุกลำดับที่ระบุ';
				return false;
			}
			out.push({ staff_id: parseInt(sid, 10), position: pos });
		});
		return { ok: err === '', err: err, rows: out };
	}
	$(document).on('click', '#btnIncludeCertAdd', function(){
		if (window.includeCertifiersUiLocked) return;
		addIncludeCertRow();
	});
	$(document).on('click', '.pm-include-cert-remove', function(){
		if (window.includeCertifiersUiLocked) return;
		var $wrap = $('#includeCertifiersRows');
		if ($wrap.find('.pm-include-cert-row').length <= 1) return;
		$(this).closest('.pm-include-cert-row').remove();
		renumberIncludeCertRows();
		syncIncludeCertRemoveVisibility();
	});
	$(document).on('focus input', '#includeCertifiersRows .pm-include-cert-combo-input', function(){
		if (window.includeCertifiersUiLocked) return;
		var $input = $(this);
		var $combo = $input.closest('.pm-include-cert-combo');
		includeCertCloseCombos($combo.find('.pm-include-cert-combo-list').get(0));
		includeCertRenderCombo($combo, $input.val());
	});
	$(document).on('keydown', '#includeCertifiersRows .pm-include-cert-combo-input', function(e){
		var $combo = $(this).closest('.pm-include-cert-combo');
		var $list = $combo.find('.pm-include-cert-combo-list');
		var $items = $list.find('.pm-include-cert-combo-item');
		if (!$items.length) return;
		var $cur = $items.filter('.is-active');
		var idx = $items.index($cur);
		if (e.key === 'ArrowDown') {
			e.preventDefault();
			idx = Math.min($items.length - 1, idx + 1);
			$items.removeClass('is-active').eq(idx).addClass('is-active');
		} else if (e.key === 'ArrowUp') {
			e.preventDefault();
			idx = Math.max(0, idx <= 0 ? 0 : idx - 1);
			$items.removeClass('is-active').eq(idx).addClass('is-active');
		} else if (e.key === 'Enter') {
			e.preventDefault();
			($cur.length ? $cur : $items.first()).trigger('mousedown');
		} else if (e.key === 'Escape') {
			includeCertCloseCombos();
		}
	});
	$(document).on('mousedown', '#includeCertifiersRows .pm-include-cert-combo-item', function(e){
		e.preventDefault();
		var $item = $(this);
		var $combo = $item.closest('.pm-include-cert-combo');
		var $row = $item.closest('.pm-include-cert-row');
		var id = String($item.attr('data-id') || '');
		var text = String($item.attr('data-text') || $item.text() || '');
		var pos = String($item.attr('data-position') || '');
		$combo.find('.pm-include-cert-id').val(id);
		$combo.find('.pm-include-cert-combo-input').val(text).data('picked-text', text);
		fillIncludeCertPosition($row, id, pos);
		includeCertCloseCombos();
	});
	$(document).on('blur', '#includeCertifiersRows .pm-include-cert-combo-input', function(){
		var $input = $(this);
		setTimeout(function(){
			var $combo = $input.closest('.pm-include-cert-combo');
			$combo.find('.pm-include-cert-combo-list').removeClass('is-open').empty();
			if (!$combo.find('.pm-include-cert-id').val()) {
				$input.val('');
				$input.closest('.pm-include-cert-row').find('input.pm-include-cert-position').val('');
			}
		}, 150);
	});
	$(document).on('click', function(e){
		if ($(e.target).closest('.pm-include-cert-combo').length) return;
		includeCertCloseCombos();
	});
	if ($modalIncludeSelectAll.length) {
		$modalIncludeSelectAll.on('change', function(){
			var checked = $(this).is(':checked');
			$modalIncludeRows.prop('checked', checked);
			updateModalIncludeControls();
		});
	}
	$(document).on('change', '.pm-include-modal-row', function(){
		updateModalIncludeControls();
	});
	if ($btnConfirmInclude.length) {
		$btnConfirmInclude.on('click', function(){
			var ids = [];
			$modalIncludeRows.filter(':checked').each(function(){
				var v = String($(this).val() || '');
				if (/^\d+$/.test(v)) ids.push(v);
			});
			if (!ids.length) {
				Swal.fire({icon:'warning', title:'กรุณาเลือกโครงการ', text:'เลือกรายการที่ต้องการยื่นขอพิจารณาแผนก่อน'});
				return;
			}
			var openFinalize = function(){
				includeSelectedIds = ids.slice(0);
				includeSelectedMeta = [];
				$modalIncludeRows.filter(':checked').each(function(){
					var $tr = $(this).closest('tr');
					var code = $.trim($tr.find('td:eq(3)').text());
					var name = $.trim($tr.find('td:eq(4) .font-weight-bold').text() || $tr.find('td:eq(4)').text());
					var unit = $.trim($tr.find('td:eq(5)').text());
					var budgetText = $.trim($tr.find('td:eq(6)').text()).replace(/,/g,'');
					var budget = parseFloat(budgetText || '0') || 0;
					var jobCode = String($tr.attr('data-job-code') || '').trim();
					var jobName = String($tr.attr('data-job-name') || '').trim();
					var kpiLabels = [];
					try {
						kpiLabels = JSON.parse($tr.attr('data-project-kpis') || '[]');
						if (!Array.isArray(kpiLabels)) kpiLabels = [];
					} catch (eKpi) { kpiLabels = []; }
					var cKind = String($tr.attr('data-consistency-kind') || '').trim();
					var cKey = String($tr.attr('data-consistency-key') || '').trim();
					var cLabel = String($tr.attr('data-consistency-label') || '').trim();
					includeSelectedMeta.push({
						id: parseInt(String($(this).val() || '0'), 10) || 0,
						code: code, name: name, unit: unit, budget: budget, jobCode: jobCode, jobName: jobName,
						kpiLabels: kpiLabels,
						consistencyKind: cKind, consistencyKey: cKey, consistencyLabel: cLabel
					});
				});
				if ($includeIdsHidden.length) $includeIdsHidden.val(includeSelectedIds.join(','));
				if ($includeCountText.length) $includeCountText.text(String(includeSelectedIds.length));
				renderFinalizeSummary();
				renderFinalizeLetterText();
				resetIncludeCertifiers();
				var showFinalize = function(){
					try {
						$modalIncludeFinalize.modal('show');
					} catch(e) {
						try {
							var el2 = document.getElementById('modalRequestIncludeFinalize');
							if (window.bootstrap && bootstrap.Modal && el2) {
								var ins2 = bootstrap.Modal.getOrCreateInstance(el2);
								ins2.show();
							}
						} catch(e2){}
					}
					setTimeout(function(){
						var mf = document.getElementById('modalRequestIncludeFinalize');
						if (mf && !mf.classList.contains('show')) {
							mf.classList.add('show');
							mf.style.display = 'block';
							mf.removeAttribute('aria-hidden');
							document.body.classList.add('modal-open');
							if (!document.querySelector('.modal-backdrop')) {
								var bd = document.createElement('div');
								bd.className = 'modal-backdrop fade show';
								document.body.appendChild(bd);
							}
						}
					}, 180);
				};
				forceHideModalById('modalRequestIncludeProject');
				setTimeout(showFinalize, 40);
			};
			openFinalize();
		});
	}
	if ($btnSubmitIncludeRequest.length) {
		$btnSubmitIncludeRequest.on('click', function(){
			var idsCsv = String(($includeIdsHidden.val() || '')).trim();
			var ids = idsCsv ? idsCsv.split(',').filter(function(v){ return /^\d+$/.test(v); }) : [];
			if (!ids.length) {
				Swal.fire({icon:'warning', title:'ไม่พบรายการโครงการ', text:'กรุณาเลือกโครงการใหม่อีกครั้ง'});
				return;
			}
			var certPack = collectIncludeCertifiersPayload();
			if (!certPack.ok) {
				Swal.fire({ icon:'warning', title:'ข้อมูลผู้รับรองไม่ครบ', text: certPack.err });
				return;
			}
			if (!certPack.rows.length) {
				Swal.fire({
					icon:'warning',
					title:'ระบุผู้รับรองโครงการ',
					text:'กรุณาระบุอย่างน้อย 1 คน เรียงจากบนลงล่าง — ลำดับสุดท้ายเป็นผู้ลงนามก่อนส่งแผน'
				});
				return;
			}
			$.ajax({
				url: '?page=project_manage&op=request_include_projects_ajax',
				type: 'POST',
				dataType: 'json',
				data: {
					project_ids: ids.join(','),
					budget_year: String(includeBudgetYear || ''),
					section_name: String($('#includeSectionNameText').val() || ''),
					subject: String($('#includeSubjectText').val() || ''),
					letter_body: String($('#includeLetterBodyText').text() || ''),
					certifiers_json: JSON.stringify(certPack.rows),
					summary_rows_json: JSON.stringify(buildIncludeSummaryRowsForSave()),
					resubmit_from_request_id: String($('#includeResubmitFromRequestId').val() || '0')
				}
			}).done(function(res){
				if (res && Number(res.ok) === 1) {
					var n = Number(res.affected || 0);
					Swal.fire({
						icon:'success',
						title:'ดำเนินการสำเร็จ',
						text: n > 0 ? ('ยื่นขอพิจารณาแผนแล้ว ' + n + ' รายการ') : 'ไม่มีรายการที่เข้าเงื่อนไขให้ยื่นขอพิจารณาแผน'
					}).then(function(){ window.location.reload(); });
				} else {
					Swal.fire({icon:'error', title:'ไม่สำเร็จ', text:(res && res.msg) ? res.msg : 'ยื่นขอพิจารณาแผนไม่สำเร็จ'});
				}
			}).fail(function(){
				Swal.fire({icon:'error', title:'ไม่สำเร็จ', text:'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ได้'});
			});
		});
	}

	$(document).on('click', '[data-action="delete-project-draft"]', function(e){
		e.preventDefault();
		var id = parseInt($(this).attr('data-id') || '0', 10);
		if (!id) return;
		var $tr = $(this).closest('tr');
		var run = function(){
			$.ajax({
				url: '?page=project_manage&op=delete_draft_project_ajax',
				type: 'POST',
				dataType: 'json',
				data: { project_id: id }
			}).done(function(res){
				if (res && res.ok === 1) {
					$tr.remove();
					$rows = $table.find('tbody tr[data-project-row="1"]');
					renderTable();
					if (typeof Swal !== 'undefined') Swal.fire({ icon:'success', title:'ลบโครงการแล้ว', timer:900, showConfirmButton:false });
					return;
				}
				var msg = (res && res.msg) ? res.msg : 'ลบไม่สำเร็จ';
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'ลบไม่สำเร็จ', text: msg });
			}).fail(function(){
				if (typeof Swal !== 'undefined') Swal.fire({ icon:'error', title:'เกิดข้อผิดพลาด', text:'ลบไม่สำเร็จ' });
			});
		};
		if (typeof Swal !== 'undefined') {
			Swal.fire({ icon:'warning', title:'ยืนยันการลบโครงการร่าง?', showCancelButton:true, confirmButtonText:'ลบ', cancelButtonText:'ยกเลิก' })
				.then(function(r){ if (r.isConfirmed) run(); });
		} else if (confirm('ยืนยันการลบโครงการร่าง?')) {
			run();
		}
	});

	renderTable();
	updateModalIncludeControls();
})();
</script>
